/*Table structure for table `route_seq` */

DROP TABLE IF EXISTS `route_seq`;

CREATE TABLE `route_seq` (
  `primary_key` bigint NOT NULL DEFAULT '0',
  `rp32weeknumber` bigint NOT NULL,
  `routecode` bigint NOT NULL,
  `customercode` bigint NOT NULL,
  `callrestrictiondays1` int DEFAULT '0',
  `callrestrictiondays2` int DEFAULT '0',
  `callrestrictiondays3` int DEFAULT '0',
  `callrestrictiondays4` int DEFAULT '0',
  `callrestrictiondays5` int DEFAULT '0',
  `callrestrictiondays6` int DEFAULT '0',
  `callrestrictiondays7` int DEFAULT '0',
  `monseq` int DEFAULT '0',
  `tueseq` int DEFAULT '0',
  `wedseq` int DEFAULT '0',
  `thuseq` int DEFAULT '0',
  `friseq` int DEFAULT '0',
  `satseq` int DEFAULT '0',
  `sunseq` int DEFAULT '0',
  `mdat` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `referenceno` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT NULL,
  `oldcustcode` bigint DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Table structure for table `routebook` */

DROP TABLE IF EXISTS `routebook`;

CREATE TABLE `routebook` (
  `routecode` bigint DEFAULT NULL,
  `transactiondate` date DEFAULT NULL,
  `invoicenumber` bigint DEFAULT NULL,
  `customercode` bigint DEFAULT NULL,
  `itemcode` bigint DEFAULT NULL,
  `salesqty` int DEFAULT NULL,
  `returnqty` int DEFAULT NULL,
  `damageqty` int DEFAULT NULL,
  `freeqty` int DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

/*Table structure for table `routecategory` */

DROP TABLE IF EXISTS `routecategory`;

CREATE TABLE `routecategory` (
  `routecatcode` bigint NOT NULL AUTO_INCREMENT,
  `routecatname` varchar(50) DEFAULT NULL,
  `arbroutecatname` varchar(50) DEFAULT NULL,
  `created` varchar(30) DEFAULT NULL,
  `cdat` date DEFAULT NULL,
  `modified` varchar(30) DEFAULT NULL,
  `mdat` date DEFAULT NULL,
  PRIMARY KEY (`routecatcode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Table structure for table `routedetail` */

DROP TABLE IF EXISTS `routedetail`;

CREATE TABLE `routedetail` (
  `RouteCode` int DEFAULT NULL,
  `WAREHOUSE` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL,
  `Plant_Code` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci DEFAULT NULL
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

/*Table structure for table `routedeviation` */

DROP TABLE IF EXISTS `routedeviation`;

CREATE TABLE `routedeviation` (
  `companyname` varchar(30) DEFAULT NULL,
  `companyaddress` varchar(30) DEFAULT NULL,
  `routecode` decimal(18,0) DEFAULT NULL,
  `routename` varchar(30) DEFAULT NULL,
  `salesmancode` decimal(18,0) DEFAULT NULL,
  `salesmanname` varchar(50) DEFAULT NULL,
  `customercode` decimal(18,0) DEFAULT NULL,
  `customername` varchar(30) DEFAULT NULL,
  `deviationflag` decimal(18,0) DEFAULT NULL,
  `plannedsequence` decimal(18,0) DEFAULT NULL,
  `actualsequence` decimal(18,0) DEFAULT NULL,
  `scheduledflag` decimal(18,0) DEFAULT NULL,
  `weekday` decimal(18,0) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Table structure for table `routegoal` */

DROP TABLE IF EXISTS `routegoal`;

CREATE TABLE `routegoal` (
  `primary_key` bigint NOT NULL AUTO_INCREMENT,
  `routecode` bigint DEFAULT NULL,
  `salesmancode` bigint DEFAULT NULL,
  `packagenumber` bigint DEFAULT NULL,
  `fromdate` date NOT NULL,
  `todate` date NOT NULL,
  `quantity` decimal(18,3) NOT NULL,
  `achievequantity` decimal(18,3) NOT NULL,
  `achieveamount` decimal(18,3) DEFAULT NULL,
  `todaysgoal` decimal(18,3) DEFAULT NULL,
  `todaysachieve` decimal(18,3) DEFAULT '0.000',
  `created` varchar(50) DEFAULT NULL,
  `cdat` datetime DEFAULT NULL,
  `modified` varchar(50) DEFAULT NULL,
  `mdat` datetime DEFAULT NULL,
  `targettype` int DEFAULT NULL,
  `commision` decimal(18,3) DEFAULT NULL,
  `commisonpercent` decimal(18,3) DEFAULT NULL,
  `insentive` decimal(18,3) DEFAULT NULL,
  `insentivepercent` decimal(18,3) DEFAULT NULL,
  `goaltype` int DEFAULT NULL,
  `dailytarget` decimal(18,3) DEFAULT NULL,
  `progressivetarget` decimal(18,3) DEFAULT NULL,
  `asontarget` decimal(18,3) DEFAULT NULL,
  `mtdtarget` decimal(18,3) DEFAULT NULL,
  `dailyvalue` decimal(18,3) DEFAULT NULL,
  `progressivevalue` decimal(18,3) DEFAULT NULL,
  `asonvalue` decimal(18,3) DEFAULT NULL,
  `mtdvalue` decimal(18,3) DEFAULT NULL,
  PRIMARY KEY (`primary_key`),
  UNIQUE KEY `UNIQ_cols` (`routecode`,`salesmancode`,`packagenumber`,`fromdate`,`todate`,`targettype`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=latin1;

/*Table structure for table `routeinfo_plant` */

DROP TABLE IF EXISTS `routeinfo_plant`;

CREATE TABLE `routeinfo_plant` (
