  `formname` varchar(100) DEFAULT NULL,
  `tablename` varchar(100) DEFAULT NULL,
  `groupcode` bigint DEFAULT NULL,
  `itemcode` bigint DEFAULT NULL,
  `created` varchar(30) DEFAULT NULL,
  `cdat` datetime DEFAULT NULL,
