  `itemcode` bigint NOT NULL,
  `transferstatus` int DEFAULT '0',
  PRIMARY KEY (`routeitemgrpcode`,`itemcode`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;

/*Table structure for table `routemaster` */

DROP TABLE IF EXISTS `routemaster`;

CREATE TABLE `routemaster` (
  `routecode` bigint NOT NULL AUTO_INCREMENT,
  `routename` varchar(50) DEFAULT NULL,
  `arbroutename` varchar(50) DEFAULT NULL,
  `subareacode` bigint DEFAULT NULL,
  `salesmancode` bigint DEFAULT NULL,
  `created` varchar(20) DEFAULT NULL,
  `cdat` datetime DEFAULT NULL,
  `modified` varchar(20) DEFAULT NULL,
  `mdat` datetime DEFAULT NULL,
  `memo1` varchar(50) DEFAULT NULL,
  `memo2` varchar(50) DEFAULT NULL,
  `hhcordseq` bigint DEFAULT '1',
  `hhcinvseq` bigint DEFAULT '1',
  `hhccshseq` bigint DEFAULT '1',
  `hhcivtseq` bigint DEFAULT '1',
  `bodocseq` bigint NOT NULL DEFAULT '1',
  `acbodocseq` bigint NOT NULL DEFAULT '1',
  `boinvseq` bigint DEFAULT '1',
  `vehiclenumber` bigint DEFAULT NULL,
  `vehicleodometer` bigint DEFAULT NULL,
  `enablescanneruse` int DEFAULT NULL,
  `routeunloadvariance` decimal(18,3) DEFAULT NULL,
