  `pricingkey` bigint DEFAULT NULL,
  `created` char(20) DEFAULT NULL,
  `cdat` datetime DEFAULT NULL,
  `modified` char(20) DEFAULT NULL,
  `mdat` datetime DEFAULT NULL,
  `memo1` varchar(50) DEFAULT NULL,
  `memo2` varchar(50) DEFAULT NULL,
  `alternatesalesmancode` varchar(50) DEFAULT NULL,
  `type` int DEFAULT '0',
  `activestatus` int DEFAULT '1',
