  `ansalesmancode` varchar(9) DEFAULT NULL,
  `username` varchar(255) DEFAULT NULL,
  `userpassword` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`salesmancode`),
  UNIQUE KEY `u_alternatesalesmancode` (`alternatesalesmancode`),
  KEY `FK_Salesman_Company` (`parentcompany`),
  KEY `FK_Salesman_CustomerPricing` (`pricingkey`),
  KEY `Salesman_FK02` (`messagekey`),
  CONSTRAINT `FK_Salesman_Company` FOREIGN KEY (`parentcompany`) REFERENCES `company` (`cmpycode`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `FK_Salesman_CustomerPricing` FOREIGN KEY (`pricingkey`) REFERENCES `customerpricing` (`pricingkey`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `Salesman_FK02` FOREIGN KEY (`messagekey`) REFERENCES `salesmanmessages` (`messagekey`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=302497 DEFAULT CHARSET=latin1;

