/* Event structure for event `auto_depot_close` */

/*!50106 DROP EVENT IF EXISTS `auto_depot_close`*/;

DELIMITER $$

/*!50106 CREATE DEFINER=`root`@`localhost` EVENT `auto_depot_close` ON SCHEDULE EVERY 1 DAY STARTS '2021-10-13 22:00:00' ON COMPLETION NOT PRESERVE ENABLE DO BEGIN
	 --   call auto_update_depot_close_summary();
	END */$$
DELIMITER ;

/* Event structure for event `OutStandingProc` */

/*!50106 DROP EVENT IF EXISTS `OutStandingProc`*/;

DELIMITER $$

/*!50106 CREATE DEFINER=`root`@`localhost` EVENT `OutStandingProc` ON SCHEDULE EVERY 1 DAY STARTS '2023-06-13 01:00:00' ON COMPLETION NOT PRESERVE ENABLE DO call ImportOutstandingInvoice_SAP */$$
DELIMITER ;

/* Function  structure for function  `check_monthclosing_time` */

/*!50003 DROP FUNCTION IF EXISTS `check_monthclosing_time` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `check_monthclosing_time`(transactiondate DATETIME) RETURNS date
    DETERMINISTIC
BEGIN
	SET @monthclose = 0;
	SET @closingtime = '17:00:00';
	SET @currenttime = '17:00:00';
	SET @lastmonthdate = CURDATE();
	SET @trandate = CONVERT(transactiondate, DATE);
	
	SELECT `status` INTO @monthclose FROM controlpanel WHERE flagid = 6;
	SELECT CONVERT(flagvalue, TIME) INTO @closingtime FROM controlpanel WHERE flagid = 83;
	SELECT CURTIME() INTO @currenttime;	
	SELECT LAST_DAY(CURDATE()) - INTERVAL 1 DAY INTO @lastmonthdate;
	
	IF @monthclose = 1 THEN
		IF CONVERT(@trandate, DATE) = CONVERT(@lastmonthdate, DATE) THEN
			IF CONVERT(@closingtime, TIME) > CONVERT(@currenttime, TIME) THEN			
				RETURN @trandate;
			ELSE
				SELECT CONVERT(transactiondate, DATE) + INTERVAL 1 DAY INTO @trandate;
				RETURN @trandate;
			END IF;
		ELSE
			RETURN @trandate;
		END IF;
	ELSE
		RETURN @trandate;
	END IF;
    END */$$
DELIMITER ;

/* Function  structure for function  `currency_name_get` */

/*!50003 DROP FUNCTION IF EXISTS `currency_name_get` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `currency_name_get`(code1 INT,code2 int) RETURNS varchar(25) CHARSET latin1
    DETERMINISTIC
BEGIN
		DECLARE nam1 varchar(25);
		if code1 != '' then
			SELECT a.currencyname into nam1  FROM currencymaster AS a WHERE a.currencycode =  code1 limit 1;
			RETURN nam1;
		else
			select currencydetail.exchangerate into @rate1 from currencydetail where currencydetail.currencydetailcode = code2 limit 1;
			RETURN @rate1;
		end if;
    END */$$
DELIMITER ;

/* Function  structure for function  `customer_pricing_type` */

/*!50003 DROP FUNCTION IF EXISTS `customer_pricing_type` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `customer_pricing_type`( pricing_type INT) RETURNS varchar(25) CHARSET latin1
    DETERMINISTIC
BEGIN
    
		IF pricing_type = 0 THEN
			RETURN 'All';
			
		ELSEIF pricing_type = 1 THEN
			RETURN 'Special Price';
			
		ELSEIF pricing_type = 2 THEN
			RETURN 'Customer';
			
		ELSEIF pricing_type = 3 THEN
			RETURN 'Salesman';
			
		ELSEIF pricing_type = 4 THEN
			RETURN 'Depot';
		ELSE 
			RETURN 'ALL';
		END IF;
    END */$$
DELIMITER ;

/* Function  structure for function  `getCustomRounding` */

/*!50003 DROP FUNCTION IF EXISTS `getCustomRounding` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getCustomRounding`(valAmt DECIMAL(8,3),roundingPoints DECIMAL(5,3)) RETURNS decimal(8,3)
    DETERMINISTIC
BEGIN
	IF (roundingPoints>0) THEN -- Upper Rounding
		IF (valAmt>0) THEN
			RETURN CEILING(ABS(valAmt)*(100/(ABS(roundingPoints)*100)))/(100/(ABS(roundingPoints)*100));
		ELSE
			RETURN -CEILING(ABS(valAmt)*(100/(ABS(roundingPoints)*100)))/(100/(ABS(roundingPoints)*100));
		END IF;
	ELSE -- Lower Rounding
		IF (valAmt>0) THEN		
			RETURN FLOOR(ABS(valAmt)*(100/(ABS(roundingPoints)*100)))/(100/(ABS(roundingPoints)*100));
		ELSE
			RETURN -FLOOR(ABS(valAmt)*(100/(ABS(roundingPoints)*100)))/(100/(ABS(roundingPoints)*100));
		END IF;
	END IF;
	-- CEILING(.41*(100/20))/(100/20)	sfa_ver6sfa_ver6
    END */$$
DELIMITER ;

/* Function  structure for function  `getpdctocashstatus` */

/*!50003 DROP FUNCTION IF EXISTS `getpdctocashstatus` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getpdctocashstatus`() RETURNS int
    DETERMINISTIC
BEGIN
    RETURN (select `status` from controlpanel where flagid = 36);		
    END */$$
DELIMITER ;

/* Function  structure for function  `getsalesmantype` */

/*!50003 DROP FUNCTION IF EXISTS `getsalesmantype` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getsalesmantype`( salesmantype INT) RETURNS varchar(50) CHARSET latin1
    DETERMINISTIC
BEGIN
    
		IF salesmantype = '1' THEN
			RETURN 'Salesman';
		ELSEIF salesmantype = '2' THEN
			RETURN 'Merchandizer';
		ELSEIF salesmantype = '3' THEN
			RETURN 'Supervisor';
		ELSEIF salesmantype = '4' THEN
			RETURN 'Helper';		
		ELSE
			RETURN '';
		END IF;
    END */$$
DELIMITER ;

/* Function  structure for function  `getstartingloadmethod` */

/*!50003 DROP FUNCTION IF EXISTS `getstartingloadmethod` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getstartingloadmethod`( method_no INT) RETURNS varchar(100) CHARSET latin1
    DETERMINISTIC
BEGIN
		IF method_no = '0' THEN
			RETURN 'Create New Load';
		ELSEIF method_no = '1' THEN
			RETURN 'Load Imported From ERP';
		ELSEIF method_no = '2' THEN
			RETURN 'Convert Load Request to Load';
		ELSEIF method_no = '3' THEN
			RETURN 'Sales order to load';
		ELSEIF method_no = '4' THEN
			RETURN 'Populate Previous day load';
		ELSEIF method_no = '5' THEN
			RETURN 'Use Suggested Load';
		ELSE
			RETURN '';
		END IF;		
    END */$$
DELIMITER ;

/* Function  structure for function  `getsurveytype` */

/*!50003 DROP FUNCTION IF EXISTS `getsurveytype` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `getsurveytype`( surveytype INT) RETURNS varchar(50) CHARSET latin1
    DETERMINISTIC
BEGIN
    
		IF surveytype = '0' THEN		
			RETURN 'Title';
		ELSEIF surveytype = '1' THEN
			RETURN 'Numeric Input';			
		ELSEIF surveytype = '2' THEN
			RETURN 'Alpha-Num Input Response';			
		ELSEIF surveytype = '3' THEN
			RETURN 'Date Input';
		ELSEIF surveytype = '4' THEN
			RETURN 'Time Input';
		ELSEIF surveytype = '5' THEN		
			RETURN 'Yes/No Option';
		ELSEIF surveytype = '6' THEN
			RETURN 'Check Box';			
		ELSEIF surveytype = '7' THEN
			RETURN 'Lookup Field';			
		ELSEIF surveytype = '8' THEN
			RETURN 'Subtitle';
		ELSE
			RETURN '';
		END IF;		
    END */$$
DELIMITER ;

