/* Function  structure for function  `get_month_order` */

/*!50003 DROP FUNCTION IF EXISTS `get_month_order` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `get_month_order`() RETURNS varchar(100) CHARSET latin1
    DETERMINISTIC
BEGIN
		DECLARE start_value INT DEFAULT MONTH(CURRENT_DATE());
		DECLARE end_value INT DEFAULT 12;
		DECLARE str varchar(100);
		
		DROP TEMPORARY TABLE IF EXISTS tmptbl;
		CREATE TEMPORARY TABLE tmptbl(monthno int);
		
		WHILE start_value <= end_value DO
			INSERT INTO tmptbl(monthno)VALUES(start_value);
			SET start_value = start_value + 1;
			
			IF start_value = 13 and MONTH(CURRENT_DATE()) != 1 THEN
				SET start_value = 1;
				set end_value = (MONTH(CURRENT_DATE())-1);
			END IF;
			
		END WHILE; 
		
		SELECT GROUP_CONCAT(monthno) INTO str FROM tmptbl;
		RETURN str;
				
    END */$$
DELIMITER ;

/* Function  structure for function  `get_name_type_base` */

/*!50003 DROP FUNCTION IF EXISTS `get_name_type_base` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `get_name_type_base`(  in_code INT,in_type INT) RETURNS varchar(25) CHARSET latin1
    DETERMINISTIC
BEGIN
	-- in_type is for customername  2 salesman name  3 routemaster
	-- 4 creditday
	IF in_type = 1 THEN
	
		RETURN  (SELECT customermaster.customername FROM customermaster WHERE customermaster.customercode = in_code LIMIT 1);
		
	ELSEIF  in_type = 2 THEN
	
		RETURN  (SELECT salesman.salesmanname1 FROM salesman WHERE salesman.salesmancode = in_code LIMIT 1);
		
	ELSEIF  in_type = 3 THEN
	
		RETURN  (SELECT routemaster.routename FROM routemaster WHERE routemaster.routecode = in_code LIMIT 1);
		
	ELSEIF  in_type = 4 THEN
	
		RETURN  (SELECT customermaster.creditlimitdays FROM customermaster WHERE customercode = in_code LIMIT 1);
	ELSEIF  in_type = 5 THEN
	
		RETURN  (SELECT itemmaster.unitspercase FROM itemmaster WHERE actualitemcode = in_code LIMIT 1);
	
	END IF;
    END */$$
DELIMITER ;

/* Function  structure for function  `get_number_type_base` */

/*!50003 DROP FUNCTION IF EXISTS `get_number_type_base` */;
DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` FUNCTION `get_number_type_base`(  in_code INT,in_type INT) RETURNS varchar(25) CHARSET latin1
    DETERMINISTIC
BEGIN
	-- find invoicenuber,documentnumber,ordernumber base on routemaster
	-- 1 - invoicenumber 2-documentnumber 3- ordernumber 4-arcollection sequence
	IF in_type = 1 THEN
	
		RETURN  (select CONCAT(routecode,6,LPAD(IFNULL(boinvseq,0),6,'0')) AS invoice_seq  FROM routemaster WHERE routecode = in_code LIMIT 1);
		
	ELSEIF  in_type = 2 THEN
	
		RETURN  (SELECT CONCAT(routecode,LPAD(IFNULL(bodocseq,0),2,'0')) AS document_seq  FROM routemaster WHERE routecode = in_code LIMIT 1);
		
	ELSEIF  in_type = 3 THEN
	
		RETURN  (SELECT CONCAT(routecode,5,LPAD(IFNULL(boordseq,0),6,'0')) AS order_seq  FROM routemaster WHERE routecode = in_code LIMIT 1);
		
	ELSEIF  in_type = 4 THEN
	
		RETURN  (SELECT CONCAT(routecode,7,LPAD(IFNULL(boordseq,0),6,'0')) AS order_seq  FROM routemaster WHERE routecode = in_code LIMIT 1);
	
	END IF;
    END */$$
DELIMITER ;

