/* Procedure structure for procedure `buildtargetcalender` */

/*!50003 DROP PROCEDURE IF EXISTS  `buildtargetcalender` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `buildtargetcalender`(
	dateStart DATE, 
	dateEnd DATE)
BEGIN
	DECLARE adate DATE;
	
	DELETE FROM targetcalender;
	
	WHILE dateStart <= dateEnd DO
		SET adate = (SELECT caldate FROM targetcalender WHERE caldate = dateStart);
		IF adate IS NULL THEN 
			BEGIN
				INSERT INTO targetcalender (caldate,calday) VALUES (dateStart,DAYNAME(dateStart));
			END; 
		END IF;
		SET dateStart = DATE_ADD(dateStart, INTERVAL 1 DAY);
	END WHILE;
END */$$
DELIMITER ;

