/* Procedure structure for procedure `employees_hier` */

/*!50003 DROP PROCEDURE IF EXISTS  `employees_hier` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `employees_hier`(
in p_emp_id smallint unsigned
)
begin
declare v_done tinyint unsigned default(0);
declare v_dpth smallint unsigned default(0);
create temporary table hier(
 boss_id smallint unsigned, 
 emp_id smallint unsigned, 
 depth smallint unsigned
)engine = memory;
insert into hier select boss_id, emp_id, v_dpth from employees where emp_id = p_emp_id;
/* http://dev.mysql.com/doc/refman/5.0/en/temporary-table-problems.html */
CREATE TEMPORARY TABLE emps ENGINE=MEMORY SELECT * FROM hier;
WHILE NOT v_done DO
    IF EXISTS( SELECT 1 FROM employees e INNER JOIN hier ON e.boss_id = hier.emp_id AND hier.depth = v_dpth) THEN
        INSERT INTO hier SELECT e.boss_id, e.emp_id, v_dpth + 1 
            FROM employees e INNER JOIN emps ON e.boss_id = emps.emp_id AND emps.depth = v_dpth;
        SET v_dpth = v_dpth + 1;            
        TRUNCATE TABLE emps;
        INSERT INTO emps SELECT * FROM hier WHERE depth = v_dpth;
    ELSE
        SET v_done = 1;
    END IF;
END WHILE;
SELECT 
 e.emp_id,
 e.name AS emp_name,
 p.emp_id AS boss_emp_id,
 p.name AS boss_name,
 hier.depth
FROM 
 hier
INNER JOIN employees e ON hier.emp_id = e.emp_id
LEFT OUTER JOIN employees p ON hier.boss_id = p.emp_id;
DROP TEMPORARY TABLE IF EXISTS hier;
DROP TEMPORARY TABLE IF EXISTS emps;
END */$$
DELIMITER ;

/* Procedure structure for procedure `ImportOutstandingInvoice_SAP` */

/*!50003 DROP PROCEDURE IF EXISTS  `ImportOutstandingInvoice_SAP` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `ImportOutstandingInvoice_SAP`()
BEGIN
        UPDATE invoiceheader INNER JOIN customermaster ON invoiceheader.customercode = customermaster.customercode
        SET invoiceheader.paymenttype=customermaster.invoicepaymentterms
        WHERE   invoiceheader.transactiondate >='2023-12-01'  AND invoiceheader.manualinvoicetype=1
        AND invoiceheader.voidflag=0;
        update invoiceheader set presoldordernumber=hhcinvoicenumber where  manualinvoicetype=1 and transactiondate >='2023-12-01';
        UPDATE invoiceheader SET presoldordernumber=invoicenumber WHERE  manualinvoicetype=0 AND transactiondate >='2023-12-01';
         
        UPDATE CUSTOMERMASTER SET BALANCE=0 WHERE activecustomer=1 AND invoicepaymentterms <>1 ;
        DELETE FROM CustomerInvoice;
        INSERT INTO CustomerInvoice SELECT * FROM CustomerInvoice_SAP;
        DELETE FROM CustomerInvoice WHERE TransactionDate >='2023-12-01';
        
                
        DELETE FROM customerinvoice WHERE invoicenumber IN(1122401029,1122401032,1122401035,1122401039) AND customercode=2458096;
        DELETE FROM customerinvoice WHERE invoicenumber IN (724400071) AND customercode=2476151;
        DELETE FROM customerinvoice WHERE invoicenumber IN (724509012) AND customercode=12307;
        DELETE FROM customerinvoice WHERE invoicenumber IN (724508892) AND customercode=3491;
      
        -- update  customermaster set balance=256.200 where customercode=2458096
        
        UPDATE  invoiceheader SET PaymentType=0 WHERE TransactionDate >='2023-12-01'
        AND ManualInvoiceType=1 AND PaymentType=1;
        UPDATE  invoiceheader SET PaymentType=1 WHERE TransactionDate >='2023-12-01'
        AND ManualInvoiceType=1 AND PaymentType=2 ;     
        
        DELETE FROM tempInvData;
        
        INSERT INTO tempInvData
        SELECT  
        ad.invoicenumber  AS invoicenumber,
        ah.customercode  ,ah.routecode,
        0 salesmancode,ad.totalinvoiceamount,
        SUM(ad.AmountPaid)amntpaid 
        FROM arheader ah INNER JOIN ardetail ad ON ah.transactionkey=ad.transactionkey
        WHERE ah.transactiondate>= '2023-12-01'  AND ah.VoidFlag=0   AND ad.invoicenumber IN (
        SELECT InvoiceNumber FROM CustomerInvoice ) 
        GROUP BY  ad.invoicenumber, ah.customercode  ,ah.routecode,ad.totalinvoiceamount  ;
        
        UPDATE CustomerInvoice INNER JOIN tempInvData ON CustomerInvoice.InvoiceNumber = tempInvData.invoicenumber
        SET CustomerInvoice.AmountPaid=CustomerInvoice.AmountPaid+tempInvData.amntpaid,
        CustomerInvoice.InvoiceBalance=(CustomerInvoice.InvoiceBalance-tempInvData.amntpaid)
        WHERE CustomerInvoice.CustomerCode=tempInvData.CustomerCode
        AND CustomerInvoice.RouteCode=tempInvData.RouteCode ;
        
	-- SET @MaxTranKey := 0;
	-- SELECT MAX(TransactionKey) FROM customerinvoice;
	-- 32998 +ROW_NUMBER() OVER( ORDER BY (SELECT 1)) AS rank1,   (@row_number:=@row_number + 1) AS rank1
	SET @row_number = 34286;   
	INSERT INTO CustomerInvoice(TransactionKey,TransactionType,DocumentNumber,InvoiceNumber,TransactionDate,CustomerCode,
        RouteCode,
        SalesmanCode,TotalInvoiceAmount,TotalSalesAmount,InvoiceBalance,PaymentType,VoidFlag,PaymentStatus,HHCInvoiceNumber,
        Remarks1,Remarks2,RouteStartDate,ERPReferenceNumber,MDat,AmountPaid)
        SELECT 34286 +ROW_NUMBER() OVER( ORDER BY (SELECT 1)) AS rank1, 2 AS transactiontype,
        presoldordernumber documentnumber ,
        presoldordernumber invoicenumber,transactiondate,
        ih.customercode  ,ih.routecode,
        ih.salesmancode,ih.totalinvoiceamount,totalinvoiceamount,totalinvoiceamount,2,0,0,totalinvoiceamount,ih.invoicenumber,
        'NotPaid/PartaillyPaid Invoice',NULL,CONVERT(ih.invoicenumber,CHAR),SYSDATE(),0
        FROM invoiceheader ih WHERE Paymenttype IN (1) AND ih.VoidFlag=0 AND transactiondate >= '2023-12-01' AND presoldordernumber 
        NOT IN (SELECT invoicenumber FROM customerinvoice);
        
        DELETE FROM  tempInvData;
        INSERT INTO tempInvData
        SELECT  
        ad.invoicenumber  AS invoicenumber,
        ah.customercode  ,ah.routecode,
        0 salesmancode,ad.totalinvoiceamount,
        SUM(ad.AmountPaid)amntpaid 
        FROM arheader ah INNER JOIN ardetail ad ON ah.transactionkey=ad.transactionkey
        WHERE ah.transactiondate>= '2023-12-01' AND ah.VoidFlag=0  AND ad.invoicenumber IN (
        SELECT presoldordernumber FROM invoiceheader WHERE   transactiondate >= '2023-12-01' ) 
        GROUP BY  ad.invoicenumber,   ah.customercode  ,ah.routecode,ad.totalinvoiceamount,ad.invoicenumber;
        
        UPDATE CustomerInvoice INNER JOIN tempInvData ON CustomerInvoice.InvoiceNumber = tempInvData.invoicenumber
        SET CustomerInvoice.AmountPaid=tempInvData.amntpaid,
        CustomerInvoice.InvoiceBalance=(CustomerInvoice.InvoiceBalance-tempInvData.amntpaid)
        WHERE CustomerInvoice.CustomerCode=tempInvData.CustomerCode
        AND CustomerInvoice.RouteCode=tempInvData.RouteCode ;
        
        DELETE FROM customerinvfinal;
        INSERT INTO customerinvfinal
        (SELECT customercode,SUM(invoicebalance) AS invoicebalance FROM customerinvoice GROUP BY customercode );
        UPDATE customermaster  INNER JOIN customerinvfinal ON customermaster.customercode=customerinvfinal.`customercode`
        SET customermaster.Balance=customerinvfinal.invoicebalance ;
 
        DELETE FROM customerinvoice WHERE invoicebalance=0;
        UPDATE CUSTOMERINVOICE SET ERPREFERENCENUMBER=INVOICENUMBER, remarks1= INVOICENUMBER  
        WHERE LTRIM(RTRIM(INVOICENUMBER)) <> LTRIM(RTRIM(ERPREFERENCENUMBER)) ;
        
    
        insert into outstanding_Log  select concat('Success : ',sysdate());
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_ardetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_ardetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_ardetail`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
        
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
	
	-- SELECT @closedroute, @indicator, @fromtime, @totime;
	
	SELECT 	
		arh.invoicenumber AS receiptno,
		ard.routekey,
		ard.invoicenumber AS invoiceno,
		CASE WHEN arh.transactiondate = ard.invoicedate THEN '0' ELSE ard.alternateinvoicenumber END AS oraclerefno, 
		ard.amountpaid,
		arh.customercode attribute1
	FROM ardetail ard
		INNER JOIN arheader arh ON arh.transactionkey = ard.transactionkey
	WHERE 	
		ard.routekey = routeKey AND 
		CAST(arh.receivedtime AS TIME) BETWEEN @fromtime AND @totime AND 
		arh.transmitindicator < @indicator;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_arheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_arheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_arheader`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
		
	SELECT 	
		arh.invoicenumber AS receiptno,
		arh.routekey,		
		DATE(arh.transactiondate) AS receiptdate,
		cm.ancustomercode AS custrefno,
		cm.customercode AS custcode,
		arh.routecode,
		sm.salesmancode AS salesmancode,
		arh.totalinvoiceamount AS receiptamt,
		CASE WHEN ccd.typecode = 1 THEN "CHEQUE" ELSE "CASH" END AS MOP,
		ccd.checknumber AS chequeno,
		DATE(ccd.checkdate) AS checkdate,			
		bm.bankname AS bankname,
		CASE WHEN advancepaymentflag = 1 THEN 'ADV' ELSE 'AR' END trantype
	FROM arheader arh
		INNER JOIN customermaster cm ON cm.customercode = arh.customercode
		INNER JOIN cashcheckdetail ccd ON ccd.routekey = arh.routekey AND ccd.visitkey = arh.visitkey 
		LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
		INNER JOIN salesman sm ON sm.salesmancode = arh.salesmancode
	WHERE 	
		arh.documentnumber > 0 AND arh.routekey = routeKey AND CAST(arh.receivedtime AS TIME) BETWEEN @fromtime AND @totime AND 
			arh.transmitindicator < @indicator;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_cashinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_cashinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_cashinvoice`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 2 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
	
	SELECT 	
		sh.invoicenumber AS receiptno,
		sh.routekey,		
		DATE(sh.transactiondate) AS receiptdate,
		cm.ancustomercode AS custrefno,
		cm.customercode AS custcode,
		sh.routecode,
		sm.salesmancode AS salesmancode,
		sh.totalinvoiceamount receiptamt,
		-- sh.totalinvoiceamount receiptamt,
		CASE WHEN ccd.typecode = 1 THEN "CHEQUE" ELSE "CASH" END AS MOP,
		ccd.checknumber AS chequeno,
		DATE(ccd.checkdate) AS checkdate,			
		bm.bankname AS bankname,
		'INV' trantype
	FROM invoiceheader sh
		INNER JOIN customermaster cm ON cm.customercode = sh.customercode
		INNER JOIN cashcheckdetail ccd ON ccd.routekey = sh.routekey AND ccd.visitkey = sh.visitkey 
		LEFT JOIN bankmaster bm ON bm.bankcode = ccd.bankcode
		INNER JOIN salesman sm ON sm.salesmancode = sh.salesmancode
	WHERE 	
		sh.routekey = routeKey AND sh.immediatepaid != 0 AND 
			CAST(sh.receivedtime AS TIME) BETWEEN @fromtime AND @totime;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_closingstocks` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_closingstocks` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_closingstocks`(
		IN routeKey BIGINT(20)
	)
BEGIN
	select 		ith.routecode,
			sm.salesmancode as salesmancode,
			itd.routekey,
			DATE(ith.transactiondate) as closingdate,
			ith.documentnumber, 			
			im.actualitemcode as itemcode,
			itd.quantity
		from 	inventorytransactiondetail itd
			inner join inventorytransactionheader ith on ith.detailkey = itd.detailkey  AND ith.transmitindicator =0
			inner join itemmaster im on im.actualitemcode = itd.itemcode
			INNER JOIN salesman sm ON sm.salesmancode = ith.salesmancode
		where 	itd.routekey = routeKey AND
			itd.transactiontypecode IN (6,5);
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_damages` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_damages` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_damages`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT 
		sed.routecode,
		sed.salesmancode,
		DATE(sed.routeenddate) AS enddate,
		sed.routekey,
		concat(sed.routecode,'0',sed.routekey) documentnumber, 
		im.actualitemcode AS itemcode,
		'B' AS transactiontype,	
		im.memo2 units,
		SUM(rd.quantity) quantity,
		rr.alternatecode attribute2,
		DATE(CASE WHEN rd.expirydate = '0000-00-00' THEN sed.routestartdate ELSE COALESCE(rd.expirydate, sed.routestartdate) END) as expirydate,
		@linid := CASE WHEN @invoice = sed.routekey THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := sed.routekey AS docn
	FROM startendday sed 	
		INNER JOIN invoicedetail id ON sed.routekey = id.routekey
		INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
		INNER JOIN invoicerxddetail rd ON rd.transactionkey = id.transactionkey AND rd.itemcode = id.itemcode
		INNER JOIN expiryreturnreasons rr ON rr.code = rd.reasoncode
	WHERE rd.itemtransactiontype = 2 AND sed.routekey = routeKey
	GROUP BY sed.routecode, sed.salesmancode, sed.routekey, im.actualitemcode, rr.alternatecode, im.memo2, 
		COALESCE(rd.expirydate, sed.routestartdate), rr.alternatecode 
	ORDER BY 4, 12;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_get_arinventory_routekey` */

