/* Procedure structure for procedure `int_exp_get_closedroutes` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_get_closedroutes` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_get_closedroutes`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN routeEndDate DATETIME	
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'rm.routecode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'cnt.*';
	END IF;
	SET @count_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM startendday sed
			INNER JOIN routemaster rm on rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
		WHERE sed.routeclosed = 1 AND sed.exportedflag =0 AND sed.routeenddate = '",routeEndDate,"'");
	PREPARE s1 FROM @count_sql;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM startendday sed
			INNER JOIN routemaster rm on rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
		WHERE sed.routeclosed = 1 AND sed.exportedflag = 0 AND sed.routeenddate = '",routeEndDate, "' ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    -- SELECT @dyn_sql;
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
    END */$$
DELIMITER ;

