/* Procedure structure for procedure `int_exp_get_routekey_rpt` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_get_routekey_rpt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_get_routekey_rpt`()
BEGIN
      
SET @trandate = '2017-03-01';
SELECT routekey
FROM
(
	SELECT DISTINCT routekey FROM invoiceheader WHERE transmitindicator = 0 AND voidflag = 0
	UNION
	SELECT DISTINCT routekey FROM arheader WHERE transmitindicator = 0 AND voidflag = 0
	UNION 
	SELECT DISTINCT routekey FROM inventorytransactionheader WHERE transmitindicator = 0 AND transactiontype IN (2,4) AND voidflag = 0
	UNION
	SELECT DISTINCT routekey FROM salesorderheader WHERE transmitindicator = 0 AND voidflag = 0
) trip
WHERE routekey > 0;  
END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_loadrequest` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_loadrequest` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_loadrequest`(
		IN routeKey BIGINT(20)
	)
BEGIN	
	SET @sql = CONCAT("
		SELECT
			ith.routecode,
			ith.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			ith.documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE((SELECT rm.alternateroutecode FROM routemaster rm WHERE rm.routecode = ith.transferlocationcode LIMIT 1), '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0 AND ith.isurgent =1
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'F'
		WHERE 	
			itd.routekey = ", routeKey, " AND itd.transactiontypecode IN (8)  
			UNION
		SELECT
			ith.routecode,
			ith.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			CONCAT(ith.documentnumber,'0') documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE((SELECT rm.alternateroutecode FROM routemaster rm WHERE rm.routecode = ith.transferlocationcode LIMIT 1), '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0 AND ith.isurgent =1
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'NF'
		WHERE 	
			itd.routekey = ", routeKey, " AND itd.transactiontypecode IN (8)");
	
	DROP TABLE IF EXISTS int_exp_loadrequestdetail;
	
	SET @sql = CONCAT('CREATE TABLE int_exp_loadrequestdetail AS ', @sql, ' ');	
	PREPARE stmt1 FROM @sql;
	EXECUTE stmt1;
	
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT
		routecode,
		salesmancode,
		DATE(transferdate) AS transferdate,
		DATE(requestdate) AS requestdate,
		routekey,
		documentnumber, 
		itemcode,
		quantity,
		units,
		attribute2,
		attribute3,
		@linid := CASE WHEN @invoice = documentnumber THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := documentnumber AS docno
	FROM 	
		int_exp_loadrequestdetail	
	ORDER BY 
		documentnumber, itemcode;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_loadrequest_scheduler` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_loadrequest_scheduler` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_loadrequest_scheduler`(
	)
BEGIN	
	SET @sql = CONCAT("
		SELECT
			ith.routecode,
			ith.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			ith.documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE(rm.alternateroutecode, '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0 AND itd.transactiontypecode IN (8)  
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'F'
				LEFT OUTER JOIN routemaster rm on rm.routecode =  ith.transferlocationcode
			
			
		UNION
		
		SELECT
			ith.routecode,
			ith.salesmancode AS salesmancode,
			DATE(ith.transactiondate) AS transferdate,
			DATE(ith.requestdate) AS requestdate,
			itd.routekey,
			CONCAT(ith.documentnumber,'0') documentnumber, 
			im.actualitemcode AS itemcode,
			itd.quantity,
			im.memo2 units,
			im.hhcitemshortdescription attribute2,
			COALESCE(rm.alternateroutecode, '') attribute3
		FROM 	
			inventorytransactiondetail itd
				INNER JOIN inventorytransactionheader ith ON ith.detailkey = itd.detailkey AND ith.transmitindicator =0 AND itd.transactiontypecode IN (8)  
				INNER JOIN itemmaster im ON im.actualitemcode = itd.itemcode AND im.hhcitemshortdescription = 'NF'
				LEFT OUTER JOIN routemaster rm on rm.routecode =  ith.transferlocationcode");
	
	DROP TABLE IF EXISTS int_exp_loadrequestdetail;
	
	SET @sql = CONCAT('CREATE TABLE IF NOT EXISTS int_exp_loadrequestdetail AS ', @sql, ' ');	
	PREPARE stmt2 FROM @sql;
	EXECUTE stmt2;
	
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT
		routecode,
		salesmancode,
		DATE(transferdate) AS transferdate,
		DATE(requestdate) AS requestdate,
		routekey,
		documentnumber, 
		itemcode,
		quantity,
		units,
		attribute2,
		attribute3,
		@linid := CASE WHEN @invoice = documentnumber THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := documentnumber AS docno
	FROM 	
		int_exp_loadrequestdetail	
	ORDER BY 
		documentnumber, itemcode;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `int_exp_loadtransfers` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_loadtransfers` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_loadtransfers`(
		IN routeKey BIGINT(20)
	)
BEGIN
	
	SET @sql = CONCAT("
		SELECT 
			ih.routecode,
			ih.salesmancode,
			DATE(ih.transactiondate) AS transferdate,
			ih.routekey,
			ih.documentnumber, 
			im.actualitemcode AS itemcode,		
			im.alternatecode,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN 'OUT' ELSE 'B' END AS transactiontype,	
			im.memo1 units,
			FLOOR(id.quantity/ im.unitspercase) quantity,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN retres.description END AS attribute2,
			CASE WHEN id.transactiontypecode = 3 THEN CURDATE() WHEN id.transactiontypecode = 2 THEN id.expirydate END AS expirydate,
			im.unitspercase attribute3
		FROM inventorytransactionheader ih 	
			INNER JOIN inventorytransactiondetail id ON ih.detailkey = id.detailkey AND ih.voidflag = 0
			INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
			LEFT OUTER JOIN retitmreasons retres ON retres.code = id.reasoncode
		WHERE ih.transactiontype = 2 AND FLOOR(id.quantity/ im.unitspercase) AND ih.routekey = ", routeKey, " AND ih.transmitindicator = 0
		
		UNION
		
		SELECT 
			ih.routecode,
			ih.salesmancode,
			DATE(ih.transactiondate) AS transferdate,
			ih.routekey,
			ih.documentnumber, 
			im.actualitemcode AS itemcode,		
			im.alternatecode,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN 'OUT' ELSE 'B' END AS transactiontype,	
			im.memo2 units,
			(id.quantity MOD im.unitspercase) quantity,
			CASE WHEN id.transactiontypecode = 3 THEN 'IN' WHEN id.transactiontypecode = 2 THEN retres.description END AS attribute2,
			CASE WHEN id.transactiontypecode = 3 THEN CURDATE() WHEN id.transactiontypecode = 2 THEN id.expirydate END AS expirydate,
			im.unitspercase attribute3
		FROM inventorytransactionheader ih 	
			INNER JOIN inventorytransactiondetail id ON ih.detailkey = id.detailkey AND ih.voidflag = 0
			INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
			LEFT OUTER JOIN retitmreasons retres ON retres.code = id.reasoncode
		WHERE ih.transactiontype = 2 AND (id.quantity MOD im.unitspercase) AND ih.routekey = ", routeKey, " AND ih.transmitindicator = 0");
	DROP TABLE IF EXISTS int_exp_transferdetail;	
	SET @sql = CONCAT('CREATE TABLE int_exp_transferdetail AS ', @sql, ' ');	
	PREPARE stmt1 FROM @sql;
	EXECUTE stmt1;
	SET @invoice := 0;
	SET @linid := 0;
	
	SELECT 
		routecode,
		salesmancode,
		transferdate,
		routekey,
		documentnumber, 
		itemcode,
		alternatecode,
		transactiontype,	
		units,
		quantity,
		attribute2,
		CASE WHEN expirydate = '0000-00-00' THEN CURDATE() ELSE expirydate END expirydate,
		attribute3,
		@linid := CASE WHEN @invoice = documentnumber THEN @linid+1 ELSE 1 END AS lineno,
		@invoice := documentnumber AS docn
	FROM int_exp_transferdetail
