/* Procedure structure for procedure `int_exp_orderdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `int_exp_orderdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `int_exp_orderdetail`(
		IN routeKey BIGINT(20)
	)
BEGIN
	SET @closedroute = 0;
	SET @s = CONCAT("SELECT routeclosed INTO @closedroute FROM startendday WHERE routekey = ", routekey," LIMIT 1");
        PREPARE stmt1 FROM @s;
        EXECUTE stmt1;	
	
	SET @indicator = @closedroute + 1;
	IF @closedroute = 1 THEN
		SET @fromtime = CAST("00:01:00" AS TIME);
		SET @totime = CAST("23:59:00" AS TIME);
	ELSE
		SET @fromtime = CAST(CONCAT(HOUR(CURTIME()),":00:00") AS TIME) - INTERVAL 10 HOUR;
		SET @totime = CURTIME() - INTERVAL 15 MINUTE;
	END IF;
		
	SET @sql = CONCAT("
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, FLOOR(sd.salesqty/ im.unitspercase) AS quantity, '0' AS refinvoiceno, 'O' AS linetype,
			sd.salescaseprice AS eachprice, 
			CASE WHEN sh.totalpromoamount > 0 THEN COALESCE(pd.promotionpercent, 0) ELSE 0 END AS itemdiscount,
			'' AS expirydate, im.memo1 unit, 'ORDER' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4, sd.salesordervat attribute5
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey 
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
			LEFT JOIN promotiondetail pd ON pd.routekey = sh.routekey AND pd.visitkey = sh.visitkey AND pd.promotiontypecode IN (2,6)
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND FLOOR(sd.salesqty/ im.unitspercase) > 0
			
			UNION
			
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno, 
			im.actualitemcode AS itemcode, (sd.salesqty MOD im.unitspercase) AS quantity, '0' AS refinvoiceno, 'O' AS linetype,
			sd.salesprice AS eachprice, 
			CASE WHEN sh.totalpromoamount > 0 THEN COALESCE(pd.promotionpercent, 0) ELSE 0 END AS itemdiscount,
			'' AS expirydate, im.memo2 unit, 'ORDER' attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4, sd.salesordervat attribute5
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
			LEFT JOIN promotiondetail pd ON pd.routekey = sh.routekey AND pd.visitkey = sh.visitkey AND pd.promotiontypecode IN (2,6)
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND (sd.salesqty MOD im.unitspercase) > 0
		
	UNION
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, FLOOR(sd.freesampleqty/im.unitspercase) AS quantity, '0' AS refinvoiceno, 'F' AS linetype,	
			'0'  AS eachprice, 0 AS itemdiscount, '' AS expirydate, im.memo1 unit, 'FREE' attribute2, im.unitspercase attribute3, 
			im.hhcitemshortdescription attribute4, 0 attribute5
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND FLOOR(sd.freesampleqty/im.unitspercase) > 0 
			
			UNION
			
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, (sd.freesampleqty MOD im.unitspercase) AS quantity, '0' AS refinvoiceno, 'F' AS linetype,	
			'0'  AS eachprice, 0 AS itemdiscount, '' AS expirydate, im.memo2 unit, 'FREE' attribute2, im.unitspercase attribute3, 
			im.hhcitemshortdescription attribute4, 0 attribute5
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND (sd.freesampleqty MOD im.unitspercase) > 0
	
	UNION
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, FLOOR(sd.returnqty/im.unitspercase) AS quantity, '0' AS refinvoiceno, 'G' AS linetype,	
			sd.returncaseprice AS eachprice, 0 AS itemdiscount, CURDATE() AS expirydate, im.memo1 unit,
			rr.alternatecode attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4, sd.returnvat attribute5
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
			INNER JOIN orderrxddetail rxd ON rxd.transactionkey = sd.transactionkey AND rxd.itemcode = sd.itemcode AND rxd.itemtransactiontype = 1
			INNER JOIN retitmreasons rr ON rr.code = rxd.reasoncode
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND FLOOR(sd.returnqty/im.unitspercase) > 0 
			
			UNION
			
		SELECT 0 AS SeqNo, sh.invoicenumber AS invoiceno, sd.routekey, 0 AS lineno,
			im.actualitemcode AS itemcode, (sd.returnqty MOD im.unitspercase) AS quantity, '0' AS refinvoiceno, 'G' AS linetype,	
			sd.returnprice AS eachprice, 0 AS itemdiscount, CURDATE() AS expirydate, im.memo2 unit, 
			rr.alternatecode attribute2, im.unitspercase attribute3, im.hhcitemshortdescription attribute4, sd.returnvat attribute5
		FROM salesorderdetail sd
			INNER JOIN salesorderheader sh ON sh.transactionkey = sd.transactionkey
			INNER JOIN itemmaster im ON im.actualitemcode = sd.itemcode AND im.hhcitemshortdescription = 'F' 
			INNER JOIN orderrxddetail rxd ON rxd.transactionkey = sd.transactionkey AND rxd.itemcode = sd.itemcode AND rxd.itemtransactiontype = 1
			INNER JOIN retitmreasons rr ON rr.code = rxd.reasoncode
		WHERE sd.routekey = ", routeKey, " AND sh.voidflag = 0 AND sh.transmitindicator < ", @indicator, " AND 
			CAST(sd.receivedtime AS TIME) BETWEEN '", @fromtime,"' AND '", @totime,"' AND (sd.returnqty MOD im.unitspercase) > 0");
		
		DROP TABLE IF EXISTS int_exp_orderdetail;
	
		SET @sql = CONCAT('CREATE TABLE int_exp_orderdetail AS ', @sql, ' ');	
		PREPARE stmt1 FROM @sql;
		EXECUTE stmt1;
		
		CALL int_exp_orderdetail_nf_items(routeKey);		
		
		SET @sql = CONCAT('INSERT INTO int_exp_orderdetail SELECT * FROM int_exp_orderdetail_nf_items');	
		PREPARE stmt2 FROM @sql;
		EXECUTE stmt2;
		
		SET @invoice := 0;
		SET @linid := 0;
		
		SELECT SeqNo, invoiceno, routekey,
			@linid := CASE WHEN @invoice = invoiceno THEN @linid+1 ELSE 1 END AS lineno,
			itemcode, quantity, refinvoiceno, linetype, eachprice, itemdiscount, expirydate, unit,
			@invoice := invoiceno AS invno, attribute2, attribute3, attribute4, attribute5
		FROM int_exp_orderdetail
		ORDER BY invoiceno, itemcode, unit, linetype; 
		
    END */$$
DELIMITER ;

