/* Procedure structure for procedure `sp_add_account_customer_addcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customer_addcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customer_addcustomer`(
	   IN cust_code BIGINT,
	   IN customer_status VARCHAR(20),
	   IN cust_name VARCHAR(50),
	   IN cust_address1 VARCHAR(50),
	   IN route_code BIGINT,
	   IN cust_address2 VARCHAR(50),
	   IN alt_code VARCHAR(50),
	   IN cust_address3 VARCHAR(50),
	   IN phone VARCHAR(20),
	   IN headoffice_code BIGINT(18),
	   IN pobox_num VARCHAR(30),
	   IN invo_pay_term INT(4),
	   IN cash_bal DOUBLE(8,0),
	   IN price_key DECIMAL(18,0),
	   IN credit_limit DOUBLE(18,4),
	   IN promotion_key INT(4),
	   IN credit_limit_days INT(4),
	   IN auth_grp_key INT(4),
	   IN discount_key INT(4),
	   IN distribution_key DECIMAL(18,0),
	   IN outlet_sub_type VARCHAR(20),
	   IN survey_key DECIMAL(18,0),
	   IN customer_cat INT(4),
	   IN arcustomer_type INT(4),
	   IN expiry_limit DOUBLE(8,0),
	   IN exprunning_value DOUBLE(8,0),
	   IN contact_name VARCHAR(50),
	   IN alpha_numeric VARCHAR(10),
	   IN cust_type INT(4),
	   IN createdby VARCHAR(30),
	   IN customer_name VARCHAR(50),
	   IN customer_state VARCHAR(50),
	   IN customer_city VARCHAR(50),
	   IN customer_add1 VARCHAR(50),
	   IN customer_add2 VARCHAR(50),
	   IN customer_add3 VARCHAR(50),
	   IN billtotbill INT(4),
	   IN ddldis_msg_key1 INT(4),
	   IN ddldis_msg_key2 INT(4),
	   IN ddlena_promo_edit_ord INT(4),
	   IN ddlcust_tax_key1 INT(4),
	   IN ddlcust_tax_key2 INT(4),
	   IN ddlcust_tax_key3 INT(4),
	   IN gpsdata DECIMAL(18,4),
	   IN ddlcust_visual INT(11),
	   IN ddlcust_adver INT(11),
	   IN ddlloyality_key INT(4),
	   IN var_applytax INT,
	   IN var_taxregistrationnumber VARCHAR(50),
	   IN var_traname VARCHAR(100),
	   IN var_tranamearabic VARCHAR(100),
	   IN chkdelivery_flag INT(4),
	   IN chkduedate_flag INT(4),
	   IN chkcustomer_statement INT(4)
	)
BEGIN
	DECLARE auto_insert INT;
	DECLARE in_flag_id INT;
    DECLARE rcode BIGINT;
    DECLARE gen_customercode BIGINT(18);		
    DECLARE in_depo_code INT;
	DECLARE in_route_depo_len INT;
	DECLARE discnt_key INT;	
	
	SELECT flagid INTO in_flag_id  FROM controlpanel  WHERE flagid IN ('7','8','9','76') AND `status`=1;
	
	IF ddldis_msg_key2 = '' THEN
		SET ddldis_msg_key2 = NULL;
	END IF; 
  
	IF in_flag_id = 7 THEN 
	
		SELECT MAX(customercode) INTO rcode FROM customermaster
		WHERE routecode =route_code  AND SUBSTRING(customercode,1,LENGTH(route_code)) LIKE route_code
		GROUP BY routecode;
	
		IF rcode IS NULL   THEN
			SET rcode =1;
			SET gen_customercode = CONCAT(route_code,'0000',rcode);			
		 ELSE		 
			SET rcode = rcode + 1 ;
			SET gen_customercode = rcode;			
		END IF;
		
    ELSEIF in_flag_id = 8 THEN
    
				SELECT depotmaster.depotcode INTO in_depo_code  FROM depotmaster 
				LEFT JOIN routemaster ON routemaster.regionmstcode = depotmaster.regionmstcode
				WHERE   routemaster.routecode = (route_code);
		
				SET in_route_depo_len = LENGTH(in_depo_code)+LENGTH(route_code);
				SELECT MAX(customercode) INTO rcode FROM customermaster
				WHERE routecode =route_code  AND SUBSTRING(customercode,1,in_route_depo_len) LIKE in_depo_code
				GROUP BY routecode ;		
		
		IF rcode IS NULL   THEN
			SET rcode =1;
			SET gen_customercode = CONCAT(in_depo_code,'0000',rcode);
		 ELSE
			SET rcode = rcode + 1 ;
			SET gen_customercode = rcode;
		END IF;
    ELSEIF in_flag_id = 9 THEN
    
				SELECT depotmaster.depotcode INTO in_depo_code  FROM depotmaster 
				LEFT JOIN routemaster ON routemaster.regionmstcode = depotmaster.regionmstcode
				WHERE   routemaster.routecode = (route_code);
		
				SELECT MAX(customercode) INTO rcode FROM customermaster
				WHERE routecode =route_code  AND SUBSTRING(customercode,1,LENGTH(in_depo_code)) LIKE in_depo_code
				GROUP BY routecode ;
				
				IF rcode IS NULL   THEN
						SET rcode =1;
						SET gen_customercode = CONCAT(route_code,in_depo_code,'0000',rcode);
				ELSE
						SET rcode = rcode + 1 ;
						SET gen_customercode = rcode;
				END IF;
		
		
    
    
	ELSE
	SELECT MAX(customercode) INTO rcode FROM customermaster;
		IF rcode IS NULL   THEN
				
			SET rcode =1;
			SET gen_customercode = CONCAT('0000',rcode);
		 ELSE
			
			SET rcode = rcode + 1;
			SET gen_customercode = rcode;
		END IF;
	
	END IF;
		
	-- Below condition is checked for the headoffice codeif it is zero then means customer = headerofficecode
	IF headoffice_code = 0 THEN 
		SET headoffice_code = gen_customercode;
	END IF;
	
	
		
	-- If auto insert is check from customer tab in Control panel	
	SELECT `status` INTO auto_insert FROM controlpanel WHERE flagid IN(22);		
	SELECT `status` INTO discnt_key  FROM controlpanel WHERE flagid IN(3);
	
	IF discnt_key = 0 THEN
		SET discount_key = 0;
	ELSE
		SET distribution_key = 0;
	END IF;
	
	IF ddldis_msg_key1 = '' THEN 
		SET ddldis_msg_key1 = NULL;
	END IF;
	
	IF ddldis_msg_key2 = '' THEN 
		SET ddldis_msg_key2 = NULL;
	END IF;
	
	IF ddlena_promo_edit_ord = '' THEN 
		SET ddlena_promo_edit_ord = NULL;
	END IF;
	
	IF ddlcust_tax_key1 = '' THEN 
		SET ddlcust_tax_key1 = NULL;
	END IF;
	
	IF ddlcust_tax_key2 = '' THEN 
		SET ddlcust_tax_key2 = NULL;
	END IF;
	
	IF ddlcust_tax_key3 = '' THEN 
		SET ddlcust_tax_key3 = NULL;
	END IF;	
	
	   
	INSERT INTO customermaster  SET
									districtcode 			= 1,
 									locationcode 			= 1,
									customercode  			= gen_customercode,
									activecustomer 			= customer_status,
									customername 			= cust_name,
									customeraddress1 		= cust_address1,
									routecode 				= route_code,
									customeraddress2 		= cust_address2,
									alternatecode 			= alt_code,
									customeraddress3 		= cust_address3,
									customerphone 			= phone,
									headofficecode 			= headoffice_code,
									pobox					= pobox_num,
									invoicepaymentterms 	= invo_pay_term,
									balance 				= cash_bal,
									pricingkey 				= price_key,
									creditlimit 			= credit_limit,
									promotionkey 			= promotion_key,
									creditlimitdays 		= credit_limit_days,
									authorizeditemgrpkey 	= auth_grp_key,
									discountkey 			= discount_key,
									distributionkey 		= distribution_key,
									outletsubtype 			= outlet_sub_type,
									surveykey 				= survey_key ,
									customercategory 		= customer_cat,
									arcustomertype 			= arcustomer_type,
									expirylimit 			= expiry_limit,
									exprunningvalue 		= exprunning_value,
									arbcontactname 			= contact_name,
									arbcustomername 		= customer_name,
									customerstate 			= customer_state,
									arabiccustomercity 		= customer_city,
									arbcustomeraddress1 	= customer_add1,
									arbcustomeraddress2 	= customer_add2,
									arbcustomeraddress3 	= customer_add3,
									ancustomercode			= alpha_numeric,
									numoutstandinginv		= billtotbill,
									messagekey1				= ddldis_msg_key1,
									messagekey2				= ddldis_msg_key2,
									enablepromoeditords		= ddlena_promo_edit_ord,
									custtaxkey1				= ddlcust_tax_key1,
									custtaxkey2 			= ddlcust_tax_key2,
									custtaxkey3 			= ddlcust_tax_key3,
									gpsdata				= gpsdata, 									
									`type` 					= cust_type,
									visualcode 			= ddlcust_visual,
									advertisecode 				=ddlcust_adver,
									created					= createdby,
									modified				= createdby,
									cdat					= CURRENT_DATE(),
									mdat					= CURRENT_DATE(),
									applytax 				= var_applytax,
									taxregistrationnumber 		= var_taxregistrationnumber,
									traname 			= var_traname,
									tranamearabic 			= var_tranamearabic,
									deliveryflag	 		= chkdelivery_flag,
									duedateflag 			= chkduedate_flag,
									statementcust 			= chkcustomer_statement;
									
				SELECT gen_customercode INTO @last_id;
	SELECT @last_id AS last_id;
	
	
	IF auto_insert = 1 THEN
		CALL sp_add_account_customer_routesequence(route_code,@last_id,createdby);
	END IF;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Customer','customermaster',@last_id,createdby,'Add');
	
	-- Update newcustomerseqnumber in Route Master		
	UPDATE routemaster SET newcustomerseqnumber = newcustomerseqnumber+1 WHERE routecode = route_code;		
			
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customer_addcustomermsg` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customer_addcustomermsg` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customer_addcustomermsg`(
	   in msg_desc 		varchar(50),
	   IN msg_line1 	VARCHAR(40),
	   IN msg_line2 	VARCHAR(40),
	   IN msg_line3 	VARCHAR(40),
	   IN msg_line4 	VARCHAR(40),
	   IN arbmsg_line1 	VARCHAR(100),
	   IN arbmsg_line2 	VARCHAR(100),
	   IN arbmsg_line3 	VARCHAR(100),
	   IN arbmsg_line4 	VARCHAR(100),
	   in msg_status	int(4),
	   in createdby 	varchar(30),
	   in altcode 		varchar(50)
	)
BEGIN	
	
	INSERT INTO customermessages  SET
									alternatecode 			= altcode,
									messagedescription		= msg_desc,
									messageline1 			= msg_line1,
									messageline2 			= msg_line2,
									messageline3 			= msg_line3,
									messageline4 			= msg_line4,
									arbmessageline1			= arbmsg_line1,
									arbmessageline2 		= arbmsg_line2,
									arbmessageline3			= arbmsg_line3,
									arbmessageline4			= arbmsg_line4,
									activestatus			= msg_status,
									created					= createdby,
									cdat					= CURRENT_DATE();
									
	select LAST_INSERT_ID() into @id;
	select @id as last_id;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Customer Message','customermessages',@id,createdby,'Add');
			
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customer_addcustomertmpl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customer_addcustomertmpl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customer_addcustomertmpl`(	   
	   in cust_code int,
	   IN customer_status VARCHAR(20),
	   in cust_name varchar(50),
	   in cust_address1 varchar(50),
	   in route_code BIGINT,
	   in cust_address2 varchar(50),
	   in alt_code varchar(50),
	   IN cust_address3 VARCHAR(50),
	   in phone varchar(20),
	   IN headoffice_code BIGINT,
	   in pobox_num VARCHAR(30),
	   in invo_pay_term int(4),
	   in cash_bal double(8,0),
	   in price_key decimal(18,0),
	   in credit_limit DOUBLE(18,4),
	   in promotion_key INT(4),
	   in credit_limit_days INT(4),
	   in auth_grp_key INT(4),
	   in discount_key INT(4),
	   in distribution_key DECIMAL(18,0),
	   in outlet_sub_type varchar(20),
	   in survey_key decimal(18,0),
	   in customer_cat INT(4),
	   in arcustomer_type INT(4),
	   in expiry_limit DOUBLE(8,0),
	   in exprunning_value DOUBLE(8,0),
	   in contact_name VARCHAR(50),
	   in alpha_numeric varchar(10),
	   in cust_type int(4),
	   in createdby varchar(30),
	   in customer_name varchar(50),
	   in customer_state VARCHAR(50),
	   in customer_city VARCHAR(50),
	   in customer_add1 VARCHAR(50),
	   in customer_add2 VARCHAR(50),
	   in customer_add3 VARCHAR(50),
	   IN billtotbill INT(4),
	   in template_name varchar(100),
	   IN ddldis_msg_key1 INT(4),
	   IN ddldis_msg_key2 INT(4),
	   IN ddlena_promo_edit_ord INT(4),
	   IN ddlcust_tax_key1 INT(4),
	   IN ddlcust_tax_key2 INT(4),
	   IN ddlcust_tax_key3 INT(4)
	)
BEGIN
	
	
	INSERT INTO customermaster  SET
									templateindicator 		= 1,
									templatename 			= template_name,
									activecustomer 			= customer_status,
									customername 			= cust_name,
									customeraddress1 		= cust_address1,
									routecode 				= NULL,
									customeraddress2 		= cust_address2,
									alternatecode 			= alt_code,
									customeraddress3 		= cust_address3,
									customerphone 			= phone,
									headofficecode 			= NULL,
									pobox					= pobox_num,
									invoicepaymentterms 	= invo_pay_term,
									balance 				= cash_bal,
									pricingkey 				= price_key,
									creditlimit 			= credit_limit,
									promotionkey 			= promotion_key,
									creditlimitdays 		= credit_limit_days,
									authorizeditemgrpkey 	= auth_grp_key,
									discountkey 			= discount_key,
									distributionkey 		= distribution_key,
									outletsubtype 			= outlet_sub_type,
									surveykey 				= survey_key ,
									customercategory 		= customer_cat,
									arcustomertype 			= arcustomer_type,
									expirylimit 			= expiry_limit,
									exprunningvalue 		= exprunning_value,
									arbcontactname 			= contact_name,
									arbcustomername 		= customer_name,
									customerstate 			= customer_state,
									arabiccustomercity 		= customer_city,
									arbcustomeraddress1 	= customer_add1,
									arbcustomeraddress2 	= customer_add2,
									arbcustomeraddress3 	= customer_add3,
									ancustomercode			= alpha_numeric,
									numoutstandinginv		= billtotbill,
									messagekey1				= ddldis_msg_key1,
									messagekey2				= ddldis_msg_key2,
									enablepromoeditords		= ddlena_promo_edit_ord,
									custtaxkey1				= ddlcust_tax_key1,
									custtaxkey2 			= ddlcust_tax_key2,
									custtaxkey3 			= ddlcust_tax_key3,
									`type` 					= cust_type,
									created					= createdby,
									modified				= createdby,
									cdat					= CURRENT_DATE(),
									mdat					= CURRENT_DATE();
									
				SELECT LAST_INSERT_ID() into @id;
				
				SELECT @id as last_id;
				
				-- Insert Log
				CALL sp_add_logmaster_information('1','Customer Template','customermaster',@id,createdby,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customer_additemmust` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customer_additemmust` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customer_additemmust`(
                    IN var_itemmustnumber   	BIGINT,
                    IN var_description     VARCHAR(50),
                    IN var_arbdescription	VARCHAR(50),
                    IN var_itemcode				text,                    
                    in var_created 				varchar(30),                    
                    in var_cnt 					int
    )
BEGIN
	DECLARE cnt INT DEFAULT 0;
	DECLARE rowcnt INT DEFAULT 0;	
	declare from_start int default 1;
	
	SELECT COUNT(*) INTO cnt FROM itemmustheader WHERE itemmustcode = var_itemmustnumber;
	
	IF cnt = 0 THEN
		INSERT INTO itemmustheader
			(itemmustdescription,
			arbitemmustdescription,			
			created,
			cdat)
		VALUES
		(var_description,
		var_arbdescription,		
		 var_created,
		 CURRENT_DATE());	
		
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS var_itemmustnumber;
		-- Insert Log
		
		CALL sp_add_logmaster_information('1','Item Must List','itemmustheader',@last_id,var_created,'Add');
		
	else
	
		update itemmustheader
			set itemmustdescription = var_description,
			arbitemmustdescription = var_arbdescription,
			modified = var_created,
			mdat = CURRENT_DATE()
		where itemmustcode = var_itemmustnumber;	
		
		set @last_id = var_itemmustnumber;		
		-- Insert Log
		
		CALL sp_add_logmaster_information('1','Item Must List','itemmustheader',@last_id,var_created,'Edit');
	
	end IF;
	
	while from_start <= var_cnt do		
		set @itemcode = split(var_itemcode,',',from_start);		
		SELECT COUNT(*) INTO rowcnt FROM itemmustdetail 
		WHERE itemmustcode = var_itemmustnumber AND itemcode = @itemcode;
	
		IF rowcnt > 0 THEN
			SELECT 'duplicate';
		ELSE
			INSERT INTO itemmustdetail
			(itemmustcode,
			itemcode)
			VALUES
			(var_itemmustnumber,
			 @itemcode			
			 );
			SELECT var_itemmustnumber;
		END IF;
		set from_start = from_start + 1;
	end while;	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_customer_routesequence` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_customer_routesequence` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_customer_routesequence`(		
		in route_code bigint,
		in cust_code  BIGINT,
		in createdby  varchar(50)
	)
BEGIN
		DECLARE week_type INT;
		declare from_start int default 1;		
		
		
		SELECT routesequenceplanflag INTO week_type FROM setup;	
    	
		if week_type = 1 then
			insert into routesequence (rp32weeknumber,routecode,customercode,callrestrictiondays1,
				callrestrictiondays2,callrestrictiondays3,callrestrictiondays4,callrestrictiondays5,
				callrestrictiondays6,callrestrictiondays7,monseq,tueseq,wedseq,thuseq,friseq,satseq,sunseq)
			values(9,route_code,cust_code,'1','1','1','1','1','1','1','1000','1000','1000','1000','1000','1000','1000');
			
			SELECT LAST_INSERT_ID() INTO @last_id;
			SELECT @last_id AS last_id;
			-- Insert Log
			CALL sp_add_logmaster_information('1','Customer','routesequence',@last_id,createdby,'Add');				  
		else
			while from_start <= 4 do
			
				INSERT INTO routesequence (rp32weeknumber,routecode,customercode,callrestrictiondays1,
					callrestrictiondays2,callrestrictiondays3,callrestrictiondays4,callrestrictiondays5,
					callrestrictiondays6,callrestrictiondays7,monseq,tueseq,wedseq,thuseq,friseq,satseq,sunseq)
				VALUES(from_start,route_code,cust_code,'1','1','1','1','1','1','1','1000','1000','1000','1000','1000','1000','1000');
							
				-- increment the value for getting next records.
				SET  from_start = from_start + 1;
				
				SELECT LAST_INSERT_ID() INTO @last_id;
				SELECT @last_id AS last_id;
				-- Insert Log
				CALL sp_add_logmaster_information('1','Customer','routesequence',@last_id,createdby,'Add');				  
			END WHILE;		
		end if;
		
		
	
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_index_addjourneycreditplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_index_addjourneycreditplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_index_addjourneycreditplan`(
	    IN var_customercode bigint(18),
	    IN var_routeids 	text,
	    IN var_credlimits 	text,
	    IN var_counter 		int(4),
	    in var_createdby 	varchar(50)
	)
BEGIN
	declare from_start 		int(4) default 1;
	declare route_code 		bigint(18);
	DECLARE credit_limit 	decimal(18,4);
	
	while from_start <= var_counter do 
	
		set route_code 		= split(var_routeids,'$',from_start);
		SET credit_limit 	= split(var_credlimits,'$',from_start);
		
		delete from journeyplancreditlimit where routecode = route_code and customercode = var_customercode;
		
		insert into journeyplancreditlimit 
				set customercode 	= var_customercode,
					routecode 		= route_code,
					creditlimit 	= credit_limit;
					
		SELECT LAST_INSERT_ID() INTO @id;
		-- Insert Log
		CALL sp_add_logmaster_information('1','Credit Journey Plan Limit','journeyplancreditlimit',@id,var_createdby,'Add'); 
	
		set from_start = from_start + 1;
	end while;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_index_addoutletproduct` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_index_addoutletproduct` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_index_addoutletproduct`(
	    IN gname VARCHAR(50),
	    IN arbgname VARCHAR(50),	    
	    IN `status` INT,
	    IN created_by VARCHAR(50)
	)
BEGIN
	
	INSERT INTO groupmaster(groupname,arbgroupname,created,cdat,activestatus)
	VALUES(gname,arbgname,created_by,CURRENT_DATE(),`status`);
		
	SELECT LAST_INSERT_ID() INTO @id;
	SELECT @id AS gcode;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Outlet Product Code','groupmaster',@id,created_by,'Add'); 
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_index_addoutletproductcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_index_addoutletproductcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_index_addoutletproductcode`(
	    IN group_code BIGINT,
	    IN item_code BIGINT,
	    IN outletitem_code VARCHAR(50),
	    in created_by VARCHAR(30)
	)
BEGIN
		
	SET @sel_qry = CONCAT("select count(*) INTO @c2 from outletitemcodes where groupcode = ",group_code," AND itemcode = ",item_code);
	PREPARE sel FROM @sel_qry;
	EXECUTE sel;		
	
	IF @c2 = 0 THEN
		INSERT INTO outletitemcodes(groupcode,itemcode,outletitemcode)VALUES(group_code,item_code,outletitem_code);
		
		SELECT LAST_INSERT_ID() into @gcode;
		SELECT 'insert' AS result,groupcode;
		-- Insert Log
		CALL sp_add_logmaster_information('1','Outlet Product Code','outletitemcodes',@gcode,created_by,'Add'); 
		
	ELSE 
		UPDATE outletitemcodes SET outletitemcode = outletitem_code WHERE itemcode = item_code AND groupcode = group_code;
		SELECT 'update' AS result; 
		
		select primary_key into @gcode from outletitemcodes WHERE itemcode = item_code AND groupcode = group_code;
		-- Insert Log
		CALL sp_add_logmaster_information('1','Outlet Product Code','outletitemcodes',@gcode,created_by,'Edit'); 
	END IF;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_index_addoutletproductcodegrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_index_addoutletproductcodegrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_index_addoutletproductcodegrid`(
		IN gname VARCHAR(50),
	    IN arbgname VARCHAR(50),
	    IN `status` INT,	    
	    IN item_code BIGINT,
	    IN outletitem_code VARCHAR(50),
	    in created_by VARCHAR(30)
	)
BEGIN
	-- insert in header table
	INSERT INTO groupmaster(groupname,arbgroupname,created,cdat,activestatus)
	VALUES(gname,arbgname,created_by,CURRENT_DATE(),`status`);
	
	SELECT LAST_INSERT_ID() INTO @id;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Outlet Product Code','groupmaster',@id,created_by,'Add'); 
		
	INSERT INTO outletitemcodes(groupcode,itemcode,outletitemcode)
	VALUES(@id,item_code,outletitem_code);
	
	SELECT 'insert' AS result,@id as lastid;
	
	SELECT LAST_INSERT_ID() INTO @gcode;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Outlet Product Code','outletitemcodes',@gcode,created_by,'Add'); 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_notes_addcreditnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_notes_addcreditnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_notes_addcreditnotecustomer`(
		IN var_routeid 			BIGINT(18),
		IN var_salesmancode 	BIGINT(18),
		IN var_customercode 	BIGINT(18),
		IN var_trantype 		INT,
		IN var_amount			DECIMAL(19,4),
		IN var_totalinvoceamt 	DECIMAL(19,4),
		IN var_remark1			VARCHAR(50),
		IN var_remark2			VARCHAR(50),
		IN var_invono 			TEXT,
		IN var_cntinvo 			INT,
		IN var_paymode 			INT,
		IN var_checknum			DECIMAL(18,0),
		IN var_checkdate 		VARCHAR(50),
		IN var_bankcode 		BIGINT(18),
		IN var_trandate 		VARCHAR(50),
		IN var_created 			VARCHAR(30),
		IN var_erprefnum 		VARCHAR(30),
		IN var_hdninvoamt 		TEXT,
		IN var_isfifo 			INT(1)
    )
BEGIN
		DECLARE docid BIGINT(18);		
		DECLARE curre_code BIGINT(18);
		DECLARE from_start INT DEFAULT 1;
		DECLARE invoice_no BIGINT(18);
		DECLARE var_invbal DECIMAL(18,4);
		DECLARE new_amtpaid DECIMAL(18,4);
		DECLARE totinvamt DECIMAL(18,4);
		DECLARE amtpaid DECIMAL(18,4);
		DECLARE invbal DECIMAL(18,4);
		DECLARE var_pdc_cash INT(1);
		
		SELECT getpdctocashstatus() INTO var_pdc_cash;
		
		-- Call this SP for convert null records into 0.
		CALL sp_edit_customer_balance_zero();
		
		SELECT get_default_currencycode_routecode(var_routeid) INTO curre_code;
		
		SET docid = CONCAT(var_routeid,"",get_acbodocseq_route(var_routeid));
		
		IF var_cntinvo > 1 THEN
			SELECT REPLACE(var_invono,'$',',') INTO @tran_ids;
		ELSE
			SELECT REPLACE(var_invono,'$','') INTO @tran_ids;
		END IF;	
		SET @q = CONCAT("SELECT SUM(totalinvoiceamount),SUM(amountpaid),SUM(invoicebalance)
				INTO @totalinvoiceamount,@amountpaid,@invoicebalance
				FROM customerinvoice WHERE transactionkey IN (",@tran_ids,")");
		PREPARE s1 FROM @q;
		EXECUTE s1;	
			
		INSERT INTO dcarheader SET
					documentnumber 		= docid,
					invoicenumber  		= docid,
					routecode			= var_routeid,
					salesmancode 		= var_salesmancode,
					customercode		= var_customercode,
					transactiontype		= var_trantype,
					paymenttype			= var_trantype,
					amountpaid			= var_amount,
					totalinvoiceamount  = @totalinvoiceamount,
					invoicebalance 		= (@totalinvoiceamount-var_amount),
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					transactiontime 	= TIME(CURRENT_DATE()),
					remarks1			= var_remark1,
					remarks2			= var_remark2,
					erpreferencenumber  = var_erprefnum,
					created 			= var_created,
					modified 			= var_created,
					cdat 				= CURRENT_DATE(),
					mdat 				= CURRENT_DATE(),
					currencycode 		= curre_code,
					pdcstatus 			= var_paymode;
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		
		SELECT update_acbodocseq_route(var_routeid);
		
		-- set abs on var_amount
		SET var_amount = ABS(var_amount);
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Credit Note (Customer)','dcarheader',@last_id,var_created,'Add');
		
		
		-- Insert Record in dcarcashcheckdetail
		IF var_paymode = 0 OR var_pdc_cash = 1 THEN
			INSERT INTO dcarcashcheckdetail SET			
					transactionkey		= @last_id,
					typecode 			= var_paymode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		ELSEIF var_paymode = 1 AND var_pdc_cash = 0	THEN			
			INSERT INTO dcarcashcheckdetail SET
					transactionkey		= @last_id,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		ELSE
			INSERT INTO dcarcashcheckdetail SET
					transactionkey		= @last_id,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		END IF;
		
		WHILE from_start <= var_cntinvo DO
		
			IF var_amount IS NOT NULL OR var_isfifo = 0 THEN
				
				SET @trankey = split(@tran_ids,',',from_start);
				
				SELECT invoicenumber,totalinvoiceamount,amountpaid,invoicebalance 
					INTO invoice_no ,totinvamt,amtpaid,invbal
					FROM customerinvoice WHERE transactionkey = @trankey;
					
				-- check fifo condifion
				IF var_isfifo = 1 AND SIGN(invbal) = -1 THEN
					SET @invoamt = ABS(invbal);
				ELSEIF var_isfifo = 1 AND from_start > 1 THEN
					SET @invoamt = var_amount;
				ELSE
					SET @invoamt = split(var_hdninvoamt,'$',from_start);
				END IF;
				SET new_amtpaid = '';
				SET var_invbal	= 0.0000;
				
				IF 	ABS(@invoamt) > ABS(invbal) THEN
					SET new_amtpaid = invbal;
				ELSE
					SET new_amtpaid = @invoamt;
					SET var_invbal  = (invbal-@invoamt);
				END IF;
				
				-- update balance in customermaster
				IF var_paymode = 0 OR var_pdc_cash = 1 THEN	
					-- update balance in headofficecode of customermaster
					SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = var_customercode;
					IF var_customercode != @headofficecode THEN 
						UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode = @headofficecode;
					END IF;
					UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode = var_customercode;
				END IF;
				
				-- Insert Record in dcardetail
				INSERT INTO dcardetail SET
							transactionkey		= @last_id,
							customercode 		= var_customercode,
							invoicenumber   	= invoice_no,
							totalinvoiceamount  = totinvamt,
							amountpaid 			= new_amtpaid,
							invoicebalance 		= var_invbal,
							paymentmode 		= var_paymode,
							invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
							currencycode 		= curre_code;
				
				IF var_paymode = 0 OR var_pdc_cash = 1 THEN 
					-- Update Record in customerinvoice
					UPDATE customerinvoice SET
							cnamountpaid			= cnamountpaid+new_amtpaid,
							amountpaid 				= (amtpaid+new_amtpaid),
							invoicebalance			= invoicebalance-new_amtpaid
							WHERE invoicenumber 	= invoice_no;				
				ELSE
					UPDATE customerinvoice SET
							pdcindicator 			= 1,
							pdcbalance 				= pdcbalance+new_amtpaid,
							pdcdate 				= STR_TO_DATE(var_checkdate,'%d-%m-%Y')
							WHERE invoicenumber 	= invoice_no;
				END IF;
				
				-- SELECT amtpaid,new_amtpaid,var_invbal;
				
				SET  var_amount = (var_amount-new_amtpaid);
				IF var_amount = 0 AND var_isfifo = 1 THEN
					SET var_cntinvo	= 0;
				END IF;				
			END IF;
			SET from_start = from_start + 1;
		END WHILE;
		IF var_amount > 0 THEN
			SELECT update_advpayment_customer_balance(var_customercode,var_amount);			
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_notes_addcreditnoteroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_notes_addcreditnoteroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_notes_addcreditnoteroute`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),		
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	VARCHAR(50),
		IN var_created 		VARCHAR(30),
		IN var_erpreferencenumber VARCHAR(50)
    )
BEGIN
		DECLARE docid BIGINT(18);
		
		-- Call this SP for convert null records into 0.
		CALL sp_edit_customer_balance_zero();
		
		SET docid = CONCAT(var_routeid,"",get_acbodocseq_route(var_routeid));
		INSERT INTO dcarheader SET
					documentnumber 		= docid,
					invoicenumber  		= docid,
					currencycode  		= get_default_currencycode(),
					routecode			= var_routeid,
					salesmancode 		= var_salesmancode,
					customercode		= 0,
					transactiontype		= var_trantype,
					totalinvoiceamount  = var_amount,
					amountpaid			= var_amount,
					invoicebalance 		= 0,
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					remarks1			= var_remark1,
					remarks2			= var_remark2,
					erpreferencenumber  = var_erpreferencenumber,
					transactiontime 	= TIME(CURRENT_DATE()),
					mdat 				= CURRENT_DATE(),
					cdat 				= CURRENT_DATE(),
					created 			= var_created,
					modified 			= var_created;
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		
		-- update routebalance in routemaster
		UPDATE routemaster SET routebalance = routebalance-var_amount WHERE routecode = var_routeid;
		
		SELECT update_acbodocseq_route(var_routeid);
			
		-- Insert Log
		CALL sp_add_logmaster_information('1','Credit Note (Route)','dcarheader',@last_id,var_created,'Add');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_notes_adddebitnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_notes_adddebitnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_notes_adddebitnotecustomer`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),
		IN var_customercode BIGINT(18),
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_invoicecombo BIGINT(28),
		IN var_trandate 	VARCHAR(50),
		IN var_created 		VARCHAR(30),
		IN var_erprefnum 	VARCHAR(30)
    )
BEGIN
		DECLARE docid BIGINT(18);		
		DECLARE curre_code BIGINT(18);
		DECLARE totalinvoceamt DECIMAL(19,4) DEFAULT 0.0000;
				
		-- Call this SP for convert null records into 0.
		CALL sp_edit_customer_balance_zero();
		
		SET docid = CONCAT(var_routeid,"",get_acbodocseq_route(var_routeid));
		
		-- SELECT currencycode INTO curre_code FROM currencymaster WHERE defaultcurrency;
		SELECT get_default_currencycode_routecode(var_routeid) INTO curre_code;
		
		SELECT sum(totalinvoiceamount) INTO totalinvoceamt FROM customerinvoice WHERE invoicenumber = var_invoicecombo;
		
		SELECT get_paymentcode_currencycode(var_customercode) INTO @pay_term;
		
		INSERT INTO dcarheader SET
					documentnumber 		= docid,
					invoicenumber  		= docid,		
					routecode			= var_routeid,
					salesmancode 		= var_salesmancode,
					customercode		= var_customercode,
					transactiontype		= 3,
					paymenttype			= @pay_term,
					transactiontime 	= TIME(CURRENT_DATE())	,
					amountpaid			= var_amount,
					totalinvoiceamount  = totalinvoceamt,
					invoicebalance 		= 0,
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					remarks1			= var_remark1,
					remarks2			= var_remark2,
					erpreferencenumber  = var_erprefnum,
					created 			= var_created,
					modified 			= var_created,
					cdat 				= CURRENT_DATE(),
					mdat 				= CURRENT_DATE(),
					currencycode 		= curre_code;
					-- pdcstatus 			= var_paymode;
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;	
		SELECT update_acbodocseq_route(var_routeid);
		
		-- update balance in customermaster
		UPDATE customermaster SET balance = balance+var_amount WHERE customercode = var_customercode;
		-- update balance in headofficecode of customermaster
		SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = var_customercode;
		IF var_customercode != @headofficecode THEN 
			UPDATE customermaster SET balance = balance+var_amount WHERE customercode = @headofficecode;
		END IF;	
		
		-- Insert Record in dcardetail
		INSERT INTO dcardetail SET
					transactionkey		= @last_id,
					customercode 		= var_customercode,
					invoicenumber    	= var_invoicecombo,
					totalinvoiceamount  = totalinvoceamt,
					amountpaid 			= var_amount,
					invoicebalance 		= 0,
					invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					currencycode 		= curre_code;			
				
		-- Update Record in customerinvoice
		UPDATE customerinvoice SET
				dnamountpaid			= dnamountpaid+var_amount,				
				totalinvoiceamount 		= totalinvoceamt,
				invoicebalance			= (invoicebalance+var_amount)
				WHERE invoicenumber 	= var_invoicecombo;
			
		-- Insert Log
		CALL sp_add_logmaster_information('1','Debit Note (Customer)','dcarheader',@last_id,var_created,'Add');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_notes_adddebitnoteroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_notes_adddebitnoteroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_notes_adddebitnoteroute`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),		
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	VARCHAR(50),
		IN var_created 		VARCHAR(30),
		IN var_erpreferencenumber VARCHAR(50)
    )
BEGIN
		DECLARE docid BIGINT(18);
		
		-- Call this SP for convert null records into 0.
		CALL sp_edit_customer_balance_zero();
		
		SET docid = CONCAT(var_routeid,"",get_acbodocseq_route(var_routeid));
		INSERT INTO dcarheader SET
					documentnumber 		= docid,
					invoicenumber  		= docid,		
					routecode			= var_routeid,
					salesmancode 		= var_salesmancode,
					customercode		= 0,
					transactiontype		= 3,
					transactiontime 	= TIME(CURRENT_DATE())	,
					totalinvoiceamount  = var_amount,
					amountpaid			= var_amount,
					invoicebalance 		= 0,
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					remarks1			= var_remark1,
					remarks2			= var_remark2,
					mdat 				= CURRENT_DATE(),
					cdat 				= CURRENT_DATE(),
					created 			= var_created,
					modified 			= var_created,
					currencycode 		= get_default_currencycode(),
					erpreferencenumber  = var_erpreferencenumber					
					;
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		SELECT update_acbodocseq_route(var_routeid);
		
		-- update routebalance in routemaster
		update routemaster set routebalance = routebalance+var_amount where routecode = var_routeid;
			
		-- Insert Log
		CALL sp_add_logmaster_information('1','Debit Note (Route)','dcarheader',@last_id,var_created,'Add');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_salesman_addsalesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_salesman_addsalesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_salesman_addsalesman`(
		IN alt_code VARCHAR(50),
	    IN salesman_name VARCHAR(50),
	    IN arbsalesman_name VARCHAR(50),
	    IN msg_key INT,
	    IN salesman_type INT,
	    IN parent_company INT,
	    IN user_name VARCHAR(50),
	    IN pwd VARCHAR(50),
	    IN salesman_status CHAR(1),
	    IN var_contactnumber VARCHAR(50),
	    IN created_by VARCHAR(50)
	)
BEGIN
	
	INSERT INTO salesman  SET 	alternatesalesmancode 	= alt_code,
									salesmanname1 			= salesman_name,
									salesmanname2 			= var_contactnumber,
									arbsalesmanname1 		= arbsalesman_name,
									messagekey 				= msg_key,
									`type` 					= salesman_type,
									parentcompany 			= parent_company,
									`username` 				= user_name,
									`userpassword` 			= pwd,
									activestatus 			= salesman_status,
									created 				= created_by,
									pricingkey 				= NULL,
									cdat 					= CURRENT_DATE(),
									mdat 					= CURRENT_DATE();
									
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	CALL sp_add_logmaster_information('1','Salesman','salesman',@last_id,created_by,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_salesman_salesmanmsg` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_salesman_salesmanmsg` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_salesman_salesmanmsg`(
	   IN msg_desc 		VARCHAR(50),
	   IN msg_line1 	VARCHAR(40),
	   IN msg_line2 	VARCHAR(40),
	   IN msg_line3 	VARCHAR(40),
	   IN msg_line4 	VARCHAR(40),
	   IN arbmsg_line1 	VARCHAR(40),
	   IN arbmsg_line2 	VARCHAR(40),
	   IN arbmsg_line3 	VARCHAR(40),
	   IN arbmsg_line4 	VARCHAR(40),
	   IN msg_status	INT(4),
	   IN createdby 	VARCHAR(30),
	   IN altcode 		VARCHAR(50)
	)
BEGIN	
	
	INSERT INTO salesmanmessages  SET
									alternatecode 			= altcode,
									messagedescription		= msg_desc,
									message1 				= msg_line1,
									message2 				= msg_line2,
									message3 				= msg_line3,
									message4 				= msg_line4,
									arbmessageline1			= arbmsg_line1,
									arbmessageline2 		= arbmsg_line2,
									arbmessageline3			= arbmsg_line3,
									arbmessageline4			= arbmsg_line4,
									activestatus			= msg_status,
									created					= createdby,
									cdat					= CURRENT_DATE(),
									mdat					= CURRENT_DATE();
									
	SELECT LAST_INSERT_ID() into @id;
	select @id as last_id;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Salesman Messages','salesmanmessages',@id,createdby,'Add');
			
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_settlement_addcashreceipt` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_settlement_addcashreceipt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_settlement_addcashreceipt`(
		IN route_code 		BIGINT(18),
	    IN salesman_code 	BIGINT(18),
	    IN cash_amt 		DECIMAL(18,4),
	    IN rec_amt 			DECIMAL(18,4),
	    IN chq_amt 			DECIMAL(18,4),
	    IN total_amt 		DECIMAL(18,4),
	    IN tran_date 		TEXT,
	    IN bank_code 		BIGINT(18),
	    IN slip_no 			VARCHAR(30),
	    IN createdby 		VARCHAR(30)	
	)
BEGIN
	DECLARE ih_trankey 		TEXT;
	DECLARE cnt_ih_trankey 	INT(11);
	DECLARE ah_trankey 		TEXT;
	DECLARE cnt_ah_trankey 	INT(11);
	DECLARE from_start 		INT DEFAULT 1;
	DECLARE tran_key 		BIGINT(28);
	DECLARE cnt_record 		INT(4) DEFAULT 0;
	declare docnumber 		bigint;
	
	SET tran_date = STR_TO_DATE(tran_date,'%d-%m-%Y');
	
	-- Get transactionkey from invoiceheader & arheader table.
	SELECT GROUP_CONCAT(ih.transactionkey),COUNT(*) INTO ih_trankey,cnt_ih_trankey FROM invoiceheader AS ih
		LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
		WHERE ih.paymenttype IN(0,4) AND ccd.typecode IN(0,1) AND ccd.transactiontype = 1 
		AND routecode = route_code AND salesmancode = salesman_code AND transactiondate = tran_date ;
	
	SELECT GROUP_CONCAT(ah.transactionkey),COUNT(*) INTO ah_trankey,cnt_ah_trankey FROM arheader AS ah
		LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
		WHERE 1 =1 AND ccd.typecode IN(0,1) AND ccd.transactiontype = 2 AND routecode = route_code 
		AND salesmancode = salesman_code AND transactiondate = tran_date;
		
	-- Now on the basis of the ih_trankey and ah_trankey we fetch the detail of the transaction key save into table.
	-- Now we start to insert record from the invoiceheader.
	INSERT INTO cashierreceiptheader SET
										tobankcode 		= bank_code,
										slipno 			= slip_no,
										paymentdate		= tran_date,
										routecode 		= route_code,
										salesmancode 	= salesman_code,
											cashamount 	= cash_amt,
										receiptamount 	= rec_amt,
											checkamount = chq_amt,
												total 	= total_amt,
												`date`  = tran_date;
		SELECT LAST_INSERT_ID() INTO @lastid;
		
		SET docnumber = CONCAT(route_code,LPAD(@lastid,5,'0'));
		
		UPDATE cashierreceiptheader SET documentnumber = docnumber
									WHERE primary_key = @lastid;
		
	-- Now we start to while loop to insert record from the invoicedetail.
	WHILE from_start <= cnt_ih_trankey DO
		SET tran_key = NULL;
		SET tran_key = split(ih_trankey,',',from_start);
		
		SET @ins1 = CONCAT("INSERT INTO cashierreceiptdetails (transactionno,transactiondate,`type`,slipno,checkno,checkdate,bankcode,invoiceamount,
											paid,balance,routecode,salesmancode,`date`,pdcbalance,checkamount,checkstatus,
											paymenttype,routekey,visitkey,transactionkey,documentnumber,customercode)
										SELECT ih.invoicenumber,ih.transactiondate,ccd.typecode,'",slip_no,"',ccd.checknumber,ccd.checkdate,",bank_code,",
											ih.totalinvoiceamount,ih.amountpaid,ih.invoicebalance,",route_code,",",salesman_code,",'",tran_date,"',0,
											ccd.amount,ccd.chequestatusindicator,ccd.paymenttype,ih.routekey,ih.visitkey,ih.transactionkey,",docnumber,",ih.customercode
											FROM invoiceheader AS ih
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
											WHERE ih.transactionkey = ",tran_key);
 		PREPARE s1 FROM @ins1;
 	 	EXECUTE s1;		
		-- Counter
		SET from_start = from_start + 1;
	END WHILE;
	
	-- Reset the counter.
	SET from_start = 1;
	
	-- Now we start to while loop to insert record from the arheader.
	WHILE from_start <= cnt_ah_trankey DO
		SET tran_key = NULL;
		SET tran_key = split(ah_trankey,',',from_start);	
		
		
		SET @ins2 = CONCAT("INSERT INTO cashierreceiptdetails 
										(transactionno,transactiondate,`type`,slipno,checkno,checkdate,bankcode,invoiceamount,paid,balance,
										 routecode,salesmancode,`date`,pdcbalance,checkamount,checkstatus,paymenttype,routekey,visitkey,
										 transactionkey,documentnumber,customercode)
										 
										 SELECT ah.invoicenumber,ah.transactiondate,ccd.typecode,'",slip_no,"',ccd.checknumber,ccd.checkdate,",bank_code,",
											ah.totalinvoiceamount,ccd.amount,ah.invoicebalance,",route_code,",",salesman_code,",'",tran_date,"',0,
											ccd.amount,paymenttype,ccd.chequestatusindicator,ah.routekey,ah.visitkey,ah.transactionkey,",docnumber,",ah.customercode
											FROM arheader AS ah
											LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
											WHERE ah.transactionkey = ",tran_key);
 		PREPARE s1 FROM @ins2;
 		EXECUTE s1;
		-- Counter		
		SET from_start = from_start + 1;		
	END WHILE; 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_account_settlement_addpdcgrid_1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_account_settlement_addpdcgrid_1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_account_settlement_addpdcgrid_1`(
		IN route_code BIGINT(18),
	    IN salesman_code BIGINT(18),
	    IN tran_date VARCHAR(50),
	    IN bank_code BIGINT(18),
	    IN erprefno VARCHAR(50),
	    IN remark VARCHAR(50),	    
	    IN bank_date TEXT,
	    IN hdntrancode TEXT,
	    IN hdncnttrancode INT(4),	    
	    IN createdby VARCHAR(30),
	    IN bankrefno VARCHAR(50)
	)
BEGIN
	
	DECLARE tran_key BIGINT(28);
	DECLARE from_start INT(11) DEFAULT 1;	
	DECLARE invoice_no BIGINT(20);
	DECLARE tbl_type VARCHAR(10);
	DECLARE tmp_str VARCHAR(500);
	
	DECLARE cnt_inv INT DEFAULT 0;
	DECLARE invnumbers TEXT;
	DECLARE from_inner_start INT(11) DEFAULT 1;	
	
	SET tran_date = STR_TO_DATE(tran_date,'%d-%m-%Y');
	
	WHILE from_start <= hdncnttrancode DO
	
		SET tmp_str 	= split(hdntrancode,'$',from_start);
		SET tran_key 	= split(tmp_str,'_',1);
		SET tbl_type 	= split(tmp_str,'_',2);
	
		IF tbl_type = 'ah' THEN
		
				SELECT 	ah.transactiondate,ah.customercode,checknumber,checkdate,bankcode,amount,ah.invoicenumber,ah.totalinvoiceamount,ah.amountpaid,ah.invoicebalance
				INTO	@transactiondate,@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@invoicenumber,@totalinvoiceamount,@amountpaid,@invoicebalance 
				FROM arheader AS ah
				LEFT JOIN cashcheckdetail AS cd ON cd.routekey = ah.routekey AND cd.visitkey = ah.visitkey
				WHERE ah.transactionkey = tran_key; 
								
				UPDATE cashcheckdetail ccd	
				LEFT OUTER JOIN arheader AS ah ON ccd.routekey = ah.routekey AND ccd.visitkey = ah.visitkey
				SET ccd.checkstatus = 1 ,typecode = 0 WHERE ah.transactionkey = tran_key;
				
				-- reset value of the customerinvoice after pdc clear sr
				UPDATE customerinvoice ci INNER JOIN ardetail ad ON ad.invoicenumber = ci.invoicenumber
				SET  	ci.invoicebalance = ci.invoicebalance - ad.pdcbalance,
					ci.amountpaid = ci.amountpaid + ad.pdcbalance,
					ci.pdcbalance = ci.pdcbalance - ad.pdcbalance 
				WHERE ad.transactionkey = tran_key;
				
				
				-- Insert record in pdcclearenceheader.
				INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
														routecode 			= route_code,
														salesmancode 		= salesman_code,
														customercode 		= @customercode,
														chequeno 			= @chequeno,
														chequedate 			= @chequedate,
														bankcode 			= @bankcode,
														chequeamount		= @chequeamount,
														chequeclearedbank	= bank_code,
														erpreferencenumber	= erprefno,
														remarks 			= remark,
														bankreferenceno 	= bankrefno,
														chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
				SELECT LAST_INSERT_ID() INTO @last_id;
				SELECT @last_id AS last_id;
				
				-- Insert Log
				CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
				
				-- Insert record in pdcclearencedetail.
				INSERT INTO pdcclearencedetail (transactionkey,invoicenumber,invoiceddate,totalinvoiceamount,invoicebalance,amountpaid,pdcamount) 
				SELECT @last_id,ad.invoicenumber,ad.invoicedate,ad.totalinvoiceamount,ad.invoicebalance,ad.amountpaid,ad.pdcbalance FROM ardetail ad where ad.transactionkey = tran_key;	
				
				-- reset value of the customerinvoice after pdc clear sr	
				UPDATE customerinvoice ci INNER JOIN ardetail ad ON ad.invoicenumber = ci.invoicenumber
				SET  pdcindicator=0, 
					pdcdate='0000-00-00'
				WHERE ci.pdcbalance = 0 AND ad.transactionkey = tran_key;
				-- Update pdcamount as 0.
			 	UPDATE ardetail SET pdcbalance = 0 WHERE transactionkey = tran_key;
				
				UPDATE customermaster SET balance = (SELECT sum(invoicebalance) from customerinvoice where customercode=@customercode) WHERE customercode = @customercode;
				
	
		ELSEIF tbl_type = 'ih' THEN
		
			SELECT 	ih.transactiondate,ih.customercode,checknumber,checkdate,bankcode,amount,ih.invoicenumber,ih.totalinvoiceamount,ih.amountpaid,ih.invoicebalance,ih.amountpaid 
			INTO	@transactiondate,@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@invoicenumber,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance 
			FROM invoiceheader ih
			LEFT JOIN cashcheckdetail AS ccd ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
			WHERE ih.transactionkey = tran_key;
			-- Update pdcamount as 0.
			UPDATE ardetail SET pdcbalance = 0 WHERE transactionkey = tran_key;
			
			UPDATE cashcheckdetail ccd	
				LEFT OUTER JOIN invoiceheader AS ih ON ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey
				SET ccd.checkstatus = 1 
				WHERE ih.transactionkey = tran_key;
				
			-- Insert record in pdcclearenceheader.
			INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
													routecode 			= route_code,
													salesmancode 		= salesman_code,
													customercode 		= @customercode,
													chequeno 			= @chequeno,
													chequedate 			= @chequedate,
													bankcode 			= @bankcode,
													chequeamount		= @chequeamount,
													chequeclearedbank	= bank_code,
													erpreferencenumber	= erprefno,
													remarks 			= remark,
													bankreferenceno 	= bankrefno,
													chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
			SELECT LAST_INSERT_ID() INTO @last_id;
			SELECT @last_id AS last_id;
			-- Insert Log
			CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
			
			-- Insert record in pdcclearencedetail.
			INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
													invoicenumber 		= @invoicenumber,
													invoiceddate		= @transactiondate,
													totalinvoiceamount	= @totalinvoiceamount,
													invoicebalance 		= @invoicebalance,
													amountpaid 			= @amountpaid,
													pdcamount			= @pdcbalance;
			
			
			-- reset value of the customerinvoice after pdc clear
			SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = @invoicenumber;
			UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
			WHERE transactionkey = @tran_key;
			
			SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = @tran_key;
			IF @latestpdcbal = 0 THEN 			
				UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
			END IF;
			
			-- update customer balance
			UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
		
		ELSEIF tbl_type = 'be' THEN
			
					SELECT  bh.customercode,bc.checknumber,DATE_FORMAT(bc.checkdate,"%d-%m-%Y") AS checkdate,bc.bankcode,bc.amount,bc.transactionkey
					INTO	@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@transactionkey
					FROM bearheader AS bh						
						LEFT JOIN bearcashcheckdetail AS bc ON bc.transactionkey = bh.transactionkey			
						WHERE bh.transactionkey = tran_key;
						
					-- Update paymenttype in bearheader table
					UPDATE bearheader SET pdcstatus	= 2 WHERE transactionkey = tran_key;
			
					-- Update paymenttype in beardetail table
					UPDATE beardetail SET paymentmode = 0 WHERE transactionkey = tran_key;			
					-- Update checkstatus in bearcashcheckdetail
					UPDATE bearcashcheckdetail SET checkstatus = 1 WHERE transactionkey = @transactionkey;
					
					-- Update pdcamount as 0.
					-- UPDATE ardetail SET pdcbalance = 0 WHERE transactionkey = tran_key;
					-- Insert record in pdcclearenceheader.
					INSERT INTO pdcclearenceheader  SET 	transactiondate 	= CURRENT_DATE(),
															routecode 			= route_code,
															salesmancode 		= salesman_code,
															customercode 		= @customercode,
															chequeno 			= @chequeno,
															chequedate 			= @chequedate,
															bankcode 			= @bankcode,
															chequeamount		= @chequeamount,
															chequeclearedbank	= bank_code,
															erpreferencenumber	= erprefno,
															remarks 			= remark,
															bankreferenceno 	= bankrefno,
															chequeclearedon 	= STR_TO_DATE(bank_date,'%d-%m-%Y');
					SELECT LAST_INSERT_ID() INTO @last_id;
					SELECT @last_id AS last_id;
					-- Insert Log
					CALL sp_add_logmaster_information('1','PDC Cheque','pdcclearenceheader',@last_id,createdby,'Add');
					
					SELECT COUNT(*),GROUP_CONCAT(invoicenumber) INTO cnt_inv,invnumbers FROM beardetail WHERE transactionkey = tran_key;
					
					SET from_inner_start = 1;
					WHILE from_inner_start <= cnt_inv DO
					
						SET invoice_no = split(invnumbers,',',from_inner_start);
						
						SELECT DATE_FORMAT(bh.transactiondate,"%d-%m-%Y") AS transactiondate,bd.totalinvoiceamount,bd.amountpaid,bd.invoicebalance,bd.amountpaid AS pdcbalance
						INTO	@transactiondate,@totalinvoiceamount,@amountpaid,@invoicebalance,@pdcbalance
						FROM bearheader AS bh
						LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
						WHERE bd.transactionkey = tran_key AND bd.invoicenumber = invoice_no;
						
						-- Insert record in pdcclearencedetail.
					
							INSERT INTO pdcclearencedetail SET 		transactionkey		= @last_id,
																	invoicenumber 		= invoice_no,
																	invoiceddate		= @transactiondate,
																	totalinvoiceamount	= @totalinvoiceamount,
																	invoicebalance 		= @invoicebalance,
																	amountpaid 			= @amountpaid,
																	pdcamount			= @pdcbalance;
							
							-- reset value of the customerinvoice after pdc clear
							SELECT transactionkey,pdcbalance INTO @tran_key,@pdcbal FROM customerinvoice WHERE invoicenumber = invoice_no;
							UPDATE customerinvoice SET  invoicebalance=invoicebalance-@pdcbal,amountpaid=amountpaid+@pdcbal,pdcbalance = pdcbalance-@pdcbal
							WHERE transactionkey = @tran_key;
							
							SELECT pdcbalance INTO @latestpdcbal FROM customerinvoice WHERE transactionkey = @tran_key;
							IF @latestpdcbal = 0 THEN 			
								UPDATE customerinvoice SET pdcindicator=0,pdcdate = ''WHERE transactionkey = @tran_key;
							END IF;
							
							-- update customer balance
							UPDATE customermaster SET balance = balance-@pdcbal WHERE customercode = @customercode;
					
						SET from_inner_start = from_inner_start + 1;
					END WHILE;
					
			ELSEIF tbl_type = 'dc' THEN
			
					SELECT dh.customercode,dc.checknumber,DATE_FORMAT(dc.checkdate,"%d-%m-%Y") AS checkdate,dc.bankcode,dc.amount,dc.transactionkey
					INTO	@customercode,@chequeno,@chequedate,@bankcode,@chequeamount,@transactionkey
					FROM dcarheader AS dh						
						LEFT JOIN dcarcashcheckdetail AS dc ON dc.transactionkey = dh.transactionkey			
						WHERE dd.transactionkey = tran_key AND dc.invoicenumber = invoice_no;
					
					-- Update paymenttype in bearheader table
