/* Procedure structure for procedure `sp_add_admin_security_adduser` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_adduser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_adduser`(
	    IN var_code VARCHAR(50),
	    IN var_username VARCHAR(50),
	    IN var_password VARCHAR(30),
	    IN var_usertypeid BIGINT,
	    IN var_accesstypeid BIGINT,
	    in var_selectionids text,
	    IN createdby VARCHAR(30)
	)
BEGIN
	DECLARE var_userID INT;
	select count(*) into @cnt from usermaster where username = `var_username`;
	
	if @cnt = 0 then 
		INSERT INTO usermaster(`username`,`password`,`usertypeid`,`accesstypeid`)
		VALUES(var_username,var_password,var_usertypeid,var_accesstypeid);
		
		select LAST_INSERT_ID() into @lastid;
		select @lastid as lastid;
		-- Insert Log
		CALL sp_add_logmaster_information('1','User Master','usermaster',@lastid,createdby,'Add');
		
		Set var_userID = (Select userid FROM usermaster where username = var_username and `password` = var_password);
		-- APN added 30/03/2015 to add userdetail based on usertype selected
		CALL sp_add_admin_usertype_userdetail(var_username, var_usertypeid, var_userID); 
		-- Insert Into useraccesscodes table.
		call sp_add_admin_security_adduseraccesscode(var_username,var_accesstypeid,var_selectionids);
		
	else
		SELECT 0 AS lastid;		
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_security_adduseraccesscode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_adduseraccesscode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_adduseraccesscode`(		
	in user_name varchar(50),
	IN intaccesstype int(4),
    IN intselectcode text
    )
begin
		if intaccesstype = 1 then -- company
		
			DELETE FROM useraccesscodes WHERE username = user_name AND cmpycode > 0;
			set @ins_qry = concat("insert into useraccesscodes(username,cmpycode,countrycode,depotcode,areacode,subareacode,regionmstcode)
				select '",user_name,"', co.cmpycode,cm.countrycode,dm.depotcode,am.areacode ,sam.subareacode,rm.regionmstcode 
				from company co 
				left outer join country cm on cm.cmpycode = co.cmpycode 
				left outer join regionmaster rm on rm.countrycode  =cm.countrycode   
				left outer join depotmaster dm on dm.regionmstcode = rm.regionmstcode
				left outer join areamaster am on am.depotcode = dm.depotcode
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where co.cmpycode in (",intselectcode,")");
			-- select @ins_qry;
			prepare s1 from @ins_qry;
			execute s1;
		elseif	intaccesstype = 2 then -- country
		
			DELETE FROM useraccesscodes WHERE username = user_name AND countrycode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,countrycode,depotcode,areacode,subareacode,regionmstcode)
				select '",user_name,"', cm.countrycode,dm.depotcode,am.areacode,sam.subareacode,rm.regionmstcode 
				from country cmpycode
				left outer join regionmaster rm on rm.countrycode  =cm.countrycode  
				left outer join depotmaster dm on dm.regionmstcode = rm.regionmstcode
				left outer join areamaster am on am.depotcode = dm.depotcode
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where cm.countrycode IN (",intselectcode,")");
			-- select @ins_qry;
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		 elseif intaccesstype = 3 THEN -- region
		 
			DELETE FROM useraccesscodes WHERE username = user_name AND regionmstcode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,depotcode,areacode,subareacode,regionmstcode)
				select '",user_name,"',dm.depotcode,am.areacode ,sam.subareacode,rm.regionmstcode  
				from regionmaster rm  
				left outer join depotmaster dm on dm.regionmstcode = rm.regionmstcode 
				left outer join areamaster am on am.depotcode = dm.depotcode
				left outer join subareamaster sam on sam.areacode = am.areacode	
				where rm.regionmstcode IN (",intselectcode,")");
			-- select @ins_qry;
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		elseif intaccesstype = 4 THEN -- branch/depot
		
			DELETE FROM useraccesscodes WHERE username = user_name AND depotcode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,depotcode,areacode,subareacode)
				select '",user_name,"' ,dm.depotcode,am.areacode,sam.subareacode 
				from  depotmaster dm 
				left outer join areamaster am on am.depotcode = dm.depotcode 
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where  dm.depotcode IN (",intselectcode,")");
			-- select @ins_qry;
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		elseif intaccesstype = 5  THEN --  area
		
			DELETE FROM useraccesscodes WHERE username = user_name AND areacode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,areacode,subareacode)
				select '",user_name,"',am.areacode,sam.subareacode
				from  areamaster am  
				left outer join subareamaster sam on sam.areacode = am.areacode 
				where am.areacode IN (",intselectcode,")");
			-- select @ins_qry;
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		elseif intaccesstype = 6  THEN --  subarea
		
			DELETE FROM useraccesscodes WHERE username = user_name AND subareacode > 0;
			SET @ins_qry = CONCAT("insert into useraccesscodes(username,subareacode)
				select '",user_name,"' , sam.subareacode  from subareamaster sam 
				where  sam.subareacode IN (",intselectcode,")");
			-- select @ins_qry;
			PREPARE s1 FROM @ins_qry;
			EXECUTE s1;
		end	if;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_security_addusertype` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_security_addusertype` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_security_addusertype`(
	    IN `code` VARCHAR(50),
	    IN `name` VARCHAR(50),
	    IN adminid VARCHAR(30),
	    in `status` varchar(1),
	    IN createdby VARCHAR(30)
	)
BEGIN	
	INSERT INTO user_type(id,user_type,is_admin,`status`)
	VALUES(`code`,`name`,adminid,`status`);
	/*03/30/2015 - APN Added as usertypedetail is based on this table*/
	INSERT INTO usertype(usertypeid, usertypename)
	VALUES(`code`,`name`);
	-- Insert Log
	CALL sp_add_logmaster_information('1','User Type','user_type',`code`,createdby,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_admin_usertype_userdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_admin_usertype_userdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_admin_usertype_userdetail`(
IN var_username varchar(50),
IN var_usertypeid BIGINT,
IN var_userid BIGINT
)
BEGIN
	/* CREATED BY: ALVIN P. NAMUAG
	   CREATE DATE: 30/03/2015
	   COMMENT: Assign user priviledge based on usertype */
	DECLARE intReadData INT;
	DECLARE intUpdateData INT;
	DECLARE intInsertData INT;
	DECLARE intDeleteData INT;
	DECLARE intAllPermissions INT;
	DECLARE intModuleID INT;
	DECLARE intFormID INT;
	DECLARE no_more_rows INT DEFAULT 0;
	DECLARE lst_usertypedetail CURSOR FOR 
		SELECT readdata, updatedata, insertdata, deletedata, allpermissions, moduleid,formid 
		FROM usertypedetail WHERE usertypeid = var_usertypeid;
	DECLARE CONTINUE HANDLER FOR NOT FOUND
	    SET no_more_rows = 1;
	
	-- delete userdetail to replace with new one
	DELETE FROM userdetail WHERE userid = var_userid; 
	
	OPEN lst_usertypedetail;
	the_loop: LOOP
	
	FETCH lst_usertypedetail INTO
	intReadData,intUpdateData,intInsertData,intDeleteData,intAllPermissions, intModuleID, intFormID;
	IF no_more_rows = 1 THEN
	   LEAVE the_loop;
	END IF;
	
		
	INSERT INTO userdetail(username, readdata, insertdata, updatedata, deletedata, allpermissions, moduleid, formid, userid)
	VALUES(var_username,intReadData,intInsertData,intUpdateData,intDeleteData,intAllPermissions, intModuleID, intFormID,var_userid);
	END LOOP the_loop;
	
	CLOSE lst_usertypedetail;
    END */$$
DELIMITER ;

