/* Procedure structure for procedure `sp_add_basic_reason_addbadreturn` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_basic_reason_addbadreturn` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_basic_reason_addbadreturn`(		
	   IN description VARCHAR(50),
	   IN arbdescription VARCHAR(50),
	   in createdby varchar(30),
	   IN altcode VARCHAR(50)
	)
BEGIN
	INSERT INTO expiryreturnreasons  SET 	description 	= description,
											arbdescription 	= arbdescription,
											hhcdescription 	= '',
											alternatecode 	= altcode,
