/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_index_items`(
		    IN var_actualitemcode         BIGINT,
                    IN var_anitemcode             VARCHAR(50),
                    IN var_itemgroupcode          DECIMAL(18,0),
                    IN var_alternatecode          VARCHAR(50),
                    IN var_itemshortdescription   VARCHAR(50),
                    IN var_warehousestock         DECIMAL(18,0),
