/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_pos_addcustomerposlimit`(
					IN var_customercode BIGINT,
					IN var_poslimit INT(11),
					in var_created varchar(30)
					)
BEGIN
    
		INSERT INTO customerposlimit SET customercode 	= var_customercode,
										poslimit 		= var_poslimit,
										posbalance 		= var_poslimit,
										created 		= var_created,
										cdat 			= CURRENT_DATE(),
										modified 		= var_created,
										mdat 			= CURRENT_DATE();
										
		
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS result;
		-- Insert Log
		CALL sp_add_logmaster_information('1','Customer POS Limit','customerposlimit',@last_id,var_created,'Add');
		
    END */$$
