/* Procedure structure for procedure `sp_add_inventory_pos_addcustomerposlimitgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_pos_addcustomerposlimitgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_pos_addcustomerposlimitgrid`(
			IN var_customercode   	bigint(20),
			IN var_itemcode      	bigint(20),
			IN var_quantity   		DECIMAL(18,0),
			IN var_serialnumber     VARCHAR(20),
			in var_created 			VARCHAR(50)
		)
BEGIN
		SELECT primary_key,posbalance INTO @pk,@posbal FROM customerposlimit WHERE customercode = var_customercode;
		-- check if posbal is greater than Zero then or not if yes then it will be save data.
		
		if @posbal > 0 then
	
			SELECT COUNT(*) into @counter FROM customerposinventory WHERE serialnumber = var_serialnumber AND itemcode = 
			(
				SELECT itemcode FROM posmaster WHERE inventorytype = 1 AND itemcode = var_itemcode
			) and customercode = var_customercode;
			
			if @counter = 0 then 
				
				if var_serialnumber != '' then 
					set var_quantity = 1;		
				end if;
				
				INSERT INTO customerposinventory SET customercode 	= var_customercode,
													itemcode		= var_itemcode,
													quantity		= var_quantity,
													serialnumber	= var_serialnumber,
													created 		= var_created,
													cdat 			= CURRENT_DATE(),
													modified 		= var_created,
													mdat 			= CURRENT_DATE();
				
				
				-- Change / Update the posbalance			
				UPDATE 	customerposlimit SET posbalance = (posbalance-1) WHERE primary_key = @pk;			
				select posbalance from customerposlimit WHERE primary_key = @pk;
				
			else				
				select 'Duplicate' as result;
			end if;			
		else		
			SELECT 'Empty' AS result;		
		end if;
		
    END */$$
DELIMITER ;

