/* Procedure structure for procedure `sp_add_inventory_routestartday_addroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_routestartday_addroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_routestartday_addroute`(
IN var_route_code INT,
IN var_date VARCHAR(30)
)
BEGIN
	DECLARE var_salesmancode INT;
	DECLARE in_last_insert_id INT;
	
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_route_code;
	
	SELECT rm.subareacode,sam.supervisorcode,sam.areacode,am.areamanagercode,am.depotcode,dm.branchmanagercode,
		   dm.cmpycode,co.nationalsalesmanagercode,rm.amountdecimaldigits
	into   @subareacode,@supervisorcode,@areacode,@areamanagercode,@depotcode,@branchmanagercode,
		   @cmpycode,@nationalsalesmanagercode,@amountdecimaldigits
	FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm,company co
	
	WHERE sam.subareacode = rm.subareacode AND am.areacode = sam.areacode AND dm.depotcode = am.depotcode
		  AND co.cmpycode = dm.cmpycode AND rm.routecode = var_route_code;
    
	
	INSERT INTO startendday set 	salesmancode = var_salesmancode,
									routecode = var_route_code,
									routestartdate = STR_TO_DATE(var_date,'%d-%m-%Y'),
									routestarttime = TIME(CURRENT_DATE()),
									areacode = @areacode,
									areamanagercode = @areamanagercode,
									branchmanagercode = @branchmanagercode,
									cmpycode = @cmpycode,
									currencycode = @amountdecimaldigits,
									depotcode=@depotcode,
									nationalsalesmanagercode=@nationalsalesmanagercode,
									subareacode=@subareacode,
									supervisorcode=@supervisorcode;
	SELECT LAST_INSERT_ID() INTO in_last_insert_id;
	
	DELETE FROM batchmaster WHERE routekey = in_last_insert_id;
	
  END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_target_additempackage` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_target_additempackage` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_target_additempackage`(
	    IN var_packagedescription varchar(50),
		IN var_arbpackagedescription varchar(50),
		in var_activestatus int(4),
		in var_alternatecode varchar(50),
		IN var_created varchar(50)
	)
BEGIN
	
	INSERT INTO itempackagemaster SET 
				packagedescription 		= var_packagedescription,
				alternatecode 			= var_alternatecode,
				arbpackagedescription 	= var_arbpackagedescription,
				activestatus 			= var_activestatus,
				created 				= var_created,
				modified 				= var_created,
				mdat 					= CURRENT_DATE(),
				cdat 					= CURRENT_DATE(); 
		
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Item Package','itempackagemaster',@last_id,var_created,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_target_additionalbarcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_target_additionalbarcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_target_additionalbarcode`(
		IN var_itemcode bigint(20),
		IN var_barcode3 varchar(20),
		IN var_barcode4 varchar(20),
		IN var_barcode5 varchar(20),
		IN var_barcode6 varchar(20),
		IN var_barcode7 varchar(20),
		IN var_barcode8 varchar(20),
		IN var_barcode9 varchar(20),
		IN var_barcode10 varchar(20),
		in var_created VARCHAR(50)
	)
BEGIN
		declare cnt int;
		
		select count(itemcode) into cnt from itembarcodes where itemcode = var_itemcode;
		
		if cnt = 0 then 
	
			INSERT INTO itembarcodes SET 
							    itemcode 	= var_itemcode,
								barcode3 	= var_barcode3,
								barcode4 	= var_barcode4,
								barcode5 	= var_barcode5,
								barcode6 	= var_barcode6,
								barcode7 	= var_barcode7,
								barcode8 	= var_barcode8,
								barcode9 	= var_barcode9,
								barcode10 	= var_barcode10,
								created 	= var_created,
								modified 	= var_created,
									cdat 	= CURRENT_DATE(),
									mdat 	= CURRENT_DATE(); 
		
			SELECT LAST_INSERT_ID() INTO @last_id;
			SELECT @last_id AS last_id;
			-- Insert Log
			CALL sp_add_logmaster_information('1','Additional Bar Code','itembarcodes',@last_id,var_created,'Add');
		else
			select '0' as last_id;
		end if;
		
		CALL sp_combo_itemmaster();
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_target_addquota` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_target_addquota` */;

