/* Procedure structure for procedure `sp_add_inventory_target_addsalesmantarget` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_target_addsalesmantarget` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_target_addsalesmantarget`(
				IN var_routecode BIGINT(18),
				IN var_salesmancode BIGINT(18),
				IN var_packagenumber BIGINT(18),
				IN var_fromdate VARCHAR(50),
				IN var_todate	VARCHAR(50),
				IN var_quantity DECIMAL(18,4),
				IN var_chkiscase INT(4),
				IN var_ttype INT(4),
				IN var_commision DECIMAL(18,4),
				IN var_insentper DECIMAL(18,4),
				IN var_insentamt DECIMAL(18,4)
	)
BEGIN
	
	-- query for checking duplicate record.
	-- SELECT COUNT(*) INTO @counter FROM routegoal WHERE salesmancode = var_salesmancode AND packagenumber = var_packagenumber AND mmonth = var_mmonth;
	
	SELECT COUNT(*) INTO @counter FROM routegoal WHERE salesmancode = var_salesmancode AND routecode = var_routecode AND targettype = var_ttype AND packagenumber = var_packagenumber AND ((fromdate BETWEEN STR_TO_DATE(var_fromdate,'%d-%m-%Y') AND STR_TO_DATE(var_todate,'%d-%m-%Y') ) OR (todate BETWEEN STR_TO_DATE(var_fromdate,'%d-%m-%Y') AND STR_TO_DATE(var_todate,'%d-%m-%Y')));
	
	IF @counter = 0 THEN -- if record is exist or not.
	
		IF var_chkiscase = 1 THEN 		
			
			SELECT unitspercase INTO @upc FROM itemmaster WHERE packagecode = var_packagenumber GROUP BY unitspercase;
			
			IF @upc > 0 THEN 
				SET var_quantity = (var_quantity * @upc);				
			END IF;
		
		END IF;
		
		SET @qry  = CONCAT("INSERT INTO routegoal SET 	routecode = ",var_routecode,",
									salesmancode = ",var_salesmancode,",
									packagenumber = ",var_packagenumber,",
									quantity = ",var_quantity,",
									targettype = ",var_ttype,",
									commision = ",var_commision,",
									insentive = ",var_insentamt,",
									insentivepercent = ",var_insentper,",
									fromdate = STR_TO_DATE('",var_fromdate,"','%d-%m-%Y'),
									todate = STR_TO_DATE('",var_todate,"','%d-%m-%Y'),
									cdat = CURRENT_DATE(),
									mdat = CURRENT_DATE()");
		SELECT @qry;
		PREPARE s1 FROM @qry;
		EXECUTE	s1;							
			
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS last_id;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Salesman Target','routegoal',@last_id,'','Add');
	ELSE
		SELECT 'Duplicate' AS last_id;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_adddepotdamageexpiry` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_adddepotdamageexpiry` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_adddepotdamageexpiry`(
			IN var_depotcode BIGINT,
			IN var_refno VARCHAR(50),
			IN var_trandate VARCHAR(30),
			IN var_fromdate VARCHAR(30),
			IN var_todate VARCHAR(30),
			IN var_itemcode BIGINT,
			IN var_pieces INT,
			IN var_cases INT,
			IN var_batchnumber VARCHAR(20),
			IN var_expirydate VARCHAR(30),
			IN var_upc DECIMAL(18,4),
			IN var_reasoncode INT,
			IN var_headerid BIGINT
		)
BEGIN
		DECLARE var_quantity BIGINT;
		DECLARE counter INT DEFAULT 0;
		DECLARE stockcounter INT DEFAULT 0;
		DECLARE var_depotinventorykey BIGINT;
		
		
		SELECT FLOOR(var_cases*var_upc)+(var_pieces) INTO var_quantity;
		
		IF var_headerid = 0 THEN 
		
			INSERT INTO depotdamageexpiryheader SET 
						transactiondate 	= CURRENT_DATE(),
						depotcode 			= var_depotcode,
						referenceno 		= var_refno,
						fromdate 			= STR_TO_DATE(var_fromdate,'%d-%m-%Y'),
						todate 				= STR_TO_DATE(var_todate,'%d-%m-%Y');
			SELECT LAST_INSERT_ID() INTO var_headerid; 
		
		ELSEIF var_depotcode > 0 THEN
			
			UPDATE depotdamageexpiryheader SET 
						transactiondate 	= CURRENT_DATE(),
						depotcode 			= var_depotcode,
						referenceno 		= var_refno,
						fromdate 			= STR_TO_DATE(var_fromdate,'%d-%m-%Y'),
						todate 				= STR_TO_DATE(var_todate,'%d-%m-%Y')
				WHERE 	headerid			= var_headerid;
			
		END IF;	
		
		SELECT IFNULL(COUNT(*),0) INTO counter FROM depotdamageexpirydetail 
				WHERE headerid 	= var_headerid AND actualitemcode = var_itemcode;
		
		IF var_headerid > 0 AND var_itemcode > 0 AND counter = 0 THEN
		
			SET @q1 = CONCAT("INSERT INTO depotdamageexpirydetail SET
									headerid 			= ",var_headerid,",
									actualitemcode 		= ",var_itemcode,",
									depotqty 			= ",var_quantity,",
									batchno 			= '",var_batchnumber,"',
									reasoncode 			= ",var_reasoncode,",
									expirydate  		= STR_TO_DATE('",var_expirydate,"','%d-%m-%Y')");
			PREPARE s1 FROM @q1;
			EXECUTE s1;
		
				-- check below query for depotstock
				SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(depotinventorykey) INTO stockcounter,var_depotinventorykey
					FROM depotstock WHERE itemcode = var_itemcode AND batchno = var_batchnumber 
						AND expirydate  = STR_TO_DATE(var_expirydate,'%d-%m-%Y')
						AND depotcode 	= var_depotcode;
										
				IF stockcounter = 0 THEN 
					IF var_reasoncode = 1 THEN -- damageqty
						INSERT INTO depotstock SET
								itemcode 			= var_itemcode,
								damagedqty 			= var_quantity,
								depotcode 			= var_depotcode,
								batchno 			= var_batchnumber,
								expirydate  		= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
					ELSE -- expiryqty
						INSERT INTO depotstock SET
								itemcode 			= var_itemcode,
								expiryqty 			= var_quantity,
								depotcode 			= var_depotcode,
								batchno 			= var_batchnumber,
								expirydate  		= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
					
					END IF;
				ELSE
					IF var_reasoncode = 1 THEN -- damageqty
						UPDATE depotstock SET
								damagedqty 			= var_quantity,
								quantity 			= quantity - var_quantity
						WHERE   depotinventorykey   = var_depotinventorykey;
					ELSE -- expiryqty
						UPDATE depotstock SET
								expiryqty 			= var_quantity,
								quantity 			= quantity - var_quantity
						WHERE   depotinventorykey   = var_depotinventorykey; 
					
					END IF;				
				END IF;	
				SELECT var_headerid AS lastid;
		ELSE
				SELECT 'Duplicate' AS dupli,var_headerid AS lastid;
		END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_adddepotinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_adddepotinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_adddepotinventory`(
			IN var_fromdepotcode BIGINT,
			IN var_todepotcode BIGINT,
			in var_trandate varchar(30),
			IN var_itemcode BIGINT,
			in var_pieces int,
			in var_cases int,
			IN var_batchnumber VARCHAR(20),
			IN var_expirydate VARCHAR(30),
			in var_upc DECIMAL(18,4),
			in var_depotinvkey bigint
		)
BEGIN
		DECLARE var_quantity BIGINT;
		declare counter int default 0;
		
		select floor(var_cases*var_upc)+(var_pieces) into var_quantity;
		
		if var_depotinvkey = 0 then 
		
			insert into depotinventoryheader set transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
												 fromdepot 			= var_fromdepotcode,
												 todepot 			= var_todepotcode;
			select LAST_INSERT_ID() into var_depotinvkey; 
			
		elseif var_fromdepotcode > 0 then
			
			update depotinventoryheader SET transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
											 fromdepot 			= var_fromdepotcode,
											 todepot 			= var_todepotcode
										where depotinvtranskey	= var_depotinvkey;	 
			
		end if;	
		
		SELECT ifnull(COUNT(*),0) INTO counter FROM depotinventorydetails 
				WHERE depotinvtranskey 	= var_depotinvkey AND itemcode = var_itemcode
				and batchno = var_batchnumber and date(expirydate) = STR_TO_DATE(var_expirydate,'%d-%m-%Y');
				
		if var_depotinvkey > 0 and var_itemcode > 0 and counter = 0 then
		
				INSERT INTO depotinventorydetails SET
						depotinvtranskey 	= var_depotinvkey,
						itemcode 			= var_itemcode,
						quantity 			= var_quantity,
						batchno 			= var_batchnumber,
						depotcode 			= var_todepotcode,
						expirydate  		= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
						
				
						
				SELECT var_depotinvkey AS lastid;
		else
				SELECT 'Duplicate' AS dupli,var_depotinvkey AS lastid;
		end if;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_addgrn` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_addgrn` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_addgrn`(
			IN var_fromdepotcode BIGINT,
			IN var_todepotcode BIGINT,
			in var_trandate varchar(30),
			IN var_remark varchar(200),
			IN var_itemcode BIGINT,
			IN var_relcases INT,
			in var_relpieces int,
			IN var_holdcases INT,
			IN var_holdpieces INT,
			IN var_batchnumber VARCHAR(20),
			IN var_expirydate VARCHAR(30),
			in var_upc DECIMAL(18,4),
			in var_created varchar(50),
			in var_grheaderid bigint
		)
BEGIN
		DECLARE var_relquantity BIGINT;
		DECLARE var_holdquantity BIGINT;
		declare counter int default 0;
		
		select centralwh into @centralwh from depotmaster where depotcode = var_fromdepotcode;
		
		-- check duplication
		select count(*) into counter from tbldepotstock 
			where depotcode 	= var_todepotcode AND 
					itemcode  	= var_itemcode AND
					batchno 	= var_batchnumber AND 
					expirydate 	= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
		
		if counter = 0 then 
			select floor(var_relcases*var_upc)+(var_relpieces) into var_relquantity;
			SELECT FLOOR(var_holdcases*var_upc)+(var_holdpieces) INTO var_holdquantity;
			
			if var_grheaderid = 0 then 
			
				insert into tblgrheader set `date` 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
										 fromdepot 	= var_fromdepotcode,
										 remark 	= var_remark,
										 todepot 	= var_todepotcode,
										 cdat 		= CURRENT_DATE(),
										 mdat 		= CURRENT_DATE(),
										 created 	= var_created,
										 modified 	= var_created;
				select LAST_INSERT_ID() into var_grheaderid;
							
			elseif var_grheaderid > 0 then
				
				update tblgrheader SET `date` 			= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
										 fromdepot 		= var_fromdepotcode,
										 todepot 		= var_todepotcode,
										 remark 		= var_remark,
										 mdat 			= CURRENT_DATE(),
										 modified 		= var_created
								where 	grheaderid		= var_grheaderid;
			end if;
		
			INSERT INTO tblgrdetail SET
							grheaderid 		= var_grheaderid,
							itemcode 		= var_itemcode,
							relquantity 	= var_relquantity,
							hldquantity 	= var_holdquantity,
							batchno 		= var_batchnumber,
							expirydate		= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
			set counter = 0;
			SELECT IFNULL(COUNT(*),0) INTO counter FROM tbldepotstock 
					WHERE depotcode 	= var_fromdepotcode AND
						  itemcode  	= var_itemcode AND
						  batchno 		= var_batchnumber AND 
						  expirydate 	= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
						  
			if counter > 0 and @centralwh = 0 then
					UPDATE tbldepotstock SET
							avlquantity = (avlquantity - var_relquantity),
							hldquantity = (hldquantity - var_holdquantity)
					WHERE 	depotcode 	= var_fromdepotcode AND 
							itemcode  	= var_itemcode AND
							batchno 	= var_batchnumber AND 
							expirydate 	= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
			end if;
			
			SET counter = 0;
			SELECT IFNULL(COUNT(*),0) INTO counter FROM tbldepotstock 
					WHERE depotcode 	= var_todepotcode AND 
						  itemcode  	= var_itemcode AND
						  batchno 		= var_batchnumber AND 
						  expirydate 	= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
						  
			IF counter = 0 THEN
							INSERT INTO tbldepotstock SET
							depotcode 			= var_todepotcode,
							itemcode 			= var_itemcode,
							avlquantity 		= var_relquantity,
							hldquantity 		= var_holdquantity,
							batchno 			= var_batchnumber,
							expirydate			= STR_TO_DATE(var_expirydate,'%d-%m-%Y');
							
					SELECT var_grheaderid AS lastid;
			else
					UPDATE tbldepotstock SET
							avlquantity = (avlquantity + var_relquantity),
							hldquantity = (hldquantity + var_holdquantity)
					WHERE 	depotcode 	= var_todepotcode AND 
							itemcode  	= var_itemcode AND
							batchno 	= var_batchnumber AND 
							expirydate 	= STR_TO_DATE(var_expirydate,'%d-%m-%Y');					
			end if;
			
		else
		
			SELECT 'Duplicate' AS dupli,var_grheaderid AS lastid;
			
		end if;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_addrouteitemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_addrouteitemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_addrouteitemgroup`(
			IN var_description 		VARCHAR(30),
			IN var_itemgroupcode    bigint,
			in var_transferstatus 	int,
			IN var_itemcode 		TEXT,
			IN var_counter			INT,
			in var_diff 			text,
			in var_diffcnt 			int,
			IN var_created			VARCHAR(30)
			
    )
BEGIN
		INSERT INTO routeitemgrp set
					description		= var_description,
					itemgroupcode 	= var_itemgroupcode,
					transferstatus	= var_transferstatus;
					
		select LAST_INSERT_ID() into @var_routeitemgrpcode;
		
		CALL sp_add_inventory_transaction_addrouteitemgroupmapping(var_itemcode,var_counter,@var_routeitemgrpcode,var_diff,var_diffcnt,var_created);
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Route Item Grouping','routeitemgrp',@var_routeitemgrpcode,var_created,'Add');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_addrouteitemgroupmapping` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_addrouteitemgroupmapping` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_addrouteitemgroupmapping`(
			IN var_itemcode     	text,
			IN var_counter        	INT,
			IN var_routeitemgrpcode	BIGINT,
			in var_diff 			text,
			in var_diffcnt 			int,
			IN var_created			VARCHAR(30)
    )
BEGIN
		declare from_start int;	
		set from_start = 1;
		
		/*set @q1 = concat("DELETE FROM routeitemmapping WHERE routeitemgrpcode = ",var_routeitemgrpcode," and itemcode in (",var_diff,")");
		prepare s1 from @q1;
		execute	s1;*/
		
		DELETE FROM routeitemmapping WHERE routeitemgrpcode = var_routeitemgrpcode;
		
		IF var_diffcnt > 0 THEN 
			-- Insert Log
			CALL sp_add_routeitemgrouplog_information(var_diffcnt,'Route Item Mapping','routeitemmapping',var_routeitemgrpcode,var_diff,var_created,'Delete');
		END IF;
		
		
		WHILE from_start <= var_counter DO 
		
			SET @def_itemcode = '';
			SET @def_itemcode = split(var_itemcode,',',from_start);
			
			INSERT INTO routeitemmapping SET	itemcode			= @def_itemcode,
												routeitemgrpcode	= var_routeitemgrpcode;
			SET from_start = from_start + 1;
			
		END WHILE;
		
   END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_dailysalesmanloadgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_dailysalesmanloadgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_dailysalesmanloadgrid`(
			IN var_itemcode BIGINT,
			IN var_routecode BIGINT,			
			IN var_cases INT(4),
			IN var_upc INT(4),
			IN var_units INT(4),
			IN var_salesmancode BIGINT ,			
			IN var_salesprice DECIMAL(28,15),
			IN var_batchnumber VARCHAR(20),
			IN var_expirydate VARCHAR(30),
			IN var_caseprice DECIMAL(18,2),
			IN var_date VARCHAR(30),
			IN var_load INT(4),
			IN var_batchstatus INT(4),
			in var_erpreferencenumber varchar(30),
			in var_retprice decimal(19,4),
			IN var_retcaseprice DECIMAL(19,4),
			in var_depotinvstatus int(4)
		)
BEGIN
	
	DECLARE var_quantity BIGINT;
	
	IF var_batchstatus > 0 THEN 
		SET @qry = CONCAT("select count(*) into @val from startingloaddetail 
					where loadperiodnumber = ",var_load," and routecode = ",var_routecode," and batchnumber	= '",var_batchnumber,"' 
					and itemcode = ",var_itemcode," and ddate = STR_TO_DATE('",var_date,"','%d-%m-%Y')");	
	ELSE
		SET @qry = CONCAT("select count(*) into @val from startingloaddetail 
					where loadperiodnumber = ",var_load," and routecode = ",var_routecode," 
					and itemcode = ",var_itemcode," and ddate = STR_TO_DATE('",var_date,"','%d-%m-%Y')");
	END IF;
	
	
	PREPARE s2 FROM @qry;
	EXECUTE s2;
		
	IF @val = 0  THEN 
	
		SELECT FLOOR(var_cases*var_upc)+(var_units) INTO var_quantity;
		
		if var_depotinvstatus = 14 then
			update depotstock set quantity = quantity - var_quantity
				where itemcode = var_itemcode and batchno = var_batchnumber 
					and depotcode = get_depotcode_routecode(var_routecode)
					and expirydate = STR_TO_DATE(var_expirydate,'%d-%m-%Y');
		elseif var_depotinvstatus = 64 THEN
			UPDATE tbldepotstock SET
					avlquantity = (avlquantity - var_quantity),
					hldquantity = (hldquantity - var_quantity)
			WHERE 	itemcode = var_itemcode AND batchno = var_batchnumber 
					AND depotcode = get_depotcode_routecode(var_routecode)
					AND expirydate = STR_TO_DATE(var_expirydate,'%d-%m-%Y');
		end if;
		
		SET @dyn = CONCAT("insert into  startingloaddetail SET
										itemcode 	= ",var_itemcode,",
										routecode 	= ",var_routecode,",
										cases 		= ",var_cases," ,
										upc			= ",var_upc,",
										units 		= ",var_units,",
										salesmancode= ",var_salesmancode," ,
										salesprice  = ",var_salesprice,",
										batchnumber	= '",var_batchnumber,"' ,
										expirydate	=  STR_TO_DATE('",var_expirydate,"','%d-%m-%Y'),
										caseprice	= ",var_caseprice,",
										warehouse	= '0',
										warehousestock = '0',
										currencycode= '0',
										status		= '0',
										returnprice	= '",var_retprice,"',
										rcvdtotunits= '0',
										suggtotunits	= '0',
										totunits		= ",(var_cases*var_upc)+var_units,",
										loadtime 		= CURRENT_TIME(),										
										returncaseprice	= ",var_retcaseprice,",
										loadperiodnumber = '",var_load,"',
										erpreferencenumber = '",var_erpreferencenumber,"',
										ddate		= STR_TO_DATE('",var_date,"','%d-%m-%Y'),
										transactiondate	= STR_TO_DATE('",var_date,"','%d-%m-%Y')");
		-- select 			@dyn;
		PREPARE s1 FROM @dyn;
		EXECUTE s1;
		SELECT LAST_INSERT_ID() AS result;
	ELSE
		SELECT 'Duplicate' AS result;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_dailysalesmanload_ordertoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_dailysalesmanload_ordertoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_dailysalesmanload_ordertoload`(
	IN var_loaddetailcode TEXT,
	IN table_name VARCHAR(100),
	IN selected_date VARCHAR(50),
	IN var_load INT,
	IN var_routecode BIGINT,
	IN var_allowcases TEXT,
	IN var_allowpieces TEXT,
	IN var_batchno TEXT,
	IN var_expirydate TEXT,
	IN var_totrecord INT	
	)
BEGIN
 	
    -- we have paste same sp_get_inventory_transaction_dailysalesmanload_qtyinfo_depot sp here
    -- because temporary table is only use in same sp that's why
    DECLARE var_selected_date DATE; 
 	DECLARE var_ids TEXT;
 	DECLARE from_loop_start INT DEFAULT 1;
 	DECLARE var_primarykey BIGINT;
 	
 	DECLARE tmp_cases BIGINT;
 	DECLARE tmp_pieces BIGINT;
 	DECLARE tmp_batchno VARCHAR(100);
 	DECLARE tmp_ddate VARCHAR(50);
 	
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,SUM(salesqty) FROM salesorderdetail AS sod
		LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		WHERE DATE(soh.orderdeliverydate) = (STR_TO_DATE(selected_date,"%d-%m-%Y")) AND routecode = var_routecode
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  SELECT STR_TO_DATE(selected_date,"%d-%m-%Y") INTO var_selected_date;
  
   IF table_name != '' THEN 
   
		DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
   
	  SET @qtmp = CONCAT("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
	  PREPARE s1 FROM @qtmp;
	  EXECUTE s1;
	  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;		
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		SELECT COUNT(itemcode) INTO main_cnt FROM salesorderdetail AS sod
			LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
			WHERE DATE(soh.orderdeliverydate) = var_selected_date AND routecode = var_routecode
			GROUP BY itemcode ORDER BY itemcode;
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;
	
	END IF;
	
	SELECT  REPLACE(var_loaddetailcode,'_',',') INTO var_ids;
	
	IF table_name = 'depotstock' THEN 
		INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,batchnumber,expirydate,mdat
			)
			SELECT sod.itemcode,routecode,var_selected_date,var_load,IF(FLOOR(sod.salesqty/im.unitspercase) > IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),FLOOR(sod.salesqty/im.unitspercase)) AS cases,
			caseprice,IF(IFNULL((sod.salesqty%im.unitspercase),0) > IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL((sod.salesqty%im.unitspercase),0)) AS units,
			((IF(FLOOR(sod.salesqty/im.unitspercase) > IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),FLOOR(sod.salesqty/im.unitspercase))*im.unitspercase)+IF(IFNULL((sod.salesqty%im.unitspercase),0) > IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL((sod.salesqty%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),soh.salesmancode,defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,soh.currencycode,ds.batchno,ds.expirydate,CURRENT_DATE()
			FROM salesorderdetail AS sod
			LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
			LEFT JOIN itemmaster AS im ON im.actualitemcode = sod.itemcode
			LEFT JOIN depotstock AS ds ON ds.depotcode = get_depotcode_routecode(soh.routecode) AND ds.itemcode = sod.itemcode
			WHERE DATE(soh.orderdeliverydate) = var_selected_date AND sod.primary_key  IN (var_ids);
			
	ELSEIF	table_name = 'tbldepotstock' THEN 
	
		INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,salesmancode,salesprice,returnprice,returncaseprice,
			transactiondate,currencycode,batchnumber,expirydate,mdat
			)
			SELECT sod.itemcode,routecode,var_selected_date,var_load,IF(FLOOR(sod.salesqty/im.unitspercase) > IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),FLOOR(sod.salesqty/im.unitspercase)) AS cases,
			caseprice,IF(IFNULL((sod.salesqty%im.unitspercase),0) > IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL((sod.salesqty%im.unitspercase),0)) AS units,
			((IF(FLOOR(sod.salesqty/im.unitspercase) > IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),FLOOR(sod.salesqty/im.unitspercase))*im.unitspercase)+IF(IFNULL((sod.salesqty%im.unitspercase),0) > IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL((sod.salesqty%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),soh.salesmancode,defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,soh.currencycode,ds.batchno,ds.expirydate,CURRENT_DATE()
			FROM salesorderdetail AS sod
			LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		    LEFT JOIN itemmaster AS im ON im.actualitemcode = sod.itemcode
		    LEFT JOIN tbldepotstock AS ds ON ds.depotcode = get_depotcode_routecode(soh.routecode) AND ds.itemcode = sod.itemcode
			WHERE DATE(soh.orderdeliverydate) = var_selected_date AND sod.primary_key  IN (var_ids);
	ELSE
		
		SELECT REPLACE(var_allowcases,'_',',') 	INTO var_allowcases;
		SELECT REPLACE(var_allowpieces,'_',',') INTO var_allowpieces;
		SELECT REPLACE(var_batchno,'_',',') 	INTO var_batchno;
		SELECT REPLACE(var_expirydate,'_',',') 	INTO var_expirydate;
		
		WHILE from_loop_start <= var_totrecord DO
			SELECT split(var_ids,',',from_loop_start) INTO var_primarykey;			
			SELECT split(var_allowcases,',',from_loop_start) INTO tmp_cases;
			SELECT split(var_allowpieces,',',from_loop_start) INTO tmp_pieces;
			SELECT split(var_batchno,',',from_loop_start) INTO tmp_batchno;
			SELECT split(var_expirydate,',',from_loop_start) INTO tmp_ddate;
			
			INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,mdat,batchnumber,expirydate
			)
			SELECT itemcode,routecode,var_selected_date,var_load,			
			IF(FLOOR(sod.salesqty/im.unitspercase) > IFNULL(FLOOR(tmp_cases/upc),0),IFNULL(FLOOR(tmp_cases/upc),0),FLOOR(sod.salesqty/im.unitspercase)) AS cases,caseprice,
			IF(IFNULL((sod.salesqty%im.unitspercase),0) > IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL((sod.salesqty%im.unitspercase),0)) AS units,
			((IF(FLOOR(sod.salesqty/im.unitspercase) > IFNULL(FLOOR(tmp_cases/upc),0),IFNULL(FLOOR(tmp_cases/upc),0),FLOOR(sod.salesqty/im.unitspercase))*upc)+IF(IFNULL((sod.salesqty%im.unitspercase),0) > IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL((sod.salesqty%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),soh.salesmancode,defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,soh.currencycode,CURRENT_DATE(),tmp_batchno,STR_TO_DATE(tmp_ddate,'%d-%m-%Y')
			FROM salesorderdetail AS sod
			LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		    LEFT JOIN itemmaster AS im ON im.actualitemcode = sod.itemcode		    
			WHERE DATE(soh.orderdeliverydate) = var_selected_date AND sod.primary_key = var_primarykey;
			
			SET from_loop_start = from_loop_start + 1;
	   END WHILE;
	
	END IF;	
	
	SELECT LAST_INSERT_ID() AS lastid;
	
	IF table_name = 'depotstock' THEN
			UPDATE depotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.quantity = ds.quantity - ((cases*upc)+units)
				WHERE sld.ddate = CURRENT_DATE();
		ELSEIF table_name = 'tbldepotstock' THEN
			UPDATE tbldepotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.avlquantity = ds.avlquantity - ((cases*upc)+units)
				WHERE sld.ddate = CURRENT_DATE();
		END IF;
	-- drop temporary table
	DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_dailysalesmanload_previousday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_dailysalesmanload_previousday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_dailysalesmanload_previousday`(
	IN var_loaddetailcode TEXT,
	IN table_name VARCHAR(100),
	IN selected_date VARCHAR(50),
	IN var_load INT,
	IN var_routecode BIGINT,
	IN var_allowcases TEXT,
	IN var_allowpieces TEXT,
	IN var_batchno TEXT,
	IN var_expirydate TEXT,
	IN var_totrecord INT	
	)
BEGIN 	
 	DECLARE var_ddate DATE;
 	DECLARE var_selected_date DATE; 
 	DECLARE var_ids TEXT;
 	DECLARE from_loop_start INT DEFAULT 1;
 	DECLARE var_primarykey BIGINT;
 	
 	DECLARE tmp_cases BIGINT;
 	DECLARE tmp_pieces BIGINT;
 	DECLARE tmp_batchno VARCHAR(100);
 	DECLARE tmp_ddate VARCHAR(50);
 	
 	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
	DECLARE var_batchnumber VARCHAR(50);
	DECLARE var_expirydate VARCHAR(50);
	
  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,SUM((cases*upc)+units) AS quantity,batchnumber,expirydate  FROM startingloaddetail AS sld
		WHERE DATE(ddate) = DATE_SUB(DATE(STR_TO_DATE(selected_date,"%d-%m-%Y")),INTERVAL 1 DAY)
		AND routecode = var_routecode AND loadperiodnumber = var_load GROUP BY itemcode,batchnumber,expirydate ORDER BY itemcode;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  SELECT DATE_SUB(DATE(STR_TO_DATE(selected_date,"%d-%m-%Y")),INTERVAL 1 DAY) INTO var_ddate;
  SELECT STR_TO_DATE(selected_date,"%d-%m-%Y") INTO var_selected_date;
  
  IF table_name != '' THEN 
	  SET @qtmp = CONCAT("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
	  PREPARE s1 FROM @qtmp;
	  EXECUTE s1;
	  OPEN cur1;
			SELECT FOUND_ROWS() INTO num_rows;
			main_loop: LOOP	
			IF no_more_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
				IF counter > num_rows THEN
					CLOSE cur1;
					LEAVE main_loop;
				END IF;
			END IF;
			FETCH cur1 INTO var_main_itemcode,var_reqquantity,var_batchnumber,var_expirydate;
			SELECT COUNT(itemcode) INTO main_cnt FROM startingloaddetail AS sld
			WHERE DATE(ddate) = var_ddate AND routecode = var_routecode AND loadperiodnumber = var_load
			AND itemcode = var_main_itemcode
 			GROUP BY itemcode ORDER BY itemcode;
				SET from_start 	= 0;
				WHILE from_start < main_cnt DO
					SET inner_start = 0;
					SET limit_start	= 0;
					 IF var_reqquantity > 0 THEN
						IF table_name = 'depotstock' THEN
							SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," 
											WHERE itemcode = ",var_main_itemcode," AND batchno = '",var_batchnumber,"' 
											AND DATE(expirydate) = DATE('",var_expirydate,"') AND quantity > 0 group by itemcode,batchno,expirydate ");
						ELSEIF table_name = 'tbldepotstock' THEN
							SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode,"
							AND batchno = '",var_batchnumber,"'AND DATE(expirydate) = DATE('",var_expirydate,"') group by batchno,expirydate ");
						END IF;
						PREPARE s1 FROM @qtmp;
						EXECUTE s1;
					-- select @qtmp;
						IF last_itemcode <> var_main_itemcode THEN
							WHILE inner_start < @innercnt DO
								IF table_name = 'depotstock' THEN
									SET @q = CONCAT("SELECT depotinventorykey,itemcode,sum(quantity),depotcode,batchno,expirydate
										into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
									FROM depotstock
									WHERE itemcode = ",var_main_itemcode," AND batchno = '",var_batchnumber,"' 
									AND DATE(expirydate) = DATE('",var_expirydate,"') AND quantity > 0 ORDER BY expirydate
									limit ",limit_start,",1");
									PREPARE s1 FROM @q;
									EXECUTE s1;
									-- select @q;
								 ELSEIF table_name = 'tbldepotstock' THEN
									SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
										into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
									FROM tbldepotstock
									WHERE itemcode = ",var_main_itemcode," AND batchno = '",var_batchnumber,"' 
									AND DATE(expirydate) = DATE('",var_expirydate,"') AND avlquantity > 0 ORDER BY expirydate
									limit ",limit_start,",1");
									PREPARE s1 FROM @q;
									EXECUTE s1;
								 END IF;
								IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
									SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
										values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
									SET var_reqquantity = var_reqquantity - @var_quantity;
									
									PREPARE s2 FROM @q1;
									EXECUTE s2;
									
								ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
									SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
										values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
									SET var_reqquantity = 0;
									
									PREPARE s2 FROM @q1;
									EXECUTE s2;
									
								END IF;
								SET inner_start 	= inner_start  + 1;
								SET limit_start 	= limit_start  + 1;
								
								IF var_reqquantity 	= 0 THEN
									SET inner_start = @innercnt;
								END IF;
							END WHILE;
						END IF;
						SET last_itemcode = var_main_itemcode;
					END IF;
					
					SET from_start 		= from_start  + 1;
					IF var_reqquantity 	= 0 THEN
						SET from_start 	= main_cnt;
					END IF;
				END WHILE;		
			SET counter = counter+1;
			END LOOP main_loop;		
	
	END IF;
	
	-- select * from tmp_quantityinfo;
	SELECT REPLACE(var_loaddetailcode,'_',',') INTO var_ids;
	
	IF table_name = 'depotstock' THEN 
		SET @Q1 = CONCAT("INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,suggtotunits,rcvdtotunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,`status`,transactiondate,erpreferencenumber,
			currencycode,batchnumber,expirydate,warehouse,warehousestock,mdat
			)
			SELECT startingloaddetail.itemcode,routecode,'",var_selected_date,"',loadperiodnumber,IF(cases > IFNULL(FLOOR(ds.quantity/upc),0),IFNULL(FLOOR(ds.quantity/upc),0),cases) AS cases,
			startingloaddetail.caseprice,IF(units > IFNULL(FLOOR(ds.quantity%upc),0),IFNULL(FLOOR(ds.quantity%upc),0),units) AS units,
			((IF(cases > IFNULL(FLOOR(ds.quantity/upc),0),IFNULL(FLOOR(ds.quantity/upc),0),cases)*upc)+IF(units > IFNULL(FLOOR(ds.quantity%upc),0),IFNULL(FLOOR(ds.quantity%upc),0),units)) AS totunits,
			suggtotunits,rcvdtotunits,upc,loadtime,salesmancode,salesprice,returnprice,startingloaddetail.returncaseprice,
			0,transactiondate,erpreferencenumber,currencycode,ds.batchno,ds.expirydate,warehouse,startingloaddetail.warehousestock,CURRENT_DATE()
			FROM startingloaddetail
			LEFT JOIN tmp_quantityinfo AS ds
				ON ds.depotcode = get_depotcode_routecode(startingloaddetail.routecode)
				  AND ds.itemcode = startingloaddetail.itemcode
				  AND ds.batchno = startingloaddetail.batchnumber
				  AND ds.expirydate = startingloaddetail.expirydate
			WHERE 1 = 1 AND loaddetailcode  IN (",var_ids,")");
			PREPARE s1 FROM @Q1;
			EXECUTE s1;
			-- select @Q1;
			SELECT LAST_INSERT_ID() AS lastid;
			
	ELSEIF	table_name = 'tbldepotstock' THEN 
	
		SET @Q1 = CONCAT("INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,suggtotunits,rcvdtotunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,`status`,transactiondate,erpreferencenumber,
			currencycode,batchnumber,expirydate,warehouse,warehousestock,mdat
			)
			SELECT startingloaddetail.itemcode,routecode,'",var_selected_date,"',loadperiodnumber,IF(cases > IFNULL(FLOOR(ds.avlquantity/upc),0),IFNULL(FLOOR(ds.avlquantity/upc),0),cases) AS cases,
			startingloaddetail.caseprice,IF(units > IFNULL(FLOOR(ds.avlquantity%upc),0),IFNULL(FLOOR(ds.avlquantity%upc),0),units) AS units,
			((IF(cases > IFNULL(FLOOR(ds.avlquantity/upc),0),IFNULL(FLOOR(ds.avlquantity/upc),0),cases)*upc)+IF(units > IFNULL(FLOOR(ds.avlquantity%upc),0),IFNULL(FLOOR(ds.avlquantity%upc),0),units)) AS totunits,
			suggtotunits,rcvdtotunits,upc,loadtime,salesmancode,salesprice,returnprice,startingloaddetail.returncaseprice,
			0,transactiondate,erpreferencenumber,currencycode,ds.batchno,ds.expirydate,warehouse,startingloaddetail.warehousestock,CURRENT_DATE()
			FROM startingloaddetail
			LEFT JOIN tmp_quantityinfo AS ds
				ON ds.depotcode = get_depotcode_routecode(startingloaddetail.routecode)
				  AND ds.itemcode = startingloaddetail.itemcode
				  AND ds.batchno = startingloaddetail.batchnumber
				  AND ds.expirydate = startingloaddetail.expirydate
			WHERE 1 = 1 AND loaddetailcode  (",var_ids,")");
			PREPARE s1 FROM @Q1;
			EXECUTE s1;
			
		SELECT LAST_INSERT_ID() AS lastid;		
	ELSE
	
	   SET @abc = CONCAT("INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
				caseprice,units,totunits,suggtotunits,rcvdtotunits,upc,loadtime,
				salesmancode,salesprice,returnprice,returncaseprice,`status`,transactiondate,erpreferencenumber,
				currencycode,warehouse,warehousestock,mdat,batchnumber,expirydate
				)
				SELECT itemcode,routecode,'",var_selected_date,"',loadperiodnumber,
				IFNULL(cases,0) AS cases,caseprice,
				IFNULL(units,0) AS units,
				(IFNULL(cases,0))+(IFNULL(units,0)) AS totunits,
				suggtotunits,rcvdtotunits,upc,loadtime,
				salesmancode,salesprice,returnprice,returncaseprice,
				0,transactiondate,erpreferencenumber,currencycode,warehouse,warehousestock,CURRENT_DATE(),
				batchnumber,expirydate
				FROM startingloaddetail
				WHERE 1 = 1 AND loaddetailcode in(",var_ids,")");
		
		PREPARE s1 FROM @abc;
		EXECUTE s1;
		
		SELECT LAST_INSERT_ID() AS lastid;
		
	END IF;
		
		IF table_name = 'depotstock' THEN
			UPDATE depotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.quantity = ds.quantity - ((cases*upc)+units)
				WHERE sld.ddate = var_selected_date;
		ELSEIF table_name = 'tbldepotstock' THEN
			UPDATE tbldepotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.avlquantity = ds.avlquantity - ((cases*upc)+units)
				WHERE sld.ddate = var_selected_date;
		END IF;
	-- drop temporary table
	 DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_dailysalesmanload_requesttoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_dailysalesmanload_requesttoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_dailysalesmanload_requesttoload`(
	IN var_loaddetailcode TEXT,
	IN table_name VARCHAR(100),	
	IN selected_date VARCHAR(50),
	IN var_load INT,
	IN var_routecode BIGINT,
	IN var_allowcases TEXT,
	IN var_allowpieces TEXT,
	IN var_batchno TEXT,
	IN var_expirydate TEXT,
	IN var_totrecord INT	
	)
BEGIN
    -- we have paste same sp_get_inventory_transaction_dailysalesmanload_qtyinfo_depot sp here
    -- because temporary table is only use in same sp that's why
	DECLARE var_selected_date DATE; 
 	DECLARE var_ids TEXT;
 	DECLARE from_loop_start INT DEFAULT 1;
 	DECLARE var_primarykey BIGINT;
 	
 	DECLARE tmp_cases BIGINT;
 	DECLARE tmp_pieces BIGINT;
 	DECLARE tmp_batchno VARCHAR(100);
 	DECLARE tmp_ddate VARCHAR(50);
	
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
	
	
	 DECLARE cur1 CURSOR FOR SELECT itemcode,SUM(quantity) AS quantity FROM inventorytransactiondetail AS itd
		LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
		WHERE itd.transactiontypecode = 8 AND DATE(ith.transactiondate) = (STR_TO_DATE(selected_date,"%d-%m-%Y"))
		AND routecode = var_routecode 
		GROUP BY itemcode ORDER BY itemcode;
  
		DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
		SELECT STR_TO_DATE(selected_date,"%d-%m-%Y") INTO var_selected_date;
		
	if table_name != '' then
		DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo;   
		SET @qtmp = CONCAT("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
		PREPARE s1 FROM @qtmp;
		EXECUTE s1;
		
	OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		 SELECT COUNT(itemcode) INTO main_cnt FROM inventorytransactiondetail AS itd
			LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
			WHERE itd.transactiontypecode = 8 AND DATE(ith.transactiondate) = var_selected_date
				AND routecode = var_routecode AND itemcode = var_main_itemcode GROUP BY itemcode;
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
		
	end if;
	SELECT  REPLACE(var_loaddetailcode,'_',',') INTO var_ids;
	if table_name = 'depotstock' then 	
			insert into startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,batchnumber,expirydate,mdat
			)
			SELECT itd.itemcode,routecode,var_selected_date,var_load,
			IF(FLOOR(itd.quantity/im.unitspercase) > IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),FLOOR(itd.quantity/im.unitspercase)) as cases,
			caseprice,
			IF(IFNULL(floor(itd.quantity%im.unitspercase),0) > IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(floor(itd.quantity%im.unitspercase),0)) AS units,
			((IF(FLOOR(itd.quantity/im.unitspercase) > IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),FLOOR(itd.quantity/im.unitspercase))*im.unitspercase)+IF(IFNULL((itd.quantity%im.unitspercase),0) > IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL((itd.quantity%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),get_salesmancode_routecode(routecode),defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,ith.currencycode,ds.batchno,ds.expirydate,CURRENT_DATE()
			FROM inventorytransactiondetail AS itd 
			 LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
			  LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
			  LEFT JOIN tmp_quantityinfo AS ds ON ds.depotcode = get_depotcode_routecode(ith.routecode) AND ds.itemcode = itd.itemcode
			WHERE  itd.transactiontypecode = 8 
					AND DATE(ith.transactiondate) = var_selected_date 
					AND primary_key  IN (var_ids);
			
	elseif	table_name = 'tbldepotstock' THEN 
	
		insert into startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,batchnumber,expirydate,mdat
			)
			SELECT itd.itemcode,routecode,var_selected_date,var_load,IF(FLOOR(itd.quantity/im.unitspercase) > IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),FLOOR(itd.quantity/im.unitspercase)) as cases,
			caseprice,IF(IFNULL((itd.quantity%im.unitspercase),0) > IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL((itd.quantity%im.unitspercase),0)) AS units,
			((IF(FLOOR(itd.quantity/im.unitspercase) > IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),FLOOR(itd.quantity/im.unitspercase))*im.unitspercase)+IF(IFNULL((itd.quantity%im.unitspercase),0) > IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL((itd.quantity%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),get_salesmancode_routecode(routecode),defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,ith.currencycode,ds.batchno,ds.expirydate,CURRENT_DATE()
			FROM inventorytransactiondetail AS itd
			  LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
			  LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
			  LEFT JOIN tmp_quantityinfo AS ds ON ds.depotcode = get_depotcode_routecode(ith.routecode) AND ds.itemcode = itd.itemcode
			WHERE itd.transactiontypecode = 8 AND DATE(ith.transactiondate) = var_selected_date AND primary_key  IN (var_ids);
	
	else
	
		SELECT REPLACE(var_allowcases,'_',',') 	INTO var_allowcases;
		SELECT REPLACE(var_allowpieces,'_',',') INTO var_allowpieces;
		SELECT REPLACE(var_batchno,'_',',') 	INTO var_batchno;
		SELECT REPLACE(var_expirydate,'_',',') 	INTO var_expirydate;
		
		WHILE from_loop_start <= var_totrecord DO
			SELECT split(var_ids,',',from_loop_start) INTO var_primarykey;			
			SELECT split(var_allowcases,',',from_loop_start) INTO tmp_cases;
			SELECT split(var_allowpieces,',',from_loop_start) INTO tmp_pieces;
			SELECT split(var_batchno,',',from_loop_start) INTO tmp_batchno;
			SELECT split(var_expirydate,',',from_loop_start) INTO tmp_ddate;
		
			insert into startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,mdat,batchnumber,expirydate
			)
			SELECT itemcode,routecode,var_selected_date,var_load,			
			IF(FLOOR(itd.quantity/im.unitspercase) > IFNULL(FLOOR(tmp_cases/upc),0),IFNULL(FLOOR(tmp_cases/upc),0),FLOOR(itd.quantity/im.unitspercase)) AS cases,caseprice,
			IF(IFNULL((itd.quantity%im.unitspercase),0) > IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL((itd.quantity%im.unitspercase),0)) AS units,
			((IF(FLOOR(itd.quantity/im.unitspercase) > IFNULL(FLOOR(tmp_cases/upc),0),IFNULL(FLOOR(tmp_cases/upc),0),FLOOR(itd.quantity/im.unitspercase))*upc)+IF(IFNULL((itd.quantity%im.unitspercase),0) > IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL((itd.quantity%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),get_salesmancode_routecode(routecode),defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,ith.currencycode,CURRENT_DATE(),tmp_batchno,STR_TO_DATE(tmp_ddate,'%d-%m-%Y')
			FROM inventorytransactiondetail AS itd 
			  LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
			  LEFT JOIN itemmaster AS im ON im.actualitemcode = itd.itemcode
			WHERE itd.transactiontypecode = 8 AND DATE(ith.transactiondate) = var_selected_date AND primary_key  = var_primarykey;
			
			SET from_loop_start = from_loop_start + 1;
	   END WHILE;
	end if;
	
	SELECT LAST_INSERT_ID() AS lastid;			
	
	IF table_name = 'depotstock' THEN
			UPDATE depotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.quantity = ds.quantity - ((cases*upc)+units)
				WHERE sld.ddate = CURRENT_DATE();
		ELSEIF table_name = 'tbldepotstock' THEN
			UPDATE tbldepotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.avlquantity = ds.avlquantity - ((cases*upc)+units)
				WHERE sld.ddate = CURRENT_DATE();
		END IF;
	-- drop temporary table
	DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_dailysalesmanload_suggestedsales` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_dailysalesmanload_suggestedsales` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_dailysalesmanload_suggestedsales`(
	IN var_loaddetailcode TEXT,
	IN table_name VARCHAR(100),
	IN selected_date VARCHAR(50),
	IN var_load INT,
	IN var_routecode BIGINT,
	IN var_allowcases TEXT,
	IN var_allowpieces TEXT,
	IN var_batchno TEXT,
	IN var_expirydate TEXT,
	IN var_totrecord INT
	)
BEGIN
 	DECLARE var_selected_date DATE; 
 	DECLARE var_ids TEXT;
 	DECLARE from_loop_start INT DEFAULT 1;
 	DECLARE var_primarykey BIGINT;
 	
 	DECLARE tmp_cases BIGINT;
 	DECLARE tmp_pieces BIGINT;
 	DECLARE tmp_batchno VARCHAR(100);
 	DECLARE tmp_ddate VARCHAR(50);
	
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,SUM(currentvisitsales) FROM suggestedsalesinvoice AS ssi		
		WHERE DATE(ssi.transactiondate) = (STR_TO_DATE(selected_date,"%d-%m-%Y")) AND routecode = var_routecode
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  SELECT STR_TO_DATE(selected_date,"%d-%m-%Y") INTO var_selected_date;
  
IF table_name != '' THEN
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  
  SET @qtmp = CONCAT("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
  PREPARE s1 FROM @qtmp;
  EXECUTE s1;
  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;		
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;		
		
		SELECT COUNT(itemcode) INTO main_cnt FROM suggestedsalesinvoice AS ssi		
			WHERE DATE(ssi.transactiondate) = var_selected_date AND routecode = var_routecode
			GROUP BY itemcode ORDER BY itemcode;
		
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
		
	END IF;	
  
	SELECT REPLACE(var_loaddetailcode,'_',',') INTO var_ids;
	
	IF table_name = 'depotstock' THEN 
		INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,batchnumber,expirydate,mdat
			)
			SELECT ssi.itemcode,routecode,var_selected_date,var_load,IF(FLOOR(ssi.currentvisitsales/im.unitspercase) > IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),FLOOR(ssi.currentvisitsales/im.unitspercase)) AS cases,
			caseprice,IF(IFNULL((ssi.currentvisitsales%im.unitspercase),0) > IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL((ssi.currentvisitsales%im.unitspercase),0)) AS units,
			((IF(FLOOR(ssi.currentvisitsales/im.unitspercase) > IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),FLOOR(ssi.currentvisitsales/im.unitspercase))*im.unitspercase)+IF(IFNULL((ssi.currentvisitsales%im.unitspercase),0) > IFNULL(FLOOR(ds.quantity%im.unitspercase),0),IFNULL(FLOOR(ds.quantity/im.unitspercase),0),IFNULL((ssi.currentvisitsales%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),get_salesmancode_routecode(ssi.routecode),defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,ssi.currencycode,ds.batchno,ds.expirydate,CURRENT_DATE()
			FROM suggestedsalesinvoice AS ssi
			  LEFT JOIN itemmaster AS im ON im.actualitemcode = ssi.itemcode
			  LEFT JOIN depotstock AS ds ON ds.depotcode = get_depotcode_routecode(ssi.routecode) AND ds.itemcode = ssi.itemcode
			WHERE DATE(ssi.transactiondate) = var_selected_date AND ssi.primary_key  IN (var_ids);
			
	ELSEIF	table_name = 'tbldepotstock' THEN 
	
		INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,salesmancode,salesprice,returnprice,returncaseprice,
			transactiondate,currencycode,batchnumber,expirydate,mdat
			)
			SELECT ssi.itemcode,routecode,var_selected_date,var_load,IF(FLOOR(ssi.currentvisitsales/im.unitspercase) > IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),FLOOR(ssi.currentvisitsales/im.unitspercase)) AS cases,
			caseprice,IF(IFNULL((ssi.currentvisitsales%im.unitspercase),0) > IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL((ssi.currentvisitsales%im.unitspercase),0)) AS units,
			((IF(FLOOR(ssi.currentvisitsales/im.unitspercase) > IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),FLOOR(ssi.currentvisitsales/im.unitspercase))*im.unitspercase)+IF(IFNULL((ssi.currentvisitsales%im.unitspercase),0) > IFNULL(FLOOR(ds.avlquantity%im.unitspercase),0),IFNULL(FLOOR(ds.avlquantity/im.unitspercase),0),IFNULL((ssi.currentvisitsales%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),get_salesmancode_routecode(ssi.routecode),defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,ssi.currencycode,ds.batchno,ds.expirydate,CURRENT_DATE()
			FROM suggestedsalesinvoice AS ssi
			  LEFT JOIN itemmaster AS im ON im.actualitemcode = ssi.itemcode
			  LEFT JOIN tbldepotstock AS ds ON ds.depotcode = get_depotcode_routecode(ssi.routecode) AND ds.itemcode = ssi.itemcode
			WHERE DATE(ssi.transactiondate) = var_selected_date AND ssi.primary_key  IN (var_ids);
	ELSE
		
		SELECT REPLACE(var_allowcases,'_',',') 	INTO var_allowcases;
		SELECT REPLACE(var_allowpieces,'_',',') INTO var_allowpieces;
		SELECT REPLACE(var_batchno,'_',',') 	INTO var_batchno;
		SELECT REPLACE(var_expirydate,'_',',') 	INTO var_expirydate;
		
		WHILE from_loop_start <= var_totrecord DO
			SELECT split(var_ids,',',from_loop_start) INTO var_primarykey;			
			SELECT split(var_allowcases,',',from_loop_start) INTO tmp_cases;
			SELECT split(var_allowpieces,',',from_loop_start) INTO tmp_pieces;
			SELECT split(var_batchno,',',from_loop_start) INTO tmp_batchno;
			SELECT split(var_expirydate,',',from_loop_start) INTO tmp_ddate;
			
			INSERT INTO startingloaddetail(itemcode,routecode,ddate,loadperiodnumber,cases,
			caseprice,units,totunits,upc,loadtime,
			salesmancode,salesprice,returnprice,returncaseprice,transactiondate,
			currencycode,mdat,batchnumber,expirydate
			)
			SELECT itemcode,routecode,var_selected_date,var_load,
			IF(FLOOR(ssi.currentvisitsales/im.unitspercase) > IFNULL(FLOOR(tmp_cases/upc),0),IFNULL(FLOOR(tmp_cases/upc),0),FLOOR(ssi.currentvisitsales/im.unitspercase)) AS cases,caseprice,
			IF(IFNULL((ssi.currentvisitsales%im.unitspercase),0) > IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL((ssi.currentvisitsales%im.unitspercase),0)) AS units,
			((IF(FLOOR(ssi.currentvisitsales/im.unitspercase) > IFNULL(FLOOR(tmp_cases/upc),0),IFNULL(FLOOR(tmp_cases/upc),0),FLOOR(ssi.currentvisitsales/im.unitspercase))*upc)+IF(IFNULL((ssi.currentvisitsales%im.unitspercase),0) > IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL(FLOOR(tmp_pieces%upc),0),IFNULL((ssi.currentvisitsales%im.unitspercase),0))) AS totunits,
			im.unitspercase,CURRENT_TIME(),get_salesmancode_routecode(ssi.routecode),defaultsalesprice,defaultgoodreturnprice,defaultgoodreturncaseprice,
			var_selected_date,ssi.currencycode,CURRENT_DATE(),tmp_batchno,STR_TO_DATE(tmp_ddate,'%d-%m-%Y')
			FROM suggestedsalesinvoice AS ssi
			  LEFT JOIN itemmaster AS im ON im.actualitemcode = ssi.itemcode			  
			WHERE DATE(ssi.transactiondate) = var_selected_date AND ssi.primary_key  = var_primarykey;	
			
			SET from_loop_start = from_loop_start + 1;
	   END WHILE;
	END IF;
	
	SELECT LAST_INSERT_ID() AS lastid;
	
	IF table_name = 'depotstock' THEN
			UPDATE depotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.quantity = ds.quantity - ((cases*upc)+units)
				WHERE sld.ddate = CURRENT_DATE();
		ELSEIF table_name = 'tbldepotstock' THEN
			UPDATE tbldepotstock AS ds 
			INNER JOIN startingloaddetail AS sld ON sld.itemcode = ds.itemcode
				AND sld.batchnumber = ds.batchno AND sld.expirydate = ds.expirydate
				AND get_depotcode_routecode(sld.routecode) = ds.depotcode
			SET ds.avlquantity = ds.avlquantity - ((cases*upc)+units)
				WHERE sld.ddate = CURRENT_DATE();
		END IF;
	-- drop temporary table
	DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_deliveryheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_deliveryheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_deliveryheader`(			
			IN var_routecode BIGINT,
			IN var_salesmancode BIGINT,			
			IN var_delivery_no BIGINT,
			IN var_date VARCHAR(30),			
			IN var_referencenumber VARCHAR(30),
			IN var_customer BIGINT(30),
			IN var_order BIGINT(30)
		)
BEGIN
	
	SET @qry = CONCAT("select count(*) into @val from deliveryheader 
					where deliveryno = ",var_delivery_no,"");
	
	
	
	PREPARE s2 FROM @qry;
	EXECUTE s2;
		
	IF @val = 0  THEN 
		SET @dyn = CONCAT("insert into deliveryheader SET
										deliveryroute 	= ",var_routecode,",
										drivercode= ",var_salesmancode," ,										
										customercode = '",var_customer,"',
										deliveryno = '",var_delivery_no,"',
										referenceno = '",var_referencenumber,"',
										helpercode = '",var_salesmancode,"',
										orderno	= '",var_order,"',
										presalesroute	= '0',
										dispatched	= '0',
										canceled	= '0',
										redispatch	= '0',
										loadsheetnumber	= '0',
										delivered	= '0',
										sequence	= '0',
										dispatchdate  = STR_TO_DATE('",var_date,"','%d-%m-%Y'),
										deliverydate  = STR_TO_DATE('",var_date,"','%d-%m-%Y')");
		-- select 			@dyn;
		PREPARE s1 FROM @dyn;
		EXECUTE s1;
		SELECT LAST_INSERT_ID() AS result;
	ELSE
		SELECT 'Duplicate' AS result;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_deliveryloadgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_deliveryloadgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_deliveryloadgrid`(
			IN var_deliveryno BIGINT,
			IN var_itemcode BIGINT,
			IN var_upc INT(4),
			IN var_caseprice DECIMAL(18,2),
			IN var_salesprice DECIMAL(28,15),						
			IN var_cases INT(4),
			IN var_units INT(4),
			IN var_freecases INT(4),
			IN var_freeunits INT(4)
		)
BEGIN
	
	DECLARE var_quantity BIGINT;
	DECLARE var_focquantity BIGINT;
	
		SET @qry = CONCAT("select count(*) into @val from deliverydetail 
					 where deliveryno = ",var_deliveryno," and itemcode = ",var_itemcode,"");
	
		
	PREPARE s2 FROM @qry;
	EXECUTE s2;
		
	IF @val = 0  THEN 
	
		SELECT FLOOR(var_cases*var_upc)+(var_units) INTO var_quantity;
		SELECT FLOOR(var_freecases*var_upc)+(var_freeunits) INTO var_focquantity;
		
		SET @dyn = CONCAT("insert into deliverydetail SET
										deliveryno 	= ",var_deliveryno,",
										itemcode 	= ",var_itemcode,",
										unitspercase	= ",var_upc,",
										caseprice 	= ",var_caseprice," ,
										salesprice  	= ",var_salesprice,",
										salesqty 	= ",var_quantity," ,
										focqty  	= ",var_focquantity,",
										returnqty	= '0',
										promotionamount	= '0',
										deliveredqty	= '0',
										deliveredfoc	= '0',
										receivedreturn	= '0',
										reasoncode	= '0'										
										");
		-- select 			@dyn;
		PREPARE s1 FROM @dyn;
		EXECUTE s1;
		SELECT LAST_INSERT_ID() AS result;
	ELSE
		SELECT 'Duplicate' AS result;
	END IF;
	SET @qry = CONCAT("select count(*) into @del_no_count from deliverydetail 
					 where deliveryno = ",var_deliveryno,"");
	PREPARE s2 FROM @qry;
	EXECUTE s2;
	SELECT @del_no_count AS result_count;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_inventory_transaction_loadrequestgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_inventory_transaction_loadrequestgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_inventory_transaction_loadrequestgrid`(
			IN var_itemcode BIGINT,
			IN var_detailkey BIGINT,			
			IN var_cases INT(4),
			IN var_upc INT(4),
			IN var_units INT(4),						
			IN var_salesprice DECIMAL(28,15),			
			IN var_caseprice DECIMAL(28,15)
			
		)
BEGIN
	
	DECLARE var_quantity BIGINT;
	SET @qry = CONCAT("select count(*) into @val from inventorytransactiondetail where transactiontypecode = 8 and detailkey = ",var_detailkey," and itemcode = ",var_itemcode," ");	
	PREPARE s2 FROM @qry;
	EXECUTE s2;
	
		
	IF @val = 0  THEN 
			
		INSERT INTO  inventorytransactiondetail SET
							routekey = (SELECT routekey FROM inventorytransactionheader WHERE detailkey =var_detailkey),
							detailkey = var_detailkey,	
							itemcode 	= var_itemcode,						
							itemprice      = var_salesprice,										
							itemcaseprice	= var_caseprice,
							requestedqty = (var_cases*var_upc)+var_units,
							quantity = (var_cases*var_upc)+var_units,
							transactiontypecode = 8,
							currencycode ='971';
				
		SELECT LAST_INSERT_ID() AS result;
	ELSE
		SELECT 'Duplicate' AS result;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_link_customer_customercatlink` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_link_customer_customercatlink` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_link_customer_customercatlink`(
			IN var_catid        bigINT,
			in var_routecode 	bigint,
			IN var_customerid   text,
			IN var_counter      INT
    )
BEGIN
		declare from_start int;	
		set from_start = 1;
		
		
		-- get customer which has current category id. because we just flush it.
		SELECT GROUP_CONCAT(a.customercode) INTO @cstids FROM customermaster AS a WHERE a.customercategory = var_catid and routecode = var_routecode;
		IF @cstids != ''  THEN 
			SET @dlt = CONCAT("UPDATE customermaster SET customercategory = 0 WHERE customercode IN (",@cstids,")");
			PREPARE s1 FROM @dlt;
			EXECUTE s1;
		end if;
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET customercategory = var_catid WHERE customercode = @cust_code;
			SET from_start = from_start + 1;
		END WHILE;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_link_customer_itemmustlink` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_link_customer_itemmustlink` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_link_customer_itemmustlink`(
			IN var_itemmustkey     BIGINT,
			IN var_fillby	   	VARCHAR(20),
			IN var_fillbyval   	VARCHAR(20),
			IN var_category	   	VARCHAR(20),
			IN var_customerid   TEXT,
			IN var_counter      INT
    )
BEGIN
		DECLARE from_start 	INT;
		DECLARE where_cond 	TEXT;
		DECLARE where_cat 	TEXT;
		DECLARE joining 	TEXT;
		
		IF var_fillby = 1 THEN
			SET where_cond 	=  ' AND route.regionmstcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode';
		ELSEIF	var_fillby = 2 THEN
			SET where_cond 	=  ' AND depot.depotcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
								LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
		ELSEIF	var_fillby = 3 THEN
			SET where_cond 	=  ' AND armst.areacode =';
			SET joining		=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
								LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
		ELSEIF	var_fillby = 4 THEN
			SET where_cond 	=  ' AND cust.routecode =';
			SET joining		=  '';
		END IF;
		
		IF var_fillbyval = 0 THEN
			SET where_cond 		=	'';
			SET var_fillbyval 	= 	'';
		END IF;
		
		
		-- where condition for the Customer Category
		IF var_category > 0 THEN
			SET where_cat 	= CONCAT(' AND customercategory = ',var_category);
		ELSE
			SET where_cat 		= '';
			SET var_category 	= '';
		END IF;
		
		SET from_start = 1;
		
		-- Below Query for selected customer id	
		SET @q1 = CONCAT( 	"SELECT group_concat(cust.customercode) INTO @cstids FROM customermaster as cust
							",joining," WHERE 1=1 ",where_cond," ",var_fillbyval," ",where_cat," and activecustomer = 1 AND cust.itemmustkey = ",var_itemmustkey," AND templateindicator = 0");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		-- select @q1;		
		IF @cstids != ''  THEN 
			SET @edit = CONCAT("UPDATE customermaster SET itemmustkey = NULL WHERE customercode IN (",@cstids,")");
			PREPARE s1 FROM @edit;
			EXECUTE s1;
		END IF;
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET itemmustkey = var_itemmustkey WHERE customercode = @cust_code;
			SET from_start = from_start + 1;
		END WHILE;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_link_customer_planogramlink` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_link_customer_planogramlink` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_link_customer_planogramlink`(
			IN var_planogramkey     BIGINT,
			IN var_fillby	   	VARCHAR(20),
			IN var_fillbyval   	VARCHAR(20),
			IN var_category	   	VARCHAR(20),
			IN var_customerid   TEXT,
			IN var_counter      INT
    )
BEGIN
		DECLARE from_start 	INT;
		DECLARE where_cond 	TEXT;
		DECLARE where_cat 	TEXT;
		DECLARE joining 	TEXT;
		
		IF var_fillby = 1 THEN
			SET where_cond 	=  ' AND route.regionmstcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode';
		ELSEIF	var_fillby = 2 THEN
			SET where_cond 	=  ' AND depot.depotcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
								LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
		ELSEIF	var_fillby = 3 THEN
			SET where_cond 	=  ' AND armst.areacode =';
			SET joining		=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
								LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
		ELSEIF	var_fillby = 4 THEN
			SET where_cond 	=  ' AND cust.routecode =';
			SET joining		=  '';
		END IF;
		
		IF var_fillbyval = 0 THEN
			SET where_cond 		=	'';
			SET var_fillbyval 	= 	'';
		END IF;
		
		
		-- where condition for the Customer Category
		IF var_category > 0 THEN
			SET where_cat 	= CONCAT(' AND customercategory = ',var_category);
		ELSE
			SET where_cat 		= '';
			SET var_category 	= '';
		END IF;
		
		SET from_start = 1;
		
		-- Below Query for selected customer id	
		SET @q1 = CONCAT( 	"SELECT group_concat(cust.customercode) INTO @cstids FROM customermaster as cust
							",joining," WHERE 1=1 ",where_cond," ",var_fillbyval," ",where_cat," and activecustomer = 1 AND cust.visualcode = ",var_planogramkey," AND templateindicator = 0");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		-- select @q1;		
		IF @cstids != ''  THEN 
			SET @edit = CONCAT("UPDATE customermaster SET visualcode = NULL WHERE customercode IN (",@cstids,")");
			PREPARE s1 FROM @edit;
			EXECUTE s1;
		END IF;
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET visualcode = var_planogramkey WHERE customercode = @cust_code;
			SET from_start = from_start + 1;
		END WHILE;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_link_customer_surveylink` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_link_customer_surveylink` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_link_customer_surveylink`(
			IN var_surveykey     BIGINT,
			IN var_fillby	   	VARCHAR(20),
			IN var_fillbyval   	VARCHAR(20),
			IN var_category	   	VARCHAR(20),
			IN var_customerid   TEXT,
			IN var_counter      INT
    )
BEGIN
		DECLARE from_start 	INT;
		DECLARE where_cond 	TEXT;
		DECLARE where_cat 	TEXT;
		DECLARE joining 	TEXT;
		
		IF var_fillby = 1 THEN
			SET where_cond 	=  ' AND route.regionmstcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode';
		ELSEIF	var_fillby = 2 THEN
			SET where_cond 	=  ' AND depot.depotcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
								LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
		ELSEIF	var_fillby = 3 THEN
			SET where_cond 	=  ' AND armst.areacode =';
			SET joining		=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
								LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
		ELSEIF	var_fillby = 4 THEN
			SET where_cond 	=  ' AND cust.routecode =';
			SET joining		=  '';
		END IF;
		
		IF var_fillbyval = 0 THEN
			SET where_cond 		=	'';
			SET var_fillbyval 	= 	'';
		END IF;
		
		
		-- where condition for the Customer Category
		IF var_category > 0 THEN
			SET where_cat 	= CONCAT(' AND customercategory = ',var_category);
		ELSE
			SET where_cat 		= '';
			SET var_category 	= '';
		END IF;
		
		SET from_start = 1;
		
