		set from_start = 1;
		
		-- Below Query for selected customer id	
		SET @q1 = CONCAT( 	"SELECT group_concat(cust.customercode) INTO @cstids FROM customermaster as cust
							",joining," WHERE 1=1 ",where_cond," ",var_fillbyval," ",where_cat," and activecustomer = 1 AND cust.promotionkey = ",var_promokey," AND templateindicator = 0");
