/* Procedure structure for procedure `sp_add_link_route_outletproductcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_link_route_outletproductcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_link_route_outletproductcode`(
			IN var_outletsubtype    BIGINT,
			IN var_fillby	   		VARCHAR(20),
			IN var_fillbyval   		VARCHAR(20),
			IN var_category	   		VARCHAR(20),
			IN var_customerid   	TEXT,
			IN var_counter      	INT
    )
BEGIN
		DECLARE where_cond 	 	TEXT;
		DECLARE where_cat 	 	TEXT;
		DECLARE where_outlet 	TEXT;		
		DECLARE joining 	 	TEXT;
		DECLARE from_start 		INT;
		
		SET from_start = 1;
		
		IF var_fillby = 1 THEN
			SET where_cond 	=  'AND route.regionmstcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode';
		ELSEIF	var_fillby = 2 THEN
			SET where_cond 	=  'AND depot.depotcode =';
			SET joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
								LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
		ELSEIF	var_fillby = 3 THEN
			SET where_cond 	=  'AND armst.areacode =';
			SET joining		=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
								LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
								LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
		ELSEIF	var_fillby = 4 THEN
			SET where_cond 	=  'AND cust.routecode =';
			SET joining		=  '';
		ELSE
			SET where_cond 	=  '';
			SET joining 	=  '';
			SET var_fillby 		=  '';
		END IF;
		
		IF var_fillbyval = 0 THEN
			SET where_cond 	=	'';
			SET var_fillbyval 		= 	'';
		END IF;
		
		IF var_category > 0 THEN
			SET where_cat = 'AND cust.customercategory = ';			
		ELSE
			SET where_cat = ' AND 1=1 ';
			SET var_category = '';
		END IF;
				
		IF var_outletsubtype > 0 THEN		
			SET where_outlet = 'AND cust.outletsubtype = ';
		ELSE
			SET where_outlet = ' AND 3=3 ';
			SET var_outletsubtype = '';
		END IF;
		
		-- Below Query for selected customer id	
		SET @q1 = CONCAT( 	"SELECT GROUP_CONCAT(cust.customercode) into @custcode  FROM customermaster as cust
							",joining," WHERE 9=9 ",where_cond," ",var_fillbyval," ",where_cat," ",var_category," and activecustomer = 1 ",where_outlet," ",var_outletsubtype," AND templateindicator = 0");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		-- select @q1;
		
		
		if @custcode != ''  then 
			SET @edit = CONCAT("UPDATE customermaster SET outletsubtype = NULL WHERE customercode IN (",@custcode,")");
			PREPARE s2 FROM @edit;
			EXECUTE s2;
		end if;
		
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET outletsubtype = var_outletsubtype WHERE customercode = @cust_code;
			SET from_start = from_start + 1;
		END WHILE;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_link_route_routeitemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_link_route_routeitemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_link_route_routeitemgroup`(
			IN var_routeitmgrp    	bigINT,
			IN var_fillby 			VARCHAR(20),
			IN var_val				VARCHAR(20),
			IN var_customerid   	text,
			IN var_counter      	INT
    )
BEGIN
		declare from_start 	int;	
		DECLARE where_cond 	TEXT;
		DECLARE joining 	TEXT;
		DECLARE where_route TEXT;
		
		SET from_start = 1;
	
		IF var_fillby = 1 THEN
			SET where_cond 	=  ' AND route.regionmstcode =';
			SET joining 	=  '';
		ELSEIF	var_fillby = 2 THEN
			SET where_cond 	=  'AND depot.depotcode =';
			SET joining 	=  'LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
								LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
		ELSEIF	var_fillby = 3 THEN
			SET where_cond 	=  'AND armst.areacode =';
			SET joining		=  'LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
								LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
		END IF;
		
		IF var_val = '0' THEN
			SET where_cond 	=	'';
			SET var_val 		= 	'';
		END IF;
		
		IF var_routeitmgrp !='0' THEN
			SET where_route = CONCAT(' AND route.routeitemgrpcode = ',var_routeitmgrp);
		ELSE
			SET where_route = ' AND 1=1 ';
			SET var_routeitmgrp = '';
		END IF;
		
		-- Below Query for selected route id	
		SET @q1 = CONCAT("SELECT GROUP_CONCAT(route.routecode) INTO @rtcode FROM routemaster as route
							",joining," WHERE 9=9 ",where_cond," ",var_val," AND routetmpl = 0 ",where_route," AND route.activestatus = 1");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		-- select @q1;
		
		if @rtcode != ''  then 
			SET @edit = CONCAT("UPDATE routemaster SET routeitemgrpcode = NULL WHERE routecode IN (",@rtcode,")");
			PREPARE s2 FROM @edit;
			EXECUTE s2;
		end if;
		
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE routemaster SET routeitemgrpcode = var_routeitmgrp WHERE routecode = @cust_code;
			SET from_start = from_start + 1;
		END WHILE;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_loadstock_inventorytransactionheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_loadstock_inventorytransactionheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_loadstock_inventorytransactionheader`(			
			IN var_routecode BIGINT,
			IN var_salesmancode BIGINT,
			IN var_date VARCHAR(30),
			IN var_urgent INT(4),
			IN var_deopt_route DECIMAL(18,0)
			
		)
BEGIN
	
		DECLARE doc_num BIGINT;
		DECLARE route_key BIGINT;		
		SELECT COALESCE(MAX(documentnumber),0)+1 INTO doc_num FROM inventorytransactionheader WHERE DATA = 1;
		SELECT COALESCE(MAX(routekey),0) INTO route_key FROM startendday WHERE routecode = var_routecode;
		SET @dyn = CONCAT("INSERT INTO inventorytransactionheader SET 
			inventorykey = ",route_key,",			
			routekey = ",route_key,",
			transactiontype = '4',
			routecode = ",var_routecode,",
			salesmancode = ",var_salesmancode,",
			transactiondate = CURDATE(),
			transactiontime = CURTIME(),
			documentnumber = ",doc_num,",
			odometerreading = '0',
			transferlocationcode = ",var_deopt_route,",
			referencenumber = ",doc_num,",
			requestdate = STR_TO_DATE('",var_date,"','%Y-%m-%d'),
			deliverydate = STR_TO_DATE('",var_date,"','%Y-%m-%d'),
			securitycode = '0',
			transmitindicator = '0',
			voidflag = '0',
			hhcdocumentnumber = '0',
			loadnumber = '0',
			refdocumentnumber = '0',
			currencycode = get_default_currencycode_routecode(",var_routecode,"),
			actualtransactiondate = CURDATE(),
			inventorynumber = ",doc_num,",
			DATA = '1',
			record_flag='1',
			isurgent=",var_urgent,",
			receivedtime = CURTIME()");
		-- select 			@dyn;
		PREPARE s1 FROM @dyn;
		EXECUTE s1;
		SELECT LAST_INSERT_ID() AS result;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_logmaster_information` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_logmaster_information` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_logmaster_information`(
					
					in counter int,
					in form_name varchar(100),
					in tblname varchar(100),
					in tblid 	text,
					in createdby varchar(30),
					in operationtype varchar(20)
				)
BEGIN
		DECLARE record_id INT;
		declare from_start int default 1;		
		
		if operationtype = 'delete' then		
			set operationtype = 'Delete';
		end if;
		
		
		while from_start <= counter do
		
		SET record_id = split(tblid,',',from_start);
		
			insert into logmaster(formname,tablename,recordid,created,cdat,operation_type)values
				(form_name,tblname,record_id,createdby,CURRENT_DATE(),operationtype);				
				
			
			-- increment the value for getting next records.
			SET  from_start = from_start + 1;
		end while;
END */$$
DELIMITER ;

