/* Procedure structure for procedure `sp_add_merchandize_index_addsurveykeyplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_merchandize_index_addsurveykeyplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_merchandize_index_addsurveykeyplan`(
			IN var_surveykey		BIGINT,
			IN var_surveyplankey    TEXT,
			IN var_counter        	INT,
			in var_created 			varchar(50)
    )
BEGIN
		DECLARE from_start INT;	
		SET from_start = 1;
		
		-- DELETE FROM customersurveykeyplan WHERE surveykey = var_surveykey;
		
		WHILE from_start <= var_counter DO 
		
			SET @plan_key = '';
			SET @plan_key = split(var_surveyplankey,',',from_start);
			
			select count(*) into @cnt from customersurveykeyplan where surveyplankey = @plan_key and surveykey = var_surveykey;
			
			if @cnt = 0 then 
				INSERT INTO customersurveykeyplan 
						SET	surveyplankey	= @plan_key,
							surveykey		= var_surveykey,
							created 		= var_created,
							cdat 			= CURRENT_DATE(),
							modified 		= var_created,
							mdat 			= CURRENT_DATE();
							
				select 'Insert';
			end if;
			SET from_start = from_start + 1;
			
		END WHILE;
		
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_merchandize_index_addsurveyplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_merchandize_index_addsurveyplan` */;

DELIMITER $$

