			IN var_surveydefkey 			TEXT,
			IN var_counter					INT,
			IN var_division        VARCHAR(50),
			IN createdby 					VARCHAR(30)
			
    )
BEGIN
		INSERT INTO customersurveyplan set
					surveysequencenumber	= var_surveysequencenumber,
					surveymandatory 		= var_surveymandatory,
					surveydescription		= var_surveydescription,
					arbsurveydescription 	= var_arbsurveydescription,
					remarks=var_division,
					created 				= createdby,
					cdat 					= CURRENT_DATE(),
					modified 				= createdby,
					mdat 					= CURRENT_DATE();
					
		select LAST_INSERT_ID() into @var_surveyplankey;
		
		CALL sp_add_merchandize_index_addcustomersurveydefassign(var_surveydefkey,var_counter,@var_surveyplankey,createdby);
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Survey Plan','customersurveyplan',@var_surveyplankey,createdby,'Add');
		
		
    END */$$
DELIMITER ;

