/* Procedure structure for procedure `sp_add_ordertransaction_salesorderadd_detail1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_ordertransaction_salesorderadd_detail1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_ordertransaction_salesorderadd_detail1`(
IN var_ordernumber DECIMAL(28,0),
IN var_documentnumber DECIMAL(28,0),
IN var_routecode DECIMAL(18,0),
IN var_customercode DECIMAL(18,0),
IN var_comment VARCHAR(200),
IN var_ponumber VARCHAR(20),
in var_delivery_date varchar(20),
IN in_output BLOB
)
BEGIN
/* insert record into salesorderheader*/
	DECLARE var_salesmancode INT;
	DECLARE in_last_insert_id INT;
	DECLARE in_route_key_code INT;
	
	-- salesman code 
		SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_routecode;
	-- routekey find
	SELECT routekey INTO in_route_key_code FROM startendday 
	WHERE startendday.routecode=var_routecode
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	-- insert record into invoiceheader	
	INSERT INTO salesorderheader_temp SET 
	transactiondate 	= DATE(CURRENT_DATE()),
	transactiontime 	= TIME(CURRENT_DATE()),
	routecode 		= var_routecode,
	salesmancode  		= var_salesmancode,
	customercode 		= var_customercode,
	comments 		= var_comment,
	comments2 		= var_ponumber,
	totalsalesamount	= 0,
	totalreturnamount	= 0,
	totaldamagedamount 	= 0,
	totalfreesampleamount	= 0,
	totalinvoiceamount	= 0,
	dexflag			= 0,
	voidflag		= 0,
	paymenttype		= 0,
	advanceused		= 0,
	paymentstatus		= 0,
	advancebalance		= 0,
	advancereceived		= 0,
	`data`			= 0,
	dsdnumber		= 0,
	orderdeliverydate	= STR_TO_DATE(var_delivery_date,'%d-%m-%Y'),
	currencycode  		= get_default_currencycode(),
	record_flag 		= '1';
		
	SET in_last_insert_id =LAST_INSERT_ID();
	
	-- update salesorderheader record	
	UPDATE salesorderheader_temp SET
	routekey 		=  in_route_key_code,
	visitkey 		=  in_last_insert_id,
	invoicenumber 		=  in_last_insert_id,
	documentnumber 	=  in_last_insert_id
	WHERE transactionkey = in_last_insert_id;
	
	
    -- retrun salesorderheader routekey,visitkey and transaction key
	SELECT in_last_insert_id AS invoice_transaction_key,
	in_last_insert_id AS visitkey ,
	in_route_key_code AS routekey ;
	CALL sp_add_ordertransaction_salesorderadd_signaturedata(in_last_insert_id,in_route_key_code,in_last_insert_id,var_customercode,0,in_output);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_ordertransaction_salesorderadd_detail2` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_ordertransaction_salesorderadd_detail2` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_ordertransaction_salesorderadd_detail2`(
IN var_transactionkey BIGINT(20),
IN var_routekey bigint(20),
IN var_visitkey bigint(20),
IN var_itemcode bigint(20),
IN var_sales_case_price DECIMAL(18,6),
IN var_sales_pcs_price DECIMAL(18,6),
IN var_goodreturn_case_price DECIMAL(18,6),
IN var_goodreturn_pcs_price DECIMAL(18,6),
IN var_return_case_price DECIMAL(18,6),
IN var_return_pcs_price DECIMAL(18,6),
IN var_salesqty DECIMAL(18,0),
IN var_returnqty DECIMAL(18,0),
IN var_damagedqty DECIMAL(18,0),
IN var_manualfreeqty decimal(18,0),
IN var_sales_amount INT
)
BEGIN
	DECLARE in_sales_price DECIMAL(18,4);	
	DECLARE in_sales_case_price DECIMAL(18,4);
	DECLARE in_return_price DECIMAL(18,4);	
	DECLARE in_return_case_price DECIMAL(18,4);
	DECLARE in_last_insert_id INT;
	
	SELECT  itemmaster.defaultsalesprice AS sales_price,
		itemmaster.defaultreturnprice AS return_price,
		itemmaster.caseprice AS sales_case_price,
		itemmaster.returncaseprice AS return_case_pric
	INTO 	in_sales_price,		in_return_price,
		in_sales_case_price,   in_return_case_price
	FROM itemmaster
	WHERE itemmaster.actualitemcode =var_itemcode;
	
	insert into salesorderdetail_temp set 
	routekey 		= var_routekey,
	visitkey 		= var_visitkey,
	transactionkey 		= var_transactionkey,
	itemcode 		= var_itemcode,
	salesprice  		= var_sales_pcs_price,
	returnprice 		= var_return_pcs_price,
	salescaseprice 		= var_sales_case_price,
	returncaseprice 	= var_return_case_price,
	goodreturnprice		= var_goodreturn_pcs_price,
	goodreturncaseprice	= var_goodreturn_case_price,
	stdsalesprice   	= in_sales_price,
	stdreturnprice  	= in_return_price,
	stdsalescaseprice 	= in_sales_case_price,
	stdreturncaseprice 	= in_return_case_price,
	promoamount 		= 0,
	salesqty 		= var_salesqty,
	returnqty 		= var_returnqty ,
	damagedqty 		= var_damagedqty,
	manualfreeqty 		= var_manualfreeqty;
	
	set in_last_insert_id =  LAST_INSERT_ID();
	-- select LAST_INSERT_ID() as sales_order_detail_primay_key;	
	
		
	UPDATE salesorderdetail_temp 
		SET salesorderdetail_temp.sales_amount = ((salesqty / var_sales_amount) * salescaseprice 
					+ ((salesqty % var_sales_amount) * salesprice))
	WHERE 
	salesorderdetail_temp.primary_key = in_last_insert_id;	
	
	UPDATE salesorderheader_temp, 
	( SELECT 
	SUM((FLOOR(id.salescaseprice) * FLOOR(salesqty/im.unitspercase))+(ROUND(id.salesprice,3) * REPLACE(ROUND((salesqty%im.unitspercase),3),",",""))) AS total_sales, 
	SUM((FLOOR(id.returncaseprice) * FLOOR(damagedqty/im.unitspercase))+(ROUND(id.returncaseprice,3) * REPLACE(ROUND((damagedqty%im.unitspercase),3),",",""))) AS total_damage, 
	SUM((FLOOR(id.goodreturncaseprice) * FLOOR(returnqty/im.unitspercase))+(ROUND(id.goodreturnprice,3) * REPLACE(ROUND((returnqty%im.unitspercase),3),",",""))) AS total_buyback, 
	SUM((FLOOR(id.salescaseprice) * FLOOR(freesampleqty/im.unitspercase))+(ROUND(id.salesprice,3) * REPLACE(ROUND((freesampleqty%im.unitspercase),3),",",""))) AS total_free_sample_qty,
	sum(id.promoamount) as promotionamount
	FROM salesorderdetail_temp AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode =id.itemcode 
	JOIN salesorderheader_temp AS ih 
	WHERE ih.transactionkey = id.transactionkey AND ih.transactionkey = var_transactionkey ) AS a	
	 SET salesorderheader_temp.totalsalesamount =IFNULL(a.total_sales,0) ,
	  salesorderheader_temp.totalinvoiceamount = (IFNULL(a.total_sales,0)- IFNULL(a.total_buyback,0)-IFNULL(a.total_damage,0)-ifnull(a.promotionamount,0)), 
	  salesorderheader_temp.totalreturnamount =a.total_buyback, 
	  salesorderheader_temp.totaldamagedamount =a.total_damage
	   WHERE salesorderheader_temp.transactionkey =var_transactionkey;
	   
	  /*	  
	  added by Hiren dave on 23-11-2012
	  ih.promoamount AS promoamount in temporaty a table
	  IFNULL(a.promoamount,0) do minus in totalinvoiceamount	  
	  */
	   	
		   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_ordertransaction_salesorderadd_signaturedata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_ordertransaction_salesorderadd_signaturedata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_ordertransaction_salesorderadd_signaturedata`(
IN in_visitkey INT,
IN in_routekey INT,
IN in_transactionkey INT,
IN in_customer INT,
IN in_amount_due DOUBLE(8,0),
IN in_output BLOB
)
BEGIN
DELETE  FROM sigcapturedata_temp WHERE transactionkey =in_transactionkey and transaction_type = 4;
	INSERT INTO sigcapturedata_temp 
	(routekey, visitkey, transactionkey, customercode, transactiondate,  balancedueamount,signaturedata,transaction_type)
	VALUES
	(in_routekey,in_visitkey,in_transactionkey,in_customer,CURRENT_DATE(),in_amount_due,in_output,4);
 
   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_organisation_index_addrotuecat` */

