/* Procedure structure for procedure `sp_add_organization_index_addarea` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_organization_index_addarea` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_organization_index_addarea`(
		    IN var_areacode        	BIGINT,
			IN var_areaname        	VARCHAR(50),
			IN var_arbareaname         	VARCHAR(50),
			IN var_depotcode           	BIGINT,
			IN var_areamanagercode      BIGINT,
			IN var_areaprefix           int(11),			
			in var_modified		CHAR(20),
			IN var_alternateareacode	varchar(30),
			IN var_activestatus		int(11),
			IN var_created               CHAR(20)
    )
BEGIN
		INSERT INTO areamaster
			(
			areaname,
			arbareaname,
			depotcode,
			areamanagercode,
			areaprefix,
			created,
			cdat,
			modified,
			mdat,
			alternateareacode,
			activestatus  )
		VALUES
		( 
		var_areaname,
		var_arbareaname,
		var_depotcode,
		var_areamanagercode,
		var_areaprefix,
		var_created,
		CURRENT_DATE(),
		var_modified,
		CURRENT_DATE(),
		var_alternateareacode,
		var_activestatus		
		 );
		 
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Area Master','areamaster',@last_id,var_created,'Add');
	
    END */$$
DELIMITER ;

