		IN var_enablestartdaydatetimeedit INT(4),
		IN var_enabledelayprint INT(4),
		IN var_enforcecallsequence INT(4),
		IN var_enablefoclimit INT(4),
		IN var_enablecashonlydiscount INT(4),		
		IN var_reqeodnosalereport INT(4),
		IN var_generatehhcseqfromboflag INT(4),
		IN var_enablenosale INT(4),
		IN var_reqeodnondelreport INT(4),
		IN var_allowpopulateload INT(4),
		IN var_cashbalance INT(4),
		IN var_allowgctocash INT(4),
		IN var_allowroutestartdayflag INT(4),
		IN var_inventoryvariance INT(4),
		IN var_reqeodprcchgreport INT(4),
		IN var_invenoversell INT(4),
		IN var_reqeodpromosreport INT(4),
		IN var_enabledamagedtrxn INT(4),		
 		IN var_reqeodnonscannedreport INT(4),
		IN var_loadaccessafterunload INT(4),
		IN var_reqeododomlogreport INT(4),
		IN var_usesalesdateflag INT(4),
		IN var_displayinvsummary INT(4),
		IN var_includeloadrequest INT(4),
		IN var_creditlimit INT(4),
		IN var_defaultdeliverydays INT(4),
		IN var_loadreqrolluporders INT(4),
		IN var_tlockstatus INT(4),
		IN var_loadreqmethod INT(4),
		IN var_routeprinter INT(4),
		IN var_routetype INT(4),
		IN var_reqeodexceptionrpt INT(4),
		IN var_depotprinter INT(4),		
		IN var_passwordarray2  INT(4),
		IN var_passwordarray8  INT(4),
		IN var_passwordarray3  INT(4),
		IN var_passwordarray9  INT(4),
		IN var_passwordarray4  INT(4),
		IN var_passwordarray13 INT(4),
		IN var_passwordarray16 INT(4),
		IN var_passwordarray11 INT(4),
		IN var_inventoryreportcontrol INT(4),
		IN var_enablestartdayrtewkdayedit INT(4),
		IN var_itemcodedisplay INT(4),
		IN var_templatename VARCHAR(100)
    )
BEGIN
	
	insert into routemaster
			SET 		routetmpl	= 1,
					 templatename	= var_templatename,
						password1 	= var_password1,
						password2 	= var_password2,
						password3 	= var_password3,
						password4 	= var_password4,
						password5	= var_password5,
					promptodominput	= var_promptodominput,
				inventorycaseinput	= var_inventorycaseinput,
				reqeoddepositreport = var_reqeoddepositreport,
