			    reqeodplacementsrpt = var_reqeodplacementsrpt,
			    amountdecimaldigits = var_amountdecimaldigits,
			  unloadoversellmessage	= var_unloadoversellmessage,                           
			       reqeodroasummary = var_reqeodroasummary,
			    inventoryvalueprint = var_inventoryvalueprint,
			       routeitemgrpcode = var_routeitemgrpcode,
			 itemdescriptiondisplay = var_itemdescriptiondisplay,
			     enableloadtransfer = var_enableloadtransfer,
			       enablescanneruse = var_enablescanneruse,
			         enablepostvoid = var_enablepostvoid,
			     enableeodaddchecks = var_enableeodaddchecks,
			      enableeodexpenses = var_enableeodexpenses,
			     enableeodadjchecks = var_enableeodadjchecks,
			     loadoutadjustments = var_loadoutadjustments,
			      enableaddcustomer = var_enableaddcustomer,
 			        enablestockicon = var_enablestockicon,
		 enablestartdaydatetimeedit = var_enablestartdaydatetimeedit,
				   enabledelayprint = var_enabledelayprint,
				enforcecallsequence = var_enforcecallsequence,
					 enablefoclimit = var_enablefoclimit,
			 enablecashonlydiscount = var_enablecashonlydiscount,
				 reqeodnosalereport = var_reqeodnosalereport,
		   generatehhcseqfromboflag = var_generatehhcseqfromboflag,
					   enablenosale	= var_enablenosale,
				 reqeodnondelreport = var_reqeodnondelreport,
				  allowpopulateload = var_allowpopulateload,
						cashbalance	= var_cashbalance,
					  allowgctocash = var_allowgctocash,
			 allowroutestartdayflag	= var_allowroutestartdayflag,
			 	 reqeodprcchgreport = var_reqeodprcchgreport,
					  invenoversell = var_invenoversell,
				  enabledamagedtrxn = var_enabledamagedtrxn,
			 reqeodnonscannedreport = var_reqeodnonscannedreport,
			  loadaccessafterunload = var_loadaccessafterunload,
			    reqeododomlogreport = var_reqeododomlogreport,
				   usesalesdateflag = var_usesalesdateflag,
				  displayinvsummary = var_displayinvsummary,
				 includeloadrequest = var_includeloadrequest,
						creditlimit = var_creditlimit,
				defaultdeliverydays = var_defaultdeliverydays,
				loadreqrolluporders = var_loadreqrolluporders,
					   depotprinter = var_depotprinter,
					    tlockstatus = var_tlockstatus,
					  loadreqmethod = var_loadreqmethod,
					   routeprinter = var_routeprinter,
					      routetype = var_routetype,
				 reqeodexceptionrpt = var_reqeodexceptionrpt,
				    passwordarray01 = var_passwordarray1,
					passwordarray07 = var_passwordarray7,
					passwordarray02 = var_passwordarray2,
					passwordarray08 = var_passwordarray8,
					passwordarray03 = var_passwordarray3,
					passwordarray09 = var_passwordarray9,
					passwordarray04 = var_passwordarray4,
					passwordarray13 = var_passwordarray13,
					passwordarray16 = var_passwordarray16,
					passwordarray11 = var_passwordarray11,
				  inventoryvariance = var_inventoryvariance,
				 reqeodpromosreport = var_reqeodpromosreport,
			 inventoryreportcontrol = var_inventoryreportcontrol,
		 enablestartdayrtewkdayedit = var_enablestartdayrtewkdayedit,
					itemcodedisplay = var_itemcodedisplay,
							created = var_modified,
						  modified	= var_modified,
							  cdat	= CURRENT_DATE(),
							  mdat	= CURRENT_DATE();				
	
	
	-- For Combo Box	
	SELECT routecode AS id,routecode AS val FROM routemaster WHERE routetmpl	= 1;
	
	-- For Route Item Group
	CALL sp_combo_routeitemgrp();
	
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Route Template','routemaster',@last_id,var_modified,'Add');	
	
		
    END */$$
