/* Procedure structure for procedure `sp_add_organization_route_addroute_template` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_organization_route_addroute_template` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_organization_route_addroute_template`(
	IN var_created VARCHAR(20),	
	IN var_password1 INT(4),
	IN var_password2 INT(4),
	IN var_password3 INT(4),
	IN var_password4 INT(4),
	IN var_password5 INT(4),
	IN var_passwordarray01 INT(4),
	IN var_passwordarray02 INT(4),
	IN var_passwordarray03 INT(4),
	IN var_passwordarray04 INT(4),
	IN var_passwordarray05 INT(4),
	IN var_passwordarray06 INT(4),
	IN var_passwordarray07 INT(4),
	IN var_passwordarray08 INT(4),
	IN var_passwordarray09 INT(4),
	IN var_passwordarray10 INT(4),
	IN var_passwordarray11 INT(4),
	IN var_passwordarray12 INT(4),
	IN var_passwordarray13 INT(4),
	IN var_passwordarray14 INT(4),
	IN var_passwordarray15 INT(4),
	IN var_passwordarray16 INT(4),
	IN var_routecatcode BIGINT,
	IN var_activestatus INT(4),	
	IN var_depotrouteflag INT(4),
	IN var_presalesorder SMALLINT(6),
	IN var_templatename VARCHAR(100),
	IN var_itemmustkey BIGINT
    )
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	
		INSERT INTO routemaster
			(
				routetmpl	,	
			password1,
			password2,
			password3,
			password4,
			password5,
			passwordarray01,			
			passwordarray02,			
			passwordarray03,			
			passwordarray04,
			passwordarray05,
			passwordarray06,
			passwordarray07,
			passwordarray08,
			passwordarray09,
			passwordarray10,
			passwordarray11,
			passwordarray12,
			passwordarray13,
			passwordarray14,
			passwordarray15,
			passwordarray16,
			routecatcode,
			activestatus,
			depotrouteflag,
			presalesorder,
			created,
			cdat,
			templatename,
			salesmancode,
			subareacode,
			vehiclenumber,
			itemmustkey			
			)
			VALUES
			(1,
			var_password1,
			var_password2,
			var_password3,
			var_password4,
			var_password5,
			var_passwordarray01,			
			var_passwordarray02,			
			var_passwordarray03,			
			var_passwordarray04,
			var_passwordarray05,
			var_passwordarray06,
			var_passwordarray07,
			var_passwordarray08,
			var_passwordarray09,
			var_passwordarray10,
			var_passwordarray11,
			var_passwordarray12,
			var_passwordarray13,
			var_passwordarray14,
			var_passwordarray15,
			var_passwordarray16,			
			var_routecatcode,
			var_activestatus,
			var_depotrouteflag,
			var_presalesorder,
			var_created,
			CURRENT_DATE(),
			var_templatename,
			NULL,
			NULL,
			NULL,
			var_itemmustkey
			);
			
			SELECT LAST_INSERT_ID() INTO @last_id;
			SELECT @last_id AS result;
			-- Insert Log
			CALL sp_add_logmaster_information('1','Route Master','routemaster',@last_id,var_created,'Add');
			
			
		
    END */$$
DELIMITER ;

