/* Procedure structure for procedure `sp_add_promotions_advancepricing_addnewpricingkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advancepricing_addnewpricingkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advancepricing_addnewpricingkey`(
	IN var_description VARCHAR(50),
	IN var_arbdescription VARCHAR(50),
	IN var_active SMALLINT(6),
	IN var_created VARCHAR(30),
	IN var_pricingplankey BIGINT,
	IN var_customer VARCHAR(30)
)
BEGIN
    
    INSERT INTO customerpricingplanheader1 SET
				DESCRIPTION = var_description,
				arbdescription 	= var_arbdescription,
				activeindicator	= var_active;
	
	
	SELECT LAST_INSERT_ID() INTO @pricekey;
	
	-- SELECT COUNT(*) INTO rowcnt FROM customerpricing1 WHERE  pricingplankey = var_pricingplankey;
	
	-- IF rowcnt = 0 THEN
	INSERT INTO customerpricing1 
		(customerpricingkey,DESCRIPTION,arbdescription,ACTIVE)
			SELECT customerpricingkey,DESCRIPTION,arbdescription,ACTIVE 
					FROM pricingplanheader1 
					WHERE customerpricingkey = var_pricingplankey;
	
	SELECT LAST_INSERT_ID() INTO @last_id;
	
	UPDATE customerpricing1 SET 
				startdate 		= CURRENT_DATE(),
				enddate			= CURRENT_DATE(),
				created 		= var_created,
				cdat 			= CURRENT_DATE(),
				modified 		= var_created,
				mdat 			= CURRENT_DATE(),
				pricingplankey		= @pricekey
			WHERE	primary_key = @last_id;
    
	-- END IF;
	update customermaster set pricingkey = @pricekey where customercode = var_customer;
	select @pricekey as pricingkey;
	
END */$$
DELIMITER ;

