/* Procedure structure for procedure `sp_add_promotions_advancepricing_pricingkeyitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advancepricing_pricingkeyitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advancepricing_pricingkeyitemgrid`(IN price_key INT,IN input_text TEXT, IN tot_row INT,in var_created varchar(30))
BEGIN
    
    DECLARE from_start INT;
    DECLARE plan_id VARCHAR(10);
    DECLARE last_id INT;
    DECLARE rowcnt INT DEFAULT 0;
    
    SET from_start = 1;
    
    WHILE from_start <= tot_row DO
    
	SET last_id = '';
    
	SET plan_id = split(input_text,',',from_start);
	SELECT COUNT(*) INTO rowcnt FROM customerpricing1 WHERE (customerpricingkey = plan_id AND pricingplankey = price_key);
	
	IF rowcnt = 0 THEN
	INSERT INTO customerpricing1 
		(customerpricingkey,description,arbdescription,active)
			SELECT customerpricingkey,description,arbdescription,active 
					FROM pricingplanheader1 
					WHERE customerpricingkey = plan_id;
	
	SELECT LAST_INSERT_ID() INTO last_id;
	
	UPDATE customerpricing1 SET 
				startdate 		= CURRENT_DATE(),
				enddate			= CURRENT_DATE(),
				created 		= var_created,
				cdat 			= CURRENT_DATE(),
				modified 		= var_created,
				mdat 			= CURRENT_DATE(),
				pricingplankey	= price_key
			WHERE	primary_key = last_id;
    
	END IF;
	
	SET  from_start = from_start + 1;
	
    END WHILE;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advancepricing_pricingplanitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advancepricing_pricingplanitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advancepricing_pricingplanitemgrid`(
                    IN p_itemcode 			BIGINT,
                    IN p_unitspercase     	DECIMAL(19,4),
					IN p_stdsalesunitprice  DECIMAL(19,4),
					IN p_stdreturnunitprice	DECIMAL(19,4),
                    IN p_stdsalescaseprice  DECIMAL(19,4),
					IN p_stdreturncaseprice	DECIMAL(19,4),
                    IN p_salesprice			DECIMAL(19,4),
                    IN p_salescaseprice     DECIMAL(19,4),
					IN p_returnprice     	DECIMAL(19,4),
                    IN p_returncaseprice	DECIMAL(19,4),
                    IN p_customerpricingkey	BIGINT,
                    IN p_createdby 			VARCHAR(50)
			)
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO rowcnt FROM pricingdetail1 WHERE ( customerpricingkey = p_customerpricingkey AND itemcode = p_itemcode);
	
	IF rowcnt > 0 THEN
		SELECT 'duplicate' AS 'result';
	ELSE
		INSERT INTO pricingdetail1  SET 
						itemcode = p_itemcode,
						unitspercase = p_unitspercase,
						stdsalesunitprice = p_stdsalesunitprice,
						stdreturnunitprice = p_stdreturnunitprice,
						stdsalescaseprice = p_stdsalescaseprice,
						stdreturncaseprice = p_stdreturncaseprice,
						salesprice =p_salesprice,
						salescaseprice = p_salescaseprice,
						returnprice = p_returnprice,
						returncaseprice = p_returncaseprice,
						customerpricingkey = p_customerpricingkey,
						created = p_createdby,
						cdat = CURRENT_DATE(),
						modified = p_createdby,
						mdat = CURRENT_DATE();
		SELECT "added" AS 'result';
	END IF;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advance_addpromotionkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advance_addpromotionkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advance_addpromotionkey`(		
	    IN txt_description VARCHAR(255),
	    IN ddl_type BIGINT,
	    IN txt_arbdescription VARCHAR(255),
	    IN ddl_activeindicator INT,
	    in created_by varchar(30)
	)
BEGIN
	DECLARE insid INT DEFAULT 0;
	INSERT INTO promokeyheader  SET 
									description 	= txt_description,
									`type` 			= ddl_type,
									arbdescription 	= txt_arbdescription,
									activeindicator = ddl_activeindicator,
									created 		= created_by,
									cdat 			= CURRENT_DATE();
	
	SELECT LAST_INSERT_ID() INTO insid;
	
	SELECT insid;
	
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Promotion Key','promokeyheader',insid,createdby,'Add');	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advance_addpromotionplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advance_addpromotionplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advance_addpromotionplan`(		
	    IN txt_plandescription VARCHAR(50),
	    IN txt_arbplandescription VARCHAR(50),
	    IN ddl_promotiontypecode BIGINT,
	    IN ddl_activeindicator INT,
	    IN ddl_rangebasis BIGINT,
	    IN ddl_amountbasis BIGINT,
	    IN ddl_exclusionoption BIGINT,
	    IN ddl_qualificationgroup BIGINT,
	    IN ddl_assignmentgroup BIGINT,
	    IN txt_assignmentnumber BIGINT,
   	    IN chk_iscase INT,
   	    IN chk_onetimeuse INT,
   	    IN chk_enforcepromotion INT,
   	    IN chk_repeatrange INT,
   	    IN var_createdby VARCHAR(30)
	)
BEGIN
	DECLARE insid INT DEFAULT 0;
	INSERT INTO promoplandetail  SET 
		qualificationgroup 	= ddl_qualificationgroup,
		assignmentgroup 	= ddl_assignmentgroup,
		rangebasis 			= ddl_rangebasis,
		amountbasis 		= ddl_amountbasis,
		exclusionoption 	= ddl_exclusionoption,
		-- assignmentnumber 	= ddl_assignmentgroup , -- this for temporary txt_assignmentnumber,
		plandescription 	= txt_plandescription,
		arbplandescription 	= txt_arbplandescription,
		promotiontypecode 	= ddl_promotiontypecode,
		iscase 				= chk_iscase,
		onetimeuse 			= chk_onetimeuse,
		repeatrange 		= chk_repeatrange,
		enforcepromotion 	= chk_enforcepromotion,
		created 			= var_createdby,
		modified 			= var_createdby,
		cdat 				= CURRENT_DATE(),
		mdat 				= CURRENT_DATE();
	SELECT LAST_INSERT_ID() INTO insid;
		
	/* Added By Hiren dave because we need to add unique value into assigment number */
	UPDATE promoplandetail SET assignmentnumber = insid WHERE plannumber = insid;
	
	INSERT INTO promoplanheader  SET 
		plannumber 		= insid,
		plandescription 	= txt_plandescription,
		arbplandescription 	= txt_arbplandescription,
		activeindicator 	= ddl_activeindicator,
		created 			= var_createdby,
		modified 			= var_createdby,
		cdat 				= CURRENT_DATE(),
		mdat 				= CURRENT_DATE();
		
	SELECT insid AS lastid;
	
	INSERT INTO promokeydetail  SET 
				promotiontypecode 	= ddl_promotiontypecode,
				qualificationgroup  = ddl_qualificationgroup,				
				promotiontypecode 	= ddl_promotiontypecode,
				assignmentgroup 	= ddl_assignmentgroup,
				rangebasis 			= ddl_rangebasis,
				exclusionoption 	= ddl_exclusionoption,
				amountbasis 		= ddl_amountbasis,
				plannumber 			= insid,
				created 			= var_createdby,
				modified 			= var_createdby,
				cdat 				= CURRENT_DATE(),
				mdat 				= CURRENT_DATE();
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Promotion Plan','promoplandetail',insid,createdby,'Add');	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advance_promotionkeyitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advance_promotionkeyitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advance_promotionkeyitemgrid`(IN promo_key INT,IN input_text TEXT, IN tot_row INT)
BEGIN
    
    DECLARE from_start INT;
    DECLARE plan_id VARCHAR(10);
    DECLARE last_id INT;
    DECLARE rowcnt INT DEFAULT 0;
    DECLARE n_plan_id INT DEFAULT 0;
    
    SET from_start = 1;
    
    WHILE from_start <= tot_row DO
    
	SET last_id = '';
    
	SET plan_id = split(input_text,',',from_start);
	SELECT COUNT(*) INTO rowcnt FROM promokeydetail WHERE (plannumber = plan_id AND promotionkey = promo_key);
	
	IF rowcnt = 0 THEN
	INSERT INTO promokeydetail 
		(plannumber,qualificationgroup,assignmentgroup,assignmentnumber,performcriteriakey,rangebasis,amountbasis,exclusionoption,iscase)
			SELECT plannumber,qualificationgroup,assignmentgroup,assignmentnumber,performcriteriakey,rangebasis,amountbasis,exclusionoption,iscase 
					FROM promoplandetail 
					WHERE plannumber = plan_id;
	
	SELECT LAST_INSERT_ID() INTO last_id;
	
	-- Get promotiontypecode from promoplandetail	
	SELECT promotiontypecode INTO @promo_code FROM promoplandetail WHERE plannumber = plan_id;
	
	UPDATE promokeydetail SET 
				startdate 		= CURRENT_DATE(),
				enddate			= CURRENT_DATE(),
				promotionkey 		= promo_key,
				promotiontypecode 	= @promo_code,
				active 			= 1	
			WHERE	primary_key = last_id;
    
	END IF;
	
	SET  from_start = from_start + 1;
	
    END WHILE;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_advance_promotionplanitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_advance_promotionplanitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_advance_promotionplanitemgrid`(
                    IN txt_rangelow 		BIGINT,
                    IN txt_rangehigh     	BIGINT,
					IN txt_repeatingrange   BIGINT,
                    IN txt_promotionamount	decimal(30,10),
					IN txt_plannumber    	BIGINT,
                    IN txt_assignmentnumber	BIGINT,
                    in var_createdby 		varchar(50)
    )
BEGIN
	DECLARE range_high BIGINT;
	DECLARE range_low BIGINT;
	DECLARE counter INT;
	DECLARE final_range_val BIGINT;
	
	SELECT MAX(rangehigh),MAX(rangelow),COUNT(*) INTO range_high,range_low,counter FROM promotionassignmentadvanced WHERE plannumber = txt_plannumber;
	IF range_high > range_low THEN
		SET final_range_val = range_high;
	ELSE
		SET final_range_val = range_low;
	END IF;
	
	if txt_rangelow > final_range_val or counter = 0 then
		
		INSERT INTO promotionassignmentadvanced  SET 
		rangelow 			= txt_rangelow,
		rangehigh 			= txt_rangehigh,
		repeatingrange 		= txt_repeatingrange,
		promotionamount 	= txt_promotionamount,
		assignmentnumber 	= txt_assignmentnumber,
		plannumber 			= txt_plannumber,
		created 			= var_createdby,
		cdat 				= CURRENT_DATE(),
		modified 			= var_createdby,
		mdat 				= CURRENT_DATE();
		
		select LAST_INSERT_ID() as result;		
		
	else
		select '0' as result,final_range_val; -- return 0 means value is less than the exist value in DB.
	end if;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_customer_addauthorizegroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_customer_addauthorizegroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_customer_addauthorizegroup`(
                    IN var_groupnumber     	BIGINT,
                    IN var_groupdescription     VARCHAR(50),
                    IN var_arbgroupdescription	VARCHAR(50),
                    IN var_itemcode		INT,
                    IN var_grouptype		INT,
                    in var_created varchar(30),
                    in var_pc_price decimal(18,4),
                    IN var_case_price DECIMAL(18,4),
                    in var_itemqty bigint(20)
    )
BEGIN
	DECLARE cnt INT DEFAULT 0;
	DECLARE rowcnt INT DEFAULT 0;
	declare grptype varchar(250);
	
	SELECT COUNT(*) INTO cnt FROM productgroupheader WHERE groupnumber = var_groupnumber;
	
	IF cnt = 0 THEN
		INSERT INTO productgroupheader
			(groupdescription,
			arbgroupdescription,
			grouptype,
			created,
			cdat  )
		VALUES
		(var_groupdescription,
		var_arbgroupdescription,
		var_grouptype,
		 var_created,
		 CURRENT_DATE());	
		
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS var_groupnumber;
		-- Insert Log
		
		if var_grouptype = 1 then 
			set grptype = 'Qualification Group';
		elseif var_grouptype = 2 THEN 
			SET grptype = 'Assignment Group';
		else
			SET grptype = 'Customer Authorize Group';
		end if;
		
		CALL sp_add_logmaster_information('1',grptype,'productgroupheader',@last_id,var_created,'Add');
		
	END IF;
	
	IF var_itemcode > 0 THEN
		SELECT COUNT(*) INTO rowcnt FROM productgroupdetail 
		WHERE groupnumber = var_groupnumber AND itemcode = var_itemcode;
	
		IF rowcnt > 0 THEN
			SELECT 'duplicate';
		ELSE
			INSERT INTO productgroupdetail
			(groupnumber,
			itemcode,
			itemqty,
			promopcprice,
			promocaseprice  )
			VALUES
			(var_groupnumber,
			var_itemcode,
			var_itemqty,
			var_pc_price,
			var_case_price
			 );
			SELECT var_groupnumber;
		END IF;
	END IF;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_customer_addfreegoods` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_customer_addfreegoods` */;

DELIMITER $$

