/* Procedure structure for procedure `sp_add_promotions_customer_addfreegoodsgriddetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_customer_addfreegoodsgriddetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_customer_addfreegoodsgriddetail`(
	   
	   IN p_creationdate VARCHAR(50),
	   IN p_remarks VARCHAR(50),
	   IN p_startdate VARCHAR(50),
	   IN p_enddate VARCHAR(50),
	   IN p_active BIGINT,
	   IN p_depotcode BIGINT,
	   IN p_customercode BIGINT,
	   IN p_itemcode     	BIGINT,
	   IN p_freequantity     	BIGINT,
	   IN createdby VARCHAR(30)
	)
BEGIN
	
	INSERT INTO `customer_foc`(
		customercode, 	
		creationdate,
		remarks,
		startdate,
		enddate,
		active,
		depotcode
	) VALUES (
		p_customercode,
		p_creationdate,
		p_remarks,
		p_startdate,
		p_enddate,
		p_active,
		p_depotcode
	);
	
	SELECT LAST_INSERT_ID() INTO @last_id;	
	SELECT "added" AS 'result',@last_id AS lastid;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Customer Free Contract','customer_foc',@last_id,createdby,'Add');
	
	
	INSERT INTO customer_foc_detail(
			contractid,
			customercode,
			itemcode,
			freequantity,
			remarks,
			editdate
		)VALUES(
			@last_id,
			p_customercode,
			p_itemcode,
			p_freequantity,
			'',
			CURRENT_DATE()
		);
		
		INSERT INTO customer_foc_balance(
			contractid,
			customercode,
			itemcode,
			originalqty,
			balanceqty,
			startdate
		)VALUES(
			@last_id,
			p_customercode,
			p_itemcode,
			p_freequantity,
			p_freequantity,
			CURRENT_DATE()
		);
		
END */$$
