/* Procedure structure for procedure `sp_add_promotions_loyality_customer_addauthorizegroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_loyality_customer_addauthorizegroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_loyality_customer_addauthorizegroup`(
                    IN var_groupnumber     	BIGINT,
                    IN var_groupdescription     VARCHAR(50),
                    IN var_arbgroupdescription	VARCHAR(50),
                    IN var_itemcode		INT,
                    IN var_grouptype		INT,
                    IN var_created VARCHAR(30),
                    IN var_pc_price DECIMAL(18,4),
                    IN var_case_price DECIMAL(18,4),
                    IN var_itemqty BIGINT(20)
    )
BEGIN
	DECLARE cnt INT DEFAULT 0;
	DECLARE rowcnt INT DEFAULT 0;
	DECLARE grptype VARCHAR(250);
	
	SELECT COUNT(*) INTO cnt FROM productgroupheader WHERE groupnumber = var_groupnumber;
	
	IF cnt = 0 THEN
		INSERT INTO productgroupheader
			(groupdescription,
			arbgroupdescription,
			grouptype,
			created,
			cdat,divison)
		VALUES
		(var_groupdescription,
		var_arbgroupdescription,
		var_grouptype,
		 var_created,
		 CURRENT_DATE(),'2');	
		
		SELECT LAST_INSERT_ID() INTO @last_id;
		SELECT @last_id AS var_groupnumber;
		-- Insert Log
		
		IF var_grouptype = 1 THEN 
			SET grptype = 'Qualification Group';
		ELSEIF var_grouptype = 2 THEN 
			SET grptype = 'Assignment Group';
		ELSE
			SET grptype = 'Customer Authorize Group';
		END IF;
		
		CALL sp_add_logmaster_information('1',grptype,'productgroupheader',@last_id,var_created,'Add');
		
	END IF;
	
	IF var_itemcode > 0 THEN
		SELECT COUNT(*) INTO rowcnt FROM productgroupdetail 
		WHERE groupnumber = var_groupnumber AND itemcode = var_itemcode;
	
		IF rowcnt > 0 THEN
			SELECT 'duplicate';
		ELSE
			INSERT INTO productgroupdetail
			(groupnumber,
			itemcode,
			itemqty,
			promopcprice,
			promocaseprice  )
			VALUES
			(var_groupnumber,
			var_itemcode,
			var_itemqty,
			var_pc_price,
			var_case_price
			 );
			SELECT var_groupnumber;
		END IF;
	END IF;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_loyality_loyalitykeyitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_loyality_loyalitykeyitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_loyality_loyalitykeyitemgrid`(IN price_key INT,IN input_text TEXT, IN tot_row INT,IN var_created VARCHAR(30))
BEGIN
    
    DECLARE from_start INT;
    DECLARE plan_id VARCHAR(10);
    DECLARE last_id INT;
    DECLARE rowcnt INT DEFAULT 0;
    
    SET from_start = 1;
    
    WHILE from_start <= tot_row DO
    
	SET last_id = '';
    
	SET plan_id = split(input_text,',',from_start);
	SELECT COUNT(*) INTO rowcnt FROM loyaltykeydetail WHERE (loyaltyplanid = plan_id AND loyaltykeyid = price_key);
	
	IF rowcnt = 0 THEN
	
	INSERT INTO loyaltykeydetail SET
				loyaltykeyid = price_key,
				loyaltyplanid 	= plan_id,
				startdate	= CURRENT_DATE(),
				enddate=CURRENT_DATE();
				
	
	SELECT LAST_INSERT_ID() INTO last_id;
	
	UPDATE customerpricing1 SET 
				startdate 		= CURRENT_DATE(),
				enddate			= CURRENT_DATE(),				
				loyaltykeyid	= price_key
			WHERE	primarykey = last_id;
    
	END IF;
	
	SET  from_start = from_start + 1;
	
    END WHILE;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_loyality_loyalityplanitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_loyality_loyalityplanitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_loyality_loyalityplanitemgrid`(
