/* Procedure structure for procedure `sp_add_promotions_supervisor_addfreegoodsgriddetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotions_supervisor_addfreegoodsgriddetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotions_supervisor_addfreegoodsgriddetail`(
	   
	   IN p_creationdate VARCHAR(50),
	   IN p_remarks VARCHAR(50),
	   IN p_startdate VARCHAR(50),
	   IN p_enddate VARCHAR(50),
	   IN p_active BIGINT,
	   IN p_depotcode varchar(10),
	   IN p_customercode BIGINT,
	   IN p_itemcode     	BIGINT,
	   IN p_freequantity     	BIGINT,
	   IN createdby VARCHAR(30)
	)
BEGIN
	DECLARE rowcnt INT DEFAULT 0;
	SELECT COUNT(*) INTO rowcnt FROM supervisor_foc WHERE ( supervisorcode = p_customercode AND (p_startdate between startdate And  enddate OR p_enddate BETWEEN startdate AND  enddate  ));
	-- select rowcnt;
	if(rowcnt=0) THEN
	
	INSERT INTO `supervisor_foc`(
		supervisorcode, 	
		creationdate,
		remarks,
		startdate,
		enddate,
		active,
		depotcode
	) VALUES (
		p_customercode,
		p_creationdate,
		p_remarks,
		p_startdate,
		p_enddate,
		p_active,
		p_depotcode
	);
	
	SELECT LAST_INSERT_ID() INTO @last_id;	
	SELECT "added" AS 'result',@last_id AS lastid;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Supervisor Free Contract','supervisor_foc',@last_id,createdby,'Add');
	
	
	INSERT INTO supervisor_foc_detail(
			contractid,
			supervisorcode,
			itemcode,
			freequantity,
			remarks,
			editdate
		)VALUES(
			@last_id,
			p_customercode,
			p_itemcode,
			p_freequantity,
			'',
			CURRENT_DATE()
		);
		
		INSERT INTO supervisor_foc_balance(
			contractid,
			supervisorcode,
			itemcode,
			originalqty,
			balanceqty,
			startdate
		)VALUES(
			@last_id,
			p_customercode,
			p_itemcode,
			p_freequantity,
			p_freequantity,
			CURRENT_DATE()
		);
		ELSE
		select 'Duplicate Record';
		end if;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotions_supervisor_freegoodsgrid` */

