/* Procedure structure for procedure `sp_add_promotion_advancepricing_addnewpricingplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotion_advancepricing_addnewpricingplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotion_advancepricing_addnewpricingplan`(
			IN var_description VARCHAR(50),
			IN var_arbdescription VARCHAR(50),
			IN var_type INT(4),
			IN var_active SMALLINT(6),
			IN var_country BIGINT(20),
			IN createdby VARCHAR(30)
		)
BEGIN
	
	INSERT INTO pricingplanheader1 SET
				DESCRIPTION 	= var_description ,
				arbdescription 	= var_arbdescription ,
				`type` 			= var_type ,
				ACTIVE 			= var_active ,
				country 		= var_country;
				
	SELECT LAST_INSERT_ID() INTO @last_id;
	
	INSERT INTO pricingdetail1   (itemcode,unitspercase,	stdsalesunitprice,stdreturnunitprice,stdsalescaseprice,	stdreturncaseprice,salesprice,salescaseprice,returnprice ,	returncaseprice,customerpricingkey,created,cdat)
SELECT p.itemcode,unitspercase,	defaultsalesprice,defaultreturnprice,caseprice,	i.returncaseprice,salesprice,salesprice,returnprice ,returnprice,@last_id,'admin',CURDATE()
FROM temp_prc_detl_1 AS p 
LEFT JOIN itemmaster i ON p.itemcode = i.actualitemcode;
	
Truncate table temp_prc_detl_1;	
	SELECT @last_id AS last_id;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Pricing Plan','pricingplanheader1',@last_id,createdby,'Add');
	
END */$$
DELIMITER ;

