/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotion_advancepricing_addpricingplan`(
			IN var_description varchar(50),
			in var_arbdescription VARCHAR(50),
			in var_type int(4),
			in var_active SMALLINT(6),
			in var_country BIGINT(20),
			IN createdby VARCHAR(30)
		)
BEGIN
	
	insert into pricingplanheader1 set
				description 	= var_description ,
				arbdescription 	= var_arbdescription ,
				`type` 			= var_type ,
				active 			= var_active ,
				country 		= var_country;
				
	SELECT LAST_INSERT_ID() INTO @last_id;
	SELECT @last_id AS last_id;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Pricing Plan','pricingplanheader1',@last_id,createdby,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_promotion_advancepricing_addtemppriceplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_promotion_advancepricing_addtemppriceplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_promotion_advancepricing_addtemppriceplan`(
IN var_itemcode  BIGINT,
IN var_saleprc DECIMAL(18,3),
IN var_retprc DECIMAL(18,3)
)
BEGIN
	
	SELECT COALESCE(MAX(customerpricingkey),0)+1 INTO @planno FROM pricingplanheader1;
	select IFNULL(COUNT(*),0) INTO @itemincnt FROM temp_prc_detl_1 WHERE itemcode = var_itemcode;
	select IFNULL(count(*),0) INTO @itemcnt from itemmaster where actualitemcode = var_itemcode AND caseprice = var_saleprc AND returncaseprice = var_retprc;
	if @itemincnt = 0 THEN 
		IF @itemcnt = 0 THEN
			 INSERT INTO temp_prc_detl_1
			 (
				CUSTOMERPRICINGKEY,
				itemcode,
				SALESPRICE,
				RETURNPRICE  
			)
			VALUES
			(
				@planno,
				var_itemcode,
				var_saleprc,
				var_retprc
			 );
		 END IF;
	ELSE 
	IF @itemcnt = 0 THEN
			 update  temp_prc_detl_1 SET 
			 
				CUSTOMERPRICINGKEY = @planno,
				itemcode = var_itemcode,
				SALESPRICE = var_saleprc,
				RETURNPRICE  = var_retprc
			
			Where CUSTOMERPRICINGKEY = @planno AND itemcode = var_itemcode;
		 END IF;
	END IF;
	
	 select @planno as newplan;
	 
END */$$
DELIMITER ;

