END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_routeitemgrouplog_information` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_routeitemgrouplog_information` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_routeitemgrouplog_information`(
					in counter int,
					in form_name varchar(100),
					in tblname varchar(100),
					in grpcode 	bigint(20),
					in itmcode text,
					in createdby varchar(30),
					in operationtype varchar(20)
				)
BEGIN
		DECLARE record_id INT;
		declare from_start int default 1;
		
		if operationtype = 'delete' then		
			set operationtype = 'Delete';
		end if;
		
		
		while from_start <= counter do
		
		SET record_id = split(itmcode,',',from_start);
		
			insert into routeitemgrouplog(formname,tablename,groupcode,itemcode,created,cdat,operation_type)values
				(form_name,tblname,grpcode,record_id,createdby,CURRENT_DATE(),operationtype);
			-- increment the value for getting next records.
			SET  from_start = from_start + 1;
		end while;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoiceadd_cashcollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoiceadd_cashcollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoiceadd_cashcollection`(
IN in_routekey INT,
IN in_visitkey INT,
IN in_amount DECIMAL(19,4),
IN in_check_no DECIMAL(18,0),
IN in_check_date VARCHAR(100),
IN in_bank_code  BIGINT(20),
IN in_cash INT
)
BEGIN
	IF in_cash = 0 THEN 
	
			IF (SELECT COUNT(routekey) FROM cashcheckdetail_temp WHERE routekey = in_routekey AND visitkey = in_visitkey ) > 0 THEN 
			
				UPDATE cashcheckdetail_temp SET 
				routekey =in_routekey,
				visitkey = in_visitkey,
				typecode ='0',
				amount = in_amount,
				checknumber = 0,
				checkdate =CURRENT_DATE(),
				hhctransactionkey = in_visitkey,
				bankcode =0 WHERE routekey = in_routekey AND visitkey =in_visitkey;
			ELSE
			
				INSERT INTO cashcheckdetail_temp(`routekey`,`visitkey`,`typecode`,`amount`,hhctransactionkey)
				VALUES(in_routekey,in_visitkey,"0",in_amount,in_visitkey);
			
			END IF;
	
	
	ELSE 
	
		IF (SELECT COUNT(routekey) FROM cashcheckdetail_temp WHERE routekey = in_routekey AND visitkey =in_visitkey) > 0 THEN 
			
			UPDATE cashcheckdetail_temp SET 	routekey =in_routekey,
							visitkey = in_visitkey,
							typecode ='1', 		
							amount = in_amount,
							checknumber = in_check_no,
							checkdate =STR_TO_DATE(in_check_date,'%d-%m-%Y'),	
							bankcode =in_bank_code,
							hhctransactionkey = in_visitkey
				  WHERE routekey = in_routekey AND visitkey =in_visitkey;
			
				
			ELSE	
				INSERT INTO cashcheckdetail_temp (routekey,visitkey,typecode,checknumber,amount,checkdate,bankcode,hhctransactionkey)
				VALUES(in_routekey,in_visitkey,"1",in_check_no,in_amount,STR_TO_DATE(in_check_date,'%d-%m-%Y'),in_bank_code,in_visitkey);
				
			END IF;
			
			
	 
	END IF;
	
	UPDATE invoiceheader_temp 
	SET 
	totalinvoiceamount=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0)),
	invoicebalance=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0)) - in_amount,
	amountpaid=in_amount,
	paymenttype=in_cash
	
	WHERE routekey=in_routekey 
	AND visitkey=in_visitkey ;
    
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoiceadd_detail1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoiceadd_detail1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoiceadd_detail1`(
IN var_invoicenumber DECIMAL(28,0),
IN var_documentnumber DECIMAL(28,0),
IN var_routecode DECIMAL(18,0),
IN var_customercode DECIMAL(18,0),
IN var_comment VARCHAR(200),
IN in_output BLOB
)
BEGIN
/* insert record into invoiceheader*/
DECLARE var_salesmancode INT;
DECLARE in_last_insert_id INT;
DECLARE in_route_key_code INT;
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_routecode;
	SELECT routekey INTO in_route_key_code FROM startendday 
	WHERE startendday.routecode=var_routecode
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	
	INSERT INTO invoiceheader_temp SET 
	
	transactiondate = DATE(CURRENT_DATE()),
	transactiontime = TIME(CURRENT_DATE()),  -- CONCAT(HOUR(CURRENT_DATE()),":",MINUTE(CURRENT_DATE()))
	actualtransactiondate = DATE(CURRENT_DATE()),
	routecode = var_routecode,
	salesmancode = var_salesmancode,
	customercode = var_customercode,
	comments = var_comment,
	record_flag ='0';
	SET in_last_insert_id =LAST_INSERT_ID();
	
	UPDATE invoiceheader_temp SET routekey =in_route_key_code , 
		         visitkey =in_last_insert_id  ,
			 invoicenumber = in_last_insert_id,
			 documentnumber = in_last_insert_id
	WHERE transactionkey =in_last_insert_id;
 
 -- retrun invoicehedere routekey,visitkey and transaction key
	SELECT in_last_insert_id AS invoice_transaction_key,
	in_last_insert_id AS visitkey ,
	in_route_key_code AS routekey ;
	
	CALL sp_add_transaction_invoiceadd_signaturedata(in_last_insert_id,in_route_key_code,in_last_insert_id,var_customercode,0,in_output);
	
	
	/* For inserting when next button press */
	INSERT INTO batchmaster_temp 
	SELECT quantity,batchdetailkey,batchnumber,expirydate,itemcode,0,0,0,0,0,0,0,0,in_last_insert_id,routekey
	FROM batchmaster
	WHERE routekey = in_route_key_code;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoiceadd_detail2` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoiceadd_detail2` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoiceadd_detail2`(
/* invoicedetail*/
IN in_transactionkey BIGINT,
IN var_routekey DECIMAL(28,0),
IN var_visitkey DECIMAL(28,0),
IN var_itemcode DECIMAL(18,0),
IN var_salesqty DECIMAL(18,0),
IN var_manualfreeqty DECIMAL(18,0),
IN var_returnqty DECIMAL(18,0),
IN var_buybackqty DECIMAL(18,0),
IN var_damagedqty DECIMAL(18,0),
IN var_expiryqty DECIMAL(18,0),
IN var_fixedrentqty DECIMAL(18,0),
IN var_sales_case_price DECIMAL(18,6),
IN var_sales_pcs_price DECIMAL(18,6),
IN var_goodreturn_case_price DECIMAL(18,6),
IN var_goodreturn_pcs_price DECIMAL(18,6),
IN var_return_case_price DECIMAL(18,6),
IN var_return_pcs_price DECIMAL(18,6),
IN var_freegood_reason INT,
IN var_return_reason INT,
IN var_buyback_reason INT,
IN var_damage_reason INT,
IN var_expiry_reason INT,
IN var_rental_reason INT,
IN var_sales_amount INT,
IN var_totalbuybackfreeamount DECIMAL(18,4)
)
BEGIN
DECLARE in_returncaseprice DECIMAL(18,4);
DECLARE in_caseprice DECIMAL(18,4);
DECLARE in_sales_price DECIMAL(18,4);	
DECLARE in_sales_case_price DECIMAL(18,4);
DECLARE in_return_price DECIMAL(18,4);	
DECLARE in_return_case_price DECIMAL(18,4);
DECLARE in_defaultgoodreturnprice DECIMAL(18,4);
DECLARE in_defaultgoodreturncaseprice DECIMAL(18,4);
DECLARE in_last_insert_id INT;
DECLARE in_batchdetailkey INT;
	
	SELECT itemmaster.defaultsalesprice AS sales_price,
	       itemmaster.defaultreturnprice AS return_price,
	        itemmaster.caseprice AS sales_case_price,
		itemmaster.returncaseprice AS return_case_price,
		itemmaster.defaultgoodreturnprice, 
		itemmaster.defaultgoodreturncaseprice
	INTO 
		in_sales_price,
		in_return_price,
		in_sales_case_price,
		in_return_case_price,
		in_defaultgoodreturnprice,
		in_defaultgoodreturncaseprice
	FROM itemmaster
	WHERE itemmaster.actualitemcode =var_itemcode;
	
	SELECT batchdetailkey INTO in_batchdetailkey FROM batchexpirydetail_temp WHERE visitkey = var_visitkey LIMIT 1;
	
	INSERT INTO invoicedetail_temp SET 
	routekey 		= var_routekey,
	visitkey 		= var_visitkey,
	transactionkey 		= in_transactionkey,
	itemcode 		= var_itemcode,
	salesqty 		= var_salesqty,
	returnqty 		= var_returnqty,
	damagedqty 		= var_damagedqty,
	fixedrentqty		=var_fixedrentqty,
	freesampleqty 		= var_manualfreeqty,
	salesprice 		= var_sales_pcs_price,
	returnprice 		= var_return_pcs_price,
	-- promoqty 		= var_promoqty,
	manualfreeqty 		= var_manualfreeqty,
	expiryqty 		= var_expiryqty,
	returnfreeqty		= var_buybackqty,
	salescaseprice		= var_sales_case_price,
	returncaseprice 	= var_return_case_price,
	record_flag		= 1,
	mdat  			= CURRENT_DATE(),
	goodreturncaseprice     = var_goodreturn_case_price,
	goodreturnprice		= var_goodreturn_pcs_price,
	stdreturncaseprice	= in_return_case_price,
	stdgoodreturnprice 	= in_defaultgoodreturnprice,
	stdreturnprice		=in_return_price,
	stdsalescaseprice	=in_sales_case_price,
	stdsalesprice		=in_sales_price,
	stdgoodreturncaseprice	= in_defaultgoodreturncaseprice,
	batchdetailkey 		= in_batchdetailkey;
	
	
	
	SET in_last_insert_id =LAST_INSERT_ID();
	
	
	UPDATE invoicedetail_temp 
		SET invoicedetail_temp.sales_amount = (FLOOR(salesqty / var_sales_amount) * salescaseprice 
					+ ((salesqty % var_sales_amount) * salesprice))
	WHERE 
	invoicedetail_temp.primary_key = in_last_insert_id;
	
	
	
	UPDATE invoiceheader_temp,
	(SELECT 
		SUM(((id.salescaseprice) * FLOOR(salesqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((salesqty%im.unitspercase),3))) AS total_sales,
		SUM(((id.returncaseprice) * FLOOR(damagedqty/im.unitspercase))+(ROUND(id.returncaseprice,3) * ROUND((damagedqty%im.unitspercase),3))) AS total_damage,
		SUM(((id.goodreturncaseprice) * FLOOR(returnqty/im.unitspercase))+(ROUND(id.goodreturnprice,3) * ROUND((returnqty%im.unitspercase),3))) AS total_buyback,
		SUM(((id.salescaseprice) * FLOOR(promoqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((promoqty%im.unitspercase),3))) AS total_promo,
		SUM(((id.salescaseprice) * FLOOR(freesampleqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((freesampleqty%im.unitspercase),3))) AS total_free_sample_qty,
		SUM(((id.salescaseprice) * FLOOR(fixedrentqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((fixedrentqty%im.unitspercase),3))) AS total_manual_free_sample_qty,
		SUM(((id.returncaseprice) * FLOOR(expiryqty/im.unitspercase))+(ROUND(id.returncaseprice,3) * ROUND((expiryqty%im.unitspercase),3))) AS total_expiry_amount
		FROM invoicedetail_temp AS id
		LEFT JOIN itemmaster AS im  ON im.actualitemcode =id.itemcode
		JOIN invoiceheader_temp  AS ih
		WHERE ih.transactionkey = id.transactionkey
		AND ih.transactionkey =in_transactionkey
	) AS a
		
		SET invoiceheader_temp.totalsalesamount =IFNULL(a.total_sales,0) ,
		-- invoiceheader.totalinvoiceamount = (IFNULL(a.total_sales,0)-IFNULL(a.totalreturnamount,0)-IFNULL(a.total_damage,0)),
		invoiceheader_temp.totalreturnamount =a.total_buyback,
		invoiceheader_temp.totaldamagedamount =a.total_damage,
		invoiceheader_temp.totalexpiryamount =a.total_expiry_amount,
		invoiceheader_temp.totalfreesampleamount =total_manual_free_sample_qty,
		invoiceheader_temp.totalmanualfree =a.total_free_sample_qty,
		invoiceheader_temp.totalbuybackfreeamount = var_totalbuybackfreeamount
		WHERE invoiceheader_temp.transactionkey =in_transactionkey;
	 
   	
   
	UPDATE invoiceheader_temp SET 
		totalinvoiceamount=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0)),
		invoicebalance=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totalpromoamount,0)-IFNULL(totaldamagedamount,0))
		WHERE invoiceheader_temp.transactionkey =in_transactionkey;   
		
   
    IF var_manualfreeqty != 0 AND  var_freegood_reason != 0 THEN
     
      INSERT INTO invoicerxddetail_temp (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,reasoncode,quantity) 
                 VALUES(var_routekey,var_visitkey,in_transactionkey,1,var_itemcode,var_freegood_reason,var_manualfreeqty);
     END IF;
	
	IF var_buybackqty != 0 AND  var_buyback_reason != 0 THEN
     
      INSERT INTO invoicerxddetail_temp (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,reasoncode,quantity) 
                 VALUES(var_routekey,var_visitkey,in_transactionkey,3,var_itemcode,var_return_reason,var_buybackqty);
     END IF;	
	
      IF var_returnqty != 0 AND  var_return_reason != 0 THEN
     
      INSERT INTO invoicerxddetail_temp (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,reasoncode,quantity) 
                 VALUES(var_routekey,var_visitkey,in_transactionkey,3,var_itemcode,var_return_reason,var_returnqty);
     END IF;
     
     IF var_damagedqty != 0 AND  var_damage_reason != 0 THEN
     
      INSERT INTO invoicerxddetail_temp (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,reasoncode,quantity) 
                 VALUES(var_routekey,var_visitkey,in_transactionkey,2,var_itemcode,var_damage_reason,var_damagedqty);
     END IF;
     
     
     IF var_expiryqty != 0 AND  var_expiry_reason != 0 THEN
     
      INSERT INTO invoicerxddetail_temp (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,reasoncode,quantity) 
                 VALUES(var_routekey,var_visitkey,in_transactionkey,2,var_itemcode,var_expiry_reason,var_expiryqty);
     END IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoiceadd_promotion` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoiceadd_promotion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoiceadd_promotion`(
IN in_routekey INT,
IN in_visitkey INT,
IN in_customercode INT,
IN in_assignment_no INT,
IN in_plannumber INT,
IN in_rangevalue INT,
IN in_promotiontypecode INT   ,
IN invoice_transaction_key  INT,
IN in_promotion_amount DECIMAL(19,4) ,   
IN in_rangelow INT,    
IN in_repeatingrange INT
 )
BEGIN
IF in_promotiontypecode = 0 THEN
	
	INSERT INTO promotiondetail
	(routekey,visitkey,transactionkey,itemtransactiontype,itemcode,promotiontypecode,promotionamount,
	oldpromotionamount,promotionplannumber,assignmentkey,weighted,record_flag,salesamount,issync,rangelow,repeatingrange) 
	
	 SELECT in_routekey,in_visitkey,invoice_transaction_key,0, productgroupdetail.itemcode,in_promotiontypecode,
	 FORMAT((((salesqty / itemmaster.unitspercase)  *  (IF (p.salescaseprice IS NULL, itemmaster.caseprice ,p.salescaseprice))) +  ((salesqty % itemmaster.unitspercase)  * invoicedetail.salesprice) -
	 ((salesqty / itemmaster.unitspercase) *  productgroupdetail.promocaseprice) +  ((salesqty % itemmaster.unitspercase) * productgroupdetail.promopcprice)),4) AS promoamount, 
	  FORMAT(((salesqty / itemmaster.unitspercase)  *  (IF (p.salescaseprice IS NULL, itemmaster.caseprice ,p.salescaseprice))) +  ((salesqty % itemmaster.unitspercase)  * invoicedetail.salesprice),4) AS SalesAmount,
	 in_plannumber,in_assignment_no,'0','1',
	  FORMAT(((salesqty / itemmaster.unitspercase)  *  (IF (p.salescaseprice IS NULL, itemmaster.caseprice ,p.salescaseprice))) +  ((salesqty % itemmaster.unitspercase)  * invoicedetail.salesprice),4) AS SalesAmount,
	 '0',in_rangelow,in_repeatingrange
	
	 
	 FROM promokeydetail 
	 INNER JOIN promotionassignmentadvanced ON promotionassignmentadvanced.assignmentnumber=promokeydetail.assignmentnumber 
	 INNER JOIN productgroupdetail ON  promotionassignmentadvanced.promotionamount = productgroupdetail.groupnumber 
	 INNER JOIN invoicedetail ON productgroupdetail.itemcode = invoicedetail.itemcode 
					AND invoicedetail.routekey = in_routekey
					AND invoicedetail.visitkey  = in_visitkey 
	 INNER JOIN itemmaster ON itemmaster.actualitemcode = productgroupdetail.itemcode 
	 LEFT JOIN pricingdetail1 p ON p.itemcode = productgroupdetail.itemcode 
					AND p.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) 
					FROM customerpricing1 JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey 
					AND customercode = in_customercode) 
	 WHERE promokeydetail.assignmentnumber = in_assignment_no 
	 AND promokeydetail.promotionkey = (SELECT promotionkey FROM customermaster  WHERE customercode =in_customercode) 
	 AND promokeydetail.plannumber =in_plannumber;
	 
	
	 
	ELSEIF in_promotiontypecode = 5 OR in_promotiontypecode = 6 THEN
	
	INSERT INTO promotiondetail
	(routekey,visitkey,transactionkey,itemtransactiontype,itemcode,promotiontypecode,promotionamount,
	oldpromotionamount,promotionplannumber,assignmentkey,weighted,record_flag,salesamount,issync,rangelow,repeatingrange) 
	
	
	SELECT in_routekey,in_visitkey,invoice_transaction_key,'0',GROUP_CONCAT(productgroupdetail.itemcode) AS itemcode,
	in_promotiontypecode,
	in_promotion_amount,
	FORMAT(SUM(((salesqty / itemmaster.unitspercase)  * IF(p.salescaseprice IS NULL, itemmaster.caseprice ,  p.salescaseprice)) + ((salesqty % itemmaster.unitspercase) * invoicedetail.salesprice)),4) AS SalesAmount,
	in_plannumber,in_assignment_no,'0','1',
	FORMAT(SUM(((salesqty / itemmaster.unitspercase)  * IF(p.salescaseprice IS NULL, itemmaster.caseprice ,  p.salescaseprice)) + ((salesqty % itemmaster.unitspercase) * invoicedetail.salesprice)),4) AS SalesAmount,
	'0',in_rangelow,in_repeatingrange
	
		FROM promokeydetail INNER JOIN productgroupdetail ON  promokeydetail.assignmentgroup = productgroupdetail.groupnumber 
		INNER JOIN invoicedetail ON productgroupdetail.itemcode = invoicedetail.itemcode AND invoicedetail.routekey = in_routekey 
					AND invoicedetail.visitkey  = in_visitkey
		INNER JOIN itemmaster ON itemmaster.actualitemcode = productgroupdetail.itemcode 
		LEFT JOIN pricingdetail1 p ON p.itemcode = productgroupdetail.itemcode 
					AND p.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) 
								   FROM customerpricing1 JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey  AND customercode = in_customercode) 
		WHERE promokeydetail.assignmentnumber = in_assignment_no 
		AND promokeydetail.promotionkey = (SELECT promotionkey FROM customermaster WHERE customercode = in_customercode) 
		AND promokeydetail.plannumber = in_plannumber GROUP BY promokeydetail.plannumber;
		
	ELSE
	
	INSERT INTO promotiondetail
	(routekey,visitkey,transactionkey,itemtransactiontype,itemcode,promotiontypecode,promotionamount,
	oldpromotionamount,promotionplannumber,assignmentkey,weighted,record_flag,salesamount,issync,rangelow,repeatingrange) 
	
	SELECT in_routekey,in_visitkey,invoice_transaction_key,'0',productgroupdetail.itemcode,in_promotiontypecode,
	in_promotion_amount,
	FORMAT(((salesqty / itemmaster.unitspercase) *	IF(p.salescaseprice IS NULL , itemmaster.caseprice,  p.salescaseprice) 	+ ((salesqty % itemmaster.unitspercase) * invoicedetail.salesprice)),4) AS SalesAmount,
	in_plannumber,in_assignment_no,'0','1',
	FORMAT(((salesqty / itemmaster.unitspercase) *	IF(p.salescaseprice IS NULL , itemmaster.caseprice,  p.salescaseprice) 	+ ((salesqty % itemmaster.unitspercase) * invoicedetail.salesprice)),4) AS SalesAmount,
	'0',in_rangelow,in_repeatingrange
	
	FROM promokeydetail
	INNER JOIN productgroupdetail ON  promokeydetail.assignmentgroup = productgroupdetail.groupnumber 
	INNER JOIN invoicedetail ON productgroupdetail.itemcode = invoicedetail.itemcode 
				 AND invoicedetail.routekey =in_routekey 
				 AND invoicedetail.visitkey  =in_visitkey
	INNER JOIN itemmaster ON itemmaster.actualitemcode = productgroupdetail.itemcode 
	LEFT JOIN pricingdetail1 p ON p.itemcode = productgroupdetail.itemcode 
				AND p.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) 
				FROM customerpricing1 JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey 
				AND customercode = in_customercode) 
	WHERE promokeydetail.assignmentnumber = in_assignment_no  
	AND promokeydetail.promotionkey = (SELECT promotionkey FROM customermaster WHERE customercode = in_customercode) 
	AND promokeydetail.plannumber = in_plannumber;
	
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoiceadd_signaturedata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoiceadd_signaturedata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoiceadd_signaturedata`(
IN in_visitkey INT,
in in_routekey int,
in in_transactionkey int,
in in_customer int,
in in_amount_due double(8,0),
in in_output BLOB
)
BEGIN
delete  from sigcapturedata_temp where transactionkey =in_transactionkey and transaction_type = 1;
	INSERT INTO sigcapturedata_temp 
	(routekey, visitkey, transactionkey, customercode, transactiondate,  balancedueamount,signaturedata,transaction_type)
	VALUES
	(in_routekey,in_visitkey,in_transactionkey,in_customer,CURRENT_DATE(),in_amount_due,in_output,1);
 
   
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoice_addinvoicetmpdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoice_addinvoicetmpdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoice_addinvoicetmpdetail`(
/* invoicedetail*/
IN var_transactionkey BIGINT,
IN var_routekey DECIMAL(28,0),
IN var_visitkey DECIMAL(28,0),
IN var_itemcode DECIMAL(18,0),
IN var_salesqty DECIMAL(18,0),
IN var_returnqty DECIMAL(18,0),
IN var_damagedqty DECIMAL(18,0),
IN var_manualfreeqty DECIMAL(18,0),
IN var_expiryqty DECIMAL(18,0),
IN var_promotionqty DECIMAL(18,0),
IN var_salescaseprice DECIMAL(18,4),
IN var_returncaseprice DECIMAL(18,4)
)
BEGIN
DECLARE in_returncaseprice DECIMAL(18,4);
DECLARE in_caseprice DECIMAL(18,4);
DECLARE in_sales_price DECIMAL(18,4);	
DECLARE in_sales_case_price DECIMAL(18,4);
DECLARE in_return_price DECIMAL(18,4);	
DECLARE in_return_case_price DECIMAL(18,4);
DECLARE in_defaultgoodreturnprice DECIMAL(18,4);
DECLARE in_defaultgoodreturncaseprice DECIMAL(18,4);
DECLARE in_last_insert_id INT;
DECLARE in_batchdetailkey INT;DECLARE in_unitspercase INT;
	
	SELECT itemmaster.defaultsalesprice AS sales_price,itemmaster.defaultreturnprice AS return_price,itemmaster.caseprice AS sales_case_price,		itemmaster.returncaseprice AS return_case_price,itemmaster.defaultgoodreturnprice, itemmaster.defaultgoodreturncaseprice,itemmaster.unitspercase INTO in_sales_price,in_return_price,in_sales_case_price,in_return_case_price,in_defaultgoodreturnprice,in_defaultgoodreturncaseprice,in_unitspercase	FROM itemmaster 	WHERE itemmaster.actualitemcode = var_itemcode;
	
	SELECT batchdetailkey INTO in_batchdetailkey FROM batchexpirydetail_temp WHERE visitkey = var_visitkey LIMIT 1;
	
	INSERT INTO invoicedetail_temp SET 
