	) AS a
		
		SET invoiceheader_temp.totalsalesamount =IFNULL(a.total_sales,0) ,
		-- invoiceheader.totalinvoiceamount = (IFNULL(a.total_sales,0)-IFNULL(a.totalreturnamount,0)-IFNULL(a.total_damage,0)),
		invoiceheader_temp.totalreturnamount =a.total_buyback,
		invoiceheader_temp.totaldamagedamount =a.total_damage,		
		invoiceheader_temp.totalmanualfree =a.total_free_sample_qty
		WHERE invoiceheader_temp.transactionkey =var_transactionkey;
	 
   	
   
	UPDATE invoiceheader_temp SET 
		totalinvoiceamount=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totaldamagedamount,0)),
		invoicebalance=(IFNULL(totalsalesamount,0)-IFNULL(totalreturnamount,0)-IFNULL(totaldamagedamount,0))
		WHERE invoiceheader_temp.transactionkey =var_transactionkey;   
		
  
	
      IF var_returnqty != 0  THEN -- AND  var_return_reason != 0 ,reasoncode,var_return_reason
     
      INSERT INTO invoicerxddetail_temp (routekey,visitkey,transactionkey,itemtransactiontype,itemcode,quantity) 
                 VALUES(var_routekey,var_visitkey,var_transactionkey,3,var_itemcode,var_returnqty);
     END IF;
    -- select var_transactionkey;
     SELECT 
		SUM((id.salescaseprice * FLOOR(salesqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((salesqty%im.unitspercase),3))) AS total_sales,
		SUM((id.returncaseprice * FLOOR(damagedqty/im.unitspercase))+(ROUND(id.returncaseprice,3) * ROUND((damagedqty%im.unitspercase),3))) AS total_damage,
		SUM((id.returncaseprice * FLOOR(returnqty/im.unitspercase))+(ROUND(id.goodreturnprice,3) * ROUND((returnqty%im.unitspercase),3))) AS total_buyback,
		SUM((id.salescaseprice * FLOOR(promoqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((promoqty%im.unitspercase),3))) AS total_promo,
		SUM((id.salescaseprice * FLOOR(freesampleqty/im.unitspercase))+(ROUND(id.salesprice,3) * ROUND((freesampleqty%im.unitspercase),3))) AS total_free_sample_qty
	FROM invoicedetail_temp AS id
	LEFT JOIN itemmaster AS im  ON im.actualitemcode =id.itemcode
	JOIN invoiceheader_temp  AS ih
	WHERE ih.transactionkey = id.transactionkey
	AND ih.transactionkey =var_transactionkey;
	
	SELECT var_transactionkey AS transkey,var_visitkey AS visitkey ,var_routekey AS routekey ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoice_addinvoicetmpheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoice_addinvoicetmpheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoice_addinvoicetmpheader`(
IN var_invoicenumber DECIMAL(28,0),
IN var_routestartdate DATETIME,
IN var_routecode DECIMAL(18,0),
IN var_customercode DECIMAL(18,0),
IN var_comment VARCHAR(200)
)
BEGIN
/* insert record into invoiceheader_temp*/
DECLARE var_salesmancode INT;
DECLARE in_last_insert_id INT;
DECLARE intRouteKey INT;
DECLARE intVisitKey INT;
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_routecode;
	SELECT routekey INTO intRouteKey FROM startendday WHERE startendday.routecode=var_routecode AND startendday.RouteStartDate = var_routestartdate ORDER BY routekey DESC  LIMIT 1	;
	
	SELECT COUNT(Visitkey) INTO @Visitkey FROM invoiceheader_temp WHERE RouteKey = intRouteKey ;
	IF @Visitkey > 0 THEN
		SELECT COALESCE(MAX(Visitkey),0)+1 INTO intVisitKey FROM invoiceheader_temp WHERE RouteKey = intRouteKey ;
	ELSE
		SELECT  COALESCE(MAX(Visitkey),0)+1 INTO intVisitKey FROM CustomerOperationsControl WHERE RouteKey = intRouteKey ;
	END IF;
	SELECT COALESCE(MAX(transactionkey),0)+1 INTO @transactionkey FROM invoiceheader_temp;
	
	SET @ins_qry = CONCAT("INSERT INTO invoiceheader_temp SET 
		transactionkey  = ",@transactionkey,",
		routekey 	= ",intRouteKey," , 
 		visitkey 	= ",intVisitKey,",	
		transactiondate = '",DATE(var_routestartdate),"',
		transactiontime = '",TIME(CURRENT_DATE()),"',  
		actualtransactiondate = '",DATE(CURRENT_DATE()),"',
		orderdeliverydate = '",DATE(var_routestartdate),"',
		routecode 	= ",var_routecode,",
		salesmancode 	= ",var_salesmancode,",
		customercode 	= ",var_customercode,",
		invoicenumber  	= ",var_invoicenumber,",
		comments 	= '",var_comment,"',
		record_flag 	='0'");
	
	PREPARE s1 FROM @ins_qry;
	EXECUTE s1;
	SET in_last_insert_id = LAST_INSERT_ID();
	
	
 
 -- retrun invoicehedere routekey,visitkey and transaction key
 
	SELECT @transactionkey AS transkey,intVisitKey AS visitkey ,intRouteKey AS routekey ;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_invoice_addinvoicetmpheader_100423` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_invoice_addinvoicetmpheader_100423` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_invoice_addinvoicetmpheader_100423`(
IN var_invoicenumber DECIMAL(28,0),
IN var_routestartdate DATETIME,
IN var_routecode DECIMAL(18,0),
IN var_customercode DECIMAL(18,0),
IN var_comment VARCHAR(200)
)
BEGIN
/* insert record into invoiceheader_temp*/
DECLARE var_salesmancode INT;
DECLARE in_last_insert_id INT;
DECLARE intRouteKey INT;
DEclare intVisitKey int;
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_routecode;
	SELECT routekey INTO intRouteKey FROM startendday WHERE startendday.routecode=var_routecode AND startendday.RouteStartDate = var_routestartdate ORDER BY routekey DESC  LIMIT 1	;
	
	SELECT  COALESCE(MAX(Visitkey),0)+1 INTO intVisitKey FROM CustomerOperationsControl WHERE RouteKey = intRouteKey ;
	-- IF intRouteKey > 0 Then
	INSERT INTO invoiceheader_temp SET 
	 	routekey 	= intRouteKey , 
 		visitkey 	= intVisitKey,	
		transactiondate = DATE(var_routestartdate), -- DATE(CURRENT_DATE()),
		transactiontime = TIME(CURRENT_DATE()),  -- CONCAT(HOUR(CURRENT_DATE()),":",MINUTE(CURRENT_DATE()))
		actualtransactiondate = DATE(CURRENT_DATE()),
		orderdeliverydate = DATE(var_routestartdate),
		routecode 	= var_routecode,
		salesmancode 	= var_salesmancode,
		customercode 	= var_customercode,
		invoicenumber  	= var_invoicenumber,
		comments 	= var_comment,
		record_flag 	='0';
	
	 SET in_last_insert_id = LAST_INSERT_ID();
	--   SET in_last_insert_id = max(transactionkey);
	-- 
 
 -- retrun invoicehedere routekey,visitkey and transaction key
 
	SELECT in_last_insert_id AS transkey,intVisitKey AS visitkey ,intRouteKey AS routekey ;
	-- ELSE
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_add_transaction_processload_addprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_add_transaction_processload_addprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_add_transaction_processload_addprocessload`(
IN in_processload_id INT,
IN in_route_code INT,
IN in_decimal_point INT,
IN in_route_key INT,
IN in_salesman_code INT
)
BEGIN
DECLARE in_last_insert_id INT;
DECLARE in_bache_key INT;
	UPDATE routemaster SET  bodocseq = IFNULL(bodocseq,0) + 1
	WHERE  routecode =in_route_code;
	
	
	INSERT INTO inventorytransactionheader 
		(inventorykey,routekey,transactiontype,routecode,salesmancode,transactiondate, 
		transactiontime,documentnumber,voidflag,loadnumber,refdocumentnumber,
		currencycode,actualtransactiondate,inventorynumber)
	SELECT 
		in_route_key,in_route_key,1,in_route_code,in_salesman_code,DATE(CURRENT_DATE()),
		TIME(CURRENT_DATE()),get_number_type_base(in_route_code,2),0,
		in_processload_id,0,get_default_currencycode(),CURRENT_DATE(),0 ;
	SELECT LAST_INSERT_ID() INTO in_last_insert_id;
	
	SELECT IFNULL(MAX(batchdetailkey),0) INTO  in_bache_key  FROM batchexpirydetail
	WHERE routekey = in_route_key;
	-- WHERE transactiontypecode = 1;
	SET in_bache_key = in_bache_key + 1;	
	
	INSERT INTO inventorytransactiondetail 
	(routekey,detailkey,transactiontypecode,itemcode,quantity,weighted,itemprice,batchdetailkey,
	itemcaseprice,	currencycode
	)
	SELECT in_route_key,in_last_insert_id,1,itemcode,
	((SUM(cases) * upc) + SUM(units)),0,
	sld.salesprice,
	in_bache_key,
	sld.caseprice,get_default_currencycode()
	
	FROM startingloaddetail sld
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE())
	GROUP BY itemcode,routecode,loadperiodnumber;
	
	UPDATE startingloaddetail SET `status` = 1
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id;
		
	
	INSERT INTO `batchexpirydetail` 
	( batchdetailkey,batchnumber,itemcode,expirydate,quantity,transactiontypecode,routekey,visitkey)
 
	SELECT in_bache_key,batchnumber,itemcode,expirydate,((cases * upc) + (units)) AS qty , 1 ,in_route_key,0
	FROM startingloaddetail sld
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE());
	
	
	INSERT INTO batchmaster (quantity,batchdetailkey,batchnumber,itemcode,damagequantity,expirydate,routekey )
	SELECT 0,in_bache_key,batchnumber,itemcode,0,expirydate,in_route_key
	FROM startingloaddetail 
	JOIN itemmaster ON actualitemcode = itemcode
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE()) AND  NOT EXISTS 
	(
		SELECT itemcode,batchnumber FROM batchmaster WHERE startingloaddetail.itemcode = batchmaster.itemcode
								AND batchmaster.batchnumber = startingloaddetail.batchnumber
								AND batchmaster.routekey = in_route_key
	);
	
	
	UPDATE batchmaster ,startingloaddetail
	SET 
	batchmaster.quantity =batchmaster.quantity +((startingloaddetail.cases * startingloaddetail.upc) + (startingloaddetail.units))
	WHERE 
	batchmaster.itemcode = startingloaddetail.itemcode AND
	batchmaster.batchnumber = startingloaddetail.batchnumber AND
	startingloaddetail.routecode = in_route_code
	AND startingloaddetail.loadperiodnumber = in_processload_id
	AND batchmaster.routekey = in_route_key
	AND ddate = DATE(CURRENT_DATE());
	
	SELECT in_route_key,1,itemcode,((cases * upc) + (units)) ,startingloaddetail.salesprice ,startingloaddetail.caseprice
	FROM startingloaddetail 
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE())	
	GROUP BY itemcode,routecode,loadperiodnumber;
	
	
	/*INSERT INTO inventorysummarydetail(
	inventorykey,routekey,itemcode,loadqty,stdsalesprice,stdsalescaseprice,stdreturnprice,stdreturncaseprice,mdat)
	SELECT in_route_key,in_route_key,itemcode,SUM(((s.cases * s.upc) + (s.units))) AS qty ,
	i.defaultsalesprice,i.caseprice,i.defaultreturnprice,i.returncaseprice ,CURRENT_DATE()
	FROM startingloaddetail AS s
	JOIN itemmaster AS i ON i.actualitemcode = s.itemcode
	WHERE s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id
	AND s.ddate=DATE(CURRENT_DATE())
	GROUP BY s.itemcode;
	*/
	
	UPDATE inventorysummarydetail
		SET loadqty = loadqty + (SELECT SUM(((s.cases * s.upc) + (s.units))) FROM startingloaddetail AS s 
				WHERE inventorysummarydetail.itemcode = s.itemcode
				AND  s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id
				AND inventorysummarydetail.routekey = in_route_key
				 AND s.ddate=DATE(CURRENT_DATE())
				)
	WHERE EXISTS ( SELECT itemcode FROM startingloaddetail  AS s 
			WHERE inventorysummarydetail.itemcode = s.itemcode
				AND  s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id 
				AND s.ddate=DATE(CURRENT_DATE())
			) AND inventorysummarydetail.routekey = in_route_key;
	INSERT INTO inventorysummarydetail
	(inventorykey,routekey,itemcode,loadqty,stdsalesprice,stdsalescaseprice,stdreturnprice,stdreturncaseprice,mdat,currencycode)
		(SELECT in_route_key,in_route_key,itemcode,SUM(((s.cases * s.upc) + (s.units))) AS qty ,
		i.defaultsalesprice,i.caseprice,i.defaultreturnprice,i.returncaseprice ,CURRENT_DATE(), get_default_currencycode_routecode(in_route_code)
		FROM startingloaddetail AS s 
		JOIN itemmaster AS i ON i.actualitemcode = s.itemcode
		WHERE s.routecode = in_route_code AND s.loadperiodnumber = in_processload_id 
		AND s.ddate = DATE(CURRENT_DATE())
		AND s.itemcode NOT IN( SELECT DISTINCT(s1.itemcode) FROM startingloaddetail  AS s1 
			JOIN inventorysummarydetail ON
			inventorysummarydetail.itemcode = s1.itemcode
			WHERE s1.routecode = in_route_code AND s1.loadperiodnumber = in_processload_id AND inventorysummarydetail.routekey = in_route_key
			AND s1.ddate = DATE(CURRENT_DATE()))
		GROUP BY s.itemcode
		);
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cancel_delivery_order` */

