DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cancel_delivery_order`(
					IN var_Pid DECIMAL(28,0)
					
				)
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT invoicenumber INTO @invnumber FROM salesorderheader WHERE transactionkey = var_Pid ;
	UPDATE  salesorderdetail SET processedflag = 0  WHERE transactionkey = var_Pid;
	UPDATE  salesorderheader SET confirmorder = 0  WHERE transactionkey = var_Pid;
	UPDATE  deliveryheader SET canceled = 1  WHERE orderno = @invnumber;
	
	
 END */$$
DELIMITER ;

