/* Procedure structure for procedure `sp_check_acl_entry` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_check_acl_entry` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_check_acl_entry`(
IN checktype INT,
IN checktypeid INT,
IN in_moduleid text
)
BEGIN
DECLARE cnt INT;
	
	/*IF checktype = 1 THEN
		SELECT COUNT(primary_key) INTO cnt FROM userdetail WHERE userid = checktypeid;
		IF cnt = 0 THEN 
			INSERT INTO userdetail 
			SELECT NULL,"","","","0","0","0","0","0",checktypeid,moduleid,formid FROM moduledetail;
		END IF;
	ELSE
		SELECT COUNT(primary_key) INTO cnt FROM usertypedetail WHERE usertypeid = checktypeid;
		IF cnt = 0 THEN 
			INSERT INTO usertypedetail 
			SELECT NULL,checktypeid,"","","0","0","0","0","0",moduleid,formid FROM moduledetail;
		END IF;
	END IF;*/
	
	IF checktype = 1 THEN
		
		SET @dyn_sql = CONCAT("delete FROM userdetail WHERE userid = ",checktypeid," and moduleid in(",in_moduleid,")");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT('INSERT INTO userdetail 
			SELECT "","","","0","0","0","0","0",',checktypeid,',moduleid,formid FROM moduledetail
			WHERE  moduleid IN(',in_moduleid,')');
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
	ELSE
		
		SET @dyn_sql = CONCAT('DELETE FROM usertypedetail WHERE usertypeid = ',checktypeid,' AND moduleid IN(',in_moduleid,')');
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		
		SET @dyn_sql = CONCAT('INSERT INTO usertypedetail 
			SELECT ',checktypeid,',"","","0","0","0","0","0",moduleid,formid FROM moduledetail
			WHERE  moduleid IN(',in_moduleid,')');
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
	END IF;
	
END */$$
DELIMITER ;

