/* Procedure structure for procedure `sp_combo_customermaster_sequence` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_customermaster_sequence` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_customermaster_sequence`(IN routeid BIGINT)
BEGIN
		
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN 	
		SELECT DISTINCT cm.customercode AS id , CONCAT(cm.alternatecode,' -- ',cm.customername) AS val 
		FROM routesequence rs
			INNER JOIN customermaster cm ON cm.customercode = rs.customercode AND cm.activecustomer = 1
		WHERE rs.routecode = routeid;
	ELSE
		SELECT DISTINCT cm.customercode AS id , CONCAT(cm.customercode,' -- ',cm.customername) AS val 
		FROM routesequence rs
			INNER JOIN customermaster cm ON cm.customercode = rs.customercode AND cm.activecustomer = 1
		WHERE rs.routecode = routeid;
	END IF;
END */$$
