/* Procedure structure for procedure `sp_combo_gccustomer_routecode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_gccustomer_routecode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_gccustomer_routecode`( in routeid bigint(18))
BEGIN
		
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN 
		SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 and routecode = routeid and invoicepaymentterms in (2,3,4) AND `type` in(1); 
	ELSE
		SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND routecode = routeid AND invoicepaymentterms IN (2,3,4) AND `type` IN(1); 
	END IF;
	
	
END */$$
