/* Procedure structure for procedure `sp_combo_itemmaster_depotcode_grn` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_itemmaster_depotcode_grn` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_itemmaster_depotcode_grn`(in var_depotcode bigint)
BEGIN
	
	declare iswh int(4);
	
	select centralwh into iswh from depotmaster where depotcode = var_depotcode;
	
	select `status` into @st from controlpanel where flagname = 'Use Alternate Code';
	
	
	if iswh = 1 then 
		if @st = 1 then 
			SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '1';
		else
			SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '1';
		end if;
	
	else
		IF @st = 1 THEN 
			SELECT actualitemcode AS id, CONCAT(alternatecode,' -- ',itemshortdescription) AS val FROM itemmaster
				WHERE activeitem = '1' and actualitemcode in(select itemcode from tbldepotstock where depotcode = var_depotcode and avlquantity > 0);
		ELSE
			SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster
				WHERE activeitem = '1' AND actualitemcode IN(SELECT itemcode FROM tbldepotstock WHERE depotcode = var_depotcode AND avlquantity > 0);
		END IF;
	end if;
	
END */$$
DELIMITER ;

