	else
		SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster WHERE activeitem = '1' AND itemgroupcode = groupcode;
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_combo_itemmaster_with_c_code` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_itemmaster_with_c_code` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_itemmaster_with_c_code`(
IN customercode INT,
IN var_c_code INT
)
BEGIN
	#For itemmaster Data
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code' LIMIT 1;
	
	-- SELECT @st;
	
	IF @st = 1 THEN 
	
	SELECT im.alternatecode AS id, CONCAT(im.alternatecode,' - ',itemshortdescription) AS val,im.unitspercase,  CASE WHEN pd.salesprice  IS NOT NULL AND pd.salesprice > 0 THEN pd.salesprice ELSE im.defaultsalesprice END AS  defaultsalesprice, CASE WHEN pd.salescaseprice IS NOT NULL AND pd.salescaseprice > 0 THEN pd.salescaseprice ELSE im.caseprice END AS  caseprice,itemshortdescription,dp.quantity FROM itemmaster AS im 
 INNER JOIN routeitemmapping itsg ON itsg.itemcode=im.actualitemcode  
 LEFT JOIN depotstock AS dp ON dp.itemcode = im.actualitemcode
 LEFT JOIN pricingdetail1 pd ON pd.itemcode = im.actualitemcode 
  AND pd.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) 
  FROM customerpricing1 JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey AND customercode = customercode LIMIT 1  ) 
 AND activeitem = '1' ;
	
		
	ELSE
			
		
		SELECT im.actualitemcode AS id, CONCAT(actualitemcode,' - ',itemshortdescription) AS val,im.unitspercase,  CASE WHEN pd.salesprice  IS NOT NULL AND pd.salesprice > 0 THEN pd.salesprice ELSE im.defaultsalesprice END AS  defaultsalesprice, CASE WHEN pd.salescaseprice IS NOT NULL AND pd.salescaseprice > 0 THEN pd.salescaseprice ELSE im.caseprice END AS  caseprice,itemshortdescription,dp.quantity FROM itemmaster AS im 
 INNER JOIN routeitemmapping itsg ON itsg.itemcode=im.actualitemcode 
  LEFT JOIN depotstock AS dp ON dp.itemcode = im.actualitemcode
 LEFT JOIN pricingdetail1 pd ON pd.itemcode = im.actualitemcode AND pd.customerpricingkey =(SELECT IFNULL(customerpricing1.customerpricingkey,0) 
 FROM customerpricing1 JOIN customermaster ON customerpricing1.pricingplankey = customermaster.pricingkey AND customercode = customercode LIMIT 1) AND activeitem = '1' ;
		
		
	END IF;
	
END */$$
DELIMITER ;

