/* Procedure structure for procedure `sp_combo_journeyplancustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_journeyplancustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_journeyplancustomer`(in dpcode bigint(20))
BEGIN	
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
		SELECT group_concat(rm.routecode) into @rtcode
			FROM routemaster rm,subareamaster sam,areamaster am,depotmaster dm
			WHERE sam.subareacode = rm.subareacode
				AND am.areacode = sam.areacode
				AND dm.depotcode = am.depotcode
				AND dm.depotcode = dpcode;
				
	IF @st = 1 THEN 
		set @q = concat("SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE `type` IN(2,3,4) AND activecustomer = 1 AND templateindicator = 0 AND routecode IN (",@rtcode,")");		
	ELSE
		SET @q = CONCAT("SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE `type` IN(2,3,4) AND activecustomer = 1 AND templateindicator = 0 AND routecode IN (",@rtcode,")");
	END IF;
	
	PREPARE s1 FROM @q;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_combo_loadperiod_routecode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_loadperiod_routecode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_loadperiod_routecode`(
		IN routeid BIGINT(18)
		)
BEGIN
	
	CALL sp_get_salesman_from_routecode(routeid);
	SELECT loadperiodnumber AS id, loadperiodnumber AS val FROM startingloaddetail 
	WHERE 
	loadperiodnumber NOT IN (SELECT loadnumber FROM inventorytransactionheader WHERE 
	DATE(transactiondate) = CURRENT_DATE() AND routecode = routeid AND transactiontype = 1) AND	
	`status` = 0 AND routecode = routeid AND ddate = CURRENT_DATE() GROUP BY loadperiodnumber;
		
	SELECT routekey  FROM startendday 
	WHERE startendday.routecode=routeid
	AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
END */$$
DELIMITER ;

