/* Procedure structure for procedure `sp_combo_route_startday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_combo_route_startday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_route_startday`()
BEGIN
	SELECT routecode AS id, CONCAT(routecode,' -- ',routename) AS val FROM routemaster 
	WHERE 
		activestatus = '1' 
		AND routetmpl = 0 
		AND allowroutestartdayflag = 1
		AND   
		routecode IN (
				SELECT startendday.routecode FROM startendday WHERE
				--- DATE(startendday.routestartdate) = CURRENT_DATE()  and 
					startendday.routeclosed =0
					AND startendday.triptype = 1 
					group by startendday.routecode
			     );
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_combo_route_startday_exclude` */

