DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_combo_taxmaster`(
	IN var_taxtype VARCHAR(50),
	IN cssVal VARCHAR(10)
	)
BEGIN
	
	IF var_taxtype = "CUSTOMER" THEN
		IF cssVal = 'en_' THEN
			SELECT taxcode AS id, CONCAT(taxcode,' -- ',taxdescription ) AS val FROM tbltaxmaster WHERE taxtype = 1; 
		ELSE
			SELECT taxcode AS id, CONCAT(taxcode,' -- ',arbtaxdescription ) AS val FROM taxmaster WHERE taxtype = 1; 
		END IF;
	ELSE
		IF cssVal = 'en_' THEN
			SELECT taxcode AS id, CONCAT(taxcode,' -- ',taxdescription ) AS val FROM tbltaxmaster WHERE taxtype = 2; 
		ELSE
			SELECT taxcode AS id, CONCAT(taxcode,' -- ',arbtaxdescription ) AS val FROM taxmaster WHERE taxtype = 2; 
		END IF;
	END IF;
END */$$
DELIMITER ;

