/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ConvertToInvoice_170122`(
IN nDeliveryNo  NUMERIC(18,0))
BEGIN
DECLARE nRouteCode NUMERIC(18,0);
DECLARE nCustomerCode NUMERIC(18,0);
DECLARE dRouteStartDate DATETIME;
DECLARE tRouteStartTime VARCHAR(20);
DECLARE strModifiedTime VARCHAR(20);
DECLARE nOrderNo  NUMERIC(18,0);
DECLARE nSOTKey   NUMERIC(18,0);
DECLARE dblSalesPrice   NUMERIC(18,6);
DECLARE dblReturnPrice   NUMERIC(18,6);
DECLARE dblDiscountAmount NUMERIC(18,6);
DECLARE nManualFreeQty   NUMERIC(18,2);
DECLARE nPaymentType  INT;
DECLARE RouteJourneyId  INT;
DECLARE BoPrefix  INT;
DECLARE BoDocSeq  INT;
DECLARE BoInvSeq  INT;
DECLARE DocumentNo  NUMERIC(18,0);
DECLARE InvoiceNo NUMERIC(18,0);
DECLARE OutPut INT;
DECLARE nItemCode  NUMERIC(18,0); 
DECLARE nSalesQty   NUMERIC(18,0);	
DECLARE nReturnQty   NUMERIC(18,0); 
DECLARE nFOCQty   NUMERIC(18,0);
DECLARE nTotalFreeQty   NUMERIC(18,0); 
DECLARE nInvQty   NUMERIC(18,0); 
DECLARE nRetQty   NUMERIC(18,0); 
DECLARE intRouteKey  BIGINT; 
DECLARE intVisitKey  BIGINT; 
DECLARE intSalesmanCode  BIGINT;  
DECLARE intSubAreaCode  BIGINT;  
DECLARE intSupervisorCode  BIGINT;  
DECLARE intAreaCode  BIGINT;  
DECLARE intAreaManagerCode  BIGINT;  
DECLARE intDepotCode  BIGINT;  
DECLARE intBranchManagerCode  BIGINT;  
DECLARE intCmpyCode  BIGINT;  
DECLARE intNationalSalesManagerCode  BIGINT;  
DECLARE strDataConRefNumber  VARCHAR(50);
  
DECLARE intInventoryeKey  BIGINT;
DECLARE intDetailKey  BIGINT;
DECLARE intTransactionKey  BIGINT;
DECLARE inttempTransactionKey  BIGINT;
DECLARE dblTotalInvoiceAmount DECIMAL(10,6);
DECLARE dblTotalReturnAmount DECIMAL(10,6);
DECLARE intPaymentType INT;
DECLARE AmountPaid DECIMAL(10,6);
DECLARE TotalSalesAmount DECIMAL(10,6);
DECLARE dblInvoiceBalance DECIMAL(10,6);
DECLARE SOTransactionKey DECIMAL(10,6);
DECLARE varTotalPromoAmount DECIMAL(10,6);
DECLARE AdvanceReceived DECIMAL(10,6);
DECLARE OriginalPayType  INT;
DECLARE nDriverId  NUMERIC(18,0);
DECLARE Transmitindicator INT;
DECLARE DeliveryCount INT;
DECLARE TempAmtpaid DECIMAL(10,6);
DECLARE dblTotalSalesAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalSalesETaxAmount DECIMAL(10,6)  DEFAULT 0;
DECLARE dblTotalSalesVatAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalReturnETaxAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalReturnVatAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalFGETaxAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalFGVatAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalMFGETaxAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalMFGVatAmount DECIMAL(10,6) DEFAULT 0;
DECLARE dblTotalPromoAmount DECIMAL(10,6) DEFAULT 0;
DECLARE intEnableExcTax  INT;
DECLARE intEnableVat  INT;
DECLARE MaxRouteKey NUMERIC(18,0);
DECLARE intc_code  INT;
DECLARE cnt INT DEFAULT 0; 
DECLARE var_presalesman NUMERIC(18,0);
DECLARE var_presalesroute NUMERIC(18,0); 
IF EXISTS(SELECT 1 FROM DeliveryHeader WHERE IFNULL(invoiced,0)=0   AND deliveryno=nDeliveryNo) THEN
proc_label: BEGIN  --  Begin  DeliveryNo invoiced or not 
SET tRouteStartTime = CURTIME();
SELECT DeliveryRoute,DeliveryDate,OrderNo,CustomerCode,DriverCode INTO nRouteCode,dRouteStartDate,nOrderNo,nCustomerCode,nDriverId  FROM DeliveryHeader WHERE DeliveryNo=nDeliveryNo;
SELECT  Transactionkey,PaymentType ,TotalInvoiceAmount,TotalReturnAmount,PaymentType ,TransactionKey
            ,TotalInvoiceAmount,TotalSalesAmount,AdvanceReceived,totalpromoamount,salesmancode,routecode INTO nSOTKey,nPaymentType,dblTotalInvoiceAmount,dblTotalReturnAmount,intPaymentType,SOTransactionKey
                                  ,dblInvoiceBalance,TotalSalesAmount,AdvanceReceived,dblTotalPromoAmount,var_presalesman,var_presalesroute
	FROM SalesOrderHeader WHERE InvoiceNumber = nOrderNo;
	
SELECT InvoicePaymentTerms,InvoicePaymentTerms  INTO intPaymentType, nPaymentType FROM Customermaster WHERE customercode=nCustomerCode; 
SET AdvanceReceived=0;						
SET intRouteKey = 0;  
	-- if Exists(Select 1 from StartEndDay)  
	BEGIN
		SELECT  COALESCE(RouteKey,0) INTO intRouteKey  FROM StartEndDay WHERE RouteCode  = nRouteCode AND RouteStartDate =dRouteStartDate;
		-- select DATE_FORMAT(RouteStartDate, '%Y-%m-%d');
		
		IF  intRouteKey = 0 THEN
		
			SELECT  MAX(RouteKey) INTO intRouteKey FROM StartEndDay;
			SET intRouteKey = intRouteKey + 1;
			
			SELECT  SalesmanCode INTO intSalesmanCode  FROM RouteMaster WHERE RouteCode = nRouteCode;
			SELECT SAM.SubAreaCode,   
			SAM.SupervisorCode, AM.AreaCode,   
			AM.AreaManagerCode,DM.DepotCode,   
			DM.BranchManagerCode, CM.CmpyCode,  
			 CM.NationalSalesManagerCode INTO  intSubAreaCode,   
			intSupervisorCode, intAreaCode ,   
			intAreaManagerCode, intDepotCode ,   
			intBranchManagerCode , intCmpyCode ,  
			intNationalSalesManagerCode FROM RouteMaster AS RM  
			INNER JOIN SubAreaMaster AS SAM ON RM.SubAreaCode = SAM.SubAreaCode  
	        INNER JOIN AreaMaster AS AM ON SAM.AreaCode = AM.AreaCode  
		    INNER JOIN DepotMaster AS DM ON AM.DepotCode = DM.DepotCode  
		    INNER JOIN Company AS CM ON DM.CmpyCode = CM.CmpyCode   
		    WHERE RM.RouteCode = nRouteCode;
  
    -- Convert(Varchar,@RouteCode) + '-' + Convert(varchar, @intRouteKey);
                        -- select CONVERT(nRouteCode,CHAR);
                        -- select CONVERT( intRouteKey,CHAR);
			SET strDataConRefNumber = CONCAT(CONVERT(nRouteCode,CHAR) ,'-' , CONVERT( intRouteKey,CHAR)); 
			 -- Convert(varchar,DATENAME(HH,getdate())) + ':' + Convert(varchar,DATENAME(MI,getdate()))
			 SET strModifiedTime = CURTIME();
			 
			  SELECT MAX(RouteKey)+1 INTO MaxRouteKey FROM StartEndDay;
			INSERT INTO StartEndDay  
				  (RouteKey  
				  ,RouteCode  
				  ,SalesmanCode  
				  ,RouteStartDate  
				  ,RouteStartTime  
				  ,RouteClosed  
				  ,SubAreaCode  
				  ,SupervisorCode  
				  ,AreaCode  
				  ,AreaManagerCode  
				  ,DepotCode  
				  ,BranchManagerCode  
				  ,CmpyCode  
				  ,NationalSalesManagerCode  
				  ,DataConRefNumber
				  ,ModifiedDate  
				  ,ModifiedTime
				  
				  ,RouteEndDate
				  ,RouteEndTime
				)  
			   VALUES  
				  (MaxRouteKey  -- Modified By Shine to get the exact routekey for the route.
				  ,nRouteCode  
				  ,intSalesmanCode  
				  ,dRouteStartDate  
				  ,strModifiedTime  
				  ,0  
				  ,intSubAreaCode 
				  ,intSupervisorCode  
				  ,intAreaCode
				  ,intAreaManagerCode 
				  ,intDepotCode
				  ,intBranchManagerCode  
				  ,intCmpyCode
				  ,intNationalSalesManagerCode
				  ,strDataConRefNumber 
				  ,CURDATE()
				  ,strModifiedTime
				  ,dRouteStartDate  
				  ,strModifiedTime
				);
				
			 
				
END IF;
END;
	 BEGIN  
		  
		   SELECT   COALESCE(MAX(documentnumber)+1,CONVERT((CONCAT(CONVERT(nRouteCode, CHAR) , '000001') ),UNSIGNED INTEGER))
		   INTO DocumentNo FROM  InventoryTransactionHeader  WHERE routecode=nRouteCode;
          SELECT   MAX(RouteKey) INTO  intRouteKey FROM StartEndDay WHERE RouteCode=nRouteCode;
			-- SET @intRouteKey = @intRouteKey + 1  
		  SET intInventoryeKey = 0 ; 
		  
		  SET intDetailKey = 0  ;
		  
		  SELECT   SalesmanCode INTO intSalesmanCode FROM RouteMaster WHERE RouteCode = nRouteCode;
		  SELECT   MAX(InventoryKey)+1 INTO intInventoryeKey FROM InventoryTransactionHeader; -- WHERE routecode=nRouteCode;  
		   SELECT  MAX(DetailKey)+1 INTO intDetailKey FROM InventoryTransactionHeader; -- WHERE routecode=nRouteCode;
 -- select intInventoryeKey;
 -- SELECT intDetailKey;
  BEGIN -- try
		  INSERT INTO InventoryTransactionHeader
		  (InventoryKey,
		   RouteKey,
		   RouteCode,
		   DetailKey,
		   DocumentNumber,
		   SalesmanCode,
		   TransactionType,
		   TransactionDate,
		   TransactionTime,
		   CurrencyCode,
		   manualinvoice)
   
                   
		   
		   VALUES (intInventoryeKey,
		   intRouteKey,
		   nRouteCode,
		   intDetailKey, 
		   DocumentNo,
		   intSalesmanCode,
		   1,
		   dRouteStartDate,
		   tRouteStartTime,
		   1,1);
		   
		   -- SELECT   MAX(InventoryKey) into intInventoryeKey FROM InventoryTransactionHeader WHERE routecode=nRouteCode;  
		   -- SELECT  MAX(DetailKey) into intDetailKey FROM InventoryTransactionHeader WHERE routecode=nRouteCode;
		   END; -- try
		   -- begin catch
		   -- 	ROLLBACK TRAN
		   -- 	THROW
		   -- 	RETURN
		   -- end catch
	END;
BEGIN
DECLARE finished INTEGER DEFAULT 0;
DECLARE CurISD CURSOR FOR SELECT itemcode,Salesqty,FOCQty,ManualFreeQty,ReturnQty FROM DeliveryDetail WHERE deliveryno=nDeliveryNo;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished = 1;
OPEN CurISD;
FETCH NEXT  FROM CurISD INTO nItemCode,nSalesQty,nFOCQty,nManualFreeQty,nReturnQty;
BEGIN
DECLARE intPrice DECIMAL(18,4);
DECLARE intCasePrice  DECIMAL(18,4);
SET nInvQty = nSalesQty+nFOCQty+nManualFreeQty;
SET nTotalFreeQty=nFOCQty+nManualFreeQty;
SET nRetQty=nReturnQty;
    
      
    BEGIN 
    
	-- Modified by Hrishi on 13Jun2018
	   -- Select  intPrice = IM.DefaultSalesPrice, intCasePrice=IM.CasePrice
    --   from ItemMaster IM
    --   inner join SalesOrderDetail SOD on SOD.ItemCode = IM.ActualItemCode
    --   where SOD.ItemCode = @ItemCode
	SELECT  IM.DefaultSalesPrice , IM.CasePrice INTO intPrice , intCasePrice
        FROM ItemMaster IM
        WHERE IM.ActualItemCode = nItemCode;
        
          BEGIN -- TRY
    	      INSERT INTO InventoryTransactionDetail
				 (RouteKey,
				  DetailKey,
				  TransactionTypeCode,
				  ItemCode,
				  ItemPrice,
				  CurrencyCode,
				  ItemCasePrice,
				  Quantity )
  
				  VALUES
				  (intRouteKey,
				   intDetailKey,
				   12,
				   nItemCode,
				   intPrice,
				   1,
				   intCasePrice,
				   nInvQty);
           END; -- TRY
           -- Begin catch   
	   -- ROLLBACK TRAN
	   -- THROW
           -- RETURN
	   -- END CATCH
         
         --  INSERT INTO InventoryTransactionDetail RETURN         
         IF nRetQty>0 THEN
           BEGIN
              BEGIN -- TRY
			 INSERT INTO InventoryTransactionDetail
						 (RouteKey,
						  DetailKey,
						  TransactionTypeCode,
						  ItemCode,
						  ItemPrice,
						  CurrencyCode,
						  ItemCasePrice,
						  Quantity )
		  
						  VALUES
						  (intRouteKey,
						   intDetailKey,
						   6,
						   nItemCode,
						   intPrice,
						   1,
						   intCasePrice,
						   nRetQty);
              END; -- TRY
              -- Begin catch   
	      -- ROLLBACK TRAN
	      -- THROW
	      -- RETURN
	      -- END CATCH
           END;
         END IF; 
         --  INSERT INTO InventoryTransactionDetail RETURN
    --  InventorySummaryDetail
        BEGIN 
		DECLARE cntisd INT DEFAULT 0;  
		SELECT COUNT(*) INTO cntisd FROM InventorySummaryDetail WHERE RouteKey = intRouteKey  AND ItemCode = nItemCode;
		
		IF cntisd > 0  THEN  
		BEGIN
		
			UPDATE InventorySummaryDetail 
				SET SaleQty = SaleQty + nSalesQty,
				
				FreesampleQty = FreeSampleQty + nTotalFreeQty,
				
				ReturnQty=ReturnQty+ nRetQty,
				Loadqty=loadqty+ nSalesQty+ nTotalFreeQty
			
			WHERE RouteKey = intRouteKey  AND ItemCode = nItemCode;
		END;
		ELSE
		BEGIN
			BEGIN -- TRY
				INSERT INTO InventorySummaryDetail  (
				RouteKey,
				InventoryKey,
				ItemCode,
				LoadQty,
				SaleQty,
				ReturnQty,
				FreeSampleQty,
				StdSalesPrice)
				VALUES
				(intRouteKey,
				intInventoryeKey,
				nItemCode,
				
				nSalesQty+nTotalFreeQty,
				nSalesQty,
				nRetQty,
				nFocQty,
				intPrice);   
			END; -- TRY
			-- Begin catch   
			-- ROLLBACK TRAN
			-- THROW
			-- RETURN
			-- END CATCH
		   END;
	        END IF;
	        
        END;
    --  InventorySummaryDetail
END;
END;
FETCH NEXT  FROM CurISD INTO nItemCode,nSalesQty,nFOCQty,nManualFreeQty,nReturnQty;
     CLOSE CurISD;
    -- DEALLOCATE CurISD;
END;
 
BEGIN
   
        
  	SELECT  COALESCE(MAX(Visitkey),0) INTO intVisitKey FROM CustomerOperationsControl WHERE RouteKey = intRouteKey;
	SET intVisitKey =intVisitKey +1;
        SELECT   SalesmanCode INTO intSalesmanCode FROM RouteMaster WHERE RouteCode = nRouteCode;
        
        BEGIN -- TRY  
		  INSERT INTO CustomerOperationsControl
		  ( VisitKey,
		    RouteKey,
		    CustomerCode,
		    RouteCode,
		    SalesmanCode,
		    VisitStartDate,
		    VisitStartTime,
		    VisitEndDate,
		    VisitEndTime,
		    TotalTransactions,
		    VoidFlag)
		    
		    VALUES
		    (intVisitKey ,
		     intRouteKey,
		     nCustomerCode,
		     nRouteCode,
		     intSalesmanCode,
		     dRouteStartDate,
		     tRouteStartTime,
		     dRouteStartDate,
		     tRouteStartTime,
		     1,
		     0);
		     
		     
	 END; -- TRY
	-- Begin catch   
	-- ROLLBACK TRAN
	-- THROW
	-- RETURN
	-- END CATCH
 END;
BEGIN
     UPDATE RouteMaster SET BODocSeq = BODocSeq +1 WHERE RouteCode = nRouteCode;	
END;
 
SELECT   COALESCE(MAX(InvoiceNumber)+1,CONVERT((CONCAT(CONVERT(nRouteCode, CHAR) , '200001') ),UNSIGNED INTEGER))
 INTO InvoiceNo FROM InvoiceHeader  WHERE routecode=nRouteCode;
  
 
 
  
BEGIN
	SET intTransactionKey = 0 ; 
	-- if Exists(Select 1 from InvoiceHeader)  
	-- BEGIN
	SELECT   MAX(TransactionKey) INTO intTransactionKey FROM InvoiceHeader;
	-- END
	  
	SET intTransactionKey = intTransactionKey + 1;
	SET inttempTransactionKey=intTransactionKey;
	SELECT  SalesmanCode INTO  intSalesmanCode FROM RouteMaster WHERE RouteCode = nRouteCode;
         -- SELECT SUM(Salesqty*PromotionAmount) INTO TotalPromoAmount FROM SalesOrderDetail WHERE TransactionKey= SOTKey;
         SET varTotalPromoAmount=0;
  
  
	-- SELECT IFNULL(EnableExciseTax,0) into intEnableExcTax FROM CustomerMaster WHERE customercode= nCustomerCode;
	-- SELECT IFNULL(EnableVat,0) INTO intEnableVat FROM CustomerMaster WHERE customercode= nCustomerCode;
	 SET intEnableExcTax=1;
	 SET intEnableVat=1;
	
	-- SET dblTotalReturnAmount=(SELECT SUM((CONVERT(d.ReturnQty / d.UnitsPerCase ,UNSIGNED INTEGER) * d.ReturnCasePrice) - (CONVERT(d.ReturnQty % d.UnitsPerCase ,UNSIGNED INTEGER) * d.ReturnPrice))
        -- FROM DeliveryHeader h INNER JOIN DeliveryDetail d
	-- ON h.DeliveryNo = d.DeliveryNo
	-- INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
	-- INNER JOIN SalesOrderDetail sd ON sh.RouteKey = sd.RouteKey  AND sh.TransactionKey=sd.TransactionKey AND sh.VisitKey = sd.VisitKey AND d.ItemCode = sd.ItemCode
	-- WHERE d.DeliveryNo = DeliveryNo);
	
	SET dblTotalReturnAmount=0;
	
 
	IF (intEnableVat=1) THEN
	BEGIN
	     
			SET dblTotalReturnVatAmount=0;
			SET dblTotalReturnVatAmount=(SELECT 
			(SUM(d.ReturnQty * im.DefaultSalesPrice)*IFNULL(tx.taxpercentage,0)/100)
			FROM DeliveryHeader h INNER JOIN DeliveryDetail d
			ON h.DeliveryNo = d.DeliveryNo
			INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
			INNER JOIN SalesOrderDetail sd ON sh.RouteKey = sd.RouteKey  AND sh.TransactionKey=sd.TransactionKey AND sh.VisitKey = sd.VisitKey AND d.ItemCode = sd.ItemCode
			INNER JOIN ItemMaster im ON im.ActualItemCode=d.ItemCode
			INNER JOIN tbltaxmaster tx ON im.itemtaxkey2=tx.taxcode 
			WHERE d.DeliveryNo =  nDeliveryNo);
			
			
		 
	END;
	ELSE
	BEGIN
	     SET dblTotalReturnVatAmount=0;
    END;
        END IF;
        	
       /* 
	SELECT (SUM(d.SalesQty * im.DefaultSalesPrice)*IFNULL(tx.taxpercentage,0)/100)
          - (CASE COALESCE(d.SalesQty,0) WHEN 0 THEN 0  ELSE d.SalesQty*d.PromotionAmount END) INTO dblTotalSalesAmount 
        FROM DeliveryHeader h INNER JOIN DeliveryDetail d
	ON h.DeliveryNo = d.DeliveryNo
	INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
	INNER JOIN ItemMaster im ON im.ActualItemCode=d.ItemCode
	left JOIN tbltaxmaster tx ON im.itemtaxkey2=tx.taxcode 
	WHERE d.DeliveryNo =  nDeliveryNo;
	*/
	
	SELECT SUM(FLOOR(d.salesqty/d.unitspercase)* d.caseprice + 
           CAST(d.salesqty % d.unitspercase AS SIGNED INTEGER )*d.SalesPrice) INTO dblTotalSalesAmount 
        FROM DeliveryHeader h INNER JOIN DeliveryDetail d
	ON h.DeliveryNo = d.DeliveryNo
	INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
	INNER JOIN ItemMaster im ON im.ActualItemCode=d.ItemCode
	LEFT JOIN tbltaxmaster tx ON im.itemtaxkey2=tx.taxcode 
	WHERE d.DeliveryNo =  nDeliveryNo;
	
	
	 -- select nDeliveryNo ;
	IF(intEnableVat=1) THEN
	BEGIN
	        
		 
		        SET dblTotalSalesVatAmount=0;
		       
			SET dblTotalSalesVatAmount=(SELECT 
			SUM(((FLOOR(d.salesqty/d.unitspercase)* d.caseprice +  CAST(d.salesqty % d.unitspercase AS SIGNED INTEGER )*d.SalesPrice)
			 - promotionamount) * IFNULL(tx.taxpercentage,0)/100)
			FROM DeliveryHeader h INNER JOIN DeliveryDetail d
			ON h.DeliveryNo = d.DeliveryNo
		        INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
			INNER JOIN ItemMaster im ON im.ActualItemCode=d.ItemCode
	                LEFT JOIN tbltaxmaster tx ON im.itemtaxkey2=tx.taxcode 
			WHERE d.DeliveryNo =  nDeliveryNo);
			 
			
		 
	END;
	ELSE
	BEGIN
	       SET dblTotalSalesVatAmount=0;
	END;
	END IF;
	
	-- SELECT 'sujee',dblTotalSalesVatAmount;
	 
	IF(intEnableVat=1) THEN
	BEGIN
	     
		       SET dblTotalFGVatAmount=0;
			SET dblTotalFGVatAmount=(SELECT 
			SUM((d.FOCQty * im.DefaultSalesPrice)*IFNULL(tx.taxpercentage,0)/100)
			FROM DeliveryHeader h INNER JOIN DeliveryDetail d
			ON h.DeliveryNo = d.DeliveryNo
			INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
			INNER JOIN ItemMaster im ON im.ActualItemCode=d.ItemCode
	                LEFT JOIN tbltaxmaster tx ON im.itemtaxkey2=tx.taxcode 
			WHERE d.DeliveryNo = nDeliveryNo);
			
			
		 	
	END;
	ELSE
	BEGIN
	       SET dblTotalFGVatAmount=0;
	END;
	END IF;
	 
	IF(intEnableVat=1) THEN
	BEGIN
	    
	    SET dblTotalMFGVatAmount=0;
		SET dblTotalMFGVatAmount=(SELECT 
		SUM((d.ManualFreeQty * im.DefaultSalesPrice)*IFNULL(tx.taxpercentage,0)/100)
		
		FROM DeliveryHeader h INNER JOIN DeliveryDetail d
		ON h.DeliveryNo = d.DeliveryNo
		INNER JOIN SalesOrderHeader sh ON h.OrderNo = sh.InvoiceNumber
			INNER JOIN ItemMaster im ON im.ActualItemCode=d.ItemCode
	                LEFT JOIN tbltaxmaster tx ON im.itemtaxkey2=tx.taxcode 
		WHERE d.DeliveryNo = nDeliveryNo);
		
	    
	END;
	ELSE
	BEGIN
	        SET dblTotalMFGVatAmount=0;
	END;
	END IF;
	-- Select dblTotalSalesAmount,dblTotalSalesETaxAmount,dblTotalSalesVatAmount, dblTotalFGETaxAmount ,dblTotalFGVatAmount ,dblTotalMFGETaxAmount ,dblTotalMFGVatAmount,dblTotalReturnAmount,dblTotalReturnETaxAmount,dblTotalReturnVatAmount,dblTotalPromoAmount;
	SET dblTotalInvoiceAmount=dblTotalSalesAmount+IFNULL(dblTotalSalesETaxAmount,0)+IFNULL(dblTotalSalesVatAmount,0)+ IFNULL(dblTotalFGETaxAmount,0) +IFNULL(dblTotalFGVatAmount,0) +IFNULL(dblTotalMFGETaxAmount,0) +IFNULL(dblTotalMFGVatAmount,0)-IFNULL(dblTotalReturnAmount,0)-IFNULL(dblTotalReturnETaxAmount,0)-IFNULL(dblTotalReturnVatAmount,0)-IFNULL(dblTotalPromoAmount,0);
	SET dblInvoiceBalance=dblTotalInvoiceAmount;
	SET TotalSalesAmount=dblTotalInvoiceAmount + dblTotalPromoAmount;
	-- SET TotalPromoAmount=0;
	SET varTotalPromoAmount=dblTotalPromoAmount;
	
SELECT InvoicePaymentTerms INTO OriginalPayType FROM CUSTOMERMASTER WHERE CUSTOMERCODE=nCustomerCode;
 
 IF(nPaymentType < 2 ) THEN -- Cash payment
 BEGIN
		 SET AmountPaid=dblTotalInvoiceAmount; 
		 SET dblInvoiceBalance =0;
		 SET intPaymentType = OriginalPayType;
 END;
 ELSE
 BEGIN
		
		 SET AmountPaid=AdvanceReceived;
		 SET dblInvoiceBalance=dblInvoiceBalance-AdvanceReceived;
		 SET intPaymentType = OriginalPayType;
 END;
 END IF;
 BEGIN -- TRY
 
  -- select    'SUJEE', dblTotalSalesVatAmount,dblTotalInvoiceAmount,dblTotalSalesAmount,dblTotalReturnAmount;
  INSERT INTO InvoiceHeader
  (RouteKey,
   TransactionKey,
   VisitKey,
   DocumentNumber,
   InvoiceNumber,
   TransactionDate,
   TransactionTime,
   CustomerCode,
    RouteCode,
   SalesmanCode,
   AmountPaid,
   TotalInvoiceAmount,TotalSalesAmount,
TotalReturnAmount,
   PaymentType,
   VoidFlag,
   PresoldOrderNumber,
InvoiceBalance,
	 ImmediatePaid,
	 -- ManualInvoiceType,
	 TotalPromoAmount,
	 HHCTransactionKey,
	  PreSalesmanCode,
	  ItemLineTaxAmount,
	 TotalTaxesAmount,record_flag,manualinvoicetype,actualtransactiondate,presalesroutecode )
   VALUES
   (intRouteKey,
    intTransactionKey,
    intVisitKey,
    DocumentNo,
    InvoiceNo,
    dRouteStartDate,
    tRouteStartTime,
    nCustomerCode,
    nRouteCode,
    intSalesmanCode,
    AmountPaid,
    dblTotalInvoiceAmount,
   dblTotalSalesAmount,
   dblTotalReturnAmount,
    intPaymentType, 
    0,
    nOrderNo
   ,dblInvoiceBalance,
	 AmountPaid,
	--  1,
	 varTotalPromoAmount,
	intVisitKey,
	-- nDriverId,
	var_presalesman,
	  (dblTotalSalesVatAmount+dblTotalFGVatAmount+dblTotalMFGVatAmount-dblTotalReturnVatAmount),
         	 (dblTotalSalesVatAmount+dblTotalFGVatAmount+dblTotalMFGVatAmount-dblTotalReturnVatAmount)
	 ,1,1,dRouteStartDate,var_presalesroute) ; 
	 END; -- TRY
	-- Begin catch   
	-- ROLLBACK TRAN
	-- THROW
	-- RETURN
	-- END CATCH
	
 IF((nPaymentType=1 OR nPaymentType=0)) THEN--  and @@ERROR = 0 ) -- Cash payment
 BEGIN
      IF(AdvanceReceived=0) THEN -- Added By Hrishi 12Jan2017 for checking advance collected or not
	BEGIN
	BEGIN -- TRY
		INSERT INTO CashCheckDetail(RouteKey,VisitKey,TypeCode,CheckNumber,Amount,CheckStatus,HHCTransactionKey,CheckDate,UpdateIndicator)      
                VALUES (intRouteKey,intVisitKey,1,0,AmountPaid,0,intVisitKey,dRouteStartDate ,0) ;
	END; -- TRY
	-- Begin catch   
	-- ROLLBACK TRAN
	-- THROW
	-- RETURN
	-- END CATCH
	END;
	END IF;
 END;
 END IF;   
END;
 BEGIN -- TRY  
   
  /*IF(intEnableVat=1 AND intEnableExcTax=1) THEN
     BEGIN
	  INSERT INTO InvoiceDetail
	  (RouteKey,
	   TransactionKey,
	   VisitKey,
	   ItemCode,
	   SalesQty,
	   ReturnQty,
	   DamagedQty,
	   FreeSampleQty,
	   SalesPrice,
	   ReturnPrice,
	   StdSalesPrice,
	   StdReturnPrice,
	   SalesCasePrice,
	   ReturnCasePrice,
	   StdSalesCasePrice,
	   StdReturnCasePrice,
	   DiscountAmount,
		 ManualFreeQty,
		  PromoAmount
		 
		  ,ExcTaxAmount,
		  VatAmount,
		  SalesItemExciseTax,
		  PromoItemExciseTax,
		  FGItemExciseTax,
		  SalesItemGSTTax,
		  PromoItemGSTTax,
		  FGItemGSTTax,
		  ReturnItemExciseTax,
		  ReturnItemGSTTax 
