/* Procedure structure for procedure `sp_countdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_countdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_countdata`(
	IN tablename Varchar (255),
	IN tablefield Varchar (255)
)
BEGIN
	SET @dyn_sql = CONCAT("SELECT COUNT(",tablefield,") AS counter FROM ",tablename," ");
	-- SELECT @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cron_average_sales_quantity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cron_average_sales_quantity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cron_average_sales_quantity`(IN var_routecode BIGINT(28))
BEGIN
    SELECT defaultrequestdays INTO @defaultrequestdays FROM routemaster WHERE routecode = var_routecode;
    
    IF @defaultrequestdays > 0 THEN
    
		DELETE FROM averagesalesqty WHERE routecode = var_routecode;
	
		INSERT INTO averagesalesqty(itemcode,routecode,itemqty)
		SELECT id.itemcode,red.routecode,FORMAT(AVG(id.salesqty),0) AS avgqty
		FROM invoicedetail AS id
		JOIN startendday AS red ON red.routekey = id.routekey 
		JOIN routemaster AS rm ON rm.routecode = red.routecode
		WHERE red.routestartdate >= (CURDATE() - INTERVAL rm.defaultrequestdays DAY)
		AND rm.loadreqrolluporders = 1 AND rm.routecode = var_routecode
		GROUP BY itemcode,routecode HAVING routecode > 0 
		ON DUPLICATE KEY UPDATE itemqty =  VALUES(itemqty);
		
	END IF;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cron_loadrequest_routes` */

