/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cron_loadrequest_routes`()
BEGIN
      
SELECT DISTINCT routecode FROM routemaster WHERE enableloadrequest = 1 AND activestatus = 1;
 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_cron_populate_loadrequest_routes` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_cron_populate_loadrequest_routes` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cron_populate_loadrequest_routes`(
IN var_route BIGINT(20)
)
BEGIN
DECLARE var_ddate DATETIME;
   
SELECT loadrequestdays INTO @numday FROM routemaster WHERE enableloadrequest = 1 AND routecode = var_route;
SET var_ddate = date_format(date_add(now(),interval @numday DAY),'%Y-%m-%d');
SET @days = @numday-7;
SET @lastweekdate = date_format(date_add(now(),interval @days DAY),'%Y-%m-%d');
SELECT count(*) INTO @numreq FROM loadrequest WHERE routecode =var_route AND  ddate = var_ddate;
IF @numreq > 0 THEN 
	DELETE FROM loadrequest WHERE routecode =var_route AND  ddate = var_ddate;
END IF;
  INSERT INTO loadrequest (itemcode,quantity,routecode,salesmancode,loadperiodnumber,loaddate,ddate,cdate)  
(SELECT itemcode,totunits,routecode,salesmancode,loadperiodnumber,ddate,var_ddate,NOW() FROM  startingloaddetail WHERE routecode = var_route AND ddate = @lastweekdate);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_customer_planogram_key_update` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_customer_planogram_key_update` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_customer_planogram_key_update`(
			IN var_catid        BIGINT,
			IN var_routecode 	BIGINT,
			IN var_customerid   TEXT,
			IN var_counter      INT
    )
BEGIN
		DECLARE from_start INT;	
		SET from_start = 1;
		
				
		SELECT GROUP_CONCAT(a.customercode) INTO @cstids FROM customermaster AS a WHERE a.visualcode = var_catid AND routecode = var_routecode;
		IF @cstids != ''  THEN 
			SET @dlt = CONCAT("UPDATE customermaster SET visualcode = 0 WHERE customercode IN (",@cstids,")");
			PREPARE s1 FROM @dlt;
			EXECUTE s1;
		END IF;
		
		WHILE from_start <= var_counter DO
			SET @cust_code = '';
			SET @cust_code = split(var_customerid,',',from_start);
			UPDATE customermaster SET visualcode = var_catid WHERE customercode =  @cust_code;
			SET from_start = from_start + 1;
		END WHILE;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_datamanagement_import` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_datamanagement_import` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_datamanagement_import`(
					in querystr text
					)
BEGIN	
	if querystr != '' then
		SET @q1 = querystr;
		PREPARE s1 FROM @q1;
		EXECUTE s1;
	end if;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_datamanagement_import_get` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_datamanagement_import_get` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_datamanagement_import_get`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	in tablename varchar(255)
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = '';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = '*';
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM ",tablename);
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	    
	SET @dyn_cnt = CONCAT("SELECT ", table_fields ," FROM ",tablename );
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_datamanagement_import_importcsv` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_datamanagement_import_importcsv` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_datamanagement_import_importcsv`(
					IN fillby INT,
					IN tablename VARCHAR(255)
					)
BEGIN
	
	IF fillby = 1 THEN	
		-- Below Query for select all database tables
		SELECT DATABASE() INTO @db;
		SET @q1 = CONCAT('show tables from ',@db);
		PREPARE s1 FROM @q1;
		EXECUTE s1;
	ELSEIF	fillby = 2 THEN
		SET @primarykey = show_pk(tablename);
		-- Below Query for select all tables fields
		SET @q1 = CONCAT('SHOW COLUMNS FROM ',tablename,' WHERE `Key` != "PRI"');
		PREPARE s1 FROM @q1;
		EXECUTE s1;
	END IF;
    
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customerseq_arrangecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customerseq_arrangecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customerseq_arrangecustomer`(
				IN route_code INT(4),
				IN week_no INT(4),
				in customer_code text,
				IN deletedby varchar(30)
			)
BEGIN
	-- Check primary_key on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(primary_key) into @counter,@filter_id FROM routesequence where rp32weeknumber = ",week_no," AND routecode = ",route_code," and customercode IN (",customer_code,")");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
		SET @del = CONCAT("Delete from routesequence where primary_key IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Arrange Customer','routesequence',@filter_id,deletedby,'delete');
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
	
	
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customerseq_salescalendar` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customerseq_salescalendar` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customerseq_salescalendar`( IN sales_year INT(4))
BEGIN
		DECLARE cnt CHAR(5);
		
		SELECT COUNT(*) INTO cnt FROM salescalender WHERE salesyear = sales_year;
		
		IF cnt > 0 THEN 
			DELETE FROM salescalender WHERE salesyear = sales_year;
			SELECT 'Delete';			
		END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customer_authorizegroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customer_authorizegroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_authorizegroup`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	-- Check groupnumber on joining tables.
		/*SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(groupnumber) into @counter,@filter_id FROM productgroupheader WHERE 	
						(
							groupnumber NOT IN ( select groupnumber from productgroupdetail WHERE groupnumber IN (",ids,"))
						)	
						AND groupnumber IN (",ids,") AND grouptype = 3");
		*/
		SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(groupnumber) into @counter,@filter_id FROM productgroupheader
						WHERE 
						(
							groupnumber NOT IN ( select authorizeditemgrpkey from customermaster WHERE authorizeditemgrpkey IN (",ids,"))
						)	
						AND groupnumber IN (",ids,") AND grouptype = 3");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
	
		-- Insert Record into bankmasterhistory table
		SET @ins = CONCAT("INSERT into productgroupheader_history (groupnumber,groupdescription,arbgroupdescription,
								grouptype,deleted,ddat)
							(
								select groupnumber,groupdescription,arbgroupdescription,grouptype,
								'",deletedby,"',CURRENT_DATE()
								from productgroupheader where groupnumber in (",@filter_id,")
							)");
		PREPARE s2 FROM @ins;
		EXECUTE s2;	
			
		SET @del = CONCAT("DELETE FROM productgroupheader WHERE groupnumber IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del = CONCAT("DELETE FROM productgroupdetail WHERE groupnumber IN (",@filter_id,")");
		PREPARE s4 FROM @del;
		EXECUTE s4;	
		
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Customer Authorize Group','productgroupheader',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
		
	END IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customer_channel` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customer_channel` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_channel`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	
	-- Check channelcode on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(channelcode) into @counter,@filter_id FROM channelmaster 
			where channelcode in(",ids,")");
	
	PREpare s1 from @chk;
	EXECUTE s1;
	-- select @chk;
	-- If counter is 0 then it will be going in this condition 
	IF @filter_id != '' THEN
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM channelmaster WHERE channelcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Channel Master','channelmaster',@filter_id,deletedby,'delete');		
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customer_custasset` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customer_custasset` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_custasset`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	
	-- Check categoryid on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(customerassetcode) into @counter,@filter_id FROM customerasset 
			where customerassetcode in(",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	-- select @chk;
	-- If counter is 0 then it will be going in this condition 
	IF @filter_id != '' THEN
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM customerasset WHERE customerassetcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Customer Asset','customerasset',@filter_id,deletedby,'delete');		
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

