DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_customer`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	
	-- Check customercode on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(customercode) into @counter,@filter_id FROM customermaster 
