		SET @ins = CONCAT("INSERT INTO customermaster_history(customercode,type,headofficecode,routecode,streetcode,
							districtcode,locationcode,customersequence,customername,customeraddress1,
							customeraddress2,customerphone,balance,customercategory,pricingkey,promotionkey,
