								customeraddress2,customerphone,balance,customercategory,pricingkey,promotionkey,
								authorizeditemgrpkey,messagekey1,messagekey2,invoicepaymentterms,invoiceretailoption,
								invoicepriceoverride,invoiceretailoverride,invoiceformatoption,invoiceextensionopt,
								invoicedsdpromptopt,invoicecopies,salesinputoprion,returnsinputoption,invoiceinputstyle,
								onhandspromptopt,inventoryselectopt,invencontaineropt,queuedreportoption,
								surveykey,contactname,callfrequency,routenumber,arbcustomernameshort,
								arbcustomername,arbcustomeraddress1,arbcustomeraddress2,hhccustomernameshort,hhccustomername,
								hhccustomeraddress1,hhccustomeraddress2,allowbeyondlimit,tclimit,activecustomer,
								creditlimitdays,created,cdat,modified,mdat,forcehand,renteddisplay,installedchiller,
								monthlydepreciation,typeofgiveaway,giveawayflag,lastvisiteddate,memo1,memo2,
								tcsubtype,rentperc,customeraddress3,customercity,customerstate,customerzip,authorizeditemlistctl,
								invoicepriceprint,messagekey3,messagekey4,messagekey5,messagekey6,orderformat,
								enableupcprint,enabledelayprint,printsequence,enablepriceeditinvs,enablesellprevious,
								enablesuggestsales,enableautofillreturns,enableautofilldamaged,enablesigcapture,
								enablereturnstrxn,enableexchangetrxn,enabledamagedreturns,enablearcollection,enablesurveyaudit,
								enabledelivinstruct,enableinvoicecomment,invoicedetailentry,orderdetailentry,forcestockcapture,
								enablepromotrxn,alternatecode,creditlimit,allowcashoncreditexceed,arbcustomeraddress3,templateindicator,
								arbcontactname,printlanguageflag,quantumno,lostplacementdelivs,newplacementdelivs,currencycode,histmaxdeliveries,
								arcustomertype,custtaxkey1,custtaxkey2,custtaxkey3,customertaxid,customertaxidoptions,outletsubtype,volume,enablegovtaxnote,
								forwardcoverfactor,enablepromoeditinvs,enableaddlpromoinvs,badcreditcustomer,enableduplicateprinting,numoutstandinginv,
								enablefocprinting,promooptions,groupcode,forceposcheck,ancustomercode,printoutletitemcode,reportprintcontrol,invoicelimiter,
								exclusiveopmode,returnpromotionkey,invoiceformat,liquorlicprint,enablepromoeditords,enableaddlpromoords,enableaddlpromoinvoices,
								enableposequipment,enablesalestrxn,enableadvancepayment,printcheckdetails,tcspecialdiscount,spldiscountdays,arabiccustomercity,
								threshholdlimit,discountkey,enforcepromotion,gpcustcode,cashonlypromo,roundnetamount,partialcollection,transactiontype,
								enabledraftcopy,enablebuybackfree,enablecpd,enablepaymentsel,gpsdata,fixedlatitude,fixedlongitude,rentkey,startdate,
								enddate,definitionvalue,runningvalue,rentcontrol,disablebalanceupdate,enablecreditlimit,autosettlecollection,enableinvoicecopy,
								pobox,shoptelephonenumber,shopfaxnumber,ownername,ownerlandlinenumber,ownermobilenumber,contactpersonlandlinenumber,
								contactpersonmobilenumber,contactpersonemail,purchasemanagername,purchasemanagerlandlinenumber,purchasemanagermobilenumber,
								purchasemanageremail,warehousemanagername,warehousemanagerlandlinenumber,warehousemanagermobilenumber,warehousemanageremail,
								expirylimit,exprunningvalue,distributionkey,gpssavecount,graceperiod,reportcustcode,'",deletedby,"',CURRENT_DATE()
								FROM customermaster where customercode in (",@filter_id,")
							)");
				
		PREPARE s2 FROM @ins;
		EXECUTE s2;
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM customermaster WHERE customercode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Customers','customermaster',@filter_id,deletedby,'delete');		
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

