/* Procedure structure for procedure `sp_delete_account_customer_itemmust` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customer_itemmust` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_itemmust`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
		SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(itemmustcode) into @counter,@filter_id FROM itemmustheader
						WHERE 
						(
							itemmustcode NOT IN ( select itemmustkey from customermaster WHERE itemmustkey IN (",ids,"))
						)	
						AND itemmustcode IN (",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
			
		SET @del = CONCAT("DELETE FROM itemmustheader WHERE itemmustcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del = CONCAT("DELETE FROM itemmustdetail WHERE itemmustcode IN (",@filter_id,")");
		PREPARE s4 FROM @del;
		EXECUTE s4;	
		
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Item Must List','itemmustheader',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
		
	END IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_customer_itemmustgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_customer_itemmustgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_customer_itemmustgrid`(		
	    IN p_id text
	)
BEGIN
		-- DELETE FROM `itemmustdetail` WHERE primary_key = p_id;
		IF LOCATE('_$', p_id) then			
			set @grpnum = split(p_id,'_$',1);
			SET @qry = CONCAT("DELETE from itemmustdetail WHERE itemmustcode in(",@grpnum,")");
			-- select @qry;
			PREPARE q1 FROM @qry;
			EXECUTE q1;
		
		else
		
			set @qry = concat("DELETE from itemmustdetail WHERE primary_key in(",p_id,")");
			-- select @qry;
			prepare q1 from @qry;
			execute q1;
		end if;
		
END */$$
DELIMITER ;

