/* Procedure structure for procedure `sp_delete_account_settlement_cashreceipt` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_settlement_cashreceipt` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_settlement_cashreceipt`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	-- Check documentnumber on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(COUNT(DISTINCT(ch.documentnumber)),0),GROUP_CONCAT(DISTINCT(ch.documentnumber)) into @counter,@filter_id 
						FROM cashierreceiptdetails cd,cashierreceiptheader ch
						WHERE ch.documentnumber IN (",ids,") AND checkstatus <> 1 AND ch.documentnumber = cd.documentnumber");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	if @counter > 0 then
		
		SET @del = CONCAT("DELETE FROM cashierreceiptdetails WHERE documentnumber IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del = CONCAT("DELETE FROM cashierreceiptheader WHERE documentnumber IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Cashier Receipt','cashierreceiptheader',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	end if;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_tax` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_tax` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_tax`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)				
				)
BEGIN
	
	
	-- Check taxcode on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(taxcode) into @counter,@filter_id FROM tbltaxmaster 
			where 	( 
						taxcode NOT IN(SELECT custtaxkey1 FROM customermaster WHERE custtaxkey1 in(",ids,")
						 )
						AND taxcode NOT IN(SELECT custtaxkey2 FROM customermaster WHERE custtaxkey2 in(",ids,")
						 )
						AND taxcode NOT IN(SELECT custtaxkey3 FROM customermaster WHERE custtaxkey3 in(",ids,")
						 )
						AND taxcode NOT IN(SELECT itemtaxkey1 FROM itemmaster WHERE itemtaxkey1 in(",ids,")
						 )
						AND taxcode NOT IN(SELECT itemtaxkey2 FROM itemmaster WHERE itemtaxkey2 in(",ids,") )
						AND taxcode NOT IN(SELECT itemtaxkey3 FROM itemmaster WHERE itemtaxkey3 in(",ids,")
						 ) 
					)
				AND taxcode in(",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	-- If counter is 0 then it will be going in this condition 
	IF @filter_id != '' THEN
		
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM tbltaxmaster WHERE taxcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master		
		CALL sp_add_logmaster_information(@counter,'Tax','tbltaxmaster',@filter_id,deletedby,'delete');		
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_transaction_gccollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_transaction_gccollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_transaction_gccollection`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	DECLARE from_start INT(11) DEFAULT 1;
	DECLARE inv_from_start INT(11) DEFAULT 1;	
	DECLARE cst_from_start INT(11) DEFAULT 1;
	DECLARE var_trankey BIGINT(18);	
	DECLARE lstart INT(11) DEFAULT 0;	
	DECLARE var_pdc_cash INT(1);
	
	SELECT getpdctocashstatus() INTO var_pdc_cash;
	
	-- Check transactionkey on joining tables.	
	/*	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM bearheader 
			where transactionkey in(",ids,")");
	
			
	SET @chk = CONCAT("SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(bh.transactionkey)into @counter,@filter_id FROM bearheader AS bh
				LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
				LEFT JOIN pdcclearencedetail AS pdc ON pdc.invoicenumber = bd.invoicenumber
				WHERE  bd.invoicenumber NOT IN (SELECT invoicenumber	FROM beardetail WHERE transactionkey IN(",ids,")) 
				AND bh.pdcstatus != 2 AND bh.transactionkey IN(",ids,")");
	*/
	SET @chk = CONCAT("SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(bh.transactionkey)into @counter,@filter_id FROM bearheader AS bh				
				WHERE  bh.pdcstatus != 2 AND bh.transactionkey IN(",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	-- select @chk;
	-- If counter is 0 then it will be going in this condition 
	IF @filter_id != '' THEN
	
		WHILE from_start <= @counter DO
			SET var_trankey = split(@filter_id,',',from_start);
						
			-- for getting customercode from detail table.
			SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(customercode) into @cst_cnt,@cstcode FROM beardetail 
			where transactionkey = ",var_trankey);	
			PREPARE s2 FROM @chk1;
			EXECUTE s2;
			
			SET cst_from_start = 1;
			SET lstart 		   = 0;
			
			-- Update in Customer Invoice.
			WHILE cst_from_start <= @cst_cnt DO
				SET @cstno = split(@cstcode,',',cst_from_start);
				SET @q = CONCAT("SELECT amountpaid,customercode,paymentmode INTO @totalinvamot,@var_customercode,@paymentmode FROM beardetail WHERE transactionkey = ",var_trankey," AND customercode = ",@cstno," LIMIT ",lstart,",1");
				PREPARE s FROM @q;
				EXECUTE s;
				IF @paymentmode = 0 OR var_pdc_cash = 1 THEN 
					-- update balance in headofficecode of customermaster
					SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = @var_customercode;
					IF @var_customercode != @headofficecode THEN
						UPDATE customermaster SET balance = balance+@totalinvamot WHERE customercode = @headofficecode;
					END IF;
					UPDATE customermaster SET balance = balance+@totalinvamot WHERE customercode = @var_customercode;
					-- select 1,@totalinvamot,@var_customercode;
				END IF;
				SET cst_from_start = cst_from_start + 1;
				SET lstart = lstart + 1;
			END WHILE;
			-- for getting invoicenumber from detail table.
			SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(invoicenumber) into @inv_cnt,@inv_filter_id FROM beardetail 
			where transactionkey = ",var_trankey);	
			PREPARE s2 FROM @chk1;
			EXECUTE s2;
			SET inv_from_start = 1;
			SET lstart 		   = 0;
			
			-- Update in Customer Invoice.
			WHILE inv_from_start <= @inv_cnt DO
				SET @invono = split(@inv_filter_id,',',inv_from_start);
				
				/*SET @q = CONCAT("SELECT amountpaid INTO @amountpaid FROM beardetail WHERE transactionkey = ",var_trankey," AND invoicenumber = ",@invono," LIMIT ",lstart,",",inv_from_start);
				PREPARE s FROM @q;
				EXECUTE s;*/
					
				SELECT amountpaid,paymentmode INTO @amountpaid,@paymentmode FROM beardetail WHERE transactionkey = var_trankey AND invoicenumber = @invono;
				
				-- SELECT pdcindicator INTO @pdcindi FROM customerinvoice WHERE invoicenumber = @invono;
				IF @paymentmode = 0 OR var_pdc_cash = 1 THEN
					UPDATE customerinvoice SET amountpaid = amountpaid-@amountpaid,invoicebalance = invoicebalance+@amountpaid						
						WHERE invoicenumber = @invono;
				ELSE
					SELECT pdcbalance INTO @pdcbalance  FROM customerinvoice WHERE invoicenumber = @invono;
					
					IF (@pdcbalance-@amountpaid) = 0 THEN
						UPDATE customerinvoice SET pdcindicator = 0, pdcbalance = pdcbalance-@amountpaid,pdcdate = '0000-00-00'
							WHERE invoicenumber = @invono;
					ELSE
						UPDATE customerinvoice SET pdcbalance = pdcbalance-@amountpaid
							WHERE invoicenumber = @invono;
					END IF;
				END IF;
			 	SET inv_from_start = inv_from_start + 1;
				SET lstart 		= lstart + 1;
			END WHILE;
			SET from_start = from_start + 1;
		END WHILE;
		-- Delete record
		SET @del = CONCAT("DELETE FROM bearheader WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM beardetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM bearcashcheckdetail WHERE transactionkey IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'GC Collection','bearheader',@filter_id,deletedby,'Delete');
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_transaction_hocollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_transaction_hocollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_transaction_hocollection`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	DECLARE from_start INT(11) DEFAULT 1;
	DECLARE inv_from_start INT(11) DEFAULT 1;
	DECLARE cst_from_start INT(11) DEFAULT 1;
	DECLARE cust_frm_start INT(11) DEFAULT 1;
	DECLARE var_trankey BIGINT(18);
	DECLARE var_customercode BIGINT(18);
	DECLARE totalinvamot DECIMAL(18,4);
	DECLARE amtpd DECIMAL(18,4);
	DECLARE lstart INT(11) DEFAULT 0;
	DECLARE lmt INT(11) DEFAULT 0;	
	DECLARE var_pdc_cash INT(1);
	
	SELECT getpdctocashstatus() INTO var_pdc_cash;
	
	-- Check transactionkey on joining tables.			
	/*	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM bearheader 
			where transactionkey in(",ids,")");
			
			
	SET @chk = CONCAT("SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(bh.transactionkey)into @counter,@filter_id FROM bearheader AS bh
				LEFT JOIN beardetail AS bd ON bd.transactionkey = bh.transactionkey
				LEFT JOIN pdcclearencedetail AS pdc ON pdc.invoicenumber = bd.invoicenumber
				WHERE  bd.invoicenumber NOT IN (SELECT invoicenumber	FROM beardetail WHERE transactionkey IN(",ids,")) 
				AND bh.pdcstatus = 1 AND bh.transactionkey IN(",ids,")");
	*/
	SET @chk = CONCAT("SELECT IFNULL(COUNT(*),0),GROUP_CONCAT(bh.transactionkey)into @counter,@filter_id FROM bearheader AS bh				
				WHERE  bh.pdcstatus != 2 AND bh.transactionkey IN(",ids,")");
				
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	-- select @chk;
	-- If counter is 0 then it will be going in this condition 
	IF @filter_id != '' THEN
		
		WHILE from_start <= @counter DO
		
			SET var_trankey = split(@filter_id,',',from_start);
			-- for getting customercode from header table.
			SELECT customercode INTO var_customercode FROM bearheader WHERE transactionkey = var_trankey;
			SELECT SUM(amountpaid) INTO totalinvamot FROM beardetail WHERE transactionkey = var_trankey AND customercode = var_customercode AND paymentmode = 0;
			UPDATE customermaster SET balance = balance+totalinvamot WHERE customercode = var_customercode;			
	
				-- for getting invoicenumber from detail table.
				SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(primary_key) into @cst_cnt,@pri_keys FROM beardetail 
				where transactionkey = ",var_trankey);	
				PREPARE s2 FROM @chk1;
				EXECUTE s2;
				
				SET cst_from_start = 1;	
				-- Update in custome master.
				WHILE cst_from_start <= @cst_cnt DO
					SET @pk = split(@pri_keys,',',cst_from_start);
					
					SELECT amountpaid,customercode INTO amtpd,@cstcd FROM beardetail WHERE transactionkey = var_trankey AND primary_key = @pk AND paymentmode = 0;
					UPDATE customermaster SET balance = balance+amtpd WHERE customercode = @cstcd;
	
					SET cst_from_start = cst_from_start + 1;
					SET lstart 		= lstart + 1;
				END WHILE;	
				-- for getting invoicenumber from detail table.
				SET @chk1 = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(invoicenumber) into @inv_cnt,@inv_filter_id FROM beardetail 
				where transactionkey = ",var_trankey);	
				PREPARE s2 FROM @chk1;
				EXECUTE s2;
				SET inv_from_start = 1;
				SET lstart 		   = 0;
				-- Update in Customer Invoice.
				WHILE inv_from_start <= @inv_cnt DO
				
					SET @invono = split(@inv_filter_id,',',inv_from_start);
					/*SET @q = CONCAT("SELECT amountpaid INTO @amountpaid FROM beardetail WHERE transactionkey = ",var_trankey," AND invoicenumber = ",@invono," LIMIT ",lstart,",",inv_from_start);
					PREPARE s FROM @q;
					EXECUTE s;*/
					
					SELECT amountpaid,paymentmode INTO @amountpaid,@paymentmode FROM beardetail WHERE transactionkey = var_trankey AND invoicenumber = @invono;
					-- SELECT pdcindicator INTO @pdcindi FROM customerinvoice WHERE invoicenumber = @invono;
					IF @paymentmode = 0 OR var_pdc_cash = 1 THEN
						UPDATE customerinvoice SET amountpaid = amountpaid-@amountpaid,invoicebalance = invoicebalance+@amountpaid						
							WHERE invoicenumber = @invono;
					ELSE
						SELECT pdcbalance INTO @pdcbalance  FROM customerinvoice WHERE invoicenumber = @invono;
						/*UPDATE customerinvoice SET pdcindicator = 0, pdcbalance = pdcbalance-@amountpaid,pdcdate = '0000-00-00'
							WHERE invoicenumber = @invono; */
						IF (@pdcbalance-@amountpaid) = 0 THEN
							UPDATE customerinvoice SET pdcindicator = 0, pdcbalance = pdcbalance-@amountpaid,pdcdate = '0000-00-00'
								WHERE invoicenumber = @invono;
						ELSE
							UPDATE customerinvoice SET pdcbalance = pdcbalance-@amountpaid
								WHERE invoicenumber = @invono;
						END IF;
					END IF;
					SET inv_from_start = inv_from_start + 1;
					SET lstart 		= lstart + 1;
				END WHILE;
				SET from_start 	= from_start + 1;
			END WHILE;
			-- Delete record
			SET @del = CONCAT("DELETE FROM bearheader WHERE transactionkey IN (",@filter_id,")");
			PREPARE s3 FROM @del;
			EXECUTE s3;
			
			-- Delete record
			SET @del = CONCAT("DELETE FROM beardetail WHERE transactionkey IN (",@filter_id,")");
			PREPARE s3 FROM @del;
			EXECUTE s3;
			
			-- Delete record
			SET @del = CONCAT("DELETE FROM bearcashcheckdetail WHERE transactionkey IN (",@filter_id,")");
			PREPARE s3 FROM @del;
			EXECUTE s3;
			-- Entry into log master
			CALL sp_add_logmaster_information(@counter,'HO Collection','bearheader',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_account_transaction_openingbal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_account_transaction_openingbal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_account_transaction_openingbal`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	declare from_start int(11) default 1;
	DECLARE var_trankey bigINT(18);
	declare var_customercode bigint(18);
	declare amountpaid decimal(18,4);
	
	-- Call this SP for convert null records into 0.
	call sp_edit_customer_balance_zero();
	
	-- Check transactionkey on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(transactionkey) into @counter,@filter_id FROM customerinvoice 
			where transactionkey in(",ids,") AND amountpaid < 1 AND dnamountpaid = 0 AND cnamountpaid = 0");
	
	PREpare s1 from @chk;
	EXECUTE s1;
	-- select @chk;
	-- If counter is not 0 then it will be going in this condition 
	IF @filter_id != '' THEN
		WHILE from_start <= @counter DO
			SET var_trankey = split(@filter_id,',',from_start);
			SELECT sum(totalinvoiceamount),customercode INTO amountpaid,var_customercode FROM customerinvoice WHERE transactionkey = var_trankey GROUP BY customercode;
			-- update balance in headofficecode of customermaster
			SELECT headofficecode INTO @headofficecode FROM customermaster WHERE `type` = 2 AND customercode = var_customercode;
			IF var_customercode != @headofficecode THEN 
				UPDATE customermaster SET balance = balance-amountpaid WHERE customercode = @headofficecode;
			END IF;
			UPDATE customermaster SET balance = balance-amountpaid WHERE customercode = var_customercode;
			SET from_start = from_start + 1;
		END WHILE;
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM customerinvoice WHERE transactionkey IN (",@filter_id,")");
 		PREPARE s3 FROM @del;
 		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Opening Balance','customerinvoice',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE -- if counter is greater then 0 than False message return	
		SET @chk = CONCAT("SELECT GROUP_CONCAT(transactionkey) into @filter_id FROM customerinvoice 
			where transactionkey in(",ids,") AND amountpaid > 0");	
		PREPARE s1 FROM @chk;
		EXECUTE s1;
		
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_admin_security_adduser` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_admin_security_adduser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_admin_security_adduser`(
				IN ids TEXT,
				IN deletedby VARCHAR(25),
				in loginid bigint(18)
				)
BEGIN
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(userid) into @counter,@filter_id FROM usermaster 
	WHERE userid IN (",ids,") AND userid <> (",loginid,") ");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
		SET @del = CONCAT("DELETE FROM usermaster WHERE userid IN (",ids,")");
