		EXECUTE s1;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'User Master','usermaster',ids,deletedby,'Delete');
		SELECT 'Success' AS result,@filter_id AS deleted_id;
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
END */$$
