/* Procedure structure for procedure `sp_delete_basic_reason_nonservice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_basic_reason_nonservice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_basic_reason_nonservice`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	-- Check code on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(code) into @counter,@filter_id FROM nonservreasons WHERE code IN (",ids,")");	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN	
		SET @del = CONCAT("DELETE FROM nonservreasons WHERE code IN (",@filter_id,")");
		PREPARE s1 FROM @del;
		EXECUTE s1;
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Nonservice Reasons','nonservreasons',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
	END IF;
		
END */$$
DELIMITER ;

