/* Procedure structure for procedure `sp_delete_inventory_index_items` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_index_items` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_index_items`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	
	-- Check actualitemcode on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(actualitemcode) into @counter,@filter_id FROM itemmaster as im
			where 	( 
						im.actualitemcode NOT IN(SELECT itemcode FROM startingloaddetail WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM productgroupdetail WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM customer_foc_detail WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM outletitemcodes WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM customerposinventory WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM posmaster WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM pricingdetail1 WHERE itemcode in(",ids,"))
					AND im.actualitemcode NOT IN(SELECT itemcode FROM customer_foc_balance WHERE itemcode in(",ids,"))					
					AND im.actualitemcode NOT IN(SELECT itemcode FROM inventorytransactiondetail WHERE itemcode in(",ids,"))					
					AND im.actualitemcode NOT IN(SELECT itemcode FROM promotiondetail WHERE itemcode in(",ids,"))					
					AND im.actualitemcode NOT IN(SELECT actualitemcode FROM discountkeydetail WHERE actualitemcode in(",ids,"))
					
					)
				AND im.actualitemcode in(",ids,")");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	-- select @chk;
	-- If counter is 0 then it will be going in this condition 
	IF @filter_id != '' THEN
		-- Insert into history table	
		SET @ins = CONCAT("INSERT INTO itemmaster_history(actualitemcode,itemgroupcode,
							itemtype,itemshortdescription,itemdescription,unitspercase,defaultsalesprice,defaultreturnprice,
							defaultretailprice,pricingkey,arbitemshortdescription,arbitemdescription,hhcitemshortdescription,
							hhcitemdescription,activeitem,caseprice,returncaseprice,retailcaseprice,alternatecode,
							created,cdat,modified,mdat,liter,dataentry,leadtime,viewflag,case1,case2,memo1,memo2,
							tcallowed,itemgroupingcode,printsequenceroute,printsequencecust,upccasecode,captureshelfstock,
							filmbagbarcode,boxtraybarcode,cartonbarcode,highper,lowper,literperunit,commissionallowedflag,
							alternateitemgroupcode,fastmovingitemflag,codedateformat,itemtaxkey1,itemtaxkey2,itemtaxkey3,
							defpricetaxkey1,defpricetaxkey2,defpricetaxkey3,packagecode,anitemcode,averagesales,enablemeatpiecescapture,
							itemcompany,caseuom,warehousestock,itemgrpcode,parentitemcode,shelflife,defaultgoodreturnprice,
							defaultgoodreturncaseprice,maxpricechange,minpricechange,allowbatchentry,costcaseprice,
							defaultcostprice,allowinvoicepricechange,reportitemcode,deleted,ddate) 
							(
								SELECT actualitemcode,itemgroupcode,
								itemtype,itemshortdescription,itemdescription,unitspercase,defaultsalesprice,defaultreturnprice,
								defaultretailprice,pricingkey,arbitemshortdescription,arbitemdescription,hhcitemshortdescription,
								hhcitemdescription,activeitem,caseprice,returncaseprice,retailcaseprice,alternatecode,
								created,cdat,modified,mdat,liter,dataentry,leadtime,viewflag,case1,case2,memo1,memo2,
								tcallowed,itemgroupingcode,printsequenceroute,printsequencecust,upccasecode,captureshelfstock,
								filmbagbarcode,boxtraybarcode,cartonbarcode,highper,lowper,literperunit,commissionallowedflag,
								alternateitemgroupcode,fastmovingitemflag,codedateformat,itemtaxkey1,itemtaxkey2,itemtaxkey3,
								defpricetaxkey1,defpricetaxkey2,defpricetaxkey3,packagecode,anitemcode,averagesales,enablemeatpiecescapture,
								itemcompany,caseuom,warehousestock,itemgrpcode,parentitemcode,shelflife,defaultgoodreturnprice,
								defaultgoodreturncaseprice,maxpricechange,minpricechange,allowbatchentry,costcaseprice,
								defaultcostprice,allowinvoicepricechange,reportitemcode,'",deletedby,"',CURRENT_DATE()
								FROM itemmaster where actualitemcode in (",@filter_id,")
							)");
				
		PREPARE s2 FROM @ins;
		EXECUTE s2;
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM itemmaster WHERE actualitemcode IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Items','itemmaster',@filter_id,deletedby,'delete');		
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
		
    END */$$
DELIMITER ;

