/* Procedure structure for procedure `sp_delete_inventory_pos_addcustomerposlimitgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_inventory_pos_addcustomerposlimitgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_inventory_pos_addcustomerposlimitgrid`(
			IN tbl_pk 	BIGINT,
			in deletedby 	varchar(30)
		)
BEGIN
	
		-- Change / Update the posbalance
		SELECT primary_key INTO @pk FROM customerposlimit WHERE customercode = (SELECT customercode FROM customerposinventory WHERE table_pk = tbl_pk);
		UPDATE customerposlimit SET posbalance = (posbalance+1) WHERE primary_key = @pk;
		
		SELECT posbalance FROM customerposlimit WHERE primary_key = @pk;
	
		delete from customerposinventory WHERE	table_pk = tbl_pk;
		-- Entry into log master
		CALL sp_add_logmaster_information('1','Customer POS Limit (Ajax Grid)','customerposinventory ',tbl_pk,deletedby,'delete');
		
		
END */$$
DELIMITER ;

