		-- Entry into log master
		CALL sp_add_logmaster_information('1','Salesman Target','routegoal',var_primarykey,deletedby,'delete');			
		
		SELECT 'Success' AS result,var_primarykey AS deleted_id;
		
		SELECT COUNT(*) AS records_count FROM routegoal WHERE salesmancode = @salesmancode;
		
			
END */$$
