				)
BEGIN
	-- Check subareacode on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(subareacode) into @counter,@filter_id FROM subareamaster WHERE subareacode IN (",ids,")");	
