DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotions_advance_addpromotionplan`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
		-- Insert Record into bankmasterhistory table
		SET @ins = CONCAT("INSERT into promoplandetail_history (plannumber,qualificationgroup,assignmentgroup,performcriteriakey,rangebasis,amountbasis,exclusionoption,assignmentnumber,plandescription,arbplandescription,promotiontypecode,rentindicator,iscase,onetimeuse,enforcepromotion,deleted,ddat)
							(
								select plannumber,qualificationgroup,assignmentgroup,performcriteriakey,rangebasis,amountbasis,exclusionoption,assignmentnumber,plandescription,arbplandescription,promotiontypecode,rentindicator,iscase,onetimeuse,enforcepromotion,
								'",deletedby,"',CURRENT_DATE()
								from promoplandetail where plannumber in (",ids,")
							)");
		PREPARE s2 FROM @ins;
		EXECUTE s2;	
	
		SET @del = CONCAT("DELETE FROM promoplandetail WHERE plannumber IN (",ids,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del = CONCAT("DELETE FROM promoplanheader WHERE plannumber IN (",ids,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del = CONCAT("DELETE FROM promokeydetail WHERE plannumber IN (",ids,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Promo Plan Defination','promoplandetail',ids,deletedby,'delete');
		
		SELECT 'Success' AS result,ids AS deleted_id;
END */$$
DELIMITER ;

