/* Procedure structure for procedure `sp_delete_promotions_customer_authorizegroupitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotions_customer_authorizegroupitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotions_customer_authorizegroupitemgrid`(		
	    IN p_id text
	)
BEGIN
		-- DELETE FROM `productgroupdetail` WHERE primary_key = p_id;
		IF LOCATE('_$', p_id) then			
			set @grpnum = split(p_id,'_$',1);
			SET @qry = CONCAT("DELETE from productgroupdetail WHERE groupnumber in(",@grpnum,")");
			-- select @qry;
			PREPARE q1 FROM @qry;
			EXECUTE q1;
		
		else
		
			set @qry = concat("DELETE from productgroupdetail WHERE primary_key in(",p_id,")");
			-- select @qry;
			prepare q1 from @qry;
			execute q1;
		end if;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_promotions_customer_freegoods` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotions_customer_freegoods` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotions_customer_freegoods`( 
				IN ids text,
				in deletedby varchar(25)
				)
BEGIN
	
	
	-- Check contractid on joining tables.
	set @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(DISTINCT(foc1.contractid)) into @counter,@filter_id 
						FROM customer_foc foc1,customer_foc_balance foc2
						WHERE foc1.contractid in(",ids,") AND foc2.originalqty = foc2.balanceqty");
	
	prepare s1 from @chk;
	execute s1;
	
	-- If counter is 0 then it will be going in this condition 
	if @counter > 0 then
		
		-- Delete record
		SET @del = concat("DELETE FROM customer_foc WHERE contractid IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Delete record
		SET @del1 = CONCAT("DELETE FROM customer_foc_balance WHERE contractid IN (",@filter_id,")");
		PREPARE s4 FROM @del1;
		EXECUTE s4;
		
		SET @del1 = CONCAT("DELETE FROM customer_foc_detail WHERE contractid IN (",@filter_id,")");
		PREPARE s4 FROM @del1;
		EXECUTE s4;		
		
		-- Entry into log master
		call sp_add_logmaster_information(@counter,'Customer Free Contract','customer_foc',@filter_id,deletedby,'Delete');
		
		select 'Success' as result,@filter_id as deleted_id;
		
	else -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	end if;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_promotions_customer_freegoodsgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotions_customer_freegoodsgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotions_customer_freegoodsgrid`(		
	    IN p_contractid BIGINT,
	    IN p_itemcode BIGINT
	)
BEGIN
	DECLARE counter INT;
	
	SELECT COUNT(*) INTO  counter FROM customer_foc_balance  WHERE contractid = p_contractid AND itemcode = p_itemcode AND originalqty = balanceqty;	
	
	IF counter > 0 THEN	
		DELETE FROM `customer_foc_detail` WHERE ( contractid = p_contractid AND itemcode = p_itemcode );
		DELETE FROM `customer_foc_balance` WHERE ( contractid = p_contractid AND itemcode = p_itemcode );
		SELECT 'Success' AS result;
	ELSE
		SELECT 'Not Found' AS result;
	END IF;
END */$$
DELIMITER ;

