/* Procedure structure for procedure `sp_delete_promotions_loyality_loyalitykey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotions_loyality_loyalitykey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotions_loyality_loyalitykey`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	-- Check pricingplankey on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(loyaltykeyid) into @counter,@filter_id FROM loyaltykeyheader 
						WHERE loyaltykeyid NOT IN( SELECT pricingkey FROM customermaster WHERE pricingkey IN (",ids,"))
						AND loyaltykeyid IN (",ids,")");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN		
	
		SET @del = CONCAT("DELETE FROM loyaltykeyheader WHERE loyaltykeyid IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Pricing Key Definition','loyaltykeyheader',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
		
	END IF;
		
END */$$
DELIMITER ;

