/* Procedure structure for procedure `sp_delete_promotions_supervisor_freegoods` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotions_supervisor_freegoods` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotions_supervisor_freegoods`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	
	
	-- Check contractid on joining tables.
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(DISTINCT(foc1.contractid)) into @counter,@filter_id 
						FROM supervisor_foc foc1,supervisor_foc_balance foc2
						WHERE foc1.contractid in(",ids,") AND foc2.originalqty = foc2.balanceqty");
	
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	-- If counter is 0 then it will be going in this condition 
	IF @counter > 0 THEN
		
		-- Delete record
		SET @del = CONCAT("DELETE FROM supervisor_foc WHERE contractid IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		-- Delete record
		SET @del1 = CONCAT("DELETE FROM supervisor_foc_balance WHERE contractid IN (",@filter_id,")");
		PREPARE s4 FROM @del1;
		EXECUTE s4;
		
		SET @del1 = CONCAT("DELETE FROM supervisor_foc_detail WHERE contractid IN (",@filter_id,")");
		PREPARE s4 FROM @del1;
		EXECUTE s4;		
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Supervisor Free Contract','supervisor_foc',@filter_id,deletedby,'Delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;		
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_promotion_customer_assignmentgrp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_promotion_customer_assignmentgrp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_promotion_customer_assignmentgrp`( 
				IN ids TEXT,
				IN deletedby VARCHAR(25)
				)
BEGIN
	-- Check groupnumber on joining tables.
	/*SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(groupnumber) into @counter,@filter_id FROM productgroupheader WHERE 
						(
							groupnumber NOT IN ( select assignmentnumber from promoplandetail WHERE assignmentnumber IN (",ids,"))							
						)	
						AND groupnumber IN (",ids,") AND grouptype = 2");
	PREPARE s1 FROM @chk;
	EXECUTE s1;*/
	
	SET @chk = CONCAT("SELECT IFNULL(count(*),0),GROUP_CONCAT(groupnumber) into @counter,@filter_id FROM productgroupheader 
					WHERE (
							groupnumber NOT IN ( select assignmentgroup from promoplandetail WHERE assignmentgroup IN (",ids,"))
						  )	
						  AND groupnumber IN (",ids,") AND grouptype = 2");
	PREPARE s1 FROM @chk;
	EXECUTE s1;
	
	IF @counter > 0 THEN
	
		-- Insert Record into bankmasterhistory table
		SET @ins = CONCAT("INSERT into productgroupheader_history (groupnumber,groupdescription,arbgroupdescription,
								grouptype,deleted,ddat)
							(
								select groupnumber,groupdescription,arbgroupdescription,grouptype,
								'",deletedby,"',CURRENT_DATE()
								from productgroupheader where groupnumber in (",@filter_id,")
							)");
		PREPARE s2 FROM @ins;
		EXECUTE s2;	
	
		SET @del = CONCAT("DELETE FROM productgroupheader WHERE groupnumber IN (",@filter_id,")");
		PREPARE s3 FROM @del;
		EXECUTE s3;
		
		SET @del2 = CONCAT("DELETE FROM productgroupdetail WHERE groupnumber IN (",@filter_id,")");
		PREPARE s4 FROM @del2;
		EXECUTE s4;
		
		-- Entry into log master
		CALL sp_add_logmaster_information(@counter,'Assignment Group','productgroupheader',@filter_id,deletedby,'delete');
		
		SELECT 'Success' AS result,@filter_id AS deleted_id;
		
	ELSE -- if counter is greater then 0 than False message return	
		
		SELECT 'Not Found' AS result,@filter_id AS deleted_id;
		
	END IF;
		
END */$$
DELIMITER ;

