/* Procedure structure for procedure `sp_delete_salesorder_tempdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_salesorder_tempdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_salesorder_tempdata`(
	IN in_visitkey INT,
	IN in_routekey INT
    )
BEGIN
DELETE FROM salesorderdetail_temp WHERE invoicedetail_temp.routekey = in_routekey AND invoicedetail_temp.visitkey = in_visitkey;
DELETE FROM promotiondetail_temp WHERE promotiondetail_temp.routekey = in_routekey AND promotiondetail_temp.visitkey = in_visitkey;
DELETE FROM salesorderheader_temp WHERE invoiceheader_temp.routekey = in_routekey AND invoiceheader_temp.visitkey = in_visitkey;
DELETE FROM cashcheckdetail_temp WHERE cashcheckdetail_temp.routekey = in_routekey  AND cashcheckdetail_temp.visitkey = in_visitkey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_delete_transaction_tempdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_delete_transaction_tempdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_delete_transaction_tempdata`(
IN in_visitkey INT,
IN in_routekey INT
)
BEGIN
DELETE FROM invoicedetail_temp WHERE invoicedetail_temp.routekey = in_routekey AND invoicedetail_temp.visitkey = in_visitkey;
DELETE FROM batchexpirydetail_temp WHERE batchexpirydetail_temp.routekey = in_routekey AND batchexpirydetail_temp.visitkey = in_visitkey;
DELETE FROM batchmaster_temp WHERE batchmaster_temp.routekey = in_routekey AND batchmaster_temp.visitkey = in_visitkey;
DELETE FROM promotiondetail_temp WHERE promotiondetail_temp.routekey = in_routekey AND promotiondetail_temp.visitkey = in_visitkey;
DELETE FROM invoiceheader_temp WHERE invoiceheader_temp.routekey = in_routekey AND invoiceheader_temp.visitkey = in_visitkey;
DELETE FROM invoicerxddetail_temp WHERE invoicerxddetail_temp.routekey = in_routekey AND invoicerxddetail_temp.visitkey = in_visitkey;
DELETE FROM cashcheckdetail_temp WHERE cashcheckdetail_temp.routekey = in_routekey  AND cashcheckdetail_temp.visitkey = in_visitkey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_customer_addchannel` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_customer_addchannel` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_customer_addchannel`(
	    IN channelname VARCHAR(50),
	    IN arbchannelname VARCHAR(50),	    
	    IN activestatus INT,
	    IN created VARCHAR(50),
	    IN channel_id BIGINT,
	    IN altcode VARCHAR(50)
	)
BEGIN
	
	UPDATE channelmaster SET 	channelname = channelname,
								arbchannelname = arbchannelname,
								modified = created,
								alternatecode 	= altcode,
								mdat = CURRENT_DATE(),
								activestatus = activestatus
								
							WHERE	
								channelcode = channel_id;
	
	CALL sp_add_logmaster_information('1','Channel','channelmaster',channel_id,created,'Edit');	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_customer_addcustasset` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_customer_addcustasset` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_customer_addcustasset`(
	    IN customercode INT,
	    IN assetcode INT,	    
	    IN startdate DATETIME,
	    IN enddate DATETIME,
	    IN created VARCHAR(50),
	    IN custast_id BIGINT,
	    IN aststatus INT
	)
BEGIN
	
	UPDATE customerasset SET 	customercode 	= customercode,
					assetcode 	= assetcode,
					startdate 	= startdate,
					enddate 	= enddate,
					modified 	= created,
					mdate 		= CURRENT_DATE(),
					assetstatus 	= aststatus
					
				WHERE	
					customerassetcode = custast_id;
	CALL sp_add_logmaster_information('1','Customer Asset','customerasset',custast_id,created,'Edit');	
END */$$
DELIMITER ;

