DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_customer_setting1`(	  
	   IN msg_key1 INT(4),
	   IN msg_key2 INT(4),
	   IN suggest_sales INT(4),
	   IN auto_fill_ret INT(4),
	   IN auto_fill_dmg INT(4),
	   IN sign_cap INT(4),
	   IN ret_trxn INT(4),
	   IN ar_coll INT(4),
	   IN promo_trxn INT(4),	  
	   IN sales_trxn INT(4),
	   IN invo_copy INT(4),	   
	   IN price_print INT(4),
	   IN print_seq INT(4),
	   IN price_edit_invs INT(4),
	   IN sell_prev INT(4),
	   IN survey_audit INT(4),
	   IN del_instr INT(4),
	   IN invo_comment INT(4),
	   IN detail_entry INT(4),
	   IN order_detail_entry INT(4),
	   IN force_stock INT(4),
	   IN auto_settle INT(4),
	   IN order_format INT(4),
	   IN delay_print INT(4),
	   IN dmg_return INT(4),
	   IN auth_ctrl INT(4),
	   IN cust_code BIGINT(18),
	   IN msg_key3 INT(4),
	   IN msg_key4 INT(4),
	   IN msg_key5 INT(4),
	   IN msg_key6 INT(4),
	   IN enableupc_print INT(4),
	   IN enable_pos INT(4),
	   IN enable_adv_pay INT(4),
	   IN enable_buy_back INT(4),
	   IN enable_rental INT(4),
	   IN var_enableautofillsales  INT(4),
	   IN var_enablebatchselection  INT(4),
	   IN var_channelcode BIGINT(28),
	   IN var_startdate VARCHAR(50),
	   IN var_enddate VARCHAR(50),
	   IN var_swap INT(4),
	   IN var_rtrnpass INT(4)
	)
BEGIN
	SET var_startdate 	= STR_TO_DATE(var_startdate,'%d-%m-%Y');
	SET var_enddate 	= STR_TO_DATE(var_enddate,'%d-%m-%Y');
	
	UPDATE customermaster  SET
									messagekey1 			= msg_key1,
									messagekey2 			= msg_key2,
									enablesuggestsales 		= suggest_sales,
									enableautofillreturns 	= auto_fill_ret,
									enableautofilldamaged 	= auto_fill_dmg,
									enablesigcapture 		= sign_cap,
									enablereturnstrxn 		= ret_trxn,
									enablearcollection 		= ar_coll,
									enablepromotrxn 		= promo_trxn,
									enablesalestrxn			= sales_trxn,
									enableinvoicecopy 		= invo_copy,
									invoicepriceprint 		= price_print,
									printsequence 			= print_seq,
									enablepriceeditinvs 	= price_edit_invs,
									enablesellprevious 		= sell_prev,
									enablesurveyaudit 		= survey_audit,
									enabledelivinstruct 	= del_instr,
									enableinvoicecomment 	= invo_comment,
									invoicedetailentry 		= detail_entry,
									orderdetailentry 		= order_detail_entry,
									forcestockcapture 		= force_stock ,
									autosettlecollection 	= auto_settle,
									orderformat 			= order_format,
									enabledelayprint 		= delay_print,
									enabledamagedreturns 	= dmg_return,
									authorizeditemlistctl 	= auth_ctrl,
									messagekey3				= msg_key3,
									messagekey4				= msg_key4,
									messagekey5				= msg_key5,
									messagekey6				= msg_key6,
									enableupcprint 			= enableupc_print,
									enableposequipment 		= enable_pos,
									enableadvancepayment 	= enable_adv_pay,
									enablebuybackfree 		= enable_buy_back,
									enablerental 			= enable_rental,
									enableautofillsales  	= var_enableautofillsales,
									enablebatchselection 	= var_enablebatchselection,
									channelcode	   			= var_channelcode,
									startdate 				= var_startdate,
									enddate 				= var_enddate,
									enableexchangetrxn 			= var_swap,
									enablereturnpassword			= var_rtrnpass
							WHERE customercode = cust_code;
END */$$
DELIMITER ;

