									enableaddlpromoords 	= promo_orders,
									enableaddlpromoinvoices	= promo_invoices,
									roundnetamount 			= roundnetamt,
									enforcepromotion 		= enforcepromo,
									enabledraftcopy 		= draftcopy,
									forwardcoverfactor 		= forwardfactor,
									customercity 			= custcity,
									customerstate 			= custstate,
									memo1 					= memo_1,
									memo2 					= memo_2,
									allowcashoncreditexceed	= allowcashonexceed,
									printoutletitemcode 	= printoutletcode,
									invoiceformatoption 	= invo_format,
									customertaxidoptions 	= tax_option,
									fixedlatitude 			= latitude,
									fixedlongitude 			= longitude,
									graceperiod 			= var_graceperiod,
									roundingoffvalue 		= roundingoff_value,
									barcode 				= var_barcode,
									itemmustkey			= var_itemmustkey,
									visualcode			= ddlcust_visual,
									distribution_check_id	= var_distribution_check_id,
									price_survey_id		= var_price_survey_id,
									advertisecode		= ddlcust_adver,
									applytax 			= var_applytax,
									taxregistrationnumber	= var_taxregistrationnumber	,
									traname 			= var_traname,
									tranamearabic 		= var_tranamearabic,
									taxcardno=taxcardno,
									crno=crno,
									email=email,
									deliverycustomer=deliverycustomer,
									enforcedeliverynumber = enforcedeliverynumber			
							WHERE customercode = cust_code;						
			
			
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_index_addoutletproduct` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_index_addoutletproduct` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_index_addoutletproduct`(
	    IN gname VARCHAR(50),
	    IN arbgname VARCHAR(50),	    
	    IN `status` INT,
	    IN modified_by VARCHAR(50),
	    in gcode BIGINT
	)
BEGIN
	
	update groupmaster set 	groupname = gname,
							arbgroupname = arbgname ,
							modified = modified_by,
							mdat = CURRENT_DATE(),
							activestatus = `status`
							
					where groupcode = gcode;
	select gcode;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Outlet Product Code','groupmaster',gcode,modified_by,'Edit');	
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_index_expirymanagement` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_index_expirymanagement` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_index_expirymanagement`(
	    IN route_id bigint(18),
	    IN amount double(8,0),
	    IN is_equally INT,
	    in var_custcode bigint(18)
	)
BEGIN
	declare var_counter int;
	declare var_customercode text;
	declare var_amount DOUBLE(8,0) default 0;
	
	if var_custcode > 0 then		
		
		SET @q = CONCAT("UPDATE customermaster set expirylimit = ",amount,"
							  where customercode in (",var_custcode,")");		
	 	PREPARE s FROM @q;
	 	EXECUTE s;		
	else
		select count(*),group_concat(customercode) into var_counter,var_customercode from customermaster 
			where routecode = route_id and activecustomer = 1 AND templateindicator = 0;
	
	
		if is_equally  = 1 then
			set var_amount = (amount/var_counter);
		else
			set var_amount = amount;
		end if;
		
		if var_counter > 0 then			
			set @q = concat("UPDATE customermaster set expirylimit = ",var_amount,"
								  where customercode in (",var_customercode,")");		
			prepare s from @q;
			execute s;			
		end if;
		
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_index_outletproductgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_index_outletproductgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_index_outletproductgrid`(		
	    -- IN p_itemcode VARCHAR(50),
	    IN p_outletitemcode VARCHAR(50),
	    in p_prinary_key bigint,
	    IN p_groupcode BIGINT
	    
	)
BEGIN
/*	
	SET @sel_qry = CONCAT("select count(primary_key) INTO @c2 from outletitemcodes where groupcode = ",p_groupcode," AND itemcode = ",p_itemcode);
	-- select @sel_qry;
	PREPARE sel FROM @sel_qry;
	EXECUTE sel;
	
	IF @c2 = p_prinary_key or @c2 = 0 THEN
		UPDATE outletitemcodes SET   itemcode = p_itemcode,
					outletitemcode = p_outletitemcode
		WHERE primary_key = p_prinary_key;
		
		select 'Success' as result;
	else
		select 'Duplicate' as result;
	end if;
*/
	
		UPDATE outletitemcodes SET   
					outletitemcode = p_outletitemcode
		WHERE primary_key = p_prinary_key;
		
		SELECT 'Success' AS result;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_notes_addcreditnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_notes_addcreditnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_notes_addcreditnotecustomer`(
		IN var_routeid 			BIGINT(18),
		IN var_salesmancode 	BIGINT(18),
		IN var_customercode 	BIGINT(18),
		IN var_trantype 		INT,
		IN var_amount			DECIMAL(19,4),
		IN var_totalinvoceamt 	DECIMAL(19,4),
		IN var_remark1			VARCHAR(50),
		IN var_remark2			VARCHAR(50),
		IN var_invono 			TEXT,
		IN var_cntinvo 			INT,
		IN var_paymode 			INT,
		IN var_checknum			DECIMAL(18,0),
		IN var_checkdate 		VARCHAR(50),
		IN var_bankcode 		BIGINT(18),
		IN var_trandate 		VARCHAR(50),
		IN var_created 			VARCHAR(30),
		IN var_erprefnum 		VARCHAR(30),
		IN var_hdninvoamt 		TEXT,
		in var_isfifo 		 	int,
		in var_trankey 			bigint(28)
    )
BEGIN
		DECLARE curre_code BIGINT(18);
		DECLARE from_start INT DEFAULT 1;
		DECLARE invoice_no BIGINT(18);
		DECLARE var_invbal DECIMAL(18,4);
		DECLARE new_amtpaid DECIMAL(18,4);
		DECLARE totinvamt DECIMAL(18,4);
		DECLARE amtpaid DECIMAL(18,4);
		DECLARE invbal DECIMAL(18,4);
		DECLARE totalinvamot DECIMAL(18,4);
		
		SELECT currencycode INTO curre_code FROM currencymaster WHERE defaultcurrency;
		SELECT totalinvoiceamount INTO totalinvamot FROM dcarheader WHERE transactionkey = var_trankey;
		
		IF var_cntinvo > 1 THEN
			SELECT REPLACE(var_invono,'$',',') INTO @tran_ids;
		ELSE
			SELECT REPLACE(var_invono,'$','') INTO @tran_ids;
		END IF;	
		SET @q = CONCAT("SELECT SUM(totalinvoiceamount),SUM(amountpaid),SUM(invoicebalance)
				INTO @totalinvoiceamount,@amountpaid,@invoicebalance
				FROM customerinvoice WHERE transactionkey IN (",@tran_ids,")");
		PREPARE s1 FROM @q;
		EXECUTE s1;	
		
		UPDATE dcarheader SET
				customercode		= var_customercode,
				transactiontype		= var_trantype,
				paymenttype			= var_trantype,
				amountpaid			= (@amountpaid+var_amount),
				totalinvoiceamount  = @totalinvoiceamount,
				invoicebalance 		= (@totalinvoiceamount-(@amountpaid+var_amount)),
				transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				transactiontime 	= TIME(CURRENT_DATE()),
				remarks1			= var_remark1,
				remarks2			= var_remark2,
				erpreferencenumber  = var_erprefnum,
				mdat 				= CURRENT_DATE(),
				currencycode 		= curre_code
		where transactionkey = var_trankey;
		SELECT var_trankey AS last_id;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Credit Note (Customer)','dcarheader',var_trankey,var_created,'Edit');
		
		IF var_paymode = 0 and var_amount > 0 THEN 
			-- Insert Record in dcarcashcheckdetail
			INSERT INTO dcarcashcheckdetail SET
					transactionkey		= var_trankey,
					typecode 			= var_paymode,
					amount 				= var_amount,
					currencycode 		= curre_code;
			
		ELSEif var_amount > 0 then
			INSERT INTO dcarcashcheckdetail SET
					transactionkey		= var_trankey,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		END IF;
		WHILE from_start <= var_cntinvo DO
			IF var_amount IS NOT NULL THEN
			
				SET @trankey = split(@tran_ids,',',from_start);
					 
				SELECT invoicenumber,totalinvoiceamount,amountpaid,invoicebalance 
					INTO invoice_no ,totinvamt,amtpaid,invbal
					FROM customerinvoice WHERE transactionkey = @trankey;
					
				-- check fifo condifion
				IF SIGN(invbal) = -1 THEN
					SET @invoamt = ABS(invbal);
				ELSEIF var_isfifo = 1 AND from_start > 1 THEN
					SET @invoamt = var_amount;
				ELSE
					SET @invoamt = split(var_hdninvoamt,'$',from_start);
				END IF;
				
				SET new_amtpaid = '';
				SET var_invbal	= 0.0000; 
				
				IF 	ABS(@invoamt) > ABS(invbal) THEN
					SET new_amtpaid = invbal;
				ELSE
					SET new_amtpaid = @invoamt;
					SET var_invbal  = (invbal-@invoamt);
				END IF;
				-- Insert Record in dcardetail
				INSERT INTO dcardetail SET
							transactionkey		= var_trankey,
							customercode 		= var_customercode,
							invoicenumber   	= invoice_no,
							totalinvoiceamount  = totinvamt,
							amountpaid 			= new_amtpaid,
							invoicebalance 		= var_invbal,
							invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
							currencycode 		= curre_code;
							
						
				IF var_paymode = 0 THEN 
					-- Update Record in customerinvoice
					UPDATE customerinvoice SET
							cnamountpaid			= cnamountpaid+new_amtpaid,
							amountpaid 				= (amtpaid+new_amtpaid),
							invoicebalance			= invoicebalance-new_amtpaid
							WHERE invoicenumber 	= invoice_no;
				ELSE
					UPDATE customerinvoice SET
							pdcindicator 			= 1,
							pdcbalance 				= pdcbalance+new_amtpaid,
							pdcdate 				= STR_TO_DATE(var_checkdate,'%d-%m-%Y')
							WHERE invoicenumber 	= invoice_no;
				END IF;
				
				-- update balance in customermaster
				IF var_paymode = 0 THEN					
					UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode = var_customercode;
				END IF;
				
				SET  var_amount = (var_amount-new_amtpaid);
				IF var_amount = 0 THEN
					SET var_cntinvo	= 0;
				END IF;
			END IF;
			SET from_start = from_start + 1;
		END WHILE;
		IF var_amount > 0 THEN
			SELECT update_advpayment_customer_balance(var_customercode,var_amount);			
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_notes_addcreditnoteroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_notes_addcreditnoteroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_notes_addcreditnoteroute`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),		
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	VARCHAR(50),
		IN var_modified		VARCHAR(30),
		IN var_erpreferencenumber VARCHAR(50),
		in var_trankey 		bigint(28)
    )
BEGIN
		update 	dcarheader SET				
				transactiontype		= var_trantype,
				totalinvoiceamount  	= var_amount,
				amountpaid		= var_amount,
				invoicebalance 		= 0,
				transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				remarks1		= var_remark1,
				remarks2		= var_remark2,
				mdat 			= CURRENT_DATE(),
				cdat 				= CURRENT_DATE(),
					modified 			= var_created,
					created 			= var_created,
				currencycode  		= get_default_currencycode(),
				erpreferencenumber      = var_erpreferencenumber
		where transactionkey = var_trankey;
		
		-- update routebalance in routemaster
		UPDATE routemaster SET routebalance = routebalance-var_amount WHERE routecode = (SELECT routecode FROM dcarheader WHERE transactionkey = var_trankey);
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Debit Note (Route)','dcarheader',var_trankey,var_modified,'Edit');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_notes_adddebitnotecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_notes_adddebitnotecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_notes_adddebitnotecustomer`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),
		IN var_customercode BIGINT(18),
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_invoicecombo BIGINT(28),
		IN var_trandate 	VARCHAR(50),
		IN var_modified 	VARCHAR(30),
		IN var_erprefnum 	VARCHAR(30),
		IN var_trankey 		BIGINT(28)
    )
BEGIN
		-- declare curre_code bigint(18);
		DECLARE totalinvoceamt DECIMAL(19,4) DEFAULT 0.0000;
		DECLARE totalinvamot DECIMAL(18,4);
		
		SELECT totalinvoiceamount INTO totalinvamot FROM dcarheader WHERE transactionkey = var_trankey;
		
		-- FOR ROLLBACK
		CALL sp_rollback_account_notes_adddebitnotecustomer(var_customercode,var_trankey);
		
		-- SELECT currencycode into curre_code FROM currencymaster WHERE defaultcurrency;
		SELECT sum(totalinvoiceamount) INTO totalinvoceamt FROM customerinvoice WHERE invoicenumber = var_invoicecombo;
		
		UPDATE 	dcarheader SET
				customercode		= var_customercode,
				transactiontype		= 3,
				transactiontime 	= TIME(CURRENT_DATE())	,
				paymenttype			= @pay_term,
				transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				amountpaid			= var_amount,
				totalinvoiceamount  = totalinvoceamt,
				invoicebalance 		= 0,
				remarks1			= var_remark1,
				remarks2			= var_remark2,
				erpreferencenumber  = var_erprefnum,				
				modified 			= var_modified,				
				mdat 				= CURRENT_DATE(),
				currencycode 		= get_default_currencycode()
		WHERE   transactionkey 		= var_trankey;
		
		-- update balance in custoemrmaster
		UPDATE customermaster SET balance = balance+var_amount WHERE customercode = var_customercode;		
		
		-- Insert Record in dcardetail
		UPDATE 	dcardetail SET				
				customercode 			= var_customercode,
				invoicenumber   		= var_invoicecombo,
				invoicedate     		= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				totalinvoiceamount  	= totalinvoceamt,
				amountpaid 				= var_amount,
				invoicebalance 			= 0,
				currencycode 			= get_default_currencycode()
		WHERE transactionkey 			= var_trankey;
	
		-- Update Record in customerinvoice
		UPDATE customerinvoice SET
				dnamountpaid			= dnamountpaid+var_amount,
				totalinvoiceamount 		= totalinvoceamt,
				invoicebalance			= (invoicebalance+var_amount)
				WHERE invoicenumber 	= var_invoicecombo;
		-- Insert Log
		CALL sp_add_logmaster_information('1','Debit Note (Customer)','dcarheader',var_trankey,var_modified,'Edit');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_notes_adddebitnoteroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_notes_adddebitnoteroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_notes_adddebitnoteroute`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),		
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	VARCHAR(50),
		IN var_modified		VARCHAR(30),
		IN var_erpreferencenumber VARCHAR(50),
		in var_trankey 		bigint(28)
    )
BEGIN
		select amountpaid into @amountpaid from dcarheader WHERE transactionkey = var_trankey;
		update 	dcarheader SET				
				transactiontype		= 3,
				transactiontime 	= TIME(CURRENT_DATE())	,
				totalinvoiceamount  = var_amount,
				amountpaid			= var_amount,
				invoicebalance 		= 0,
				transactiondate = STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				remarks1		= var_remark1,
				remarks2		= var_remark2,
				mdat 			= CURRENT_DATE(),
				cdat 				= CURRENT_DATE(),
				created 			= var_created,
				modified 			= var_created,
				currencycode 			= get_default_currencycode(),
				erpreferencenumber      = var_erpreferencenumber	
		where transactionkey = var_trankey;
		
		-- update routebalance in routemaster
		if sign(var_amount) = -1 then
			SET @bal = var_amount + abs(@amountpaid);
			set @st = 0;
		elseif @amountpaid > var_amount then 
			set @bal = @amountpaid - var_amount;
			SET @st = 0;
		elseif @amountpaid < var_amount THEN 
			SET @bal = var_amount - @amountpaid;
			SET @st = 1;
		end if;
		
		if @st = 1 then
			UPDATE routemaster SET routebalance = routebalance + @bal WHERE routecode = (select routecode from dcarheader WHERE transactionkey = var_trankey);
		else 
			UPDATE routemaster SET routebalance = routebalance - @bal WHERE routecode = (SELECT routecode FROM dcarheader WHERE transactionkey = var_trankey);
		end if;
			
		-- Insert Log
		CALL sp_add_logmaster_information('1','Debit Note (Route)','dcarheader',var_trankey,var_modified,'Edit');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_salesman_addsalesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_salesman_addsalesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_salesman_addsalesman`(
		IN alt_code VARCHAR(50),
	    IN salesman_name VARCHAR(50),
	    IN arbsalesman_name VARCHAR(50),
	    IN msg_key INT,
	    IN salesman_type INT,
	    IN parent_company INT,
	    IN user_name VARCHAR(50),
	    IN pwd VARCHAR(50),
	    IN salesman_status CHAR(1),
	    IN var_contactnumber VARCHAR(50),
	    IN modified_by VARCHAR(50),
	    IN salesman_code BIGINT
	)
BEGIN
	
	UPDATE salesman  SET 	alternatesalesmancode 	= alt_code,
									salesmanname1 			= salesman_name,
									salesmanname2 			= var_contactnumber,
									arbsalesmanname1 		= arbsalesman_name,
									messagekey 				= msg_key,
									`type` 					= salesman_type,
									parentcompany 			= parent_company,									
									activestatus 			= salesman_status,
									modified 				= modified_by,
									mdat 					= CURRENT_DATE()
						WHERE  salesmancode = salesman_code;
	IF user_name != '' AND pwd != '' THEN
	 
		UPDATE salesman  SET username 	 = user_name,
							 userpassword  = pwd
						 WHERE  salesmancode = salesman_code;
	END IF;
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Salesman','salesman',salesman_code,modified_by,'Edit');	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_salesman_salesmanmsg` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_salesman_salesmanmsg` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_salesman_salesmanmsg`(
	   IN msg_desc 		VARCHAR(50),
	   IN msg_line1 	VARCHAR(40),
	   IN msg_line2 	VARCHAR(40),
	   IN msg_line3 	VARCHAR(40),
	   IN msg_line4 	VARCHAR(40),
	   IN arbmsg_line1 	VARCHAR(100),
	   IN arbmsg_line2 	VARCHAR(100),
	   IN arbmsg_line3 	VARCHAR(100),
	   IN arbmsg_line4 	VARCHAR(100),
	   IN msg_status	INT(4),
	   IN modifiedby 	VARCHAR(30),
	   in altcode 		VARCHAR(50),
	   IN msg_id 		BIGINT
	)
BEGIN	
	
	UPDATE salesmanmessages  SET
								alternatecode 			= altcode,
								messagedescription		= msg_desc,
								message1 				= msg_line1,
								message2 				= msg_line2,
								message3 				= msg_line3,
								message4 				= msg_line4,
								arbmessageline1			= arbmsg_line1,
								arbmessageline2 		= arbmsg_line2,
								arbmessageline3			= arbmsg_line3,
								arbmessageline4			= arbmsg_line4,
								activestatus			= msg_status,
								modified				= modifiedby,
								mdat					= CURRENT_DATE()
					WHERE messagekey = msg_id;
														
	SELECT msg_id AS last_id;
			
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_tax_addtax` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_tax_addtax` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_tax_addtax`(
	     IN description VARCHAR(50),
	    IN arbdescription VARCHAR(50),
	    IN tax_type INT,
	   IN tax_percentage DECIMAL(18,4),
	    IN tax_base INT,
	    IN modified_by VARCHAR(50),
	    IN var_taxcode BIGINT
	)
BEGIN
	
	UPDATE tbltaxmaster  SET 						taxdescription 				= description,
									arbtaxdescription 			= arbdescription,									
									taxtype 				= tax_type,									
									taxpercentage 				= tax_percentage,
									taxbase 				= tax_base,
									modified 				= modified_by,
									mdat 					= CURRENT_DATE()
						WHERE  taxcode = var_taxcode;
	-- Edit status Inserted Log
	
	CALL sp_add_logmaster_information('1','Tax','tbltaxmaster',var_taxcode,modified_by,'Edit');	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_transaction_addgccollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_transaction_addgccollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_transaction_addgccollection`(
		IN var_routeid 			BIGINT(18),
		IN var_salesmancode 	BIGINT(18),
		IN var_customercode 	BIGINT(18),
		IN var_trantype 		INT,
		IN var_amount			DECIMAL(19,4),
		IN var_totalinvoceamt 	DECIMAL(19,4),		
		IN var_invono 			TEXT,
		IN var_cntinvo 			INT,
		IN var_paymode 			INT,
		IN var_checknum			DECIMAL(18,0),
		IN var_checkdate 		VARCHAR(50),
		IN var_bankcode 		BIGINT(18),
		IN var_trandate 		VARCHAR(50),
		IN var_created 			VARCHAR(30),
		IN var_erprefnum 		VARCHAR(30),
		IN var_hdninvoamt 		TEXT,
		IN var_isfifo 			int(1),
		in var_trankey 			bigint(28)
    )
BEGIN
		DECLARE curre_code BIGINT(18);
		DECLARE from_start INT DEFAULT 1;
		DECLARE invoice_no BIGINT(18);
		DECLARE var_invbal DECIMAL(18,4);
		DECLARE new_amtpaid DECIMAL(18,4);
		DECLARE totinvamt DECIMAL(18,4);
		DECLARE amtpaid DECIMAL(18,4);
		DECLARE invbal DECIMAL(18,4);
		declare routeid bigint(18);		
		DECLARE totalinvamt DECIMAL(18,4);
		
		SELECT totalinvoiceamount INTO totalinvamt FROM bearheader WHERE transactionkey = var_trankey;
		
		select routecode into routeid from bearheader where transactionkey = var_trankey;
		
		SELECT currencycode INTO curre_code FROM currencymaster WHERE defaultcurrency;
			
		IF var_cntinvo > 1 THEN
			SELECT REPLACE(var_invono,'$',',') INTO @tran_ids;
		ELSE
			SELECT REPLACE(var_invono,'$','') INTO @tran_ids;
		END IF;	
		SET @q = CONCAT("SELECT SUM(totalinvoiceamount),SUM(amountpaid),SUM(invoicebalance)
				INTO @totalinvoiceamount,@amountpaid,@invoicebalance
				FROM customerinvoice WHERE transactionkey IN (",@tran_ids,")");
		PREPARE s1 FROM @q;
		EXECUTE s1;	
			
		UPDATE bearheader SET
				customercode		= var_customercode,
				`trantype`			= var_trantype,
				amountpaid			= var_amount,
				totalinvoiceamount  = @totalinvoiceamount,
				invoicebalance 		= (@totalinvoiceamount-(@amountpaid+var_amount)),
				transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				transactiontime 	= CURRENT_TIME(),
				erpreferencenumber  = var_erprefnum,
				modified 			= var_created,				
				mdat 				= CURRENT_DATE(),
				currencycode 		= curre_code
		where transactionkey = var_trankey;
		SELECT var_trankey AS last_id;
	
				
		-- Insert Log
		CALL sp_add_logmaster_information('1','GC Collection','bearheader',var_trankey,var_created,'Edit');
		
		IF var_paymode = 0 and var_amount > 0 THEN 
			-- Insert Record in bearcashcheckdetail
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= var_trankey,
					typecode 			= var_paymode,
					amount 				= var_amount,
					currencycode 		= curre_code;
			
		ELSEif var_amount > 0 then
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= var_trankey,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		END IF;
		WHILE from_start <= var_cntinvo DO
			IF var_amount IS NOT NULL THEN
				
				SET @trankey = split(@tran_ids,',',from_start);
					 
				SELECT invoicenumber,totalinvoiceamount,amountpaid,invoicebalance 
					INTO invoice_no ,totinvamt,amtpaid,invbal
					FROM customerinvoice WHERE transactionkey = @trankey;
					
				-- check fifo condifion
				IF SIGN(invbal) = -1 THEN
					SET @invoamt = ABS(invbal);
				ELSEIF var_isfifo = 1 AND from_start > 1 THEN
					SET @invoamt = var_amount;
				ELSE
					SET @invoamt = split(var_hdninvoamt,'$',from_start);
				END IF;
				
				SET new_amtpaid = '';
				SET var_invbal	= 0.0000; 
				
				IF 	ABS(@invoamt) > ABS(invbal) THEN
					SET new_amtpaid = invbal;
				ELSE
					SET new_amtpaid = @invoamt;
					SET var_invbal  = (invbal-@invoamt);
				END IF;
				-- Insert Record in beardetail
				INSERT INTO beardetail SET
							transactionkey		= var_trankey,
							customercode 		= var_customercode,
							invoicenumber   	= invoice_no,
							totalinvoiceamount  = totinvamt,
							amountpaid 			= new_amtpaid,
							invoicebalance 		= var_invbal,
							invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
							currencycode 		= curre_code;
							
				IF var_paymode = 0 THEN 
					-- Update Record in customerinvoice
					UPDATE customerinvoice SET
							amountpaid 				= (amtpaid+new_amtpaid),
							invoicebalance			= invoicebalance-new_amtpaid
							WHERE invoicenumber 	= invoice_no;
				ELSE
					UPDATE customerinvoice SET
							pdcindicator 			= 1,
							pdcbalance 				= pdcbalance+new_amtpaid,
							pdcdate 				= STR_TO_DATE(var_checkdate,'%d-%m-%Y')
							WHERE invoicenumber 	= invoice_no;
				END IF;
				
				IF var_paymode = 0 THEN
					UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode = var_customercode;
				END IF;
				
				SET  var_amount = (var_amount-new_amtpaid);
				IF var_amount = 0 THEN
					SET var_cntinvo	= 0;
				END IF;
			END IF;
			SET from_start = from_start + 1;
		END WHILE;
		IF var_amount > 0 THEN
			SELECT update_advpayment_customer_balance(var_customercode,var_amount);			
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_transaction_addhocollection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_transaction_addhocollection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_transaction_addhocollection`(
		IN var_routeid 			BIGINT(18),
		IN var_salesmancode 	BIGINT(18),
		IN var_customercode 	BIGINT(18),
		IN var_trantype 		INT,
		IN var_amount			DECIMAL(19,4),
		IN var_totalinvoceamt 	DECIMAL(19,4),		
		IN var_invono 			TEXT,
		IN var_cntinvo 			INT,
		IN var_paymode 			INT,
		IN var_checknum			DECIMAL(18,0),
		IN var_checkdate 		VARCHAR(50),
		IN var_bankcode 		BIGINT(18),
		IN var_trandate 		VARCHAR(50),
		IN var_created 			VARCHAR(30),
		IN var_erprefnum 		VARCHAR(30),
		IN var_hdninvoamt 		TEXT,
		IN var_isfifo 			INT(1),
		IN var_trankey 			BIGINT(28)
    )
BEGIN
		DECLARE curre_code BIGINT(18);
		DECLARE from_start INT DEFAULT 1;
		DECLARE invoice_no BIGINT(18);
		DECLARE var_invbal DECIMAL(18,4);
		DECLARE new_amtpaid DECIMAL(18,4);
		DECLARE totinvamt DECIMAL(18,4);
		DECLARE amtpaid DECIMAL(18,4);
		DECLARE invbal DECIMAL(18,4);		
		DECLARE totalinvamot DECIMAL(18,4);
		
		SELECT totalinvoiceamount INTO totalinvamot FROM bearheader WHERE transactionkey = var_trankey;
		SELECT currencycode INTO curre_code FROM currencymaster WHERE defaultcurrency;
		
		IF var_cntinvo > 1 THEN
			SELECT REPLACE(var_invono,'$',',') INTO @tran_ids;
		ELSE
			SELECT REPLACE(var_invono,'$','') INTO @tran_ids;
		END IF;	
		
		SET @q = CONCAT("SELECT SUM(totalinvoiceamount),SUM(amountpaid),SUM(invoicebalance)
				INTO @totalinvoiceamount,@amountpaid,@invoicebalance
				FROM customerinvoice WHERE transactionkey IN (",@tran_ids,")");
		PREPARE s1 FROM @q;
		EXECUTE s1;	
		
		UPDATE bearheader SET
				customercode		= var_customercode,				
				`trantype`			= var_trantype,
				amountpaid			= var_amount,
				totalinvoiceamount  = @totalinvoiceamount,
				invoicebalance 		= (@totalinvoiceamount-(@amountpaid+var_amount)),
				transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
				transactiontime 	= CURRENT_TIME(),
				erpreferencenumber  = var_erprefnum,				
				modified 			= var_created,				
				mdat 				= CURRENT_DATE(),
				currencycode 		= curre_code
		WHERE transactionkey = var_trankey;
		SELECT var_trankey AS last_id;
		
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','HO Collection','bearheader',var_trankey,var_created,'Edit');
		
		IF var_paymode = 0 AND var_amount != 0 THEN 
			-- Insert Record in bearcashcheckdetail
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= var_trankey,
					typecode 			= var_paymode,
					amount 				= var_amount,
					currencycode 		= curre_code;
			
		ELSEIF var_amount != 0 THEN
			INSERT INTO bearcashcheckdetail SET
					transactionkey		= var_trankey,
					typecode 			= var_paymode,
					checknumber 		= var_checknum,
					checkdate           = STR_TO_DATE(var_checkdate,'%d-%m-%Y'),
					bankcode 			= var_bankcode,
					amount 				= var_amount,
					currencycode 		= curre_code;
		END IF;
		WHILE from_start <= var_cntinvo DO
		
			IF var_amount != 0 THEN
			
				SET @trankey = split(@tran_ids,',',from_start);
					 
				SELECT invoicenumber,totalinvoiceamount,amountpaid,invoicebalance 
					INTO invoice_no ,totinvamt,amtpaid,invbal
					FROM customerinvoice WHERE transactionkey = @trankey;
					
				-- check fifo condifion
				IF SIGN(invbal) = -1 THEN
					SET @invoamt = ABS(invbal);
				ELSEIF var_isfifo = 1 AND from_start > 1 THEN
					SET @invoamt = var_amount;
				ELSE
					SET @invoamt = split(var_hdninvoamt,'$',from_start);
				END IF;
				
				SET new_amtpaid = '';
				SET var_invbal	= 0.0000; 
				
				IF 	ABS(@invoamt) > ABS(invbal) THEN
					SET new_amtpaid = invbal;
				ELSE
					SET new_amtpaid = @invoamt;
					SET var_invbal  = (invbal-@invoamt);
				END IF;
				
				-- update balance in custoemrmaster	for a branch & head office customer.
				IF var_paymode = 0 THEN
					UPDATE customermaster SET balance = balance-new_amtpaid WHERE customercode IN (@custocde,var_customercode);					
				END IF;
				
				-- Insert Record in beardetail
				INSERT INTO beardetail SET
							transactionkey		= var_trankey,
							customercode 		= var_customercode,
							invoicenumber   	= invoice_no,
							totalinvoiceamount  = totinvamt,
							amountpaid 			= new_amtpaid,
							invoicebalance 		= var_invbal,
							invoicedate     	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
							currencycode 		= curre_code;
							
				-- Update Record in customerinvoice
				IF var_paymode = 0 THEN
					UPDATE customerinvoice SET
							cnamountpaid		= new_amtpaid,
							amountpaid 			= (amtpaid+new_amtpaid),
							invoicebalance		= invoicebalance-new_amtpaid
							WHERE invoicenumber = invoice_no;
				ELSE
					UPDATE customerinvoice SET
							pdcindicator 		= 1,
							pdcbalance 			= pdcbalance+new_amtpaid,
							pdcdate 			= STR_TO_DATE(var_checkdate,'%d-%m-%Y')
							WHERE invoicenumber = invoice_no;
				END IF;
				
				
				
				SET  var_amount = (var_amount-new_amtpaid);
				IF var_amount = 0 THEN
					SET var_cntinvo	= 0;
				END IF;
			END IF;
			SET from_start = from_start + 1;
		END WHILE;
		IF var_amount > 0 THEN
			SELECT update_advpayment_customer_balance(var_customercode,var_amount);
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_account_transaction_addopeningbal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_account_transaction_addopeningbal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_account_transaction_addopeningbal`(
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),
		IN var_customercode BIGINT(18),
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	VARCHAR(50),
		IN var_erprefno 	VARCHAR(30),
		IN var_modified		VARCHAR(30),
		IN var_trankey      BIGINT(28)
    )
BEGIN
			declare totalinvamot decimal(18,4);
			declare bal DECIMAL(18,4);
			
			SELECT get_paymentcode_currencycode(var_customercode) INTO @pay;
			SELECT get_default_currencycode() INTO @curr_code;
			select totalinvoiceamount into totalinvamot from customerinvoice WHERE transactionkey = var_trankey;
			
			
			UPDATE 	customerinvoice SET
					customercode		= var_customercode,
					transactiontype		= var_trantype,
					paymenttype 		= @pay,
					transactiontime 	= TIME(CURRENT_DATE()),
					totalinvoiceamount  = var_amount,
					invoicebalance		= var_amount,
					amountpaid			= 0,
					transactiondate 	= STR_TO_DATE(var_trandate,'%d-%m-%Y'),
					remarks1			= var_remark1,
					remarks2			= var_remark2,
					erpreferencenumber 	= var_erprefno,
					currencycode 		= @curr_code
			WHERE transactionkey 		= var_trankey;
		
		
		SELECT IFNULL(SUM(totalinvoiceamount),0) INTO bal FROM customerinvoice WHERE customercode = var_customercode;
		UPDATE customermaster SET balance = bal WHERE customercode = var_customercode;
			
		-- Insert Log
		CALL sp_add_logmaster_information('1','Opening Balance','customerinvoice',var_trankey,var_modified,'Edit');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_admin_cpanel_customer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_admin_cpanel_customer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_admin_cpanel_customer`(IN ids TEXT)
BEGIN
	
	UPDATE controlpanel SET `status` = '0', modifieddate = CURRENT_DATE() WHERE formid = 2;	 
	UPDATE controlpanel SET `status` = '1', modifieddate = CURRENT_DATE() WHERE FIND_IN_SET(flagid,ids) AND formid = 2;
	 -- SELECT FlagID,FormID,FlagName,`Status` FROM controlpanel WHERE  FormID = 2;
	-- check grace period status if it is 0 then we set 0 value in customermaster table.
	SELECT `status` INTO @grace_status FROM controlpanel WHERE flagid = 74 AND `status` = 0;
	IF @grace_status = 0 THEN
		UPDATE customermaster SET graceperiod = 0;
	END IF;
	
	SELECT `status` INTO @credit_execption FROM controlpanel WHERE flagid = 81;
	IF @credit_execption = 0 THEN
		UPDATE customermaster SET startdate = NULL,enddate = NULL;
	END IF;
	 	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_admin_cpanel_general` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_admin_cpanel_general` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_admin_cpanel_general`(
		IN ids TEXT,
		IN cost_perc DECIMAL(18,4),
		IN round_off DECIMAL(18,4),
		IN salesman_load INT,
		IN month_closing_time VARCHAR(50)
		)
BEGIN
	
	UPDATE controlpanel SET `status` = '0', modifieddate = CURRENT_DATE();
	UPDATE controlpanel SET `status` = '1', modifieddate = CURRENT_DATE() WHERE FIND_IN_SET(flagid,ids);
	
	
	UPDATE controlpanel SET flagvalue = month_closing_time WHERE flagid = 83;
	-- if cost_perc > 0 then 
	UPDATE controlpanel SET flagvalue = cost_perc WHERE flagid = 78;
	UPDATE controlpanel SET flagvalue = round_off WHERE flagid = 75;		
	-- end if;
	
	UPDATE controlpanel SET `status` = salesman_load WHERE flagid = 60;
	
	-- if  Use Grace Period(Credit Limit) 0 then graceperiod value will be 0 in customermaster
	SELECT `status` INTO @st FROM controlpanel WHERE flagid = 74;
	IF @st = 0 THEN
		UPDATE customermaster SET graceperiod =0;
	END IF;
	
	CALL sp_get_header_menu_option();
	
	-- for control panel
	CALL sp_get_admin_cpanel_general();
	
	SELECT * FROM controlpanel WHERE flagid IN (78,75) ORDER BY flagid DESC;
	
	-- if  Use Grace Period(Credit Limit) 0 then graceperiod value will be 0 in customermaster
	SELECT `status` INTO @st FROM controlpanel WHERE flagid = 79;
	IF @st = 0 THEN
		UPDATE customermaster SET itemmustkey =0;
	END IF;
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagid = 83;
	IF @st = 0 THEN
		UPDATE customermaster SET distribution_check_id =0;
	END IF;
	
	SELECT `status` INTO @credit_execption FROM controlpanel WHERE flagid = 81;
	IF @credit_execption = 0 THEN
		UPDATE customermaster SET startdate = NULL,enddate = NULL;
	END IF;	
	
	SELECT `status` INTO @channelcode FROM controlpanel WHERE flagid = 82;
	IF @channelcode = 0 THEN
		UPDATE customermaster SET channelcode = NULL;
	END IF;
	
	SELECT `status` INTO @monthclose FROM controlpanel WHERE flagid = 6;
	UPDATE controlpanel SET `status` = @monthclose WHERE flagid = 83;		
	
END */$$
DELIMITER ;

