/* Procedure structure for procedure `sp_edit_admin_index_index` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_admin_index_index` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_admin_index_index`(
	IN Var_SetupID INT,
	IN Var_ConversionRate DECIMAL(18,6),
	IN Var_CurrencySymbol  VARCHAR(10),
	IN Var_ArbCurrencySymbol  VARCHAR(10),
	IN Var_JourneyPlanFlag INT,
	IN Var_RouteSequencePlanFlag INT,
	IN Var_WeekStartDay INT,
	IN Var_importfilepath VARCHAR(1000),
	IN Var_AllowControlonPrepareFilesFlag INT,
	IN Var_AllowNormalGCCollectionHHCFlag INT,
	IN Var_AllowPrepareFilesAfterUpload INT,
	IN Var_DefaultsOnPrepareFilesFlag INT,
	IN Var_ResendDatatoERPAllowed INT,
	IN Var_AllowCashInvoiceOnCreditCust INT,
	IN Var_CallRestrictionDaysFlag INT,
	IN Var_AllowMoreThanOneSalesman INT,
	IN Var_TransferInventoryFlag INT,
	IN Var_ENABLELOADREQUESTTOLOADOUT INT,
	IN Var_RestrictPrepareFile INT,
	IN Var_MultiDayPostingDate INT,
	IN Var_PreviousDayUploadFlag INT,
	IN var_tabletsyncmode INT,
	IN var_synctimeinterval INT,
    IN createdby VARCHAR(30)
    )
BEGIN
		UPDATE setup
            SET
			conversionrate = Var_ConversionRate,
			currencysymbol = Var_CurrencySymbol,
			arbcurrencysymbol = Var_ArbCurrencySymbol,			
			journeyplanflag = Var_JourneyPlanFlag,
			routesequenceplanflag = Var_RouteSequencePlanFlag,
			-- weekstartday = Var_WeekStartDay,
			importfilepath = Var_importfilepath,
			allowcontrolonpreparefilesflag = Var_AllowControlonPrepareFilesFlag,
			allownormalgccollectionhhcflag = Var_AllowNormalGCCollectionHHCFlag,
			allowpreparefilesafterupload = Var_AllowPrepareFilesAfterUpload,
			defaultsonpreparefilesflag = Var_DefaultsOnPrepareFilesFlag,
			resenddatatoerpallowed = Var_ResendDatatoERPAllowed,
			allowcashinvoiceoncreditcust = Var_AllowCashInvoiceOnCreditCust,
			callrestrictiondaysflag  = Var_CallRestrictionDaysFlag,
			allowmorethanonesalesman  = Var_AllowMoreThanOneSalesman,
			transferinventoryflag = Var_TransferInventoryFlag,
			enableloadrequesttoloadout = Var_ENABLELOADREQUESTTOLOADOUT,
			restrictpreparefile = Var_RestrictPrepareFile,
			multidaypostingdate = Var_MultiDayPostingDate,
			previousdayuploadflag = Var_PreviousDayUploadFlag,
			tabletsyncmode = var_tabletsyncmode,
			synctimeinterval = var_synctimeinterval,
			modifieddate = CURRENT_DATE()
            WHERE setupid = Var_SetupID;
            SELECT Var_SetupID;
            SELECT * FROM setup;
            
            -- count records for day selection combo disable.
			SELECT COUNT(*) INTO @cnt FROM salescalender;
			IF @cnt = 0 THEN 
				UPDATE setup SET weekstartday = Var_WeekStartDay WHERE setupid = Var_SetupID;
			END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_admin_security_adduser` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_admin_security_adduser` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_admin_security_adduser`(
	    IN `var_code` VARCHAR(50),
	    IN `var_username` VARCHAR(50),
	    IN `var_password` VARCHAR(30),
	    IN `var_usertypeid` BIGINT,
	    IN `var_accesstypeid` BIGINT,
	    IN var_selectionids TEXT,
	    IN createdby VARCHAR(30)
	)
BEGIN
	SELECT COUNT(*) INTO @cnt FROM usermaster WHERE username = var_username and userid != var_code;
	
	IF @cnt = 0 THEN 	
		UPDATE usermaster SET username  = var_username,
					 `password` = var_password,
					 `usertypeid` = var_usertypeid,
					 `accesstypeid` = var_accesstypeid
				WHERE userid = var_code;
		
		-- APN added 30/03/2015 to add userdetail based on usertype selected
		CALL sp_add_admin_usertype_userdetail(var_username, var_usertypeid, var_code);
		-- Insert Log
		CALL sp_add_logmaster_information('1','User Master','usermaster',var_code,createdby,'Edit');
		SELECT var_code AS lastid;
	else
		SELECT 0 AS lastid;
		CALL sp_get_admin_security_adduser(var_code);
	end if;
	
	
	-- Insert Into useraccesscodes table.
	CALL sp_add_admin_security_adduseraccesscode(var_username,var_accesstypeid,var_selectionids);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_admin_security_addusertype` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_admin_security_addusertype` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_admin_security_addusertype`(
	    IN `code` VARCHAR(50),
	    IN `name` VARCHAR(50),
	    IN adminid VARCHAR(30),
	    IN `status` VARCHAR(1),
	    IN createdby VARCHAR(30)
	)
BEGIN	
	UPDATE user_type SET user_type 	= `name`,
			     is_admin 	= adminid,
			     `status`  	= `status`
			WHERE id = `code`;
	-- 3/30/2015 APN added
	UPDATE usertype SET usertypename = `name` where usertypeid = `code`;
	-- Insert Log
	CALL sp_add_logmaster_information('1','User Type','user_type',`code`,createdby,'Edit');
	
END */$$
DELIMITER ;

