	call int_sp_error_logging('sp - sp_edit_admin_security_userpwd');
	UPDATE usermaster SET `password` = var_password where userid = var_userid and username = var_username;
	SELECT ROW_COUNT() as updatecount;
	CALL int_sp_insert_logging('usermaster',userid,createdBy,'Update','sp - sp_edit_admin_security_userpwd');
    END */$$
