DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_basic_index_addbank`(		
	    IN banknm VARCHAR(50),
	    IN arbbanknm VARCHAR(50),
	    IN bankbal DECIMAL(19,4),
	    IN modifiedby VARCHAR(50),	    
	    IN created_date DATETIME,
	    IN bankstatus INT(11),
	    IN altcode VARCHAR(30),
	    IN banktype INT(11),	    
	    IN acntnum BIGINT,
	     IN bankcd BIGINT
	)
BEGIN
	
	update bankmaster set 	bankname = banknm,
							arbbankname = arbbanknm,
							bankbalance = bankbal,
							modified = modifiedby,
							mdat= CURRENT_DATE(),
							activestatus = bankstatus,
							alternatecode = altcode,
							`type` = banktype,
							acnumber = acntnum
						where bankcode = bankcd;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Bank','bankmaster',bankcd,modifiedby,'Edit');	
	
END */$$
DELIMITER ;

