DELIMITER ;

/* Procedure structure for procedure `sp_edit_basic_index_addcompany` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_basic_index_addcompany` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_basic_index_addcompany`(		
		IN altcmpcode VARCHAR(50),	    	    
	    IN cmpname VARCHAR(50),
	    IN arbcmpname VARCHAR(100),
	    IN parentcompany BIGINT,
	    IN cont_name VARCHAR(40),	    
	    IN address VARCHAR(100),
	    IN telephone VARCHAR(50),
	    IN fax VARCHAR(50),
	    IN zipcode VARCHAR(20),
	    IN countrycode BIGINT,
	    in countryname varchar(50),
	    in taxregistrationnumber VARCHAR(50),
	    in distributorcode VARCHAR(10),
	    in activestatus int,	    
	    IN modifiedby VARCHAR(50),
	    in companycode bigint,
	    IN crno VARCHAR(50),
	    IN taxcodeno VARCHAR(50)
	)
BEGIN
	
	update company set 	`name` 					= cmpname,
							address 			= address,
							telephone 			= telephone,
							fax 				= fax,
							contactname 		= cont_name,
							arbcompanyname 		= arbcmpname,
							alternatecmpycode 	= altcmpcode,
							modified 			= modifiedby,
							mdat 				= CURRENT_DATE(),
							zipcode 			= zipcode,
							countrycode 		= countrycode,
							countryname 		= countryname,
							arbcountryname 		= arbcountryname,
							taxregistrationnumber 	= taxregistrationnumber,
							distributorcode 	= distributorcode,
							activestatus 		= activestatus,
							parentcompany 		= parentcompany,
							crno 			= crno,	
							taxcodeno 		= taxcodeno
							
							
						where cmpycode = companycode;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Company','company',companycode,modifiedby,'Edit');
END */$$
DELIMITER ;

