/* Procedure structure for procedure `sp_edit_hhctransaction_loadstock_viewloadrequestgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_hhctransaction_loadstock_viewloadrequestgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_hhctransaction_loadstock_viewloadrequestgrid`(
	    IN p_cases BIGINT,
	    IN p_pieces BIGINT,
	    IN p_id BIGINT
	)
BEGIN
		declare upc int;
		select unitspercase into upc from itemmaster where actualitemcode = (select itemcode from inventorytransactiondetail where primary_key = p_id);
		
		UPDATE 	inventorytransactiondetail SET quantity = (p_cases*upc)+p_pieces WHERE primary_key = p_id;
		
	
END */$$
DELIMITER ;

