	   IN var_reqdate 		date,
	   IN var_detailkey  	bigint(28),
	   IN var_deldate       date	
	)
BEGIN
	update inventorytransactionheader  SET 	requestdate 	= var_reqdate,deliverydate = var_deldate
									where 	detailkey  		= var_detailkey;
	
	SELECT var_detailkey AS last_id;
END */$$
