	    IN p_ActualItemCode BIGINT
	)
BEGIN
	
	UPDATE itemmaster SET   itemshortdescription = p_ItemShortDescription,
				unitspercase = p_UnitsPerCase,
				defaultsalesprice = p_DefaultSalesPrice,
				defaultreturnprice = p_DefaultReturnPrice,
