/* Procedure structure for procedure `sp_edit_inventory_index_additem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_index_additem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_index_additem`(
		    IN var_actualitemcode         BIGINT,
                    IN var_anitemcode             VARCHAR(50),
                    IN var_itemgroupcode          DECIMAL(18,0),
                    IN var_alternatecode          VARCHAR(50),
                    IN var_itemshortdescription   VARCHAR(50),
                    IN var_warehousestock         DECIMAL(18,0),
                    IN var_itemdescription        VARCHAR(50),
                    IN var_itemgrpcode            VARCHAR(10),
                    IN var_unitspercase           INT(11),
                    IN var_dataentry              INT(11),
                    IN var_liter                  FLOAT,
                    IN var_literperunit            FLOAT,
                    IN var_caseprice               DECIMAL(18,4),
                    IN var_defaultsalesprice       DECIMAL(18,4),
                    IN var_defaultgoodreturncaseprice  DECIMAL(18,4),
                    IN var_defaultgoodreturnprice  DECIMAL(18,4),
                    IN var_returncaseprice  	   DECIMAL(18,4),
                    IN var_defaultreturnprice      DECIMAL(18,4),
                    IN var_caseuom              	INT(11),
                    IN var_activeitem              	INT(11),
                    IN var_captureshelfstock      	INT(11),
                    IN var_tcallowed                INT(11),
                    IN var_allowinvoicepricechange 	INT(11),
                    IN var_arbitemdescription       VARCHAR(100),
                    IN var_arbitemshortdescription  VARCHAR(100),
                    IN var_costcaseprice       		DECIMAL(18,4),
                    IN var_defaultcostprice  		DECIMAL(18,4), 
                    IN var_barcode1 VARCHAR(20),
		    IN var_barcode2 VARCHAR(20),
                    IN var_barcode3 VARCHAR(20),
		    IN var_barcode4 VARCHAR(20),
		    IN var_barcode5 VARCHAR(20),
		    IN var_barcode6 VARCHAR(20),
		    IN var_barcode7 VARCHAR(20),
		    IN var_barcode8 VARCHAR(20),
		    IN var_barcode9 VARCHAR(20),
		    IN var_barcode10 VARCHAR(20),
                    IN var_created      CHAR(20),
                    IN var_modified     CHAR(20),
                    IN var_itemtaxkey1	INT(11),
                    IN var_itemtaxkey2	INT(11),
                    IN var_itemtaxkey3	INT(11)
    )
BEGIN
		UPDATE itemmaster SET
			anitemcode = var_anitemcode ,
			itemgroupcode  =  var_itemgroupcode,
			alternatecode = var_alternatecode,
			itemshortdescription = var_itemshortdescription,
			warehousestock = var_warehousestock,
			itemdescription = var_itemdescription,
			itemgrpcode = var_itemgrpcode,
			unitspercase = var_unitspercase,
			dataentry = var_dataentry,
			liter  = var_liter,
			literperunit = var_literperunit,
			caseprice = var_caseprice,
			defaultsalesprice = var_defaultsalesprice,
			defaultgoodreturncaseprice = var_defaultgoodreturncaseprice,
			defaultgoodreturnprice = var_defaultgoodreturnprice,
			returncaseprice = var_returncaseprice,
			defaultreturnprice = var_defaultreturnprice,
			caseuom = var_caseuom,
			activeitem = var_activeitem,
			captureshelfstock = var_captureshelfstock,
			tcallowed = var_tcallowed,
			allowinvoicepricechange = var_allowinvoicepricechange,
			arbitemdescription = var_arbitemdescription,
			arbitemshortdescription = var_arbitemshortdescription,
			costcaseprice = var_costcaseprice,
			defaultcostprice = var_defaultcostprice,
			barcode1 	= var_barcode1,
			barcode2 	= var_barcode2,
			barcode3 	= var_barcode3,
			barcode4 	= var_barcode4,
			barcode5 	= var_barcode5,
			barcode6 	= var_barcode6,
			barcode7 	= var_barcode7,
			barcode8 	= var_barcode8,
			barcode9 	= var_barcode9,
			barcode10 	= var_barcode10,
			itemtaxkey1 	= var_itemtaxkey1,
			itemtaxkey2 	= var_itemtaxkey2,
			itemtaxkey3 	= var_itemtaxkey3,
			created 	= var_created,
			modified 	= var_modified,
			cdat 		= CURRENT_DATE(),
			mdat 		= CURRENT_DATE()
		WHERE actualitemcode 	= var_actualitemcode;
		SELECT var_actualitemcode AS result;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Items','itemmaster',var_actualitemcode,var_modified,'Edit');	
		-- insert item in default group of route item group 
		-- 1 is consider as a default group code.
		-- below select query is checked in control panel table.
		SELECT `status` INTO @st FROM controlpanel WHERE flagid = 61;
		IF @st = 1 THEN
			SELECT COUNT(*) INTO @exist FROM routeitemmapping WHERE 
				itemcode = var_actualitemcode AND routeitemgrpcode = 1;
			IF @exist = 0 THEN
				INSERT INTO routeitemmapping SET itemcode = var_actualitemcode, routeitemgrpcode = 1;
			END IF;
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_index_additemgrp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_index_additemgrp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_index_additemgrp`(
           Var_ItemGroupCode BIGINT,
	   Var_AlternateItemGroupCode  VARCHAR(50),
           Var_SubMajorCategoryCode  INT,
           Var_ItemGroupName VARCHAR(50),
           Var_ARBItemGroup  VARCHAR(50),
           Var_ActiveStatus INT,
           var_modified varchar(30)
           )
BEGIN
		UPDATE itemgroup
                SET
			submajorcategorycode = Var_SubMajorCategoryCode,
			itemgroupname = Var_ItemGroupName,
			arbitemgroup = Var_ARBItemGroup,
			alternateitemgroupcode = Var_AlternateItemGroupCode,
			activestatus = Var_ActiveStatus,
			modified = var_modified,
			mdat = CURRENT_DATE()
                WHERE itemgroupcode = Var_ItemGroupCode;
                SELECT Var_ItemGroupCode;
                
		
			-- Insert Log
			CALL sp_add_logmaster_information('1','Item Group','itemgroup',Var_ItemGroupCode,var_modified,'Edit');	
		
		
    END */$$
DELIMITER ;

