			IN var_itemtype             INT(11),
			IN var_itemtaxkey1          INT(11),
			IN var_itemtaxkey2          INT(11),
			IN var_itemtaxkey3          INT(11),
			IN var_allowbatchentry      INT(11),
			IN var_packagecode          BIGINT,
			IN var_memo1       			VARCHAR(50),
			IN var_memo2  				VARCHAR(50),
