/* Procedure structure for procedure `sp_edit_inventory_routeendday_editroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_routeendday_editroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_routeendday_editroute`(
IN var_route_key text,
IN var_date VARCHAR(30)
)
BEGIN
DECLARE in_last_insert_id INT;
DECLARE in_bache_key INT;
declare inv_status int;
declare counter int default 0;
declare from_start INT DEFAULT 1;
	SELECT (LENGTH(var_route_key) - LENGTH(REPLACE(var_route_key, ',', ''))+1) into counter;
	
	
	set @Q1 = concat("UPDATE startendday SET startendday.routeenddate =date(CURRENT_DATE()),
		startendday.routeendtime = TIME(CURRENT_DATE()),
		routeclosed = 1 
		WHERE startendday.routekey in(",var_route_key,") AND routeclosed = 0 ");
	prepare s1 from @Q1;
	execute s1;
	
	
	SET @Q2 = CONCAT("UPDATE inventorysummarydetail,(
				SELECT itemcode,(IFNULL(inventorysummarydetail.loadqty,0)+IFNULL(beginstockqty,0)+
					IFNULL(loadaddqty,0)-IFNULL(loadcutqty,0)-IFNULL(saleqty,0)+IFNULL(returnqty,0)+
					IFNULL(returnfreeqty,0)-IFNULL(freesampleqty,0)) AS qnt
				FROM inventorysummarydetail
				WHERE routekey IN(",var_route_key,")
				) AS t1
			SET 
				unloadqty = t1.qnt
			WHERE routekey IN(",var_route_key,")
				AND t1.itemcode = inventorysummarydetail.itemcode");
	PREPARE s2 FROM @Q2;
	EXECUTE s2;
		
/*
pankil - for routeend add the entry in inventorytransactionheader,inventorytransactiondetail,batchexpirydetail
*/
WHILE from_start <= counter DO
	
	SET @route_key = split(var_route_key,',',from_start);
	
	SELECT routecode,salesmancode INTO @in_routecode,@in_salesmancode FROM startendday WHERE routekey = @route_key;
	
	INSERT INTO inventorytransactionheader
	(inventorykey,routekey,transactiontype,routecode,salesmancode,transactiondate, 
	transactiontime,documentnumber,voidflag,refdocumentnumber,
	currencycode,actualtransactiondate,inventorynumber)
	SELECT 
		@route_key,@route_key,3,@in_routecode,@in_salesmancode,DATE(CURRENT_DATE()),
		TIME(CURRENT_DATE()),get_number_type_base(@in_routecode,2),0,
		0,get_default_currencycode(),CURRENT_DATE(),0;
		
	SELECT LAST_INSERT_ID() INTO in_last_insert_id;
	
	SELECT IFNULL(MAX(batchdetailkey),0) INTO  in_bache_key  FROM batchexpirydetail
	WHERE routekey = @route_key;
	-- WHERE transactiontypecode = 1;
	SET in_bache_key = in_bache_key + 1;	
	
	
	INSERT INTO inventorytransactiondetail 
	(routekey,detailkey,transactiontypecode,itemcode,quantity,weighted,itemprice,batchdetailkey,
	itemcaseprice,	currencycode
	)
	SELECT
		@route_key,in_last_insert_id,6,itemcode,(IFNULL(inventorysummarydetail.loadqty,0)+IFNULL(beginstockqty,0)+IFNULL(loadaddqty,0)-IFNULL(loadcutqty,0)-IFNULL(saleqty,0)+IFNULL(returnqty,0)+IFNULL(returnfreeqty,0)-IFNULL(freesampleqty,0)) AS qnt,
		0,inventorysummarydetail.stdsalesprice,in_bache_key,inventorysummarydetail.stdsalescaseprice,
		get_default_currencycode()
	FROM 
	inventorysummarydetail
	WHERE routekey = @route_key;
	
	
	INSERT INTO batchexpirydetail(itemcode,batchdetailkey,batchnumber,expirydate,quantity,transactiontypecode,routekey,visitkey)
	SELECT itemcode,(SELECT CASE WHEN COUNT(batchdetailkey)>0 THEN batchdetailkey ELSE (SELECT MAX(batchdetailkey)+1 FROM batchexpirydetail) END AS batchdetailkey FROM batchexpirydetail WHERE transactiontypecode=5),
	batchnumber,expirydate,quantity,6,@route_key,0
	FROM batchmaster
	WHERE routekey = @route_key;
	SELECT flagid INTO inv_status FROM controlpanel WHERE flagid IN(14,64) AND `status` = 1;
	
	IF inv_status = 14 THEN
		UPDATE depotstock,(SELECT itemcode,batchnumber,expirydate,quantity
					FROM batchmaster
					WHERE routekey = @route_key) AS bm
		 SET depotstock.quantity = (depotstock.quantity + bm.quantity)
		WHERE batchno 	= bm.batchnumber
			AND depotstock.expirydate 	= bm.expirydate
			AND depotstock.itemcode 	= bm.itemcode
			AND depotcode 	= get_depotcode_routecode(@in_routecode);
	ELSEIF inv_status = 64 THEN
		UPDATE tbldepotstock,(SELECT itemcode,batchnumber,expirydate,quantity
					FROM batchmaster
					WHERE routekey = @route_key) AS bm
		SET avlquantity = (avlquantity + bm.quantity)
		WHERE batchno 	= bm.batchnumber 
			AND tbldepotstock.expirydate 	= bm.expirydate 
			AND tbldepotstock.itemcode 	= bm.itemcode
			AND depotcode 	= get_depotcode_routecode(@in_routecode);
	END IF;
	
	DELETE FROM batchmaster WHERE routekey = @route_key;
	
	SET from_start = from_start + 1;
	
END WHILE;
	/*SELECT var_route_key,in_last_insert_id,6,itemcode,
	((SUM(cases) * upc) + SUM(units)),0,
	sld.salesprice,
	in_bache_key,
	sld.caseprice,get_default_currencycode()
	
	FROM startingloaddetail sld
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE())
	GROUP BY itemcode,routecode,loadperiodnumber;
	*/	
	/*
	INSERT INTO `batchexpirydetail` 
	( batchdetailkey,batchnumber,itemcode,expirydate,quantity,transactiontypecode,routekey,visitkey)
 
	SELECT in_bache_key,batchnumber,itemcode,expirydate,((cases * upc) + (units)) AS qty , 1 ,var_route_key,0
	FROM startingloaddetail sld
	WHERE routecode = in_route_code AND loadperiodnumber = in_processload_id
	AND ddate=DATE(CURRENT_DATE());
	*/
	
  END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_target_additempackage` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_target_additempackage` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_target_additempackage`(
	    IN var_packagedescription VARCHAR(50),
		IN var_arbpackagedescription VARCHAR(50),
		IN var_activestatus INT(4),
		IN var_alternatecode VARCHAR(50),
		IN var_modified VARCHAR(50),
		in var_packagecode bigint
	)
BEGIN
	
	UPDATE 	itempackagemaster SET 
			packagedescription 		= var_packagedescription,
			alternatecode 			= var_alternatecode,
			arbpackagedescription 	= var_arbpackagedescription,
			activestatus 			= var_activestatus,
			modified 				= var_modified,
			mdat 					= CURRENT_DATE()
			where packagecode = var_packagecode;
		
	-- Insert Log
	CALL sp_add_logmaster_information('1','Item Package','itempackagemaster',var_packagecode,var_modified,'Add');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_target_additionalbarcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_target_additionalbarcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_target_additionalbarcode`(
		IN var_itemcode BIGINT(20),
		IN var_barcode3 VARCHAR(20),
		IN var_barcode4 VARCHAR(20),
		IN var_barcode5 VARCHAR(20),
		IN var_barcode6 VARCHAR(20),
		IN var_barcode7 VARCHAR(20),
		IN var_barcode8 VARCHAR(20),
		IN var_barcode9 VARCHAR(20),
		IN var_barcode10 VARCHAR(20),
		IN var_modified VARCHAR(50)
	)
BEGIN
	
	DECLARE cnt INT;
	declare tbl_key bigint;
	
	select primary_key into tbl_key from itembarcodes WHERE itemcode = var_itemcode ;
	
	SELECT COUNT(itemcode) INTO cnt FROM itembarcodes WHERE itemcode != var_itemcode and primary_key = tbl_key;
		
	IF cnt = 0 THEN 
	
		update itembarcodes SET    	itemcode 		= var_itemcode,
									barcode3 		= var_barcode3,
									barcode4 		= var_barcode4,
									barcode5 		= var_barcode5,
									barcode6 		= var_barcode6,
									barcode7 		= var_barcode7,
									barcode8 		= var_barcode8,
									barcode9 		= var_barcode9,
									barcode10 		= var_barcode10,
									modified 		= var_modified,
										mdat 		= CURRENT_DATE()
								where primary_key 	= tbl_key and itemcode = var_itemcode;
		
		select tbl_key AS last_id;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Additional Bar Code','itembarcodes',tbl_key,var_modified,'Edit');
	ELSE
			SELECT '0' AS last_id;
	END IF;
		
		CALL sp_combo_itemmaster();
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_target_addquota` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_target_addquota` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_target_addquota`(
	    IN var_quotadescription VARCHAR(20),
		IN var_arbquotadescription VARCHAR(20),
		IN var_activestatus INT(4),
