DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_target_addsalesmantarget` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_target_addsalesmantarget` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_target_addsalesmantarget`(
				
				IN var_fromdate 		VARCHAR(50),
				IN var_todate 			VARCHAR(50),
				IN var_quantity 		DECIMAL(18,4),				
				IN var_primarykey 		BIGINT(18),				
				IN var_modified 		VARCHAR(50),
				IN var_comval1 			DECIMAL(18,4),
				IN var_insentper 		DECIMAL(18,4),
				IN var_insentamt 		DECIMAL(18,4)
				
				
	)
BEGIN
	
	DECLARE var_packagenumber BIGINT;
	DECLARE var_salesmancode BIGINT;
	DECLARE var_targeton BIGINT;
	
	SELECT packagenumber,salesmancode,targettype INTO var_packagenumber,var_salesmancode,var_targeton FROM routegoal 
		WHERE primary_key = var_primarykey;
	
	-- query for checking duplicate record.
	SELECT COUNT(*) INTO @counter FROM routegoal 
		WHERE salesmancode = var_salesmancode AND packagenumber = var_packagenumber AND targettype = var_targeton AND primary_key <> var_primarykey
		AND (fromdate BETWEEN STR_TO_DATE(var_fromdate,'%d-%m-%Y') AND STR_TO_DATE(var_todate,'%d-%m-%Y') ) AND (todate BETWEEN STR_TO_DATE(var_fromdate,'%d-%m-%Y') AND STR_TO_DATE(var_todate,'%d-%m-%Y'));
	
	IF @counter = 0 THEN -- if record is exist or not.
	
			UPDATE routegoal SET
									fromdate 	= STR_TO_DATE(var_fromdate,'%d-%m-%Y'),
									todate 		= STR_TO_DATE(var_todate,'%d-%m-%Y'),
									commision       = var_comval1,									
									quantity 	= var_quantity,
									modified 	= var_modified,
									insentivepercent 	= var_insentper,
									insentive 	= var_insentamt,
									mdat 		= CURRENT_DATE()
					WHERE primary_key = var_primarykey;
			-- Insert Log
			CALL sp_add_logmaster_information('1','Salesman Target','routegoal',var_primarykey,var_modified,'Edit');
			
			SELECT var_primarykey AS last_id;
	ELSE
		SELECT 'Duplicate' AS last_id;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_adddepotinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_adddepotinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_adddepotinventory`(			
			IN var_depotinvkey BIGINT
		)
BEGIN
	
	DECLARE inv_status INT;
	
	SELECT flagid INTO inv_status FROM controlpanel WHERE `status` = 1 AND flagid IN (14,64);
	
	IF inv_status = 14 THEN 	 
		
	UPDATE depotstock AS dpts,(SELECT 	 did.itemcode,did.quantity,did.batchno,did.depotcode,did.expirydate,did.depotinvtranskey
							FROM depotinventorydetails AS did
							WHERE (did.itemcode,did.batchno,did.expirydate,did.depotcode ) 
							IN (SELECT itemcode,batchno,expirydate,depotcode FROM depotstock)
							AND did.depotinvtranskey 	= var_depotinvkey
						   ) AS tbl
	SET dpts.quantity = (dpts.quantity + tbl.quantity)		
	WHERE tbl.depotinvtranskey = var_depotinvkey AND tbl.itemcode = dpts.itemcode 
	AND dpts.batchno = tbl.batchno AND dpts.expirydate = tbl.expirydate AND  dpts.depotcode = tbl.depotcode;
	 
			
	INSERT INTO depotstock(itemcode,quantity,batchno,depotcode,expirydate) 
		SELECT 	 did.itemcode,did.quantity,did.batchno,did.depotcode,did.expirydate
		FROM depotinventorydetails AS did
		WHERE (did.itemcode ,did.batchno ,did.expirydate ,did.depotcode ) 
		NOT IN(SELECT ds.itemcode,ds.batchno,ds.expirydate,ds.depotcode FROM depotstock as ds)
		and did.depotinvtranskey 	= var_depotinvkey;
   
	
	
	ELSEIF inv_status = 64 THEN 
		
		UPDATE tbldepotstock AS dpts,(SELECT 	 did.itemcode,did.quantity,did.batchno,did.depotcode,did.expirydate,did.depotinvtranskey
							FROM depotinventorydetails AS did
							WHERE (did.itemcode,did.batchno,did.expirydate,did.depotcode ) 
							IN (SELECT itemcode,batchno,expirydate,depotcode FROM tbldepotstock)
							AND did.depotinvtranskey 	= var_depotinvkey
						   ) AS tbl
	SET dpts.quantity = (dpts.quantity + tbl.quantity)		
	WHERE tbl.depotinvtranskey = var_depotinvkey AND tbl.itemcode = dpts.itemcode 
	AND dpts.batchno = tbl.batchno AND dpts.expirydate = tbl.expirydate AND  dpts.depotcode = tbl.depotcode;
	 
			
	INSERT INTO tbldepotstock(itemcode,quantity,batchno,depotcode,expirydate) 
		SELECT 	 did.itemcode,did.quantity,did.batchno,did.depotcode,did.expirydate
		FROM depotinventorydetails AS did
		WHERE (did.itemcode ,did.batchno ,did.expirydate ,did.depotcode ) 
		NOT IN(SELECT ds.itemcode,ds.batchno,ds.expirydate,ds.depotcode FROM tbldepotstock AS ds)
		AND did.depotinvtranskey 	= var_depotinvkey;
			
	
	END IF;
	
	UPDATE depotinventoryheader SET isposted = 1 WHERE depotinvtranskey	= var_depotinvkey;	 
			
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_addopeningbal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_addopeningbal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_addopeningbal`(
		IN var_invoinum		BIGINT(18),
		IN var_routeid 		BIGINT(18),
		IN var_salesmancode BIGINT(18),
		IN var_customercode BIGINT(18),
		IN var_trantype 	INT,
		IN var_amount		DECIMAL(19,4),
		IN var_remark1		VARCHAR(50),
		IN var_remark2		VARCHAR(50),
		IN var_trandate 	DATETIME,
		IN var_modified		VARCHAR(30),
		in var_trankey      bigint(28)
    )
BEGIN
			UPDATE 	customerinvoice SET
					invoicenumber   = var_invoinum,
					routecode		= var_routeid,
					salesmancode 	= var_salesmancode,
					customercode	= var_customercode,
					transactiontype	= var_trantype,
					amountpaid		= var_amount,
					remarks1		= var_remark1,
					transactiondate = var_trandate,
					remarks2		= var_remark2
			where transactionkey = var_trankey;		
			
		-- Insert Log
		CALL sp_add_logmaster_information('1','Opening Balance','customerinvoice',var_trankey,var_modified,'Edit');
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_addrouteitemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_addrouteitemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_addrouteitemgroup`(
			IN var_description 		VARCHAR(30),
			IN var_itemgroupcode    BIGINT,
			in var_transferstatus 	int,
			IN var_itemcode 		TEXT,
			IN var_counter			INT,
			IN var_diff 			TEXT,
			IN var_diffcnt 			INT,
			IN modified_by 			VARCHAR(30),
			in var_routeitemgrpcode bigint
			
    )
BEGIN
		update 	routeitemgrp SET
				description		= var_description,
				itemgroupcode 	= var_itemgroupcode,
				transferstatus	= var_transferstatus
		where 	routeitemgrpcode= var_routeitemgrpcode;
			
		CALL sp_add_inventory_transaction_addrouteitemgroupmapping(var_itemcode,var_counter,var_routeitemgrpcode,var_diff,var_diffcnt,modified_by);
			
		-- Inser Log	
		CALL sp_add_logmaster_information('1','Route Item Group','routeitemgrp',var_routeitemgrpcode,modified_by,'Edit');	
    END */$$
