/* Procedure structure for procedure `sp_edit_inventory_transaction_changestatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_changestatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_changestatus`(
			IN var_ids TEXT
		)
BEGIN
	
	declare from_start int default 1;
	DECLARE total_record INT;
	
	
	SELECT LENGTH(var_ids) - LENGTH(REPLACE(var_ids, ',', '')) into total_record;
	set total_record = total_record + 1;
	
	while from_start <= total_record do 
		set @id = split(var_ids,',',from_start);
	
		SET @q1 = CONCAT("SELECT GROUP_CONCAT(routecode),GROUP_CONCAT(loadperiodnumber),GROUP_CONCAT(itemcode),ddate 
				INTO @routecode,@loadperiodnumber,@itemcode,@ddate
			FROM startingloaddetail WHERE loaddetailcode IN (",@id,") ");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		
		SET @q1 = CONCAT("UPDATE startingloaddetail SET `status` = 0 
			WHERE routecode IN ( ",@routecode," ) AND loadperiodnumber IN ( ",@loadperiodnumber," ) 
			AND ddate IN ( '",@ddate,"' ) ");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		-- AND itemcode IN ( ",@itemcode," ) 
		
		set from_start = from_start + 1;
	end while;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_dailysalesmanloadgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_dailysalesmanloadgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_dailysalesmanloadgrid`(
			IN var_loaddetailcode BIGINT,
			IN var_cases INT(4),
			IN var_units INT(4),
			IN var_batchnumber VARCHAR(20),
			IN var_expirydate VARCHAR(30),
			IN var_batch_st INT(4),
			IN var_ddate VARCHAR(30)
		)
BEGIN
	
	DECLARE batchentry INT(1) DEFAULT 0;
	DECLARE route_code BIGINT;
	DECLARE tran_date DATE;
	DECLARE load_no INT;
	DECLARE item_code BIGINT;
	DECLARE counter INT DEFAULT 0;
	
	SELECT allowbatchentry INTO batchentry FROM itemmaster 
		WHERE actualitemcode = ( SELECT itemcode FROM startingloaddetail 
									WHERE loaddetailcode = var_loaddetailcode);
	
	IF var_batch_st > 0 THEN
		IF batchentry = 0 THEN 
			SET var_batchnumber = 'NONE';
			SET var_expirydate	= '31-12-2099';
			SET @counter = 0;
		ELSE
			-- get batch number.
			SELECT routecode,transactiondate,loadperiodnumber,itemcode 
				INTO route_code,tran_date,load_no,item_code 
				FROM startingloaddetail WHERE loaddetailcode = var_loaddetailcode;	
			
			SET @q1 = CONCAT("SELECT COUNT(*) INTO @counter FROM startingloaddetail WHERE routecode = ",route_code," 
				AND ddate = STR_TO_DATE('",var_ddate,"','%d-%m-%Y') AND itemcode = ",item_code,"
				AND batchnumber = '",var_batchnumber,"' AND expirydate = STR_TO_DATE('",var_expirydate,"','%d-%m-%Y')				
				AND loaddetailcode <> ",var_loaddetailcode," AND loadperiodnumber = ",load_no);
			PREPARE s1 FROM @q1;
			EXECUTE s1;				
			-- select 	@q1,route_code,tran_date,item_code,var_loaddetailcode,load_no;
		END IF;
		IF @counter = 0 THEN		
			UPDATE startingloaddetail SET
					cases 		= var_cases ,
					units 		= var_units,
					batchnumber = var_batchnumber,
					expirydate	= STR_TO_DATE(var_expirydate,'%d-%m-%Y'),
					totunits	= (var_cases*upc)+var_units,
					loadtime 	= CURRENT_TIME()
				WHERE loaddetailcode = var_loaddetailcode;
			
			SELECT 'Success' AS result;
		ELSE
			SELECT 'Duplicate' AS result;
		END IF;
	ELSE
		UPDATE startingloaddetail SET
				cases 		= var_cases ,
				units 		= var_units,
				totunits	= (var_cases*upc)+var_units,
				loadtime 	= CURRENT_TIME()
			WHERE loaddetailcode = var_loaddetailcode;	
			
		SELECT var_loaddetailcode AS last_id,'Success' AS result;	
	END IF;		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_deliveryloadgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_deliveryloadgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_deliveryloadgrid`(
			IN var_id BIGINT,
			IN var_caseprice DECIMAL(18,2),
			IN var_salesprice DECIMAL(28,15),						
			IN var_cases INT(4),
			IN var_units INT(4),
			IN var_freecases INT(4),
			IN var_freeunits INT(4)
		)
BEGIN
		
		DECLARE var_quantity BIGINT;
		DECLARE var_focquantity BIGINT;
		DECLARE var_upc BIGINT;
		
		SELECT unitspercase INTO var_upc FROM deliverydetail WHERE deliveryindex = var_id;
		SELECT FLOOR(var_cases*var_upc)+(var_units) INTO var_quantity;
		SELECT FLOOR(var_freecases*var_upc)+(var_freeunits) INTO var_focquantity;
		
		
		UPDATE deliverydetail SET
				caseprice 		= var_caseprice,
				salesprice 		= var_salesprice,
				salesqty		= var_quantity,
				focqty 			=  var_focquantity
			WHERE deliveryindex = var_id;	
			
		SELECT var_id AS last_id,'Success' AS result;	
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_depotdamageexpirygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_depotdamageexpirygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_depotdamageexpirygrid`(			
			IN var_batchno varchar(50),
			IN var_expirydate VARCHAR(30),
			IN var_cases INT,
			IN var_pieces INT,			
			in var_detailid BIGINT,
			IN var_headerid BIGINT
		)
BEGIN
	
	DECLARE var_quantity BIGINT;
	declare var_upc int(11);
	
	select unitspercase into var_upc from itemmaster 
		where actualitemcode = (select actualitemcode from depotdamageexpirydetail where detailid = var_detailid);
	
	SELECT FLOOR(var_cases*var_upc)+(var_pieces) INTO var_quantity;
		
	UPDATE depotdamageexpirydetail SET 	-- batchno 	= var_batchno,
										-- expirydate = STR_TO_DATE(var_expirydate,'%d-%m-%Y'),
									 depotqty 	= var_quantity
		WHERE detailid	= var_detailid;
		
	SELECT actualitemcode,batchno,depotcode,expirydate,reasoncode
		INTO   @actualitemcode,@batchno,@depotcode,@expirydate,@reasoncode
	FROM depotdamageexpirydetail as ded,depotdamageexpiryheader as deh	
	WHERE detailid	= var_detailid and ded.headerid = deh.headerid;	
	
	select count(*),group_concat(depotinventorykey) into @counter,@depotinventorykey FROM depotstock
		WHERE 	itemcode = @actualitemcode AND batchno = @batchno
				  AND depotcode = @depotcode AND expirydate  = @expirydate; 
	
	if @counter > 0 then
		IF @reasoncode = 1 THEN -- damageqty
			UPDATE depotstock SET
					damagedqty 			= var_quantity
			WHERE   depotinventorykey   = @depotinventorykey;
		ELSE -- expiryqty
			UPDATE depotstock SET
					expiryqty 			= var_quantity
			WHERE   depotinventorykey   = @depotinventorykey; 
		end if;
	else
		IF @reasoncode = 1 THEN -- damageqty
			INSERT INTO depotstock SET
					itemcode 			= @actualitemcode,
					damagedqty 			= var_quantity,
					depotcode 			= @depotcode,
					batchno 			= @batchno,
					expirydate  		= @expirydate;
		ELSE -- expiryqty
			INSERT INTO depotstock SET
					itemcode 			= @actualitemcode,
					expiryqty 			= var_quantity,
					depotcode 			= @depotcode,
					batchno 			= @batchno,
					expirydate  		= @expirydate;		
		END IF;
	end if;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_depotinventorygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_depotinventorygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_depotinventorygrid`(			
			IN var_batchno VARCHAR(50),
			IN var_expirydate VARCHAR(30),
			IN var_cases INT,
			IN var_pieces INT,
			IN var_primary_id BIGINT,
			IN var_trankey BIGINT			
		)
BEGIN
	
	DECLARE counter INT DEFAULT 0;
	DECLARE var_quantity BIGINT;
	DECLARE var_upc INT(11);	
	DECLARE var_itemcode BIGINT;
	declare var_batch_number varchar(50);
	
	SELECT itemcode,batchno INTO var_itemcode,var_batch_number FROM depotinventorydetails WHERE primary_key = var_primary_id;
	
	SELECT IFNULL(COUNT(*),0) INTO counter FROM depotinventorydetails 
		WHERE depotinvtranskey 	= var_trankey AND itemcode = var_itemcode
		AND batchno = var_batchno AND DATE(expirydate) = STR_TO_DATE(var_expirydate,'%d-%m-%Y')
		AND primary_key != var_primary_id;
				
	IF counter = 0 THEN 
		
		SELECT unitspercase INTO var_upc FROM itemmaster WHERE actualitemcode = var_itemcode;
	
		SELECT FLOOR(var_cases*var_upc)+(var_pieces) INTO var_quantity;
		
		if var_batch_number <> 'NONE' then 
			UPDATE depotinventorydetails SET batchno 	= var_batchno,
									 expirydate = STR_TO_DATE(var_expirydate,'%d-%m-%Y'),
									 quantity 	= var_quantity
			WHERE primary_key = var_primary_id;
			
			UPDATE depotstock SET batchno 	= var_batchno,
						 expirydate = STR_TO_DATE(var_expirydate,'%d-%m-%Y'),
						 quantity 	= var_quantity
			WHERE depotinventorykey	= var_trankey AND itemcode = var_itemcode;
			
		else
			UPDATE depotinventorydetails SET quantity 	= var_quantity			
				WHERE primary_key = var_primary_id;	
	
			UPDATE depotstock SET quantity 	= var_quantity
				WHERE depotinventorykey	= var_trankey AND itemcode = var_itemcode;
		end if;	
		
		SELECT var_trankey AS lastid;
	ELSE
		SELECT 'Duplicate' AS dupli,var_trankey AS lastid;
	END IF;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_inventory_transaction_grngrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_inventory_transaction_grngrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_inventory_transaction_grngrid`(			
			IN var_availablecases INT,
			IN var_availablepieces INT,
			IN var_holdcases INT,
			IN var_holdpieces INT,
			in var_itemcode bigint,
			in var_trankey bigint
		)
BEGIN
	
	DECLARE var_availablequantity BIGINT;
	DECLARE var_holdquantity BIGINT;
	DECLARE var_fromdepot BIGINT;
	DECLARE var_todepot BIGINT;
	declare var_upc int(11);
	declare var_batchno varchar(50);
	declare var_expirydate date;
	declare var_relquantity BIGINT;
	declare var_hldquantity BIGINT;
	
	select unitspercase into var_upc from itemmaster where actualitemcode = var_itemcode;
	
	SELECT FLOOR(var_availablecases*var_upc)+(var_availablepieces) INTO var_availablequantity;
	SELECT FLOOR(var_holdcases*var_upc)+(var_holdpieces) INTO var_holdquantity;
	
	select relquantity,hldquantity into var_relquantity,var_hldquantity from tblgrdetail
		WHERE grheaderid = var_trankey AND itemcode = var_itemcode;
	
	select var_relquantity,var_hldquantity,var_availablequantity,var_holdquantity;
	UPDATE tblgrdetail SET relquantity	= var_availablequantity,
							hldquantity	= var_holdquantity
		WHERE grheaderid = var_trankey and itemcode = var_itemcode;	 
	
	IF var_relquantity > var_availablequantity THEN
		SET var_availablequantity = (var_relquantity - var_availablequantity);
	ELSE
		SET var_availablequantity = (var_availablequantity - var_relquantity);
	END IF;
	
	IF var_hldquantity > var_holdquantity THEN
		SET var_holdquantity = (var_hldquantity - var_availablequantity);
	ELSE
		SET var_holdquantity = (var_availablequantity - var_hldquantity);
	END IF;	
	
	select fromdepot,todepot into var_fromdepot,var_todepot from tblgrheader where grheaderid = var_trankey;
	
	SELECT batchno,expirydate INTO var_batchno,var_expirydate FROM tblgrdetail
		WHERE grheaderid = var_trankey and itemcode = var_itemcode;
	SELECT centralwh INTO @centralwh FROM depotmaster WHERE depotcode = var_fromdepot;	
	if @centralwh = 0 then 
		UPDATE tbldepotstock SET
							avlquantity = (avlquantity - var_availablequantity),
							hldquantity = (hldquantity - var_holdquantity)
					WHERE 	depotcode 	= var_fromdepot AND 
							itemcode  	= var_itemcode AND
							batchno 	= var_batchno AND 
							expirydate 	= var_expirydate;
   end if;
   
   UPDATE tbldepotstock SET
							avlquantity = (avlquantity + var_availablequantity),
							hldquantity = (hldquantity + var_holdquantity)
					WHERE 	depotcode 	= var_todepot AND 
							itemcode  	= var_itemcode AND
							batchno 	= var_batchno AND 
							expirydate 	= var_expirydate;
	select var_fromdepot,var_todepot;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_links_route_activenonactiveitem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_links_route_activenonactiveitem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_links_route_activenonactiveitem`(
			IN var_itemgrp   	bigint(18),
			IN var_itemid   	text,
			IN var_counter      INT
    )
BEGIN
		declare where_cond text;
		
		if var_itemgrp > 0 then
			set where_cond = concat(' AND itemgroupcode = ',var_itemgrp);
		else
			set where_cond = '';
		end if;
		
		if var_counter > 0 then 
			-- Update status to 1
			SET @edit = CONCAT("UPDATE itemmaster SET activeitem = '1' WHERE actualitemcode NOT IN (",var_itemid,") ",where_cond);
			PREPARE s1 FROM @edit;
			EXECUTE s1;
			-- Update status to 0
			SET @edit1 = CONCAT("UPDATE itemmaster SET activeitem = '0' WHERE actualitemcode IN (",var_itemid,") ",where_cond);
			PREPARE s2 FROM @edit1;
			EXECUTE s2;
		else
			-- Update status to 1
			UPDATE itemmaster SET activeitem = '1';			
		end if;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_links_route_itemsgropuchange` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_links_route_itemsgropuchange` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_links_route_itemsgropuchange`(			
			IN var_toitemgrp   	BIGINT(18),
			IN var_itemid   	TEXT
    )
BEGIN
		
			SET @edit1 = CONCAT("UPDATE itemmaster SET itemgroupcode = '",var_toitemgrp,"' WHERE actualitemcode IN (",var_itemid,") ");
			PREPARE s2 FROM @edit1;
			EXECUTE s2;
		
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_loadstock_inventorytransactionheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_loadstock_inventorytransactionheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_loadstock_inventorytransactionheader`(			
			IN var_detailkey BIGINT,
			IN var_urgent INT(4),
			IN var_warehouse DECIMAL(18,0),
			IN var_date VARCHAR(30)
		)
BEGIN
	
		UPDATE 	inventorytransactionheader SET isurgent = var_urgent, transferlocationcode = var_warehouse,
		requestdate = var_date,
		deliverydate = var_date
		WHERE detailkey = var_detailkey;		
	
END */$$
DELIMITER ;

