/* Procedure structure for procedure `sp_edit_merchandize_index_addcustomerimages` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_merchandize_index_addcustomerimages` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_merchandize_index_addcustomerimages`(
			IN var_table_id BIGINT(28),
			IN var_imagename VARCHAR(100),
			IN var_customercode BIGINT(20),
