/* Procedure structure for procedure `sp_edit_merchandize_index_addlookupindex` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_merchandize_index_addlookupindex` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_merchandize_index_addlookupindex`(
		IN descr VARCHAR(50),
	    IN arbdescr VARCHAR(50),	    
	    IN modifiedby CHAR(20),
	    in table_id bigint
	)
BEGIN
	update lookupindexheader SET 	description			= descr,
									arbdescription		= arbdescr,
									modified 			= modifiedby,
									mdat 				= CURRENT_DATE()
						where  transactionkey = table_id;
						
		select table_id as last_id;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Lookup Index','lookupindexheader',table_id,modifiedby,'Edit');
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_merchandize_index_addsurvey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_merchandize_index_addsurvey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_merchandize_index_addsurvey`(
			IN var_surveyindex        	DECIMAL(18,0),
			IN var_surveyprompt        	VARCHAR(50),
			IN var_arbsurveyprompt      VARCHAR(200),
			IN var_surveyrectype        INT(11),
			IN var_responselength 	   	INT(11),
			IN var_responsedecimalpos	INT(11),
			IN var_lookuptype 			INT(11),
			IN var_ddllkindex  			int(11),
			in var_status				INT(11),
			IN var_modified		   		VARCHAR(30),
			IN var_surveycode   		bigint
			
    )
BEGIN
		update customersurveydefinition SET	surveyindex			= var_surveyindex,
											surveyprompt		= var_surveyprompt,
											arbsurveyprompt 	= var_arbsurveyprompt,
											surveyrectype		= var_surveyrectype,
											responselength 		= var_responselength,
											responsedecimalpos	= var_responsedecimalpos,
											lookuptype 			= var_lookuptype,
											lookupindex			= var_ddllkindex,
											activestatus 		= var_status,
											modified 			= var_modified,
											mdat 				= CURRENT_DATE()
									where surveydefkey = var_surveycode;
		SELECT var_surveycode;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Survey Definition','customersurveydefinition',var_surveycode,var_modified,'Edit');
		
    END */$$
DELIMITER ;

