/* Procedure structure for procedure `sp_edit_merchandize_index_addsurveyplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_merchandize_index_addsurveyplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_merchandize_index_addsurveyplan`(
			IN var_surveydescription        VARCHAR(50),
			IN var_arbsurveydescription 	VARCHAR(200),
			IN var_surveysequencenumber 	DECIMAL(18,0),
			IN var_surveymandatory   		INT,
			in var_surveydefkey 			text,
			in var_counter					int,
			IN var_division        VARCHAR(50),
			in var_modified 				varchar(30),
			IN var_surveyplankey 			BIGINT
    )
BEGIN
		UPDATE 		customersurveyplan SET
					surveysequencenumber	= var_surveysequencenumber,
					surveymandatory 		= var_surveymandatory,
					surveydescription		= var_surveydescription,
					arbsurveydescription	= var_arbsurveydescription,					
					remarks =var_division,
					modified 				= var_modified,
					mdat 					= CURRENT_DATE()					
					where surveyplankey 	= var_surveyplankey;
					
			call sp_add_merchandize_index_addcustomersurveydefassign(var_surveydefkey,var_counter,var_surveyplankey,var_modified);
			
			-- Insert Log
			CALL sp_add_logmaster_information('1','Survey Plan','customersurveyplan',var_surveyplankey,var_modified,'Edit');
    END */$$
