	   IN catname VARCHAR(50),
	   IN arbcatname VARCHAR(50),
	   IN createdby VARCHAR(30),
	   in catid bigint
	)
BEGIN
	update routecategory  SET 	routecatname 	= catname,
								arbroutecatname = arbcatname,
								modified 		= createdby,
								mdat 			= current_date()
							where routecatcode  = catid;
	
	SELECT catid AS last_id;
	-- Insert Log
	CALL sp_add_logmaster_information('1','Route Category','routecategory',catid,createdby,'Edit');
END */$$
