			  unloadoversellmessage	= var_unloadoversellmessage,                           
			       reqeodroasummary = var_reqeodroasummary,
			    inventoryvalueprint = var_inventoryvalueprint,
			       routeitemgrpcode = var_routeitemgrpcode,
			 itemdescriptiondisplay = var_itemdescriptiondisplay,
			     enableloadtransfer = var_enableloadtransfer,
			       enablescanneruse = var_enablescanneruse,
			         enablepostvoid = var_enablepostvoid,
			     enableeodaddchecks = var_enableeodaddchecks,
			      enableeodexpenses = var_enableeodexpenses,
			     enableeodadjchecks = var_enableeodadjchecks,
			     loadoutadjustments = var_loadoutadjustments,
			      enableaddcustomer = var_enableaddcustomer,
			        enablestockicon = var_enablestockicon,
		 enablestartdaydatetimeedit = var_enablestartdaydatetimeedit,
				   enabledelayprint = var_enabledelayprint,
				enforcecallsequence = var_enforcecallsequence,
					 enablefoclimit = var_enablefoclimit,
			 enablecashonlydiscount = var_enablecashonlydiscount,
				 reqeodnosalereport = var_reqeodnosalereport,
		   generatehhcseqfromboflag = var_generatehhcseqfromboflag,
					   enablenosale	= var_enablenosale,
				 reqeodnondelreport = var_reqeodnondelreport,
				  allowpopulateload = var_allowpopulateload,
						cashbalance	= var_cashbalance,
					  allowgctocash = var_allowgctocash,
			 allowroutestartdayflag	= var_allowroutestartdayflag,
			 	 reqeodprcchgreport = var_reqeodprcchgreport,
					  invenoversell = var_invenoversell,
				  enabledamagedtrxn = var_enabledamagedtrxn,
