			    reqeododomlogreport = var_reqeododomlogreport,
				   usesalesdateflag = var_usesalesdateflag,
				  displayinvsummary = var_displayinvsummary,
				 includeloadrequest = var_includeloadrequest,
						creditlimit = var_creditlimit,
				defaultdeliverydays = var_defaultdeliverydays,
				loadreqrolluporders = var_loadreqrolluporders,
					   depotprinter = var_depotprinter,
					    tlockstatus = var_tlockstatus,
					  loadreqmethod = var_loadreqmethod,
					   routeprinter = var_routeprinter,
					      routetype = var_routetype,
				 reqeodexceptionrpt = var_reqeodexceptionrpt,
					passwordarray01 = var_passwordarray1,
					passwordarray07 = var_passwordarray7,
					passwordarray02 = var_passwordarray2,
					passwordarray08 = var_passwordarray8,
					passwordarray03 = var_passwordarray3,
					passwordarray09 = var_passwordarray9,
					passwordarray04 = var_passwordarray4,
					passwordarray13 = var_passwordarray13,
					passwordarray16 = var_passwordarray16,
					passwordarray11 = var_passwordarray11,
				 reqeodpromosreport = var_reqeodpromosreport,
				  inventoryvariance = var_inventoryvariance,
					loadsheetreport = var_loadsheetreport,
			 inventoryreportcontrol = var_inventoryreportcontrol,
		 enablestartdayrtewkdayedit = var_enablestartdayrtewkdayedit,
					itemcodedisplay = var_itemcodedisplay,					  
						  modified	= var_modified,
							mdat	= CURRENT_DATE()
				where routecode	= var_templateid;
				
	SELECT var_templateid AS last_id;
	
	-- For Combo Box
	SELECT routecode AS id,routecode AS val FROM routemaster WHERE routetmpl	= 1;
	
	-- For Route Item Group
	CALL sp_combo_routeitemgrp();
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Route Template','routemaster',var_templateid,var_modified,'Edit');
		
    END */$$
