/* Procedure structure for procedure `sp_edit_promotions_customer_freegoodsgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_promotions_customer_freegoodsgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_promotions_customer_freegoodsgrid`(
					IN p_freequantity   BIGINT,
                    IN p_contractid		BIGINT,
                    in p_itemcode 		bigint,
                    IN p_foc 		BIGINT
    )
BEGIN
	
		update customer_foc_detail set 
				freequantity = p_freequantity
			where contractid = p_contractid and itemcode = p_itemcode;
		
		update customer_foc_balance set 
				originalqty = p_freequantity,
				balanceqty 	= p_freequantity - p_foc
		WHERE 	contractid 	= p_contractid AND itemcode = p_itemcode;
	
    END */$$
