/* Procedure structure for procedure `sp_edit_promotions_supervisor_addfreegoods` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_promotions_supervisor_addfreegoods` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_promotions_supervisor_addfreegoods`(		
	   IN p_creationdate VARCHAR(50),
	   IN p_remarks VARCHAR(50),
	   IN p_startdate VARCHAR(50),
	   IN p_enddate VARCHAR(50),
	   IN p_active BIGINT,
	   IN p_depotcode BIGINT,
	   IN p_contractid BIGINT,
	   IN modified_by VARCHAR(30)
	)
BEGIN
	UPDATE supervisor_foc  SET
		creationdate 	= p_creationdate,
		remarks 		= p_remarks,
		startdate 		= p_startdate,
		enddate 		= p_enddate,
		active 			= p_active
	WHERE contractid 	= p_contractid;		
	
	-- Insert Log
	CALL sp_add_logmaster_information('1','Supervisor Free Goods','supervisor_foc',p_contractid,modified_by,'Edit');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_edit_promotions_supervisor_freegoodsgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_promotions_supervisor_freegoodsgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_promotions_supervisor_freegoodsgrid`(
					IN p_freequantity   BIGINT,
                    IN p_contractid		BIGINT,
                    IN p_itemcode 		BIGINT,
                    IN p_foc 		BIGINT
    )
BEGIN
	
		UPDATE supervisor_foc_detail SET 
				freequantity = p_freequantity
			WHERE contractid = p_contractid AND itemcode = p_itemcode;
		
		UPDATE supervisor_foc_balance SET 
				originalqty = p_freequantity,
				balanceqty 	= p_freequantity - p_foc
		WHERE 	contractid 	= p_contractid AND itemcode = p_itemcode;
	
    END */$$
DELIMITER ;

