/* Procedure structure for procedure `sp_edit_transaction_invoiceadd_detail1` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_edit_transaction_invoiceadd_detail1` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_edit_transaction_invoiceadd_detail1`(
IN var_invoicenumber DECIMAL(28,0),
IN var_documentnumber DECIMAL(28,0),
IN var_routecode DECIMAL(18,0),
IN var_customercode DECIMAL(18,0),
IN var_comment varchar(200),
IN in_output BLOB,
IN in_invoice_transaction_key int
)
BEGIN
DECLARE var_salesmancode INT;
DECLARE in_route_key_code INT;
	
	SELECT salesmancode INTO var_salesmancode FROM routemaster  WHERE routemaster.routecode = var_routecode;
	SELECT routekey INTO in_route_key_code FROM startendday 
	WHERE startendday.routecode=var_routecode
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	update invoiceheader_temp set 
	routekey  =in_route_key_code ,
	routecode = var_routecode,
	salesmancode = var_salesmancode,
	customercode = var_customercode,
	comments = var_comment
	where transactionkey = in_invoice_transaction_key;
	
	select transactionkey as invoice_transaction_key ,
	       routekey,
	       visitkey 
	 FROM invoiceheader_temp 
	where transactionkey = in_invoice_transaction_key;
	
	CALL sp_add_transaction_invoiceadd_signaturedata(in_invoice_transaction_key,in_route_key_code,in_invoice_transaction_key,var_customercode,0,in_output);
    
END */$$
DELIMITER ;

