/* Procedure structure for procedure `sp_getcombobox_account_customerseq_arrangecustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_getcombobox_account_customerseq_arrangecustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_getcombobox_account_customerseq_arrangecustomer`(in route_code int(4),IN week_no INT(4))
BEGIN
		-- For Route Combo
		CALL sp_combo_routemaster();
		
		-- For Customer Information
		-- SELECT customercode,alternatecode ,customername FROM customermaster where routecode = route_code order by customercode;
		SELECT cust.customername,cust.arbcustomername,cust.alternatecode, rs.* FROM routesequence AS rs
			RIGHT JOIN customermaster AS cust ON cust.customercode = rs.customercode
			WHERE rp32weeknumber = week_no AND rs.routecode = route_code
