/* Procedure structure for procedure `sp_getcombobox_account_customer_addcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_getcombobox_account_customer_addcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_getcombobox_account_customer_addcustomer`()
BEGIN
	-- For Pricekey Data
	CALL sp_combo_pricingkey();
		
	-- For Route Data
	CALL sp_combo_routemaster();
	
	-- For Promotional Key	
	CALL sp_combo_promotionkey();
	
	-- For Customer Category
	SELECT categoryid AS id, CONCAT(categoryid,' --- ',categoryname) AS val FROM categorymaster;
	
	-- For Survey Key
	SELECT surveykey AS id, CONCAT(surveykey,' --- ',surveydescription) AS val FROM customersurveykey;
	
	-- For Discount Key
	SELECT discountkey AS id, CONCAT(discountkey,' --- ',description) AS val FROM discountkeyheader;	
	
	-- For Distribution Key
	SELECT distributionkey AS id, CONCAT(distributionkey,' --- ',description) AS val FROM distributionkeyheader;
	
	-- For Authorized Item Group Key	
	SELECT groupnumber AS id, CONCAT(groupnumber,' --- ',groupdescription) AS val FROM productgroupheader WHERE grouptype = 3;
	
	-- For Headoffice
	CALL sp_combo_headoffice();
	
	-- For Outlet Product Code
	SELECT groupcode AS id, CONCAT(groupcode,' --- ',groupname) AS val FROM groupmaster;
		
	-- For Getting Auto Increment ID
	SHOW TABLE STATUS LIKE 'customermaster';
	
	-- For Template Combo	
	SELECT customercode AS id, CONCAT(customercode,' --- ',templatename) AS val FROM customermaster WHERE templateindicator = 1;
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79,81,82);
	
	SELECT taxcode AS id, CONCAT(taxcode,' --- ',taxdescription) AS val FROM taxmaster;
	
	CALL sp_combo_itemmust();
	
	CALL sp_combo_channel();		
 
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_getcombobox_account_customer_addcustomertmpl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_getcombobox_account_customer_addcustomertmpl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_getcombobox_account_customer_addcustomertmpl`()
BEGIN
	-- For Pricekey Data
	CALL sp_combo_pricingkey();
		
	-- For Route Data
	CALL sp_combo_routemaster();
	
	-- For Promotional Key
	CALL sp_combo_promotionkey();
	
	-- For Customer Category
	SELECT categoryid AS id, CONCAT(categoryid,' -- ',categoryname) AS val FROM categorymaster;
	
	-- For Survey Key
	SELECT surveykey AS id, CONCAT(surveykey,' -- ',surveydescription) AS val FROM customersurveykey;
	
	-- For Discount Key
	SELECT discountkey AS id, CONCAT(discountkey,' -- ',description) AS val FROM discountkeyheader;
	
	-- For Distribution Key
	SELECT distributionkey AS id, CONCAT(distributionkey,' -- ',description) AS val FROM distributionkeyheader;
	
	-- For Authorized Item Group Key	
	SELECT groupnumber AS id, CONCAT(groupnumber,' -- ',groupdescription) AS val FROM productgroupheader WHERE grouptype = 3;
	
	-- For Headoffice
	CALL sp_combo_headoffice();
	
	-- For Outlet Product Code
	SELECT groupcode AS id, CONCAT(groupcode,' -- ',groupname) AS val FROM groupmaster;
	
	-- For Template Combo	
	SELECT customercode AS id, CONCAT(customercode,' --- ',templatename) AS val FROM customermaster WHERE templateindicator = 1;
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79);
	
	SELECT taxcode AS id, CONCAT(taxcode,' --- ',taxdescription) AS val FROM taxmaster;
	
	CALL sp_combo_itemmust();
	
	-- For loyality key
	SELECT loyaltykeyid AS id,CONCAT(loyaltykeyid,' --- ',description) AS val FROM loyaltykeyheader;	
	
END */$$
DELIMITER ;

