/* Procedure structure for procedure `sp_get_account_customerseq_addcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customerseq_addcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customerseq_addcustomer`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN route_code BIGINT,
	IN week_no INT,
	IN main_rootid BIGINT(18)
	 )
BEGIN
	DECLARE add_where TEXT DEFAULT NULL;
	DECLARE sel_qry TEXT DEFAULT NULL;
	
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'customercode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'cm.*';
	END IF;
	
	-- if main root id and current root id different than all the customer are coming from main rootid
	IF route_code != main_rootid THEN
		SET sel_qry = CONCAT(" SELECT customercode FROM  routesequence 
				WHERE routecode =  ",main_rootid," AND rp32weeknumber = ",week_no," AND activecustomer = 1");
	ELSE
		SET sel_qry = CONCAT(" SELECT customercode FROM  routesequence 
				WHERE rp32weeknumber = ",week_no,"  AND routecode =  ",route_code," AND activecustomer = 1");
	END IF;
	
	/* Fetch allowmorethanonesalesman from setup for display multiple customer */
	SELECT allowmorethanonesalesman  INTO @allow_multiple_customer FROM setup;
	
	IF @allow_multiple_customer = 0 THEN 
		SET add_where = CONCAT(" routecode = ",route_code);
	ELSE
		SET add_where = "1 = 1";
	END IF;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM customermaster AS cm 
	WHERE ",add_where," AND cm.`type` < 3 AND activecustomer = 1 AND customercode NOT IN ( ",sel_qry," ) AND templateindicator = 0 AND routecode =  ",route_code," ",table_where); 
	
	PREPARE cnt1 FROM @cnt_sql;
	EXECUTE cnt1;	
    
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customermaster AS cm 
	WHERE ",add_where," AND cm.`type` < 3 AND activecustomer = 1 AND customercode NOT IN ( ",sel_qry," ) AND templateindicator = 0 AND routecode =  ",route_code," ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");    
    
    PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	-- SELECT @dyn_sql;
	CALL sp_combo_routemaster();
	
	CALL sp_get_setup_option();
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_customerseq_routesequence` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customerseq_routesequence` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customerseq_routesequence`(
	in route_code bigint,
	IN week_no int,	
	in field_name varchar(30),
	in day_name varchar(10)
	 )
BEGIN
	CALL sp_combo_routemaster();
	CALL sp_get_weekstart_day();
	
	IF day_name = 'satseq' THEN
		SET field_name = 'callrestrictiondays6';
	ELSEIF day_name = 'sunseq' THEN
		SET field_name = 'callrestrictiondays7';
	ELSEIF day_name = 'monseq' THEN
		SET field_name = 'callrestrictiondays1';
	ELSEIF day_name = 'tueseq' THEN
		SET field_name = 'callrestrictiondays2';
	ELSEiF day_name = 'wedseq' THEN
		SET field_name = 'callrestrictiondays3';
	ELSEIF day_name = 'thuseq' THEN
		SET field_name = 'callrestrictiondays4';
	ELSE
		SET field_name = 'callrestrictiondays5';
	END IF;
	
	
	set @qry = concat("SELECT rs.customercode,",day_name," as dayname,cm.alternatecode,cm.customername,cm.arbcustomername,cm.customeraddress1,cm.customeraddress2,cm.customeraddress3 FROM routesequence AS rs
					   LEFT JOIN customermaster AS cm ON cm.customercode = rs.customercode
					   WHERE rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," 
					   AND ",field_name," = 1 ORDER BY ",day_name," ASC");
	
	prepare s1 from @qry;
	execute s1;
	-- select @qry;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_customerseq_routesequence_print` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customerseq_routesequence_print` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customerseq_routesequence_print`(
	IN route_code BIGINT,
	IN week_no INT,	
	IN field_name VARCHAR(30),
	IN day_name VARCHAR(10),
	IN printoption INT
	 )
BEGIN
	CALL sp_combo_routemaster();
	CALL sp_get_weekstart_day();
	
	IF printoption = 0 THEN
		IF day_name = 'satseq' THEN
			SET field_name = 'callrestrictiondays6';
		ELSEIF day_name = 'sunseq' THEN
			SET field_name = 'callrestrictiondays7';
		ELSEIF day_name = 'monseq' THEN
			SET field_name = 'callrestrictiondays1';
		ELSEIF day_name = 'tueseq' THEN
			SET field_name = 'callrestrictiondays2';
		ELSEIF day_name = 'wedseq' THEN
			SET field_name = 'callrestrictiondays3';
		ELSEIF day_name = 'thuseq' THEN
			SET field_name = 'callrestrictiondays4';
		ELSE
			SET field_name = 'callrestrictiondays5';
		END IF;
	
		IF field_name = "callrestrictiondays1" THEN
			SET @day = "MON";
		ELSEIF field_name = "callrestrictiondays2" THEN
			SET @day = "TUE";
		ELSEIF field_name = "callrestrictiondays3" THEN
			SET @day = "WED";
		ELSEIF field_name = "callrestrictiondays4" THEN
			SET @day = "THU";
		ELSEIF field_name = "callrestrictiondays5" THEN
			SET @day = "FRI";
		ELSEIF field_name = "callrestrictiondays6" THEN
			SET @day = "SAT";
		ELSEIF field_name = "callrestrictiondays7" THEN
			SET @day = "SUN";
		END IF;
		
		SET @qry = CONCAT("
			SELECT rs.customercode, '",@day,"' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3
			FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," AND ",field_name," = 1 ORDER BY 3");
					
	ELSE
	
		SET @qry = CONCAT("
			SELECT rs.customercode, 'MON' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 3 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays1 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," UNION
			SELECT rs.customercode, 'TUE' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 4 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays2 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," UNION
			SELECT rs.customercode, 'WED' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 5 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays3 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," UNION
			SELECT rs.customercode, 'THU' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 6 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays4 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," UNION
			SELECT rs.customercode, 'FRI' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 7 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays5 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," UNION
			SELECT rs.customercode, 'SAT' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 1 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays6 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," UNION
			SELECT rs.customercode, 'SUN' as dayname, cm.alternatecode, cm.customername, cm.arbcustomername, CONCAT(cm.customeraddress1,cm.customeraddress2,cm.customeraddress3) customeraddress1, '' customeraddress2, '' customeraddress3, 2 id FROM routesequence AS rs INNER JOIN customermaster AS cm ON cm.customercode = rs.customercode
			WHERE rs.callrestrictiondays7 = 1 AND rs.routecode = ",route_code," AND rp32weeknumber = ",week_no," 		
			ORDER BY 9");
	END IF;
	
	PREPARE s1 FROM @qry;
	EXECUTE s1;
	-- select @qry;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_customerseq_salescalendar` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customerseq_salescalendar` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customerseq_salescalendar`( in sales_year int(4))
BEGIN
		
		SELECT date_format(weekstartdate,'%d-%m-%Y') as weekstartdate,date_format(weekenddate,'%d-%m-%Y') as weekenddate,weeknumber,salesperiod,rp32weeknumber FROM salescalender WHERE salesyear = sales_year ORDER BY weeknumber ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_customer_addauthorizegroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_addauthorizegroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_addauthorizegroup`(IN id BIGINT)
BEGIN
	#For itemmaster table
	#SELECT actualitemcode AS id, CONCAT(actualitemcode,' -- ',itemshortdescription) AS val FROM itemmaster; 
	CALL sp_combo_itemgroup();
	
	if id > 0 then
		#For productgroupheader
		SELECT * FROM `productgroupheader` WHERE `groupnumber` = id;
	else
		call sp_get_table_last_id('productgroupheader');
	end if;	
	#For Case Price & PC Price
	SELECT actualitemcode,unitspercase,defaultsalesprice,caseprice,defaultreturnprice FROM itemmaster;
	
END */$$
