/* Procedure structure for procedure `sp_get_account_customer_addauthorizegroupgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_addauthorizegroupgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_addauthorizegroupgrid`(
	IN srchvalue VARCHAR(500), 	-- for searching keywords
	IN order_by VARCHAR(500),	-- for order by
	IN order_type VARCHAR(10),	-- for order type
	IN lmt_strt INT,		-- for limit start
	IN lmt_end INT, 			-- for limit end
	IN table_fields TEXT, 			
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	SET @dyn_sql1 = CONCAT("SELECT COUNT(im.actualitemcode) AS counter FROM productgroupdetail AS pgd 
		LEFT JOIN itemmaster AS im ON pgd.itemcode = im.actualitemcode 
		LEFT JOIN productgroupheader AS pgh ON pgh.groupnumber = pgd.groupnumber
		WHERE 1=1 AND im.actualitemcode IS NOT NULL ",table_where);
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
	
	SET @dyn_sql2 = CONCAT("SELECT ",table_fields," FROM productgroupdetail AS pgd 
		LEFT JOIN itemmaster AS im ON pgd.itemcode = im.actualitemcode 
		LEFT JOIN productgroupheader AS pgh ON pgh.groupnumber = pgd.groupnumber WHERE 1=1 AND im.actualitemcode IS NOT NULL ", table_where,
		" ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end);
	#SELECT @dyn_sql2;
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
	
END */$$
DELIMITER ;

