/* Procedure structure for procedure `sp_get_account_customer_addcustassetinfo` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_customer_addcustassetinfo` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_customer_addcustassetinfo`()
BEGIN
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
		
	
	    IF @st = 1 THEN 
		SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 ; 
		SELECT assetcode AS id, CONCAT(alternatecode,' -- ',assetname) AS val FROM assetmaster WHERE assetstatus = 1 ;
	    ELSE
		SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0;
		SELECT assetcode AS id, CONCAT(assetcode,' -- ',assetname) AS val FROM assetmaster WHERE assetstatus = 1 ;  
	    END IF;
END */$$
