		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM customermaster AS cm
		LEFT JOIN invoiceheader AS ih ON ih.customercode = cm.customercode
		WHERE 1=1  ",table_where," GROUP BY cm.customercode ");
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customermaster AS cm
		LEFT JOIN invoiceheader AS ih ON ih.customercode = cm.customercode
		WHERE 1=1  ",table_where,  " GROUP BY cm.customercode  ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
		
    END */$$
