/* Procedure structure for procedure `sp_get_account_notes_adddebitcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_notes_adddebitcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_notes_adddebitcustomer`(
	IN id 			BIGINT(20),
	in trandate		varchar(30)
    )
BEGIN
		CALL sp_combo_routemaster();		
				
		IF id > 0 THEN 
			SELECT dcah.*,dd.invoicenumber AS dd_invoicenumber FROM dcarheader AS dcah
				LEFT JOIN dcardetail AS dd ON dd.transactionkey = dcah.transactionkey
				LEFT JOIN customerinvoice AS ci ON ci.transactionkey = dd.invoicenumber
				WHERE dcah.transactionkey = id;
		ELSE
			SELECT 1;
		END IF;
		
		call sp_get_table_last_id('dcarheader');
    END */$$
DELIMITER ;

