DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_notes_invoicetotal`(
		IN ids text
    )
BEGIN
		set @q1 = concat("SELECT SUM(totalinvoiceamount) AS invoiceamt,
							SUM(amountpaid) AS amountpaid, 
							SUM(invoicebalance) AS balanceamt
							FROM customerinvoice
							WHERE transactionkey IN(",ids,")");
		prepare s1 from @q1;
		EXECUTE s1;
    END */$$
