/* Procedure structure for procedure `sp_get_account_settlement_pdcclearance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_pdcclearance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_pdcclearance`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'pdc.transactionkey';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'transactionkey.*';
		END IF;
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM pdcclearenceheader AS pdc
							LEFT JOIN salesman AS sm ON sm.salesmancode = pdc.salesmancode
							LEFT JOIN routemaster AS rm ON rm.routecode = pdc.routecode
							LEFT JOIN customermaster AS cm ON cm.customercode = pdc.customercode
							WHERE 1 =1 ",table_where);
		-- select @cnt_sql;
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM pdcclearenceheader AS pdc
							LEFT JOIN salesman AS sm ON sm.salesmancode = pdc.salesmancode
							LEFT JOIN routemaster AS rm ON rm.routecode = pdc.routecode
							LEFT JOIN customermaster AS cm ON cm.customercode = pdc.customercode							
							LEFT JOIN bankmaster AS bm ON bm.bankcode = pdc.bankcode
							WHERE 1 = 1 ",table_where," ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		-- select @dyn_sql;
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
	-- 	select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_settlement_pdc_crheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_settlement_pdc_crheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_settlement_pdc_crheader`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'edit_del_primary_id';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'crh.*';
		END IF;
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM cashierreceiptheader crh
								LEFT JOIN cashierreceiptdetails crd on crd.documentnumber = crh.documentnumber
								WHERE 1 = 1 AND crh.paymenttype = 1",table_where,"
							UNION (
								SELECT
								  COUNT(*) AS counter
								FROM customerinvoice ci
								  LEFT JOIN salesman sm
									ON sm.salesmancode = ci.salesmancode
								  LEFT JOIN routemaster rm
									ON rm.routecode = ci.routecode 
								WHERE ci.pdcbalance > 0 AND ci.pdcindicator = 1 AND ci.transactiontype = 1
								)");
		-- crh.pdcbalance > 0
		
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"  FROM cashierreceiptheader crh
								LEFT JOIN cashierreceiptdetails crd on crd.documentnumber = crh.documentnumber
								LEFT JOIN salesman sm ON sm.salesmancode = crh.salesmancode
								LEFT JOIN routemaster rm ON rm.routecode = crh.routecode
								WHERE 1 = 1 AND crh.paymenttype = 1 ",table_where,"
							UNION (
									SELECT
									  ci.salesmancode,
									  sm.salesmanname1,
									  ci.routecode,
									  rm.routename,
									  2 AS sett_tran_type,
									  ci.transactionkey as edit_del_primary_id
									FROM customerinvoice ci
									  LEFT JOIN salesman sm
										ON sm.salesmancode = ci.salesmancode
									  LEFT JOIN routemaster rm
										ON rm.routecode = ci.routecode 
									WHERE ci.pdcbalance > 0 AND ci.pdcindicator = 1 AND ci.transactiontype = 1
									) ORDER BY ",order_by," ",
							order_type," LIMIT ",lmt_strt,", ",lmt_end);
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
		-- select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_account_tax` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_tax` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_tax`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'taxcode';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'tax.*';
	END IF;
    
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter 
	FROM tbltaxmaster AS tax 
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
	FROM tbltaxmaster AS tax 
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end);
	
	PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
    
END */$$
