/* Procedure structure for procedure `sp_get_account_transaction_addgccolletion` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_account_transaction_addgccolletion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_transaction_addgccolletion`(
	IN id 			BIGINT(20)
    )
BEGIN
		declare paytype int(4);
		
		CALL sp_combo_routemaster_actran();
		call sp_combo_bankmaster();
				
		IF id > 0 THEN 
			SELECT *  FROM bearheader WHERE transactionkey = id  AND trantype = 2;
		ELSE
			CALL sp_get_table_last_id('bearheader');
		END IF;
		
		IF id > 0 THEN 
			select typecode into paytype FROM bearcashcheckdetail where transactionkey = id;
			
			if paytype > 0 then
				SELECT typecode,checknumber,DATE_FORMAT(checkdate,'%d-%m-%Y') AS checkdate,SUM(amount) AS amount,bm.bankname 
					FROM bearcashcheckdetail AS bcd,bankmaster AS bm 
				WHERE bm.bankcode = bcd.bankcode AND transactionkey = id
					GROUP BY transactionkey;
			else
				SELECT typecode,SUM(amount) AS amount FROM bearcashcheckdetail
					WHERE transactionkey = id
					GROUP BY transactionkey;
			end if;
		end if;
    END */$$
DELIMITER ;

