DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_account_transaction_monthcloseview`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'itemcode';
		END IF;
		
		/*if order_by = 'month_name(bmonth) AS bmonth' then
			SET order_by = 'bmonth';
		END IF; */
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'mc.*';
		END IF;
		SET @cnt_sql = CONCAT(" SELECT count(*) AS counter
								FROM monthlysummarizationperroute,itemmaster
								WHERE monthlysummarizationperroute.itemcode = itemmaster.actualitemcode
								",table_where);
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM monthlysummarizationperroute,itemmaster
							WHERE monthlysummarizationperroute.itemcode = itemmaster.actualitemcode
							",table_where," ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
		SELECT @dyn_sql;
    END */$$
DELIMITER ;

