/* Procedure structure for procedure `sp_get_admin_security_adduseraccesscode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_admin_security_adduseraccesscode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_admin_security_adduseraccesscode`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	in table_name varchar(150)
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'id';
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 't1.*';
	END IF;
	
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM ",table_name," AS t1 
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM ",table_name," AS t1	
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	-- select @dyn_sql;	 
END */$$
