/* Procedure structure for procedure `sp_get_admin_security_selecteduseraccesscode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_admin_security_selecteduseraccesscode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_admin_security_selecteduseraccesscode`(
	IN var_username varchar(150),
	IN var_accesscode int(4)
)
BEGIN
	
	if var_accesscode = 1 then 
		select GROUP_CONCAT(DISTINCT(cmpycode)) as selected from useraccesscodes where username = var_username;
	elseif var_accesscode = 2 then
		SELECT GROUP_CONCAT(DISTINCT(countrycode)) AS selected FROM useraccesscodes WHERE username = var_username;
	ELSEIF var_accesscode = 3 THEN
		SELECT GROUP_CONCAT(DISTINCT(regionmstcode)) AS selected FROM useraccesscodes WHERE username = var_username;
	ELSEIF var_accesscode = 4 THEN
		SELECT GROUP_CONCAT(DISTINCT(depotcode)) AS selected FROM useraccesscodes WHERE username = var_username;
	ELSEIF var_accesscode = 5 THEN
		SELECT GROUP_CONCAT(DISTINCT(areacode)) AS selected FROM useraccesscodes WHERE username = var_username;
	ELSEIF var_accesscode = 6 THEN
		SELECT GROUP_CONCAT(DISTINCT(subareacode)) AS selected FROM useraccesscodes WHERE username = var_username;
	End IF;
	
END */$$
DELIMITER ;

