/* Procedure structure for procedure `sp_get_customer_from_outletproductcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_customer_from_outletproductcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_customer_from_outletproductcode`(
					IN outletprod 	VARCHAR(20),
					IN cust_cat 	varchar(20),
					in fillby 		VARCHAR(20),
					in val			VARCHAR(20),
					in country 		VARCHAR(20)
					)
BEGIN
	declare where_cond 	 text;
	DECLARE where_cat 	 TEXT;
	DECLARE where_outlet TEXT;	
	
	DECLARE joining 	 TEXT;	
	-- DECLARE outletjoin 	 TEXT;
	-- DECLARE cntryjoin 	 TEXT;
	-- DECLARE catjoin 		 TEXT;
	
	
	if fillby = 1 then
		SET where_cond 	=  'AND route.regionmstcode =';
		set joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode';
	elseif	fillby = 2 THEN
		SET where_cond 	=  'AND depot.depotcode =';
		set joining 	=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
							LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
							LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
	ELSEIF	fillby = 3 THEN
		SET where_cond 	=  'AND armst.areacode =';
		set joining		=  'LEFT JOIN routemaster AS route ON route.routecode = cust.routecode
							LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
							LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
	ELSEIF	fillby = 4 THEN
		SET where_cond 	=  'AND cust.routecode =';
		SET joining		=  '';
	else
		SET where_cond 	=  '';
		SET joining 	=  '';
		SET fillby 		=  '';
	end if;
	
	IF val = 0 THEN
		SET where_cond 	=	'';
		SET val 		= 	'';
	END IF;
	
	if cust_cat !='0' then
		set where_cat = 'AND cust.customercategory = ';
		-- set catjoin = 'LEFT JOIN categorymaster AS cat ON cat.categoryid = cust.customercategory';
	else
		SET where_cat = ' AND 1=1 ';
		set cust_cat = '';
	end if;
		
	if outletprod !='0' then		
		set where_outlet = 'AND cust.outletsubtype = ';
	else
		SET where_outlet = ' AND 3=3 ';
		set outletprod = '';
	end if;
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN	
		-- Below Query for select customer
		set @q1 = concat( "SELECT cust.customercode AS id, CONCAT(cust.alternatecode,' -- ',cust.customername) AS val FROM customermaster as cust
							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 AND templateindicator = 0"); 
	
		-- Below Query for selected customer	
		SET @q2 = CONCAT( 	"SELECT cust.customercode AS id, CONCAT(cust.alternatecode,' -- ',cust.customername) AS val FROM customermaster  as cust
							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 ",where_outlet," ",outletprod," AND templateindicator = 0");
	else	
			-- Below Query for select customer
		SET @q1 = CONCAT( "SELECT cust.customercode AS id, CONCAT(cust.customercode,' -- ',cust.customername) AS val FROM customermaster as cust
							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 AND templateindicator = 0"); 
	
		-- Below Query for selected customer	
		SET @q2 = CONCAT( 	"SELECT cust.customercode AS id, CONCAT(cust.customercode,' -- ',cust.customername) AS val FROM customermaster  as cust
							",joining," WHERE 9=9 ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 ",where_outlet," ",outletprod," AND templateindicator = 0");	
	end if;
	
	PREPARE s1 FROM @q1;
	EXECUTE s1;
	-- select @q1;
	
	PREPARE s2 FROM @q2;
	EXECUTE s2;
	-- select @q2;
	
	-- Below Query for selected customer id	
	SET @q3 = CONCAT( 	"SELECT cust.customercode FROM customermaster as cust
						",joining," WHERE 9=9 ",payterm," ",where_cond," ",val," ",where_cat," ",cust_cat," and activecustomer = 1 ",where_outlet," ",outletprod," AND templateindicator = 0");
	PREPARE s3 FROM @q3;
	EXECUTE s3;
	-- select @q3;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_customer_from_planogramkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_customer_from_planogramkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_customer_from_planogramkey`(
					IN catid BIGINT,
					IN routeid BIGINT
					)
BEGIN
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF routeid > 0 THEN 
	
		IF @st = 1 THEN  
			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster 
				WHERE routecode = routeid AND activecustomer = 1 AND templateindicator = 0; 
			
			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster 
				WHERE routecode = routeid AND visualcode = catid AND activecustomer = 1 AND templateindicator = 0; 
		ELSE
		
			
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster 
				WHERE routecode = routeid AND activecustomer = 1 AND templateindicator = 0; 
			
			
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster 
				WHERE routecode = routeid AND visualcode = catid AND activecustomer = 1 AND templateindicator = 0;
		END IF;
			
		
		SELECT customercode FROM customermaster 
			WHERE routecode = routeid AND visualcode = catid AND activecustomer = 1 AND templateindicator = 0; 
	ELSE
	
		IF @st = 1 THEN	
			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster 
				WHERE activecustomer = 1 AND templateindicator = 0; 
			
			
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster 
				WHERE visualcode = catid AND activecustomer = 1 AND templateindicator = 0;
		ELSE
			
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster 
				WHERE activecustomer = 1 AND templateindicator = 0; 
			
			
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster 
				WHERE visualcode = catid AND activecustomer = 1 AND templateindicator = 0;
		END IF;
			
		
		SELECT customercode FROM customermaster 
			WHERE itemmapkey = catid AND activecustomer = 1 AND templateindicator = 0; 	
	
	END IF;
	
END */$$
DELIMITER ;

