							INNER JOIN customermaster as cm ON cm.customercode = dh.customercode 
					 WHERE invoiced IS NULL  and canceled=0 ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	 -- select @dyn_sql;
   PREPARE s2 FROM @dyn_sql;	
	 EXECUTE s2;	
	
END */$$
