/* Procedure structure for procedure `sp_get_hhctransaction_cloudtran_addprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_cloudtran_addprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_cloudtran_addprocessload`()
BEGIN
	SELECT routecode AS id, CONCAT(routecode,' -- ',routename) AS val FROM routemaster 
	WHERE 
		activestatus = '1' 
		AND routetmpl = 0 
		AND   
		routecode IN (
				SELECT startendday.routecode FROM startendday WHERE
					--- DATE(startendday.routestartdate) = CURRENT_DATE() AND
					startendday.routeclosed =0
					AND startendday.triptype = 1
					GROUP BY startendday.routecode
			     );
    
    
END */$$
DELIMITER ;

