/* Procedure structure for procedure `sp_get_hhctransaction_loadtransfer_viewdamageret` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_loadtransfer_viewdamageret` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_loadtransfer_viewdamageret`(
	IN tran_key BIGINT(28)
    )
BEGIN
		SELECT
			 DATE_FORMAT(ih.transactiondate,'%d-%m-%Y') AS transactiondate,
			 DATE_FORMAT(sd.routestartdate,'%d-%m-%Y') AS routestartdate,
			 ih.transactiontime,
			 ih.documentnumber,
			 IF(ih.voidflag = 1, 'Valid','Not Valid') AS voidflag,
			 IF(routeclosed = 1, 'Closed','Live') AS accperiod,			 
			 ih.routecode AS routecode,
			 sm.salesmanname1 AS salesmanname1,
			 cm.customername
			FROM invoiceheader AS ih
			LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
			LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
			LEFT JOIN startendday AS sd ON sd.routecode = ih.routecode
			WHERE ih.transactionkey = tran_key group by ih.transactionkey;
		-- Route Master Combo
		CALL sp_combo_routemaster();	
    END */$$
DELIMITER ;

