		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'id.*';
		END IF;
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM invoiceheader AS ih
								LEFT JOIN invoicedetail AS id ON id.transactionkey = ih.transactionkey
								LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
								WHERE 1=1  ",table_where);
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoiceheader AS ih
								LEFT JOIN invoicedetail AS id ON id.transactionkey = ih.transactionkey
								LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode								
							  WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," 
							  LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
		
		
		SELECT @cnt_sql,@dyn_sql;
		
    END */$$
