/* Procedure structure for procedure `sp_get_hhctransaction_summary_customerinventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_summary_customerinventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_summary_customerinventory`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'coc.primary_id';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'coc.*';
	END IF;
	SET @cnt_sql = CONCAT("
		SELECT COUNT(coc.customercode) AS counter 
		FROM customeroperationscontrol coc
			LEFT OUTER JOIN (SELECT routekey, visitkey, COUNT(*) invcount FROM customerinventorydetail GROUP BY routekey, visitkey) cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey 
		WHERE COALESCE(cid.invcount,0) > 0  ",table_where);
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("
		SELECT ", table_fields ," 
		FROM customeroperationscontrol coc
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
			INNER JOIN routemaster rm ON rm.routecode = coc.routecode
			LEFT OUTER JOIN (SELECT routekey, visitkey, COUNT(*) invcount FROM customerinventorydetail GROUP BY routekey, visitkey) cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey 
		WHERE COALESCE(cid.invcount,0) > 0 ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");	
	PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
	select @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhctransaction_summary_inventorysummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_summary_inventorysummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_summary_inventorysummary`(
