							LEFT JOIN customerinventorydetail cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey 
							LEFT JOIN itemmaster im ON im.actualitemcode = cid.itemcode 
							where 1 =1   ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
