/* Procedure structure for procedure `sp_get_hhctransaction_summary_viewinventorysummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_summary_viewinventorysummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_summary_viewinventorysummary`(
		IN var_routekey BIGINT(18)
	)
BEGIN
	SELECT sed.routekey,sed.routecode, rm.routename, sm.salesmanname1, DATE_FORMAT(sed.routestartdate,"%d-%m-%Y") as routestartdate,DATE_FORMAT(sed.routeenddate,"%d-%m-%Y") as routeenddate, 
	IF(sed.routeclosed = 0,'No','Yes') AS routeclosed
	FROM startendday sed
	LEFT JOIN routemaster rm ON rm.routecode = sed.routecode
	left join salesman as sm on sm.salesmancode = sed.salesmancode
	WHERE sed.routekey = var_routekey;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhctransaction_summary_viewinventorysummarygrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_summary_viewinventorysummarygrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_summary_viewinventorysummarygrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	SET order_by = 'sed.routekey, im.alternatecode';
	
	SET order_type= 'ASC';
	
	IF table_fields = '' THEN
		SET table_fields = 'sed.*';
	END IF;
	SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM startendday sed,routemaster rm,salesman sm,
							inventorysummarydetail isd,itemmaster im, itemgroup ig,submajorcategory smc,
							majorcategory mc
							WHERE sed.routekey = isd.routekey AND sed.routecode = rm.routecode AND
                            sed.salesmancode = sm.salesmancode AND im.actualitemcode = isd.itemcode AND
                            ig.itemgroupcode = im.itemgroupcode AND smc.submajorcategorycode = ig.submajorcategorycode AND
                            mc.majorcategorycode = smc.majorcategorycode ",table_where);
	
	PREPARE s1 FROM @cnt_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("
		SELECT ", table_fields ," 
		FROM startendday sed, routemaster rm, salesman sm, inventorysummarydetail isd,itemmaster im, itemgroup ig,submajorcategory smc, majorcategory mc
		WHERE sed.routekey = isd.routekey AND sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode AND im.actualitemcode = isd.itemcode AND
				ig.itemgroupcode = im.itemgroupcode AND smc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = smc.majorcategorycode ",
		table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		
 	PREPARE s2 FROM @dyn_sql;	
 	EXECUTE s2;
 	
 	SELECT @dyn_sql;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_hhctransaction_transaction_checkprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhctransaction_transaction_checkprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhctransaction_transaction_checkprocessload`(IN routeid bigINT)
BEGIN
	SELECT routekey INTO @in_route_key_code FROM startendday 
	WHERE startendday.routecode=routeid
		AND startendday.routeclosed = 0
	ORDER BY routekey DESC  LIMIT 1	;
	
	
	select count(*) as counter from inventorytransactionheader where routecode = routeid 
	 and routekey = @in_route_key_code;
	-- and transactiondate = CURRENT_DATE();
	
END */$$
DELIMITER ;

