/* Procedure structure for procedure `sp_get_hhc_index_invoiceitem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_hhc_index_invoiceitem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_hhc_index_invoiceitem`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'actualitemcode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'im.*';
	END IF;
	IF rwcnt = 1 THEN
		SET @dyn_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM itemmaster AS im 
		WHERE 1=1  ",table_where);
	ELSE
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM itemmaster AS im 
		 WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
