	PREPARE s1 FROM @dyn_sql;
	-- select @dyn_sql;
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_dailysalesmanload_qtyinfo_ordertoload`(
in table_name varchar(50),
IN tran_date DATE,
IN var_routecode BIGINT
)
BEGIN
  
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,sum(salesqty) FROM salesorderdetail AS sod
		LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
		WHERE DATE(soh.orderdeliverydate) = tran_date and routecode = var_routecode
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  
  set @qtmp = concat("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
  prepare s1 from @qtmp;
  EXECUTE s1;
  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;		
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		SELECT COUNT(itemcode) INTO main_cnt FROM salesorderdetail AS sod
			LEFT JOIN salesorderheader AS soh ON soh.transactionkey = sod.transactionkey
			WHERE DATE(soh.orderdeliverydate) = tran_date AND routecode = var_routecode
			GROUP BY itemcode ORDER BY itemcode;
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_dailysalesmanload_qtyinfo_previousday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_dailysalesmanload_qtyinfo_previousday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_dailysalesmanload_qtyinfo_previousday`(
IN table_name VARCHAR(50),
IN exp_date DATE,
IN var_routecode BIGINT,
IN var_load INT(4)
)
BEGIN
  
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,SUM((cases*upc)+units) AS quantity  FROM startingloaddetail AS sld
		WHERE DATE(ddate) = exp_date AND routecode = var_routecode AND loadperiodnumber = var_load
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  
  SET @qtmp = CONCAT("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
  PREPARE s1 FROM @qtmp;
  EXECUTE s1;
  
  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		
		SELECT COUNT(itemcode) INTO main_cnt FROM startingloaddetail AS sld
		WHERE DATE(ddate) = exp_date AND routecode = var_routecode AND loadperiodnumber = var_load
		-- GROUP BY itemcode 
		ORDER BY itemcode;
		
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
								-- ORDER BY expirydate
								-- select @q;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
								-- ORDER BY expirydate
							 END IF;							 
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								-- select @q1;
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_dailysalesmanload_qtyinfo_requesttoload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_dailysalesmanload_qtyinfo_requesttoload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_dailysalesmanload_qtyinfo_requesttoload`(
in table_name varchar(50),
IN tran_date DATE,
IN var_routecode BIGINT
)
BEGIN
  
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
	DECLARE cur1 CURSOR FOR SELECT itemcode,sum(quantity) as quantity FROM inventorytransactiondetail AS itd
		LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
		where itd.transactiontypecode = 8 AND DATE(ith.transactiondate) = tran_date
		and routecode = var_routecode group by itemcode order by itemcode;
  
		DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
		DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo;   
		set @qtmp = concat("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
		prepare s1 from @qtmp;
		EXECUTE s1;
		
	OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;
		 SELECT COUNT(itemcode) INTO main_cnt FROM inventorytransactiondetail AS itd
			LEFT JOIN inventorytransactionheader AS ith ON ith.detailkey = itd.detailkey
			WHERE itd.transactiontypecode = 8 AND DATE(ith.transactiondate) = tran_date
				AND routecode = var_routecode and itemcode = var_main_itemcode GROUP BY itemcode;
			set from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					if table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					end if;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						while inner_start < @innercnt do
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							set limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_dailysalesmanload_qtyinfo_suggestedsales` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_dailysalesmanload_qtyinfo_suggestedsales` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_dailysalesmanload_qtyinfo_suggestedsales`(
in table_name varchar(50),
in tran_date date,
in var_routecode bigint
)
BEGIN
  
	DECLARE var_main_itemcode,var_reqquantity,last_itemcode DECIMAL(18,0);
	DECLARE counter INT DEFAULT 1;
	DECLARE no_more_rows BOOLEAN;
	DECLARE from_start,inner_start,limit_start,num_rows,main_cnt INT DEFAULT 0;
  
  DECLARE cur1 CURSOR FOR SELECT itemcode,sum(currentvisitsales) FROM suggestedsalesinvoice AS ssi		
		where DATE(ssi.transactiondate) = tran_date and routecode = var_routecode
		GROUP BY itemcode ORDER BY itemcode;  
  
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;  
  DROP TEMPORARY TABLE IF EXISTS tmp_quantityinfo; 
  
  set @qtmp = concat("CREATE TEMPORARY TABLE tmp_quantityinfo (SELECT * FROM ",table_name," WHERE 1 = 2)");
  prepare s1 from @qtmp;
  EXECUTE s1;
  OPEN cur1;
		SELECT FOUND_ROWS() INTO num_rows;
		main_loop: LOOP	
		IF no_more_rows THEN
			CLOSE cur1;
			LEAVE main_loop;
			IF counter > num_rows THEN
				CLOSE cur1;
				LEAVE main_loop;
			END IF;
		END IF;		
  
		FETCH cur1 INTO var_main_itemcode,var_reqquantity;		
		
		SELECT count(itemcode) into main_cnt FROM suggestedsalesinvoice AS ssi		
			WHERE DATE(ssi.transactiondate) = tran_date AND routecode = var_routecode
			GROUP BY itemcode ORDER BY itemcode;
		
			SET from_start 	= 0;
			WHILE from_start < main_cnt DO
				SET inner_start = 0;
				SET limit_start	= 0;
 				 IF var_reqquantity > 0 THEN
					IF table_name = 'depotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE quantity > 0 AND itemcode = ",var_main_itemcode);
					ELSEIF table_name = 'tbldepotstock' THEN
						SET @qtmp = CONCAT("SELECT COUNT(*) INTO @innercnt FROM ",table_name," WHERE avlquantity > 0 AND itemcode = ",var_main_itemcode);
					END IF;
					PREPARE s1 FROM @qtmp;
					EXECUTE s1;
					
					IF last_itemcode <> var_main_itemcode THEN
						WHILE inner_start < @innercnt DO
							IF table_name = 'depotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM depotstock
								WHERE itemcode = ",var_main_itemcode," AND quantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 ELSEIF table_name = 'tbldepotstock' THEN
								SET @q = CONCAT("SELECT depotinventorykey,itemcode,avlquantity,depotcode,batchno,expirydate
									into @var_depotinventorykey,@var_itemcode,@var_quantity,@var_depotcode,@var_batchno,@var_expirydate
								FROM tbldepotstock
								WHERE itemcode = ",var_main_itemcode," AND avlquantity > 0 ORDER BY expirydate
								limit ",limit_start,",1");
								PREPARE s1 FROM @q;
								EXECUTE s1;
							 END IF;
							IF @var_quantity < var_reqquantity  AND @var_quantity > 0 THEN
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",@var_quantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = var_reqquantity - @var_quantity;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							ELSEIF @var_quantity > var_reqquantity  AND @var_quantity > 0 THEN					
								SET @q1 = CONCAT("insert into tmp_quantityinfo (depotinventorykey,itemcode,quantity,depotcode,batchno,expirydate)
									values(",@var_depotinventorykey,",",@var_itemcode,",",var_reqquantity,",",@var_depotcode,",'",@var_batchno,"','",@var_expirydate,"')");
								SET var_reqquantity = 0;
								
								PREPARE s2 FROM @q1;
								EXECUTE s2;
								
							END IF;
							SET inner_start 	= inner_start  + 1;
							SET limit_start 	= limit_start  + 1;
							
							IF var_reqquantity 	= 0 THEN
								SET inner_start = @innercnt;
							END IF;
						END WHILE;
					END IF;
					SET last_itemcode = var_main_itemcode;
	 			END IF;
				
				SET from_start 		= from_start  + 1;
				IF var_reqquantity 	= 0 THEN
					SET from_start 	= main_cnt;
				END IF;
			END WHILE;		
		SET counter = counter+1;
		END LOOP main_loop;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_index_addcompanygroup` */

