/* Procedure structure for procedure `sp_get_inventory_index_additem` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_index_additem` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_index_additem`(
	IN itemcode INT
    )
BEGIN
	DECLARE places INT(4);
	IF itemcode > 0 THEN 
		SELECT get_decimalplaces_value() INTO places;
		SET @q = CONCAT("SELECT 	actualitemcode,
									anitemcode,
									itemgroupcode,
									alternatecode,
									itemshortdescription,
									warehousestock,
									itemdescription,
									itemgrpcode,
									unitspercase,
									dataentry ,
									liter ,
									literperunit,
									FORMAT(caseprice,",places,") AS caseprice,
									FORMAT(defaultsalesprice,",places,") AS defaultsalesprice,
									FORMAT(defaultgoodreturncaseprice,",places,") AS defaultgoodreturncaseprice,
									FORMAT(defaultgoodreturnprice,",places,") AS defaultgoodreturnprice,
									FORMAT(returncaseprice,",places,") AS returncaseprice,
									FORMAT(defaultreturnprice,",places,") AS defaultreturnprice,
									caseuom,
									activeitem,
									captureshelfstock,
									tcallowed,
									allowinvoicepricechange,
									arbitemdescription,
									arbitemshortdescription,
									FORMAT(defaultcostprice,",places,") as defaultcostprice,
									FORMAT(costcaseprice,",places,") as costcaseprice,
									offtakeparameter,
									barcode1,
									barcode2,
									barcode3,
									barcode4,
									barcode5,
									barcode6,
									barcode7,
									barcode8,
									barcode9,
									barcode10,
									created,
									modified,
									cdat,
									mdat
								FROM itemmaster
								WHERE actualitemcode = ",itemcode);
				PREPARE s1 FROM @q;
				EXECUTE s1;		
	ELSE
		CALL sp_get_table_last_id('itemmaster');
	
	END IF;
	
	CALL sp_combo_itemgroup();
	
	CALL sp_get_inventory_index_itemset1(itemcode);
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_index_additemgrp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_index_additemgrp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_index_additemgrp`(
	IN Groupcode INT
    )
BEGIN
	
	IF Groupcode > 0 THEN 
		SELECT item.itemgroupcode, item.submajorcategorycode, item.itemgroupname, item.arbitemgroup,
			sub.description,item.alternateitemgroupcode, item.activestatus,DATE_FORMAT(item.cdat,'%d-%m-%Y') AS cdat
			FROM itemgroup AS item
		LEFT JOIN submajorcategory AS sub ON sub.submajorcategorycode = item.submajorcategorycode WHERE item.itemgroupcode = Groupcode;
	ELSE	
		CALL sp_get_table_last_id('itemgroup');		
	END IF;
	-- Submajor Category Combo
	call sp_combo_submajorcategory();
		
    END */$$
DELIMITER ;

