/* Procedure structure for procedure `sp_get_inventory_target_addsalesmantarget` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_target_addsalesmantarget` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_target_addsalesmantarget`(
			IN var_pk BIGINT
    )
BEGIN
	IF var_pk > 0 THEN
		SELECT rg.*,route.routename,route.salesmantargetdays FROM routegoal AS rg
		LEFT JOIN routemaster AS route ON route.routecode = rg.routecode
		WHERE primary_key = var_pk;
	ELSE
		-- call sp_get_table_last_id('routegoal');
		SELECT 1;
	END IF;
	CALL sp_combo_itempackage();
	CALL sp_get_salesman('TARGET','');
	
	SELECT * FROM quotamain;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_target_addsalesmantargetgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_target_addsalesmantargetgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_target_addsalesmantargetgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;	
	
	IF table_fields = '' THEN
		SET table_fields = 'rg.*';
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM routegoal AS rg 
	left join itempackagemaster as ipm on ipm.packagecode = rg.packagenumber
	WHERE 1=1  ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,",
		CASE when rg.targettype = 1 then 'Sales Quantity' when rg.targettype = 2 then 'Sales Value' 
			when rg.targettype = 3 then 'Collection' 
			when rg.targettype = 4 then 'Total Visits' when rg.targettype = 5 then 'Total Selling Calls' 
			when rg.targettype = 6 then 'Damage Against Sales' else 
			'MSL' end targettype,
			CASE WHEN rg.packagenumber = 1 THEN 'No Group' ELSE packagedescription END packagedescription
	 FROM routegoal AS rg 
	left join itempackagemaster as ipm on ipm.packagecode = rg.packagenumber	
	WHERE 1=1  ",table_where, " ORDER BY rg.fromdate desc, rg.targettype LIMIT ",lmt_strt,", ",lmt_end,"");
	
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	-- select @dyn_sql;
	-- WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ",  
	-- WHERE 1=1  ",table_where,  " ORDER BY FIELD(",order_by,",",get_month_order(),") ",
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_target_commission_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_target_commission_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_target_commission_report`(
	IN in_limit INT,
	IN in_page INT,
	IN var_tdate VARCHAR(50)
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SELECT COUNT(*) INTO @in_counter
	FROM routegoal AS rg 
				 INNER JOIN routemaster rm ON rm.routecode = rg.routecode
				 INNER JOIN salesman sm ON sm.salesmancode = rg.salesmancode
				 LEFT JOIN itempackagemaster AS ipm ON ipm.packagecode = rg.packagenumber
				WHERE var_tdate BETWEEN rg.fromdate AND rg.todate;
	
	IF in_limit != "" && in_page != "" THEN 
	CALL sp_report_calculate_paging_data (@in_counter, in_limit, in_page, @new_start_limit);
	SELECT @new_start_limit AS start_limit, @in_counter AS counter;
		
	SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT 
				 rm.routecode, rm.routename, sm.alternatesalesmancode salesmancode, sm.salesmanname1,
				 DATE_FORMAT(rg.fromdate,'%d-%m-%Y') as fromdate,DATE_FORMAT(rg.todate,'%d-%m-%Y') as todate,
				 rg.quantity,rg.commision,rg.insentivepercent,rg.insentive,rg.achieveamount,
				 CASE 
					WHEN rg.targettype = 1 THEN 'Sales Quantity' 
					WHEN rg.targettype = 2 THEN 'Sales Value' 
					WHEN rg.targettype = 3 THEN 'Collection ' 
					WHEN rg.targettype = 4 THEN 'Total Calls' 
					WHEN rg.targettype = 5 THEN 'Total Selling Calls' 
					WHEN rg.targettype = 6 THEN 'D & E'
					WHEN rg.targettype = 7 THEN 'MSL' 
					ELSE '***' END targettype,
				 CASE WHEN rg.packagenumber = 1 THEN 'CUSTOMER' ELSE packagedescription END packagedescription,
				
				CASE WHEN
					rg.quantity = 0 THEN 0 
				ELSE
					CASE 
						WHEN rg.targettype = 3 THEN CASE WHEN rg.quantity > 0 THEN 0 ELSE rg.commision END	
						WHEN rg.targettype = 6 THEN CASE WHEN rg.quantity < rg.achieveamount THEN 0 ELSE rg.commision END	
					ELSE
						CASE WHEN rg.quantity > rg.achieveamount THEN 0 ELSE rg.commision END				
					END
				END targetstatus				 
				 
				 FROM routegoal AS rg 
				 INNER JOIN routemaster rm ON rm.routecode = rg.routecode
				 INNER JOIN salesman sm ON sm.salesmancode = rg.salesmancode
				 LEFT JOIN itempackagemaster AS ipm ON ipm.packagecode = rg.packagenumber
				WHERE '", var_tdate ,"' BETWEEN rg.fromdate AND rg.todate
				ORDER BY rg.routecode, rg.fromdate, rg.targettype", limit_val);
	
	-- select @dyn_sql;
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;
	
END */$$
DELIMITER ;

