/* Procedure structure for procedure `sp_get_inventory_transaction_adddailysalesmanload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_adddailysalesmanload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_adddailysalesmanload`(
	IN loadcode INT
    )
BEGIN
	
	DECLARE loadnumber INT;
				
		CALL sp_combo_itemmaster();
		CALL sp_combo_routemaster();
		CALL sp_combo_salesman();
		
		SELECT actualitemcode,unitspercase,defaultsalesprice,caseprice,defaultreturnprice FROM itemmaster;
		SELECT `status` FROM controlpanel WHERE flagid = 1;
		
		IF loadcode > 0 THEN 
		
			SELECT DATE_FORMAT(ld.ddate,'%d/%m/%Y') AS ddate,ld.salesmancode,ld.loadperiodnumber,
			ld.routecode,slman.salesmanname1,ld.erpreferencenumber ,ld.status AS load_status, ld.loadtime
			FROM startingloaddetail AS ld
			LEFT JOIN salesman AS slman ON slman.salesmancode = ld.salesmancode
			WHERE ld.loaddetailcode = loadcode;
			
			SELECT loadperiodnumber INTO loadnumber FROM startingloaddetail WHERE loaddetailcode = loadcode;
			
			SELECT replace(im.itemdescription,'"','') itemdescription,ld.* FROM startingloaddetail AS ld
			LEFT JOIN itemmaster AS im ON im.actualitemcode = ld.itemcode
			WHERE ld.loadperiodnumber= loadnumber and ddate=DATE_FORMAT(NOW(), "%Y-%m-%d");
			
		END IF;
		
		-- SELECT flagid,getstartingloadmethod(flagid) AS flagname FROM controlpanel WHERE flagid IN(72,60,47,34,54,15) AND `status` = 1;
		SELECT flagid,getstartingloadmethod(`status`) AS flagname,`status` FROM controlpanel WHERE flagid IN(60) ;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_adddeliveryload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_adddeliveryload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_adddeliveryload`(
	IN loadcode INT
    )
BEGIN
	
	DECLARE loadnumber INT;
				
		CALL sp_combo_itemmaster();
		CALL sp_combo_routemaster();
		CALL sp_combo_salesman();
		
		SELECT actualitemcode,unitspercase,defaultsalesprice,caseprice,defaultreturnprice FROM itemmaster;
		SELECT `status` FROM controlpanel WHERE flagid = 1;
		
		IF loadcode > 0 THEN 
		
		
		
			SELECT DATE_FORMAT(ld.deliverydate,'%d/%m/%Y') AS ddate,ld.drivercode,ld.deliveryno,ld.orderno,ld.referenceno,ld.customercode,
			ld.deliveryroute,slman.salesmanname1,ld.delivered AS load_status
			FROM deliveryheader AS ld
			LEFT JOIN salesman AS slman ON slman.salesmancode = ld.drivercode
			WHERE ld.deliveryno = loadcode;
			
			SELECT deliveryno INTO loadnumber FROM deliveryheader WHERE deliveryno = loadcode;
			
			-- SELECT im.itemdescription,ld.* FROM startingloaddetail AS ld
			-- LEFT JOIN itemmaster AS im ON im.actualitemcode = ld.itemcode
			-- WHERE ld.loadperiodnumber= loadnumber;
			
		END IF;
		
		-- SELECT flagid,getstartingloadmethod(flagid) AS flagname FROM controlpanel WHERE flagid IN(72,60,47,34,54,15) AND `status` = 1;
		SELECT flagid,getstartingloadmethod(`status`) AS flagname,`status` FROM controlpanel WHERE flagid IN(60) ;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_adddepotdamageexpiry` */

