DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_adddepotdamageexpiry`(
	IN header_id bigINT
    )
BEGIN			
		CALL sp_combo_itemmaster();
		call sp_combo_depotmaster();	
					
		IF header_id > 0 THEN
			select headerid,referenceno,DATE_FORMAT(fromdate,"%d-%m-%Y") AS fromdate,DATE_FORMAT(todate,"%d-%m-%Y") AS todate,
					depotcode,DATE_FORMAT(transactiondate,"%d-%m-%Y") AS transactiondate
			from depotdamageexpiryheader where headerid = header_id;
		else
			call sp_get_table_last_id('depotdamageexpiryheader');
		END IF;
		
    END */$$
DELIMITER ;

