/* Procedure structure for procedure `sp_get_inventory_transaction_openingbalance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_openingbalance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_openingbalance`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'transactionkey';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'ci.*';
		END IF;
		
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM customerinvoice AS ci
			  LEFT JOIN routemaster AS rm ON rm.routecode = ci.routecode
			  LEFT JOIN salesman AS sm ON sm.salesmancode = ci.salesmancode
			  LEFT JOIN customermaster AS cm ON cm.customercode = ci.customercode
			WHERE ci.transactiontype = 1 ",table_where);
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customerinvoice AS ci
			  LEFT JOIN routemaster AS rm ON rm.routecode = ci.routecode
			  LEFT JOIN salesman AS sm ON sm.salesmancode = ci.salesmancode
			  LEFT JOIN customermaster AS cm ON cm.customercode = ci.customercode
			 WHERE ci.transactiontype = 1  ",table_where,  " ORDER BY ",order_by," ",
			order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_inventory_transaction_routeitemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_inventory_transaction_routeitemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_inventory_transaction_routeitemgroup`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'routeitemgrpcode';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		SET order_type= 'ASC';
		
		IF table_fields = '' THEN
			SET table_fields = 'route.*';
		END IF;
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter
			FROM routeitemgrp AS route
			WHERE 1=1  ",table_where);
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM routeitemgrp AS route			 
			 WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ",
			order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;
    END */$$
DELIMITER ;

