/* Procedure structure for procedure `sp_get_iteminfo_depotcode_itemcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_iteminfo_depotcode_itemcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_iteminfo_depotcode_itemcode`( 
in depotid bigint(18),
IN itemid BIGINT(18),
in primary_id bigint(18))
BEGIN
	
	if primary_id > 0 then 
		SELECT expirydate
		FROM depotstock
		WHERE depotinventorykey = primary_id;
	else
		SELECT depotinventorykey AS id,batchno AS val 
		FROM depotstock
		WHERE itemcode = itemid AND depotcode = depotid;
		
		call sp_get_iteminfo_itemcode(itemid);
		
	end if;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_iteminfo_itemcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_iteminfo_itemcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_iteminfo_itemcode`( in itemid bigint(18))
BEGIN
	
	SELECT
	  actualitemcode,
	  unitspercase,
	  defaultsalesprice,
	  caseprice,
	  defaultreturnprice,
	  allowbatchentry,
	  defaultgoodreturnprice,
	  defaultgoodreturncaseprice
	FROM itemmaster 
	WHERE actualitemcode = itemid;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_itemqtyinfo_itemcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_itemqtyinfo_itemcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_itemqtyinfo_itemcode`( 
	IN depotid BIGINT(18),
	in itemid bigint(18)
	)
BEGIN
	
	SELECT actualitemcode,unitspercase,allowbatchentry FROM itemmaster WHERE actualitemcode = itemid;
		
	select 	IFNULL(FLOOR(tds.avlquantity/im.unitspercase),0) as availablecases,
			IFNULL((tds.avlquantity%im.unitspercase),0) as availablepieces,
			IFNULL(FLOOR(tds.hldquantity/im.unitspercase),0) as holdcases,
			IFNULL((tds.hldquantity%im.unitspercase),0) AS holdpieces
	from 	tbldepotstock AS tds,itemmaster AS im 
	WHERE tds.itemcode = im.actualitemcode AND depotcode = depotid AND itemcode = itemid;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_items_itemgroupcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_items_itemgroupcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_items_itemgroupcode`(
					IN itemgrpcode  BIGINT,
					in routegrpcode bigint
				)
BEGIN
	
	declare where_cond text;
	if itemgrpcode = 0 then
		set itemgrpcode = '';
		set where_cond  = '';
	else
		SET where_cond  = CONCAT(' AND im.itemgroupcode = ',itemgrpcode);
	end if;
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	IF @st = 1 THEN
	
		set @q1 = concat("SELECT actualitemcode AS id,CONCAT(im.alternatecode,' - ',im.itemshortdescription) AS val FROM itemmaster AS im
			WHERE 1=1 ",where_cond," and activeitem = 1
			ORDER BY 2");
		prepare s1 from @q1;
		execute s1;
		
		if routegrpcode > 0 then
			SELECT actualitemcode AS id,CONCAT(im.alternatecode,' - ',im.itemshortdescription) AS val FROM itemmaster AS im
				left join routeitemmapping as rim on rim.itemcode = im.actualitemcode
				WHERE rim.routeitemgrpcode = routegrpcode AND activeitem = 1
				ORDER BY 2;		
		end if;
		
	else		
		SET @q1 = CONCAT("SELECT actualitemcode AS id,CONCAT(im.actualitemcode,' - ',im.itemshortdescription) AS val FROM itemmaster AS im
			WHERE 1=1 ",where_cond," and activeitem = 1");
		PREPARE s1 FROM @q1;
		EXECUTE s1;
		
		IF routegrpcode > 0 THEN
			SELECT actualitemcode AS id,CONCAT(im.actualitemcode,' - ',im.itemshortdescription) AS val FROM itemmaster AS im
				LEFT JOIN routeitemmapping AS rim ON rim.itemcode = im.actualitemcode
				WHERE rim.routeitemgrpcode = routegrpcode and activeitem = 1;
		end if;
	end if;
	
	IF routegrpcode > 0 THEN
		SELECT actualitemcode AS id FROM itemmaster AS im
				LEFT JOIN routeitemmapping AS rim ON rim.itemcode = im.actualitemcode
				WHERE rim.routeitemgrpcode = routegrpcode AND activeitem = 1;
	end if;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_items_routeitemgroupcode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_items_routeitemgroupcode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_items_routeitemgroupcode`(
					IN routeid BIGINT
					)
BEGIN
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN			
		SELECT itemcode AS id, CONCAT(im.alternatecode,' - ',im.itemdescription) AS val FROM itemmaster AS im
			LEFT JOIN routeitemmapping AS rim ON rim.itemcode = im.actualitemcode
			LEFT JOIN routemaster AS rm ON rm.routeitemgrpcode = rim.routeitemgrpcode
			WHERE rm.routecode = routeid order by im.alternatecode;
	else
		SELECT itemcode AS id,CONCAT(im.actualitemcode,' - ',im.itemdescription) AS val FROM itemmaster AS im
			LEFT JOIN routeitemmapping AS rim ON rim.itemcode = im.actualitemcode
			LEFT JOIN routemaster AS rm ON rm.routeitemgrpcode = rim.routeitemgrpcode
			WHERE rm.routecode = routeid;
	end if;
		
END */$$
DELIMITER ;

