/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_addsurveyplan`(IN id BIGINT)
BEGIN
	
	
	CALL sp_combo_surveydefinition();	
	
	if id > 0 then
	
