/* Procedure structure for procedure `sp_get_merchandize_index_customerimages` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_customerimages` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_customerimages`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT,
	in var_routecode bigint(28)
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'customercode';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'ci.*';
		END IF;
		
		if var_routecode = '' then
			set var_routecode = 0;
		end if;
				
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter from customeroperationscontrol AS ci
		LEFT JOIN customermaster AS c ON c.customercode = ci.customercode
		WHERE ci.customercode IN(SELECT DISTINCT customercode FROM routesequence WHERE routecode IN(",var_routecode,"))
		",table_where);
	 	PREPARE s1 FROM @cnt_sql;
	 	EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customeroperationscontrol AS ci
		LEFT JOIN customermaster AS c ON c.customercode = ci.customercode
		WHERE ci.customercode IN(SELECT DISTINCT customercode FROM routesequence WHERE routecode IN(",var_routecode,"))
		",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	 	PREPARE s2 FROM @dyn_sql;
	 	EXECUTE s2;
	 	
	 	
		CALL sp_combo_routemaster();
    END */$$
DELIMITER ;

