/* Procedure structure for procedure `sp_get_merchandize_index_lookupindexgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_lookupindexgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_lookupindexgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'look.*';
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter FROM lookupindexdetail AS look 
	WHERE 1=1 ",table_where);
	
	PREPARE s1 FROM @dyn_cnt;
	-- SELECT @dyn_sql;
	EXECUTE s1;
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM lookupindexdetail AS look 
	WHERE 1=1 ",table_where,  " ORDER BY ",order_by," ", 
	order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	PREPARE s2 FROM @dyn_sql;
	-- SELECT @dyn_sql;
	EXECUTE s2;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_merchandize_index_selectedsurveyplangrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_merchandize_index_selectedsurveyplangrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_merchandize_index_selectedsurveyplangrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT
    )
BEGIN
		IF lmt_strt = '' THEN
			SET lmt_strt=0;
		END IF;
		IF lmt_end = '' THEN
			SET lmt_end=10;
		END IF;
		IF order_by = '' THEN
			SET order_by = 'kplan.primary_key';
		END IF;
		IF order_type = '' THEN
			SET order_type= 'DESC';
		END IF;
		IF table_fields = '' THEN
			SET table_fields = 'plan.*';
		END IF;
		
		
		SET @cnt_sql = CONCAT("SELECT COUNT(*) AS counter FROM customersurveyplan AS plan
		LEFT JOIN customersurveykeyplan AS kplan ON kplan.surveyplankey = plan.surveyplankey
		WHERE 1=1  ",table_where);		
		PREPARE s1 FROM @cnt_sql;
		EXECUTE s1;
		
		SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM customersurveyplan AS plan
		LEFT JOIN customersurveykeyplan AS kplan ON kplan.surveyplankey = plan.surveyplankey
		WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
		PREPARE s2 FROM @dyn_sql;
		EXECUTE s2;		
    END */$$
DELIMITER ;

