/* Procedure structure for procedure `sp_get_notes_creditnotecustomer_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_notes_creditnotecustomer_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_notes_creditnotecustomer_report`(
	IN id 			BIGINT(20)
    )
BEGIN
		DECLARE paytype INT(4);
		
				
		IF id > 0 THEN 
			 SELECT transactiondate,documentnumber,rm.routename,cm.customername,sm.salesmanname1,amountpaid,paymenttype
				FROM dcarheader dh
				INNER JOIN routemaster rm ON rm.routecode= dh.routecode
				INNER JOIN customermaster cm ON cm.customercode = dh.customercode
				INNER JOIN salesman sm ON sm.salesmancode = dh.salesmancode WHERE transactionkey = id;
			SELECT invoicenumber,invoicedate,totalinvoiceamount,amountpaid,invoicebalance  FROM dcardetail WHERE transactionkey = id;
		END IF;
		
		IF id > 0 THEN 
			SELECT typecode INTO paytype FROM dcarcashcheckdetail WHERE transactionkey = id;
			
			IF paytype > 0 THEN
				SELECT typecode,checknumber,DATE_FORMAT(checkdate,'%d-%m-%Y') AS checkdate,SUM(amount) AS amount,bm.bankname 
					FROM dcarcashcheckdetail AS bcd,bankmaster AS bm 
				WHERE bm.bankcode = bcd.bankcode AND transactionkey = id
					GROUP BY transactionkey;
			ELSE
				SELECT typecode,SUM(amount) AS amount FROM dcarcashcheckdetail
					WHERE transactionkey = id
					GROUP BY transactionkey;
			END IF;
		END IF;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_not_assigned_devices` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_not_assigned_devices` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_not_assigned_devices`(IN var_device_id VARCHAR(100))
BEGIN
	SET @dyn_sql1 = CONCAT("SELECT dev.primary_key, dev.device_id, dev.remarks  
		FROM tbl_device dev
		WHERE dev.device_id NOT IN (SELECT DISTINCT device_assigned_id FROM routemaster WHERE COALESCE(device_assigned_id,'') != '')");
			
	IF var_device_id != '' THEN
	
		SET @dyn_sql1 = CONCAT("SELECT dev.primary_key, dev.device_id, dev.remarks  
			FROM tbl_device dev
			WHERE dev.device_id NOT IN (SELECT DISTINCT device_assigned_id FROM routemaster WHERE COALESCE(device_assigned_id,'') != '')
			UNION
			SELECT primary_key, device_id, remarks  
			FROM tbl_device 
			WHERE device_id = '", var_device_id, "'");
	
	END IF;
	
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_not_fcm_token_assigned_devices` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_not_fcm_token_assigned_devices` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_not_fcm_token_assigned_devices`(IN var_device_id VARCHAR(100))
BEGIN
	SET @dyn_sql1 = CONCAT("SELECT dev.primary_key, dev.device_id, dev.remarks  
		FROM tbl_device_token dev
		WHERE dev.device_id NOT IN (SELECT DISTINCT device_fcm_assigned_id FROM routemaster WHERE COALESCE(device_fcm_assigned_id,'') != '')");
			
	IF var_device_id != '' THEN
	
		SET @dyn_sql1 = CONCAT("SELECT dev.primary_key, dev.device_id, dev.remarks  
			FROM tbl_device_token dev
			WHERE dev.device_id NOT IN (SELECT DISTINCT device_fcm_assigned_id FROM routemaster WHERE COALESCE(device_fcm_assigned_id,'') != '')
			UNION
			SELECT primary_key, device_id, remarks  
			FROM tbl_device_token 
			WHERE device_id = '", var_device_id, "'");
	
	END IF;
	
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;
	
    END */$$
DELIMITER ;

