/* Procedure structure for procedure `sp_get_organization_route_addroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_addroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_addroute`(IN id BIGINT)
BEGIN
	#Get Data from Routemaster for particular record
	SELECT * FROM routemaster WHERE  `routecode` = id;
		
	-- For Region
	CALL sp_combo_regionmaster();
		
	-- For Sub Area
	CALL sp_combo_subareamaster();
	
	-- For Salesman
	CALL sp_get_salesman('ROUTE',id);
	
	-- For Company
	CALL sp_combo_company();
	-- For Van
	CALL sp_combo_vanmaster();
	-- For Route Category /Business Type
	CALL sp_combo_routecategory();
	-- For Item Group
	CALL sp_combo_routeitemgrp();
	
	-- For Route Template Combo Box
	SELECT routecode AS id,templatename AS val FROM routemaster WHERE routetmpl	= 1;
	
	-- For Currency Combo
	CALL sp_combo_currency();
	
	CALL sp_combo_customermaster();
	
	CALL sp_combo_itemmust();
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79);
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_organization_route_addroutetmpl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_addroutetmpl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_addroutetmpl`(IN id BIGINT)
BEGIN
	IF id > 0 THEN
		#Get Data from Routetemplate for particular record
		SELECT * FROM routemaster WHERE  routecode = id AND routetmpl	= 1;
	ELSE
		SELECT 1;	
	END IF;
	
	SELECT routecode AS id,routecode AS val FROM routemaster WHERE routetmpl	= 1;
	
	-- For Route Item Group
	CALL sp_combo_routeitemgrp();
	
	-- For Currency Combo
	CALL sp_combo_currency();
	
	-- For Route Category /Business Type
	CALL sp_combo_routecategory();
	
	CALL sp_combo_itemmust();
	
	SELECT `status` FROM controlpanel WHERE flagid IN (3,57,74,79);
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_organization_route_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_report`(IN id BIGINT)
BEGIN
	#Get Data from Routemaster for particular record
	SELECT 	routecode,
			reqeoddepositreport,
			reqeodsalesreport,
			reqeodrteactivreport,
			reqeodrtestlmtreport,
			reqeodroutereviewrpt,
			reqeodrtnexchreport,
			reqeodplacementsrpt,
			reqeodprcchgreport,
			reqeodpromosreport,
			reqeodnosalereport,
			reqeodnondelreport,
			reqeodexceptionrpt,
			reqeodunauthbalance,
			reqeodroasummary,
			reqeodnonscannedreport,
			reqeododomlogreport
			
	 FROM routemaster WHERE  `routecode` = id;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_organization_route_route` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_route` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_route`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'route.routecode';
	END IF;
	
	SET order_type = ' ASC ';
	
	-- IF order_type = '' THEN
	-- 	SET order_type= ' DESC ';
	-- END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'cnt.*';
	END IF;
    
	SET @count_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM routemaster AS route LEFT JOIN salesman ON route.salesmancode = salesman.salesmancode
		LEFT JOIN subareamaster AS subarea ON route.subareacode = subarea.subareacode
		WHERE 1=1 AND routetmpl = 0 ",table_where);
    PREPARE s1 FROM @count_sql;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM routemaster AS route LEFT JOIN salesman ON route.salesmancode = salesman.salesmancode
		LEFT JOIN subareamaster AS subarea ON route.subareacode = subarea.subareacode
		WHERE 1=1 AND routetmpl = 0 ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    -- SELECT @dyn_sql;
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_organization_route_routetmpl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_organization_route_routetmpl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_organization_route_routetmpl`(
		in id bigint)
BEGIN
	-- For Getting Route Template information.
	select * from routemaster where routecode =  id and routetmpl = 1;
	
	-- For Getting Last Increment ID
	call sp_get_table_last_id('routemaster');
	
	-- For Region
	CALL sp_combo_regionmaster();
		
	-- For Sub Area
	CALL sp_combo_subareamaster();
	
	-- For Salesman
	CALL sp_combo_salesman();
	
	-- For Company
	CALL sp_combo_company();
	-- For Van
	CALL sp_combo_vanmaster();
	-- For Business Type
	CALL sp_combo_routecategory();
	
	-- For Item Group
	CALL sp_combo_itemgroup();
	
	-- For Route Template Combo Box
	SELECT routecode AS id,routecode AS val FROM routemaster WHERE routetmpl	= 1;
	
END */$$
DELIMITER ;

