/* Procedure structure for procedure `sp_get_promotions_advancepricing_pricingchangeitemgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_advancepricing_pricingchangeitemgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_advancepricing_pricingchangeitemgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'p.*';
	END IF;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(*) INTO @counter FROM pricingdetail1 pd1
			INNER JOIN pricingplanheader1 pph1 ON pph1.customerpricingkey = pd1.customerpricingkey
			WHERE ACTIVE =1   ",table_where);	
	PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1; 
	select @counter as counter;-- primary_key, pd1.customerpricingkey,pd1.itemcode,pph1.description
	SET @dyn_sql = CONCAT("SELECT ", table_fields ,"   
			FROM pricingdetail1 pd1
			INNER JOIN pricingplanheader1 pph1 ON pph1.customerpricingkey = pd1.customerpricingkey
			WHERE ACTIVE =1  ",table_where,  " ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",@counter,"");
	PREPARE s2 FROM @dyn_sql;
	 EXECUTE s2;
	select @dyn_sql;
	
END */$$
DELIMITER ;

