	IF table_fields = '' THEN
		SET table_fields = 'p.*';
	END IF;
	
		SET @dyn_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM promokeydetail AS p 
		LEFT JOIN promoplandetail pd ON p.plannumber = pd.plannumber
		LEFT JOIN productgroupheader AS pgh ON pgh.groupnumber = p.qualificationgroup  
