DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_customer_addfreegoods`(in id bigint)
BEGIN
	if id > 0 then
		SELECT contractid,customercode,DATE_FORMAT(creationdate,"%d/%m/%Y") AS creationdate,DATE_FORMAT(enddate,"%d/%m/%Y") AS enddate, active, depotcode, remarks FROM customer_foc WHERE  `contractid` = id;
	else
		call sp_get_table_last_id('customer_foc');
