/* Procedure structure for procedure `sp_get_promotions_customer_freegoodsgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_customer_freegoodsgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_customer_freegoodsgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'cf.itemcode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'ASC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'cf.*';
	END IF;
	IF rwcnt = 1 THEN
		SET @dyn_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM  customer_foc_detail AS cf 
		LEFT JOIN itemmaster im ON cf.itemcode = im.actualitemcode
		LEFT JOIN customer_foc_balance cb ON (cf.contractid = cb.contractid AND cf.itemcode = cb.itemcode )
		WHERE 1=1  ",table_where);
	ELSE
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM  customer_foc_detail AS cf 
		LEFT JOIN itemmaster im ON cf.itemcode = im.actualitemcode
		LEFT JOIN customer_foc_balance cb ON (cf.contractid = cb.contractid AND cf.itemcode = cb.itemcode )
		WHERE 1=1  ",table_where,  " GROUP BY cf.itemcode ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	END IF;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
END */$$
