/* Procedure structure for procedure `sp_get_promotions_supervisor_addfreegoods` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_supervisor_addfreegoods` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_supervisor_addfreegoods`(IN id BIGINT)
BEGIN
	IF id > 0 THEN
		SELECT contractid,supervisorcode,DATE_FORMAT(creationdate,"%d/%m/%Y") AS creationdate,DATE_FORMAT(enddate,"%d/%m/%Y") AS enddate, active, depotcode, remarks FROM supervisor_foc WHERE  `contractid` = id;
	ELSE
		CALL sp_get_table_last_id('customer_foc');
	END IF;
	
	-- For Customer Data
	CALL sp_combo_customermaster;
	
	-- For Depot Data
	-- CALL sp_combo_depotmaster;
           -- CALL sp_combo_routemaster;
           CALL  sp_combo_supervisor;
	-- For Item Data
	CALL sp_combo_itemmaster;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_promotions_supervisor_freegoods` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_supervisor_freegoods` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_supervisor_freegoods`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'contractid';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'ASC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'cf.*';
	END IF;
	
    
		SET @dyn_cnt = CONCAT("SELECT COUNT(*) AS counter 
		FROM supervisor_foc AS cf 
		LEFT JOIN supervisor AS cm ON cm.supervisorcode =  cf.supervisorcode 
		WHERE 1=1  ",table_where);
		
		PREPARE s1 FROM @dyn_cnt;	
		EXECUTE s1;	
    
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM supervisor_foc AS cf 
		LEFT JOIN supervisor AS cm ON cm.supervisorcode =  cf.supervisorcode 
		WHERE 1=1 ",table_where,  " ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    
    	PREPARE s2 FROM @dyn_sql;	
