/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotions_supervisor_freegoodsgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotions_supervisor_freegoodsgrid`(
	IN rwcnt INT,
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_fields TEXT,
	IN table_where TEXT 
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'cf.itemcode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'ASC';
	END IF;
	IF table_fields = '' THEN
		SET table_fields = 'cf.*';
	END IF;
	IF rwcnt = 1 THEN
		SET @dyn_sql = CONCAT("SELECT COUNT(*) AS counter 
		FROM  supervisor_foc_detail AS cf 
		LEFT JOIN itemmaster im ON cf.itemcode = im.actualitemcode
		LEFT JOIN supervisor_foc_balance cb ON (cf.contractid = cb.contractid AND cf.itemcode = cb.itemcode )
		WHERE 1=1  ",table_where);
	ELSE
		SET @dyn_sql = CONCAT("SELECT ", table_fields ,"
		FROM  supervisor_foc_detail AS cf 
		LEFT JOIN itemmaster im ON cf.itemcode = im.actualitemcode
		LEFT JOIN supervisor_foc_balance cb ON (cf.contractid = cb.contractid AND cf.itemcode = cb.itemcode )
		WHERE 1=1  ",table_where,  " GROUP BY cf.itemcode ORDER BY ",order_by," ", 
		order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	END IF;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_promotion_advancepricing_addpricingplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotion_advancepricing_addpricingplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotion_advancepricing_addpricingplan`(IN id BIGINT)
BEGIN
	#For Country Data
	CALL sp_combo_country();
	
	IF id > 0 THEN
		SELECT * FROM pricingplanheader1 WHERE customerpricingkey = id;
		
		# get item master date
		CALL sp_combo_itemmaster;
		
		# Get Item information.
		SELECT actualitemcode,unitspercase,caseprice,returncaseprice,defaultgoodreturnprice,defaultsalesprice FROM itemmaster;
		
	ELSE 
		#For Table Last ID
		CALL sp_get_table_last_id('pricingplanheader1');
	END IF;
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_promotion_advancepricing_changeitempriceinplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotion_advancepricing_changeitempriceinplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotion_advancepricing_changeitempriceinplan`(IN id BIGINT)
BEGIN
	#For Item Master
	CALL sp_combo_itemmaster();
	
	#For Route Master
	CALL sp_combo_customermaster();
	
	SELECT actualitemcode AS id, alternatecode,itemshortdescription  AS itemdesc,unitspercase,caseprice,returncaseprice  FROM itemmaster WHERE activeitem = '1';
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_promotion_advancepricing_itemdetail_plan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotion_advancepricing_itemdetail_plan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotion_advancepricing_itemdetail_plan`(IN id BIGINT)
BEGIN
	if id > 0 then
		SELECT  primary_key, pd1.customerpricingkey,pd1.itemcode,pph1.description
			FROM pricingdetail1 pd1
			INNER JOIN pricingplanheader1 pph1 ON pph1.customerpricingkey = pd1.customerpricingkey
			WHERE active =1 AND  itemcode = id ;
		SELECT actualitemcode,unitspercase,caseprice,returncaseprice,defaultgoodreturnprice,defaultsalesprice FROM itemmaster
		WHERE actualitemcode = id;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_promotion_advancepricing_matchingpromoplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_promotion_advancepricing_matchingpromoplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_promotion_advancepricing_matchingpromoplan`(
IN  newkey INT
)
BEGIN
    DECLARE new_plan_count INT;
	SELECT COUNT(itemcode) INTO new_plan_count FROM TEMP_PRC_DETL_1 WHERE customerpricingkey = newkey;
	SET @matchingkey = -1;
	SELECT prckey INTO @pricingplan FROM(
	SELECT prckey , (SELECT COUNT(*) FROM pricingdetail1 WHERE customerpricingkey = prckey) OLDkeytot
	FROM(
	SELECT  o.customerpricingkey prckey
	FROM pricingdetail1 o, TEMP_PRC_DETL_1 n
	WHERE o.itemcode = n.itemcode
	AND o.salescaseprice = n.salesprice
	AND o.returncaseprice = n.returnprice
	AND n.customerpricingkey = newkey
	AND o.customerpricingkey <> newkey
	) k
	/*GROUP BY
	prckey
	HAVING COUNT(*) = new_plan_count*/
	) L WHERE OLDkeytot = new_plan_count LIMIT 1;
	select cph.pricingplankey ,cph.description into @matchingkey, @descr from customerpricingplanheader1 as cph
	 inner join customerpricing1 cp on cph.pricingplankey = cp.pricingplankey
	 where cp.customerpricingkey = @pricingplan;
	 
	SELECT @matchingkey as pricingkey, @descr as plandescr;
END */$$
DELIMITER ;

