		# Get Item information.
		SELECT actualitemcode,unitspercase,caseprice,returncaseprice,defaultgoodreturnprice,defaultsalesprice FROM itemmaster;
		
	ELSE 
		#For Table Last ID
		CALL sp_get_table_last_id('loyaltyplanheader');
	END IF;
	
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_report_routetracking` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_report_routetracking` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_report_routetracking`(
		IN var_routecode TEXT,
		IN var_startday VARCHAR(50),
		IN var_showcustomers INT(4)
	)
BEGIN
	
	IF var_showcustomers = 1 THEN
		SET @sql= CONCAT("
			SELECT map.routecode, map.salesmancode, map.entrydate, map.entrytime, map.endtime,map.latitude, map.longitude, 
				map.customercode, cm.customername
			FROM startendday sed
				INNER JOIN (SELECT routekey, routecode,salesmancode, visitstartdate entrydate, 
					CAST(visitstarttime AS TIME) entrytime, CAST(visitendtime AS TIME) endtime,latitude, longitude, customercode
					FROM customeroperationscontrol 
						UNION
					SELECT routekey, routecode, salesmancode, entrydate, entrytime,0 as endtime, latitude, longitude, 0 customercode
					FROM routetrack) map ON map.routekey = sed.routekey
				INNER JOIN customermaster cm ON cm.customercode = map.customercode	
			WHERE map.latitude > 0 AND sed.routestartdate = '", var_startday, "' AND sed.routecode IN (",var_routecode,")
			ORDER BY map.routecode, map.entrydate, map.entrytime");	
	ELSE
		SET @s1 =  'DROP TABLE IF EXISTS routetrack_temp';
		PREPARE s1 FROM @s1;
		EXECUTE s1;
		
		SET @latitude = 0.000000;
		SET @longitude = 0.000000;
		SET @route = 0;
		SET @s2 =  CONCAT("CREATE TABLE routetrack_temp AS 
				SELECT entryid, routekey, routecode, salesmancode, entrydate, entrytime, deviceid, latitude, longitude,
					@latitude := CASE WHEN @latitude = 0 THEN latitude WHEN @route = routecode THEN @latitude ELSE 0 END AS lat,
					@longitude := CASE WHEN @longitude = 0 THEN longitude WHEN @route = routecode THEN @longitude ELSE 0 END AS lon,
					@route := routecode routecodetemp,
					CASE WHEN (@latitude+@longitude) = 0 THEN 0 ELSE
						(((ACOS(SIN((latitude*PI()/180)) * SIN((@latitude*PI()/180))+COS((latitude*PI()/180)) * 
					    COS((@latitude*PI()/180)) * COS(((longitude-@longitude)* PI()/180))))*180/PI())*60*1.1515) * 1.609344 END AS difference       
				FROM routetrack WHERE routecode IN (",var_routecode,") AND entrydate = '", var_startday, "'
				ORDER BY routecode, entrydate, entrytime");
		PREPARE s2 FROM @s2;
		EXECUTE s2;
		
		SET @s1 =  'DROP TABLE IF EXISTS sfa_report_routetrack';
		PREPARE s1 FROM @s1;
		EXECUTE s1;
		
		SET @s2 =  CONCAT("CREATE TABLE sfa_report_routetrack AS 
				SELECT a.entryid, a.routekey, a.routecode, a.salesmancode, a.entrytime, a.latitude, a.longitude, a.difference,
					CASE WHEN m.firstid = a.entryid THEN 'min' ELSE 'max' END type
				FROM routetrack_temp AS a, 
					(SELECT routecode, entrydate, MIN(entryid) AS firstid, MAX(entryid) AS lastid FROM routetrack_temp GROUP BY routecode, entrydate) m
				WHERE m.routecode = a.routecode AND m.entrydate = a.entrydate AND (m.firstid = a.entryid OR m.lastid = a.entryid) AND
					a.routecode IN (", var_routecode, ") AND a.entrydate = '", var_startday, "'
			UNION
				SELECT a.entryid, a.routekey, a.routecode, a.salesmancode, a.entrytime, a.latitude, a.longitude, a.difference,
					'mid' TYPE
				FROM routetrack_temp AS a, 
					(SELECT routecode, entrydate, MAX(difference) AS lastpoint FROM routetrack_temp GROUP BY routecode, entrydate) m
				WHERE m.routecode = a.routecode AND m.entrydate = a.entrydate AND m.lastpoint = a.difference AND
					a.routecode IN (", var_routecode, ") AND a.entrydate = '", var_startday, "'
				ORDER BY 3, 5");
		PREPARE s2 FROM @s2;
		EXECUTE s2;			
		
		SET @sql= "
			SELECT routecode, salesmancode, 
				SEC_TO_TIME(SUM(TIME_TO_SEC(starttime))) starttime, SEC_TO_TIME(SUM(TIME_TO_SEC(endtime))) endtime, 
				SUM(startlat) startlatitude, SUM(startlon) startlongitude, 
				SUM(midlat) midlatitude, SUM(midlon) midlongitude,
				SUM(endlat) endlatitude, SUM(endlon) endlongitude
			FROM
			(
			SELECT routecode, salesmancode, entrytime starttime, '00:00:00' endtime, latitude startlat, longitude startlon, 0 midlat, 0 midlon, 0 endlat, 0 endlon
			FROM sfa_report_routetrack 
			WHERE TYPE = 'min'
				UNION
			SELECT routecode, salesmancode, '00:00:00' starttime, entrytime endtime, 0 startlat, 0 startlon, latitude midlat, longitude midlon, 0 endlat, 0 endlon
			FROM sfa_report_routetrack 
			WHERE TYPE = 'mid'
				UNION
			SELECT routecode, salesmancode, '00:00:00' starttime, entrytime endtime, 0 startlat, 0 startlon, 0 midlat, 0 midlon, latitude endlat, longitude endlon
			FROM sfa_report_routetrack 
			WHERE TYPE = 'max'
			) track
			GROUP BY routecode, salesmancode";	
	END IF;
	PREPARE s1 FROM @sql;
	EXECUTE s1;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_report_routetracking_2006` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_report_routetracking_2006` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_report_routetracking_2006`(
		IN var_routecode TEXT,
		IN var_startday VARCHAR(50),
		IN var_showcustomers INT(4)
	)
BEGIN
	
	IF var_showcustomers = 1 THEN
		SET @sql= CONCAT("
			SELECT map.routecode, map.salesmancode, map.entrydate, map.entrytime, map.latitude, map.longitude, 
				map.customercode, cm.customername
			FROM startendday sed
				INNER JOIN (SELECT routekey, routecode,salesmancode, visitstartdate entrydate, 
					CAST(visitstarttime AS TIME) entrytime, latitude, longitude, customercode
					FROM customeroperationscontrol 
						UNION
					SELECT routekey, routecode, salesmancode, entrydate, entrytime, latitude, longitude, 0 customercode
					FROM routetrack) map ON map.routekey = sed.routekey
				LEFT JOIN customermaster cm ON cm.customercode = map.customercode	
			WHERE map.latitude > 0 AND sed.routestartdate = '", var_startday, "' AND sed.routecode IN (",var_routecode,")
			ORDER BY map.routecode, map.entrydate, map.entrytime");	
	ELSE
		SET @s1 =  'DROP TABLE IF EXISTS routetrack_temp';
		PREPARE s1 FROM @s1;
		EXECUTE s1;
		
		SET @latitude = 0.000000;
		SET @longitude = 0.000000;
		SET @route = 0;
		SET @s2 =  CONCAT("CREATE TABLE routetrack_temp AS 
				SELECT entryid, routekey, routecode, salesmancode, entrydate, entrytime, deviceid, latitude, longitude,
					@latitude := CASE WHEN @latitude = 0 THEN latitude WHEN @route = routecode THEN @latitude ELSE 0 END AS lat,
					@longitude := CASE WHEN @longitude = 0 THEN longitude WHEN @route = routecode THEN @longitude ELSE 0 END AS lon,
					@route := routecode routecodetemp,
					CASE WHEN (@latitude+@longitude) = 0 THEN 0 ELSE
						(((ACOS(SIN((latitude*PI()/180)) * SIN((@latitude*PI()/180))+COS((latitude*PI()/180)) * 
					    COS((@latitude*PI()/180)) * COS(((longitude-@longitude)* PI()/180))))*180/PI())*60*1.1515) * 1.609344 END AS difference       
				FROM routetrack WHERE routecode IN (",var_routecode,") AND entrydate = '", var_startday, "'
				ORDER BY routecode, entrydate, entrytime");
		PREPARE s2 FROM @s2;
		EXECUTE s2;
		
		SET @s1 =  'DROP TABLE IF EXISTS sfa_report_routetrack';
		PREPARE s1 FROM @s1;
		EXECUTE s1;
		
		SET @s2 =  CONCAT("CREATE TABLE sfa_report_routetrack AS 
				SELECT a.entryid, a.routekey, a.routecode, a.salesmancode, a.entrytime, a.latitude, a.longitude, a.difference,
					CASE WHEN m.firstid = a.entryid THEN 'min' ELSE 'max' END type
				FROM routetrack_temp AS a, 
					(SELECT routecode, entrydate, MIN(entryid) AS firstid, MAX(entryid) AS lastid FROM routetrack_temp GROUP BY routecode, entrydate) m
				WHERE m.routecode = a.routecode AND m.entrydate = a.entrydate AND (m.firstid = a.entryid OR m.lastid = a.entryid) AND
					a.routecode IN (", var_routecode, ") AND a.entrydate = '", var_startday, "'
			UNION
				SELECT a.entryid, a.routekey, a.routecode, a.salesmancode, a.entrytime, a.latitude, a.longitude, a.difference,
					'mid' TYPE
				FROM routetrack_temp AS a, 
					(SELECT routecode, entrydate, MAX(difference) AS lastpoint FROM routetrack_temp GROUP BY routecode, entrydate) m
				WHERE m.routecode = a.routecode AND m.entrydate = a.entrydate AND m.lastpoint = a.difference AND
					a.routecode IN (", var_routecode, ") AND a.entrydate = '", var_startday, "'
				ORDER BY 3, 5");
		PREPARE s2 FROM @s2;
		EXECUTE s2;			
		
		SET @sql= "
			SELECT routecode, salesmancode, 
				SEC_TO_TIME(SUM(TIME_TO_SEC(starttime))) starttime, SEC_TO_TIME(SUM(TIME_TO_SEC(endtime))) endtime, 
				SUM(startlat) startlatitude, SUM(startlon) startlongitude, 
				SUM(midlat) midlatitude, SUM(midlon) midlongitude,
				SUM(endlat) endlatitude, SUM(endlon) endlongitude
			FROM
			(
			SELECT routecode, salesmancode, entrytime starttime, '00:00:00' endtime, latitude startlat, longitude startlon, 0 midlat, 0 midlon, 0 endlat, 0 endlon
			FROM sfa_report_routetrack 
			WHERE TYPE = 'min'
				UNION
			SELECT routecode, salesmancode, '00:00:00' starttime, entrytime endtime, 0 startlat, 0 startlon, latitude midlat, longitude midlon, 0 endlat, 0 endlon
			FROM sfa_report_routetrack 
			WHERE TYPE = 'mid'
				UNION
			SELECT routecode, salesmancode, '00:00:00' starttime, entrytime endtime, 0 startlat, 0 startlon, 0 midlat, 0 midlon, latitude endlat, longitude endlon
			FROM sfa_report_routetrack 
			WHERE TYPE = 'max'
			) track
			GROUP BY routecode, salesmancode";	
	END IF;
	PREPARE s1 FROM @sql;
	EXECUTE s1;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_customer_from_routecode` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_customer_from_routecode` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_customer_from_routecode`(
	IN trankey	BIGINT(28),
	IN trantype INT(4)
    )
BEGIN
		DECLARE routeid BIGINT(18);
		DECLARE salesmanid BIGINT(18);
		DECLARE custcode BIGINT(18);
		
		IF trantype = 1 THEN 
			SELECT routecode,salesmancode,customercode INTO routeid,salesmanid,custcode FROM arheader WHERE transactionkey = trankey;
		ELSE
			SELECT routecode,salesmancode,customercode INTO routeid,salesmanid,custcode FROM customerinvoice WHERE transactionkey = trankey;
		END IF;
				
		SELECT routecode,routename FROM routemaster WHERE routecode 	= routeid;
		SELECT salesmancode,salesmanname1 FROM salesman WHERE salesmancode 	= salesmanid;
		-- call sp_combo_customermaster_routecode(routeid);
		CALL sp_combo_customermaster();
		CALL sp_combo_bankmaster();
		select custcode;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_customer_from_routecode_crheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_customer_from_routecode_crheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_customer_from_routecode_crheader`(
	IN trankey	BIGINT(28),
	in trantype int(4)
    )
BEGIN
		declare routeid bigint(18);
		DECLARE salesmanid BIGINT(18);
		DECLARE custcode BIGINT(18) DEFAULT 0;
		
		IF trantype = 1 THEN 
			select routecode,salesmancode into routeid,salesmanid from cashierreceiptheader where documentnumber = trankey;		
		ELSEIF trantype = 2 THEN 
			SELECT routecode,salesmancode,customercode INTO routeid,salesmanid,custcode FROM customerinvoice WHERE transactionkey = trankey;
		else
			select 1;
		END IF;
				
		select routecode,routename from routemaster where routecode = routeid;
		SELECT salesmancode,salesmanname1 FROM salesman WHERE salesmancode 	= salesmanid;
		-- call sp_combo_customermaster_routecode(routeid);
		CALL sp_combo_customermaster();
		call sp_combo_bankmaster();
		SELECT ifnull(custcode,0) as custcode;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_enddate_time` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_enddate_time` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_enddate_time`(
		IN routeid BIGINT	    
	)
BEGIN
	
	SELECT CONCAT(DATE_FORMAT(routeenddate,"%d-%m-%Y"),' ',routeendtime) AS routeenddate 
		FROM startendday WHERE routeclosed = 1 AND routecode = routeid ORDER BY MAX(routeenddate) DESC LIMIT 1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_from_criteria` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_from_criteria` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_from_criteria`(
					IN fillby 		INT,
					IN val 			VARCHAR(20),				
					IN routeitmgrp 	VARCHAR(20)
					)
BEGIN
	DECLARE where_cond 	TEXT;
	DECLARE joining 	TEXT;
	DECLARE where_route TEXT;
	
	IF fillby = 1 THEN
		SET where_cond 	=  ' AND route.regionmstcode =';
		SET joining 	=  '';
	ELSEIF	fillby = 2 THEN
		SET where_cond 	=  'AND depot.depotcode =';
		SET joining 	=  'LEFT JOIN regionmaster AS reg ON reg.regionmstcode = route.regionmstcode
							LEFT JOIN depotmaster AS depot ON depot.regionmstcode = reg.regionmstcode'; 
	ELSEIF	fillby = 3 THEN
		SET where_cond 	=  'AND armst.areacode =';
		SET joining		=  'LEFT JOIN subareamaster AS sub ON sub.subareacode = route.subareacode
							LEFT JOIN areamaster AS armst ON armst.areacode = sub.areacode';
	END IF;
	
	IF val = '0' THEN
		SET where_cond 	=	'';
		SET val 		= 	'';
	END IF;
	
	IF routeitmgrp !='0' THEN
		SET where_route = concat(' AND route.routeitemgrpcode = ',routeitmgrp);
	ELSE
		SET where_route = ' AND 1=1 ';
		SET routeitmgrp = '';
	END IF;
	
	
	
	-- Below Query for select route
	SET @q1 = CONCAT( "SELECT route.routecode AS id, CONCAT(route.routecode,' -- ',route.routename) AS val FROM routemaster as route
						",joining," WHERE 9=9 ",where_cond," ",val," AND routetmpl = 0 AND route.activestatus = 1"); 
	
	PREPARE s1 FROM @q1;
	EXECUTE s1;
	-- select @q1;
	
	-- Below Query for selected route
	SET @q2 = CONCAT( 	"SELECT route.routecode AS id, CONCAT(route.routecode,' -- ',route.routename) AS val FROM routemaster as route
						",joining," WHERE 9=9 ",where_cond," ",val," AND routetmpl = 0 ",where_route," AND route.activestatus = 1");
	PREPARE s2 FROM @q2;
	EXECUTE s2;
	-- select @q2;
	
	-- Below Query for selected route id	
	SET @q3 = CONCAT( 	"SELECT route.routecode AS routecode FROM routemaster as route
						",joining," WHERE 9=9 ",where_cond," ",val," AND routetmpl = 0 ",where_route," AND route.activestatus = 1");
	PREPARE s3 FROM @q3;
	EXECUTE s3;
	-- select @q3;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_route_status_startendday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_route_status_startendday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_route_status_startendday`(IN routeid BIGINT,IN routedate VARCHAR(50))
BEGIN
	SELECT COUNT(*) AS cnt FROM startendday 
		WHERE routeclosed = 0 AND DATE(routestartdate) = STR_TO_DATE(routedate,'%d-%m-%Y') AND routecode = routeid;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_salesman` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_salesman` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_salesman`(
	IN form VARCHAR(20),
	IN param1 VARCHAR(10)
	)
BEGIN
	IF form = 'TARGET' THEN
		SET @sql1 = CONCAT("SELECT DISTINCT sm.salesmancode AS id, CONCAT(sm.salesmancode,' - ',sm.salesmanname1) AS val 
		FROM routemaster rm
			INNER JOIN salesman sm on sm.salesmancode = rm.salesmancode AND sm.activestatus = 1");
			
	ELSEIF form = 'ROUTE' THEN
		SET @cond = '';
		IF param1 != '' THEN
			SET @cond = CONCAT(' WHERE rm.routecode <> ', param1);
		END IF;
		
		SET @sql1 = CONCAT("SELECT DISTINCT sm.salesmancode AS id, CONCAT(sm.salesmancode,' - ',sm.salesmanname1) AS val 
		FROM salesman sm 
		WHERE sm.activestatus = 1 AND sm.salesmancode NOT IN (SELECT DISTINCT COALESCE(rm.salesmancode,0) FROM routemaster rm", @cond, ")");
			
	ELSE
		SET @sql1 = CONCAT("SELECT DISTINCT sm.salesmancode AS id, CONCAT(sm.salesmancode,' - ',sm.salesmanname1) AS val 
		FROM salesman sm 
		WHERE sm.activestatus = 1");
					
	END IF;
	
	PREPARE s1 FROM @sql1;
	EXECUTE s1;
	
END */$$
DELIMITER ;

