DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_customerinvoice_additem_customer_100423`(
IN var_item INT,
IN var_customer INT
)
BEGIN
	select actualitemcode,unitspercase,itemshortdescription as  itemdesc,caseprice,returncaseprice from itemmaster where actualitemcode = var_item;
	 
