/* Procedure structure for procedure `sp_get_transaction_index_addcustomerinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_addcustomerinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_addcustomerinvoice`(
    IN id INT
    )
BEGIN
   
    CALL sp_combo_routemaster();
    -- For Header
    SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ih.routecode,ih.salesmancode,ih.*,
        cm.customeraddress1,cm.customeraddress2,cm.customeraddress3,cm.customername,cm.arbcustomername,sm.salesmanname1 AS salesmanname,rm.routename,
        CASE WHEN ih.voidflag = 0 THEN 'NORMAL' ELSE 'VOIDED' END AS voidflag, sn.signaturedata,ih.customercode,hhcinvoicenumber,comments, 
        ih.totalinvoiceamount AS invamt, ci.amount AS amtpaid, ih.invoicebalance AS invbal,ih.itemlinetaxamount,
        DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate,ih.totalexpiryamount,cm.taxregistrationnumber,cm.traname
        FROM invoiceheader AS ih
        LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
        LEFT JOIN routemaster AS rm ON rm.routecode = ih.routecode
        LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
        LEFT JOIN cashcheckdetail AS ci ON ih.routekey = ci.routekey AND ih.visitkey = ci.visitkey
        LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
        LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
    WHERE ih.transactionkey = id;
   
   
    -- For Mode of Payment
    SELECT cm.invoicepaymentterms AS paymentterm,
           ccd.typecode, ccd.checknumber, ccd.amount, ccd.checkdate,
           bm.bankname       
           FROM invoiceheader AS ih
           LEFT JOIN cashcheckdetail AS ccd ON ih.routekey = ccd.routekey AND ih.visitkey = ccd.visitkey
           LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
           LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
    WHERE ih.transactionkey = id;
    
    SELECT SUM(promoamount) AS promoamount  FROM invoicedetail WHERE transactionkey = id;
    
   	
	
    SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
    select routecode into @routecode FROM invoiceheader  WHERE transactionkey = id;
     IF @st = 1 THEN 
		SELECT cm.customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster cm 
		INNER JOIN routesequence rs ON cm.customercode = rs.customercode  
		WHERE activecustomer = 1 AND templateindicator = 0 AND rs.routecode=@routecode; 
	    ELSE
		SELECT cm.customercode AS id, CONCAT(cm.customercode,' -- ',customername) AS val FROM customermaster cm 
		INNER JOIN routesequence rs ON cm.customercode = rs.customercode  
		WHERE activecustomer = 1 AND templateindicator = 0 AND rs.routecode=@routecode;  
	    END IF;
    END */$$
DELIMITER ;

