        ih.totalinvoiceamount AS invamt, ci.amount AS amtpaid, ih.invoicebalance AS invbal,ih.itemlinetaxamount,
        DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate,ih.totalexpiryamount,cm.taxregistrationnumber,cm.traname, ih.paymenttype, cm.taxcardno
        FROM invoiceheader_foc AS ih
        LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
