        LEFT JOIN cashcheckdetail AS ci ON ih.routekey = ci.routekey AND ih.visitkey = ci.visitkey
        LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
        LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
    WHERE ih.transactionkey = id;
   
   
    -- For Mode of Payment
   /* SELECT cm.invoicepaymentterms AS paymentterm,
           ccd.typecode, ccd.checknumber, ccd.amount, ccd.checkdate,
           bm.bankname       
           FROM invoiceheader_foc AS ih
           LEFT JOIN cashcheckdetail AS ccd ON ih.routekey = ccd.routekey AND ih.visitkey = ccd.visitkey
           LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
           LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
    WHERE ih.transactionkey = id;
    */
    
    SELECT '' paymentterm,
           '' typecode, '' checknumber, '' amount, '' checkdate,
           '' bankname       
           FROM invoiceheader_foc AS ih
           LEFT JOIN cashcheckdetail AS ccd ON ih.routekey = ccd.routekey AND ih.visitkey = ccd.visitkey
           LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
           LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
    WHERE ih.transactionkey = id;
    
    SELECT SUM(promoamount) AS promoamount  FROM invoicedetail_foc WHERE transactionkey = id;
    
    SELECT imagename
	FROM `invoiceheader_foc` AS ih 
	JOIN `customerimages` c ON c.routekey = ih.routekey AND c.visitkey=ih.visitkey WHERE ih.transactionkey = id;	
	
   --  SELECT   customercode,hhcinvoicenumber,comments FROM invoiceheader WHERE transactionkey = id;
    END */$$
DELIMITER ;

