/* Procedure structure for procedure `sp_get_transaction_index_addinvoice_old` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_addinvoice_old` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_addinvoice_old`(
    IN id INT
    )
BEGIN
   
    CALL sp_combo_routemaster();
    -- For Header
    SELECT presoldordernumber INTO @presold FROM invoiceheader WHERE transactionkey=id;
IF @presold=0 THEN
    SELECT payment_mode(scl.invoicepaymentterms) AS paymentterm,ih.routecode,ih.salesmancode,ih.*,
        cm.customeraddress1,cm.customeraddress2,cm.customeraddress3,cm.customername,cm.arbcustomername,sm.salesmanname1 AS salesmanname,rm.routename,
        CASE WHEN ih.voidflag = 0 THEN 'NORMAL' ELSE 'VOIDED' END AS voidflag, sn.signaturedata,
        ih.totalinvoiceamount AS invamt, ci.amount AS amtpaid, ih.invoicebalance AS invbal,ih.itemlinetaxamount,
        DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate,customerphone,pobox,vendorid,cm.emailid,cm.enableponumber,cm.printvendorid
        FROM invoiceheader AS ih
        LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
        LEFT JOIN routemaster AS rm ON rm.routecode = ih.routecode
        LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
        LEFT JOIN salescategorylimit AS scl ON scl.customercode = ih.customercode
        LEFT JOIN cashcheckdetail AS ci ON ih.routekey = ci.routekey AND ih.visitkey = ci.visitkey
        LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
        LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
    WHERE ih.transactionkey = id;
ELSE
   SELECT payment_mode(scl.invoicepaymentterms) AS paymentterm,ih.routecode,sh.salesmancode,ih.*,
        cm.customeraddress1,cm.customeraddress2,cm.customeraddress3,cm.customername,cm.arbcustomername,
        sm.salesmanname1 AS salesmanname,rm.routename,
        CASE WHEN ih.voidflag = 0 THEN 'NORMAL' ELSE 'VOIDED' END AS voidflag, sn.signaturedata,
        ih.totalinvoiceamount AS invamt, ci.amount AS amtpaid, ih.invoicebalance AS invbal,ih.itemlinetaxamount,
        DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate,customerphone,pobox,vendorid,cm.emailid,cm.enableponumber,cm.printvendorid
        FROM invoiceheader AS ih
		LEFT JOIN salesorderheader AS sh ON ih.presoldordernumber = sh.invoicenumber
        LEFT JOIN salesman AS sm ON sm.salesmancode = sh.salesmancode
        LEFT JOIN routemaster AS rm ON rm.routecode = ih.routecode
        LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
        LEFT JOIN salescategorylimit AS scl ON scl.customercode = ih.customercode
        LEFT JOIN cashcheckdetail AS ci ON ih.routekey = ci.routekey AND ih.visitkey = ci.visitkey
        LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
        LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
    WHERE ih.transactionkey = id;
   
   END IF;
    -- For Mode of Payment
    SELECT cm.invoicepaymentterms AS paymentterm,
           ccd.typecode, ccd.checknumber, ccd.amount, ccd.checkdate,
           bm.bankname       
           FROM invoiceheader AS ih
           LEFT JOIN cashcheckdetail AS ccd ON ih.routekey = ccd.routekey AND ih.visitkey = ccd.visitkey
           LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
           LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode
    WHERE ih.transactionkey = id;
    
    SELECT SUM(promoamount) AS promoamount  FROM invoicedetail WHERE transactionkey = id;
    
    SELECT imagename
	FROM `invoiceheader` AS ih 
	JOIN `customerimages` c ON c.routekey = ih.routekey AND c.visitkey=ih.visitkey WHERE ih.transactionkey = id AND c.imgtype='1';	
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_advpayment` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_advpayment` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_advpayment`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ah.*';
	END IF;
	
	if table_where = '' then
		set table_where = concat(' AND transactiondate =  ',date(CURRENT_DATE()));
	end if;
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(transactionkey) AS counter FROM arheader as ah 
	LEFT JOIN routemaster as rm on rm.routecode = ah.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ah.salesmancode
	LEFT JOIN customermaster as cm on cm.customercode = ah.customercode	
	WHERE 1=1  AND advancepaymentflag = 1 ",table_where);
    PREPARE s1 FROM @dyn_cnt;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM arheader as ah 
	LEFT JOIN routemaster as rm on rm.routecode = ah.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ah.salesmancode
	LEFT JOIN customermaster as cm on cm.customercode = ah.customercode	
	WHERE 1=1  AND advancepaymentflag = 1 ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_advpaymentdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_advpaymentdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_advpaymentdetail`(
    IN id INT
    )
BEGIN
   
    CALL sp_combo_routemaster();
    -- For Header
    SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ah.routecode,ah.salesmancode,ah.*,
    cm.customeraddress1,cm.customername,sm.salesmanname1 AS salesmanname ,amountpaid,ah.totalinvoiceamount,
    (ah.totalinvoiceamount-amountpaid) AS balancedue,
    CASE WHEN voidflag = 0 THEN 'NORMAL' ELSE 'VOIDED' END AS voidflag,signaturedata,
    DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate
    FROM arheader AS ah
        LEFT JOIN salesman AS sm ON sm.salesmancode = ah.salesmancode
        LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode   
        -- LEFT JOIN sigcapturedata AS sn ON sn.customercode = ah.customercode
        LEFT JOIN sigcapturedata AS sn ON sn.routekey = ah.routekey AND sn.visitkey = ah.visitkey
        LEFT JOIN startendday AS ed ON ed.routekey = ah.routekey    
    WHERE ah.transactionkey = id;
   
    -- For Mode of Payment
    SELECT cm.invoicepaymentterms AS paymentterm,
           ccd.typecode, ccd.checknumber, ccd.amount, ccd.checkdate,
           bm.bankname       
           FROM arheader AS ah
           -- LEFT JOIN cashcheckdetail AS ccd ON ah.transactionkey = ccd.hhctransactionkey  AND ah.visitkey = ccd.visitkey
           LEFT JOIN cashcheckdetail AS ccd ON ah.routekey = ccd.routekey  AND ah.visitkey = ccd.visitkey
           LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
           LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode
    WHERE ah.transactionkey = id AND ah.advancepaymentflag = '1' ;
   
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_arcollectionadd` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_arcollectionadd` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_arcollectionadd`(
    IN id INT
    )
BEGIN
   
    CALL sp_combo_routemaster();
    CALL sp_combo_customermaster();
    -- For Header
    if id > 0 then
	    SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ah.routecode,ah.salesmancode,ah.*,
		cm.customeraddress1,cm.customername,sm.salesmanname1 AS salesmanname,
		CASE WHEN voidflag = 0 THEN 'NORMAL' ELSE 'VOIDED' END AS voidflag,signaturedata,SUM(amountpaid) AS totalamountpaid,
		DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate
		FROM arheader AS ah
		LEFT JOIN salesman AS sm ON sm.salesmancode = ah.salesmancode
		LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode
		LEFT JOIN startendday AS ed ON ed.routekey = ah.routekey    
		-- LEFT JOIN sigcapturedata AS sn ON sn.customercode = ah.customercode
		LEFT JOIN sigcapturedata AS sn ON sn.routekey = ah.routekey AND sn.visitkey = ah.visitkey        
	    WHERE ah.transactionkey = id GROUP BY amountpaid;
	    -- For AR Payment
	    SELECT invoicenumber,DATE_FORMAT(invoicedate,'%d-%m-%Y') AS invoicedate,totalinvoiceamount,amountpaid,(totalinvoiceamount-amountpaid) AS balancedue
	    FROM ardetail WHERE transactionkey = id;
	   
	    -- For Mode of Payment
	    SELECT cm.invoicepaymentterms AS paymentterm,
		   ccd.typecode, ccd.checknumber, ccd.amount, ccd.checkdate,
		   bm.bankname       
		   FROM arheader AS ah
		   -- LEFT JOIN cashcheckdetail AS ccd ON ah.transactionkey = ccd.hhctransactionkey  AND ah.visitkey = ccd.visitkey
		   LEFT JOIN cashcheckdetail AS ccd ON ah.routekey = ccd.routekey  AND ah.visitkey = ccd.visitkey
		   LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
		   LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode
	    WHERE ah.transactionkey = id AND ah.advancepaymentflag != 1 ;
   end if;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_arcollection_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_arcollection_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_arcollection_report`(
    IN var_transactiondate VARCHAR(20)
    )
BEGIN
       -- IF var_transactiondate != '' THEN
	SELECT cm.hhccustomernameshort,invoicenumber, alternatecode, customername, routename, payment_mode(invoicepaymentterms), FORMAT(amountpaid,3) AS totalinvoiceamount
	FROM arheader AS ah 
	LEFT JOIN routemaster AS rm ON rm.routecode = ah.routecode
	LEFT JOIN salesman AS sm ON sm.salesmancode = ah.salesmancode
	LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode	
	WHERE advancepaymentflag != 1  AND  transactiondate = DATE(var_transactiondate)    AND record_flag = '1'  ORDER BY transactionkey DESC;
      --  END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_arheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_arheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_arheader`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ah.*';
	END IF;
	
	if table_where = '' then
		set table_where = concat(' AND transactiondate =  ',date(CURRENT_DATE()));
	end if;
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(transactionkey) AS counter FROM arheader as ah 
	LEFT JOIN routemaster as rm on rm.routecode = ah.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ah.salesmancode
	LEFT JOIN customermaster as cm on cm.customercode = ah.customercode	
	WHERE advancepaymentflag != 1 ",table_where);
	
	
	 PREPARE s1 FROM @dyn_cnt;	
	 EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM arheader as ah 
	LEFT JOIN routemaster as rm on rm.routecode = ah.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ah.salesmancode
	LEFT JOIN customermaster as cm on cm.customercode = ah.customercode	
	WHERE advancepaymentflag != 1 ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_arheaderdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_arheaderdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_arheaderdetail`(
    IN id INT
    )
BEGIN
   
    CALL sp_combo_routemaster();
    -- For Header
    SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ah.routecode,ah.salesmancode,ah.*,
        cm.customeraddress1,cm.customername,sm.salesmanname1 AS salesmanname,
        CASE WHEN voidflag = 0 THEN 'NORMAL' ELSE 'VOIDED' END AS voidflag,signaturedata,SUM(amountpaid) AS totalamountpaid,
        DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate
        FROM arheader AS ah
        LEFT JOIN salesman AS sm ON sm.salesmancode = ah.salesmancode
        LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode
        LEFT JOIN startendday AS ed ON ed.routekey = ah.routekey    
        -- LEFT JOIN sigcapturedata AS sn ON sn.customercode = ah.customercode
        LEFT JOIN sigcapturedata AS sn ON sn.routekey = ah.routekey AND sn.visitkey = ah.visitkey        
    WHERE ah.transactionkey = id GROUP BY amountpaid;
    -- For AR Payment
    SELECT invoicenumber,DATE_FORMAT(invoicedate,'%d-%m-%Y') AS invoicedate,totalinvoiceamount,amountpaid,(totalinvoiceamount-amountpaid) AS balancedue
    FROM ardetail WHERE transactionkey = id;
   
    -- For Mode of Payment
    SELECT cm.invoicepaymentterms AS paymentterm,
           ccd.typecode, ccd.checknumber, ccd.amount, ccd.checkdate,
           bm.bankname       
           FROM arheader AS ah
           -- LEFT JOIN cashcheckdetail AS ccd ON ah.transactionkey = ccd.hhctransactionkey  AND ah.visitkey = ccd.visitkey
           LEFT JOIN cashcheckdetail AS ccd ON ah.routekey = ccd.routekey  AND ah.visitkey = ccd.visitkey
           LEFT JOIN bankmaster AS bm ON ccd.bankcode = bm.bankcode   
           LEFT JOIN customermaster AS cm ON cm.customercode = ah.customercode
    WHERE ah.transactionkey = id AND ah.advancepaymentflag != 1 ;
   
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_arpaymentdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_arpaymentdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_arpaymentdetail`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	in tran_key bigint 
	
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
