	WHERE 1=1 AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
END */$$
