/* Procedure structure for procedure `sp_get_transaction_index_dispatchsalesorderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_dispatchsalesorderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_dispatchsalesorderheader`(
	IN id INT
    )
BEGIN
	
 CALL sp_combo_routemaster_splitsalesorder();
	-- CALL sp_combo_routemaster();
	-- For Header
	SELECT deliveryno,orderno,customername,presalesroute,
		DATE_FORMAT(deliverydate,'%d-%m-%Y') AS deliverydate,ponumber
		FROM deliveryheader AS ih
		LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode   
	WHERE ih.deliveryno = id;
	
    END */$$
