/* Procedure structure for procedure `sp_get_transaction_index_dispatch_salesorderdetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_dispatch_salesorderdetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_dispatch_salesorderdetailgrid`(
	IN orderno BIGINT 
	
	)
BEGIN
	
		SET @lmt_strt=0;
	
	
	
		SET @lmt_end=100;
	
		SET @order_by = 'id.deliveryindex';
	
		SET @order_type= 'DESC';
	
	
     
	SET @dyn_cnt = CONCAT("SELECT COUNT(deliveryindex) AS counter FROM deliverydetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 AND id.processedflag = 0   and deliveryno='",orderno,"'");
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	-- select @dyn_cnt;
	
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
	
	IF @st = 1 THEN 
	
	SET @dyn_sql = CONCAT("SELECT deliveryindex ,deliveryno,alternatecode as alternatecode,itemshortdescription,id.caseprice as salescaseprice,id.salesprice,id.unitspercase,
FLOOR((id.salesqty/im.unitspercase)) AS case_sales_qty, (id.salesqty%im.unitspercase) AS pcs_sales_qty, FLOOR((id.manualfreeqty/im.unitspercase)) AS case_foc_qty, (id.manualfreeqty%im.unitspercase) AS pcs_foc_qty, 
id.returnqty, IFNULL(id.returnprice,0)as returnprice, FORMAT(((((id.salesqty div im.unitspercase)*id.caseprice)+((id.salesqty%im.unitspercase)*id.salesprice))- (id.returnqty*id.returnprice)-id.promotionamount),3) AS total_amount FROM deliverydetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	
	WHERE 1=1  and id.processedflag = 0   and deliveryno='",orderno,"' ORDER BY ",@order_by," ", @order_type," LIMIT ",@lmt_strt,", ",@lmt_end,"");
	ELSE
	SET @dyn_sql = CONCAT("SELECT deliveryindex ,deliveryno,itemcode as alternatecode,itemshortdescription,id.caseprice as salescaseprice,id.salesprice,id.unitspercase,
FLOOR((id.salesqty/im.unitspercase)) AS case_sales_qty, (id.salesqty%im.unitspercase) AS pcs_sales_qty, FLOOR((id.manualfreeqty/im.unitspercase)) AS case_foc_qty, (id.manualfreeqty%im.unitspercase) AS pcs_foc_qty,
id.returnqty, IFNULL(id.returnprice,0)as returnprice, 
FORMAT(((((id.salesqty div im.unitspercase)*id.caseprice)+((id.salesqty%im.unitspercase)*id.salesprice)) - (id.returnqty*id.returnprice) - id.promotionamount),3) AS total_amount 
FROM deliverydetail AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	
	WHERE 1=1  and id.processedflag = 0   and deliveryno='",orderno,"' ORDER BY ",@order_by," ", @order_type," LIMIT ",@lmt_strt,", ",@lmt_end,"");
	
	END IF;
	-- select @dyn_sql;	
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_focinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_focinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_focinvoice`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	IF table_where = '' THEN
		SET table_where = CONCAT(' AND transactiondate =  ',DATE(CURRENT_DATE()));
	END IF;
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(transactionkey) AS counter FROM invoiceheader_foc as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE 1=1  ",table_where);
    PREPARE s1 FROM @dyn_cnt;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoiceheader_foc as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	SELECT @dyn_sql;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_focinvoicedetailgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_focinvoicedetailgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_focinvoicedetailgrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN tran_key BIGINT 
	
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	  
	SELECT routekey INTO @routekey FROM invoiceheader WHERE transactionkey =  tran_key;
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(primary_key) AS counter FROM invoicedetail_foc AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1
	--  AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 )
	AND transactionkey = ",tran_key," ",table_where);
	
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoicedetail_foc AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 
	-- AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 ) 
	AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	-- select @dyn_sql;
	SET @dyn_tc = CONCAT("SELECT 
         IFNULL(SUM((((salesqty/im.unitspercase)*id.salescaseprice)+((salesqty%im.unitspercase)*id.salesprice))-(((returnqty/im.unitspercase)*id.returncaseprice)+((returnqty%im.unitspercase)*id.returnprice))-promoamount),0)	 as tc_amount
	 FROM invoicedetail_foc AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 and im.tcallowed = '1' 
	-- AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 )
	 AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where);
	-- select @dyn_tc;
    PREPARE s3 FROM @dyn_tc;
	EXECUTE s3;	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_focinvoicedetailgrid_print` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_focinvoicedetailgrid_print` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_focinvoicedetailgrid_print`(	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN tran_key BIGINT 
	
	)
BEGIN	
	SET order_by = '1 ';
		
	SET order_type= 'ASC';	
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;	
		
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoicedetail_foc AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	LEFT JOIN tbltaxmaster AS ttm ON ttm.taxcode = im.itemtaxkey2
	WHERE 1=1 
	AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type,"");
	PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	
	SET @dyn_cnt = CONCAT("SELECT COALESCE(sum(salesqty),0) as salescount, COALESCE(sum(returnqty),0) as returncount, 
	COALESCE(sum(damagedqty),0) as damagecount, COALESCE(sum(freesampleqty),0) as promocount, 
	COALESCE(sum(manualfreeqty),0) as freecount 
	FROM invoicedetail_foc AS id 
	WHERE transactionkey = ",tran_key," ");
	
	PREPARE s5 FROM @dyn_cnt;
	EXECUTE s5;
	
	-- select @dyn_sql;
    
END */$$
DELIMITER ;

