/* Procedure structure for procedure `sp_get_transaction_index_invoicedetailtempgrid` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_invoicedetailtempgrid` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_invoicedetailtempgrid`(
	IN rwcnt INT,	
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT,
	IN tran_key BIGINT,
	IN inv_view VARCHAR(10) 
	
	)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'primary_key';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	IF inv_view = '' THEN 
	  SET @detailtable = "invoicedetail_temp";
	  SELECT routekey INTO @routekey FROM invoiceheader_temp WHERE transactionkey =  tran_key;
	ELSE 
	  SET @detailtable = "invoicedetail";
	  SELECT routekey INTO @routekey FROM invoiceheader WHERE transactionkey =  tran_key;
	END IF;
	
	
	SET @dyn_cnt = CONCAT("SELECT COUNT(primary_key) AS counter FROM ",@detailtable," AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1
	--  AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 ) AND routekey = @routekey
	  AND transactionkey = ",tran_key," ",table_where);
	
    PREPARE s1 FROM @dyn_cnt;
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM ",@detailtable," AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 
	-- AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 ) AND routekey = @routekey
	 AND transactionkey = ",tran_key," ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;	
	 -- select @dyn_sql;
	SET @dyn_tc = CONCAT("SELECT 
         IFNULL(SUM((((salesqty/im.unitspercase)*id.salescaseprice)+((salesqty%im.unitspercase)*id.salesprice))-(((returnqty/im.unitspercase)*id.returncaseprice)+((returnqty%im.unitspercase)*id.returnprice))-promoamount),0)	 as tc_amount
	 FROM ",@detailtable," AS id 
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode
	WHERE 1=1 and im.tcallowed = '1' 
	-- AND ( salesqty > 0 OR returnqty > 0 OR damagedqty > 0 OR manualfreeqty > 0 )
	 AND routekey = @routekey AND transactionkey = ",tran_key," ",table_where);
	-- select @dyn_tc;
    PREPARE s3 FROM @dyn_tc;
	EXECUTE s3;	
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_manualinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_manualinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_manualinvoice`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	IF table_where = '' THEN
		SET table_where = CONCAT(' AND transactiondate =  ',DATE(CURRENT_DATE()));
	END IF;
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(transactionkey) AS counter FROM invoiceheader as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE 1=1  ",table_where);
    PREPARE s1 FROM @dyn_cnt;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM invoiceheader as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.routecode
	LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE 1=1  ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    PREPARE s2 FROM @dyn_sql;	
	EXECUTE s2;
	select @dyn_sql;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_salesorder` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_salesorder` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_salesorder`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'transactionkey';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	IF table_where = '' THEN
		SET table_where = CONCAT(' AND transactiondate =  ',DATE(CURRENT_DATE()));
	END IF;
    
	SET @dyn_cnt = CONCAT("SELECT COUNT(DISTINCT transactionkey) AS counter FROM  usermaster as um 
							INNER JOIN (SELECT DISTINCT cmpycode, username FROM useraccesscodes) as uac ON uac.username= um.username
							INNER JOIN (SELECT DISTINCT routecode, cmpycode, routename FROM routemaster) as rm ON rm.cmpycode = uac.cmpycode
							INNER JOIN salesorderheader AS ih ON ih.routecode = rm.routecode
							LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
							LEFT JOIN customermaster as cm on cm.customercode = ih.customercode
	WHERE 1=1  ",table_where);
    PREPARE s1 FROM @dyn_cnt;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT  DISTINCT  ", table_fields ,"  FROM  usermaster as um 
							INNER JOIN (SELECT DISTINCT cmpycode, username FROM useraccesscodes) as uac ON uac.username= um.username
							INNER JOIN (SELECT DISTINCT routecode, cmpycode, routename FROM routemaster) as rm ON rm.cmpycode = uac.cmpycode
							INNER JOIN (SELECT DISTINCT salesorderheader.* FROM salesorderheader) as ih ON ih.routecode = rm.routecode
							LEFT JOIN salesman as sm on sm.salesmancode = ih.salesmancode	
							LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
					 WHERE 1=1   ",table_where,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	-- select @dyn_sql;
   PREPARE s2 FROM @dyn_sql;	
	 EXECUTE s2;	
	 select @dyn_sql;
	
END */$$
DELIMITER ;

