/* Procedure structure for procedure `sp_get_transaction_index_salesorderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_salesorderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_salesorderheader`(
	IN id INT
    )
BEGIN
	
	CALL sp_combo_routemaster();
	-- For Header
	SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ih.routecode,ih.salesmancode,ih.*,
		cm.customeraddress1,cm.customername,sm.salesmanname1 AS salesmanname ,signaturedata,
		DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate
		FROM salesorderheader AS ih
		LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
		LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode	
		-- LEFT JOIN sigcapturedata AS sn ON sn.customercode = ih.customercode 
		LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
		LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
	WHERE ih.transactionkey = id;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_splitsalesorderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_splitsalesorderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_splitsalesorderheader`(
	IN id INT
    )
BEGIN
	
	CALL sp_combo_routemaster_splitsalesorder();
	-- CALL sp_combo_routemaster();
	-- For Header
	SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ih.routecode,ih.salesmancode,ih.*,
		cm.customeraddress1,cm.customername,sm.salesmanname1 AS salesmanname ,signaturedata,
		DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate
		FROM salesorderheader AS ih
		LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
		LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode	
		-- LEFT JOIN sigcapturedata AS sn ON sn.customercode = ih.customercode 
		LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
		LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
	WHERE ih.transactionkey = id;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_splitsalesorder_report` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_splitsalesorder_report` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_splitsalesorder_report`(
    IN var_transactionkey INT
    )
BEGIN
        IF var_transactionkey > 0 THEN
 SELECT  routekey INTO @routekey FROM salesorderheader AS ih WHERE ih.transactionkey  = var_transactionkey;
		SELECT payment_mode(cm.invoicepaymentterms) AS paymentterm,ih.routecode,cm.customeraddress1,cm.customername,sm.salesmanname1 AS salesmanname ,signaturedata,
			DATE_FORMAT(ed.routestartdate,'%d-%m-%Y') AS routestartdate,DATE_FORMAT(ih.transactiondate,'%d-%m-%Y') AS transactiondate,
DATE_FORMAT(ih.orderdeliverydate,'%d-%m-%Y') AS orderdeliverydate,ih.*,rm.routename as deliveryroute
		FROM salesorderheader AS ih
		LEFT JOIN salesman AS sm ON sm.salesmancode = ih.salesmancode
		LEFT JOIN routemaster as rm on rm.routecode = ih.orderdeliveryroutecode
		LEFT JOIN customermaster AS cm ON cm.customercode = ih.customercode	
		LEFT JOIN sigcapturedata AS sn ON sn.routekey = ih.routekey AND sn.visitkey = ih.visitkey
		LEFT JOIN startendday AS ed ON ed.routekey = ih.routekey    
	WHERE ih.transactionkey = var_transactionkey;
	
	
	
	
		SELECT im.alternatecode, im.itemshortdescription, im.unitspercase, dp.quantity AS depostock, im.division, id.salesqty AS pcs_sales_qty, id.freesampleqty AS pcs_foc_qty, 
 FORMAT(id.salesprice,3) AS salesprice, FORMAT(((((id.salesqty DIV im.unitspercase)*id.salescaseprice)+((id.salesqty%im.unitspercase)*id.salesprice))-id.promoamount),3) AS total_amount, id.primary_key AS edit_del_primary_id 
FROM salesorderdetail AS id
	LEFT JOIN itemmaster AS im ON im.actualitemcode = id.itemcode	
	LEFT JOIN depotstock AS dp ON dp.itemcode = id.itemcode
	WHERE 1=1  AND (id.processedflag = 0 OR id.processedflag = 2) AND routekey = @routekey  AND  transactionkey = var_transactionkey ORDER BY id.primary_key DESC;
        END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_get_transaction_index_splittedsalesorder` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_transaction_index_splittedsalesorder` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_transaction_index_splittedsalesorder`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500), 		
	IN order_by VARCHAR(500),		
	IN order_type VARCHAR(10),		
	IN lmt_strt INT,				
	IN lmt_end INT, 				
	IN table_fields TEXT, 			
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	
	IF order_by = '' THEN
		SET order_by = 'deliveryno';
	END IF;
	
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	
	IF table_fields = '' THEN
		SET table_fields = 'ih.*';
	END IF;
	
	IF table_where = '' THEN
		SET table_where = CONCAT(' AND transactiondate =  ',DATE(CURRENT_DATE()));
	END IF;
    
    SELECT invoicenumber INTO @invnumber FROM salesorderheader WHERE transactionkey = table_where ;
    
    
    -- SELECT @invnumber;
	-- SELECT order_by;
	-- SELECT lmt_strt;
	-- SELECT lmt_end;
	SET @dyn_cnt = CONCAT("SELECT COUNT(deliveryno) AS counter FROM deliveryheader as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.deliveryroute 	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE canceled=0   and orderno=", @invnumber);
    PREPARE s1 FROM @dyn_cnt;	
	EXECUTE s1;	
	
	SET @dyn_sql = CONCAT("SELECT ", table_fields ," FROM deliveryheader as ih 
	LEFT JOIN routemaster as rm on rm.routecode = ih.deliveryroute 	
	LEFT JOIN customermaster as cm on cm.customercode = ih.customercode	
	WHERE canceled=0  and orderno=", @invnumber,  " ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
	
   PREPARE s2 FROM @dyn_sql;	
	 EXECUTE s2;	
	
END */$$
DELIMITER ;

