/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_user_and_usertype`(
					IN usertype BIGINT
					)
BEGIN
	IF usertype = 1 THEN 
		select um.userid as id, concat(um.userid, " --- ", um.username) as val from usermaster as um order by userid asc;
