/* Procedure structure for procedure `sp_get_year` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_get_year` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_get_year`(
IN form VARCHAR(50)
)
BEGIN
	IF form = 'ACCOUNT' THEN
		SELECT DISTINCT(YEAR(transactiondate)) AS cur_year FROM customerinvoice ORDER BY 1 DESC;
		
	ELSEIF form = 'DATA' THEN
		SELECT DISTINCT(YEAR(routestartdate)) AS cur_year FROM startendday ORDER BY 1 DESC;	
	END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_hhctransaction_cloudtran_addprocessload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_hhctransaction_cloudtran_addprocessload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_hhctransaction_cloudtran_addprocessload`()
BEGIN
	SELECT routecode AS id, CONCAT(routecode,' -- ',routename) AS val FROM routemaster 
	WHERE 
		activestatus = '1' 
		AND routetmpl = 0 
		AND   
		routecode IN (
				SELECT startendday.routecode FROM startendday WHERE
					--- DATE(startendday.routestartdate) = CURRENT_DATE() AND
					startendday.routeclosed =0
					AND startendday.triptype = 1
					GROUP BY startendday.routecode
			     );
    
    
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_get_columnnames_temporarytable` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_get_columnnames_temporarytable` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_get_columnnames_temporarytable`(
	IN tablenamevalue TEXT
    )
BEGIN
	IF tablenamevalue = 'temp_customermaster' THEN 
		SELECT "temp_customermaster" AS tablename;
		SHOW COLUMNS FROM temp_customermaster;		
	
	ELSEIF tablenamevalue = 'temp_routegoal' THEN 
	 	SELECT "temp_routegoal" AS tablename;
	 	SHOW COLUMNS FROM temp_routegoal;
	 	
	ELSEIF tablenamevalue = 'temp_routesequence' THEN 
		SELECT "temp_routesequence" AS tablename;
		SHOW COLUMNS FROM temp_routesequence;	
	
	ELSEIF tablenamevalue = 'temp_loadrequest' THEN 
		SELECT "temp_loadrequest" AS tablename;
		SHOW COLUMNS FROM temp_loadrequest;
	
	ELSEIF tablenamevalue = 'temp_freecontract' THEN 
		SELECT "temp_freecontract" AS tablename;
		SHOW COLUMNS FROM temp_freecontract;
			
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_import_post_maintable_fromtemptable` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_import_post_maintable_fromtemptable` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_import_post_maintable_fromtemptable`(
	IN tablenamevalue TEXT
    )
BEGIN
	IF tablenamevalue = 'temp_customermaster' THEN 
		CALL sp_post_customers_fromtemptable();
			
	ELSEIF tablenamevalue = 'temp_routegoal' THEN 
		CALL sp_post_routegoal();
		
	ELSEIF tablenamevalue = 'temp_routesequence' THEN 
		CALL sp_post_routesequence();
	
	ELSEIF tablenamevalue = 'temp_loadrequest' THEN 
		CALL sp_post_loadrequest();
	
	ELSEIF tablenamevalue = 'temp_freecontract' THEN 
		CALL sp_post_freecontract_header(); 
		CALL sp_post_freecontract_detail();
		DELETE FROM `temp_freecontract`;
				
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_advance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_advance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_advance`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND ar.routecode IN (", var_routecode, ")");   
	END IF;
	   
	SET @dyn_sql = CONCAT("
		SELECT ar.transactiondate TransactionDate, ar.routecode RouteCode, rm.routename Route,
			sm.salesmanname1 Salesman, ar.invoicenumber ReceiptNo, cm.alternatecode CustomerCode, 
			cm.customername Customer, ar.amountpaid AmounPaid,
			CASE WHEN ccd.typecode =0 THEN 'CASH' ELSE 'CHEQUE' END Mop, 
			CASE WHEN ccd.typecode =0 THEN '' ELSE ccd.checknumber END ChequeNo,
			CASE WHEN ccd.typecode =0 THEN '' ELSE DATE_FORMAT(ccd.checkdate,'%Y-%m-%d') END ChequeDate,
			ar.comments
		FROM arheader ar
			INNER JOIN customermaster cm ON cm.customercode = ar.customercode
			INNER JOIN routemaster rm ON rm.routecode = ar.routecode
			INNER JOIN salesman sm ON sm.salesmancode = ar.salesmancode
			INNER JOIN cashcheckdetail ccd ON ccd.routekey = ar.routekey AND ccd.visitkey = ar.visitkey
		WHERE ar.voidflag=0 AND ar.advancepaymentflag = 1 AND 
			(DATE_FORMAT(ar.transactiondate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"') ", cond_routecode, " 
		ORDER BY ar.transactiondate, ar.routecode, ar.invoicenumber");
	 
	-- SELECT @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_appversion` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_appversion` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_appversion`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT rm.routecode RouteCode, rm.routename RouteName, sm.alternatesalesmancode SalesmanCode, 
			sm.salesmanname1 SalesmanName, 
			DATE_FORMAT(sed.routestartdate,'%d-%m-%Y') TripStartDate,
			DATE_FORMAT(sed.routeenddate,'%d-%m-%Y') TripEndDate, 
			sed.versionno AppVersionNo,
			sed.dataconrefnumber DeviceID
		FROM startendday sed
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode
			INNER JOIN salesman sm ON sm.salesmancode = sed.salesmancode
		WHERE routekey IN (SELECT MAX(sed1.routekey) FROM startendday sed1 GROUP BY sed1.routecode)");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_collections` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_collections` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_collections`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND ar.routecode IN (", var_routecode, ")");   
	END IF;
	   
	SET @dyn_sql = CONCAT("
		SELECT ar.transactiondate ReceiptDate, ar.routecode Route, sm.alternatesalesmancode Salesman, ar.invoicenumber ReceiptNo, 
				cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername Customer, ar.totalinvoiceamount ReceiptAmount,
				ard.invoicenumber ClearedInvoiceNo, ard.alternateinvoicenumber ReferenceInvoiceNo, ard.amountpaid ClearedAmount,
				CASE WHEN ccd.typecode =0 THEN 'CASH' ELSE 'CHEQUE' END Mop, 
				CASE WHEN ccd.typecode =0 THEN '' ELSE ccd.checknumber END ChequeNo,
				CASE WHEN ccd.typecode =0 THEN '' ELSE DATE_FORMAT(ccd.checkdate,'%Y-%m-%d') END ChequeDate
		FROM arheader ar
				INNER JOIN salesman sm ON sm.salesmancode = ar.salesmancode
				INNER JOIN customermaster cm ON cm.customercode = ar.customercode
				INNER JOIN ardetail ard ON ard.transactionkey = ar.transactionkey AND ar.voidflag = 0
				INNER JOIN cashcheckdetail ccd ON ccd.routekey = ar.routekey AND ccd.visitkey = ar.visitkey
		WHERE (DATE_FORMAT(ar.transactiondate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"') ", cond_routecode, " 
		ORDER BY ar.transactiondate, ar.routecode, ar.invoicenumber");
	 
	-- SELECT @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_customer_inventory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_customer_inventory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_customer_inventory`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND coc.routecode IN (", var_routecode, ")");   
	END IF;
	
	SET @dyn_sql = CONCAT("
	SELECT rm.routecode RouteCode, rm.routename Route, coc.salesmancode Salesman,
		DATE_FORMAT(coc.visitstartdate,'%d-%m-%Y') VisitDate, 
		cm.alternatecode CustomerCode, cm.customername Customer, 
		im.alternatecode Itemcode, im.itemdescription ItemName, im.unitspercase UPC, (cid.qtyloc1each + cid.qtyloc2each) ShelfQty
	FROM customeroperationscontrol coc
		INNER JOIN routemaster rm ON rm.routecode = coc.routecode
		INNER JOIN customermaster cm ON cm.customercode = coc.customercode
		INNER JOIN customerinventorydetail cid ON cid.routekey = coc.routekey AND cid.visitkey = coc.visitkey
		INNER JOIN itemmaster im ON im.actualitemcode = cid.itemcode		
	WHERE DATE_FORMAT(coc.visitstartdate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"' ", cond_routecode, " 
	ORDER BY 1, 2, 3, 5");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_distributionandsales` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_distributionandsales` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_distributionandsales`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND routecode IN (", var_routecode, ")");   
	END IF;
	SET @time = CONCAT("temp_",REPLACE(CURTIME(),":",""));
	SET @coc = CONCAT("dist_coc_",@time);
	SET @distribute = CONCAT("dist_sub_",@time);
	SET @distributemain = CONCAT("dist_main_",@time);
			
	SET @temptable =  CONCAT("CREATE TABLE IF NOT EXISTS ", @coc," AS 
		SELECT routekey, visitkey, customercode, routecode, salesmancode, visitstartdate
		FROM customeroperationscontrol 
		WHERE DATE_FORMAT(visitstartdate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate , "' ", cond_routecode, " ");
	PREPARE qry1 FROM @temptable;
	EXECUTE qry1;
	
	SET @temptable =  CONCAT("CREATE TABLE IF NOT EXISTS ", @distribute, " AS 
		SELECT coc.routecode, coc.salesmancode, coc.visitstartdate, coc.customercode, coc.routekey, coc.visitkey, 
			rim.itemcode, im.alternatecode, im.itemdescription,
			SUM(COALESCE(ci.qtyloc1each,0)) invqty, 0 saleqty
		FROM ", @coc ," coc 			
			INNER JOIN routemaster rm ON rm.routecode = coc.routecode 
			INNER JOIN itemmustdetail rim ON rim.itemmustcode = rm.itemmustkey AND rim.active=1	
			INNER JOIN itemmaster im ON im.actualitemcode = rim.itemcode
			LEFT OUTER JOIN customerinventorydetail ci ON coc.routekey = ci.routekey AND coc.visitkey = ci.visitkey AND ci.itemcode = rim.itemcode	
		GROUP BY coc.routekey, coc.visitkey, rim.itemcode");
	PREPARE qry2 FROM @temptable;
	EXECUTE qry2;
	
	SET @temptable =  CONCAT("INSERT INTO ", @distribute, " 
		SELECT ih.routecode, ih.salesmancode, ih.transactiondate, ih.customercode, ih.routekey, ih.visitkey, 
			rim.itemcode, im.alternatecode, im.itemdescription,
			0 invqty, (salesqty - returnqty + freesampleqty) saleqty
		FROM invoiceheader ih 										
			INNER JOIN routemaster rm ON rm.routecode = ih.routecode 
			INNER JOIN itemmustdetail rim ON rim.itemmustcode = rm.itemmustkey AND rim.active=1		
			INNER JOIN itemmaster im ON im.actualitemcode = rim.itemcode			
			LEFT OUTER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND id.itemcode = rim.itemcode
		WHERE transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate , "'
		GROUP BY ih.routekey, ih.visitkey, rim.itemcode");
	PREPARE qry3 FROM @temptable;
	EXECUTE qry3;
	
	SET @temptable =  CONCAT("CREATE TABLE IF NOT EXISTS ", @distributemain, " 
		SELECT routecode, salesmancode, visitstartdate, customercode, routekey, visitkey, 
			itemcode, alternatecode, itemdescription,
			SUM(invqty) invqty, SUM(saleqty) saleqty
		FROM ", @distribute ," 
		GROUP BY routekey, customercode, itemcode");
	PREPARE qry3 FROM @temptable;
	EXECUTE qry3;	
	
	SET @dyn_sql = CONCAT("
	SELECT DATE_FORMAT(dist.visitstartdate,'%d-%m-%Y') VisitDate, dist.routecode Route, dist.salesmancode Salesman,  
		cm.alternatecode CustomerCode, cm.customername CustomerName, 
		dist.alternatecode ItemCode, dist.itemdescription Item, 
		dist.invqty InventoryQuantity, dist.saleqty SalesQuantity
	FROM ", @distributemain ," dist 
		INNER JOIN customermaster cm ON cm.customercode = dist.customercode
	");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
	SET @coctemp = CONCAT("DROP TABLE IF EXISTS ",@coc);
	PREPARE qry1 FROM @coctemp ;
	EXECUTE qry1;
	
	SET @disttemp = CONCAT("DROP TABLE IF EXISTS ",@distribute);
	PREPARE qry1 FROM @disttemp ;
	EXECUTE qry1;
	
	SET @disttemp = CONCAT("DROP TABLE IF EXISTS ",@distributemain);
	PREPARE qry1 FROM @disttemp ;
	EXECUTE qry1;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_distribution_check` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_distribution_check` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_distribution_check`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND coc.routecode IN (", var_routecode, ")");   
	END IF;
	
	SET @dyn_sql = CONCAT("
		SELECT coc.routecode Route, coc.salesmancode Salesman, DATE_FORMAT(coc.visitstartdate,'%d-%m-%Y') VisitDate, 
			cm.alternatecode CustomerCode, cm.customername CustomerName, 
			im.alternatecode ItemCode, im.itemdescription Item, 
			cic.qtyloc1each Quantity, DATE_FORMAT(cic.expiry_date,'%d-%m-%Y') Expiry
	FROM customeroperationscontrol coc 
			INNER JOIN customerinventorycheck cic ON cic.routekey = coc.routekey AND cic.visitkey = coc.visitkey ", cond_routecode, " 
			INNER JOIN itemmaster im ON im.actualitemcode = cic.itemcode
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
	WHERE DATE_FORMAT(coc.visitstartdate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"'
	ORDER BY  coc.routecode, DATE_FORMAT(coc.visitstartdate,'%Y-%m-%d') , cm.alternatecode, im.alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_geocodes` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_geocodes` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_geocodes`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	   
	SET @dyn_sql = CONCAT("
		SELECT alternatecode CustomerCode, customercode CustomerID, customername CustomerName,	
			customeraddress1 Address,
			CASE WHEN invoicepaymentterms < 2 THEN 'CASH' WHEN invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END PaymentType, 
			fixedlatitude Latitude, fixedlongitude Longitude
		FROM customermaster 
		WHERE fixedlatitude > 0
		ORDER BY alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_geocodes_history` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_geocodes_history` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_geocodes_history`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	   
	SET @dyn_sql = CONCAT("
		SELECT DISTINCT co.routecode Route, co.salesmancode SalesmanID, s.alternatesalesmancode SalesmanCode, s.salesmanname1 Salesman, 
			co.customercode CustomerId, cm.alternatecode CustomerCode, cm.customername Customer, 
			co.latitude Latitude, co.longitude Longitude, DATE_FORMAT(co.visitstartdate,'%Y-%m-%d') VisitDate
		FROM customeroperationscontrol co
			INNER JOIN customermaster cm ON co.customercode=cm.customercode
			INNER JOIN salesman s ON co.salesmancode=s.salesmancode
		WHERE DATE_FORMAT(co.visitstartdate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
		ORDER BY s.alternatesalesmancode, cm.alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_integritycheck` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_integritycheck` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_integritycheck`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT `date` LogDate, `time` LogTime, errorcode ErrorCode, description Description, remarks Details
		FROM intexperrorlogs
		WHERE errorcode > 0 AND date = '", var_fromdate ,"' AND description NOT LIKE '%ORA-00001: unique constraint (ROUTEPRO.%'");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_otp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_otp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_otp`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	-- SET @dyn_sql = CONCAT("
	-- 	SELECT DISTINCT 
	-- 	aoc.routecode Route,cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName, 
	-- CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END PaymentType, 
	-- cm.creditlimit CreditLimit, cm.creditlimitdays CreditDays,
	-- CASE WHEN aoc.type = 1 THEN 'Journey Plan' WHEN aoc.type = 2 THEN 'GPS' WHEN aoc.type = 3 THEN 'Void' WHEN aoc.type = 4 THEN 'Returns' WHEN aoc.type = 5 THEN 'CreditLimit' WHEN aoc.type = 6 THEN 'CreditDays' ELSE '' END OTPFor,
	-- cm.fixedlatitude MasterLatitude, cm.fixedlongitude MasterLongitude, 
	-- COALESCE(coc.latitude,0) VisitLatitude,COALESCE(coc.longitude,0) VisitLongitude,
	-- CASE WHEN (coc.latitude+coc.longitude) = 0 THEN 0 WHEN (cm.fixedlatitude+cm.fixedlongitude) = 0 THEN 0 ELSE
	-- COALESCE((((ACOS(SIN((coc.latitude*PI()/180)) * SIN((cm.fixedlatitude*PI()/180))+COS((coc.latitude*PI()/180)) * 
	-- COS((cm.fixedlatitude*PI()/180)) * COS(((coc.longitude-cm.fixedlongitude)* PI()/180))))*180/PI())*60*1.1515) * 1.609344,0) END AS 'Difference (Kms)'
	-- FROM t_access_override_log aoc
	-- LEFT OUTER JOIN (SELECT coc.routekey, coc.customercode, coc.latitude, coc.longitude
	-- FROM customeroperationscontrol coc 
	-- GROUP BY coc.routekey, coc.customercode) AS coc ON coc.routekey = aoc.routekey AND coc.customercode = aoc.customercode
	-- INNER JOIN customermaster cm ON cm.customercode = aoc.customercode
	-- INNER JOIN routemaster rm ON rm.routecode = aoc.routecode
	-- WHERE DATE_FORMAT(aoc.accesstime,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
	-- ORDER BY aoc.routecode, aoc.customercode");
	SET @dyn_sql = CONCAT("
		SELECT DISTINCT 
	           DATE_FORMAT(aoc.accesstime,'%d-%m-%Y') TranDate,
		   rm.routecode RouteCode, sm.alternatesalesmancode SalesmanCode, sm.salesmanname1 SalesmanName,
		   cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName, 
		   CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END PaymentType, 
		   cm.creditlimit CreditLimit, cm.creditlimitdays CreditDays,
		   CASE WHEN aoc.featureid = 1 THEN 'GPS' WHEN aoc.featureid = 2 THEN 'JourneyPlan' 
			WHEN aoc.featureid = 6 THEN 'Returns' WHEN aoc.featureid = 4 THEN 'CreditLimit' WHEN aoc.featureid = 5 THEN 'CreditDays' ELSE '' END OTPUsedFor		   
		FROM t_access_override_log aoc
		   INNER JOIN customermaster cm ON cm.customercode = aoc.customercode
		   INNER JOIN routemaster rm ON rm.routecode = aoc.routecode
		   INNER JOIN salesman sm ON sm.salesmancode = aoc.salesmancode
		WHERE DATE_FORMAT(aoc.accesstime,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
		ORDER BY aoc.routecode, aoc.customercode");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
