/* Procedure structure for procedure `sp_otherreport_pdc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_pdc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_pdc`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND ar.routecode IN (", var_routecode, ")");   
	END IF;
	SET cond_routecode = '';	
	
	SET @dyn_sql = CONCAT("
		SELECT DATE_FORMAT(ar.transactiondate,'%d-%m-%Y') ReceiptDate, ar.routecode Route, sm.alternatesalesmancode SalesmanCode, sm.salesmanname1 SalesmanName, sam.subareaname Area,
				ar.invoicenumber ReceiptNo, cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername Customer, ar.totalinvoiceamount ReceiptAmount,
				ard.invoicenumber ClearedInvoiceNo, ard.alternateinvoicenumber ReferenceInvoiceNo, ard.amountpaid ClearedAmount,
				CASE WHEN ccd.typecode =0 THEN 'CASH' ELSE 'CHEQUE' END Mop, 
				CASE WHEN ccd.typecode =0 THEN '' ELSE ccd.checknumber END ChequeNo,
				CASE WHEN ccd.typecode =0 THEN '' ELSE DATE_FORMAT(ccd.checkdate,'%d-%m-%Y') END ChequeDate
		FROM arheader ar
				INNER JOIN salesman sm ON sm.salesmancode = ar.salesmancode
				INNER JOIN routemaster rm ON rm.routecode = ar.routecode
				INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
				INNER JOIN customermaster cm ON cm.customercode = ar.customercode
				INNER JOIN ardetail ard ON ard.transactionkey = ar.transactionkey AND ar.voidflag = 0
				INNER JOIN cashcheckdetail ccd ON ccd.routekey = ar.routekey AND ccd.visitkey = ar.visitkey AND ccd.typecode = 1
		WHERE DATE_FORMAT(ccd.checkdate,'%Y-%m-%d') > CURDATE() 
		ORDER BY ar.transactiondate, ar.routecode, ar.invoicenumber");
		
	-- WHERE (DATE_FORMAT(ar.transactiondate,'%Y-%m-%d') BETWEEN '", var_fromdate , "' AND '", var_todate ,"') ", cond_routecode, " 
	 
	-- SELECT @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_productivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_productivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_productivity`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND coc.routecode IN (", var_routecode, ")");   
	END IF;
	   
	SET @dyn_sql = CONCAT("
		SELECT DISTINCT DATE_FORMAT(coc.visitstartdate,'%d-%m-%Y')  `VisitDate`, coc.routecode `RouteCode`, rm.routename `Route`, sm.salesmanname1 `Salesman`, 
			cm.ancustomercode `CustomerCode`, cm.customername `Customer`, 
			COALESCE(ih.salesamount,0) Sales, COALESCE(ar.aramount, 0) Receipt, COALESCE(so.orderamount, 0) SalesOrder, COALESCE(ns.nosale,'') NoTransaction
		FROM customeroperationscontrol coc
			INNER JOIN routemaster rm ON rm.routecode = coc.routecode
			INNER JOIN salesman sm ON sm.salesmancode=coc.salesmancode
			INNER JOIN customermaster cm ON cm.customercode = coc.customercode
			LEFT OUTER JOIN (SELECT routekey, customercode, SUM(totalinvoiceamount) salesamount FROM invoiceheader GROUP BY routekey, customercode) ih ON ih.routekey = coc.routekey AND ih.customercode = coc.customercode
			LEFT OUTER JOIN (SELECT routekey, customercode, SUM(totalinvoiceamount) aramount FROM arheader GROUP BY routekey, customercode) ar ON ar.routekey = coc.routekey AND ar.customercode = coc.customercode
			LEFT OUTER JOIN (SELECT routekey, customercode, SUM(totalinvoiceamount) orderamount FROM salesorderheader GROUP BY routekey, customercode) so ON so.routekey = coc.routekey AND so.customercode = coc.customercode
			LEFT OUTER JOIN (SELECT CODE, description nosale FROM nonservreasons) ns ON ns.code = coc.reasoncode
		WHERE coc.visitstartdate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' ", cond_routecode, " 
		ORDER BY coc.visitstartdate, coc.routecode, cm.ancustomercode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_running_promotions` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_running_promotions` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_running_promotions`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	   
	SET @dyn_sql = CONCAT("
		SELECT pkd.plannumber PromoPlan, pph.plandescription Description, 
			DATE_FORMAT(pkd.startdate,'%Y-%m-%d') StartDate, DATE_FORMAT(pkd.enddate,'%Y-%m-%d') EndDate, 
			pgh.groupnumber GroupNo, im.itemdescription Item, im.defaultsalesprice SalesPrice,
			pa.rangelow RangeLow, pa.rangehigh RangeHigh, CASE pa.repeatingrange WHEN 0 THEN 'NO' ELSE 'YES' END RepeatRange, 
			pa.promotionamount PromoValue
		FROM promokeydetail pkd
				INNER JOIN promoplanheader pph ON pph.plannumber = pkd.plannumber
				INNER JOIN productgroupheader pgh ON pgh.groupnumber = pkd.qualificationgroup
				INNER JOIN productgroupdetail pgd ON pgd.groupnumber = pgh.groupnumber
				INNER JOIN itemmaster im ON im.actualitemcode = pgd.itemcode
				INNER JOIN promotionassignmentadvanced pa ON pa.assignmentnumber = pkd.assignmentnumber
		WHERE DATE_FORMAT(pkd.enddate,'%Y-%m-%d') >= CURDATE()");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_sales_summary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_sales_summary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_sales_summary`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND ih.routecode IN (", var_routecode, ")");   
	END IF;
	SET cond_routecode = '';	
	
	SET @dyn_sql = CONCAT("
	SELECT
		DATE_FORMAT(ih.transactiondate,'%d-%b-%Y') AS InvoiceDate, ih.transactiontime `Time`, ih.invoicenumber InvoiceNo,	
		cm.alternatecode CustomerCode, cm.customername CustomerName, 
		rm.routecode RouteCode, rm.routename Route, ih.salesmancode SalesmanID, sm.salesmanname1 Salesman,
		CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS MOP,
		ih.totalinvoiceamount AS IvoiceAmount, ih.amountpaid AmountPaid, ih.invoicebalance InvoiceBalance
	FROM
		invoiceheader ih
		INNER JOIN customermaster cm ON cm.customercode = ih.customercode
		INNER JOIN routemaster rm ON rm.routecode = ih.routecode
		INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
	WHERE
		ih.voidflag = 0 AND ih.transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' ", cond_routecode);
			 
	-- SELECT @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_unprocessed_load` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_unprocessed_load` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_unprocessed_load`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	
	DROP TABLE IF EXISTS tmp_load;
	CREATE TABLE tmp_load AS 
		SELECT DISTINCT loadnumber FROM inventorytransactionheader WHERE transactiontype = 1 AND loadnumber > 0 AND transactiondate BETWEEN var_fromdate AND var_todate;
	 
	SELECT DISTINCT sld.routecode Route, sld.salesmancode Salesman, sld.ddate LoadDate, sld.loadperiodnumber LoadNo, sld.erpreferencenumber LoadRefNom, ldc.loadnumber ProcessedNo
	FROM startingloaddetail_backup sld
		LEFT OUTER JOIN tmp_load ldc ON ldc.loadnumber = sld.loadperiodnumber
	WHERE ldc.loadnumber IS NULL AND sld.ddate BETWEEN var_fromdate AND var_todate
	
	UNION
	
	SELECT DISTINCT sld.routecode Route, sld.salesmancode Salesman, sld.ddate LoadDate, sld.loadperiodnumber LoadNo, sld.erpreferencenumber LoadRefNo, ldc.loadnumber ProcessedNo
	FROM startingloaddetail sld
		LEFT OUTER JOIN tmp_load ldc ON ldc.loadnumber = sld.loadperiodnumber
	WHERE ldc.loadnumber IS NULL AND sld.ddate BETWEEN var_fromdate AND var_todate;  
	
	DROP TABLE IF EXISTS tmp_load;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_vanstock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_vanstock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_vanstock`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
		
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';
	ELSE 
		SET cond_routecode = CONCAT("AND sed.routecode IN (", var_routecode, ")"); 
	END IF;
	
	
	SET @dyn_sql = CONCAT("
	SELECT DATE_FORMAT(COALESCE(sed.routeenddate,CURDATE()),'%d-%m-%Y') StockDate, rm.routecode RouteCode, rm.routename Route, 
		im.actualitemcode `ItemID`, im.alternatecode `ItemCode`, im.itemdescription `Item`, im.unitspercase `UPC`,
		 isd.vanstock `StockPCS`,CONCAT(FLOOR(isd.vanstock/im.unitspercase),'/', (isd.vanstock MOD im.unitspercase)) `Case/Pcs`
	FROM startendday sed
		INNER JOIN inventorysummarydetail isd ON isd.routekey = sed.routekey
		INNER JOIN itemmaster im ON im.actualitemcode = isd.itemcode
		INNER JOIN routemaster rm ON rm.routecode = sed.routecode
	WHERE COALESCE(sed.routeenddate,CURDATE()) = '", curdate(), "' ", cond_routecode, "
	ORDER BY 1,2,4");
	
	-- SELECT @dyn_sql;
	
	PREPARE s2 FROM @dyn_sql;
	EXECUTE s2;	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_vanstock_movement` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_vanstock_movement` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_vanstock_movement`(
IN var_routecode TEXT,
IN var_fromdate VARCHAR(20),
IN var_todate VARCHAR(20)
)
BEGIN
	DECLARE cond_routecode TEXT;
	SET @@group_concat_max_len = 32000;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND sed.routecode IN (", var_routecode, ")");   
	END IF;
	
	SET @tablename = CONCAT("temp_routekey");
	SET @dyn_sql = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS
		SELECT sed.routecode, MIN(sed.routekey) routekey
		FROM startendday sed
		WHERE sed.routestartdate BETWEEN '",var_fromdate, "' AND '", var_todate, "' ", cond_routecode, "
		GROUP BY sed.routecode");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
	SET @dyn_sql = CONCAT("			
		SELECT sed.routecode, rm.routename, 
			isd.itemcode ItemID, im.alternatecode ItemCode, im.itemdescription Item,
			COALESCE(opn.beginstockqty,0) `Opening`, SUM(isd.loadqty) `Loaded`, 
			SUM(isd.loadaddqty) `TransferIn`, SUM(isd.loadcutqty) `TransferOut`, 
			SUM(isd.saleqty) `Sales`, SUM(isd.freesampleqty) `Free`, SUM(isd.returnqty) `Return`,
			COALESCE(opn.beginstockqty,0) + SUM(isd.loadqty + isd.loadaddqty - isd.loadcutqty - isd.saleqty + isd.returnqty - isd.freesampleqty) `Closing`
		FROM startendday sed
			INNER JOIN inventorysummarydetail isd ON isd.routekey = sed.routekey
			LEFT OUTER JOIN (SELECT tk.routecode, isd.routekey, isd.itemcode, isd.beginstockqty 
				FROM ", @tablename, " tk
					INNER JOIN inventorysummarydetail isd on isd.routekey = tk.routekey) opn ON opn.routecode = sed.routecode AND opn.itemcode = isd.itemcode
			INNER JOIN itemmaster im ON im.actualitemcode = isd.itemcode
			INNER JOIN routemaster rm ON rm.routecode = sed.routecode AND rm.activestatus = 1
		WHERE sed.routestartdate BETWEEN '",var_fromdate, "' AND '", var_todate, "' ", cond_routecode, "
		GROUP BY sed.routecode, im.alternatecode  ");
	 PREPARE s2 FROM @dyn_sql;
	 EXECUTE s2;	
	 
	 SET @dyn_sql = CONCAT("DROP TABLE IF EXISTS ", @tablename, "");
	PREPARE s3 FROM @dyn_sql;
	EXECUTE s3;	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_vanstock_new` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_vanstock_new` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_vanstock_new`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
DECLARE cond_routecode TEXT;
		
IF var_routecode = 'All' THEN
	SET cond_routecode = '';
ELSE 
	SET cond_routecode = CONCAT("AND rm.routecode IN (", var_routecode, ")"); 
END IF;
	
DROP TABLE IF EXISTS tmp_items;
  CREATE TABLE tmp_items AS SELECT rm.routecode, map.itemcode, im.unitspercase, im.alternatecode FROM routemaster rm INNER JOIN routeitemmapping map ON map.routeitemgrpcode = rm.routeitemgrpcode INNER JOIN itemmaster im ON im.actualitemcode = map.itemcode;
DROP TABLE IF EXISTS tmp_route;
  CREATE TABLE tmp_route AS SELECT routecode, routename, salesmancode,activestatus FROM routemaster WHERE activestatus = 1 AND depotrouteflag=0 AND routecode IN (SELECT DISTINCT routecode FROM startendday);
DROP TABLE IF EXISTS tmp_lasttrip;
  CREATE TABLE tmp_lasttrip AS SELECT routecode, MAX(routekey) routekey FROM startendday WHERE routeclosed = 1 GROUP BY routecode;
DROP TABLE IF EXISTS tmp_presenttrip;
  CREATE TABLE tmp_presenttrip AS SELECT routecode, MAX(routekey) routekey FROM startendday WHERE routeclosed = 0 GROUP BY routecode;
SET @dyn_sql = CONCAT("   
SELECT CURDATE() SystemDate, rm.routecode Route, sm.alternatesalesmancode SalesmanCode, sm.salesmanname1 Salesman,
	im.alternatecode ItemCode, im.itemcode ItemID, 
	COALESCE(clos.ClosingQty, 0) Opening,
	COALESCE(lod.LoadQty, 0) Loaded, COALESCE(tout.OutQty, 0) TransferOut, COALESCE(tin.InQty, 0) TransferIn,
	COALESCE(sale.SalesQty, 0) Sales, COALESCE(sale.FreeQty, 0) + COALESCE(SUM(sale.mfreeqty), 0) Free, 
	COALESCE(sale.ReturnQty, 0) GReturn, COALESCE(sale.ReturnFreeQty, 0) GReturnFree,
	COALESCE(clos.ClosingQty, 0) + COALESCE(lod.LoadQty, 0) - COALESCE(tout.OutQty, 0) + COALESCE(tin.InQty, 0) - 
		COALESCE(sale.SalesQty, 0) - COALESCE(sale.FreeQty, 0)  - COALESCE(SUM(sale.mfreeqty), 0)+ COALESCE(sale.ReturnQty, 0) + COALESCE(sale.ReturnFreeQty, 0) VanStock
FROM tmp_route rm 
	INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode	
	INNER JOIN tmp_items im ON im.routecode = rm.routecode
	LEFT OUTER JOIN
		(SELECT sed.routecode, id.itemcode, SUM(id.quantity) ClosingQty
		FROM tmp_lasttrip sed 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 3 AND id.transactiontypecode = 5
		GROUP BY sed.routecode, id.itemcode) clos ON clos.routecode = rm.routecode AND clos.itemcode = im.itemcode	
	LEFT OUTER JOIN
		(SELECT sed1.routecode, id.itemcode, SUM(id.quantity) LoadQty
		FROM tmp_presenttrip sed1 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed1.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 1 AND id.transactiontypecode = 1
		GROUP BY sed1.routecode, id.itemcode) lod ON lod.routecode = rm.routecode AND lod.itemcode = im.itemcode
	LEFT OUTER JOIN
		(SELECT sed2.routecode, id.itemcode, SUM(id.quantity) OutQty
		FROM tmp_presenttrip sed2 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed2.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 2 AND id.transactiontypecode = 2
		GROUP BY sed2.routecode, id.itemcode) tout ON tout.routecode = rm.routecode AND tout.itemcode = im.itemcode
	LEFT OUTER JOIN
		(SELECT sed3.routecode, id.itemcode, SUM(id.quantity) InQty
		FROM tmp_presenttrip sed3 
			INNER JOIN inventorytransactionheader ih ON ih.routekey = sed3.routekey 
			INNER JOIN inventorytransactiondetail id ON id.detailkey = ih.detailkey AND ih.transactiontype = 2 AND id.transactiontypecode = 3
		GROUP BY sed3.routecode, id.itemcode) tin ON tin.routecode = rm.routecode AND tin.itemcode = im.itemcode
	LEFT OUTER JOIN
		(SELECT sed4.routecode, id.itemcode, SUM(id.salesqty) SalesQty, SUM(id.freesampleqty) FreeQty, SUM(id.manualfreeqty) mfreeqty, 
			SUM(id.returnqty) ReturnQty, SUM(id.returnfreeqty) ReturnFreeQty
		FROM tmp_presenttrip sed4 
			INNER JOIN invoiceheader ih ON ih.routekey = sed4.routekey 
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
		GROUP BY sed4.routecode, id.itemcode) sale ON sale.routecode = rm.routecode AND sale.itemcode = im.itemcode
WHERE 
	COALESCE(clos.ClosingQty, 0) + COALESCE(lod.LoadQty, 0) + COALESCE(tout.OutQty, 0) + COALESCE(tin.InQty, 0) + 
	COALESCE(sale.SalesQty, 0) + COALESCE(sale.FreeQty, 0) + COALESCE(sale.mfreeqty, 0) + COALESCE(sale.ReturnQty, 0) + COALESCE(sale.ReturnFreeQty, 0) > 0
	", cond_routecode, "
GROUP BY rm.routecode, im.itemcode 
ORDER BY rm.routecode, im.alternatecode");
PREPARE s2 FROM @dyn_sql;
EXECUTE s2;
	
DROP TABLE IF EXISTS tmp_items;
DROP TABLE IF EXISTS tmp_route;
DROP TABLE IF EXISTS tmp_lasttrip;
DROP TABLE IF EXISTS tmp_presenttrip;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_visitplan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_visitplan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_visitplan`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN
	DECLARE cond_routecode TEXT;
	
	IF var_routecode = 'All' THEN
		SET cond_routecode = '';	
	ELSE 
		SET cond_routecode = CONCAT("AND rs.routecode IN (", var_routecode, ")");   
	END IF;
	   
	SET @dyn_sql = CONCAT("
		SELECT rm.routecode RouteCode, rm.routename Route, rs.rp32weeknumber WeekNo, 
			cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName,	
			CASE WHEN rs.callrestrictiondays6 = 1 THEN 'YES' ELSE '' END Saturday,
			CASE WHEN rs.callrestrictiondays7 = 1 THEN 'YES' ELSE '' END Sunday,
			CASE WHEN rs.callrestrictiondays1 = 1 THEN 'YES' ELSE '' END Monday,
			CASE WHEN rs.callrestrictiondays2 = 1 THEN 'YES' ELSE '' END Tuesday,
			CASE WHEN rs.callrestrictiondays3 = 1 THEN 'YES' ELSE '' END Wednesday,
			CASE WHEN rs.callrestrictiondays4 = 1 THEN 'YES' ELSE '' END Thursday,
			CASE WHEN rs.callrestrictiondays5 = 1 THEN 'YES' ELSE '' END Friday,
			cm.fixedlatitude Latitude, cm.fixedlongitude Longitude
		FROM routesequence rs
			INNER JOIN customermaster cm ON cm.customercode = rs.customercode
			INNER JOIN routemaster rm ON rm.routecode = rs.routecode 
		WHERE rm.activestatus=1 ", cond_routecode, " 
		ORDER BY rm.routecode, rs.rp32weeknumber, cm.alternatecode");
	 
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_otherreport_void` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_otherreport_void` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_otherreport_void`(
IN var_routecode TEXT,
IN var_customercode TEXT,
IN var_itemcode TEXT,
IN var_fromdate VARCHAR(100),
IN var_todate VARCHAR(100),
IN var_groupby VARCHAR(100)
)
BEGIN	
	SET @dyn_sql = CONCAT("
		SELECT DATE_FORMAT(void.transactiondate,'%d-%m-%Y') TranDate, void.trantype Transaction, rm.routecode Route, 
		sm.alternatesalesmancode SalesmanCode, sm.salesmanname1 SalesmanName, 
		void.invoicenumber TransactionNo, 
		cm.customercode CustomerID, cm.alternatecode CustomerCode, cm.customername CustomerName, 
		void.totalinvoiceamount TransactionAmount
		FROM
			(
			SELECT 'SALES' trantype, transactiondate, routecode, salesmancode, invoicenumber, customercode, totalinvoiceamount
			FROM invoiceheader
			WHERE voidflag = 1 AND transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
			UNION
			SELECT 'COLLECTION' trantype, transactiondate, routecode, salesmancode, invoicenumber, customercode, totalinvoiceamount
			FROM arheader
			WHERE voidflag = 1 AND transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
			UNION
			SELECT 'ORDER' trantype, transactiondate, routecode, salesmancode, invoicenumber, customercode, totalinvoiceamount
			FROM salesorderheader
			WHERE voidflag = 1 AND transactiondate BETWEEN '", var_fromdate , "' AND '", var_todate ,"' 
			) void
			INNER JOIN routemaster rm on rm.routecode = void.routecode
			INNER JOIN salesman sm on sm.salesmancode = void.salesmancode
			INNER JOIN customermaster cm on cm.customercode = void.customercode
		ORDER BY void.transactiondate, void.trantype");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 -- SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_category_channel` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_category_channel` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_category_channel`()
BEGIN
	
	DECLARE Customercategory VARCHAR(50); 
	DECLARE Customerchannel VARCHAR(50); 
	
	DECLARE done INT DEFAULT FALSE;
	
	DECLARE cur_one CURSOR FOR 
		( SELECT DISTINCT customercategory, customerchannel FROM imp_customermaster );
		
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
					
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO Customercategory, Customerchannel;
		
		IF done = TRUE THEN
			LEAVE read_loop_one;
		END IF;
		
		-- insert to customercategory
		INSERT INTO channelmaster SET
			alternatecode = Customerchannel,
			channelname = Customerchannel,
			arbchannelname = Customerchannel,
			created = 'admin',
			cdat = CURDATE(),
			activestatus = 1
		ON DUPLICATE KEY UPDATE
			channelname = Customerchannel,
			arbchannelname = Customerchannel,
			modified = 'admin',
			mdat = CURDATE();
			
		-- insert to channelmaster
		INSERT INTO categorymaster SET 	
			alternatecode = Customercategory,
			categoryname = Customercategory,
			arbcategoryname = Customercategory,
			created = 'admin',
			cdat = CURDATE(),
			activestatus = 1
		ON DUPLICATE KEY UPDATE 
			categoryname = Customercategory,
			arbcategoryname = Customercategory,
			modified = 'admin',
			mdat = CURDATE();
		
		END LOOP read_loop_one;
	
	CLOSE cur_one;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_customers` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_customers` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_customers`()
BEGIN	
	SET @routecode = 0;
	SELECT MIN(routecode) routecode INTO @routecode  FROM routemaster;
	
	UPDATE customermaster SET alternatecode = CONCAT("INACTIVE-",customercode) WHERE customercode<85772;
	UPDATE customermaster SET alternatecode = CONCAT('XYZ.',customercode) WHERE customercode>=85772;
	UPDATE imp_customermaster SET pricingkey = 0 WHERE pricingkey = '';	
	DELETE FROM imp_customermaster WHERE customerreferenceno = '';
	
	SET @excepstarton = '2016-01-01 00:00:00';
	SET @excependon = '2016-01-01 00:00:00';
	
	INSERT INTO customermaster 
		(customercode, TYPE, headofficecode, routecode, customername, customeraddress1, customeraddress2, customeraddress3, customerphone, channelcode, customercategory, 
		pricingkey, invoicepaymentterms, invoiceformatoption, contactname, activecustomer, creditlimitdays, created, cdat, memo1, memo2, invoicepriceprint, enabledelayprint,
		printsequence, enablepriceeditinvs, enablesellprevious, enableautofillreturns, enableautofilldamaged, enablesigcapture, enablereturnstrxn, enableexchangetrxn,
		enabledamagedreturns, enablearcollection, enableinvoicecomment, forcestockcapture, enablepromotrxn, alternatecode, creditlimit, templateindicator, templatename,
		printlanguageflag, enablepromoeditinvs, enablesalestrxn, enableinvoicecopy, enableautofillsales, barcode, division, ancustomercode, arbcustomername,
		statementdays, promotionkey, graceperiod, enablereturnpassword,startdate,enddate, taxregistrationnumber, applytax, traname,hhccustomername)
		
	SELECT cm.customercode, 1 TYPE, cm.customercode headofficecode, @routecode routecode, REPLACE(cm.customername,"'","`") customername,  REPLACE(cm.customeraddress1,"'","`") customeraddress1, 
		REPLACE(cm.customeraddress2,"'","`") customeraddress2, REPLACE(cm.customeraddress3,"'","`") customeraddress3, cm.phonenumber, chm.channelcode, cat.categoryid, 
		CAST(cm.pricingkey AS UNSIGNED) pricingkey, cm.invoicepaymentterms, 2 invoiceformatoption, REPLACE(cm.contactname,"'","`") customeraddress1, cm.activestatus, 
		cm.creditlimitdays, 'admin', CURDATE(), REPLACE(cm.memo1,"'","`") memo1, REPLACE(cm.atribute2,"'","`") memo2, 1 invoicepriceprint, 1 enabledelayprint, 2 printsequence, 
		1 enablepriceeditinvs, 1 enablesellprevious, 1 enableautofillreturns, 1 enableautofilldamaged, 1 enablesigcapture, 3 enablereturnstrxn, 
		CASE WHEN cm.invoicepaymentterms = 2 THEN 0 ELSE 1 END enableexchangetrxn, 
		1 enabledamagedreturns, 
		CASE WHEN cm.invoicepaymentterms = 2 THEN 1 ELSE 0 END  enablearcollection, 1 enableinvoicecomment, 
		1 forcestockcapture, 3 enablepromotrxn, 
		-- CASE WHEN cm.reccount > 1 THEN CONCAT(cm.atribute1,'-',cm.reccount) ELSE cm.atribute1 END alternatecode, 
		CONCAT(cm.atribute1,'(',cm.customercode,')') alternatecode,
		cm.creditlimitamount, 0 templateindicator, cm.customerclass, 1 printlanguageflag, 1 enablepromoeditinvs, 1 enablesalestrxn, 1 enableinvoicecopy, 
		1 enableautofillsales, 
		-- CASE WHEN cm.reccount > 1 THEN CONCAT(cm.atribute1,'-',cm.reccount) ELSE cm.atribute1 END barcode, 
		CONCAT(cm.atribute1,'(',cm.customercode,')') barcode,
		0 division, cm.customerreferenceno ancustomercode, cm.arbcustomername,
		CASE WHEN cm.memo1 = 'MonthEnd' THEN 1 ELSE 0 END statementdays, 1 promotionkey,
		0 graceperiod, 1 enablereturnpassword, 
		CASE WHEN cm.credithold = 0 THEN curdate() ELSE @excepstarton END startdate,
		CASE WHEN cm.credithold = 0 THEN CURDATE() ELSE @excependon END enddate,		
		cm.atribute3 taxregistrationno, 
		CASE WHEN cm.atribute4 > 0 THEN 1 ELSE 0 END applytax,
		cm.atribute5, cm.atribute1
	FROM imp_customermaster cm
		LEFT OUTER JOIN categorymaster cat ON cat.alternatecode = cm.customercategory
		LEFT OUTER JOIN channelmaster chm ON chm.alternatecode = cm.customerchannel
	
		ON DUPLICATE KEY UPDATE 
			customermaster.customername = REPLACE(REPLACE(cm.customername,"'","`"),'  ',' '), 
			customermaster.arbcustomername = REPLACE(REPLACE(cm.arbcustomername,"'","`"),'  ',' '), 
			customermaster.customeraddress1 =  REPLACE(REPLACE(cm.customeraddress1,"'","`"),'  ',' '), 
			customermaster.customeraddress2 =  REPLACE(REPLACE(cm.customeraddress2,"'","`"),'  ',' '), 
			customermaster.customeraddress3 = REPLACE(REPLACE(cm.customeraddress3,"'","`"),'  ',' '), 
			customermaster.contactname = REPLACE(REPLACE(cm.contactname,"'","`"),'  ',' '), 
			-- customermaster.alternatecode = CASE WHEN cm.reccount > 1 THEN CONCAT(cm.atribute1,'-',cm.reccount) ELSE cm.atribute1 END,
			customermaster.alternatecode = CONCAT(cm.atribute1,'(',cm.customercode,')'),
			customermaster.hhccustomername = cm.atribute1,
			-- customermaster.barcode = CASE WHEN cm.reccount > 1 THEN CONCAT(cm.atribute1,'-',cm.reccount) ELSE cm.atribute1 END,
			customermaster.barcode = CONCAT(cm.atribute1,'(',cm.customercode,')'),
			customermaster.channelcode = chm.channelcode,
			customermaster.customercategory = cat.categoryid,
			customermaster.templatename = REPLACE(cm.customerclass,"'","`"),
			customermaster.pricingkey = cm.pricingkey,
			customermaster.enableexchangetrxn = CASE WHEN cm.invoicepaymentterms = 2 THEN 0 ELSE 1 END,
			customermaster.invoicepaymentterms = cm.invoicepaymentterms,
			customermaster.creditlimit = cm.creditlimitamount,
			customermaster.creditlimitdays = cm.creditlimitdays,
			customermaster.statementdays = CASE WHEN cm.memo1 = 'MonthEnd' THEN 1 ELSE 0 END,
			customermaster.enablesalestrxn = 1, -- cm.credithold,
			customermaster.memo1 = REPLACE(cm.memo1,"'","`"),
			customermaster.memo2 = REPLACE(cm.atribute2,"'","`"),
			customermaster.activecustomer = cm.activestatus,
			customermaster.modified = 'admin', 
			customermaster.mdat = CURDATE(),
			customermaster.enablearcollection = CASE WHEN cm.invoicepaymentterms = 2 THEN 1 ELSE 0 END,
			customermaster.graceperiod = CASE WHEN cm.invoicepaymentterms = 2 THEN 1 ELSE 0 END,
			customermaster.startdate = CASE WHEN cm.credithold = 0 THEN CURDATE() ELSE @excepstarton END,
			customermaster.enddate = CASE WHEN cm.credithold = 0 THEN CURDATE() ELSE @excependon END,
			customermaster.taxregistrationnumber = cm.atribute3,
			customermaster.applytax =  CASE WHEN cm.atribute4 > 0 THEN 1 ELSE 0 END,
			customermaster.traname = REPLACE(REPLACE(cm.atribute5,"'","`"),'  ',' ');
	
	-- Disabling Collection for EPPCO, EMARAT customers. Diabling collection will diable the downloading of Outstsning data.
	UPDATE customermaster SET enablearcollection = 0 WHERE alternatecode IN ('DA8683','DA11496','DE455','DE455-2');
	
	-- Enabling Exception for EPPCO, EMARAT customers. For other customers there wont be any exception.
	SET @excepstarton = '2016-01-01 01:01:01';
	SET @excependon = '2020-12-31 01:01:01';
	UPDATE customermaster SET startdate = @excepstarton, enddate = @excependon WHERE pricingkey IN
		(SELECT pricingplankey FROM customerpricingplanheader1 WHERE description IN ('P09','P17','P18') );
		
	UPDATE customermaster SET roundnetamount= 2, roundingoffvalue=2 WHERE invoicepaymentterms < 2;	
	
	UPDATE customermaster SET alternatecode=customercode WHERE alternatecode LIKE '%XYZ.%';
	
	UPDATE routesequence rs
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode AND cm.activecustomer=0
	SET rs.callrestrictiondays1 = 0, rs.callrestrictiondays2 = 0, rs.callrestrictiondays3 = 0, rs.callrestrictiondays4 = 0,
		rs.callrestrictiondays5 = 0, rs.callrestrictiondays6 = 0, rs.callrestrictiondays7 = 0;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_freecontract_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_freecontract_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_freecontract_detail`()
BEGIN
	
	DECLARE cu_customerid INT(10);
	DECLARE cu_contractid INT(10);
	DECLARE cu_startdate DATE;
	DECLARE cu_enddate DATE;
	DECLARE cu_itemid INT(10);
	DECLARE cu_qty INT(10);
	DECLARE cu_upc INT(10);
	DECLARE cu_route INT(10);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT customerid, customerid contractid, startdate, enddate, itemid, qty*upc qty, upc, route
			FROM temp_freecontract WHERE customerid > 0 AND itemid > 0);	
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_customerid, cu_contractid, cu_startdate, cu_enddate, cu_itemid, cu_qty, cu_upc, cu_route;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
			
			INSERT INTO customer_foc (customercode, contractid, creationdate, remarks, startdate, enddate, active, depotcode)
				VALUES (cu_customerid, cu_contractid, CURDATE(), '', cu_startdate, cu_enddate, 1, cu_route)
			ON DUPLICATE KEY UPDATE
					creationdate = CURDATE(), 
					startdate = cu_startdate, 
					enddate = cu_enddate;			
			
			INSERT INTO customer_foc_detail (customercode, contractid, itemcode, freequantity, editdate, remarks)
				VALUES (cu_customerid, cu_contractid, cu_itemid, cu_qty, CURDATE(), '')
			ON DUPLICATE KEY UPDATE
					editdate = CURDATE(), 
					freequantity = cu_qty;
			
			INSERT INTO customer_foc_balance (customercode, itemcode, originalqty, balanceqty, contractid, startdate)
				VALUES (cu_customerid, cu_itemid, cu_qty, cu_qty, cu_contractid, cu_startdate)
			ON DUPLICATE KEY UPDATE
					startdate = cu_startdate, 
					originalqty = cu_qty,
					balanceqty = cu_qty;
					
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	-- -----------------------------------------------------------------------------------------------------------------------------	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_freecontract_header` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_freecontract_header` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_freecontract_header`()
BEGIN
	UPDATE temp_freecontract fc
		INNER JOIN customermaster cm ON cm.alternatecode = REPLACE(fc.customercode,' ','') 
	SET fc.customerid = cm.customercode;
	
	UPDATE temp_freecontract fc
		INNER JOIN itemmaster im ON im.alternatecode = REPLACE(fc.itemcode,' ','') 
	SET fc.itemid = im.actualitemcode, fc.upc = im.unitspercase;
	
	-- UPDATE temp_freecontract SET 
		-- startdate = COALEScE(DATE_FORMAT(STR_TO_DATE(startdate, '%d/%m/%Y'), '%Y-%m-%d'),curdate()), 
		-- enddate = COALESCE(DATE_FORMAT(STR_TO_DATE(enddate, '%d/%m/%Y'), '%Y-%m-%d'),CURDATE());
	
	UPDATE temp_freecontract SET customerid = 0 WHERE customerid IS NULL;
	UPDATE temp_freecontract SET itemid = 0 WHERE itemid IS NULL;
	
	UPDATE temp_freecontract SET temp_freecontract.route = 
		COALESCE((SELECT MAX(rs.routecode) FROM routesequence rs WHERE rs.customercode = temp_freecontract.customerid), 0);
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_itemgroup` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_itemgroup` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_itemgroup`(
)
BEGIN
	DECLARE cu_submajorcategoryid INT(8);
	DECLARE cu_groupid INT(8);
	DECLARE cu_alternatecode VARCHAR(50);
	DECLARE cu_groupname VARCHAR(50);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT DISTINCT (SELECT MIN(submajorcategorycode) FROM submajorcategory) submajorcategorycode,
			brandid, brand, CONCAT(brandname,' - ', brand) itemgroup
		 FROM imp_itemmaster);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_submajorcategoryid, cu_groupid, cu_alternatecode, cu_groupname;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
			
			INSERT INTO itemgroup SET 	
				itemgroupcode = cu_groupid,
				alternateitemgroupcode = cu_alternatecode,
				itemgroupname = cu_groupname, 
				arbitemgroup = cu_groupname, 
				submajorcategorycode = cu_submajorcategoryid,
				activestatus = 1, 
				cdat = CURDATE(),
				hhcitemgroup = cu_groupname,
				created = 'admin'
			ON DUPLICATE KEY UPDATE
				itemgroupname = cu_groupname, 
				arbitemgroup = cu_groupname,
				mdat = CURDATE(),
				hhcitemgroup = cu_groupname,
				modified = 'admin';
			
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	-- -----------------------------------------------------------------------------------------------------------------------------
					
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_items` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_items` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_items`()
BEGIN	
			
	INSERT INTO itemmaster (actualitemcode, itemgroupcode, itemtype, itemshortdescription, itemdescription, unitspercase, defaultsalesprice, defaultreturnprice,
		defaultretailprice, arbitemshortdescription, arbitemdescription, activeitem, caseprice, returncaseprice, retailcaseprice, alternatecode, created, cdat,
		printsequenceroute, printsequencecust, anitemcode, itemcompany, defaultgoodreturnprice, defaultgoodreturncaseprice, allowbatchentry, barcode1, 
		barcode2, barcode3, memo1, memo2, liter, dataentry, captureshelfstock, literperunit, packagecode, warehousestock, hhcitemshortdescription)
		
	SELECT itemid, (SELECT MIN(itemgroupcode) FROM itemgroup) itemgroup, 1 itemtype, 
		REPLACE(REPLACE(itemdescription,"'","`"),"á",""), 
		REPLACE(REPLACE(itemdescription,"'","`"),"á",""), unitspercase, 
		eachprice, eachprice, eachprice, 
		REPLACE(REPLACE(itempacking,"'","`"),"á",""), 
		REPLACE(REPLACE(itempacking,"'","`"),"á",""), activestatus, caseprice, caseprice, caseprice, itemcode, 
		'admin', CURDATE(), itemid, itemid, itemcode, (SELECT MIN(cmpycode) FROM company) itemcompany, eachprice, caseprice, 0 allowbatchentry, 
		barcodeeach barcode1, barcodecarton barcode2, otherbarcode barcode3, memo1,memo2, 0, 0, 0, 0, 0, 0, attribute1
		
	FROM imp_itemmaster
	
		ON DUPLICATE KEY UPDATE 
			itemmaster.itemshortdescription = REPLACE(REPLACE(imp_itemmaster.itemdescription,"'","`"),"á",""), 
			itemmaster.itemdescription = REPLACE(REPLACE(imp_itemmaster.itemdescription,"'","`"),"á",""), 
			itemmaster.arbitemshortdescription =  REPLACE(REPLACE(imp_itemmaster.itempacking,"'","`"),"á",""), 
			itemmaster.arbitemdescription =  REPLACE(REPLACE(imp_itemmaster.itempacking,"'","`"),"á",""), 
			-- itemmaster.unitspercase = imp_itemmaster.unitspercase,
			itemmaster.modified = 'admin', 
			itemmaster.mdat = CURRENT_DATE(), 
			itemmaster.memo1 = imp_itemmaster.memo1, 
			itemmaster.memo2 = imp_itemmaster.memo2,
			itemmaster.activeitem = imp_itemmaster.activestatus,
			itemmaster.hhcitemshortdescription = imp_itemmaster.attribute1,
			itemmaster.barcode1=imp_itemmaster.barcodeeach,
			itemmaster.barcode2=imp_itemmaster.barcodecarton,
			itemmaster.barcode3=imp_itemmaster.otherbarcode;
	
	UPDATE itemmaster SET itemdescription = CONCAT(LEFT(itemshortdescription,45), 'OTR') WHERE memo1 = 'OTR';
	
	INSERT INTO routeitemgrp 
		VALUE ('1','0', 'DEFAULT GROUP', 'admin', NOW(),NULL,NULL,'1') 
		ON DUPLICATE KEY UPDATE 
			modified = 'admin', 
			mdat = NOW();
	-- seeting row id for duplication checking
	SET @pos := 0;
	UPDATE itemmaster SET printsequenceroute = (SELECT @pos := @pos + 1 ) ORDER BY alternatecode;
	UPDATE itemmaster SET printsequencecust = printsequenceroute;
	-- ------------------------------------------------------------------------------------------------
	
	-- DELETE FROM routeitemmapping WHERE routeitemgrpcode = 1;
	-- INSERT INTO routeitemmapping SELECT 1, actualitemcode, 0 FROM itemmaster WHERE activeitem = 1;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_loadrequest` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_loadrequest` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_loadrequest`()
BEGIN
UPDATE temp_loadrequest SET requestdate = REPLACE(requestdate,'-','/');
SELECT INSTR(LEFT(requestdate,4),'/') INTO @format FROM temp_loadrequest LIMIT 1;
IF @format = 0 THEN
	UPDATE temp_loadrequest req
		INNER JOIN itemmaster im ON im.alternatecode = req.itemcode
	SET req.itemid=im.actualitemcode, 
		req.upc = im.unitspercase;
ELSE
	UPDATE temp_loadrequest req
		INNER JOIN itemmaster im ON im.alternatecode = req.itemcode
	SET req.itemid=im.actualitemcode, 
		req.upc = im.unitspercase, 
		req.requestdate = DATE_FORMAT(STR_TO_DATE(req.requestdate, '%d/%m/%Y'), '%Y-%m-%d');
END IF;
UPDATE temp_loadrequest req
	INNER JOIN salesman im ON im.alternatesalesmancode = req.salesmancode
SET req.salesmanid=im.salesmancode;
SET @docno := 0; SET @route := '';
SELECT COALESCE(MAX(documentnumber),0) INTO @docno FROM inventorytransactionheader WHERE DATA = 1;
UPDATE temp_loadrequest 
	SET docno = @docno := CASE WHEN @route = salesmancode THEN @docno ELSE @docno + 1 END,
	salesmancode = @route := salesmancode
ORDER BY salesmancode;
UPDATE temp_loadrequest SET temp_loadrequest.routekey = 
	(SELECT MAX(sed.routekey) FROM startendday sed WHERE sed.salesmancode = temp_loadrequest.salesmanid);
	
UPDATE temp_loadrequest SET temp_loadrequest.routecode = 
	(SELECT rm.routecode FROM routemaster rm WHERE rm.salesmancode = temp_loadrequest.salesmanid);
	
INSERT INTO inventorytransactionheader (inventorykey,routekey,transactiontype,routecode,salesmancode,transactiondate,transactiontime,documentnumber,
	odometerreading,transferlocationcode,referencenumber,requestdate,securitycode,transmitindicator,voidflag,
	hhcdocumentnumber,loadnumber,refdocumentnumber,currencycode,actualtransactiondate,inventorynumber,DATA,
	record_flag,deliverydate,isurgent,receivedtime)
SELECT DISTINCT
	req.routekey inventorykey, req.routekey routekey, 4 transactiontype, req.routecode, req.salesmanid, CURDATE() transactiondate,
	CURTIME() transactiontime, req.docno, 0 odometerreading, 
	COALESCE((SELECT rm.routecode FROM routemaster rm WHERE rm.alternateroutecode = req.warehouse LIMIT 1), '') transferlocationcode, 
	0 referencenumber, req.requestdate, 0 securitycode, 0 transmitindicator, 0 voidflag, req.docno hhcdocumentnumber, 0 loadnumber, 
	0 refdocumentnumber, 1 currencycode, CURDATE() actualtransactiondate, req.docno inventorynumber, 1 DATA, 
	1 record_flag, req.requestdate deliverydate, COALESCE(urgent,0) isurgent, CURTIME() receivedtime
FROM temp_loadrequest req
WHERE req.requestdate IS NOT NULL;
INSERT INTO inventorytransactiondetail (routekey,detailkey,transactiontypecode,itemcode,quantity,requestedqty,weighted,
	itemprice,batchdetailkey,itemcaseprice,currencycode,record_flag,expirydate,reasoncode)
SELECT req.routekey, ith.detailkey, 8 transactiontypecode, req.itemid, SUM(req.qty), SUM(req.qty), 0 weighted, 
	im.defaultsalesprice, 0 batchdetailkey, im.caseprice, 1 currencycode, 1 record_flag, NULL expirydate, 
	NULL reasoncode
FROM temp_loadrequest req
	INNER JOIN itemmaster im ON im.actualitemcode = req.itemid
	INNER JOIN inventorytransactionheader ith ON ith.documentnumber = req.docno AND ith.routecode = req.routecode
WHERE req.requestdate IS NOT NULL
GROUP BY req.routekey, ith.detailkey, req.itemid;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_majorcategory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_majorcategory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_majorcategory`(
)
BEGIN
	DECLARE cu_companygroupcode INT(8);
	DECLARE cu_majorcategorycode INT(8);
	DECLARE cu_alternatecode VARCHAR(50);
	DECLARE cu_categorydesc VARCHAR(50);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT DISTINCT (SELECT MIN(companygroupcode) FROM companygroup) companygroupcode, 
			brandid, brand, CONCAT(brandgroupname,' - ', brand) brandgroupname
		 FROM imp_itemmaster);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_companygroupcode, cu_majorcategorycode, cu_alternatecode, cu_categorydesc;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
			
			INSERT INTO majorcategory SET
				majorcategorycode = cu_majorcategorycode,
				companygroupcode = cu_companygroupcode,
				alternatecode = cu_alternatecode,
				description = cu_categorydesc,
				arbdescription = cu_categorydesc,
				activestatus = 1,
				cdat = CURDATE(),
				created = 'admin'
			ON DUPLICATE KEY UPDATE 
				description = cu_categorydesc,
				arbdescription = cu_categorydesc,
				mdat = CURDATE(),
				modified = 'admin';
			
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	-- -----------------------------------------------------------------------------------------------------------------------------
					
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_routegoal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_routegoal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_routegoal`()
BEGIN
	UPDATE temp_routegoal SET packagenumber = 2 WHERE targettype IN (1,2,6,7) AND packagenumber=1;
	DELETE FROM routegoal 
	USING routegoal, temp_routegoal
	WHERE temp_routegoal.routecode = routegoal.routecode AND 
			temp_routegoal.packagenumber = routegoal.packagenumber AND 
			temp_routegoal.fromdate = routegoal.fromdate AND 
			temp_routegoal.todate = routegoal.todate AND
			temp_routegoal.targettype = routegoal.targettype;
	
	INSERT INTO routegoal
		(routecode, salesmancode, packagenumber, fromdate, todate, quantity, achievequantity, achieveamount,
			todaysgoal, todaysachieve, targettype, commision, commisonpercent, insentive, insentivepercent, goaltype, cdat)
	SELECT 
		rs.routecode, rm.salesmancode, rs.packagenumber, rs.fromdate, rs.todate, rs.quantity, 0, 0,
			0, 0, rs.targettype, rs.commision, 0, rs.insentive, 0, 0, NOW()
	FROM temp_routegoal rs 
		INNER JOIN routemaster rm ON rm.routecode = rs.routecode
	
	ON DUPLICATE KEY UPDATE 
		cdat = NOW(),
		quantity = rs.quantity;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_routesequence` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_routesequence` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_routesequence`()
BEGIN
	
	SELECT COALESCE(COUNT(*),0) INTO @recordcount FROM temp_routesequence ;
	
	If @recordcount > 0 THEN
		DELETE FROM routesequence WHERE routecode IN (SELECT DISTINCT routecode FROM temp_routesequence);
	END IF;
	
	INSERT INTO routesequence
		(rp32weeknumber, routecode, customercode, callrestrictiondays1, callrestrictiondays2, 
		callrestrictiondays3, callrestrictiondays4, callrestrictiondays5, callrestrictiondays6, callrestrictiondays7, 
		monseq, tueseq, wedseq, thuseq, friseq, satseq, sunseq, mdat, referenceno)
	SELECT 
		seq.weeknumber, seq.routecode, seq.customercode, 
		seq.monvisit, seq.tuevisit, seq.wedvisit, seq.thuvisit, seq.frivisit, seq.satvisit, seq.sunvisit,
		seq.monsequence, seq.tuesequence, seq.wedsequence, seq.thusequence, seq.frisequence, seq.satsequence, seq.sunsequence,
		seq.mdat, seq.refno
	FROM
		(SELECT 
			rs.weeknumber, rs.routecode, cm.customercode, 
			CASE WHEN SUM(rs.monvisit) >= 1 THEN 1 ELSE 0 END monvisit, 
			CASE WHEN SUM(rs.tuevisit) >= 1 THEN 1 ELSE 0 END  tuevisit, 
			CASE WHEN SUM(rs.wedvisit) >= 1 THEN 1 ELSE 0 END  wedvisit, 
			CASE WHEN SUM(rs.thuvisit) >= 1 THEN 1 ELSE 0 END  thuvisit, 
			CASE WHEN SUM(rs.frivisit) >= 1 THEN 1 ELSE 0 END  frivisit, 
			CASE WHEN SUM(rs.satvisit) >= 1 THEN 1 ELSE 0 END  satvisit, 
			CASE WHEN SUM(rs.sunvisit) >= 1 THEN 1 ELSE 0 END  sunvisit,
			rs.monsequence, rs.tuesequence, rs.wedsequence, rs.thusequence, rs.frisequence, rs.satsequence, rs.sunsequence,
			CURDATE() mdat, NULL refno
		FROM temp_routesequence rs 
			INNER JOIN routemaster rm ON rm.routecode = rs.routecode
			INNER JOIN customermaster cm ON cm.hhccustomername = rs.customercode AND UPPER(cm.memo2)=UPPER(rm.memo1)
		GROUP BY rs.weeknumber, rs.routecode, cm.customercode) seq	
	ON DUPLICATE KEY UPDATE 
		routesequence.rp32weeknumber = seq.weeknumber, 
		routesequence.routecode = seq.routecode, 
		routesequence.customercode = seq.customercode, 
		routesequence.callrestrictiondays1 = seq.monvisit, 
		routesequence.callrestrictiondays2 = seq.tuevisit, 
		routesequence.callrestrictiondays3 = seq.wedvisit, 
		routesequence.callrestrictiondays4 = seq.thuvisit, 
		routesequence.callrestrictiondays5 = seq.frivisit, 
		routesequence.callrestrictiondays6 = seq.satvisit, 
		routesequence.callrestrictiondays7 = seq.sunvisit, 
		routesequence.monseq = seq.monsequence, 
		routesequence.tueseq = seq.tuesequence, 
		routesequence.wedseq = seq.wedsequence, 
		routesequence.thuseq = seq.thusequence, 
		routesequence.friseq = seq.frisequence, 
		routesequence.satseq = seq.satsequence, 
		routesequence.sunseq = seq.sunsequence, 
		routesequence.mdat = seq.mdat;
		
	UPDATE routesequence rs
		INNER JOIN customermaster cm ON cm.customercode = rs.customercode AND cm.activecustomer=0
	SET rs.callrestrictiondays1 = 0,rs.callrestrictiondays2 = 0,rs.callrestrictiondays3 = 0,rs.callrestrictiondays4 = 0,
		rs.callrestrictiondays5 = 0,rs.callrestrictiondays6 = 0,rs.callrestrictiondays7 = 0;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_post_submajorcategory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_post_submajorcategory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_submajorcategory`(
)
BEGIN
	DECLARE cu_majorcategoryid INT(8);
	DECLARE cu_subcategoryid INT(8);
	DECLARE cu_alternatecode VARCHAR(50);
	DECLARE cu_subcategoryname VARCHAR(50);
	
	DECLARE done INT DEFAULT FALSE;
		
	DECLARE cur_one CURSOR FOR 
		(SELECT DISTINCT (SELECT MIN(majorcategorycode) FROM majorcategory) majorcategorycode,
			subcategoryid, subcategory, CONCAT(subcategoryname,' - ', subcategory) subcategoryname
		 FROM imp_itemmaster);
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	
	OPEN cur_one;
	read_loop_one: LOOP
		
		FETCH cur_one INTO cu_majorcategoryid, cu_subcategoryid, cu_alternatecode, cu_subcategoryname;
			
			IF done = TRUE THEN
				LEAVE read_loop_one;
			END IF;
			
			INSERT INTO submajorcategory SET 	
				submajorcategorycode = cu_subcategoryid,
				alternatecode = cu_alternatecode,
				description = cu_subcategoryname, 
				arbdescription = cu_subcategoryname, 
				majorcategorycode = cu_majorcategoryid,
				activestatus = 1, 
				cdat = CURDATE(), 
				created = 'admin'
		ON DUPLICATE KEY UPDATE 
				description = cu_subcategoryname, 
				arbdescription = cu_subcategoryname,
				mdat = CURDATE(),
				modified = 'admin';
			
	END LOOP read_loop_one;
	
	CLOSE cur_one;
	-- -----------------------------------------------------------------------------------------------------------------------------
					
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_reportcollectiondetails` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_reportcollectiondetails` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_reportcollectiondetails`( in reportname varchar(50))
BEGIN
 if reportname= 'Collection Detail' then 
  
	 SELECT
ah.invoicenumber AS receiptnumber,ah.transactiondate,ah.routecode,ah.Salesmancode collectedsalesman,ah.customercode,customername,
CASE WHEN typecode=0 THEN ccd.amount ELSE 0 END  AS cashpayment ,
CASE WHEN typecode=1 THEN ccd.amount ELSE 0 END  AS checkpayment,ad.amountpaid AS totalamountpaid,ad.invoicedate,
ad.invoicenumber,ad.salesmancode InvoicedSalesman,ad.totalinvoiceamount,ad.invoicebalance,ccd.checknumber
FROM arheader ah INNER JOIN ardetail ad ON ah.routekey=ad.routekey AND ah.visitkey=ad.visitkey
INNER JOIN cashcheckdetail ccd ON ccd.routekey=ad.routekey AND ccd.visitkey=ad.visitkey
INNER JOIN customermaster cm ON cm.customercode=ah.customercode
WHERE ah.transactiondate BETWEEN '2022-01-16' AND '2022-02-22';
else
Select 'No Report Selected';
end if;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customerpendingbalance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customerpendingbalance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customerpendingbalance`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
IN in_status_val INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
	IF in_status_val = 1 THEN 
		SET @dyn_sql = CONCAT("SELECT 
						DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
						DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt
					FROM 
						customerinvoice ci, customermaster cm
					WHERE 
						cm.customercode = ci.customercode AND ci.invoicebalance <> 0 ",in_where,"
					GROUP BY monthno,yearno
					ORDER BY yearno,monthno");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
	ELSE
		
		SET @dyn_sql = CONCAT("SELECT  	count(*) INTO @in_counter  FROM customerinvoice ci, customermaster cm WHERE 
			cm.customercode = ci.customercode AND ci.invoicebalance <> 0", in_where);
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
		
		SET @dyn_sql = CONCAT("SELECT 
						DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
						DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt,
						ci.routecode, ci.salesmancode, ci.customercode, DATE(ci.transactiondate) transactiondate, ci.erpreferencenumber,
						cm.customername, cm.reportcustcode,
						CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
						CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
						ci.invoicebalance,ci.invoicebalance as total,ci.invoicenumber,
						(SELECT ih.comments FROM invoiceheader ih WHERE ih.invoicenumber = ci.invoicenumber) comments,
						cm.arbcustomername
					FROM 
						customerinvoice ci, customermaster cm
					WHERE 
						cm.customercode = ci.customercode AND ci.invoicebalance <> 0",in_where, " ORDER BY hocode,honame",in_orderby," ",in_sort, " ",limit_val) ;
		-- select @dyn_sql;
		 PREPARE s1 FROM @dyn_sql;
		 EXECUTE s1;	
	
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customerpendingbalance_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customerpendingbalance_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customerpendingbalance_detail`( IN cust_type INT(4)
  ,IN var_user INt(4)
  )
BEGIN
	
		SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
		
		If var_user = 1 THEN
			
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND `type` = cust_type; 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  AND `type` = cust_type; 
		END IF;	
		
		ELSE
		
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND `type` = cust_type
			AND customercode IN (SELECT customercode FROM routesequence WHERE routecode IN(SELECT routecode FROM routemaster WHERE templatename=var_user)); 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  AND `type` = cust_type
			AND customercode IN (SELECT customercode FROM routesequence WHERE routecode IN(SELECT routecode FROM routemaster WHERE templatename=var_user)); 
		END IF;
		
		END IF;
			
		
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customerpending_coloums` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customerpending_coloums` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customerpending_coloums`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
SET @dyn_sql = CONCAT("SELECT 
		DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
		DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt
	FROM 
		customerinvoice ci, customermaster cm
	WHERE 
		cm.customercode = ci.customercode AND ci.invoicebalance <> 0",in_where, " GROUP BY yearno,monthno ORDER BY ",in_orderby," ",in_sort, " LIMIT ",@new_start_limit, ",",in_limit) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customer_aging` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customer_aging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customer_aging`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT ""; 
SET @dyn_sql = CONCAT("SELECT 
				count(*) INTO @in_counter  
			FROM customerinvoice ci, customermaster cm
			WHERE 
				cm.customercode = ci.customercode AND ci.invoicebalance <> 0"
			, in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT 
					DATE_FORMAT(ci.transactiondate, '%d %b %Y') AS transactiondate,
					CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
					CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,		
					ci.erpreferencenumber, ci.customercode, cm.customername, cm.reportcustcode, cm.creditlimit, cm.creditlimitdays,
					DATEDIFF(NOW(), ci.transactiondate) nodays, 
					(SELECT CASE WHEN DATEDIFF(NOW(),MIN(ci1.transactiondate)) > cm.creditlimitdays THEN 'red' ELSE '' END FROM customerinvoice ci1 WHERE ci1.customercode = cm.customercode AND ci1.invoicebalance > 0) creditstatus,
					ci.invoicebalance, ci.routecode, ci.salesmancode,
					(SELECT COALESCE(ih.comments, '') FROM invoiceheader ih WHERE ih.invoicenumber = ci.invoicenumber) comments,
					CASE 
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 120 THEN 121
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 90 THEN 91
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 60 THEN 61
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 30 THEN 31
					ELSE 0 END age,
					cm.arbcustomername
				FROM 
					customerinvoice ci, customermaster cm
				WHERE 
					cm.customercode = ci.customercode AND ci.invoicebalance <> 0 ",in_where, " ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
	-- select @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_customer_aging_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_customer_aging_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_customer_aging_detail`()
BEGIN
CALL sp_combo_customermaster() ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_pdc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_pdc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_pdc`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM customerinvoice ci, customermaster cm ,routemaster rm,salesman sm 
	", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	SET @dyn_sql = CONCAT("
		SELECT DATE_FORMAT( ci.transactiondate, '%d %b %y') AS transactiondate,
		 CASE 
			WHEN cm.type = 1 THEN '0'
			WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) 
			ELSE '1' 
			END hocode,
		 CASE 
			WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS'
			WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode)
			ELSE '' 
			END honame,
		 ci.erpreferencenumber, ci.customercode,ci.invoicenumber, cm.customername, cm.reportcustcode, cm.creditlimit, cm.creditlimitdays, ci.invoicebalance,
		 ci.routecode, ci.salesmancode ,rm.routename, sm.salesmanname1,ci.pdcbalance,ci.pdcdate,
		 CASE WHEN DATEDIFF(ci.transactiondate, CURDATE()) > 120 THEN 121
		  WHEN DATEDIFF( ci.transactiondate, CURDATE()) > 90 THEN 91 
		  WHEN DATEDIFF( ci.transactiondate, CURDATE()) > 60 THEN 61 
		  WHEN DATEDIFF( ci.transactiondate, CURDATE()) > 30 THEN 31 
		  ELSE 0 
		  END age,
		  cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1
		FROM customerinvoice ci, customermaster cm ,routemaster rm,salesman sm
		",in_where, orderby_val,limit_val) ;
   -- SELECT @dyn_sql;	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_pdc_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_pdc_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_pdc_detail`( IN cust_type INT(4))
BEGIN
SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
			
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 AND `type` = cust_type; 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  AND `type` = cust_type; 
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_routependingbalance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_routependingbalance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_routependingbalance`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
	IF in_where = 1 then
		SET @dyn_sql = CONCAT("SELECT DISTINCT(DATE_FORMAT(ci.transactiondate,'%Y')) yearno
					FROM customerinvoice ci, routemaster rm, salesman sm 
					WHERE rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode 
					GROUP BY DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
					ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1
					ORDER BY yearno");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
	ElSE 
	
		SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM (SELECT ci.routecode FROM customerinvoice ci, routemaster rm, salesman sm WHERE 
					rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode", in_where,"
					GROUP BY DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
					ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1) as cnt");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
		
		SET @dyn_sql = CONCAT("
			SELECT
				DATE_FORMAT(ci.transactiondate,'%Y') yearno, 
				DATE_FORMAT(ci.transactiondate,'%m') monthno, DATE_FORMAT(ci.transactiondate,'%M') monthtxt,
				ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1, sum(ci.invoicebalance) invoicebalance,
				rm.arbroutename,sm.arbsalesmanname1
			FROM customerinvoice ci, routemaster rm, salesman sm
			WHERE rm.routecode = ci.routecode and sm.salesmancode = ci.salesmancode",in_where, "
			 GROUP BY DATE_FORMAT(ci.transactiondate,'%Y'), DATE_FORMAT(ci.transactiondate,'%m'), DATE_FORMAT(ci.transactiondate,'%M'),
				ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
		 PREPARE s1 FROM @dyn_sql;
		 EXECUTE s1;	
	 
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_routependingbalance_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_routependingbalance_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_routependingbalance_detail`()
BEGIN
CALL sp_combo_routemaster() ;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_route_aging` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_route_aging` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_route_aging`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  
			FROM customerinvoice ci, customermaster cm, routemaster rm, salesman sm,
				(SELECT ih.invoicenumber, ih.actualtransactiondate FROM invoiceheader ih) inv 
			WHERE cm.customercode = ci.customercode AND ci.routecode = rm.routecode AND ci.salesmancode = sm.salesmancode AND
				ci.invoicebalance <> 0 AND inv.invoicenumber =ci.invoicenumber", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT 
					date(ci.transactiondate) AS transactiondate,
					CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode order by cm1.reportcustcode LIMIT 1) ELSE '1' END hocode,
					CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode order by cm1.customername LIMIT 1) ELSE '' END honame,		 
					ci.invoicenumber, ci.erpreferencenumber, ci.customercode, cm.customername,cm.arbcustomername, cm.reportcustcode, ci.routecode, rm.routename, ci.salesmancode, sm.salesmanname1, 
					cm.creditlimit, cm.creditlimitdays,
					(SELECT CASE WHEN DATEDIFF(MIN(ci1.transactiondate), NOW()) > cm.creditlimitdays THEN 'red' ELSE '' END FROM customerinvoice ci1 WHERE ci1.customercode = cm.customercode AND ci1.invoicebalance > 0 LIMIT 1) creditstatus,
					DATEDIFF(ci.transactiondate, NOW()) nodays, ci.invoicebalance, 
					CASE 
						WHEN DATEDIFF(NOW(),ci.transactiondate) > 120 THEN ci.invoicebalance ELSE 0 END age121, 
							CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 90 && DATEDIFF(NOW(),ci.transactiondate) <= 120 THEN ci.invoicebalance ELSE 0 END age91, 
								CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 60 && DATEDIFF(NOW(),ci.transactiondate) <= 90 THEN ci.invoicebalance ELSE 0 END age61,
									CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 30 && DATEDIFF(NOW(),ci.transactiondate) <= 60 THEN ci.invoicebalance ELSE 0 END age31,
									CASE WHEN DATEDIFF(NOW(),ci.transactiondate) > 0 && DATEDIFF(NOW(),ci.transactiondate) <= 30 THEN ci.invoicebalance ELSE 0 END age,						
					CASE WHEN ci.pdcbalance != 0 THEN ci.pdcbalance ELSE (SELECT SUM(ard.pdcbalance) FROM ardetail ard WHERE ard.pdcbalance > 0 AND ard.invoicenumber = ci.invoicenumber) END pdcamount, 
					CASE WHEN ci.pdcbalance != 0 THEN 
							(SELECT ccd.checkdate FROM invoiceheader ih, cashcheckdetail ccd WHERE ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND ih.invoicenumber = ci.invoicenumber order by ccd.checkdate LIMIT 1)
						ELSE 
							(SELECT ccd.checkdate FROM ardetail ard, cashcheckdetail ccd WHERE ccd.routekey = ard.routekey AND ccd.visitkey = ard.visitkey AND ard.pdcbalance > 0 AND ard.invoicenumber = ci.invoicenumber order by ccd.checkdate LIMIT 1) END pdcdate,
					cm.arbcustomername,rm.arbroutename,sm.arbsalesmanname1
				FROM 
					customerinvoice ci, customermaster cm, routemaster rm, salesman sm
					
				WHERE 
					cm.customercode = ci.customercode AND ci.routecode = rm.routecode AND ci.salesmancode = sm.salesmancode AND
					ci.invoicebalance <> 0 ",in_where, " ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
					
					 -- ci.pdcbalance as pdcamount,
	 PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;		
	-- select @dyn_sql;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_route_aging_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_route_aging_detail` */;

