/* Procedure structure for procedure `sp_report_account_soa` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_soa` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_soa`(
	IN customercodeparam INT,
	IN dtfromdateparam DATETIME,
	IN dttodateparam DATETIME
)
BEGIN
	DECLARE openingbalance_val float DEFAULT 0;
	DECLARE total_val FLOAT DEFAULT 0;
	/*
	SET @customercode = customercodeparam;
	SET @dtfromdate = dtfromdateparam;
	SET @dttodate = dttodateparam;
	*/
	SELECT customername,arbcustomername INTO @custname,@arbcustname FROM customermaster WHERE customercode = customercodeparam;
	-- SELECT arbcustomername INTO @arbcustname FROM customermaster WHERE customercode = customercodeparam;
	
	CREATE TABLE tempstatementofaccount (customercode NUMERIC, customername VARCHAR(50), arbcustomername VARCHAR(50), detailtype INT, detailtext VARCHAR(150), transactiondate DATETIME ,amount FLOAT);
	DELETE FROM tempstatementofaccount;
	
	
	SET openingbalance_val = 0;
	SET total_val = 0;
	
	SELECT IFNULL(SUM(ih.totalinvoiceamount),0) INTO openingbalance_val FROM customerinvoice ih,customermaster cm WHERE ih.customercode=cm.customercode AND cm.headofficecode=customercodeparam AND ih.transactiontype IN(1,2) AND ih.transactiondate < dtfromdateparam AND ih.voidflag=0;
	
	-- amount collected using bo 
	SELECT IFNULL(SUM(d.amountpaid),0) INTO total_val FROM bearheader h,beardetail d WHERE h.transactionkey=d.transactionkey AND h.transactiondate < dtfromdateparam AND h.customercode=customercodeparam AND h.voidflag=0 ;
	
	SET openingbalance_val = openingbalance_val - total_val; 
	
	SET total_val = 0;
	-- credit note 
	SELECT IFNULL(SUM(d.amountpaid),0) INTO total_val FROM dcarheader h,dcardetail d,customermaster cm WHERE h.transactionkey=d.transactionkey AND h.transactiondate < dtfromdateparam AND h.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND h.voidflag=0 AND h.transactiontype = 4;
	SET openingbalance_val = openingbalance_val - total_val; 
	SET total_val = 0;
	-- debit note 
	
	SELECT IFNULL(SUM(d.amountpaid),0) INTO total_val FROM dcarheader h,dcardetail d,customermaster cm WHERE h.transactionkey=d.transactionkey AND h.transactiondate < dtfromdateparam AND h.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND h.voidflag=0 AND h.transactiontype = 3;
	SET openingbalance_val = openingbalance_val + total_val; 
	SET total_val = 0;
	-- ar collection if any 
	SELECT IFNULL(SUM(ih.amountpaid ),0) INTO total_val FROM arheader ih, ardetail id,customermaster cm WHERE id.transactionkey = ih.transactionkey AND ih.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND ih.transactiondate < dtfromdateparam AND ih.voidflag=0 ;
	SET openingbalance_val = openingbalance_val - total_val; 
	SET total_val = 0;
	IF openingbalance_val IS NULL THEN
		SET openingbalance_val = 0;
	END IF;
		
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount)
	 VALUES(customercodeparam, @custname, @arbcustname, 1, 'opening balance ',dtfromdateparam , openingbalance_val);
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount) 
	( SELECT ih.customercode, @custname,@arbcustname, 1, CONCAT('opening balance: ',ih.invoicenumber) , ih.transactiondate, ih.totalinvoiceamount 
		FROM customerinvoice ih,customermaster cm 
		WHERE ih.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND ih.transactiontype = 1 AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND ih.voidflag = 0 );
		
	INSERT INTO tempstatementofaccount(customercode, customername,arbcustomername, detailtype, detailtext, transactiondate, amount) 
	( SELECT ih.customercode, @custname,@arbcustname, 2, CONCAT('invoice: ', ih.invoicenumber) , ih.transactiondate, ih.totalinvoiceamount 
		FROM customerinvoice ih,customermaster cm 
		WHERE ih.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND ih.transactiontype = 2 AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND ih.voidflag = 0 );
	
	
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount) 
	( SELECT ih.customercode, @custname, @arbcustname, 4, CONCAT('payment: ', ih.invoicenumber ) , ih.transactiondate, ih.immediatepaid 
		FROM customerinvoice ih, customermaster cm 
		WHERE ih.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND ih.transactiontype = 2 AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND ih.voidflag=0 AND ih.immediatepaid != 0 );
	
	
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount) 
	(SELECT ih.customercode, @custname, @arbcustname, 3,  CONCAT('debit note: ',ih.documentnumber), ih.transactiondate, ih.amountpaid 
		FROM dcarheader ih, customermaster cm 
		WHERE ih.customercode = cm.customercode AND ih.transactiontype=3 AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND cm.headofficecode = customercodeparam AND ih.voidflag=0);
	
	
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount) 
	(SELECT ih.customercode, @custname, @arbcustname, 5, CONCAT('credit note: ', ih.documentnumber,' ',ih.remarks1) ,ih.transactiondate,ih.amountpaid 
		FROM dcarheader ih,customermaster cm 
		WHERE ih.customercode = cm.customercode AND ih.transactiontype=4 AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND cm.headofficecode =customercodeparam AND ih.voidflag=0);
	
	
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount) 
	(SELECT ih.customercode, @custname, @arbcustname, 4, CONCAT('payment: ', ih.invoicenumber), ih.transactiondate, ih.amountpaid 
		FROM arheader ih,ardetail id, customermaster cm 
		WHERE id.transactionkey = ih.transactionkey AND ih.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND ih.voidflag=0);
	
	INSERT INTO tempstatementofaccount(customercode, customername, arbcustomername, detailtype, detailtext, transactiondate, amount) 
	(SELECT ih.customercode, @custname, @arbcustname, 5,  CONCAT('advance received: ', ih.invoicenumber), ih.transactiondate, ih.advancereceived 
		FROM salesorderheader ih,customermaster cm 
		WHERE ih.customercode = cm.customercode AND cm.headofficecode = customercodeparam AND (ih.transactiondate BETWEEN dtfromdateparam AND dttodateparam) AND ih.voidflag=0);
	SELECT * FROM tempstatementofaccount ORDER BY transactiondate,detailtype ;
	DROP TABLE tempstatementofaccount;		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_account_soa_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_account_soa_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_account_soa_detail`(IN var_user INT(4))
BEGIN
	SELECT `status` INTO @st FROM controlpanel WHERE flagname = 'Use Alternate Code';
		
		IF var_user = 1 THEN
			
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 ; 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  ; 
		END IF;	
		
		ELSE
		
		IF @st = 1 THEN 
			SELECT customercode AS id, CONCAT(alternatecode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0 
			AND customercode IN (SELECT customercode FROM routesequence WHERE routecode IN(SELECT routecode FROM routemaster WHERE templatename=var_user)); 
		ELSE
			SELECT customercode AS id, CONCAT(customercode,' -- ',customername) AS val FROM customermaster WHERE activecustomer = 1 AND templateindicator = 0  
			AND customercode IN (SELECT customercode FROM routesequence WHERE routecode IN(SELECT routecode FROM routemaster WHERE templatename=var_user)); 
		END IF;
		
		END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_calculate_paging_data` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_calculate_paging_data` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_calculate_paging_data`(
in in_count int,
in in_limit int,
in in_page int,
out out_start_limit int
)
BEGIN
    DECLARE count1 int;
    DECLARE total_pages INT;
    
	set count1  = in_count;
	IF( count1 > 0 ) then 
		set total_pages = CEIL(count1/in_limit);
	ELSE 
		set total_pages = 0;
	end if;
	
	IF (in_page > total_pages) then 
	set in_page=total_pages;
	
	end if;
	set out_start_limit = in_limit * in_page - in_limit; 
        
    
    END */$$
DELIMITER ;

