/* Procedure structure for procedure `sp_report_dailyreport_routesummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routesummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routesummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
				FROM startendday sed, routemaster rm, salesman sm
				WHERE sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routekey, rm.routecode, rm.routename, CONCAT(rm.routecode,'-',rm.routename) AS routes, 
					sm.salesmancode, sm.salesmanname1, CONCAT(sm.salesmancode,'-', sm.salesmanname1) AS salesman,
					DATE_FORMAT(sed.routestartdate, '%d %b %Y') routestartdate, sed.routestarttime,DATE_FORMAT(sed.routeenddate, '%d %b %Y') routeenddate, sed.routeendtime, sed.routestartodometer, sed.routeendodometer, 
					COALESCE((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0 AND ih.totalsalesamount + ih.totalfreesampleamount + ih.totalmanualfree > 0), 0 ) totalinvdocuments, 
					COALESCE((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0 AND ih.totalsalesamount + ih.totalfreesampleamount + ih.totalmanualfree = 0), 0 ) totalinvretdocuments,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms < 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalcashsales, 
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms = 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalgcsales,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms > 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totaltcsales,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalinvoiceamount, 
					COALESCE((SELECT COUNT(arh.invoicenumber) FROM arheader arh WHERE arh.routekey = sed.routekey AND arh.amountpaid <> 0 AND arh.voidflag = 0), 0 ) totalardocuments, 
					COALESCE((SELECT SUM(arh.totalinvoiceamount) FROM arheader arh WHERE arh.routekey = sed.routekey AND arh.voidflag = 0), 0 ) totalacctsreceivable,
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE  ih.immediatepaid !=0 AND ccd.routekey = sed.routekey AND ccd.typecode = 0), 0)
					+
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 0), 0) totalcash,
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0)
					+
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0 ) totalchecks, 
					COALESCE((SELECT SUM(soh.totalinvoiceamount) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND soh.voidflag = 0), 0 ) totalorderamount,
					sed.totalexpenses, sed.cashvariance, sed.inventoryvariance
				 FROM startendday sed, routemaster rm,salesman sm 
				 WHERE sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode 
					  ",in_where, " ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	-- select @dyn_sql1;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routesummary_edit` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routesummary_edit` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routesummary_edit`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
				FROM startendday sed, routemaster rm, salesman sm
				WHERE sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routekey, rm.routecode, rm.routename, CONCAT(rm.routecode,'-',rm.routename) AS routes, 
					sm.salesmancode, sm.salesmanname1, CONCAT(sm.salesmancode,'-', sm.salesmanname1) AS salesman,sed.routestarttime, sed.routeendtime, 
					TIME_FORMAT(TIMEDIFF(CONCAT (DATE_FORMAT(routeenddate,'%Y-%m-%d'),' ',routeendtime),
					CONCAT (DATE_FORMAT(routestartdate,'%Y-%m-%d'),' ',routestarttime)),'%H:%i') AS actualworkinghrs,					
					sed.routestartodometer, sed.routeendodometer, 
					
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms < 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalcashsales, 
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms = 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalgcsales,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih INNER JOIN customermaster cm ON cm.customercode = ih.customercode AND cm.invoicepaymentterms > 2 WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totaltcsales,
					COALESCE((SELECT SUM(ih.totalinvoiceamount) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND ih.voidflag = 0), 0 ) totalinvoiceamount  , 
					
					COALESCE((SELECT COUNT(arh.invoicenumber) FROM arheader arh WHERE arh.routekey = sed.routekey AND arh.amountpaid <> 0 AND arh.voidflag = 0), 0 ) totalardocuments, 
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE  ih.immediatepaid !=0 AND ccd.routekey = sed.routekey AND ccd.typecode = 0), 0)
+
COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 0), 0) 
+
COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0)
+
COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0 ) totalacctsreceivable, 
					
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE  ih.immediatepaid !=0 AND ccd.routekey = sed.routekey AND ccd.typecode = 0), 0)
					+
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 0), 0) totalcash,
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN invoiceheader ih ON ih.routekey= ccd.routekey AND ih.visitkey = ccd.visitkey AND ih.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0)
					+
					COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd INNER JOIN arheader ar ON ar.routekey= ccd.routekey AND ar.visitkey = ccd.visitkey AND ar.voidflag = 0 WHERE ccd.routekey = sed.routekey AND ccd.typecode = 1), 0 ) totalchecks, 
					COALESCE((SELECT SUM(soh.totalinvoiceamount) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND soh.voidflag = 0), 0 ) totalorderamount
					
				 FROM startendday sed, routemaster rm,salesman sm 
				 WHERE sed.routecode = rm.routecode AND sed.salesmancode = sm.salesmancode 
					  ",in_where, " ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	-- select @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
 	EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dailyreport_routesyncstatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dailyreport_routesyncstatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dailyreport_routesyncstatus`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT
)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	
	SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
				FROM startendday sed, synclog rs, routemaster rm, salesman sm
				WHERE rs.routekey = sed.routekey AND rm.routecode = rs.routecode AND sm.salesmancode = rs.userid
				 ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT sed.routekey,rs.routecode, rm.routename, rs.userid, sm.salesmanname1, DATE_FORMAT(rs.syncdate, '%d %b %Y') as syncdate1,
					rs.synctime,IF(rs.synctype = '1','UPLOAD','DOWNLOAD') as synctype, 
					IF(rs.routeclosed = '0','LIVE','CLOSED') as routeclosed
				FROM startendday sed, synclog rs, routemaster rm, salesman sm
				WHERE rs.routekey = sed.routekey AND rm.routecode = rs.routecode AND sm.salesmancode = rs.userid
				    ",in_where, " ORDER BY ", in_orderby, " ",in_sort, " ",limit_val);
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

