BEGIN
CALL sp_combo_customermaster() ;
CALL `sp_combo_routemaster`();
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_itemgroupwisesales` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_itemgroupwisesales` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_itemgroupwisesales`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	SET @dyn_sql = CONCAT("
		SELECT
			count(*) INTO @in_counter
		FROM
			invoiceheader ih, invoicedetail id, routemaster rm, salesman sm,
			itemmaster im, itemgroup ig, submajorcategory smc, majorcategory mc
		WHERE
			ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND
			ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND ih.transactionkey = id.transactionkey AND
			id.itemcode = im.actualitemcode AND ig.itemgroupcode = im.itemgroupcode AND
			smc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = smc.majorcategorycode
	 ", in_where);
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	SET @dyn_sql = CONCAT("
		SELECT
			ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ih.actualtransactiondate,
			mc.majorcategorycode, mc.description majorcategory, im.reportitemcode itemcode, im.itemdescription, im.unitspercase,
			id.salesqty, (id.freesampleqty + id.manualfreeqty) freesampleqty, id.damagedqty,id.expiryqty, id.returnqty,
			(CAST(id.salesqty/im.unitspercase AS UNSIGNED) * id.salescaseprice) +
			(CASE WHEN id.salesqty % im.unitspercase <> 0 THEN id.salesqty % im.unitspercase ELSE 0 END * id.salesprice) sales_invprice,
			CASE WHEN id.salesqty > 0 THEN
			COALESCE((SELECT SUM(pd.promotionamount*pd.promotionquantity) FROM promotiondetail pd WHERE pd.routekey = ih.routekey AND pd.visitkey = ih.visitkey AND pd.itemcode = id.itemcode AND pd.promotiontypecode IN (1,2)), 0)
			ELSE 0 END itempromodiscount,
			CASE WHEN id.salesqty > 0 AND ((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) > 0 THEN
			ROUND(
			((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) /
			(ih.totalsalesamount /
			(
			(CAST(id.salesqty/im.unitspercase AS UNSIGNED) * id.salescaseprice) + (CASE WHEN id.salesqty % im.unitspercase <> 0 THEN id.salesqty % im.unitspercase ELSE 0 END * id.salesprice) -
			COALESCE((SELECT SUM(pd.promotionamount*pd.promotionquantity) FROM promotiondetail pd WHERE pd.routekey = id.routekey AND pd.visitkey = id.visitkey AND pd.itemcode = id.itemcode AND pd.promotiontypecode IN (1,2)), 0)
			)
			), 3)
			ELSE 0
			END invdiscountbreakup,
			-- coalesce ((select sum(pd.promotionquantity) from promotiondetail pd where pd.routekey = ih.routekey and pd.visitkey = ih.visitkey and pd.itemcode = id.itemcode and pd.promotiontypecode = 7), 0) promofree,
			0 promofree,
			(CAST((id.freesampleqty + id.manualfreeqty)/im.unitspercase AS UNSIGNED) * im.caseprice) +
			(CASE WHEN (id.freesampleqty + id.manualfreeqty) % im.unitspercase <> 0 THEN (id.freesampleqty + id.manualfreeqty) % im.unitspercase ELSE 0 END * im.defaultsalesprice) AS freegods_stdprice,
			(CAST(id.damagedqty/im.unitspercase AS UNSIGNED) * id.returncaseprice) +
			(CASE WHEN id.damagedqty % im.unitspercase <> 0 THEN id.damagedqty % im.unitspercase ELSE 0 END * id.returnprice) AS damagereturn_invprice,
			(CAST(id.expiryqty/im.unitspercase AS UNSIGNED) * id.returncaseprice) +
			(CASE WHEN id.expiryqty % im.unitspercase <> 0 THEN id.expiryqty % im.unitspercase ELSE 0 END * id.returnprice) AS expiryreturn_invprice,
			(CAST(id.returnqty/im.unitspercase AS UNSIGNED) * id.goodreturncaseprice) +
			(CASE WHEN id.returnqty % im.unitspercase <> 0 THEN id.returnqty % im.unitspercase ELSE 0 END * id.goodreturnprice) AS goodretun_invprice,
			rm.arbroutename,sm.arbsalesmanname1,mc.arbdescription,im.arbitemdescription
		FROM
			invoiceheader ih, invoicedetail id, routemaster rm, salesman sm,
			itemmaster im, itemgroup ig, submajorcategory smc, majorcategory mc
		WHERE
			ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND
			ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND ih.transactionkey = id.transactionkey AND
			id.itemcode = im.actualitemcode AND ig.itemgroupcode = im.itemgroupcode AND
			smc.submajorcategorycode = ig.submajorcategorycode AND mc.majorcategorycode = smc.majorcategorycode
		",in_where, orderby_val,limit_val) ;
  -- select @dyn_sql;	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_itemgroupwisesales_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_itemgroupwisesales_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_itemgroupwisesales_detail`()
BEGIN
	CALL sp_combo_routemaster() ;
	CALL sp_combo_majorcategory();
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_itemsalessummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_itemsalessummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_itemsalessummary`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(500),
	IN in_sort VARCHAR(50),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	
	SET @tablename = "tmp_itemsales_summary_report";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SELECT CODE INTO @damage FROM expiryreturnreasons WHERE UPPER(description) LIKE '%DAMAGE%' LIMIT 1;
	SELECT CODE INTO @expiry FROM expiryreturnreasons WHERE UPPER(description) LIKE '%EXPIRY%' LIMIT 1;
	
	SET @tmp = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT rm.alternateroutecode routecode, rm.routename, sm.alternatesalesmancode salesmancode, sm.salesmanname1, 
			ih.invoicenumber, ih.transactiondate, ih.totalinvoiceamount, ih.totalsalesamount, ih.totalreturnamount, ih.totaldamagedamount, 
			((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) invoicediscount, 
			cm.alternatecode customercode, cm.customername, mg.majorcategorycode, mg.description majorcategory, 
			ig.itemgroupcode, ig.itemgroupname, im.alternatecode itemcode, im.itemdescription, im.unitspercase upc, 
			id.salesqty, id.freesampleqty + id.manualfreeqty freesampleqty, 
			COALESCE(dmg.damagedqty, 0) damagedqty, COALESCE(exp.expiryqty, 0) expiryqty, COALESCE(oth.badqty, 0) badqty, id.returnqty, 
			id.salescaseprice, id.salesprice, id.returncaseprice, id.returnprice, id.goodreturncaseprice, id.goodreturnprice, 	
			id.stdsalescaseprice,  id.stdsalesprice, id.stdreturncaseprice, id.stdreturnprice, id.stdgoodreturncaseprice, id.stdgoodreturnprice, 
			im.caseprice, im.defaultsalesprice pcsprice, 	
			COALESCE(pd.linediscount,0) itempromodiscount, 
			rm.arbroutename, sm.arbsalesmanname1, cm.arbcustomername, ig.arbitemgroup, mg.arbdescription, im.arbitemdescription
		FROM 
			invoiceheader ih
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
			INNER JOIN routemaster rm ON rm.routecode = ih.routecode
			INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			INNER JOIN customermaster cm ON cm.customercode = ih.customercode
			INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
			INNER JOIN itemgroup ig ON ig.itemgroupcode = im.itemgroupcode
			INNER JOIN submajorcategory smc ON smc.submajorcategorycode = ig.submajorcategorycode 
			INNER JOIN majorcategory mg ON mg.majorcategorycode = smc.majorcategorycode
			
			LEFT OUTER JOIN (SELECT routekey, visitkey, itemcode, SUM(promotionamount*promotionquantity) linediscount 
				FROM promotiondetail WHERE promotiontypecode < 3 GROUP BY routekey, visitkey, itemcode) pd ON pd.routekey = id.routekey AND pd.visitkey = id.visitkey AND pd.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) damagedqty
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode = ", @damage," GROUP BY transactionkey, itemcode) dmg ON dmg.transactionkey = id.transactionkey AND dmg.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) expiryqty
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode = ", @expiry," GROUP BY transactionkey, itemcode) exp ON exp.transactionkey = id.transactionkey AND exp.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) badqty
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode NOT IN ( ", @expiry, ",", @damage,") GROUP BY transactionkey, itemcode) oth ON oth.transactionkey = id.transactionkey AND oth.itemcode = id.itemcode
		WHERE 
			1=1 ", in_where) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
	(SELECT COUNT(*) AS counter
	FROM tmp_itemsales_summary_report
	GROUP BY transactiondate, 	majorcategorycode, itemgroupcode, itemcode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @tmp = CONCAT("
		SELECT
			routecode, routename, salesmancode, salesmanname1, transactiondate,  
			majorcategorycode, majorcategory, itemgroupcode, itemgroupname, itemcode, itemdescription, upc, 
			SUM(salesqty) salesqty, SUM(freesampleqty) freesampleqty, SUM(returnqty) returnqty, 
			SUM(damagedqty) damagedqty, SUM(expiryqty) expiryqty, SUM(badqty) otherbadqty,
			SUM((FLOOR(salesqty/ upc) * stdsalescaseprice) + (CASE WHEN (salesqty MOD upc) <> 0 THEN (salesqty MOD upc) ELSE 0 END * stdsalesprice)) salesdefprice, 		
			SUM((FLOOR(salesqty/ upc) * salescaseprice) + (CASE WHEN (salesqty MOD upc) <> 0 THEN (salesqty MOD upc) ELSE 0 END * salesprice)) salesinvprice, 		
			SUM(((FLOOR(salesqty/ upc) * salescaseprice) + (CASE WHEN (salesqty MOD upc) <> 0 THEN (salesqty MOD upc) ELSE 0 END * salesprice)) - 
			((FLOOR(salesqty/ upc) * stdsalescaseprice) + (CASE WHEN (salesqty MOD upc) <> 0 THEN (salesqty MOD upc) ELSE 0 END * stdsalesprice))) pricediff,
			CASE WHEN salesqty > 0 THEN
			SUM(ROUND(invoicediscount / (totalsalesamount / ((FLOOR( salesqty/ upc) * salescaseprice) + (CASE WHEN (salesqty MOD upc) <> 0 THEN (salesqty MOD upc) ELSE 0 END * salesprice) - itempromodiscount)), 3))
			ELSE 0 END invdiscountbreakup, 
			CASE WHEN salesqty > 0 THEN SUM(itempromodiscount) ELSE 0 END itempromodiscount, 
			SUM((FLOOR(freesampleqty/ upc) * stdsalescaseprice) + (CASE WHEN (freesampleqty MOD upc) <> 0 THEN (freesampleqty MOD upc) ELSE 0 END * stdsalesprice)) AS freegodsstdprice, 			 
			SUM((FLOOR(damagedqty/ upc) * stdreturncaseprice) + (CASE WHEN (damagedqty MOD upc) <> 0 THEN (damagedqty MOD upc) ELSE 0 END * stdreturnprice)) AS damagestdprice, 
			SUM((FLOOR(damagedqty/ upc) * returncaseprice) + (CASE WHEN (damagedqty MOD upc) <> 0 THEN (damagedqty MOD upc) ELSE 0 END * returnprice)) AS damageinvprice, 	
			SUM((FLOOR(expiryqty/ upc) * stdreturncaseprice) + (CASE WHEN (expiryqty MOD upc) <> 0 THEN (expiryqty MOD upc) ELSE 0 END * stdreturnprice)) AS expirystdprice, 
			SUM((FLOOR(expiryqty/ upc) * returncaseprice) + (CASE WHEN (expiryqty MOD upc) <> 0 THEN (expiryqty MOD upc) ELSE 0 END * returnprice)) AS expiryinvprice, 			 
			SUM((FLOOR(badqty/ upc) * stdreturncaseprice) + (CASE WHEN (badqty MOD upc) <> 0 THEN (badqty MOD upc) ELSE 0 END * stdreturnprice)) AS otherdamgestdprice, 
			SUM((FLOOR(badqty/ upc) * returncaseprice) + (CASE WHEN (badqty MOD upc) <> 0 THEN (badqty MOD upc) ELSE 0 END * returnprice)) AS otherdamgeinvprice, 			 		 
			SUM((FLOOR(returnqty/ upc) * stdgoodreturncaseprice) + (CASE WHEN (returnqty MOD upc) <> 0 THEN (returnqty MOD upc) ELSE 0 END * stdgoodreturnprice)) AS goodretunstdprice,
			SUM((FLOOR(returnqty/ upc) * goodreturncaseprice) + (CASE WHEN (returnqty MOD upc) <> 0 THEN (returnqty MOD upc) ELSE 0 END * goodreturnprice)) AS goodretuninvprice,
			SUM((FLOOR(salesqty/ upc) * salescaseprice) + (CASE WHEN (salesqty MOD upc) <> 0 THEN (salesqty MOD upc) ELSE 0 END * salesprice)) - 
				SUM((FLOOR(damagedqty/ upc) * returncaseprice) + (CASE WHEN (damagedqty MOD upc) <> 0 THEN (damagedqty MOD upc) ELSE 0 END * returnprice)) - 	
				SUM((FLOOR(expiryqty/ upc) * returncaseprice) + (CASE WHEN (expiryqty MOD upc) <> 0 THEN (expiryqty MOD upc) ELSE 0 END * returnprice)) - 			 
				SUM((FLOOR(badqty/ upc) * returncaseprice) + (CASE WHEN (badqty MOD upc) <> 0 THEN (badqty MOD upc) ELSE 0 END * returnprice)) AS netsalesinvprice, 			 		 
			arbroutename, arbsalesmanname1, arbitemgroup, arbdescription, arbitemdescription
		FROM ", @tablename, "
		GROUP BY transactiondate, routecode, majorcategorycode, itemgroupcode, itemcode
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_kpi_averagedropsize` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_kpi_averagedropsize` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_kpi_averagedropsize`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	SET @dyn_sql = CONCAT("SELECT COUNT(t1.cnt) INTO @in_counter FROM (SELECT count(*) as cnt FROM
					kpi_averagedropsize
				WHERE
					routecode IN (SELECT routecode FROM routemaster WHERE activestatus = 1) ", in_where,"
				GROUP BY
					DATE_FORMAT(routestartdate,'%M'), YEAR(routestartdate), MONTH(routestartdate),
					 routecode, routename, salesmancode, salesmanname1) AS t1 ");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	
	
	SET @dyn_sql = CONCAT("SELECT 
					DATE_FORMAT(routestartdate,'%M') AS `date`,
					YEAR(routestartdate) AS `tempyear`,
					MONTH(routestartdate) AS `tempmonth`,
					DATE_FORMAT(routestartdate, '%m') AS txtmonth,
					-- CONCAT(CAST(routecode AS CHAR) ,' - ', routename) AS route,
					-- CONCAT(CAST(salesmancode AS CHAR) ,' - ', salesmanname1) AS salesman,
					CAST(routecode AS CHAR) as routecode,routename,
					CAST(salesmancode AS CHAR) as salesmancode,salesmanname1,
					IFNULL(SUM(totalinvoices),0) AS no_of_invoice,
					IFNULL(SUM(salesqty),0) AS sale_qty,
					IFNULL(SUM(freeqty),0) AS free_qty,
					IFNULL(SUM(promoqty),0) AS promo_qty,
					IFNULL(SUM(returnqty),0) AS return_qty,
					IFNULL(SUM(damageqty),0) AS buyback_qty,
					IFNULL(SUM(netinvoiceamt),0) AS net_sales,
					IFNULL(SUM(salesqty)/ CASE WHEN SUM(totalinvoices) = 0 THEN 1 ELSE SUM(totalinvoices) END,0) AS qty_drop_size,
					IFNULL(SUM(netinvoiceamt) / CASE WHEN SUM(totalinvoices) = 0 THEN 1 ELSE SUM(totalinvoices) END,0) AS value_drop_size
				FROM
					kpi_averagedropsize
				WHERE
					routecode IN (SELECT routecode FROM routemaster WHERE activestatus = 1) ",in_where," 
				GROUP BY
					DATE_FORMAT(routestartdate,'%M'), YEAR(routestartdate), MONTH(routestartdate),
					 routecode, routename, salesmancode, salesmanname1 ", orderby_val,limit_val) ;
  -- select @dyn_sql;	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_kpi_sales_productivity` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_kpi_sales_productivity` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_kpi_sales_productivity`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE orderby_val TEXT DEFAULT "";
DECLARE limit_val TEXT DEFAULT "";
	IF in_where = 1 THEN 
		SET @dyn_sql = CONCAT("SELECT YEAR(ih.transactiondate) yearno
					FROM invoiceheader ih, salesman sm
					WHERE ih.salesmancode = sm.salesmancode AND ih.voidflag = 0", in_where,"
					GROUP BY YEAR(ih.transactiondate)  ORDER BY yearno");
		PREPARE s1 FROM @dyn_sql;
		EXECUTE s1;
	ELSE
		SELECT COUNT(t1.cnt) INTO @in_counter FROM (SELECT COUNT(*) AS cnt
		FROM invoiceheader ih, salesman sm
		WHERE ih.salesmancode = sm.salesmancode AND ih.voidflag = 0
		GROUP BY YEAR(ih.transactiondate), sm.salesmancode) AS t1;
		
		IF in_limit != "" && in_page != "" THEN 
			CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
			SELECT @new_start_limit AS start_limit,@in_counter AS counter;
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
		IF in_orderby != "" && in_sort != "" THEN
			SET orderby_val = CONCAT(in_orderby," ",in_sort, ",");
		END IF;
		
		
		SET @dyn_sql = CONCAT("SELECT YEAR(ih.transactiondate) yearno, sm.salesmancode, sm.salesmanname1,sm.arbsalesmanname1,
						SUM(ih.totalinvoiceamount) salesamount
					FROM invoiceheader ih, salesman sm
					WHERE ih.salesmancode = sm.salesmancode AND ih.voidflag = 0", in_where,"
					GROUP BY YEAR(ih.transactiondate), sm.salesmancode ORDER BY ",orderby_val," yearno asc ",limit_val);
		-- select @dyn_sql;
		 PREPARE s1 FROM @dyn_sql;
		 EXECUTE s1;
	END IF;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_kpi_strikerate_callrate_avgtime` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_kpi_strikerate_callrate_avgtime` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_kpi_strikerate_callrate_avgtime`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
	DECLARE orderby_val TEXT DEFAULT "";
	DECLARE limit_val TEXT DEFAULT "";
	
	CALL sp_report_dataanalysis_kpi_temp();
	
	SET @new_start_limit = 0;
	SET @dyn_sql = CONCAT("SELECT count(t1.cnt) INTO @in_counter FROM (SELECT count(*) as cnt FROM kpi_temp ", in_where, " 
		GROUP BY YEAR(routestartdate), MONTH(routestartdate), DATE_FORMAT(routestartdate,'%M'), routecode, routename, salesmancode, salesman) as t1 ");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	 
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		
		IF @new_start_limit >= 0 THEN 
			SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
		END IF;
	END IF;
	IF in_orderby != "" && in_sort != "" THEN
		SET orderby_val = CONCAT( " ORDER BY ",in_orderby," ",in_sort);
	END IF;
	SET @dyn_sql = CONCAT("
	SELECT
		YEAR(routestartdate) AS tranyear,
		MONTH(routestartdate) AS tranmonthno,
		DATE_FORMAT(routestartdate,'%M') AS tranmonthtxt,
		routecode AS routecode,
		-- CONCAT(CAST(routecode AS CHAR) , ' - ' , routename) AS route,
		-- CONCAT(CAST(salesmancode AS CHAR) , ' - ' , salesman) AS salesman,
		CAST(routecode AS CHAR) AS routecode,
		routename,arbroutename,
		CAST(salesmancode AS CHAR) as salesmancode,
		salesman,arbsalesmanname,		
		SUM(totalsheduled) AS targetto_visit,
		SUM(totalvisited) AS targetvisits,
		SUM(totalsheduled) - SUM(totalvisited) AS callexceptions,
		SUM(totalunsheduledvisit) AS non_targetvisits,
		SUM(totalvisited) + SUM(totalunsheduledvisit) AS totalvisits,
		SUM(totalsheduledsale) AS schedulesale,
		SUM(totalunsheduledsale) AS unsched_sale,
		SUM(totalshedulednosale) AS schedulenosale,
		SUM(totalunshedulednosale) AS unschedulenosale,
		SUM(totalsheduledsale) + SUM(totalunsheduledsale) AS effectivevisit,
		((SUM(totalsheduledsale) + SUM(totalunsheduledsale)) * 100) /
		SUM(CASE WHEN (totalvisited + totalunsheduledvisit) = 0 THEN 1 ELSE (totalvisited + totalunsheduledvisit) END) AS strikerate,
		(SUM(totalvisited) * 100) /
		SUM(CASE WHEN totalsheduled = 0 THEN 1 ELSE totalsheduled END) AS callcomp,
		(SUM(totalvisited) * 100) /
		SUM(CASE WHEN (totalvisited + totalunsheduledvisit) = 0 THEN 1 ELSE (totalvisited + totalunsheduledvisit) END) AS discipline,
		MIN(routestartodometer) AS startkms,
		MAX(routeendodometer) AS endkms,
		CASE WHEN MAX(routeendodometer) - MIN(routestartodometer) < 0 THEN 0 ELSE MAX(routeendodometer) - MIN(routestartodometer) END AS kms_covered,
		MAX(CAST(routetimespendinminutes AS TIME)) AS averagein_out_time
	FROM
		kpi_temp
	",in_where,"
	GROUP BY
		YEAR(routestartdate), MONTH(routestartdate), DATE_FORMAT(routestartdate,'%M'),
		routecode, routename, salesmancode, salesman ", orderby_val,limit_val) ;
  -- select @dyn_sql;	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_dataanalysis_kpi_temp` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_dataanalysis_kpi_temp` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_dataanalysis_kpi_temp`(
)
BEGIN
	SET @dyn_sql = CONCAT("DROP TABLE kpi_temp");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	SET @dyn_sql = CONCAT("
		CREATE TABLE kpi_temp
		SELECT  
				sed.routestartdate, sed.routeenddate, 
				dm.depotcode, dm.depotname, am.areacode, am.areaname, sam.subareacode, sam.subareaname, 
				sed.routecode, rm.routename, rm.alternateroutecode, rm.arbroutename, 
				sed.salesmancode, sm.salesmanname1 AS salesman, sm.alternatesalesmancode, sm.arbsalesmanname1 arbsalesmanname,
				sed.routeendodometer, sed.routestartodometer, 
				CASE WHEN (sed.routeendodometer - sed.routestartodometer) < 0 THEN 0 ELSE (sed.routeendodometer - sed.routestartodometer) END AS routekmcovered,
				COALESCE (totaltime.routetime, '00:00:00') AS routetimespendinminutes,		
				COALESCE (total_sheduled.totalcust, 0) AS totalsheduled, 		
				COALESCE (total_visited.totalcust, 0) AS totalvisited,
				(SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
					COALESCE (total_unsheduled_visit.totalcust, 0) AS totalunsheduledvisit,			
				COALESCE (total_sheduled_sale.totalcust, 0) AS totalsheduledsale, 
				(SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
					COALESCE (total_unsheduled_sale.totalcust, 0) AS totalunsheduledsale,			 
				COALESCE (total_sheduled_nosale.totalcust, 0) AS totalshedulednosale,
				COALESCE (total_unsheduled_nosale.totalcust, 0) AS totalunshedulednosale,		
				COALESCE (total_unscanned.totalunscan, 0) AS totalunscannedcust,		
				COALESCE (totalcashsale.noofinv, 0) AS totalcashsale,
				COALESCE (totalcreditsale.noofinv, 0) AS totalcreditsale,		
				CASE WHEN COALESCE (total_sheduled.totalcust, 0) > 0 THEN
					CAST(COALESCE (totalcashsale.noofinv, 0) + COALESCE (totalcreditsale.noofinv, 0) AS DECIMAL)/ CAST(COALESCE (total_sheduled.totalcust, 0) AS DECIMAL) * 100
				ELSE
					0
				END AS strikerate,		
				CASE WHEN COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0) > 0 THEN
					CAST(COALESCE (totalcashsale.noofinv, 0) + COALESCE (totalcreditsale.noofinv, 0) AS DECIMAL) / CAST(COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0) AS DECIMAL) * 100
				ELSE
					0
				END AS productivity	
			FROM 
				startendday sed
				INNER JOIN routemaster rm ON sed.routecode = rm.routecode
				INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
				INNER JOIN subareamaster sam ON rm.subareacode = sam.subareacode
				INNER JOIN areamaster am ON sam.areacode = am.areacode
				INNER JOIN depotmaster dm ON am.depotcode = dm.depotcode
				LEFT OUTER JOIN
					(SELECT rsc.routekey, rsc.routecode, COUNT(rsc.customercode) AS totalcust FROM routesequencecustomerstatus rsc 
						WHERE (rsc.schelduledflag = 1) 
						GROUP BY rsc.routekey, rsc.routecode) AS total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
				LEFT OUTER JOIN
					(SELECT vis.routekey, vis.routecode, COUNT(vis.customercode) AS totalcust FROM routesequencecustomerstatus vis 
						WHERE (vis.schelduledflag = 1) AND (vis.servicedflag <> 0) 
						GROUP BY vis.routekey, vis.routecode) AS total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
				LEFT OUTER JOIN
					(SELECT visout.routekey, visout.routecode, COUNT(visout.customercode) AS totalcust FROM routesequencecustomerstatus visout 
						WHERE (visout.schelduledflag = 0) AND (visout.servicedflag <> 0) 
						GROUP BY visout.routekey, visout.routecode) AS total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
				LEFT OUTER JOIN
					(SELECT sale.routekey, sale.routecode, COUNT(sale.customercode) AS totalcust FROM routesequencecustomerstatus sale 
						WHERE (sale.schelduledflag = 1) AND (sale.servicedflag = 1) 
						GROUP BY sale.routekey, sale.routecode) AS total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode 
				LEFT OUTER JOIN
					(SELECT sale.routekey, sale.routecode, COUNT(sale.customercode) AS totalcust FROM routesequencecustomerstatus sale 
						WHERE (sale.schelduledflag = 0) AND (sale.servicedflag = 1) 
						GROUP BY sale.routekey, sale.routecode) AS total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
				LEFT OUTER JOIN
					(SELECT nsale.routekey, nsale.routecode, COUNT(nsale.customercode) AS totalcust FROM routesequencecustomerstatus nsale 
						WHERE (nsale.schelduledflag = 1) AND (nsale.servicedflag = 2) 
						GROUP BY nsale.routekey, nsale.routecode) AS total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
				LEFT OUTER JOIN
					(SELECT nsale.routekey, nsale.routecode, COUNT(nsale.customercode) AS totalcust FROM routesequencecustomerstatus nsale 
						WHERE (nsale.schelduledflag = 0) AND (nsale.servicedflag = 2) 
						GROUP BY nsale.routekey, nsale.routecode) AS total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
				LEFT OUTER JOIN
					(SELECT nsale.routekey, nsale.routecode, COUNT(nsale.customercode) AS totalunscan FROM routesequencecustomerstatus nsale 
						WHERE (nsale.servicedflag <> 0) AND (nsale.scannedflag = 0) 
						GROUP BY nsale.routekey, nsale.routecode) AS total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
				LEFT OUTER JOIN
					(SELECT ih.routekey, ih.routecode, TIMEDIFF(MAX(CAST(visitendtime AS TIME)),MIN(CAST(visitstarttime AS TIME))) AS routetime FROM customeroperationscontrol ih 
						GROUP BY ih.routekey, ih.routecode) AS totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
				LEFT OUTER JOIN
					(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM invoiceheader ih 
						WHERE (ih.immediatepaid != 0) AND (ih.voidflag = 0) 
						GROUP BY ih.routekey, ih.routecode) AS totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
				LEFT OUTER JOIN
					(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM invoiceheader ih 
						WHERE (ih.immediatepaid = 0) AND (ih.voidflag = 0) 
						GROUP BY ih.routekey, ih.routecode) AS totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode	
			");
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;	
	 
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_data_item_distribution` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_data_item_distribution` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_data_item_distribution`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM 
		invoiceheader ih, invoicedetail id, customermaster cm, routemaster rm, salesman sm, categorymaster cg,
		itemmaster im, itemgroup ig, submajorcategory smc, majorcategory mc
	WHERE 
		ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND cm.customercategory = cg.categoryid AND 
		id.itemcode = im.actualitemcode AND im.itemgroupcode = ig.itemgroupcode AND ig.submajorcategorycode = smc.submajorcategorycode AND
		smc.majorcategorycode = mc.majorcategorycode", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT 
		DATE_FORMAT(ih.actualtransactiondate,'%Y') YEAR, DATE_FORMAT(ih.actualtransactiondate,'%m') monthno, DATE_FORMAT(ih.actualtransactiondate,'%M') monthtxt, 
		ih.actualtransactiondate, cm.customercategory, cg.categoryname, 
		cm.reportcustcode customercode, cm.customername, ih.routecode, rm.routename, ih.salesmancode, sm.salesmanname1, ih.invoicenumber,  
		ih.totalsalesamount, ih.totalreturnamount, ih.totaldamagedamount, ih.totalexpiryamount,
		(ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount invoicediscount, 
		ih.totalinvoiceamount, (ih.totalmanualfree + ih.totalfreesampleamount) totalfreesampleamount,
		mc.majorcategorycode, mc.description majorcategory, im.reportitemcode itemcode, im.itemdescription,  
		
		id.salesqty,
		(CAST(id.salesqty/im.unitspercase AS UNSIGNED) * id.salescaseprice) + 
			(CASE WHEN id.salesqty % im.unitspercase <> 0 THEN (id.salesqty % im.unitspercase) * id.salesprice ELSE 0 END) AS salesvalue,
		
		id.returnqty,
		(CAST(id.returnqty/im.unitspercase AS UNSIGNED) * id.goodreturncaseprice) + 
			(CASE WHEN id.returnqty % im.unitspercase <> 0 THEN (id.returnqty % im.unitspercase) * id.goodreturnprice ELSE 0 END) AS returnvalue,
		
		id.damagedqty,
		(CAST(id.damagedqty/im.unitspercase AS UNSIGNED) * id.returncaseprice) + 
			(CASE WHEN id.damagedqty % im.unitspercase <> 0 THEN (id.damagedqty % im.unitspercase) * id.returnprice ELSE 0 END) AS damagevalue,
		
		id.expiryqty,
		(CAST(id.expiryqty/im.unitspercase AS UNSIGNED) * id.returncaseprice) + 
			(CASE WHEN id.expiryqty % im.unitspercase <> 0 THEN (id.expiryqty % im.unitspercase) * id.returnprice ELSE 0 END) AS expiredvalue,
		
		id.freesampleqty + id.manualfreeqty freesampleqty,
		(CAST((id.freesampleqty + id.manualfreeqty)/im.unitspercase AS UNSIGNED) * im.caseprice) + 
			(CASE WHEN (id.freesampleqty + id.manualfreeqty) % im.unitspercase <> 0 THEN ((id.freesampleqty + id.manualfreeqty) % im.unitspercase) * im.defaultsalesprice ELSE 0 END) AS freevalue,
		
		CASE WHEN id.salesqty > 0 THEN
				COALESCE((SELECT SUM(pd.promotionamount*pd.promotionquantity) FROM promotiondetail pd WHERE pd.routekey = id.routekey AND pd.visitkey = id.visitkey AND pd.itemcode = id.itemcode AND pd.promotiontypecode IN (1,2)), 0)
			ELSE 0 END itempromodiscount,
		
		CASE WHEN id.salesqty > 0 AND ((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) > 0 THEN 
			ROUND(
				((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) / 
				(ih.totalsalesamount / 
				(
				(CAST(id.salesqty/im.unitspercase AS UNSIGNED) * id.salescaseprice) + (CASE WHEN id.salesqty % im.unitspercase <> 0 THEN id.salesqty % im.unitspercase ELSE 0 END * id.salesprice) - 
				COALESCE((SELECT SUM(pd.promotionamount*pd.promotionquantity) FROM promotiondetail pd WHERE pd.routekey = id.routekey AND pd.visitkey = id.visitkey AND pd.itemcode = id.itemcode AND pd.promotiontypecode IN (1,2)), 0)
				)
				), 3)
			ELSE 0 
				END invdiscountbreakup,
						
		id.salescaseprice, id.salesprice, id.goodreturncaseprice, id.goodreturnprice, id.returncaseprice, id.returnprice,
		cm.arbcustomername,rm.arbroutename,im.arbitemdescription,mc.arbdescription,cg.arbcategoryname
	FROM 
		invoiceheader ih, invoicedetail id, customermaster cm, routemaster rm, salesman sm, categorymaster cg,
		itemmaster im, itemgroup ig, submajorcategory smc, majorcategory mc
	WHERE 
		ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND cm.customercategory = cg.categoryid AND 
		id.itemcode = im.actualitemcode AND im.itemgroupcode = ig.itemgroupcode AND ig.submajorcategorycode = smc.submajorcategorycode AND
		smc.majorcategorycode = mc.majorcategorycode",in_where, " ORDER BY ",in_orderby," ",in_sort, " ",limit_val) ;
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_data_item_distributionmonthly` */

