/* Procedure structure for procedure `sp_report_data_monthly_revenue` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_data_monthly_revenue` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_data_monthly_revenue`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM (SELECT ih.routecode FROM invoiceheader AS ih, routemaster AS rm, salesman AS sm
WHERE
	ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND
	(ih.voidflag = 0)", in_where," GROUP BY 
	rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
	DATE_FORMAT(ih.transactiondate,'%Y'), DATE_FORMAT(ih.transactiondate,'%m'),  DATE_FORMAT(ih.transactiondate,'%M')) as cnt");
	 PREPARE s1 FROM @dyn_sql;
 	 EXECUTE s1;
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("SELECT
	rm.routecode, rm.routename, 
	sm.salesmancode, sm.salesmanname1,
	DATE_FORMAT(ih.transactiondate,'%Y') AS noyear, 
	DATE_FORMAT(ih.transactiondate,'%m') AS nomonth, DATE_FORMAT(ih.transactiondate,'%M') AS txtmonth, 
	COALESCE(SUM(ih.totalinvoiceamount), 0) AS salesamt,
	rm.arbroutename
FROM         
	invoiceheader AS ih, routemaster AS rm, salesman AS sm
WHERE
	ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND
	(ih.voidflag = 0)",in_where, " GROUP BY 
	rm.routecode, rm.routename, sm.salesmancode, sm.salesmanname1, 
	DATE_FORMAT(ih.transactiondate,'%Y'), DATE_FORMAT(ih.transactiondate,'%m'),  DATE_FORMAT(ih.transactiondate,'%M') ORDER BY ",in_orderby," ",in_sort, "",limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_data_sales_free_summary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_data_sales_free_summary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_data_sales_free_summary`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(500),
	IN in_sort VARCHAR(50),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	
	SET @tablename = "tmp_sales_free_summary_report";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SET @tmp = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT rm.alternateroutecode routecode, rm.routename, sm.alternatesalesmancode salesmancode, sm.salesmanname1, 
			ih.invoicenumber, ih.transactiondate, ih.totalinvoiceamount, ih.totalsalesamount, ih.totalreturnamount, ih.totaldamagedamount, 
			((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount) invoicediscount, 
			cm.alternatecode customercode, cm.customername, mg.majorcategorycode, mg.description majorcategory, 
			ig.itemgroupcode, ig.itemgroupname, im.alternatecode itemcode, im.itemdescription, im.unitspercase upc, 
			id.salesqty, id.freesampleqty + id.manualfreeqty freesampleqty, id.damagedqty, id.expiryqty, id.returnqty, 
			id.salescaseprice, id.salesprice, id.returncaseprice, id.returnprice, id.goodreturncaseprice, id.goodreturnprice, 	
			id.stdsalescaseprice,  id.stdsalesprice, id.stdreturncaseprice, id.stdreturnprice, id.stdgoodreturncaseprice, id.stdgoodreturnprice, 
			im.caseprice, im.defaultsalesprice pcsprice, 	
			COALESCE(pd.linediscount,0) itempromodiscount, 
			rm.arbroutename, sm.arbsalesmanname1, cm.arbcustomername, ig.arbitemgroup, mg.arbdescription, im.arbitemdescription
		FROM 
			invoiceheader ih
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
			INNER JOIN routemaster rm ON rm.routecode = ih.routecode
			INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			INNER JOIN customermaster cm ON cm.customercode = ih.customercode
			INNER JOIN itemmaster im ON im.actualitemcode = id.itemcode
			INNER JOIN itemgroup ig ON ig.itemgroupcode = im.itemgroupcode
			INNER JOIN submajorcategory smc ON smc.submajorcategorycode = ig.submajorcategorycode 
			INNER JOIN majorcategory mg ON mg.majorcategorycode = smc.majorcategorycode
			LEFT OUTER JOIN (SELECT routekey, visitkey, itemcode, SUM(pd.promotionamount*pd.promotionquantity) linediscount 
				FROM promotiondetail pd WHERE promotiontypecode IN (1, 2) GROUP BY routekey, visitkey, itemcode) pd ON pd.routekey = id.routekey AND pd.visitkey = id.visitkey AND pd.itemcode = id.itemcode
		WHERE 
			1=1 ", in_where) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
	(SELECT COUNT(*) AS counter
	FROM tmp_sales_free_summary_report
	GROUP BY routecode, routename, transactiondate, majorcategorycode, itemgroupcode, itemcode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @tmp = CONCAT("
		SELECT 
			routecode, routename, salesmancode, salesmanname1, transactiondate,  
			majorcategorycode, majorcategory, itemgroupcode, itemgroupname, itemcode, itemdescription, upc, 		
			SUM(salesqty) salesqty, SUM(freesampleqty) freesampleqty, SUM(damagedqty) damagedqty, SUM(returnqty) returnqty, 	 
			SUM((CAST( salesqty/ upc AS UNSIGNED) * stdsalescaseprice) + (CASE WHEN salesqty % upc <> 0 THEN salesqty % upc ELSE 0 END * stdsalesprice)) salesdefprice, 		
			SUM((CAST( salesqty/ upc AS UNSIGNED) * salescaseprice) + (CASE WHEN salesqty % upc <> 0 THEN salesqty % upc ELSE 0 END * salesprice)) salesinvprice, 	
			
			SUM(((CAST( salesqty/ upc AS UNSIGNED) * stdsalescaseprice) + (CASE WHEN salesqty % upc <> 0 THEN salesqty % upc ELSE 0 END * stdsalesprice)) -		
			((CAST( salesqty/ upc AS UNSIGNED) * salescaseprice) + (CASE WHEN salesqty % upc <> 0 THEN salesqty % upc ELSE 0 END * salesprice))) pricediff, 	
			
			CASE WHEN salesqty > 0 THEN
				SUM(ROUND(invoicediscount / (totalsalesamount / ((CAST( salesqty/ upc AS UNSIGNED) * salescaseprice) + (CASE WHEN salesqty % upc <> 0 THEN salesqty % upc ELSE 0 END * salesprice) - itempromodiscount)), 3))
			ELSE 0 END invdiscountbreakup, 
			
			CASE WHEN salesqty > 0 THEN SUM(itempromodiscount) ELSE 0 END itempromodiscount, 
			SUM((CAST(( freesampleqty)/ upc AS UNSIGNED) * stdsalescaseprice) + (CASE WHEN ( freesampleqty) % upc <> 0 THEN ( freesampleqty) % upc ELSE 0 END * stdsalesprice)) AS freegodsstdprice, 			 
			SUM((CAST( damagedqty/ upc AS UNSIGNED) * stdreturncaseprice) + (CASE WHEN damagedqty % upc <> 0 THEN damagedqty % upc ELSE 0 END * stdreturnprice)) AS damagestdprice, 
			SUM((CAST( damagedqty/ upc AS UNSIGNED) * returncaseprice) + (CASE WHEN damagedqty % upc <> 0 THEN damagedqty % upc ELSE 0 END * returnprice)) AS damageinvprice, 			 
			SUM((CAST( returnqty/ upc AS UNSIGNED) * stdgoodreturncaseprice) + (CASE WHEN returnqty % upc <> 0 THEN returnqty % upc ELSE 0 END * stdgoodreturnprice)) AS goodretunstdprice,
			SUM((CAST( returnqty/ upc AS UNSIGNED) * goodreturncaseprice) + (CASE WHEN returnqty % upc <> 0 THEN returnqty % upc ELSE 0 END * goodreturnprice)) AS goodretuninvprice,
			
			SUM(salesqty) - SUM(damagedqty) - SUM(returnqty) netqty, 
			SUM((CAST( salesqty/ upc AS UNSIGNED) * salescaseprice) + (CASE WHEN salesqty % upc <> 0 THEN salesqty % upc ELSE 0 END * salesprice)) -
				SUM((CAST( damagedqty/ upc AS UNSIGNED) * returncaseprice) + (CASE WHEN damagedqty % upc <> 0 THEN damagedqty % upc ELSE 0 END * returnprice)) -
				SUM((CAST( returnqty/ upc AS UNSIGNED) * goodreturncaseprice) + (CASE WHEN returnqty % upc <> 0 THEN returnqty % upc ELSE 0 END * goodreturnprice)) netamount, 
			
			
			arbroutename, arbsalesmanname1, arbitemgroup, arbdescription, arbitemdescription
		FROM ", @tablename, "
		GROUP BY routecode, routename, salesmancode, salesmanname1, transactiondate,  
			majorcategorycode, majorcategory, itemgroupcode, itemgroupname, itemcode, itemdescription, upc
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_data_sales_free_summary_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_data_sales_free_summary_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_data_sales_free_summary_detail`()
BEGIN
CALL sp_combo_routemaster() ;
	CALL sp_combo_itemmaster();
	CALL sp_combo_majorcategory();
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_distributioncheck_distributionchechsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_distributioncheck_distributionchechsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_distributioncheck_distributionchechsummary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";
    -- SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM invoiceheader ih, customermaster cm, routemaster rm, salesman sm
	-- WHERE 
	-- 	cm.customercode = ih.customercode AND rm.routecode = ih.routecode AND sm.salesmancode = ih.salesmancode", in_where);
	SET @dyn_sql = CONCAT("SELECT
				  COUNT(*) INTO @in_counter
				FROM customeroperationscontrol coc
				  JOIN `customerinventorycheck` cid
				    ON cid.routekey = coc.routekey
				      AND cid.visitkey = coc.visitkey
				  LEFT JOIN itemmaster im
				    ON im.actualitemcode = cid.itemcode
				  LEFT JOIN distributioncheckdetail dcd
				    ON dcd.itemcode = cid.itemcode
				  LEFT JOIN startendday sed
				    ON sed.routekey = coc.routekey
				      AND sed.routecode = coc.routecode
				WHERE 1 = 1
				", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	-- SET @dyn_sql = CONCAT("SELECT DATE_FORMAT(ih.actualtransactiondate, '%d %b %Y') AS transactiondate, ih.routecode, rm.routename, rm.arbroutename, ih.salesmancode, sm.salesmanname1,  sm.arbsalesmanname1,
	-- 	ih.transactiontime, cm.reportcustcode customercode, cm.customername,cm.arbcustomername, ih.invoicenumber,	ih.totalinvoiceamount,
	-- 	CASE WHEN ih.paymenttype < 2 THEN 'CASH' WHEN ih.paymenttype = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
	-- 	CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
	-- 	CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '-' END honame,
	-- 	CASE WHEN cm.type = 1 THEN 'NORMAL CUSTOMERS' WHEN cm.type = 2 THEN (SELECT cm1.arbcustomername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '-' END arbhoname,
	-- 	COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd WHERE ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND ccd.hhctransactionkey = ih.hhctransactionkey AND ccd.typecode = 1), 0) AS immediatecash,
	-- 	COALESCE((SELECT SUM(ccd.amount) FROM cashcheckdetail ccd WHERE ccd.routekey = ih.routekey AND ccd.visitkey = ih.visitkey AND ccd.hhctransactionkey = ih.hhctransactionkey AND ccd.typecode = 2), 0) AS immediatecheck,
	-- 	COALESCE((SELECT SUM(ard.amountpaid) FROM ardetail ard WHERE ard.alternateinvoicenumber = CAST(ih.invoicenumber AS CHAR)), 0) AS artotalpaid,
	-- 	COALESCE((SELECT SUM(ard.amountpaid) FROM ardetail ard, cashcheckdetail ccd WHERE ard.routekey = ccd.routekey AND ard.visitkey = ccd.visitkey AND ccd.typecode = 1 AND ard.invoicenumber = ih.invoicenumber AND COALESCE(ard.chequestatusindicator, 0) = 0), 0) arcash,
	-- 	COALESCE((SELECT SUM(ard.amountpaid) FROM ardetail ard, cashcheckdetail ccd WHERE ard.routekey = ccd.routekey AND ard.visitkey = ccd.visitkey AND ccd.typecode = 2 AND ard.invoicenumber = ih.invoicenumber AND COALESCE(ard.chequestatusindicator, 0) = 0), 0) archeck
	-- FROM 
	-- 	invoiceheader ih, customermaster cm, routemaster rm, salesman sm
	-- WHERE 
	-- 	cm.customercode = ih.customercode AND rm.routecode = ih.routecode AND sm.salesmancode = ih.salesmancode",in_where, " ORDER BY ",in_orderby," ",in_sort,limitval) ;
	SET @dyn_sql = CONCAT("SELECT
				  coc.routecode,
				  im.alternatecode actualitemcode,
				  im.itemdescription,
				  FORMAT(im.defaultsalesprice,2) AS defaultsalesprice,
				  FORMAT(im.caseprice,2) AS caseprice,
				  dcd.cutoff_qty,
				  dcd.max_qty,
				  CONCAT(FLOOR(cid.qtyloc1each/im.unitspercase),'/',cid.qtyloc1each%im.unitspercase)    location1,
				  CONCAT(FLOOR(cid.qtyloc2each/im.unitspercase),'/',cid.qtyloc2each%im.unitspercase)    location2,
				  im.unitspercase,
				  DATE_FORMAT(cid.expiry_date,'%d-%m-%Y') AS expiry_date
				FROM customeroperationscontrol coc
				  JOIN `customerinventorycheck` cid
				    ON cid.routekey = coc.routekey
				      AND cid.visitkey = coc.visitkey
				  LEFT JOIN itemmaster im
				    ON im.actualitemcode = cid.itemcode
				  LEFT JOIN distributioncheckdetail dcd
				    ON dcd.itemcode = cid.itemcode
				  LEFT JOIN startendday sed
				    ON sed.routekey = coc.routekey
				      AND sed.routecode = coc.routecode
				WHERE 1 = 1
				",in_where, " ORDER BY ",in_orderby," ",in_sort,", actualitemcode ASC ",limitval);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_item_distribution_monthlycom` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_item_distribution_monthlycom` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_item_distribution_monthlycom`()
BEGIN
DECLARE fieldsarray TEXT DEFAULT "";
DECLARE counter INT DEFAULT 1;
DECLARE num_rows int DEFAULT 0;
declare fieldyear,fieldmonth,fieldtxt varchar(100);
declare no_more_rows boolean;
DECLARE crpayment CURSOR FOR
SELECT 
		CONCAT(DATE_FORMAT(ih.actualtransactiondate,'%M'),"_",DATE_FORMAT(ih.actualtransactiondate,'%Y')) YEAR, DATE_FORMAT(ih.actualtransactiondate,'%m') monthno, DATE_FORMAT(ih.actualtransactiondate,'%M') monthtxt
		
	FROM 
		invoiceheader ih, invoicedetail id, customermaster cm, routemaster rm, salesman sm, categorymaster cg,
		itemmaster im, itemgroup ig, submajorcategory smc, majorcategory mc
	WHERE 
		ih.routekey = id.routekey AND ih.visitkey = id.visitkey AND 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND cm.customercategory = cg.categoryid AND 
		id.itemcode = im.actualitemcode AND im.itemgroupcode = ig.itemgroupcode AND ig.submajorcategorycode = smc.submajorcategorycode AND
		smc.majorcategorycode = mc.majorcategorycode GROUP BY DATE_FORMAT(ih.actualtransactiondate,'%Y'),DATE_FORMAT(ih.actualtransactiondate,'%m'),DATE_FORMAT(ih.actualtransactiondate,'%M');
DECLARE CONTINUE HANDLER FOR NOT FOUND SET no_more_rows = TRUE;
OPEN crpayment;
            SELECT FOUND_ROWS() INTO num_rows;		
	main_loop: LOOP
                IF no_more_rows THEN
		CLOSE crpayment;
		LEAVE main_loop;
		else IF counter > num_rows THEN
			CLOSE crpayment;
			LEAVE main_loop;
		END IF;
	END IF;
		FETCH crpayment INTO fieldyear,fieldmonth,fieldtxt;
		
		SET fieldsarray = concat(fieldsarray,fieldyear,' DECIMAL(19,8)',',');
		
		SET counter = counter+1;
		END LOOP main_loop;
set fieldsarray = LEFT(fieldsarray,LENGTH(fieldsarray)-1);
		DROP TEMPORARY TABLE IF EXISTS tempitemdis;
		SET @dyn_sql = CONCAT("CREATE TEMPORARY TABLE tempitemdis(",fieldsarray,")");
		
PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
		 select * from tempitemdis;
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_kpi_strikerate_callrate_avgtime` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_kpi_strikerate_callrate_avgtime` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_kpi_strikerate_callrate_avgtime`(
	IN in_where TEXT
)
BEGIN
	SET @s1 =  'DROP TABLE IF EXISTS kpi_report_strikerate_callrate_avgtime';
	PREPARE s1 FROM @s1;
	EXECUTE s1;	
	
	SET @sql = CONCAT("SELECT 
		YEAR(sed.routestartdate) AS tranyear,
		MONTH(sed.routestartdate) AS tranmonthno,
		DATE_FORMAT(sed.routestartdate,'%M') AS tranmonthtxt,
		sed.routestartdate, sed.routeenddate, 
		dm.depotcode, dm.depotname, am.areacode, am.areaname, sam.subareacode, sam.subareaname, 
		sed.routecode, rm.routename, rm.alternateroutecode, rm.arbroutename,
		sed.salesmancode, sm.salesmanname1 AS salesman, sm.alternatesalesmancode, sm.arbsalesmanname1,
		
		COALESCE (totaltime.routetime, '00:00:00') routetimespendinminutes,		
		COALESCE (total_sheduled.totalcust, 0) AS totalsheduled, 		
		COALESCE (total_visited.totalcust, 0) AS totalvisited,
		COALESCE (total_sheduled_sale.totalcust, 0) AS totalsheduledsale, 
		
		(SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE (total_unsheduled_visit.totalcust, 0) AS totalunsheduledvisit,	
				
		(SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE (total_unsheduled_sale.totalcust, 0) AS totalunsheduledsale,
					
		COALESCE (total_sheduled_nosale.totalcust, 0) AS totalshedulednosale,
		COALESCE (total_unsheduled_nosale.totalcust, 0) AS totalunshedulednosale,	
		COALESCE (total_unscanned.totalunscan, 0) AS totalunscannedcust,	
		COALESCE (totalcashsale.noofinv, 0) AS totalcashsale,
		COALESCE (totalcreditsale.noofinv, 0) AS totalcreditsale,	
		
		CASE WHEN COALESCE (total_sheduled.totalcust, 0) > 0 THEN
			CAST(COALESCE (totalcashsale.noofinv, 0) + COALESCE (totalcreditsale.noofinv, 0) AS DECIMAL)/ CAST(COALESCE (total_sheduled.totalcust, 0) AS DECIMAL) * 100
		ELSE
			0
		END AS strikerate,	
		
		CASE WHEN COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0) > 0 THEN
			CAST(COALESCE (totalcashsale.noofinv, 0) + COALESCE (totalcreditsale.noofinv, 0) AS DECIMAL) / CAST(COALESCE (total_visited.totalcust, 0) + COALESCE (total_unsheduled_visit.totalcust, 0) AS DECIMAL) * 100
		ELSE
			0
		END AS productivity,
		
		(COALESCE(total_visited.totalcust,0) * 100) / 
			CASE WHEN COALESCE(total_sheduled.totalcust,0) = 0 THEN 1 ELSE COALESCE(total_sheduled.totalcust,0) END AS callcompleted,
		 
		(COALESCE(total_visited.totalcust,0) * 100) / 
			CASE WHEN (COALESCE(total_visited.totalcust,0)+ COALESCE(total_unsheduled_visit.totalcust,0)) = 0 THEN 1 ELSE 
				(COALESCE(total_visited.totalcust,0)+ COALESCE(total_unsheduled_visit.totalcust,0)) END AS discipline,
	
		COALESCE(sed.routeendodometer, 0) routeendodometer, COALESCE(sed.routestartodometer, 0) routestartodometer, 
		
		CASE WHEN COALESCE(sed.routeendodometer, 0) - COALESCE(sed.routestartodometer, 0) < 0 THEN 0 ELSE 
			COALESCE(sed.routeendodometer, 0) - COALESCE(sed.routestartodometer, 0) END AS kmscovered
		
	FROM 
		startendday sed
		INNER JOIN routemaster rm ON sed.routecode = rm.routecode
		INNER JOIN salesman sm ON sed.salesmancode = sm.salesmancode
		INNER JOIN subareamaster sam ON rm.subareacode = sam.subareacode
		INNER JOIN areamaster am ON sam.areacode = am.areacode
		INNER JOIN depotmaster dm ON am.depotcode = dm.depotcode
		LEFT OUTER JOIN
			(SELECT rsc.routekey, rsc.routecode, COUNT(rsc.customercode) AS totalcust FROM routesequencecustomerstatus rsc 
			WHERE (rsc.schelduledflag = 1) 
			GROUP BY rsc.routekey, rsc.routecode) AS total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
		LEFT OUTER JOIN
			(SELECT vis.routekey, vis.routecode, COUNT(vis.customercode) AS totalcust FROM routesequencecustomerstatus vis 
			WHERE (vis.schelduledflag = 1) AND (vis.servicedflag <> 0) 
			GROUP BY vis.routekey, vis.routecode) AS total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
		LEFT OUTER JOIN
			(SELECT visout.routekey, visout.routecode, COUNT(visout.customercode) AS totalcust FROM routesequencecustomerstatus visout 
			WHERE (visout.schelduledflag = 0) AND (visout.servicedflag <> 0) 
			GROUP BY visout.routekey, visout.routecode) AS total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
		LEFT OUTER JOIN
			(SELECT sale.routekey, sale.routecode, COUNT(sale.customercode) AS totalcust FROM routesequencecustomerstatus sale 
			WHERE (sale.schelduledflag = 1) AND (sale.servicedflag = 1) 
			GROUP BY sale.routekey, sale.routecode) AS total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode 
		LEFT OUTER JOIN
			(SELECT sale.routekey, sale.routecode, COUNT(sale.customercode) AS totalcust FROM routesequencecustomerstatus sale 
			WHERE (sale.schelduledflag = 0) AND (sale.servicedflag = 1) 
			GROUP BY sale.routekey, sale.routecode) AS total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
		LEFT OUTER JOIN
			(SELECT nsale.routekey, nsale.routecode, COUNT(nsale.customercode) AS totalcust FROM routesequencecustomerstatus nsale 
			WHERE (nsale.schelduledflag = 1) AND (nsale.servicedflag = 2) 
			GROUP BY nsale.routekey, nsale.routecode) AS total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
		LEFT OUTER JOIN
			(SELECT nsale.routekey, nsale.routecode, COUNT(nsale.customercode) AS totalcust FROM routesequencecustomerstatus nsale 
			WHERE (nsale.schelduledflag = 0) AND (nsale.servicedflag = 2) 
			GROUP BY nsale.routekey, nsale.routecode) AS total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
		LEFT OUTER JOIN
			(SELECT nsale.routekey, nsale.routecode, COUNT(nsale.customercode) AS totalunscan FROM routesequencecustomerstatus nsale 
			WHERE (nsale.servicedflag <> 0) AND (nsale.scannedflag = 0) 
			GROUP BY nsale.routekey, nsale.routecode) AS total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, TIMEDIFF(MAX(TIME_FORMAT(ih.transactiontime, '%h:%i %p')),MIN(TIME_FORMAT(ih.transactiontime, '%h:%i %p'))) AS routetime FROM invoiceheader ih 
			GROUP BY ih.routekey, ih.routecode) AS totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM invoiceheader ih 
			WHERE (ih.immediatepaid != 0) AND (ih.voidflag = 0) 
			GROUP BY ih.routekey, ih.routecode) AS totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
		LEFT OUTER JOIN
			(SELECT ih.routekey, ih.routecode, COUNT(DISTINCT ih.customercode) noofinv FROM invoiceheader ih 
			WHERE (ih.immediatepaid = 0) AND (ih.voidflag = 0) 
			GROUP BY ih.routekey, ih.routecode) AS totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode 
	WHERE ",in_where) ;
	SET @s2 =  CONCAT("CREATE TABLE kpi_report_strikerate_callrate_avgtime AS ", @sql);
	PREPARE s2 FROM @s2;
	EXECUTE s2;	
	SET @s3 = 'UPDATE kpi_report_strikerate_callrate_avgtime SET routetimespendinminutes = ''00:00:00'' WHERE routetimespendinminutes=''0'' ';
	PREPARE s3 FROM @s3;
	EXECUTE s3;	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_merchandizing_pos` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_merchandizing_pos` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_merchandizing_pos`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM 
	customeroperationscontrol coc, posequipmentchangedetail pos, salesman sm, routemaster rm, customermaster cm, 
	posmaster pm, posinstructions poi
WHERE 	
	coc.routekey = pos.routekey AND coc.visitkey = pos.visitkey AND 
	pos.itemcode = pm.itemcode AND poi.posinstructioncode = pos.instructioncode AND
	coc.salesmancode = sm.salesmancode AND coc.routecode = rm.routecode AND coc.customercode = cm.customercode", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("SELECT 
	sm.alternatesalesmancode salesmancode, sm.salesmanname1 salesman, rm.alternateroutecode routecode, rm.routename route,
	REPLACE(cm.alternatecode,'-','') customercode, cm.customername customer, 
	DATE_FORMAT(coc.visitstartdate, '%d %b %Y') date, coc.visitstarttime time,
	pm.itemcode, pm.itemdescription, pos.quantity, pos.serialnumber, poi.posinstructionname, 
	CASE WHEN pos.posaction = 1 THEN 'ADDED POS' WHEN pos.posaction = 2 THEN 'DELETED POS' ELSE 'POS CHECKED' END posstatus,
	cm.arbcustomername,sm.arbsalesmanname1,rm.arbroutename,pm.arbitemdescription,poi.arbposinstructionname
FROM 
	customeroperationscontrol coc, posequipmentchangedetail pos, salesman sm, routemaster rm, customermaster cm, 
	posmaster pm, posinstructions poi
WHERE 	
	coc.routekey = pos.routekey AND coc.visitkey = pos.visitkey AND 
	pos.itemcode = pm.itemcode AND poi.posinstructioncode = pos.instructioncode AND
	coc.salesmancode = sm.salesmancode AND coc.routecode = rm.routecode AND coc.customercode = cm.customercode",in_where, " ORDER BY ",in_orderby," ",in_sort, "",limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_merchandizing_survey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_merchandizing_survey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_merchandizing_survey`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limitval TEXT DEFAULT "";    
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter FROM 
		customeroperationscontrol coc, surveyauditdetail sad, customersurveydefinition csd, salesman sm, routemaster rm, customermaster cm
	WHERE 	
		coc.routekey = sad.routekey AND coc.visitkey = sad.visitkey AND 
		sad.surveyindex = csd.surveyindex AND sad.surveydefkey = csd.surveydefkey AND
		coc.salesmancode = sm.salesmancode AND coc.routecode = rm.routecode AND coc.customercode = cm.customercode", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		SET @limitval = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
	
	  SELECT @new_start_limit AS start_limit,@in_counter AS counter;
	
	SET @dyn_sql = CONCAT("SELECT 
		sm.alternatesalesmancode salesmancode, sm.salesmanname1 salesman, rm.alternateroutecode routecode, rm.routename route,
		REPLACE(cm.alternatecode,'-','') customercode, cm.customername customer, 
		DATE_FORMAT(coc.visitstartdate, '%d %b %Y') date, coc.visitstarttime time,
		csd.surveyprompt surveydescription, 
		CASE WHEN sad.surveyrectype = 9 THEN 
			CASE WHEN sad.surveyresponse = 0 THEN 'NO' ELSE 'YES' END
		ELSE 
			sad.surveyresponse 
			END surveyresponse,
		sm.arbsalesmanname1,rm.arbroutename,cm.arbcustomername,csd.arbsurveyprompt
	FROM 
		customeroperationscontrol coc, surveyauditdetail sad, customersurveydefinition csd, salesman sm, routemaster rm, customermaster cm
	WHERE 	
		coc.routekey = sad.routekey AND coc.visitkey = sad.visitkey AND 
		sad.surveyindex = csd.surveyindex AND sad.surveydefkey = csd.surveydefkey AND
		coc.salesmancode = sm.salesmancode AND coc.routecode = rm.routecode AND coc.customercode = cm.customercode",in_where, " ORDER BY ",in_orderby," ",in_sort, "",limitval) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_otherreport_paramlist` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_otherreport_paramlist` */;

DELIMITER $$

