/* Procedure structure for procedure `sp_report_otp_log` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_otp_log` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_otp_log`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT,
IN in_user varchar(25)
)
BEGIN
	SET @dyn_sql = CONCAT("
		SELECT o.ROUTECODE, CONCAT(o.CUSTOMERCODE,'-', customername) customer, otptype, otpdate, otptime, username FROM otplogdetail o
INNER JOIN customermaster c ON o.customercode = c.customercode 
		",in_where, "order by otpdate, routecode,o.customercode, otptime") ;
   -- SELECT @dyn_sql;	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tabletreport_cashcheque_collection` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tabletreport_cashcheque_collection` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tabletreport_cashcheque_collection`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(255),
	IN in_sort VARCHAR(25),
	IN in_limit INT,
	IN in_page INT
)
BEGIN
	SET @dyn_sql = CONCAT('SELECT t1.* from (
				SELECT "COLLECTION" trantype, arh.transactiondate, arh.routecode, arh.invoicenumber AS receiptnumber, cm.alternatecode `code`, cm.customername, cm.arbcustomername,arh.amountpaid,
					CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END AS mop,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE CAST(ccd.checknumber AS CHAR) END AS checknumber, 
					CASE WHEN ccd.typecode = 0 THEN "" ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END AS checkdate,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END AS bankname,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END AS arbbankname,
					CASE WHEN ccd.typecode = 0 THEN 0 ELSE ccd.amount END AS checkamount
				FROM startendday AS sed INNER JOIN
					arheader AS arh ON sed.routekey = arh.routekey INNER JOIN
					cashcheckdetail AS ccd ON arh.routekey = ccd.routekey AND arh.visitkey = ccd.visitkey INNER JOIN
					bankmaster AS bm ON ccd.bankcode = bm.bankcode INNER JOIN
					customermaster AS cm ON arh.customercode = cm.customercode
				WHERE (arh.voidflag = 0)
				', in_where, '
			UNION
				SELECT "INVOICE" trantype, ih.transactiondate, ih.routecode, ih.invoicenumber AS receiptnumber, cm.alternatecode CODE, cm.customername,cm.arbcustomername, ih.immediatepaid amountpaid,
					CASE WHEN ccd.typecode = 0 THEN "CASH" ELSE "CHEQUE" END AS mop,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE CAST(ccd.checknumber AS CHAR) END AS checknumber,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE DATE_FORMAT(ccd.checkdate, "%d %b %Y") END AS checkdate,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.bankname END AS bankname,
					CASE WHEN ccd.typecode = 0 THEN "" ELSE bm.arbbankname END AS arbbankname,
					CASE WHEN ccd.typecode = 0 THEN 0 ELSE ccd.amount END AS checkamount
				FROM startendday AS sed INNER JOIN
					invoiceheader AS ih ON sed.routekey = ih.routekey INNER JOIN
					cashcheckdetail AS ccd ON ih.routekey = ccd.routekey AND ih.visitkey = ccd.visitkey INNER JOIN
					bankmaster AS bm ON ccd.bankcode = bm.bankcode INNER JOIN
					customermaster AS cm ON ih.customercode = cm.customercode
				WHERE (ih.immediatepaid > 0) AND ( ih.voidflag = 0)
				',in_where,'
				) as t1 ORDER BY t1.',in_orderby,' ',in_sort) ;
	 		-- select @dyn_sql;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_tabletreport_cashcheque_collection_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tabletreport_cashcheque_collection_detail` */;

