/* Procedure structure for procedure `sp_report_tablet_void_transaction` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_tablet_void_transaction` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_tablet_void_transaction`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
SET @dyn_sql = CONCAT("
				SELECT t1.* from (
				SELECT 'Sales' trantype,
		ih.routekey, ih.visitkey, DATE_FORMAT(ih.actualtransactiondate,'%d %b %Y') AS transactiondate, ih.transactiontime, ih.invoicenumber, 
		cm.reportcustcode customercode, cm.customername, rm.routecode, rm.routename, ih.salesmancode, sm.salesmanname1 salesman,
		ih.totalinvoiceamount invoiceamount, ih.immediatepaid amountpaid
	FROM 
		invoiceheader ih, customermaster cm, routemaster rm, salesman sm
	WHERE 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND ih.voidflag = 1",in_where," 
		
	
	UNION
	
	SELECT 'Collection' trantype,
		ih.routekey, ih.visitkey, DATE_FORMAT(ih.transactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber, 
		cm.reportcustcode customercode, cm.customername, rm.routecode, rm.routename, ih.salesmancode, sm.salesmanname1 salesman,
		ih.totalinvoiceamount invoiceamount, ih.amountpaid
	FROM 
		arheader ih, customermaster cm, routemaster rm, salesman sm
	WHERE 
		ih.customercode = cm.customercode AND ih.routecode = rm.routecode AND ih.salesmancode = sm.salesmancode AND ih.voidflag = 1",in_where,"	
				
					) as t1 ORDER BY t1.",in_orderby," ",in_sort) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
    END */$$
DELIMITER ;

