/* Procedure structure for procedure `sp_report_transaction_collectionsummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_collectionsummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_collectionsummary`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
    SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM arheader arh, customermaster cm, routemaster rm, ardetail ard, cashcheckdetail ccd where arh.customercode = cm.customercode AND arh.routecode = rm.routecode AND arh.voidflag = 0 AND 
		ard.routekey = arh.routekey AND ard.visitkey = arh.visitkey AND ard.transactionkey = arh.transactionkey AND 
		ccd.routekey = arh.routekey AND ccd.visitkey = arh.visitkey AND 
		COALESCE(ard.chequestatusindicator, 0) = 0 AND ard.amountpaid + ard.pdcbalance <> 0", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	 
	SET @dyn_sql = CONCAT("SELECT
		DATE(arh.transactiondate) transactiondate, 
		arh.transactionkey, arh.invoicenumber documentnumber, cm.reportcustcode customercode, cm.customername, cm.arbcustomername, arh.routecode, rm.routename,  rm.arbroutename, 
		arh.totalinvoiceamount totalreceiptamount, arh.amountpaid totalreceiptamountpaid, 
		ard.alternateinvoicenumber, DATE(ard.invoicedate)  AS invoicedate, 
		COALESCE((SELECT ci.salesmancode FROM customerinvoice ci WHERE ci.erpreferencenumber = ard.alternateinvoicenumber  AND ard.alternateinvoicenumber != '' AND ard.alternateinvoicenumber IS NOT NULL), 0) invoicedby,
		ard.totalinvoiceamount, ard.amountpaid  amountpaid,
		CASE WHEN ccd.typecode = 0 THEN ard.amountpaid  ELSE 0 END arcash,
		CASE WHEN ccd.typecode = 1 THEN ard.amountpaid  ELSE 0 END archeck
	FROM 
		arheader arh, customermaster cm, routemaster rm, ardetail ard, cashcheckdetail ccd
	WHERE 
		arh.customercode = cm.customercode AND arh.routecode = rm.routecode AND arh.voidflag = 0 AND 
		ard.routekey = arh.routekey AND ard.visitkey = arh.visitkey AND ard.transactionkey = arh.transactionkey AND 
		ccd.routekey = arh.routekey AND ccd.visitkey = arh.visitkey AND 
		COALESCE(ard.chequestatusindicator, 0) = 0 AND ard.amountpaid + ard.pdcbalance <> 0",in_where, " ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	  PREPARE s1 FROM @dyn_sql;
	  EXECUTE s1;		
	-- select @dyn_sql;
	
END */$$
DELIMITER ;

