/* Procedure structure for procedure `sp_report_transaction_ordersummery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_ordersummery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_ordersummery`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				salesorderheader soh, customermaster cm, routemaster rm, salesman sm
			WHERE
				soh.customercode = cm.customercode AND soh.routecode = rm.routecode 
				AND soh.salesmancode = sm.salesmancode ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					soh.routekey, soh.visitkey, soh.transactiondate sqltrandate,
					DATE_FORMAT(soh.transactiondate,'%d-%b-%Y') AS transactiondate, soh.transactiontime, soh.invoicenumber,
					CASE WHEN soh.paymenttype < 2 THEN 'CASH' WHEN soh.paymenttype = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
					CASE WHEN cm.type = 1 THEN '0' WHEN cm.type = 2 THEN (SELECT cm1.reportcustcode FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '1' END hocode,
					CASE WHEN cm.type = 1 THEN 'normal customers' WHEN cm.type = 2 THEN (SELECT cm1.customername FROM customermaster cm1 WHERE cm1.customercode = cm.headofficecode) ELSE '' END honame,
					cm.reportcustcode customercode, cm.customername, rm.routecode, rm.routename, soh.salesmancode, sm.salesmanname1 salesman,
					soh.totalsalesamount AS salesamount, soh.totalreturnamount AS goodreturnamount, soh.totaldamagedamount,
					soh.totalfreesampleamount AS freeamount,
					ROUND((soh.totalsalesamount-soh.totalreturnamount-soh.totaldamagedamount) - soh.totalinvoiceamount, 3) AS discountamount,
					soh.totalinvoiceamount AS invoiceamount, '00:00:00' receivedtime
				FROM
					salesorderheader soh, customermaster cm, routemaster rm, salesman sm
				WHERE
					soh.customercode = cm.customercode AND soh.routecode = rm.routecode 
					AND soh.salesmancode = sm.salesmancode
		",in_where, " ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;		
	
END */$$
DELIMITER ;

