/* Procedure structure for procedure `sp_report_transaction_returnsummery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_returnsummery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_returnsummery`(
	IN in_where TEXT,
	IN in_orderby VARCHAR(500),
	IN in_sort VARCHAR(50),
	IN in_limit INT,
	IN in_page INT)
BEGIN
	DECLARE limit_val TEXT DEFAULT "";
	DECLARE in_counter INT(8);
	
	SET @tablename = "tmp_itemreturn_summary_report";
	
	SET @tmp = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry FROM @tmp ;
	EXECUTE qry;
	
	SELECT CODE INTO @damage FROM expiryreturnreasons WHERE UPPER(description) LIKE '%DAMAGE%' LIMIT 1;
	SELECT CODE INTO @expiry FROM expiryreturnreasons WHERE UPPER(description) LIKE '%EXPIRY%' LIMIT 1;
	
	SET @tmp = CONCAT(" CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT
			ih.transactiondate, ih.routecode, rm.routename, rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman, cm.alternatecode customercode,
			mc.majorcategorycode, mc.description majorcategroy, im.alternatecode itemcode, im.itemdescription, im.unitspercase upc,
			COALESCE(dmg.quantity, 0) damagedqty, COALESCE(exp.quantity, 0) expiredqty, COALESCE(oth.quantity, 0) otherdamagedqty, 
			id.returnprice, id.returncaseprice
		FROM
			invoiceheader ih 
			INNER JOIN invoicedetail id ON id.transactionkey = ih.transactionkey AND ih.voidflag = 0
			INNER JOIN routemaster rm ON rm.routecode = ih.routecode
			INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			INNER JOIN customermaster cm ON cm.customercode = ih.customercode
			INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
			INNER JOIN itemgroup ig ON  ig.itemgroupcode = im.itemgroupcode
			INNER JOIN submajorcategory sc ON sc.submajorcategorycode = ig.submajorcategorycode
			INNER JOIN majorcategory mc ON mc.majorcategorycode = sc.majorcategorycode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) quantity
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode = ", @damage," GROUP BY transactionkey, itemcode) dmg ON dmg.transactionkey = id.transactionkey AND dmg.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) quantity
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode = ", @expiry," GROUP BY transactionkey, itemcode) exp ON exp.transactionkey = id.transactionkey AND exp.itemcode = id.itemcode
			
			LEFT OUTER JOIN (SELECT transactionkey, itemcode, SUM(quantity) quantity
				FROM  invoicerxddetail WHERE itemtransactiontype = 2 and reasoncode NOT IN ( ", @expiry, ",", @damage,") GROUP BY transactionkey, itemcode) oth ON oth.transactionkey = id.transactionkey AND oth.itemcode = id.itemcode
		WHERE 
			COALESCE(dmg.quantity, 0) + COALESCE(exp.quantity, 0) + COALESCE(oth.quantity, 0) != 0 ", in_where) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;	
	
	SELECT COUNT(cnt.counter) INTO in_counter
	FROM
	(SELECT COUNT(*) AS counter
	FROM tmp_itemreturn_summary_report
	GROUP BY transactiondate, routecode, majorcategorycode, itemcode) cnt;
	SELECT in_counter;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data (in_counter, in_limit, in_page, @new_start_limit);
		SELECT @new_start_limit AS start_limit, in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ", @new_start_limit, ",", in_limit);
	END IF;
	
	SET @tmp = CONCAT("
		SELECT 
			transactiondate, routecode, routename, arbroutename, salesmancode, salesman, 
			majorcategorycode, majorcategroy, itemcode, itemdescription, upc, returncaseprice, returnprice,
			damagedqty,
			(FLOOR(damagedqty/upc) * returncaseprice) + ((damagedqty % upc) * returnprice) AS damagevalue,
			expiredqty,
			(FLOOR(expiredqty/upc) * returncaseprice) + ((expiredqty % upc) * returnprice) AS expvalue,
			otherdamagedqty,
			(FLOOR(otherdamagedqty/upc) * returncaseprice) + ((otherdamagedqty % upc) * returnprice) AS otherdamagevalue,			
			damagedqty + expiredqty + otherdamagedqty totaldamage,
			(FLOOR(damagedqty/upc) * returncaseprice) + ((damagedqty % upc) * returnprice) +
			(FLOOR(expiredqty/upc) * returncaseprice) + ((expiredqty % upc) * returnprice) +
			(FLOOR(otherdamagedqty/upc) * returncaseprice) + ((otherdamagedqty % upc) * returnprice) AS totaldamagevalue			
		FROM ", @tablename, "
		GROUP BY transactiondate, routecode, routename, arbroutename, salesmancode, majorcategorycode, majorcategroy, itemcode, itemdescription, upc
		ORDER BY ",in_orderby," ",in_sort," ",limit_val) ;
	 PREPARE qry FROM @tmp;
	 EXECUTE qry;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_returnsummery_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_returnsummery_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_returnsummery_detail`(
)
BEGIN
	CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_route_review` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_route_review` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_route_review`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM routemaster rm, salesman sm,startendday sed
	LEFT JOIN total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
	LEFT JOIN total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
	LEFT JOIN total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
	LEFT JOIN total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode
	LEFT JOIN total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
	LEFT JOIN total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
	LEFT JOIN total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
	LEFT JOIN total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
	LEFT JOIN totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
	LEFT JOIN totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
	LEFT JOIN totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode
	WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)", in_where,"");
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	END IF;
	
	SET @dyn_sql = CONCAT("SELECT
		YEAR(routeenddate) AS tranyear, 
		MONTH(routeenddate) AS tranmonthno, 
		DATE_FORMAT(routeenddate,'%M') AS tranmonthtxt, 
		DATE_FORMAT(routestartdate,'%d-%b-%Y')  AS routestartdate1,
		DATE_FORMAT(routeenddate,'%W') AS daytxt,
		DATE_FORMAT(routeenddate,'%d-%b-%Y') AS routeenddate1,
		rm.routecode AS routecode, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, 
		CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman, 
		CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.arbsalesmanname1) AS arbsalesman, 
		CAST(SUM(COALESCE(total_sheduled.totalcust, 0)) AS CHAR) AS targettovisit, 
		CAST(SUM(COALESCE(total_visited.totalcust, 0)) AS CHAR) AS targetvisits, 
		CAST(SUM(COALESCE(total_sheduled.totalcust, 0)) - SUM(COALESCE(total_visited.totalcust, 0)) AS CHAR) AS callexceptions, 
		CAST(SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_visit.totalcust, 0)) AS CHAR) AS nontargetvisits, 
		CAST(SUM(COALESCE(total_visited.totalcust, 0)) + SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_visit.totalcust, 0)) AS CHAR) AS totalvisits, 
		CAST(SUM(COALESCE(total_sheduled_sale.totalcust, 0)) AS CHAR) AS schedulesale, 
		CAST(SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_sale.totalcust, 0)) AS CHAR) AS unschedsale, 
		CAST(SUM(COALESCE(total_sheduled_nosale.totalcust, 0)) AS CHAR) AS schedulenosale, 
		CAST(SUM(COALESCE(total_unsheduled_nosale.totalcust, 0)) AS CHAR) AS unschedulenosale, 
		CAST(SUM(COALESCE(total_sheduled_sale.totalcust, 0)) + SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
			COALESCE(total_unsheduled_sale.totalcust, 0)) AS CHAR) AS effectivevisit, 
		CAST(MIN(routestartodometer) AS CHAR) AS startkms, 
		CAST(MAX(routeendodometer) AS CHAR) AS endkms, 
		CAST((CASE WHEN (MAX(routeendodometer) - MIN(routestartodometer)) < 0 THEN 0 ELSE (MAX(routeendodometer) - MIN(routestartodometer)) END) AS CHAR) AS kmscovered
	FROM routemaster rm, salesman sm,startendday sed
	LEFT JOIN total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
	LEFT JOIN total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
	LEFT JOIN total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
	LEFT JOIN total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode
	LEFT JOIN total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
	LEFT JOIN total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
	LEFT JOIN total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
	LEFT JOIN total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
	LEFT JOIN totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
	LEFT JOIN totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
	LEFT JOIN totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode
	WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)",in_where, " GROUP BY YEAR(routeenddate), MONTH(routeenddate), routestartdate, routeenddate, 
		rm.routecode, rm.routename, sm.salesmancode, salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
	
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_route_review_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_route_review_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_route_review_detail`(
)
BEGIN
	CALL sp_combo_routemaster() ;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_route_review_edit` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_route_review_edit` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_route_review_edit`(IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter  FROM routemaster rm, salesman sm,startendday sed
               LEFT JOIN total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
               LEFT JOIN total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
               LEFT JOIN total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
               LEFT JOIN total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode
               LEFT JOIN total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
               LEFT JOIN total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
               LEFT JOIN total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
               LEFT JOIN total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
               LEFT JOIN totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
               LEFT JOIN totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
               LEFT JOIN totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode
               WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)", in_where,"");
               PREPARE s1 FROM @dyn_sql;
               EXECUTE s1;
               
               IF in_limit != "" && in_page != "" THEN 
                              CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
                              SELECT @new_start_limit AS start_limit,@in_counter AS counter;
                              SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
               END IF;
               
               SET @dyn_sql = CONCAT("SELECT
                              YEAR(routeenddate) AS tranyear, 
                              MONTH(routeenddate) AS tranmonthno, 
                              DATE_FORMAT(routeenddate,'%M') AS tranmonthtxt, 
                              
                              rm.routecode AS routecode, 
                              CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.routename) AS route, 
                              CONCAT(CAST(rm.routecode AS CHAR) , ' - ' , rm.arbroutename) AS arbroutename, 
                              CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.salesmanname1) AS salesman, 
                              CONCAT(CAST(sm.salesmancode AS CHAR) , ' - ' , sm.arbsalesmanname1) AS arbsalesman, 
                              CAST(SUM(COALESCE(total_sheduled.totalcust, 0)) AS CHAR) AS targettovisit, 
                              CAST(SUM(COALESCE(total_visited.totalcust, 0)) AS CHAR) AS targetvisits, 
                              CAST(SUM(COALESCE(total_sheduled.totalcust, 0)) - SUM(COALESCE(total_visited.totalcust, 0)) AS CHAR) AS callexceptions, 
                              CAST(SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
                                             COALESCE(total_unsheduled_visit.totalcust, 0)) AS CHAR) AS nontargetvisits, 
                              CAST(SUM(COALESCE(total_visited.totalcust, 0)) + SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
                                             COALESCE(total_unsheduled_visit.totalcust, 0)) AS CHAR) AS totalvisits, 
                              CAST(SUM(COALESCE(total_sheduled_sale.totalcust, 0)) AS CHAR) AS schedulesale, 
                              CAST(SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
                                             COALESCE(total_unsheduled_sale.totalcust, 0)) AS CHAR) AS unschedsale, 
                              CAST(SUM(COALESCE(total_sheduled_nosale.totalcust, 0)) AS CHAR) AS schedulenosale, 
                              CAST(SUM(COALESCE(total_unsheduled_nosale.totalcust, 0)) AS CHAR) AS unschedulenosale, 
                              CAST(SUM(COALESCE(total_sheduled_sale.totalcust, 0)) + SUM((SELECT COUNT(ih.invoicenumber) FROM invoiceheader ih WHERE ih.routekey = sed.routekey AND (ih.voidflag = 0) AND ih.customercode NOT IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) +
                                             COALESCE(total_unsheduled_sale.totalcust, 0)) AS CHAR) AS effectivevisit,
                                             
                                             
                              
(SELECT SUM(targetvalue) FROM customermaster cm WHERE cm.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE   rscs.schelduledflag =1 AND rscs.routekey = sed.routekey)) AS targetvalue,
((SELECT IFNULL(SUM(soh.totalinvoiceamount),0.000) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.schelduledflag = 1 AND rscs.servicedflag = 1 AND rscs.routekey = sed.routekey)) + 
(SELECT IFNULL(SUM(soh.totalinvoiceamount),0.000) FROM invoiceheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.schelduledflag = 1 AND rscs.servicedflag = 1  AND rscs.routekey = sed.routekey))
) AS targetvisitedvalue,
  ((SELECT IFNULL(SUM(soh.totalinvoiceamount),0.000) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode   IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.schelduledflag = 0 AND rscs.servicedflag = 1 AND rscs.routekey = sed.routekey)) + 
(SELECT  IFNULL(SUM(soh.totalinvoiceamount),0.000) FROM invoiceheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode   IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.schelduledflag = 0 AND rscs.servicedflag = 1 AND rscs.routekey = sed.routekey))
) AS targetnotvisitedvalue, 
                   
(
((SELECT IFNULL(SUM(soh.totalinvoiceamount),0.000) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) + 
(SELECT IFNULL(SUM(soh.totalinvoiceamount),0.000) FROM invoiceheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey))
)
/
(SELECT IFNULL(SUM(targetvalue),0.000) FROM customermaster cm WHERE cm.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE   rscs.schelduledflag =1 AND rscs.routekey = sed.routekey))
) AS scheduledvistedvstargetvalue,
(SELECT SUM(soh.totalinvoiceamount) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) AS actualordervalue,
(SELECT SUM(ah.amountpaid) FROM arheader ah WHERE ah.routekey = sed.routekey AND (ah.voidflag = 0) AND ah.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) AS collectionvalue,
CAST(((SELECT COUNT(DISTINCT soh.customercode) FROM salesorderheader soh WHERE soh.routekey = sed.routekey AND (soh.voidflag = 0) AND soh.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) ) / (SELECT COUNT( DISTINCT(rscs.customercode)) FROM routesequencecustomerstatus rscs WHERE   rscs.servicedflag =1 AND rscs.routekey = sed.routekey) AS CHAR) AS orderconvertionratio,
CAST( (SELECT COUNT(DISTINCT ah.customercode) FROM arheader ah WHERE ah.routekey = sed.routekey AND (ah.voidflag = 0) AND ah.customercode  IN (SELECT DISTINCT(rscs.customercode) FROM routesequencecustomerstatus rscs WHERE rscs.routekey = sed.routekey)) / (SELECT COUNT( DISTINCT(rscs.customercode)) FROM routesequencecustomerstatus rscs WHERE   rscs.servicedflag =1 AND rscs.routekey = sed.routekey) AS CHAR) AS collectionconversionratio                                                                                        
                              
               FROM routemaster rm, salesman sm,startendday sed
               LEFT JOIN total_sheduled ON sed.routekey = total_sheduled.routekey AND sed.routecode = total_sheduled.routecode
               LEFT JOIN total_visited ON sed.routekey = total_visited.routekey AND sed.routecode = total_visited.routecode
               LEFT JOIN total_unsheduled_visit ON sed.routekey = total_unsheduled_visit.routekey AND sed.routecode = total_unsheduled_visit.routecode
               LEFT JOIN total_sheduled_sale ON sed.routekey = total_sheduled_sale.routekey AND sed.routecode = total_sheduled_sale.routecode
               LEFT JOIN total_unsheduled_sale ON sed.routekey = total_unsheduled_sale.routekey AND sed.routecode = total_unsheduled_sale.routecode
               LEFT JOIN total_sheduled_nosale ON sed.routekey = total_sheduled_nosale.routekey AND sed.routecode = total_sheduled_nosale.routecode
               LEFT JOIN total_unsheduled_nosale ON sed.routekey = total_unsheduled_nosale.routekey AND sed.routecode = total_unsheduled_nosale.routecode
               LEFT JOIN total_unscanned ON sed.routekey = total_unscanned.routekey AND sed.routecode = total_unscanned.routecode
               LEFT JOIN totaltime ON sed.routekey = totaltime.routekey AND sed.routecode = totaltime.routecode
               LEFT JOIN totalcashsale ON sed.routekey = totalcashsale.routekey AND sed.routecode = totalcashsale.routecode
               LEFT JOIN totalcreditsale ON sed.routekey = totalcreditsale.routekey AND sed.routecode = totalcreditsale.routecode
               WHERE (sed.routecode = rm.routecode) AND (sed.salesmancode = sm.salesmancode)",in_where, " GROUP BY YEAR(routeenddate), MONTH(routeenddate), routestartdate, routeenddate, 
       rm.routecode, rm.routename, sm.salesmancode, salesmanname1 ORDER BY ",in_orderby," ",in_sort, " ", limit_val) ;
              --  Select @dyn_sql;
                PREPARE s1 FROM @dyn_sql;
              EXECUTE s1;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salessummary` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salessummary` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_report_transaction_salessummary`(
IN in_where TEXT,
IN in_orderby VARCHAR(255),
IN in_sort VARCHAR(25),
IN in_limit INT,
IN in_page INT
)
BEGIN
DECLARE limit_val TEXT DEFAULT "";
SET @dyn_sql = CONCAT("SELECT count(*) INTO @in_counter 
			FROM
				invoiceheader ih
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
			WHERE
				ih.voidflag = 0 ", in_where);
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;
	
	 IF in_limit != "" && in_page != "" THEN 
		CALL sp_report_calculate_paging_data(@in_counter ,in_limit,in_page,@new_start_limit);
		SELECT @new_start_limit AS start_limit,@in_counter AS counter;
		SET limit_val = CONCAT(" LIMIT ",@new_start_limit, ",",in_limit);
	 END IF;
	
	SET @dyn_sql = CONCAT("SELECT
					ih.routekey, ih.visitkey, ih.actualtransactiondate sqltrandate,
					DATE_FORMAT(ih.actualtransactiondate,'%d-%b-%Y') AS transactiondate, ih.transactiontime, ih.invoicenumber,
					CASE WHEN cm.invoicepaymentterms < 2 THEN 'CASH' WHEN cm.invoicepaymentterms = 2 THEN 'CREDIT' ELSE 'TC' END AS mop,
					cm.alternatecode customercode, cm.customername,cm.arbcustomername, rm.routecode, rm.routename,rm.arbroutename, ih.salesmancode, sm.salesmanname1 salesman,
					ih.totalsalesamount AS salesamount, concat('-',ih.totalreturnamount) AS goodreturnamount, (ih.totaldamagedamount+ih.totalexpiryamount) as totaldamagedamount, ih.totalexpiryamount,
					ih.totalfreesampleamount + ih.totalmanualfree AS freeamount,
					ROUND((ih.totalsalesamount-ih.totalreturnamount-ih.totaldamagedamount-ih.totalexpiryamount) - ih.totalinvoiceamount, 3) AS discountamount,
					ih.totaldiscountamount + totalpromoamount AS discountamount1,
					ih.totalinvoiceamount AS invoiceamount,
					ih.immediatepaid,
					ih.itemlinetaxamount,
					CASE WHEN ih.totalsalesamount > 0 THEN ROUND((ih.totalsalesamount+ih.itemlinetaxamount), 3) ELSE '0.000' END AS totalnetsales,
					CASE WHEN ih.totalreturnamount != 0 THEN ROUND((ih.itemlinetaxamount - ih.totalreturnamount), 3) ELSE '0.000' END AS totalnetreturn,
					ih.amountpaid, ih.invoicebalance,
					SUM(FLOOR(salesqty/im.unitspercase)) as salescase,	SUM((salesqty%im.unitspercase)) as salespcs,	
					SUM(FLOOR(returnqty/im.unitspercase)) as returncase,	SUM((returnqty%im.unitspercase)) as returnpcs,
					
					SUM(FLOOR(damagedqty/im.unitspercase))+SUM(FLOOR(id.expiryqty/im.unitspercase)) as damagedcase,	SUM((damagedqty%im.unitspercase))+SUM((id.expiryqty%im.unitspercase)) as damagedpcs,
					
					SUM(FLOOR((freesampleqty+manualfreeqty)/im.unitspercase)) as freecase,	SUM(((freesampleqty+manualfreeqty)%im.unitspercase)) as freepcs		
				FROM
					invoiceheader ih
					INNER JOIN invoicedetail id ON ih.routekey = id.routekey AND ih.visitkey = id.visitkey
					INNER JOIN itemmaster im ON id.itemcode = im.actualitemcode
					INNER JOIN customermaster cm ON cm.customercode = ih.customercode
					INNER JOIN routemaster rm ON rm.routecode = ih.routecode
					INNER JOIN salesman sm ON sm.salesmancode = ih.salesmancode
				WHERE
					ih.voidflag = 0 ",in_where, " GROUP BY ih.routekey,ih.visitkey ORDER BY ih.invoicenumber") ;
	 PREPARE s1 FROM @dyn_sql;
	 EXECUTE s1;	
	 SELECT @dyn_sql;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_report_transaction_salessummary_150222` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_report_transaction_salessummary_150222` */;

