/* Procedure structure for procedure `sp_update_promotion_advancepricing_customerpricingplankey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_promotion_advancepricing_customerpricingplankey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_promotion_advancepricing_customerpricingplankey`(
	IN var_customer BIGINT,
	IN var_pricingkey BIGINT
)
BEGIN
    
    
	UPDATE customermaster SET pricingkey = var_pricingkey WHERE customercode = var_customer;
	select var_customer;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_promotion_advancepricing_itemprice_plan` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_promotion_advancepricing_itemprice_plan` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_promotion_advancepricing_itemprice_plan`(
		    IN p_itemcode 			BIGINT,
                    IN p_salesprice			DECIMAL(19,4),
                    IN p_salescaseprice    	DECIMAL(19,4),
		    IN p_returnprice     	DECIMAL(19,4),
                    IN p_returncaseprice	DECIMAL(19,4),
                    IN var_primary_key		BIGINT,
                    IN p_createdby 		VARCHAR(50)
		)
BEGIN
	
	UPDATE pricingdetail1 SET
				itemcode 	= p_itemcode,
				salesprice 	= p_salesprice,
				salescaseprice 	= p_salescaseprice,
				returnprice 	= p_returnprice,
				returncaseprice = p_returncaseprice,
				modified 	= p_createdby,
				mdat 		= CURRENT_DATE()
			WHERE primary_key = var_primary_key;
				
		SELECT var_primary_key AS last_id;
		
		-- Insert Log
		CALL sp_add_logmaster_information('1','Price Change','pricingdetail1',pricingdetail1,p_createdby,'Edit');
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_sequence_numbers` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_sequence_numbers` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_sequence_numbers`(
                IN var_routeid INT
    )
BEGIN
	DECLARE var_seqflag INT(2);
	
	DECLARE var_invno VARCHAR(15);
	DECLARE var_invretno VARCHAR(15);
	DECLARE var_swapno VARCHAR(15);
	DECLARE var_arno VARCHAR(15);
	DECLARE var_ordno VARCHAR(15);
	DECLARE var_docno VARCHAR(15);
	DECLARE var_invdo varchar(15);
	
	SELECT COALESCE(transactionnoseq,0) INTO var_seqflag FROM routemaster WHERE routecode = var_routeid;
	
	IF var_seqflag > 0 THEN
		
		SELECT COALESCE(MAX(invoicenumber),0) INTO var_invno FROM invoiceheader WHERE dexflag = 0 AND  manualinvoicetype = 0 AND deliverycustomer = 0 AND  routecode = var_routeid;
		SELECT COALESCE(MAX(invoicenumber),0) INTO var_invretno FROM invoiceheader WHERE dexflag = 1 AND  manualinvoicetype = 0 AND deliverycustomer = 0 AND routecode = var_routeid;
		SELECT COALESCE(MAX(invoicenumber),0) INTO var_swapno FROM invoiceheader WHERE dexflag = 2 AND  manualinvoicetype = 0 AND deliverycustomer = 0 AND routecode = var_routeid;
		select coalesce(max(invoicenumber),0) into var_invdo from invoiceheader where dexflag = 0 and manualinvoicetype = 0 and deliverycustomer = 1 and routecode = var_routeid;
		
	ELSE
	
		SELECT COALESCE(MAX(invoicenumber),0) INTO var_invno FROM invoiceheader WHERE manualinvoicetype = 0 AND deliverycustomer = 0 AND routecode = var_routeid;
		SELECT COALESCE(MAX(invoicenumber),0) INTO var_invdo FROM invoiceheader WHERE manualinvoicetype = 0 AND deliverycustomer = 1 AND routecode = var_routeid;
		SET var_invretno = var_invno;
		SET var_swapno = var_invno;
	
	END IF;                
	
	SELECT COALESCE(MAX(invoicenumber),0) INTO var_arno FROM arheader WHERE routecode = var_routeid;
	SELECT COALESCE(MAX(invoicenumber),0) INTO var_ordno FROM salesorderheader WHERE routecode = var_routeid;
	
	SELECT MAX(maxno) INTO var_docno FROM
		(
			SELECT COALESCE(MAX(documentnumber),0) maxno FROM inventorytransactionheader WHERE manualinvoice = 0 AND routecode = var_routeid
				UNION
			SELECT COALESCE(MAX(documentnumber),0) maxno FROM invoiceheader WHERE manualinvoicetype = 0 AND routecode = var_routeid
				UNION
			SELECT COALESCE(MAX(documentnumber),0) maxno FROM salesorderheader WHERE routecode = var_routeid
				UNION
			SELECT COALESCE(MAX(documentnumber),0) maxno FROM arheader WHERE routecode = var_routeid
		) tblmax;	
	
	-- SELECT COALESCE(MAX(documentnumber),0) INTO var_docno FROM inventorytransactionheader WHERE routecode = var_routeid;
                
	SET @routelng = LENGTH(var_routeid);
                
	IF var_invno != '0' THEN
		SET var_invno = RIGHT(var_invno,LENGTH(var_invno)-@routelng-1);
	ELSE
		SET var_invno = "1";
	END IF;
	
	IF var_invdo != '0' THEN
		SET var_invdo = RIGHT(var_invdo,LENGTH(var_invdo)-@routelng-1);
	ELSE
		SET var_invdo = "1";
	END IF;
	
	IF var_invretno != '0' THEN
		SET var_invretno = RIGHT(var_invretno,LENGTH(var_invretno)-@routelng-1);
	ELSE
		SET var_invretno = "1";
	END IF;
  
  	IF var_swapno != '0' THEN
		SET var_swapno = RIGHT(var_swapno,LENGTH(var_swapno)-@routelng-1);
	ELSE
		SET var_swapno = "1";
	END IF;
	              
	IF var_arno != '0' THEN
		SET var_arno = RIGHT(var_arno,LENGTH(var_arno)-@routelng-1);
	ELSE
		SET var_arno = "1";
	END IF;
	
	IF var_ordno != '0' THEN
		SET var_ordno = RIGHT(var_ordno,LENGTH(var_ordno)-@routelng-1);
	ELSE
		SET var_ordno = "1";
	END IF;
                
	IF var_docno != '0' THEN
		SET var_docno = RIGHT(var_docno,LENGTH(var_docno)-@routelng);
	ELSE
		SET var_docno = "1";
	END IF;
                
	UPDATE routemaster SET 
		hhcinvseq= CAST(var_invno AS UNSIGNED),
		hhcarseq = CAST(var_arno AS UNSIGNED) , 
		hhcordseq = CAST(var_ordno AS UNSIGNED), 
		bodocseq = CAST(var_docno AS UNSIGNED) ,
		hhcinvretseq = CAST(var_invretno AS UNSIGNED),
		hhcswapseq = CAST(var_swapno AS UNSIGNED),
		invdoseq = cast(var_invdo AS UNSIGNED)
	WHERE routecode = var_routeid;
                                
	UPDATE routemaster 
		SET routemaster.vehicleodometer = COALESCE((SELECT sed.routeendodometer FROM startendday sed WHERE sed.routeclosed = 1 AND sed.routecode = routemaster.routecode ORDER BY sed.routekey DESC LIMIT 1),0)
	WHERE routecode = var_routeid;
	
END */$$
DELIMITER ;

