/* Procedure structure for procedure `sp_update_transaction_salesorder` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_transaction_salesorder` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_transaction_salesorder`(
					IN var_Pid DECIMAL(28,0)
					
				)
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM salesorderdetail WHERE transactionkey = var_Pid AND processedflag = '0';
		
IF cnt = 0 THEN 
	UPDATE  salesorderheader SET voidflag = 0, confirmorder = 1 WHERE transactionkey = var_Pid;
ELSE  
	UPDATE  salesorderheader SET voidflag = 1, confirmorder = 1 WHERE transactionkey = var_Pid;
END IF;
	
 END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_update_transaction_unload_closeroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_update_transaction_unload_closeroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_transaction_unload_closeroute`(
IN routecode BIGINT,
IN startdate Datetime
)
BEGIN
		
	SELECT COUNT(*) into @counter FROM startendday WHERE routecode = routecode AND routestartdate =startdate AND routeclosed = 0;
	if @counter > 0 then 
		UPDATE 	startendday SET  routeenddate = CURDATE(),
			 routeendtime = CURTIME(),
			 routeendodometer = 1,
			 routeclosed = 1,
			 modifieddate = CURDATE(),
			 modifiedtime = CURTIME(),
			 exportedflag = 0
		WHERE routecode = routecode AND routestartdate =startdate AND routeclosed = 0;
	
	select @counter as msg;
	else
	SELECT @counter as msg;
	end if;	
	
    END */$$
DELIMITER ;

