/* Procedure structure for procedure `sp_ws_from_tablet_endday` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_from_tablet_endday` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_from_tablet_endday`(
        IN var_routekey BIGINT(20),
        IN var_routeenddate DATE,
        IN var_routeendtime VARCHAR(10),
        IN var_routeendodometer DECIMAL(18,0),    
	IN var_totaldocuments INT(4),
	IN var_totalcash DOUBLE(8,4),
	IN var_totalchecks DOUBLE(8,0),	
	IN var_totalorderamount DOUBLE(8,0),
	IN var_totalinvoiceamount DOUBLE(8,4),
	IN var_totalchargesales DOUBLE(8,4),
	IN var_totalcashsales DOUBLE(8,4),
	IN var_totalacctsreceivable DOUBLE(8,0),
	IN var_totalexpenses DOUBLE(8,0),
	IN var_inventoryvariance DOUBLE(8,4),
	IN var_cashvariance DOUBLE(8,0)
    )
BEGIN
	UPDATE startendday SET 	
		routeenddate = var_routeenddate,
		routeendodometer = var_routeendodometer,
		routeendtime=CURTIME(),
		routeclosed = '1',
		totaldocuments = var_totaldocuments,
		totalcash = var_totalcash,
		totalchecks = var_totalchecks,
		totalcheckrequests = '0',
		totalorderamount = var_totalorderamount,
		totalinvoiceamount = var_totalinvoiceamount,
		totalchargesales = var_totalchargesales,
		totalcashsales = var_totalcashsales,
		totalacctsreceivable = var_totalacctsreceivable,
		totalexpenses = var_totalexpenses,
		inventoryvariance = var_inventoryvariance,
		cashvariance = var_cashvariance,
		totalfullservicesales = '0',
		totalfullservicecash = '0',
		-- dataconrefnumber = '0',
		exportedflag = '0',
		routejourneyid = '0',
		modifieddate=CURDATE(),
		modifiedtime=CURTIME(),
		DATA = '0'				
		WHERE routekey = var_routekey AND triptype = 0;
				
	UPDATE routemaster SET vehicleodometer = var_routeendodometer WHERE routecode = (SELECT routecode FROM startendday WHERE routekey = var_routekey AND triptype = 0 );	
	
	DELETE FROM salesorderdetail WHERE salesqty+returnqty+damagedqty+freesampleqty+manualfreeqty=0 AND routekey = var_routekey;
				
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getareamaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getareamaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getareamaster`(
	IN rwcnt INT,			-- for getting total records
	IN srchvalue VARCHAR(500), 	-- for searching keywords
	IN order_by VARCHAR(500),	-- for order by
	IN order_type VARCHAR(10),	-- for order type
	IN lmt_strt INT,		-- for limit start
	IN lmt_end INT 			-- for limit end
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'AreaCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(area.areacode) AS counter FROM areamaster AS area
	LEFT JOIN `areamanager` AS `manager` ON manager.areamanagercode = area.areamanagercode
	LEFT JOIN `depotmaster` AS `depot` ON depot.depotcode = area.depotcode
	WHERE (areaname LIKE('%",srchvalue,"%') OR areamanagername LIKE('%",srchvalue,"%')  OR depotname LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT `area`.`areaCode`, `area`.`areaname`, `manager`.`areamanagername`, `depot`.`depotname`,
	`area`.`activestatus` FROM `areamaster` AS `area`
	LEFT JOIN `areamanager` AS `manager` ON manager.areamanagercode = area.areamanagercode
	LEFT JOIN `depotmaster` AS `depot` ON depot.depotcode = area.depotcode
	WHERE (areaname LIKE('%",srchvalue,"%') OR areamanagername LIKE('%",srchvalue,"%')  OR depotname LIKE('%",srchvalue,"%'))
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	PREPARE s1 FROM @dyn_sql;
	-- select @dyn_sql;
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcompany` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcompany` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcompany`(
	IN rwcnt INT,
	IN srchvalue VARCHAR(500),
	IN order_by VARCHAR(500),
	IN order_type VARCHAR(10),
	IN lmt_strt INT,
	IN lmt_end INT,
	IN table_where TEXT 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'CmpyCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(cmpny.cmpycode) AS counter FROM company AS cmpny
	LEFT JOIN `nationalsalesmanager` AS `salesmngr` ON salesmngr.nationalsalesmanagercode = cmpny.nationalsalesmanagercode
	WHERE (countryname LIKE('%",srchvalue,"%') OR arbcompanyname LIKE('%",srchvalue,"%') OR name LIKE('%",srchvalue,"%')) ",table_where);
    ELSE
	SET @dyn_sql = CONCAT("SELECT `cmpny`.*, `salesmngr`.`nationalsalesmanagername`
	FROM `company` AS `cmpny` LEFT JOIN `nationalsalesmanager` AS `salesmngr` ON salesmngr.nationalsalesmanagercode = cmpny.nationalsalesmanagercode
	WHERE (countryname LIKE('%",srchvalue,"%') OR arbcompanyname LIKE('%",srchvalue,"%') OR name LIKE('%",srchvalue,"%')) ",table_where, "
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	-- SELECT @dyn_sql;
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcountrymaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcountrymaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcountrymaster`(
	in rwcnt int,	IN srchvalue VARCHAR(500), in order_by varchar(500),IN order_type VARCHAR(10),	IN lmt_strt int,  IN lmt_end INT, IN table_fields TEXT, IN table_where text 		)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'CountryCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
	if table_fields = '' then
		set table_fields = 'cnt.*';
	end if;
    if rwcnt = 1 THEN
	SET @dyn_sql = concat("SELECT COUNT(cnt.countrycode) AS counter FROM country AS cnt
	LEFT JOIN `currencymaster` AS `cur` ON cur.CurrencyCode = cnt.CurrencyCode
	WHERE (CountryName LIKE('%",srchvalue,"%') OR CurrencyName LIKE('%",srchvalue,"%')) ",table_where);
    ELSE
	SET @dyn_sql = concat("SELECT ", table_fields ," ,`cur`.`currencyname`
	FROM `country` AS `cnt` LEFT JOIN `currencymaster` AS `cur` ON cur.currencycode = cnt.currencycode
	WHERE (countryname LIKE('%",srchvalue,"%') OR currencyname LIKE('%",srchvalue,"%')) ",table_where, "
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
    	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcustomercategory` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcustomercategory` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcustomercategory`(
	IN rwcat INT,			-- for getting total records
	IN srchvalue VARCHAR(500), 	-- for searching keywords
	IN order_by VARCHAR(500),	-- for order by
	IN order_type VARCHAR(10),	-- for order type
	IN lmt_strt INT,		-- for limit start
	IN lmt_end INT 			-- for limit end
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	IF order_by = '' THEN
		SET order_by = 'CategoryName';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcat = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(cat.categoryid) AS counter FROM categorymaster AS cat
	WHERE (categoryname LIKE('%",srchvalue,"%') OR arbcategoryname LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT cat.categoryid,`cat`.`categoryname`, `cat`.`arbcategoryname`
	FROM `categorymaster` AS `cat`
	WHERE (categoryname LIKE('%",srchvalue,"%') OR arbcategoryname LIKE('%",srchvalue,"%'))
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	PREPARE s1 FROM @dyn_sql;
	-- select @dyn_sql;
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getcustomer_balance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getcustomer_balance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getcustomer_balance`(
	var_routeid  VARCHAR(15),
	var_customercode  VARCHAR(15)
    )
BEGIN
	SELECT `status` INTO @var_tempflag FROM controlpanel WHERE flagid = 51;
	
	IF  @var_tempflag = '1' THEN #Other Route Invoice For The Same Customer
	
		SET @dyn_sql = CONCAT("
			SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,", var_routeid, " routecode,ci.salesmancode,
				ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
				ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
				ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
				ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
				ci.duedate
			FROM customerinvoice ci 
				INNER JOIN salesman sm ON sm.salesmancode = ci.salesmancode
			WHERE ci.transactiontype = 2 AND ci.voidflag = 0 AND ci.duedate IS NOT NULL AND ci.customercode=",var_customercode);        
	ELSE
		SET @dyn_sql = CONCAT("
			SELECT ci.transactionkey,ci.transactiontype,ci.documentnumber,ci.invoicenumber,ci.transactiondate,ci.transactiontime,ci.customercode,", var_routeid, " routecode,ci.salesmancode,
				ci.totalinvoiceamount,ci.totalsalesamount,ci.totalreturnamount,ci.totaldamagedamount,ci.totalfreesampleamount,ci.immediatepaid,ci.amountpaid,ci.dnamountpaid,ci.cnamountpaid,
				ci.invoicebalance,ci.paymenttype,ci.voidflag,ci.paymentstatus, sm.alternatesalesmancode remarks1,'' remarks2,ci.routestartdate,ci.erpreferencenumber,ci.mdat,ci.totalpromoamount,
				ci.gcpaymenttype,ci.totaltaxesamount,ci.itemlinetaxamount,ci.totaldiscountamount,ci.pdcindicator,ci.chequecollection,ci.totalexpiryamount,ci.currencycode,ci.pdcbalance,
				ci.totalmanualfree,ci.totallimitedfree,ci.totalrebaterent,ci.totalfixedrent,ci.data,ci.totaldiscdistributionamount,ci.totalreplacementamount,ci.pdcdate,ci.totalbuybackfreeamount, 
				ci.duedate
			FROM customerinvoice ci 
				INNER JOIN salesman sm ON sm.salesmancode = ci.salesmancode
			WHERE ci.transactiontype = 2 AND ci.voidflag = 0 AND ci.duedate IS NOT NULL AND ci.routecode=", var_routeid," AND ci.customercode=",var_customercode);   
	END IF;
	
	PREPARE s1 FROM @dyn_sql;
	EXECUTE s1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_delivery` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_delivery` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_delivery`(
	var_cust VARCHAR(15),
	var_orderdate VARCHAR(15),
	var_orderno VARCHAR(15),
	var_lpono  VARCHAR(15),
	var_routeid  VARCHAR(15)
    )
BEGIN
	
	-- Temp table to keep the orderno to download.
	SET @tablename = CONCAT("temp_delivery_",var_routeid);
	SET @tempdel = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry1 FROM @tempdel ;
	EXECUTE qry1;
	
	SET @temppromotable = '';
	IF var_cust <> '' THEN
		SET @temppromotable = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT dh.orderno FROM deliveryheader dh INNER JOIN customermaster cm ON cm.customercode = dh.customercode 
		WHERE UPPER(cm.alternatecode) LIKE '%", UPPER(var_cust) ,"%' ORDER BY dh.orderno LIMIT 10");
		
	ELSEIF var_orderno <> '' THEN
		SET @temppromotable = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT DISTINCT orderno FROM deliveryheader WHERE orderno LIKE '%", var_orderno ,"%' ORDER BY orderno LIMIT 10");
	
	ELSEIF var_lpono <> '' THEN
		SET @temppromotable = CONCAT("CREATE TABLE IF NOT EXISTS ", @tablename, " AS 
		SELECT DISTINCT orderno FROM deliveryheader WHERE UPPER(loadsheetnumber) LIKE '%", UPPER(var_lpono) ,"%' ORDER BY orderno LIMIT 10");
	END IF;	
	PREPARE qry2 FROM @temppromotable;
	EXECUTE qry2;
	
	#FROM salesorderheader
	SET @dyn_sql1 = CONCAT("SELECT dh.deliveryno,dh.orderno,dh.customercode,dh.deliveryroute,dh.deliverydate,
			dh.drivercode,dh.loadsheetnumber, cm.alternatecode reference,dh.totalamount
		FROM deliveryheader dh INNER JOIN customermaster cm on cm.customercode = dh.customercode
		WHERE orderno IN (SELECT orderno FROM ", @tablename ,")");
	PREPARE s1 FROM @dyn_sql1;
	EXECUTE s1;	
		
        
        #FROM salesorderdetail
	SET @dyn_sql2 = CONCAT("SELECT dd.*
		FROM deliveryheader dh 
			INNER JOIN deliverydetail dd ON dd.deliveryno = dh.deliveryno AND dh.orderno IN (SELECT orderno FROM ", @tablename ,")");
	PREPARE s2 FROM @dyn_sql2;
	EXECUTE s2;
	
	SET @tempdel = CONCAT("DROP TABLE IF EXISTS ",@tablename);
	PREPARE qry1 FROM @tempdel ;
	EXECUTE qry1;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_ardetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_ardetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_ardetail`(
					IN var_routekey DECIMAL(28,0),
					IN var_visitkey DECIMAL(28,0),
					IN var_transactionkey DECIMAL(28,0),
					IN var_invoicenumber DECIMAL(18,0),
					IN var_invoicedate DATETIME,
					IN var_totalinvoiceamount DECIMAL(19,4),
					IN var_onacctreasoncode INT(11),
					IN var_amountpaid DECIMAL(19,4),
					IN var_invoicebalance DECIMAL(19,4),
					IN var_arcollectiontype INT(11),
					IN var_chequestatusindicator DECIMAL(18,0),
					IN var_sapchequestatusindicator Varchar(50),
					IN var_currencycode DECIMAL(18,0),
					IN var_pdcbalance DECIMAL(19,4),
					IN var_alternateinvoicenumber VARCHAR(30),
					IN var_salesmancode BIGINT(18)
				)
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM ardetail WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `invoicenumber` =var_invoicenumber;
	IF cnt = 0 THEN	
		
		INSERT INTO ardetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			invoicenumber = var_invoicenumber,
			salesmancode=var_salesmancode,
			invoicedate = var_invoicedate,
			totalinvoiceamount = var_totalinvoiceamount,
			onacctreasoncode = var_onacctreasoncode,
			amountpaid = var_amountpaid,
			invoicebalance = var_invoicebalance,
			arcollectiontype = var_arcollectiontype,
			chequestatusindicator = var_chequestatusindicator,
			referenceno = var_sapchequestatusindicator,
			currencycode = get_default_currencycode_routekey(var_routekey),
			pdcbalance = var_pdcbalance,
			alternateinvoicenumber = var_alternateinvoicenumber,
			receivedtime = CURTIME();								
			
		UPDATE customerinvoice SET amountpaid = amountpaid + var_amountpaid, invoicebalance = invoicebalance - var_amountpaid WHERE `invoicenumber` = var_invoicenumber;
		
	END IF;								
	
 				
	SELECT var_transactionkey AS lastid;	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_arheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_arheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_arheader`(	
		IN var_transationkey BIGINT(11),	
		IN var_routekey DECIMAL(28,0),
		IN var_visitkey DECIMAL(28,0),
		IN var_documentnumber DECIMAL(28,0),
		IN var_transactiondate DATETIME,
		IN var_transactiontime VARCHAR(10),
		IN var_customercode DECIMAL(18,0),
		IN var_routecode DECIMAL(18,0),
		IN var_salesmancode DECIMAL(18,0),
		IN var_voidflag INT(11),
		IN var_splittransaction INT(11),
		IN var_transmitindicator INT(11),
		IN var_totalinvoiceamount DECIMAL(19,4),
		IN var_amountpaid DECIMAL(19,4),
		IN var_invoicebalance DECIMAL(19,4),
		IN var_invoicenumber DECIMAL(28,0),
		IN var_hhcdocumentnumber DECIMAL(28,0),
		IN var_hhcinvoicenumber DECIMAL(28,0),
		IN var_voidreasoncode INT(11),
		IN var_chequecollection DECIMAL(18,0),
		IN var_currencycode DECIMAL(18,0),
		IN var_hhctransactionkey DECIMAL(18,0),
		IN var_data INT(11),
		IN var_comments VARCHAR(200),
		IN var_advancepaymentflag INT(11),
		IN var_excesspayment DECIMAL(19,4),
		IN var_comments2 VARCHAR(200)
		)
BEGIN
 	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM arheader WHERE `invoicenumber` = var_invoicenumber;
 	IF cnt = 0 THEN	
	
		INSERT INTO arheader SET    
				routekey = var_routekey,
				visitkey = var_visitkey,
				documentnumber = var_documentnumber,
				transactiondate = check_monthclosing_time(var_transactiondate),
				transactiontime = var_transactiontime,
				customercode = var_customercode,
				routecode = var_routecode,
				salesmancode = var_salesmancode,
				voidflag = var_voidflag,
				splittransaction = var_splittransaction,
				transmitindicator = var_transmitindicator,
				totalinvoiceamount = var_totalinvoiceamount,
				amountpaid = var_amountpaid,
				invoicebalance = var_invoicebalance,
				invoicenumber = var_invoicenumber,
				hhcdocumentnumber = var_hhcdocumentnumber,
				hhcinvoicenumber = var_hhcinvoicenumber,
				voidreasoncode = var_voidreasoncode,
				chequecollection = var_chequecollection,
				currencycode = get_default_currencycode_routekey(var_routekey),
				hhctransactionkey = var_hhctransactionkey,
				`data` = var_data,
				comments = var_comments,
				advancepaymentflag = var_advancepaymentflag,
				excesspayment = var_excesspayment,
				comments2 = var_comments2,
				record_flag='1',
				actualtransactiondate = var_transactiondate,
				receivedtime = CURTIME();
				
			SELECT LAST_INSERT_ID() AS lastid ;
             	ELSE
			UPDATE arheader SET voidflag = var_voidflag WHERE `invoicenumber` = var_invoicenumber;
			-- UPDATE customerinvoice SET voidflag = var_voidflag WHERE `invoicenumber` = var_invoicenumber;
			
			SELECT transactionkey AS lastid FROM arheader WHERE `invoicenumber` = var_invoicenumber;
		END IF;							
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_batchdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_batchdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_batchdetail`(
					IN var_routekey BIGINT(28),
					IN var_batchdetailkey DECIMAL(18,0),
					IN var_batchnumber VARCHAR(20),
					IN var_itemcode BIGINT(18),
					IN var_quantity DECIMAL(18,0),
					IN var_transactiontypecode INT(11),
					IN var_expirydate DATETIME,
					IN var_visitkey BIGINT(28)
				)
BEGIN
	DECLARE flag INT DEFAULT 0;
	DECLARE cnt INT DEFAULT 0;
	
	SELECT STATUS INTO flag FROM controlpanel WHERE flagid = 1;
	
	IF flag = 1 THEN
	
		SELECT COUNT(*) INTO cnt FROM batchexpirydetail WHERE routekey = var_routekey AND batchnumber = var_batchnumber AND itemcode = var_itemcode AND visitkey=var_visitkey AND transactiontypecode = var_transactiontypecode AND batchdetailkey = var_batchdetailkey;
		
		IF cnt = 0 THEN
		
			INSERT INTO batchexpirydetail SET 
			routekey = var_routekey,
			batchdetailkey = var_batchdetailkey,
			batchnumber = var_batchnumber,
			itemcode = var_itemcode, 
			quantity = var_quantity,
			transactiontypecode = var_transactiontypecode,
			expirydate = var_expirydate,visitkey=var_visitkey;
			
		ELSE		
			UPDATE batchexpirydetail SET
			batchdetailkey = var_batchdetailkey,
			quantity = var_quantity,
			expirydate = var_expirydate 
			WHERE routekey = var_routekey AND batchnumber = var_batchnumber AND itemcode = var_itemcode AND visitkey=var_visitkey AND transactiontypecode = var_transactiontypecode AND batchdetailkey = var_batchdetailkey; 				
		
		END IF;	
	       			
	END IF;
	
	SELECT var_routekey AS lastid; 
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_cashcheckdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_cashcheckdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_cashcheckdetail`(
	IN var_routekey DECIMAL(28,0),
	IN var_visitkey DECIMAL(28,0),
	IN var_typecode INT(11),
	IN var_paymenttype INT(4),
	IN var_checknumber DECIMAL(18,0),
	IN var_amount DECIMAL(19,4),
	IN var_updateindicator INT(11),
	IN var_checkdate DATETIME,
	IN var_bankcode BIGINT(20),
	IN var_checkstatus INT(11),
	IN var_branchcode DECIMAL(18,0),
	IN var_drawercode DECIMAL(18,0),
	IN var_chequestatusindicator DECIMAL(18,0),
	IN var_sapchequestatusindicator DECIMAL(18,0),
	IN var_currencycode DECIMAL(18,0),
	IN var_hhctransactionkey DECIMAL(18,0),
	IN var_transactiontype INT(4),
	IN var_checktype INT(11)
)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	SELECT COUNT(*) INTO cnt FROM cashcheckdetail WHERE routekey = var_routekey AND visitkey =var_visitkey AND hhctransactionkey =var_hhctransactionkey;
	IF LENGTH(var_checknumber) > 10 THEN
		SET var_checknumber = LEFT(var_checknumber,10);
	END IF;
 	IF cnt = 0 THEN
 	
		INSERT INTO cashcheckdetail SET routekey = var_routekey,
				visitkey = var_visitkey,
				typecode = var_typecode,
				checknumber = var_checknumber,
				amount = var_amount,
				updateindicator = var_updateindicator,
				checkdate = var_checkdate,
				bankcode = var_bankcode,
				checkstatus = var_checkstatus,
				branchcode = var_branchcode,
				drawercode = var_drawercode,
				chequestatusindicator = var_chequestatusindicator,
				sapchequestatusindicator = var_sapchequestatusindicator,
				currencycode = get_default_currencycode_routekey(var_routekey),
				hhctransactionkey = var_hhctransactionkey,
				paymenttype = var_paymenttype,
				transactiontype = var_transactiontype,
				checktype = var_checktype;
		
 	ELSE
 	
		UPDATE cashcheckdetail SET routekey = var_routekey,
			visitkey = var_visitkey,
			typecode = var_typecode,
			checknumber = var_checknumber,
			amount = var_amount,
			updateindicator = var_updateindicator,
			checkdate = var_checkdate,
			bankcode = var_bankcode,
			checkstatus = var_checkstatus,
			branchcode = var_branchcode,
			drawercode = var_drawercode,
			chequestatusindicator = var_chequestatusindicator,
			sapchequestatusindicator = var_sapchequestatusindicator,
			currencycode = get_default_currencycode_routekey(var_routekey),
			hhctransactionkey = var_hhctransactionkey,
			paymenttype = var_paymenttype,
			transactiontype = var_transactiontype,
			checktype = var_checktype
			WHERE routekey = var_routekey AND visitkey =var_visitkey AND hhctransactionkey =var_hhctransactionkey;
 	END IF;
 	
	SELECT var_routekey AS lastid;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_customerinvoice` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_customerinvoice` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_customerinvoice`(
					IN var_transactionkey DECIMAL(28,0),
					IN var_transactiontype INT(11),
					IN var_documentnumber DECIMAL(18,0),
					IN var_invoicenumber DECIMAL(18,0),
					IN var_transactiondate DATETIME,
					IN var_transactiontime VARCHAR(10),
					IN var_customercode DECIMAL(18,0),
					IN var_routecode DECIMAL(18,0),
					IN var_salesmancode DECIMAL(18,0),
					IN var_totalinvoiceamount DECIMAL(19,4),
					IN var_totalsalesamount DECIMAL(19,4),
					IN var_totalreturnamount DECIMAL(19,4),
					IN var_totaldamagedamount DECIMAL(19,4),
					IN var_totalfreesampleamount DECIMAL(19,4),
					IN var_immediatepaid DECIMAL(19,4),
					IN var_amountpaid DECIMAL(19,4),
					IN var_dnamountpaid DECIMAL(19,4),
					IN var_cnamountpaid DECIMAL(19,4),
					IN var_invoicebalance DECIMAL(19,4),
					IN var_paymenttype INT(11),
					IN var_voidflag INT(11),
					IN var_paymentstatus INT(11),
					IN var_hhcinvoicenumber DECIMAL(28,0),
					IN var_remarks1 VARCHAR(50),
					IN var_remarks2 VARCHAR(50),
					IN var_routestartdate DATETIME,
					IN var_erpreferencenumber VARCHAR(30),
					IN var_mdat DATETIME,
					IN var_totalpromoamount DECIMAL(19,4),
					IN var_gcpaymenttype INT(11),
					IN var_totaltaxesamount DECIMAL(19,4),
					IN var_itemlinetaxamount DECIMAL(19,4),
					IN var_totaldiscountamount DECIMAL(19,4),
					IN var_pdcindicator INT(11),
					IN var_chequecollection DECIMAL(18,0),
					IN var_totalexpiryamount DECIMAL(19,4),
					IN var_currencycode DECIMAL(18,0),
					IN var_pdcbalance DECIMAL(19,4),
					IN var_totalmanualfree DECIMAL(19,4),
					IN var_totallimitedfree DECIMAL(19,4),
					IN var_totalrebaterent DECIMAL(19,4),
					IN var_totalfixedrent DECIMAL(19,4),
					IN var_data INT(11),
					IN var_totaldiscdistributionamount DECIMAL(19,4),
					IN var_totalreplacementamount DECIMAL(19,4),
					IN var_pdcdate DATETIME,
					IN var_totalbuybackfreeamount DECIMAL(19,4),
					IN var_duedate DATETIME
				)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	SELECT COUNT(*) INTO cnt FROM customerinvoice WHERE invoicenumber = var_invoicenumber;
	
 	IF cnt = 0 THEN
	
		INSERT INTO customerinvoice SET 
		transactiontype = var_transactiontype,
		documentnumber = var_documentnumber,
		invoicenumber = var_invoicenumber,
		transactiondate = check_monthclosing_time(var_transactiondate),
		transactiontime = var_transactiontime,
		customercode = var_customercode,
		routecode = var_routecode,
		salesmancode = var_salesmancode,
		totalinvoiceamount = var_totalinvoiceamount,
		totalsalesamount = var_totalsalesamount,
		totalreturnamount = var_totalreturnamount,
		totaldamagedamount = var_totaldamagedamount,
		totalfreesampleamount = var_totalfreesampleamount,
		immediatepaid = var_immediatepaid,
		amountpaid = var_amountpaid,
		dnamountpaid = var_dnamountpaid,
		cnamountpaid = var_cnamountpaid,
		invoicebalance = var_invoicebalance,
		paymenttype = var_paymenttype,
		voidflag = var_voidflag,
		paymentstatus = var_paymentstatus,
		hhcinvoicenumber = var_hhcinvoicenumber,
		remarks1 = var_remarks1,
		remarks2 = var_remarks2,
		erpreferencenumber = var_erpreferencenumber,
		mdat = CURRENT_DATE(),
		totalpromoamount = var_totalpromoamount,
		gcpaymenttype = var_gcpaymenttype,
		totaltaxesamount = var_totaltaxesamount,
		itemlinetaxamount = var_itemlinetaxamount,
		totaldiscountamount = var_totaldiscountamount,
		pdcindicator = var_pdcindicator,
		chequecollection = var_chequecollection,
		totalexpiryamount = var_totalexpiryamount,
		currencycode = get_default_currencycode_routecode(var_routecode),
		pdcbalance = var_pdcbalance,
		totalmanualfree = var_totalmanualfree,
		totallimitedfree = var_totallimitedfree,
		totalrebaterent = var_totalrebaterent,
		totalfixedrent = var_totalfixedrent,
		`data` = var_data,
		totaldiscdistributionamount = var_totaldiscdistributionamount,
		totalreplacementamount = var_totalreplacementamount,
		pdcdate=var_pdcdate,
		routestartdate=var_transactiondate,
		totalbuybackfreeamount=var_totalbuybackfreeamount,
		duedate = var_duedate;
	ELSE
	
		UPDATE customerinvoice SET 		
			amountpaid = var_amountpaid,		
			invoicebalance = var_invoicebalance,
			voidflag = var_voidflag,
			mdat = CURRENT_DATE(),
			pdcindicator = var_pdcindicator,
			chequecollection = var_chequecollection,		
			pdcbalance = var_pdcbalance,		
			pdcdate=var_pdcdate
		WHERE invoicenumber = var_invoicenumber;
	END IF;
	
	SELECT var_transactionkey AS lastid;  					
	
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_customeroperationcontrol` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_customeroperationcontrol` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_customeroperationcontrol`(
	IN var_visitkey BIGINT(20),
	IN var_routekey BIGINT(20),
	IN var_customercode DECIMAL(18,0),
	IN var_routecode DECIMAL(18,0),
	IN var_salesmancode DECIMAL(18,0),
	IN var_odometerreading DECIMAL(18,0),
	IN var_visitstartdate DATETIME,
	IN var_visitstarttime VARCHAR(10),
	IN var_visitenddate DATETIME,
	IN var_visitendtime VARCHAR(10),
	IN var_totaltransactions INT(11),
	IN var_addedcustomer INT(11),
	IN var_voidflag INT(11),
	IN var_scannerindicator INT(11),
	IN var_reasoncode INT(11),
	IN var_latitude DECIMAL(18,10),
	IN var_longitude DECIMAL(18,10),
	IN var_radius DECIMAL(18,6)
)
BEGIN
    
	DECLARE cnt INT DEFAULT 0;
	
	SELECT IFNULL(COUNT(*),0) INTO cnt FROM customeroperationscontrol 
		WHERE routekey = var_routekey AND visitkey = var_visitkey ;
		
	IF cnt = 0 THEN
    
		INSERT INTO customeroperationscontrol SET visitkey = var_visitkey,
			routekey = var_routekey,
			customercode = var_customercode,
			routecode = var_routecode,
			salesmancode = var_salesmancode,
			odometerreading = var_odometerreading,
			visitstartdate = var_visitstartdate,
			visitstarttime = var_visitstarttime,
			visitenddate = var_visitenddate,
			visitendtime = CASE WHEN var_visitendtime = '0' THEN var_visitstarttime ELSE var_visitendtime END ,
			totaltransactions = var_totaltransactions,
			addedcustomer = var_addedcustomer,
			voidflag = var_voidflag,
			scannerindicator = var_scannerindicator,
			reasoncode = var_reasoncode,
			latitude = var_latitude,
			longitude = var_longitude,
			radius = var_radius;
		
		if var_latitude > 0 THEN
			
			UPDATE customermaster 
			SET fixedlatitude = var_latitude, fixedlongitude =var_longitude
			WHERE customercode = var_customercode;		
			
		END IF;
		
		SELECT var_routekey AS lastid ; 
		
	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_inventorysummarydetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_inventorysummarydetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_inventorysummarydetail`(
					IN var_inventorykey DECIMAL(28,0),
					IN var_itemcode DECIMAL(18,0),
					IN var_routekey DECIMAL(28,0),
					IN var_weighted INT(4),
					IN var_beginstockqty DECIMAL(18,0),
					IN var_loadqty DECIMAL(18,0),
					IN var_loadaddqty DECIMAL(18,0),
					IN var_loadcutqty DECIMAL(18,0),
					IN var_loadreqqty DECIMAL(18,0),
					IN var_saleqty DECIMAL(18,0),
					IN var_returnqty DECIMAL(18,0),
					IN var_damagedaddqty DECIMAL(18,0),
					IN var_damagedcutqty DECIMAL(18,0),
					IN var_endstockqty DECIMAL(18,0),
					IN var_unloadqty DECIMAL(18,0),
					IN var_damagedunloadqty DECIMAL(18,0),
					IN var_freesampleqty DECIMAL(18,0),
					IN var_truckdamagedunloadqty DECIMAL(18,0),
					IN var_stdsalesprice DECIMAL(18,6),
					IN var_stdreturnprice DECIMAL(18,6),
					IN var_cashsalesqty DECIMAL(18,0),
					IN var_cashsalesvalue DOUBLE(8,0),
					IN var_tcsalesqty DECIMAL(18,0),
					IN var_tcsalesvalue DOUBLE(8,0),
					IN var_gcsalesqty DECIMAL(18,0),
					IN var_gcsalesvalue DOUBLE(8,0),
					IN var_cashdamagedqty DECIMAL(18,0),
					IN var_cashdamagedvalue DOUBLE(8,0),
					IN var_tcdamagedqty DECIMAL(18,0),
					IN var_tcdamagedvalue DOUBLE(8,0),
					IN var_gcdamagedqty DECIMAL(18,0),
					IN var_gcdamagedvalue DOUBLE(8,0),
					IN var_cashreturnqty DECIMAL(18,0),
					IN var_cashreturnvalue DOUBLE(8,0),
					IN var_tcreturnqty DECIMAL(18,0),
					IN var_tcreturnvalue DOUBLE(8,0),
					IN var_gcreturnqty DECIMAL(18,0),
					IN var_gcreturnvalue DOUBLE(8,0),
					IN var_promoqty DECIMAL(18,0),
					IN var_cashsalesitemexcisetax DOUBLE(8,0),
					IN var_cashsalesitemgsttax DOUBLE(8,0),
					IN var_cashreturnitemexcisetax DOUBLE(8,0),
					IN var_cashreturnitemgsttax DOUBLE(8,0),
					IN var_cashdamageditemexcisetax DOUBLE(8,0),
					IN var_cashdamageditemgsttax DOUBLE(8,0),
					IN var_cashfgitemexcisetax DOUBLE(8,0),
					IN var_cashfgitemgsttax DOUBLE(8,0),
					IN var_cashpromoitemexcisetax DOUBLE(8,0),
					IN var_cashpromoitemgsttax DOUBLE(8,0),
					IN var_tcsalesitemexcisetax DOUBLE(8,0),
					IN var_tcsalesitemgsttax DOUBLE(8,0),
					IN var_tcreturnitemexcisetax DOUBLE(8,0),
					IN var_tcreturnitemgsttax DOUBLE(8,0),
					IN var_tcdamageditemexcisetax DOUBLE(8,0),
					IN var_tcdamageditemgsttax DOUBLE(8,0),
					IN var_tcfgitemexcisetax DOUBLE(8,0),
					IN var_tcfgitemgsttax DOUBLE(8,0),
					IN var_tcpromoitemexcisetax DOUBLE(8,0),
					IN var_tcpromoitemgsttax DOUBLE(8,0),
					IN var_gcsalesitemexcisetax DOUBLE(8,0),
					IN var_gcsalesitemgsttax DOUBLE(8,0),
					IN var_gcreturnitemexcisetax DOUBLE(8,0),
					IN var_gcreturnitemgsttax DOUBLE(8,0),
					IN var_gcdamageditemexcisetax DOUBLE(8,0),
					IN var_gcdamageditemgsttax DOUBLE(8,0),
					IN var_gcfgitemexcisetax DOUBLE(8,0),
					IN var_gcfgitemgsttax DOUBLE(8,0),
					IN var_gcpromoitemexcisetax DOUBLE(8,0),
					IN var_gcpromoitemgsttax DOUBLE(8,0),
					IN var_batchdetailkey DECIMAL(18,0),
					IN var_stdsalescaseprice DECIMAL(18,6),
					IN var_stdreturncaseprice DECIMAL(18,6),
					IN var_expiryqty DECIMAL(18,0),
					IN var_stdgoodreturncaseprice DECIMAL(18,6),
					IN var_stdgoodreturnprice DECIMAL(18,6),
					IN var_currencycode DECIMAL(18,0),
					IN var_returnfreeqty DECIMAL(18,0),
					IN var_damageqty DECIMAL(18,0),
					IN var_expdmgfreeqty DECIMAL(18,0),
					IN var_expunloadqty DECIMAL(18,0),
					IN var_dmgunloadqty DECIMAL(18,0),
					IN var_expdmgfreeunloadqty DECIMAL(18,0),
					IN var_rentqty DECIMAL(18,0),
					IN var_mdate DATETIME,	
					IN var_loadadjustqty DECIMAL(18,0)
				)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM inventorysummarydetail WHERE itemcode = var_itemcode AND routekey = var_routekey AND record_flag='1';
	
	IF cnt = 0 THEN
	
		INSERT INTO inventorysummarydetail SET 	
						inventorykey = var_inventorykey,
						itemcode = var_itemcode,
						routekey = var_routekey,
						weighted = var_weighted,
						beginstockqty = var_beginstockqty,
						loadqty = var_loadqty,
						loadaddqty = var_loadaddqty,
						loadcutqty = var_loadcutqty,
						loadreqqty = var_loadreqqty,
						saleqty = var_saleqty,
						returnqty = var_returnqty,
						damagedaddqty = var_damagedaddqty,
						damagedcutqty = var_damagedcutqty,
						endstockqty = var_endstockqty,
						unloadqty = var_unloadqty,
						damagedunloadqty = var_damagedunloadqty,
						freesampleqty = var_freesampleqty,
						truckdamagedunloadqty = var_truckdamagedunloadqty,
						stdsalesprice = var_stdsalesprice,
						stdreturnprice = var_stdreturnprice,
						cashsalesqty = var_cashsalesqty,
						cashsalesvalue = var_cashsalesvalue,
						tcsalesqty = var_tcsalesqty,
						tcsalesvalue = var_tcsalesvalue,
						gcsalesqty = var_gcsalesqty,
						gcsalesvalue = var_gcsalesvalue,
						cashdamagedqty = var_cashdamagedqty,
						cashdamagedvalue = var_cashdamagedvalue,
						tcdamagedqty = var_tcdamagedqty,
						tcdamagedvalue = var_tcdamagedvalue,
						gcdamagedqty = var_gcdamagedqty,
						gcdamagedvalue = var_gcdamagedvalue,
						cashreturnqty = var_cashreturnqty,
						cashreturnvalue = var_cashreturnvalue,
						tcreturnqty = var_tcreturnqty,
						tcreturnvalue = var_tcreturnvalue,
