					cashdamagedqty = var_cashdamagedqty,
					cashdamagedvalue = var_cashdamagedvalue,
					tcdamagedqty = var_tcdamagedqty,
					tcdamagedvalue = var_tcdamagedvalue,
					gcdamagedqty = var_gcdamagedqty,
					gcdamagedvalue = var_gcdamagedvalue,
					cashreturnqty = var_cashreturnqty,
