					gcreturnqty = var_gcreturnqty,
					gcreturnvalue = var_gcreturnvalue,
					promoqty = var_promoqty,
					cashsalesitemexcisetax = var_cashsalesitemexcisetax,
					cashsalesitemgsttax = var_cashsalesitemgsttax,
					cashreturnitemexcisetax = var_cashreturnitemexcisetax,
					cashreturnitemgsttax = var_cashreturnitemgsttax,
					cashdamageditemexcisetax = var_cashdamageditemexcisetax,
					cashdamageditemgsttax = var_cashdamageditemgsttax,
					cashfgitemexcisetax = var_cashfgitemexcisetax,
					cashfgitemgsttax = var_cashfgitemgsttax,
					cashpromoitemexcisetax = var_cashpromoitemexcisetax,
					cashpromoitemgsttax = var_cashpromoitemgsttax,
					tcsalesitemexcisetax = var_tcsalesitemexcisetax,
					tcsalesitemgsttax = var_tcsalesitemgsttax,
					tcreturnitemexcisetax = var_tcreturnitemexcisetax,
					tcreturnitemgsttax = var_tcreturnitemgsttax,
					tcdamageditemexcisetax = var_tcdamageditemexcisetax,
					tcdamageditemgsttax = var_tcdamageditemgsttax,
					tcfgitemexcisetax = var_tcfgitemexcisetax,
					tcfgitemgsttax = var_tcfgitemgsttax,
					tcpromoitemexcisetax = var_tcpromoitemexcisetax,
					tcpromoitemgsttax = var_tcpromoitemgsttax,
					gcsalesitemexcisetax = var_gcsalesitemexcisetax,
					gcsalesitemgsttax = var_gcsalesitemgsttax,
					gcreturnitemexcisetax = var_gcreturnitemexcisetax,
					gcreturnitemgsttax = var_gcreturnitemgsttax,
					gcdamageditemexcisetax = var_gcdamageditemexcisetax,
					gcdamageditemgsttax = var_gcdamageditemgsttax,
					gcfgitemexcisetax = var_gcfgitemexcisetax,
					gcfgitemgsttax = var_gcfgitemgsttax,
					gcpromoitemexcisetax = var_gcpromoitemexcisetax,
					gcpromoitemgsttax = var_gcpromoitemgsttax,
					batchdetailkey = var_batchdetailkey,
					stdsalescaseprice = var_stdsalescaseprice,
					stdreturncaseprice = var_stdreturncaseprice,
					expiryqty = var_expiryqty,
					stdgoodreturncaseprice = var_stdgoodreturncaseprice,
					stdgoodreturnprice = var_stdgoodreturnprice,
					currencycode = get_default_currencycode_routekey(var_routekey),
					returnfreeqty = var_returnfreeqty,
					damageqty = var_damageqty,
					expdmgfreeqty = var_expdmgfreeqty,
					expunloadqty = var_expunloadqty,
					dmgunloadqty = var_dmgunloadqty,
					expdmgfreeunloadqty = var_expdmgfreeunloadqty,
					loadadjustqty=var_loadadjustqty,
					rentqty = var_rentqty,
					mdat = CURRENT_DATE(),
					vanstock = (var_beginstockqty + var_loadqty + var_loadaddqty - var_loadcutqty - var_saleqty + var_returnqty - var_freesampleqty - var_promoqty + var_returnfreeqty),
					vanstockvalue = (var_beginstockqty + var_loadqty + var_loadaddqty - var_loadcutqty - var_saleqty + var_returnqty - var_freesampleqty - var_promoqty + var_returnfreeqty) * var_stdsalesprice
			WHERE itemcode = var_itemcode AND routekey = var_routekey AND record_flag='1';
			
		END IF;			
											
		SELECT var_routekey AS lastid; 		
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_inventorytransactiondetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_inventorytransactiondetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_inventorytransactiondetail`(
					IN var_routekey DECIMAL(28,0),
					IN var_detailkey BIGINT(20),
					IN var_transactiontypecode BIGINT(20),
					IN var_itemcode BIGINT(20),
					IN var_quantity DECIMAL(18,0),
					IN var_weighted INT(11),
					IN var_itemprice DECIMAL(18,6),
					IN var_batchdetailkey DECIMAL(18,0),
					IN var_itemcaseprice DECIMAL(18,6),
					IN var_currencycode DECIMAL(18,0),
					IN var_requestedqty BIGINT(18),
					IN var_expirydate DATETIME,
					IN var_reasoncode INT(18)
				)
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM inventorytransactiondetail 
WHERE itemcode = var_itemcode AND routekey = var_routekey AND detailkey = var_detailkey AND 
	transactiontypecode = var_transactiontypecode;
IF cnt = 0 THEN
	INSERT INTO inventorytransactiondetail SET 
		routekey = var_routekey,
		detailkey = var_detailkey,
		transactiontypecode = var_transactiontypecode,
		itemcode = var_itemcode,
		quantity = var_quantity,
		requestedqty = var_requestedqty,
		weighted = var_weighted,
		itemprice = var_itemprice,
		batchdetailkey = var_batchdetailkey,
		itemcaseprice = var_itemcaseprice,
		currencycode = get_default_currencycode_routekey(var_routekey),
		record_flag='1',
		expirydate = var_expirydate,
		reasoncode = var_reasoncode;
ELSE
	UPDATE inventorytransactiondetail SET 	
						
		transactiontypecode = var_transactiontypecode,					       
		quantity = var_quantity,
		requestedqty = var_requestedqty,
		weighted = var_weighted,
		itemprice = var_itemprice,
		batchdetailkey = var_batchdetailkey,
		itemcaseprice = var_itemcaseprice,
		currencycode = get_default_currencycode_routekey(var_routekey),
		expirydate = var_expirydate,
		reasoncode = var_reasoncode
		
	WHERE itemcode = var_itemcode AND routekey = var_routekey AND detailkey = var_detailkey AND 
		record_flag='1' AND transactiontypecode = var_transactiontypecode;
	
	END IF;
 				
	SELECT var_routekey AS lastid;
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_inventorytransactionheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_inventorytransactionheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_inventorytransactionheader`(
	IN var_inventorykey DECIMAL(28,0),
	IN var_routekey DECIMAL(28,0),
	IN var_transactiontype INT(11),
	IN var_routecode DECIMAL(28,0),
	IN var_salesmancode INT(11),
	IN var_transactiondate DATETIME,
	IN var_transactiontime VARCHAR(10),
	IN var_documentnumber DECIMAL(28,0),
	IN var_odometerreading DECIMAL(18,0),
	IN var_transferlocationcode DECIMAL(18,0),
	IN var_referencenumber DECIMAL(28,0),
	IN var_requestdate DATETIME,
	IN var_securitycode DECIMAL(18,0),
	IN var_transmitindicator INT(11),
	IN var_voidflag INT(11),
	IN var_hhcdocumentnumber DECIMAL(28,0),
	IN var_loadnumber INT(11),
	IN var_refdocumentnumber DECIMAL(18,0),
	IN var_currencycode DECIMAL(18,0),
	IN var_actualtransactiondate DATETIME,
	IN var_inventorynumber DECIMAL(18,0),
	IN var_data INT(11),
	IN var_isurgent INT(11)
)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM inventorytransactionheader WHERE  documentnumber = var_documentnumber;
 	
 	IF cnt = 0 THEN		
		INSERT INTO inventorytransactionheader SET 
			inventorykey = var_inventorykey,			
			routekey = var_routekey,
			transactiontype = var_transactiontype,
			routecode = var_routecode,
			salesmancode = var_salesmancode,
			transactiondate = var_transactiondate,
			transactiontime = var_transactiontime,
			documentnumber = var_documentnumber,
			odometerreading = var_odometerreading,
			transferlocationcode = CASE WHEN var_transactiontype = 4 AND var_transferlocationcode = 0 THEN 1 ELSE var_transferlocationcode END,
			referencenumber = var_referencenumber,
			requestdate = var_requestdate,
			deliverydate = IF(var_transactiontype < 4,var_transactiondate, var_requestdate + INTERVAL 1 DAY),
			securitycode = var_securitycode,
			transmitindicator = var_transmitindicator,
			voidflag = var_voidflag,
			hhcdocumentnumber = var_documentnumber,
			loadnumber = var_loadnumber,
			refdocumentnumber = var_refdocumentnumber,
			currencycode = get_default_currencycode_routecode(var_routecode),
			actualtransactiondate = var_actualtransactiondate,
			inventorynumber = var_documentnumber,
			DATA = var_data,
			record_flag='1',
			isurgent=var_isurgent,
			receivedtime = NOW();
			
		IF var_loadnumber > 0 THEN
			UPDATE startingloaddetail 
			SET STATUS = 1 
			WHERE routecode = var_routecode AND loadperiodnumber = var_loadnumber;			
		END IF;
		
		SELECT LAST_INSERT_ID() AS lastid ;  
		
	ELSE		
		
		SELECT detailkey AS lastid FROM inventorytransactionheader WHERE documentnumber = var_documentnumber;
		
 	END IF;
 	
   END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_inventoryvariance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_inventoryvariance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_inventoryvariance`(
					IN var_routekey DECIMAL(28,0),
					IN var_currencycode DECIMAL(18,0)
				)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	DECLARE var_routecode BIGINT(28);
	DECLARE var_customercode BIGINT(28);
	DECLARE var_salesmancode BIGINT(28);
	DECLARE var_document_number BIGINT(28);
	DECLARE var_totalinvoiceamount DECIMAL(20,5);
	DECLARE invoicedetailids INT DEFAULT 0;
	
	SELECT startendday.routecode,startendday.salesmancode,variancecustomercode INTO var_routecode,var_salesmancode,var_customercode FROM startendday 
	LEFT JOIN routemaster rm ON rm.routecode = startendday.routecode WHERE routekey = var_routekey;
	
	IF var_customercode > 0 THEN
	-- get document number
	SELECT (CONCAT(routecode,0,LPAD(IFNULL(bodocseq,0),6,'0'))+1) INTO var_document_number FROM routemaster WHERE routecode = var_routecode;
	
	-- update bodocseq
	UPDATE routemaster SET bodocseq = bodocseq + 1 WHERE routecode = var_routecode;
	INSERT INTO customeroperationscontrol SET 
									routekey 				= var_routekey,
									visitkey 				= 0,
									customercode 			= var_customercode,
									routecode 				= var_routecode,
									salesmancode 			= var_salesmancode,
									odometerreading			= 0,
									visitstartdate			= CURRENT_DATE(),
									visitstarttime			= TIME(CURRENT_DATE()),
									visitenddate			= CURRENT_DATE(),
									visitendtime			= TIME(CURRENT_DATE()),
									totaltransactions		= 1,
									addedcustomer			= 0,
									voidflag				= 0,
									scannerindicator		= 0,
									reasoncode				= 0,
									latitude				= 0,
									longitude				= 0,
									radius					= 0;
	SELECT LAST_INSERT_ID() INTO @customerlastid;
	
	INSERT INTO invoiceheader SET 	
									routekey 				= var_routekey,
									visitkey 				= 0,
									documentnumber			= var_document_number,
									invoicenumber			= var_document_number,
									transactiondate			= CURRENT_DATE(),
									transactiontime 		= TIME(CURRENT_DATE()),
									customercode 			= var_customercode,
									routecode 				= var_routecode,
									salesmancode 			= var_salesmancode,
									amountpaid				= 0,
									invoicebalance			= 0,
									paymenttype 			= 0,
									paymentstatus 			= 0,
									gcpaymenttype 			= 1,
									currencycode 			= var_currencycode,
									actualtransactiondate 	= CURRENT_DATE(),
									hhctransactionkey		= 0,
									record_flag 			= 3,
									varianceflag 			= 1;
									
	SELECT LAST_INSERT_ID() INTO @lastid;
	
	SELECT itemcode INTO @varianceitem FROM inventorytransactiondetail WHERE transactiontypecode = 9 AND routekey = var_routekey;
	
	IF @varianceitem > 0 THEN
		INSERT INTO invoicedetail (routekey,visitkey,transactionkey,itemcode,salesqty,salesprice,stdsalesprice,salescaseprice,stdsalescaseprice,currencycode)   	
		SELECT var_routekey,0,@lastid,itemcode,quantity,itemprice,itemprice,itemcaseprice,itemcaseprice,var_currencycode FROM inventorytransactiondetail WHERE transactiontypecode = 9 AND routekey = var_routekey;		
	
		SELECT ((quantity/unitspercase)*itemcaseprice)+((quantity%unitspercase)*itemprice) INTO var_totalinvoiceamount FROM inventorytransactiondetail JOIN itemmaster ON actualitemcode = itemcode WHERE routekey = var_routekey AND transactiontypecode = 9;	
		UPDATE invoiceheader SET totalinvoiceamount = var_totalinvoiceamount, amountpaid = var_totalinvoiceamount WHERE routekey = var_routekey AND visitkey = 0;
	ELSE
		DELETE FROM customeroperationscontrol WHERE primary_id = @customerlastid;
		DELETE FROM invoiceheader WHERE transactionkey = @lastid;		
		-- update bodocseq
		UPDATE routemaster SET bodocseq = bodocseq - 1 WHERE routecode = var_routecode;
	END IF;
	END IF;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_invoicerxddetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_invoicerxddetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_invoicerxddetail`(	    
		IN var_routekey DECIMAL(28,0),
		IN var_visitkey DECIMAL(28,0),
		IN var_transactionkey DECIMAL(28,0),
		IN var_itemtransactiontype INT(11),
		IN var_itemcode DECIMAL(18,0),
		IN var_itemtranstypeseq INT(11),
		IN var_reasoncode INT(11),
		IN var_quantity DECIMAL(18,0),
		IN var_catchweightqty DECIMAL(18,0),
		IN var_weighted INT(11),
		IN var_instructioncode INT(11),
		IN var_currencycode DECIMAL(18,0),
		IN var_expirydate DATETIME,
		IN var_invoiceno DECIMAL(28,0),
		IN var_batchnumber VARCHAR(200)
	)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM invoicerxddetail 
		WHERE routekey = var_routekey AND visitkey =var_visitkey AND itemcode =var_itemcode AND 
			itemtransactiontype = var_itemtransactiontype AND reasoncode = var_reasoncode;
			
 	IF cnt = 0 THEN
	
		INSERT INTO invoicerxddetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			itemtransactiontype = var_itemtransactiontype,
			itemcode = var_itemcode,
			itemtranstypeseq = var_itemtranstypeseq,
			reasoncode = var_reasoncode,
			quantity = var_quantity,
			catchweightqty = var_catchweightqty,
			weighted = var_weighted,
			instructioncode = var_instructioncode,
			currencycode = get_default_currencycode_routekey(var_routekey),
			expirydate = var_expirydate,
			invoiceno = var_invoiceno,
			receivedtime = CURTIME(),
			batchnumber=var_batchnumber;
	
	END IF;
	
	SELECT var_routekey AS lastid; 	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_nonservicedcustomer` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_nonservicedcustomer` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_nonservicedcustomer`(
					IN var_routekey DECIMAL(28,0),
					IN var_customercode DECIMAL(18,0),
					IN var_reasoncode INT(11)
				)
BEGIN
	
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM nonservicedcustomer WHERE `routekey` = var_routekey AND `customercode` = var_customercode;
 	
	IF cnt = 0 THEN
	
		INSERT INTO nonservicedcustomer SET routekey = var_routekey,
											customercode = var_customercode,
											reasoncode = var_reasoncode;
											
		SELECT var_routekey AS lastid; 	
	
	ELSE
		SELECT var_routekey AS lastid; 	
	
	END IF;
	
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_orderrxddetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_orderrxddetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_orderrxddetail`(	    
		IN var_routekey DECIMAL(28,0),
		IN var_visitkey DECIMAL(28,0),
		IN var_transactionkey DECIMAL(28,0),
		IN var_itemtransactiontype INT(11),
		IN var_itemcode DECIMAL(18,0),
		IN var_itemtranstypeseq INT(11),
		IN var_reasoncode INT(11),
		IN var_quantity DECIMAL(18,0),
		IN var_catchweightqty DECIMAL(18,0),
		IN var_weighted INT(11),
		IN var_instructioncode INT(11),
		IN var_expirydate DATETIME
	)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM orderrxddetail 
		WHERE routekey = var_routekey AND visitkey =var_visitkey AND itemcode =var_itemcode AND 
			itemtransactiontype = var_itemtransactiontype AND reasoncode = var_reasoncode;
			
 	IF cnt = 0 THEN
	
		INSERT INTO orderrxddetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			itemtransactiontype = var_itemtransactiontype,
			itemcode = var_itemcode,
			itemtranstypeseq = var_itemtranstypeseq,
			reasoncode = var_reasoncode,
			quantity = var_quantity,
			catchweightqty = var_catchweightqty,
			weighted = var_weighted,
			instructioncode = var_instructioncode,
			expirydate = var_expirydate,
			receivedtime = CURTIME();
	
	END IF;
	
	SELECT var_routekey AS lastid; 	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_posequipmentchangedetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_posequipmentchangedetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_posequipmentchangedetail`(
IN var_routekey DECIMAL(28,0),
IN var_visitkey DECIMAL(28,0),
IN var_posaction INT(11),
IN var_itemcode DECIMAL(18,0),
IN var_quantity DECIMAL(18,0),
IN var_serialnumber VARCHAR(50),
IN var_instructioncode INT(11))
BEGIN
    DECLARE cnt INT DEFAULT 0;
    SELECT COUNT(*) INTO cnt FROM posequipmentchangedetail WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `itemcode`= var_itemcode;
 	IF cnt = 0 THEN	
 	
 	INSERT INTO posequipmentchangedetail SET routekey = var_routekey,
			visitkey = var_visitkey,
			posaction = var_posaction,
			itemcode = var_itemcode,
			quantity = var_quantity,
			serialnumber = var_serialnumber,
			instructioncode = var_instructioncode;
 	
 	SELECT var_routekey AS lastid FROM posequipmentchangedetail; 
 	ELSE
 	UPDATE posequipmentchangedetail SET routekey = var_routekey,
			visitkey = var_visitkey,
			posaction = var_posaction,
			itemcode = var_itemcode,
			quantity = var_quantity,
			serialnumber = var_serialnumber,
			instructioncode = var_instructioncode
			;
 	
 	
 	SELECT var_routekey AS lastid; 
 	END IF;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_posmaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_posmaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_posmaster`(
					IN var_alternatecode VARCHAR(50),
					IN var_itemdescription VARCHAR(50),
					IN var_arbitemdescription VARCHAR(50),
					IN var_itemvalue DECIMAL(19,4),
					IN var_inventorytype INT(11),
					IN var_created CHAR(20),
					IN var_activestatus INT(11)
				)
BEGIN
	
	INSERT INTO posmaster SET 	alternatecode = var_alternatecode,
								itemdescription = var_itemdescription,
								arbitemdescription = var_arbitemdescription,
								itemvalue = var_itemvalue,
								inventorytype = var_inventorytype,
								created = var_created,
								cdat = CURRENT_DATE(),
								modified = var_created,
								mdat = CURRENT_DATE(),
								activestatus = var_activestatus;
	
 				
	SELECT LAST_INSERT_ID() AS lastid; 	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_promotiondetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_promotiondetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_promotiondetail`(	    
					IN var_routekey DECIMAL(28,0),
					IN var_visitkey DECIMAL(28,0),
					IN var_transactionkey DECIMAL(28,0),
					IN var_itemtransactiontype INT(11),
					IN var_itemcode BIGINT(20),
					IN var_promotiontypecode INT(11),
					IN var_promotionamount DECIMAL(19,4),
					IN var_promotionquantity DECIMAL(18,0),
					IN var_catchweightqty INT(11),
					IN var_weighted INT(11),
					IN var_promotionplannumber INT(11),
					IN var_assignmentkey INT(11),
					IN var_exclusionoption INT(11),
					IN var_promochgindicator INT(11),
					IN var_oldpromotionamount DECIMAL(19,4),
					IN var_performindicator INT(11),
					IN var_performcriteriakey INT(11),
					IN var_promotioncaseprice DECIMAL(19,4),
					IN var_currencycode DECIMAL(18,0),
					IN var_memo1 varchar(50)
				)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	
	SELECT COUNT(*) INTO cnt FROM promotiondetail 
		WHERE routekey = var_routekey AND visitkey =var_visitkey AND itemcode =var_itemcode AND 
			itemtransactiontype = var_itemtransactiontype AND promotiontypecode = var_promotiontypecode AND
			promotionplannumber = var_promotionplannumber;
 
	IF cnt = 0 THEN
	
		IF var_promotiontypecode = 5 OR var_promotiontypecode = 6 THEN
			SET var_itemcode = 0;
		END IF; 
	
		INSERT INTO promotiondetail SET 	
				routekey = var_routekey,
				visitkey = var_visitkey,
				transactionkey = var_transactionkey,
				itemtransactiontype = var_itemtransactiontype,
				itemcode = var_itemcode,
				promotiontypecode = var_promotiontypecode,
				promotionamount = (var_oldpromotionamount * var_promotionamount)/100,
				promotionquantity = var_promotionquantity,
				catchweightqty = var_catchweightqty,
				weighted = var_weighted,
				promotionplannumber = var_promotionplannumber,
				assignmentkey = var_assignmentkey,
				exclusionoption = var_exclusionoption,
				promochgindicator = var_promochgindicator,
				oldpromotionamount = var_oldpromotionamount,
				performindicator = var_performindicator,
				performcriteriakey = var_performcriteriakey,
				promotioncaseprice = var_promotioncaseprice,
				currencycode = var_currencycode,
				memo1 = var_memo1,
				promotionpercent = var_promotionamount;
				
 ELSE
 
		UPDATE promotiondetail SET 					
				itemtransactiontype = var_itemtransactiontype,
				promotiontypecode = var_promotiontypecode,
				promotionamount = (var_oldpromotionamount * var_promotionamount)/100,
				promotionquantity = var_promotionquantity,
				catchweightqty = var_catchweightqty,
				weighted = var_weighted,
				promotionplannumber = var_promotionplannumber,
				assignmentkey = var_assignmentkey,
				exclusionoption = var_exclusionoption,
				promochgindicator = var_promochgindicator,
				oldpromotionamount = var_oldpromotionamount,
				performindicator = var_performindicator,
				performcriteriakey = var_performcriteriakey,
				promotioncaseprice = var_promotioncaseprice,
				currencycode = var_currencycode,
				memo1 = var_memo1,
				promotionpercent = var_promotionamount
		WHERE routekey = var_routekey AND visitkey =var_visitkey AND itemcode =var_itemcode;
		
END IF;	
		
	-- UPDATE promotiondetail AS p 
	-- 		JOIN invoicedetail ON invoicedetail.itemcode = p.itemcode AND invoicedetail.visitkey=var_visitkey AND invoicedetail.routekey=var_routekey 
	-- 	SET p.promotionquantity=invoicedetail.freesampleqty 
	-- WHERE p.promotiontypecode=7 AND p.routekey = var_routekey AND p.visitkey =var_visitkey AND p.promotionplannumber=var_promotionplannumber AND 
	--	p.itemtransactiontype=var_itemtransactiontype;						
	
	DELETE FROM promotiondetail WHERE promotiontypecode=7 AND routekey = var_routekey AND visitkey =var_visitkey AND promotionquantity=0;		
 		
	SELECT var_routekey AS lastid; 	
	
 END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_routemaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_routemaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_routemaster`(
        IN var_routecode bigint(20),
        IN var_mdat datetime,
	IN var_hhcordseq int(11),
	IN var_hhcinvseq int(11),
	IN var_hhccshseq int(11),
	IN var_hhcivtseq int(11),
	IN var_bodocseq int(11),
	IN var_cashbalance int(4),
	IN var_creditlimit double(8,0),
	IN var_routebalance double(8,0),
	IN var_hhcarseq decimal(18,0),
	IN var_hhcloadseq decimal(18,0),
	IN var_hhcappversion int(4),
	IN var_hhcinvretseq  INT(4)
	
)
BEGIN
    
     	
 	UPDATE routemaster SET
			mdat = CURRENT_DATE(),
			hhcordseq = var_hhcordseq,
			hhcinvseq = var_hhcinvseq,
			hhccshseq = var_hhccshseq,
			hhcivtseq = var_hhcivtseq,
			bodocseq = var_bodocseq,
			-- creditlimit = var_creditlimit,
			routebalance = var_routebalance,
			hhcarseq = var_hhcarseq,
			hhcloadseq = var_hhcloadseq 
			 WHERE routecode = var_routecode;
			 
	Select routecode as lastid from routemaster  WHERE routecode = var_routecode;		 
			 
 	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_routetrack` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_routetrack` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_routetrack`(
	IN var_latitude DECIMAL(18,6),
	IN var_longitude DECIMAL(18,6),
	IN var_deviceid VARCHAR(50)
	)
BEGIN
	
	SELECT COALESCE(MAX(routekey),0) routekey INTO @routekey
	FROM startendday
	WHERE routeclosed = 0 AND dataconrefnumber = var_deviceid;
	
	IF @routekey > 0 THEN
		SELECT routecode, salesmancode INTO @routecode, @salesmancode
		FROM startendday
		WHERE routekey = @routekey;
		
		INSERT INTO routetrack SET 	
			routekey = @routekey,
			routecode = @routecode,
			salesmancode = @salesmancode,
			entrydate = CURDATE(),
			entrytime = CURTIME(),
			deviceid = var_deviceid,
			latitude = var_latitude,
			longitude = var_longitude;
			
		SELECT LAST_INSERT_ID() AS lastid ; 
		
	ELSE
		SELECT 0 AS lastid;
				
	END IF;								
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_salesorderdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_salesorderdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_salesorderdetail`(
		IN var_routekey DECIMAL(28,0),
		IN var_visitkey DECIMAL(28,0),
		IN var_transactionkey DECIMAL(28,0),
		IN var_itemcode DECIMAL(18,0),
		IN var_salesqty DECIMAL(18,0),
		IN var_returnqty DECIMAL(18,0),
		IN var_damagedqty DECIMAL(18,0),
		IN var_freesampleqty DECIMAL(18,0),
		IN var_salesprice DECIMAL(18,6),
		IN var_returnprice DECIMAL(18,6),
		IN var_stdsalesprice DECIMAL(18,6),
		IN var_stdreturnprice DECIMAL(18,6),
		IN var_coopid CHAR(10),
		IN var_salescaseprice DECIMAL(18,6),
		IN var_returncaseprice DECIMAL(18,6),
		IN var_stdsalescaseprice DECIMAL(18,6),
		IN var_stdreturncaseprice DECIMAL(18,6),
		IN var_currencycode DECIMAL(18,0),
		IN var_allocated DECIMAL(18,0),
		IN var_freegoodcases DECIMAL(18,0),
		IN var_freegoodpcs DECIMAL(18,0),
		IN var_salespcs DECIMAL(18,0),
		IN var_allocatedcases DECIMAL(18,0),
		IN var_salescases DECIMAL(18,0),
		IN var_allocatedpcs DECIMAL(18,0),
		IN var_returncases DECIMAL(18,0),
		IN var_returnpcs DECIMAL(18,0),
		IN var_manualfreeqty DECIMAL(18,0),
		IN var_salesordervat  DECIMAL(19,4),
		IN var_salesorderexcisetax DECIMAL(19,4),
		IN var_returnvat DECIMAL(19,4),
		IN var_returnexcisetax DECIMAL(19,4),
		IN var_damagedvat DECIMAL(19,4),
		IN var_damagedexcisetax DECIMAL(19,4),
		IN var_promovat DECIMAL(19,4),
		IN var_promoexcisetax DECIMAL(19,4),
		IN var_fgvat DECIMAL(19,4),
		IN var_fgexcisetax DECIMAL(19,4),
		IN var_promoamount DECIMAL(19,4),
		IN var_promovalue DECIMAL(19,4)
	)
BEGIN
	DECLARE cnt INT DEFAULT 0;
	SELECT COUNT(*) INTO cnt FROM salesorderdetail WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `itemcode` =var_itemcode;
 	
 	IF cnt = 0 THEN		
		INSERT INTO salesorderdetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			itemcode = var_itemcode,
			salesqty = var_salesqty,
			returnqty = var_returnqty,
			damagedqty = var_damagedqty,
			freesampleqty = var_freesampleqty,			
			-- salesprice = var_returnprice,
			salesprice = var_salesprice,
			returnprice = var_returnprice,
			stdsalesprice = var_stdsalesprice,
			stdreturnprice = var_stdreturnprice,
			coopid = var_coopid,
			salescaseprice = var_salescaseprice,
			returncaseprice = var_returncaseprice,
			stdsalescaseprice = var_stdsalescaseprice,
			stdreturncaseprice = var_stdreturncaseprice,
			currencycode = get_default_currencycode_routekey(var_routekey),
			allocated = var_allocated,
			freegoodcases = var_freegoodcases,
			freegoodpcs = var_freegoodpcs,
			manualfreeqty = var_manualfreeqty,
			salespcs = var_salespcs,
			allocatedcases = var_allocatedcases,
			salescases = var_salescases,
			allocatedpcs = var_allocatedpcs,
			returncases = var_returncases,
			returnpcs = var_returnpcs,
			receivedtime = CURTIME(),
			salesordervat = var_salesordervat,
			salesorderexcisetax = var_salesorderexcisetax,
			returnvat = var_returnvat,
			returnexcisetax = var_returnexcisetax,
			damagedvat  = var_damagedvat,
			damagedexcisetax  = var_damagedexcisetax,
			promovat  = var_promovat,
			promoexcisetax  = var_promoexcisetax,
			fgvat  = var_fgvat,
			fgexcisetax = var_fgexcisetax,
			promoamount=var_promoamount,
			promovalue=var_promovalue;	
	END IF;
	
	SELECT var_routekey AS lastid;
 				
		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_salesorderheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_salesorderheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_salesorderheader`(
	IN var_transactionkey DECIMAL(28,0),
	IN var_routekey DECIMAL(28,0),
	IN var_visitkey DECIMAL(28,0),
	IN var_documentnumber DECIMAL(28,0),
	IN var_invoicenumber DECIMAL(28,0),
	IN var_transactiondate DATETIME,
	IN var_transactiontime VARCHAR(10),
	IN var_dsdnumber VARCHAR(20),
	IN var_ponumber VARCHAR(20),
	IN var_customercode DECIMAL(18,0),
	IN var_routecode DECIMAL(18,0),
	IN var_salesmancode DECIMAL(10,0),
	IN var_orderdeliveryroutecode DECIMAL(18,0),
	IN var_orderdeliverydate DATETIME,
	IN var_totalinvoiceamount DOUBLE(18,4),
	IN var_totalsalesamount DOUBLE(18,4),
	IN var_totalreturnamount DOUBLE(18,4),
	IN var_totaldamagedamount DOUBLE(18,4),
	IN var_dexflag INT(4),
	IN var_splittransaction INT(4),
	IN var_voidflag INT(4),
	IN var_transmitindicator INT(4),
	IN var_hhcinvoicenumber DECIMAL(28,0),
	IN var_paymenttype INT(4),
	IN var_hhcdocumentnumber DECIMAL(28,0),
	IN var_voidreasoncode INT(4),
	IN var_advanceused DOUBLE(8,0),
	IN var_paymentstatus INT(4),
	IN var_advancebalance DOUBLE(8,0),					
	IN var_advancereceived DOUBLE(8,0),
	IN var_currencycode DECIMAL(18,0),
	IN var_status INT(4),
	IN var_refnumber DECIMAL(28,0),
	IN var_totalfreesampleamount DOUBLE(8,0),
	IN var_deliverystatus VARCHAR(25),
	IN var_data INT(4),
	IN var_comments VARCHAR(200),
	IN var_actualtransactiondate DATETIME,
	IN var_comments2 VARCHAR(200),
	IN var_hhctransactionkey DECIMAL(18,0),
	IN var_mdate DATETime,
	IN var_totalpromoamount DECIMAL(19,4),
	IN var_totallineitemtax DECIMAL(19,4)
)
BEGIN
	
DECLARE cnt INT DEFAULT 0;
	
SELECT COUNT(*) INTO cnt FROM salesorderheader WHERE `invoicenumber` = var_invoicenumber;
IF cnt = 0 THEN	
 	
	INSERT INTO salesorderheader SET 	
		routekey = var_routekey,
		visitkey = var_visitkey,
		documentnumber = var_documentnumber,
		invoicenumber = var_invoicenumber,
		transactiondate = var_transactiondate,
		transactiontime = var_transactiontime,
		dsdnumber = var_dsdnumber,
		ponumber = var_ponumber,
		customercode = var_customercode,
		routecode = var_routecode,
		salesmancode = var_salesmancode,
		orderdeliveryroutecode = var_orderdeliveryroutecode,
		orderdeliverydate = var_orderdeliverydate,
		totalinvoiceamount = var_totalinvoiceamount,
		totalsalesamount = var_totalsalesamount,
		totalreturnamount = var_totalreturnamount,
		totaldamagedamount = var_totaldamagedamount,
		dexflag = var_dexflag,
		splittransaction = var_splittransaction,
		voidflag = var_voidflag,
		transmitindicator = CASE WHEN var_voidflag = 1 THEN 2 ELSE var_transmitindicator END,
		hhcinvoicenumber = var_hhcinvoicenumber,
		paymenttype = var_paymenttype,
		hhcdocumentnumber = var_hhcdocumentnumber,
		voidreasoncode = var_voidreasoncode,
		advanceused = var_advanceused,
		paymentstatus = var_paymentstatus,
		advancebalance = var_advancebalance,
		mdat = CURRENT_DATE(),
		advancereceived = var_advancereceived,
		currencycode = get_default_currencycode_routekey(var_routekey),
		`status` = var_status,
		refnumber = var_refnumber,
		totalfreesampleamount = var_totalfreesampleamount,
		deliverystatus = var_deliverystatus,
		`data` = var_data,
		comments = var_comments,
		actualtransactiondate = var_actualtransactiondate,
		comments2 = var_comments2,
		hhctransactionkey = var_hhctransactionkey,
		totalpromoamount=var_totalpromoamount,
		record_flag='1',
		receivedtime = CURTIME(),
		totallineitemtax = var_totallineitemtax;	
 				
	SELECT LAST_INSERT_ID() AS lastid ; 					
			
ELSE
	UPDATE salesorderheader SET 
		voidflag = var_voidflag,
		transmitindicator = CASE WHEN var_voidflag = 1 THEN 2 ELSE var_transmitindicator END
	WHERE `invoicenumber` = var_invoicenumber;
		
	SELECT transactionkey AS lastid FROM salesorderheader WHERE `invoicenumber` = var_invoicenumber;
END IF;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_sigcaptchdata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_sigcaptchdata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_sigcaptchdata`(
		 IN var_routekey DECIMAL(28,0),
		IN var_visitkey DECIMAL(28,0),
		IN var_transactionkey DECIMAL(28,0),
		IN var_customercode BIGINT(18),
		IN var_documentnumber DECIMAL(28,0),
		IN var_transactiondate DATETIME,
		IN var_transactiontime VARCHAR(10),
		IN var_balancedueamount DOUBLE(8,0),
		IN var_signaturedata BLOB,
		IN var_transctiontype INT(11)
)
BEGIN
DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM sigcapturedata 
	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `customercode` = var_customercode;
IF cnt = 0 THEN	
	
		INSERT INTO sigcapturedata SET 
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = var_transactionkey,
			customercode = var_customercode,
			documentnumber = var_documentnumber,
			transactiondate = var_transactiondate,
			transactiontime = var_transactiontime,
			balancedueamount = var_balancedueamount,
			signaturedata = var_signaturedata,
			transaction_type=var_transctiontype;
  END IF;									
 				
 SELECT var_routekey AS lastid; 	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_surveyauditdetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_surveyauditdetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_surveyauditdetail`(
					IN var_routekey DECIMAL(28,0),
					IN var_visitkey DECIMAL(28,0),
					IN var_surveydefkey BIGINT(20),
					IN var_surveypage INT(11),
					IN var_surveyindex INT(11),
					IN var_surveyrectype INT(11),
					IN var_lookuptype INT(11),
					IN var_surveyresponse VARCHAR(50)
				)
BEGIN
	
	DECLARE cnt INT DEFAULT 0;
SELECT COUNT(*) INTO cnt FROM surveyauditdetail WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `surveydefkey` = var_surveydefkey  ;
 	IF cnt = 0 THEN
	
	INSERT INTO surveyauditdetail SET 	routekey = var_routekey,
										visitkey = var_visitkey,
										surveydefkey = var_surveydefkey,
										surveypage = var_surveypage,
										surveyindex = var_surveyindex,
										surveyrectype = var_surveyrectype,
										lookuptype = var_lookuptype,
										surveyresponse = var_surveyresponse;
	ELSE
	UPDATE surveyauditdetail SET 	routekey = var_routekey,
										visitkey = var_visitkey,
										surveydefkey = var_surveydefkey,
										surveypage = var_surveypage,
										surveyindex = var_surveyindex,
										surveyrectype = var_surveyrectype,
										lookuptype = var_lookuptype,
										surveyresponse = var_surveyresponse
										WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `surveydefkey` = var_surveydefkey;
	
 	END IF;			
	SELECT var_routekey AS lastid; 	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getdata_from_tablet` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getdata_from_tablet` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getdata_from_tablet`(
