		item.itemshortdescription,
		item.itemdescription,
		item.unitspercase,
		item.defaultsalesprice,
		item.defaultreturnprice,
		item.defaultretailprice,
		item.pricingkey,
		item.arbitemshortdescription,
		item.arbitemdescription,
