		item.defpricetaxkey2,
		item.defpricetaxkey3,
		item.packagecode,
		item.anitemcode,
		item.averagesales,
		item.enablemeatpiecescapture,
		item.itemcompany,
		item.caseuom,
		item.warehousestock,
		item.itemgrpcode,
		item.parentitemcode,
		item.shelflife,
		item.defaultgoodreturnprice,
		item.defaultgoodreturncaseprice,
		item.maxpricechange,
		item.minpricechange,
		item.allowbatchentry,
		item.temp1,
		item.costcaseprice,
		item.defaultcostprice,
		item.allowinvoicepricechange,
		item.reportitemcode from itemmaster As item
		LEFT JOIN inventorytransactiondetail AS imd ON item.actualitemcode = imd.ItemCode where imd.RouteKey = RouteId;
	-- Query for Customer master by Route code
	Select  cust.customercode,
		cust.type,
		cust.headofficecode,
		cust.routecode,
		cust.streetcode,
		cust.districtcode,
		cust.locationcode,
		cust.customersequence,
		cust.customername,
		cust.customeraddress1,
		cust.customeraddress2,
		cust.customerphone,
		cust.balance,
		cust.customercategory,
		cust.pricingkey,
		cust.promotionkey,
		cust.authorizeditemgrpkey,
		cust.messagekey1,
		cust.messagekey2,
		cust.invoicepaymentterms,
		cust.invoiceretailoption,
		cust.invoicepriceoverride,
		cust.invoiceretailoverride,
		cust.invoiceformatoption,
		cust.invoiceextensionopt,
		cust.invoicedsdpromptopt,
		cust.invoicecopies,
		cust.salesinputoprion,
		cust.returnsinputoption,
		cust.invoiceinputstyle,
		cust.onhandspromptopt,
		cust.inventoryselectopt,
		cust.invencontaineropt,
		cust.queuedreportoption,
		cust.surveykey,
		cust.contactname,
		cust.customertype,
		cust.callfrequency,
		cust.routenumber,
		cust.arbcustomernameshort,
		cust.arbcustomername,
		cust.arbcustomeraddress1,
		cust.arbcustomeraddress2,
		cust.hhccustomernameshort,
		cust.hhccustomername,
		cust.hhccustomeraddress1,
		cust.hhccustomeraddress2,
		cust.allowbeyondlimit,
		cust.tclimit,
		cust.activecustomer,
		cust.creditlimitdays,
		cust.created,
		cust.cdat,
