		cust.enableupcprint,
		cust.enabledelayprint,
		cust.printsequence,
		cust.enablepriceeditinvs,
		cust.enablesellprevious,
		cust.enablesuggestsales,
		cust.enableautofillreturns,
		cust.enableautofilldamaged,
		cust.enablesigcapture,
