		cust.arbcustomeraddress3,
		cust.templateindicator,
		cust.arbcontactname,
		cust.printlanguageflag,
		cust.quantumno,
		cust.lostplacementdelivs,
		cust.newplacementdelivs,
		cust.currencycode,
		cust.histmaxdeliveries,
		cust.arcustomertype,
		cust.custtaxkey1,
		cust.custtaxkey2,
		cust.custtaxkey3,
		cust.customertaxid,
		cust.customertaxidoptions,
		cust.outletsubtype,
		cust.volume,
		cust.enablegovtaxnote,
		cust.forwardcoverfactor,
		cust.enablepromoeditinvs,
		cust.enableaddlpromoinvs,
		cust.badcreditcustomer,
		cust.enableduplicateprinting,
		cust.numoutstandinginv,
		cust.enablefocprinting,
		cust.promooptions,
		cust.groupcode,
		cust.forceposcheck,
		cust.ancustomercode,
		cust.printoutletitemcode,
		cust.reportprintcontrol,
		cust.invoicelimiter,
		cust.exclusiveopmode,
		cust.returnpromotionkey,
		cust.invoiceformat,
		cust.liquorlicprint,
		cust.enablepromoeditords,
		cust.enableaddlpromoords,
		cust.enableaddlpromoinvoices,
		cust.enableposequipment,
		cust.enablesalestrxn,
		cust.printcheckdetails,
		cust.tcspecialdiscount,
		cust.spldiscountdays,
		cust.arabiccustomercity,
		cust.threshholdlimit,
		cust.discountkey,
		cust.enforcepromotion,
		cust.gpcustcode,
		cust.cashonlypromo,
		cust.roundnetamount,
		cust.partialcollection,
		cust.transactiontype,
		cust.enabledraftcopy,
		cust.enablebuybackfree,
		cust.enablecpd,
		cust.enablepaymentsel,
