		cust.fixedlatitude,
		cust.fixedlongitude,
		cust.rentkey,
		cust.startdate,
		cust.enddate,
		cust.definitionvalue,
		cust.runningvalue,
		cust.rentcontrol,
		cust.disablebalanceupdate,
		cust.enablecreditlimit,
		cust.autosettlecollection,
		cust.enableinvoicecopy,
		cust.pobox,
		cust.shoptelephonenumber,
		cust.shopfaxnumber,
		cust.ownername,
		cust.ownerlandlinenumber,
		cust.ownermobilenumber,
		cust.contactpersonlandlinenumber,
		cust.contactpersonmobilenumber,
		cust.contactpersonemail,
		cust.purchasemanagername,
		cust.purchasemanagerlandlinenumber,
		cust.purchasemanagermobilenumber,
		cust.purchasemanageremail,
		cust.warehousemanagername,
		cust.warehousemanagerlandlinenumber,
		cust.warehousemanagermobilenumber,
		cust.warehousemanageremail,
		cust.expirylimit,
		cust.exprunningvalue,
		cust.distributionkey,
		cust.gpssavecount,
		cust.graceperiod,
		cust.reportcustcode from customermaster AS cust Where cust.routecode = RouteId;
	-- Query for salesman which are related to salesman code
	SELECT  sman.salesmancode,
		sman.salesmanname1,
		sman.salesmanname2,
		sman.arbsalesmanname1,
		sman.messagekey,
		sman.pricingkey,
		sman.created,
		sman.cdat,
		sman.modified,
		sman.mdat,
		sman.memo1,
		sman.memo2,
		sman.alternatesalesmancode,
		sman.type,
		sman.activestatus,
		sman.parentcompany,
		sman.ansalesmancode,
		sman.username,
		sman.userpassword FROM salesman AS sman WHERE sman.salesmancode = SalesmanId;
	-- Query for route master data by route code
	select  route.routecode,
		route.routename,
		route.arbroutename,
		route.subareacode,
		route.salesmancode,
		route.created,
		route.cdat,
		route.modified,
		route.mdat,
		route.memo1,
		route.memo2,
		route.hhcordseq,
		route.hhcinvseq,
		route.hhccshseq,
		route.hhcivtseq,
		route.bodocseq,
