/* Procedure structure for procedure `sp_ws_getregionmaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getregionmaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getregionmaster`(
	IN rwcnt INT,			-- for getting total records
	IN srchvalue VARCHAR(500), 	-- for searching keywords
	IN order_by VARCHAR(500),	-- for order by
	IN order_type VARCHAR(10),	-- for order type
	IN lmt_strt INT,		-- for limit start
	IN lmt_end INT 			-- for limit end
)
BEGIN
	IF lmt_strt = '' THEN
		SET lmt_strt=0;
	END IF;
	IF lmt_end = '' THEN
		SET lmt_end=10;
	END IF;
	if order_by = '' THEN
		SET order_by = 'RegionMstCode';
	END IF;
	IF order_type = '' THEN
		SET order_type= 'DESC';
	END IF;
    IF rwcnt = 1 THEN
	SET @dyn_sql = CONCAT("SELECT COUNT(regionmstcode) AS counter FROM regionmaster AS reg
	LEFT JOIN `country` AS `cnt` ON cnt.countrycode = reg.countrycode
	WHERE (countryname LIKE('%",srchvalue,"%') OR regionmstname LIKE('%",srchvalue,"%'))");
    ELSE
	SET @dyn_sql = CONCAT("SELECT `reg`.`regionmstcode`, `reg`.`regionmstname`, `cnt`.`countryname`
	FROM regionmaster AS reg LEFT JOIN `country` AS `cnt` ON cnt.countrycode = reg.countrycode
	WHERE (countryname LIKE('%",srchvalue,"%') OR regionmstname LIKE('%",srchvalue,"%'))
	ORDER BY ",order_by," ", order_type," LIMIT ",lmt_strt,", ",lmt_end,"");
    END IF;
	PREPARE s1 FROM @dyn_sql;
	-- select @dyn_sql;
	EXECUTE s1;
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_getroute_balance` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_getroute_balance` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_getroute_balance`(
	var_routeid  VARCHAR(15)
    )
BEGIN
	
	UPDATE routemaster rm
		INNER JOIN (SELECT routecode, SUM(invoicebalance) invoicebalance FROM customerinvoice WHERE voidflag=0 GROUP BY routecode) ci ON ci.routecode=rm.routecode
	SET rm.routebalance = ci.invoicebalance
	WHERE rm.routecode = var_routeid;
	
	SELECT COALESCE(SUM(routebalance),0) routebalance from routemaster where routecode = var_routeid;
	
END */$$
DELIMITER ;

