/* Procedure structure for procedure `sp_ws_get_from_customerdistributioncheck` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_from_customerdistributioncheck` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_customerdistributioncheck`(
    IN var_routekey BIGINT(20),	
	IN var_customercode BIGINT(20),
	IN var_visitkey BIGINT(20),
	IN var_itemcode BIGINT(20),	
	IN var_qty FLOAT(18,4),
	IN var_distributionkey BIGINT(20)
	)
BEGIN
 DECLARE cnt INT DEFAULT 0;
 SELECT COUNT(*) INTO cnt FROM customerdistributioncheck WHERE `customercode` = var_customercode AND routekey = var_routekey AND visitkey = var_visitkey AND itemcode= var_itemcode;
IF cnt = 0 THEN	
	INSERT INTO customerdistributioncheck SET routekey = var_routekey,					
					customercode = var_customercode,
					visitkey = var_visitkey,					
					qty = var_qty,
					distributionkey = var_distributionkey,
					itemcode=var_itemcode;
						
			SELECT LAST_INSERT_ID() AS lastid ;
ELSE
UPDATE customerdistributioncheck SET qty = var_qty,distributionkey = var_distributionkey WHERE `customercode` = var_customercode AND routekey = var_routekey AND visitkey = var_visitkey AND itemcode= var_itemcode;
SELECT itemcode FROM customerdistributioncheck WHERE `customercode` = var_customercode AND routekey = var_routekey AND visitkey = var_visitkey AND itemcode= var_itemcode;
END IF; 						
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_get_from_customerinventorycheck` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_from_customerinventorycheck` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_customerinventorycheck`(
    IN var_routekey BIGINT(20),
	IN var_visitkey BIGINT(20),
	IN var_itemcode BIGINT(20),
	IN var_weighted INT(11),
	IN var_qtyloc1case DECIMAL(18,0),
	IN var_catchweightqtyloc1 DECIMAL(18,0),
	IN var_qtyloc1each INT(11),
	IN var_qtyloc2case DECIMAL(18,0),
	IN var_catchweightqtyloc2 DECIMAL(18,0),
	IN var_qtyloc2each INT(11),
	IN var_qtyloc3case DECIMAL(18,0),
	IN var_catchweightqtyloc3 DECIMAL(18,0),
	IN var_qtyloc3each INT(11),
	IN var_shelfstockcase DECIMAL(18,0),
	IN var_shelfstockcatchweightqty DECIMAL(18,0),
	IN var_shelfstockeach DECIMAL(18,0),
	IN var_oldestcode DECIMAL(18,0),
	IN var_expiry_date DATETIME)
BEGIN
 
	DECLARE cnt INT DEFAULT 0;
	SELECT COUNT(*) INTO cnt FROM customerinventorycheck 
		WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `itemcode` =var_itemcode AND 
			expiry_date = var_expiry_date;
 	
 	IF cnt = 0 THEN	
		INSERT INTO customerinventorycheck 
		SET routekey = var_routekey,
		visitkey = var_visitkey,
		itemcode = var_itemcode,
		weighted = var_weighted,
		qtyloc1case = var_qtyloc1case,
		catchweightqtyloc1 = var_catchweightqtyloc1,
		qtyloc1each = var_qtyloc1each,
		qtyloc2case = var_qtyloc2case,
		catchweightqtyloc2 = var_catchweightqtyloc2,
		qtyloc2each = var_qtyloc2each,
		qtyloc3case = var_qtyloc3case,
		catchweightqtyloc3 = var_catchweightqtyloc3,
		qtyloc3each = var_qtyloc3each,
		shelfstockcase = var_shelfstockcase,
		shelfstockcatchweightqty = var_shelfstockcatchweightqty,
		shelfstockeach = var_shelfstockeach,
		oldestcode = var_oldestcode,
		expiry_date = var_expiry_date;
	END IF;
	
	SELECT var_routekey AS lastid ;
	-- SELECT var_expiry_date;			
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_get_from_customerinventorydetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_from_customerinventorydetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_customerinventorydetail`(
    IN var_routekey BIGINT(20),
	IN var_visitkey BIGINT(20),
	IN var_itemcode BIGINT(20),
