DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_customermaster`(IN var_customercode BIGINT(20),
IN var_type INT(4),
IN var_headofficecode BIGINT(20),
