/* Procedure structure for procedure `sp_ws_get_from_nosalesheader` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_from_nosalesheader` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_nosalesheader`(
        IN var_transactionkey bigint(20),
	IN var_routekey decimal(28,0),
	IN var_visitkey decimal(28,0),
	IN var_documentnumber decimal(28,0),
	IN var_invoicenumber decimal(28,0),
	IN var_routecode decimal(18,0),
	IN var_salesmancode decimal(18,0),
	IN var_transactiondate datetime,
	IN var_transactiontime varchar(10),
	IN var_nosalereasoncode int(11),
	IN var_voidflag int(11),
	IN var_transmitindicator int(11),
	IN var_customercode decimal(18,0),
	IN var_hhcdocumentnumber decimal(28,0),
	IN var_hhcinvoicenumber decimal(28,0),
	IN var_data int(11))
BEGIN
    
    INSERT INTO nosalesheader SET 
			routekey = var_routekey,
			visitkey = var_visitkey,
			documentnumber = var_documentnumber,
			invoicenumber = var_invoicenumber,
			routecode = var_routecode,
			salesmancode = var_salesmancode,
			transactiondate = var_transactiondate,
			transactiontime = var_transactiontime,
			nosalereasoncode = var_nosalereasoncode,
			voidflag = var_voidflag,
			transmitindicator = var_transmitindicator,
			customercode = var_customercode,
			hhcdocumentnumber = var_hhcdocumentnumber,
			hhcinvoicenumber = var_hhcinvoicenumber,
			data = var_data;
			
			SELECT LAST_INSERT_ID() AS lastid ; 
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_get_from_rotuegoal` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_from_rotuegoal` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_rotuegoal`(
        IN var_primary_key bigint(28),
        IN var_routecode bigint(18),
        IN var_salesmancode bigint(18),
	IN var_packagenumber bigint(18),
	IN var_todaysgoal decimal(18,0),
	IN var_todaysachieve decimal(18,0),
	IN var_quotadesckey1 decimal(18,0),
	IN var_quotagoal1 decimal(18,0),
	IN var_quotaachieve1 decimal(18,0),
	IN var_quotareset1 decimal(18,0),
	IN var_quotadesckey2 decimal(18,0),
	IN var_quotagoal2 decimal(18,0),
	IN var_quotaachieve2 decimal(18,0),
	IN var_quotareset2 decimal(18,0),
	IN var_quotadesckey3 decimal(18,0),
	IN var_quotagoal3 decimal(18,0),
	IN var_quotaachieve3 decimal(18,0),
	IN var_quotareset3 decimal(18,0),
	IN var_created varchar(50),
	IN var_cdat datetime,
	IN var_modified varchar(50),
	IN var_mdat datetime,
	IN var_mmonth decimal(18,0),
	IN var_yyear int(11),
	in var_fromdate date,
	in var_todate date,
	in var_quantity int,
	in var_achievequantity int
	)
BEGIN
	
	INSERT INTO routegoal SET 
			routecode = var_routecode,
			salesmancode = var_salesmancode,
			packagenumber = var_packagenumber,
			todaysgoal = var_todaysgoal,
			todaysachieve = var_todaysachieve,
			quotadesckey1 = var_quotadesckey1,
			quotagoal1 = var_quotagoal1,
			quotaachieve1 = var_quotaachieve1,
			quotareset1 = var_quotareset1,
			quotadesckey2 = var_quotadesckey2,
			quotagoal2 = var_quotagoal2,
			quotaachieve2 = var_quotaachieve2,
			quotareset2 = var_quotareset2,
			quotadesckey3 = var_quotadesckey3,
			quotagoal3 = var_quotagoal3,
			quotaachieve3 = var_quotaachieve3,
			quotareset3 = var_quotareset3,
			created = var_created,
			cdat = var_cdat,
			modified = var_modified,
			mdat = var_mdat,
			mmonth = var_mmonth,
			fromdate = var_fromdate,
			todate = var_todate,
			quantity = var_quantity,
			achievequantity = var_achievequantity;
			
			
	SELECT LAST_INSERT_ID() AS lastid ; 	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_get_from_routesequencecustomerstatus` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_from_routesequencecustomerstatus` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_from_routesequencecustomerstatus`(
    IN var_routekey DECIMAL(28,0),
    IN var_seqweeknumber INT(11),
    IN var_seqweekday INT(11),
    IN var_routecode DECIMAL(18,0),
    IN var_customercode DECIMAL(18,0),
    IN var_sequencenumber INT(11),
    IN var_schelduledflag INT(11),
    IN var_servicedflag INT(11),
    IN var_scannedflag INT(11))
BEGIN
 
	INSERT INTO routesequencecustomerstatus SET 
		routekey = var_routekey,
		seqweeknumber = var_seqweeknumber,
		seqweekday = var_seqweekday,
		routecode = var_routecode,
		customercode = var_customercode,
		sequencenumber = var_sequencenumber,
		schelduledflag = var_schelduledflag,
		servicedflag = var_servicedflag,
		scannedflag = var_scannedflag;
						
	SELECT routekey AS lastid 
	from routesequencecustomerstatus where routekey = var_routekey and customercode = var_customercode; 		
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_get_tablet_startingloaddetail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_get_tablet_startingloaddetail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_get_tablet_startingloaddetail`(
    IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT)
BEGIN
    DECLARE var_syncdate DATETIME;
     DECLARE var_where1 VARCHAR(250);
     IF var_checkmdate = 1 THEN
	-- Statement for get syncdate by using userid and deviceid variables
	SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
	   IF var_syncdate != '' THEN
		-- check syncdate for all table which you need for sync
		SET var_where1 = CONCAT(" AND voidreasons.mdat > '",var_syncdate,"' ");
	   END IF;
	END IF;
    SET @dyn_sql1 = CONCAT("SELECT  
		sd.itemcode,
		sd.routecode,
		sd.ddate,
		sd.caseprice,
		sd.loadperiodnumber,
		sd.cases,
		sd.units,
		sd.totunits,
		sd.suggtotunits,
		sd.rcvdtotunits,
		sd.upc,
		sd.loadtime,
		sd.salesmancode,
		sd.salesprice,
		sd.returnprice,
		sd.status,
		sd.transactiondate,
		sd.erpreferencenumber,
		sd.currencycode,
		sd.batchnumber,
		sd.expirydate,
		sd.warehouse,
		sd.warehousestock,
		sd.mdat
		FROM startingloaddetail AS sd
		WHERE 1=1 AND sd.routecode = ",var_routeid," and DATE(sd.ddate)=DATE(CURRENT_DATE()) AND sd.salesmancode = ",var_userid," ",var_where1);
		PREPARE s1 FROM @dyn_sql1;
		EXECUTE s1;
		
		SET @dyn_sql2 = CONCAT("UPDATE startingloaddetail SET `status` = 0 
		WHERE routecode = ",var_routeid," and DATE(ddate)= CURRENT_DATE() AND salesmancode = ",var_userid);
		PREPARE s2 FROM @dyn_sql2;
		EXECUTE s2;
		
		show WARNINGS;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_importinventory_counts` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_importinventory_counts` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_importinventory_counts`(
	IN var_routeid VARCHAR(255)
    )
BEGIN
		SELECT COALESCE(MAX(routekey),0) INTO @routekey FROM startendday WHERE routeclosed = 1 AND routecode = var_routeid;
		
		 SET @dyn_sql2 = CONCAT(" SELECT 'SLD' as TTYPE, ifnull(sum(totunits),0) as CloudCount
		 FROM startingloaddetail
		 WHERE routecode = ",var_routeid," and status=0  AND ddate = CURDATE() AND totunits > 0 
		 union 
		 SELECT 'ISD' AS TTYPE,ifnull(sum(quantity),0) CloudCount FROM inventorytransactiondetail 
		 WHERE transactiontypecode = 5 AND quantity > 0 AND routekey=",@routekey, "
		 union
		 SELECT 'PKH' as TTYPE, COUNT(*) as CloudCount
		 FROM promokeyheader 
		 WHERE promotionkey IN (SELECT  DISTINCT promotionkey FROM customermaster JOIN routesequence ON customermaster.customercode=routesequence.customercode AND routesequence.routecode = ",var_routeid," AND customermaster.promotionkey>0 )
		 union 
		 SELECT 'PKD' as TTYPE, COUNT(*) as CloudCount
		 FROM promokeydetail
		 pkd WHERE pkd.promotionkey IN (SELECT promotionkey FROM promokeyheader pkh WHERE pkh.promotionkey 
                 IN (SELECT  DISTINCT promotionkey FROM customermaster JOIN routesequence ON customermaster.customercode=routesequence.customercode AND routesequence.routecode = ",var_routeid," AND customermaster.promotionkey>0)) AND pkd.enddate>= CURRENT_DATE()
		 union
		 SELECT 'PPH' as TTYPE, COUNT(*) as CloudCount
		 FROM promoplanheader pph WHERE pph.plannumber IN (SELECT plannumber FROM promokeydetail pkd WHERE pkd.promotionkey 
                 IN (SELECT promotionkey FROM promokeyheader pkh WHERE pkh.promotionkey 
                 IN (SELECT  DISTINCT promotionkey FROM customermaster JOIN routesequence ON customermaster.customercode=routesequence.customercode AND routesequence.routecode = ",var_routeid," AND customermaster.promotionkey>0)) AND pkd.enddate>= CURRENT_DATE())	
		 union
		 SELECT 'PPD' as TTYPE, COUNT(*) as CloudCount
		 FROM promoplandetail ppd WHERE ppd.plannumber IN (SELECT pph.plannumber FROM promoplanheader pph WHERE pph.plannumber 
                 IN (SELECT plannumber FROM promokeydetail pkd WHERE pkd.promotionkey 
                 IN (SELECT promotionkey FROM promokeyheader pkh WHERE pkh.promotionkey 
                 IN (SELECT  DISTINCT promotionkey FROM customermaster JOIN routesequence ON customermaster.customercode=routesequence.customercode AND routesequence.routecode = ",var_routeid," AND customermaster.promotionkey>0)) AND pkd.enddate>= CURRENT_DATE()))
                 union
                 SELECT 'PAA' as TTYPE, COUNT(*) as CloudCount
                 FROM promotionassignmentadvanced paa WHERE paa.assignmentnumber IN (SELECT assignmentnumber FROM promoplandetail
                 ppd  WHERE  ppd.plannumber IN (SELECT pph.plannumber FROM promoplanheader pph WHERE pph.plannumber 
                 IN (SELECT plannumber FROM promokeydetail pkd WHERE pkd.promotionkey 
                 IN (SELECT promotionkey FROM promokeyheader pkh WHERE pkh.promotionkey 
                 IN (SELECT  DISTINCT promotionkey FROM customermaster JOIN routesequence ON customermaster.customercode=routesequence.customercode AND routesequence.routecode = ",var_routeid," AND customermaster.promotionkey>0)) AND pkd.enddate>= CURRENT_DATE())) )
                 union
                
                  SELECT 'CP' AS TTYPE, COUNT(*) AS CloudCount
		FROM customerpricingplanheader1 cpph 
		INNER JOIN customerpricing1 cp ON cpph.pricingplankey = cp.pricingplankey AND cp.enddate >= CURRENT_DATE()
		INNER JOIN pricingplanheader1 pph ON cp.customerpricingkey = pph.customerpricingkey	
		WHERE cpph.pricingplankey IN (SELECT DISTINCT(cm.pricingkey) keyval 
		FROM customermaster cm INNER JOIN routesequence rs ON cm.customercode = rs.customercode AND rs.routecode = ",var_routeid,") 
		union
		
		SELECT 'RS' AS TTYPE, COUNT(*) AS CloudCount FROM customermaster cm 
		INNER JOIN routesequence rs ON rs.customercode = cm.customercode WHERE  rs.routecode = ",var_routeid,"
		 ");
		 PREPARE s2 FROM @dyn_sql2;
		 EXECUTE s2;
		
		
		
		
		
	
		 
	
	
	
    END */$$
DELIMITER ;

