/* Procedure structure for procedure `sp_ws_instertion_tbl_synclog` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_instertion_tbl_synclog` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_instertion_tbl_synclog`(
	IN var_userid INT,	
	IN var_routecode INT,
        IN var_routekey INT,
        IN var_routeclosed enum('0','1'),        
        IN var_synctype INT       
)
BEGIN
	IF var_userid != 0 AND var_routekey != 0 Then 
		
		SELECT routecode INTO @route from routemaster WHERE salesmancode = var_userid;
		SELECT COALESCE(MAX(routekey),0) INTO @routekey FROM startendday WHERE routeclosed = 0 and routecode = @route;
		
		INSERT INTO synclog(userid,syncdate,routecode,synctime,synctype,routeclosed,routekey)
			VALUES(var_userid, CURDATE(), @route, CURTIME(), var_synctype, var_routeclosed, @routekey);
   
	END IF;
	
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_inv_header` */

