/* Procedure structure for procedure `sp_ws_itemlistbyroute` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_itemlistbyroute` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_itemlistbyroute`(
	IN RouteCode INT,
	IN SalesmanCode INT
    )
BEGIN
	SELECT im.itemshortdescription, im.unitspercase,im.case1,im.case2,im.actualitemcode FROM itemmaster AS im
	INNER JOIN inventorytransactiondetail AS itd ON itd.RouteKey = RouteCode AND itd.transactiontypecode = 1 AND itd.itemcode = im.actualitemcode;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_populate_loadrequest` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_populate_loadrequest` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_populate_loadrequest`(
	IN RouteCode INT
    )
BEGIN
	SELECT itemcode,quantity,routecode,salesmancode,loadperiodnumber,loaddate,ddate
	FROM loadrequest 
	WHERE routecode = RouteCode AND ddate = current_date();
    END */$$
