	DECLARE var_where28 VARCHAR(250);
	DECLARE var_where29 VARCHAR(250);
	
	SET var_where1 = "";
	SET var_where2 = "";
	SET var_where3 = "";
	SET var_where4 = "";
	SET var_where5 = "";
	SET var_where6 = "";
	SET var_where7 = "";
	SET var_where8 = "";
	SET var_where9 = "";
	
	SET var_where11 = "";
