	SET var_where14 = "";
	SET var_where15 = "";
	SET var_where16 = "";
	SET var_where17 = "";
	SET var_where18 = "";
	SET var_where19 = "";
	SET var_where20 = "";
	SET var_where21 = "";
	SET var_where22 = "";
	SET var_where23 = "";
	SET var_where24 = "";
	SET var_where25 = "";
	SET var_where26 = "";
	SET var_where27 = "";
	SET var_where28 = "";
	SET var_where29 = "";
		
	IF var_checkmdate = 1 THEN
		-- Statement for get syncdate by using userid and deviceid variables
		SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid;
		   IF var_syncdate != '' THEN
			-- check syncdate for all table which you need for sync
			SET var_where1 = CONCAT(" AND item.mdat > '",var_syncdate,"' ");
			SET var_where2 = CONCAT(" AND cust.mdat > '",var_syncdate,"' ");
			SET var_where3 = CONCAT(" AND cust.mdat > '",var_syncdate,"' ");
			SET var_where4 = CONCAT(" AND sman.mdat > '",var_syncdate,"' ");
