						mdat
						FROM expreasons WHERE 1=1 ",var_where7);
		PREPARE s7 FROM @dyn_sql7;
		EXECUTE s7;
		
		#FROM expiryreturnreasons
		SET @dyn_sql8 = CONCAT("SELECT code,
						alternatecode,
						description,
						arbdescription,
						hhcdescription,
						created,
						cdat,
						modified,
						mdat
						FROM expiryreturnreasons WHERE 1=1 ",var_where8);
		PREPARE s8 FROM @dyn_sql8;
		EXECUTE s8;
	
		#FROM retitmreasons
		SET @dyn_sql9 = CONCAT("SELECT code,
						alternatecode,
						description,
						arbdescription,
						hhcdescription,
						created,
						cdat,
						modified,
						mdat
						FROM retitmreasons WHERE 1=1 ",var_where9);
		PREPARE s9 FROM @dyn_sql9;
		EXECUTE s9;
	
		#FROM freegoodreasons
		SET @dyn_sql10 = CONCAT("SELECT reason_code,
						alternatereasoncode,
						reason_desc,
						reason_arb_desc,
						created,
						cdat,
						modified,
						mdat
						FROM freegoodreasons WHERE 1=1 ",var_where10);
		PREPARE s10 FROM @dyn_sql10;
		EXECUTE s10;
		
		#FROM voidreasons
		SET @dyn_sql11 = CONCAT("SELECT code,
						alternatecode,
						description,
						arbdescription,
						hhcdescription,
						created,
						cdat,
						modified,
						mdat
						FROM voidreasons WHERE 1=1 ",var_where11);
		PREPARE s11 FROM @dyn_sql11;
		EXECUTE s11;
	       	
		#FROM nonservreasons
		#SET @dyn_sql12 = CONCAT("SELECT code,
		#				alternatecode,
		#				description,
		#				arbdescription,
		#				hhcdescription,
		#				created,
		#				cdat,
		#				modified,
		#				mdat
		#			FROM nonservreasons WHERE 1=1 ",var_where12);
		#PREPARE s12 FROM @dyn_sql12;
		#EXECUTE s12;
		
		#FROM salsmanmessage
		SET @dyn_sql13 = CONCAT("SELECT messagekey,
						alternatecode,
						messagedescription,
						message1,
						message2,
						message3,
						message4,
						arbmessageline1,
						arbmessageline2,
						arbmessageline3,
						arbmessageline4,
						created,
						cdat,
						modified,
						mdat,activestatus
						FROM salesmanmessages WHERE 1=1 ",var_where13);
		PREPARE s13 FROM @dyn_sql13;
		EXECUTE s13;
		#FROM vanmaster
		SET @dyn_sql14 = CONCAT("SELECT vancode,
						alternatecode,
						vandescription,
						arbvandescription,
						activestatus,
						vanregno,
						vanmodel,
						vantype,
						created,
						cdat,
						modified,
						mdat
						FROM vanmaster WHERE 1=1 ",var_where14);
		PREPARE s14 FROM @dyn_sql14;
		EXECUTE s14;
		
		#FROM routegoal
		SET @dyn_sql4 = CONCAT("SELECT * FROM routegoal WHERE targettype =0");
		PREPARE s4 FROM @dyn_sql4;
		EXECUTE s4;
		
		#FROM itempackagemaster
		SET @dyn_sql16 = CONCAT("SELECT packagecode,
						alternatecode,
						packagedescription,
						arbpackagedescription,
						created,
						cdat,
						modified,
						mdat,
						activestatus
						FROM itempackagemaster WHERE 1=1 ",var_where16);
		PREPARE s16 FROM @dyn_sql16;
		EXECUTE s16;
		 #FROM POSmaster
		SET @dyn_sql17 = CONCAT("SELECT itemcode ,alternatecode, itemdescription , arbitemdescription , itemvalue , inventorytype , created , cdat , modified , mdat , activestatus FROM posmaster WHERE 1=1 ",var_where17);
		PREPARE s17 FROM @dyn_sql17;
		EXECUTE s17;
		#FROM CustomerPOSinventory
		SET @dyn_sql18 = CONCAT("SELECT customercode,
						itemcode,
						quantity,
						serialnumber
						FROM customerposinventory WHERE 1=1 ");
		PREPARE s18 FROM @dyn_sql18;
		EXECUTE s18;
	
		#FROM CustomerPOSinventory
		SET @dyn_sql19 = CONCAT("SELECT customercode,
						poslimit,
						posbalance
						FROM customerposlimit WHERE 1=1");
		PREPARE s19 FROM @dyn_sql19;
		EXECUTE s19;
	
			
		#FROM posinstructions
		SET @dyn_sql20 = CONCAT("SELECT posinstructioncode,
						posinstructionname,
						arbposinstructionname,
						created,
						cdat,
						modified,
						mdat
						FROM posinstructions WHERE 1=1 ",var_where20);
		PREPARE s20 FROM @dyn_sql20;
		EXECUTE s20;
		#FROM customersurveyplan
		SET @dyn_sql21 = CONCAT("SELECT surveyplankey,
						surveysequencenumber,
						surveymandatory,
						surveydescription,
						arbsurveydescription
						FROM customersurveyplan WHERE 1=1 ",var_where21);
		PREPARE s21 FROM @dyn_sql21;
		EXECUTE s21;
		
		#FROM customersurveykeyplan
		SET @dyn_sql22 = CONCAT("SELECT primary_key,
						surveyplankey,
						surveykey
						FROM customersurveykeyplan WHERE 1=1 ",var_where22);
		PREPARE s22 FROM @dyn_sql22;
		EXECUTE s22;
		
		#FROM customersurveykey
		SET @dyn_sql23 = CONCAT("SELECT surveykey,
						surveydescription,
						arbsurveydescription,
						surveyplankey,
						created,
						cdat,
						modified,
						mdat,
						activestatus
						FROM customersurveykey WHERE 1=1 ",var_where23);
		PREPARE s23 FROM @dyn_sql23;
		EXECUTE s23;
		
		#FROM customersurveydefinition
		SET @dyn_sql24 = CONCAT("SELECT surveydefkey,
						surveyindex,
						lineindex,
						surveyrectype,
						surveyprompt,
						arbsurveyprompt,
						responselength,
						responsedecimalpos,
						lookuptype,
						lookupindex,
						retainvalue,
						activestatus,
						created,
						cdat,
						modified,
						mdat
						FROM customersurveydefinition WHERE 1=1 ",var_where24);
		PREPARE s24 FROM @dyn_sql24;
		EXECUTE s24;
			
		#FROM customersurveydefinition
		SET @dyn_sql25 = CONCAT("SELECT surveyplankey,
						surveydefkey
						FROM customersurveydefassign WHERE 1=1 ",var_where25);
		PREPARE s25 FROM @dyn_sql25;
		EXECUTE s25;	
		
		#FROM lookupindexdetail
		SET @dyn_sql26 = CONCAT("SELECT primary_key,
						transactionkey,
						description,
						arbdescription
						FROM lookupindexdetail WHERE 1=1 ",var_where26);
		PREPARE s26 FROM @dyn_sql26;
		EXECUTE s26;
				
		
		#FROM suggested sales 
		SET @dyn_sql27 = CONCAT("SELECT * FROM suggestedsalesinvoice WHERE 1=1 ",var_where27);
		PREPARE s27 FROM @dyn_sql27;
		EXECUTE s27;
		
		#FROM inventorytranactiondetai 
		SET @dyn_sql28 = CONCAT("SELECT * FROM inventorytransactiondetail WHERE transactiontypecode = '6' AND routekey=(SELECT MAX(routekey) FROM startendday where routecode = ",var_routeid," AND salesmancode = ",var_userid," )");
		PREPARE s28 FROM @dyn_sql28;
		EXECUTE s28;
		
		#FROM customer_foc_balance
		SET @dyn_sql29 = CONCAT("SELECT * FROM customer_foc_balance WHERE 1=1 ");
		PREPARE s29 FROM @dyn_sql29;
		EXECUTE s29;
		
		#FROM customer_foc_detial
		SET @dyn_sql30 = CONCAT("SELECT * FROM customer_foc_detail WHERE 1=1");
		PREPARE s30 FROM @dyn_sql30;
		EXECUTE s30;
		
		#FROM journeyplancreditlimit
		SET @dyn_sql31 = CONCAT("SELECT * FROM journeyplancreditlimit WHERE 1=1 ");
		PREPARE s31 FROM @dyn_sql31;
		EXECUTE s31;
		
		#FROM salesorderheader
		SET @dyn_sql32 = CONCAT("SELECT * FROM salesorderheader WHERE routecode = ",var_routeid," and orderdeliverydate=",CURRENT_DATE(),"");
		PREPARE s32 FROM @dyn_sql32;
		EXECUTE s32;
		
		#FROM salesorderdetail
		SET @dyn_sql33 = CONCAT("SELECT * FROM salesorderdetail WHERE transactionkey = (SELECT transactionkey FROM salesorderheader WHERE routecode = ",var_routeid," and orderdeliverydate=",CURRENT_DATE(),")");
		PREPARE s33 FROM @dyn_sql33;
		EXECUTE s33;
		
		#FROM batchexpirydetail
		SET @dyn_sql34 = CONCAT("SELECT * FROM batchexpirydetail WHERE routekey = (SELECT MAX(routekey) FROM startendday where routecode = ",var_routeid," AND salesmancode = ",var_userid,")");
		PREPARE s34 FROM @dyn_sql34;
		EXECUTE s34;
				
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_setting` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_setting` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_setting`(
	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
)
BEGIN
	-- Declare variable for get syncdate
	DECLARE var_syncdate DATETIME;
	DECLARE rcnt INT;	
	DECLARE var_depots INT;	
	DECLARE var_transfer INT;	
	DECLARE var_condition VARCHAR(250);
	
	SET @routekey = 0; SET @routegroup = 0;
	SELECT COALESCE(MAX(routekey), 0) INTO @routekey FROM startendday WHERE routeclosed = 1 AND routecode = var_routeid;
	SELECT COALESCE(routeitemgrpcode, 0) INTO @routegroup FROM routemaster WHERE routecode = var_routeid;
	
	-- Creqating a temporary opening stock table; this is to reduce the load for the web service
	SET @tableopenstk = CONCAT("temp_openstock_",var_routeid);
	SET @tabletmp1 = CONCAT("DROP TABLE IF EXISTS ",@tableopenstk);
	PREPARE qry1 FROM @tabletmp1 ;
	EXECUTE qry1;
	
	SET @tabletmp1 =  CONCAT("CREATE TABLE IF NOT EXISTS ", @tableopenstk, " AS SELECT * FROM inventorytransactiondetail WHERE transactiontypecode = 5 AND quantity > 0 AND routekey= ", @routekey);
	PREPARE qry2 FROM @tabletmp1;
	EXECUTE qry2;
	-- -----------------------------------------------------------------------------------------------------------------
	
	-- Checking if any item having closing stock is removed from route itemgroup. if so then it will add that item back.	
	SET @tabletmp1 =  CONCAT("INSERT INTO routeitemmapping
		SELECT ", @routegroup, "  routeitemgrpcode, itd.itemcode, 0
		FROM ", @tableopenstk, " itd
			LEFT OUTER JOIN routeitemmapping rim ON rim.itemcode = itd.itemcode AND rim.routeitemgrpcode = ", @routegroup," 
		WHERE itd.transactiontypecode = 5 AND itd.routekey = ", @routekey, " AND rim.itemcode IS NULL");
	PREPARE qry3 FROM @tabletmp1;
	EXECUTE qry3;
	-- ----------------------------------------------------------------------------------------------------------
	
	-- Checking if any item having load is removed from route itemgroup. if so then it will add that item back.	
	SET @tabletmp1 =  CONCAT("INSERT INTO routeitemmapping
		SELECT DISTINCT ", @routegroup, "  routeitemgrpcode, itd.itemcode, 0
		FROM startingloaddetail itd
			LEFT OUTER JOIN routeitemmapping rim ON rim.itemcode = itd.itemcode AND rim.routeitemgrpcode = ", @routegroup," 
		WHERE itd.status = 0 AND itd.warehouse=1 AND itd.ddate = curdate() AND itd.routecode = ", var_routeid," AND rim.itemcode IS NULL");
	PREPARE qry3 FROM @tabletmp1;
	EXECUTE qry3;
	-- ----------------------------------------------------------------------------------------------------------
	
	-- updating inventoryreportcontrol with closing stock qty to heck in the device.
	SET @tabletmp1 =  CONCAT("UPDATE routemaster SET inventoryreportcontrol = COALESCE((SELECT SUM(quantity) FROM ", @tableopenstk, "), 0) WHERE routecode = ", var_routeid);
	PREPARE qry4 FROM @tabletmp1;
	EXECUTE qry4;
	-- ----------------------------------------------------------------------------------------------------------
	
	-- updating enablestockicon with load qty to heck in the device.
	SET @tabletmp1 =  CONCAT("UPDATE routemaster SET enablestockicon = (SELECT COALESCE(SUM(sld.totunits),0) FROM startingloaddetail sld WHERE sld.status = 0 AND sld.warehouse=1 AND sld.ddate = curdate() AND sld.routecode = ", var_routeid,") WHERE routecode = ", var_routeid);
	PREPARE qry4 FROM @tabletmp1;
	EXECUTE qry4;
	-- ----------------------------------------------------------------------------------------------------------
	
	
	SET @dyn_sql8 = CONCAT("SELECT  controlpanel.flagid, controlpanel.formid, controlpanel.flagname, controlpanel.status, 0 as flagvalue FROM controlpanel ORDER BY flagid");		
	PREPARE s8 FROM @dyn_sql8;
	EXECUTE s8;
	
	SET @dyn_sql9 = CONCAT("SELECT * FROM setup");		
	PREPARE s9 FROM @dyn_sql9;
	EXECUTE s9;
	
	SET @dyn_sql7 = CONCAT("SELECT * FROM company ORDER BY 1 LIMIT 1");
	PREPARE s7 FROM @dyn_sql7;
	EXECUTE s7;
	-- sm.created, sm.cdat, sm.modified, sm.mdat,
	SET @dyn_sql4 = CONCAT("SELECT 
		sm.salesmancode, sm.salesmanname1, sm.salesmanname2, '' arbsalesmanname1, sm.messagekey, sm.pricingkey,
		sup.supervisorname AS memo1, sup.contactno AS memo2, '' alternatesalesmancode, sm.type, 
		sm.activestatus, sm.parentcompany, sm.ansalesmancode, sm.username, sm.userpassword 
	FROM routemaster rm
		INNER JOIN salesman sm ON sm.salesmancode = rm.salesmancode
		INNER JOIN subareamaster sam ON sam.subareacode = rm.subareacode
		INNER JOIN supervisor sup ON sup.supervisorcode = sam.supervisorcode
	WHERE routecode =  ",var_routeid);
	PREPARE s4 FROM @dyn_sql4;
	EXECUTE s4;
		
	SELECT am.depotcode INTO var_depots FROM areamaster am 
		INNER JOIN subareamaster sam ON am.areacode = sam.areacode INNER JOIN routemaster rm ON sam.subareacode = rm.subareacode  WHERE rm.routecode = var_routeid;	
	-- SELECT COUNT(routekey) INTO rcnt from startendday where routecode= var_routeid and routeclosed=0; 
	
	SELECT transferinventoryflag INTO var_transfer FROM setup;
	
	SET @temproutetable = "DROP TABLE IF EXISTS temp_route"; 
	PREPARE qry3 FROM @temproutetable;
	EXECUTE qry3;
	
	IF  var_transfer = '0' THEN
		SET var_condition = CONCAT(" AND rm.routecode = ",var_routeid, " ");
	ELSEIF  var_transfer = '1' THEN
		SET var_condition = CONCAT(" AND rm.depotrouteflag = ","0 ");
	ELSEIF  var_transfer = '2' THEN
		SET var_condition = CONCAT(" AND rm.depotrouteflag = ","1 ");
	ELSE
		SET var_condition = CONCAT(" AND rm.depotrouteflag < ", "2 ");
	END IF;
	
	SET @temproutetable =  CONCAT("CREATE TEMPORARY TABLE IF NOT EXISTS temp_route AS 
			SELECT DISTINCT rm.routecode routecode FROM areamaster am 
				INNER JOIN subareamaster sam ON am.areacode = sam.areacode INNER JOIN routemaster rm ON sam.subareacode = rm.subareacode
			WHERE rm.activestatus = 1 AND am.depotcode = ", var_depots, var_condition);
	PREPARE qry4 FROM @temproutetable;
	EXECUTE qry4;
	
	IF  var_transfer = '2' THEN
		SET @temproutetable =  CONCAT("INSERT INTO temp_route (routecode) VALUES (",var_routeid,")");
		PREPARE qry4 FROM @temproutetable;
		EXECUTE qry4;
	END IF;
	
	-- IF rcnt = '0' THEN
	--	CALL sp_update_sequence_numbers(var_routeid);	  
	-- END IF;
	-- sujee temp comment uncomment after live 
	   CALL sp_update_sequence_numbers(var_routeid);	
	-- for populate load request table	
	 CALL sp_cron_populate_loadrequest_routes(var_routeid); 
	-- route.created, route.cdat, route.modified, route.mdat,
	SET @dyn_sql5 = CONCAT("SELECT  route.routecode, 
			route.routename, 
			route.arbroutename, 
			route.subareacode, 
			route.salesmancode, 			
			route.memo1, 
			route.memo2, 
			route.hhcordseq, 
			route.hhcinvseq, 
			route.hhccshseq, 
			route.hhcivtseq, 
			route.bodocseq, 
			route.boinvseq, 
			route.vehiclenumber, 
			route.vehicleodometer, 
			route.enablescanneruse, 
			route.password1, 
			route.password2, 
			route.password3, 
			route.password4, 
			route.password5, 
			route.passwordarray01, 
			route.passwordarray02, 
			route.passwordarray03, 
			route.passwordarray04, 
			route.passwordarray05, 
			route.passwordarray06, 
			route.passwordarray07, 
			route.passwordarray08, 
			route.passwordarray09, 
			route.passwordarray10, 
			route.passwordarray11, 
			route.passwordarray12, 
			route.passwordarray13, 
			route.passwordarray14, 
			route.passwordarray15, 
			route.passwordarray16, 
			route.enabledelayprint, 
			route.promptodominput, 
			route.enableeodexpenses, 
			route.enableeodadjchecks, 
			route.enableeodaddchecks, 
			route.reqeoddepositreport, 
			route.reqeodsalesreport, 
			route.reqeodrteactivreport, 
			route.reqeodrtestlmtreport, 
			route.reqeodroutereviewrpt, 
			route.reqeodrtnexchreport, 
			route.reqeodplacementsrpt, 
			route.reqeodprcchgreport, 
			route.reqeodpromosreport, 
			route.reqeodnosalereport, 
			route.reqeodnondelreport, 
			route.reqeodexceptionrpt, 
			route.reqeodunauthbalance, 
			route.reqeodroasummary, 
			route.inventorycaseinput, 
			route.loadreqreportformat, 
			route.includeloadrequest, 
			route.loadoutadjustments, 
			route.autocalculateloadin, 
			route.requireloadin, 
			route.loadsheetreport, 
			route.inventoryvariance, 
			route.invenoversell, 
			route.enablenosale, 
			route.enablepostvoid, 
			route.cashbalance, 
			route.amountdecimaldigits as amountdecimaldigits, 
			route.unloadoversellmessage, 
			route.displayinvsummary, 
			route.alternateroutecode, 
			route.enabledamagedtrxn, 
			route.defaultdeliverydays, 
			route.reqeodnonscannedreport, 
			route.reqeododomlogreport, 
			route.inventoryvalueprint, 
			route.loadaccessafterunload, 
			route.routebalance, 
			route.depotrouteflag, 
			route.routeinventoryvariance, 
			route.allowpopulateload, 
			route.enableaddcustomer, 
			route.allowgctocash, 
			route.usesalesdateflag, 
			route.enablestartdaydatetimeedit, 
			route.newcustomerseqnumber, 
			route.enableloadtransfer, 
			route.loadreqmethod, 
			route.loadreqrolluporders, 
			route.routeprinter, 
			route.depotprinter, 
			route.routetype, 
			route.enablescancustomer, 
			route.enforcecallsequence, 
			route.enablefoclimit, 
			route.enablemiddaytelecom, 
			route.printdocumentnumber, 
			route.activestatus, 
			route.enablecashonlydiscount, 
			route.eodreportcontrol, 
			route.pdcthreshold, 
			route.itemcodedisplay, 
			route.routeitemgrpcode, 
			route.itemdescriptiondisplay, 
			route.lastcustomersequence, 
			route.loadsecurityflag, 
			route.routecatcode, 
			route.usealternatecodes, 
			route.enabledraftcopy, 
			route.boarseq, 
			route.boordseq, 
			route.hhcarseq, 
			route.hhcloadseq, 
			route.boloadseq, 
			route.deliveryroute, 
			route.presalesorder, 
			route.hhcappversion, 
			route.usesequenceflag, 
			route.customerseq, 
			route.routeseqno, 
			route.allowbalcheck, 
			route.allowedradius, 
			route.cmpycode, 
			route.regionmstcode, 
			route.expirylimit, 
			route.runningvalue,
			route.transactionnoseq,
			route.enablefreereason,
			route.maximumgpsallowed,
			route.defaultrequestdays,
			route.defaultweeksetting,
			route.voidoverride,
			route.salesmantargetdays,
			route.hhcinvretseq,
			route.hhcswapseq,
			route.enableautopostingaccount,
			route.variancecustomercode,
			route.forcesettlementdays,
			route.routecreditcheck,
			route.creditlimit routecreditlimit, 
			route.routecreditlimitdays,
			route.itemmustkey, 
			route.inventoryreportcontrol,
			route.enablestockicon,
			route.enablegps,
			route.enforcegps,
			route.updategps,
			route.enableloadrequest,
			route.loadrequestdays,
			route.invdoseq
		FROM routemaster AS route LEFT JOIN currencymaster as curr on curr.currencycode = route.amountdecimaldigits
		WHERE route.routecode IN (SELECT routecode FROM temp_route)");
	PREPARE s5 FROM @dyn_sql5;
	EXECUTE s5;
		
	SET @dyn_sql13 = CONCAT(" SELECT
			startendday.routekey,
			startendday.routecode,
			startendday.salesmancode,
			startendday.routestartdate,
			startendday.routestarttime,
			startendday.routeenddate,
			startendday.routeendtime,
			startendday.routestartodometer,
			startendday.routeendodometer,
			startendday.totaldocuments,
			startendday.totalcash,
			startendday.totalchecks,
			startendday.totalcheckrequests,
			startendday.totalorderamount,
			startendday.totalinvoiceamount,
			startendday.totalchargesales,
			startendday.totalcashsales,
			startendday.totalacctsreceivable,
			startendday.totalexpenses,
			startendday.inventoryvariance,
			startendday.totalfullservicesales,
			startendday.totalfullservicecash,
			startendday.routeclosed,
			startendday.cashvariance,
			startendday.modifieddate,
			startendday.modifiedtime,
			startendday.subareacode,
			startendday.supervisorcode,
			startendday.areacode,
			startendday.areamanagercode,
			startendday.depotcode,
			startendday.branchmanagercode,
			startendday.cmpycode,
			startendday.nationalsalesmanagercode,
			startendday.dataconrefnumber,
			startendday.exportedflag,
			startendday.routesequence,
			startendday.currencycode,
			startendday.routejourneyid,
			startendday.data 
		FROM startendday 
		WHERE startendday.routecode = ",var_routeid," AND startendday.routeclosed = 1 ORDER BY 1 DESC LIMIT 0");
	PREPARE s13 FROM @dyn_sql13;
	EXECUTE s13;
    
	SET @dyn_sql10 = CONCAT("SELECT CURRENT_DATE() as synctime");
	PREPARE s10 FROM @dyn_sql10;
	EXECUTE s10;
	
	SELECT * FROM currencymaster WHERE currencycode IN (SELECT amountdecimaldigits FROM routemaster WHERE routecode = var_routeid);
	
	SET @tabletmp1 = CONCAT("DROP TABLE IF EXISTS ",@tableopenstk);
	PREPARE qry1 FROM @tabletmp1 ;
	EXECUTE qry1;
		
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_syncicsdata_survey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_syncicsdata_survey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_syncicsdata_survey`(
    	IN var_userid INT,
	IN var_deviceid VARCHAR(255),
	IN var_routeid INT,
	IN var_checkmdate INT
    )
BEGIN
 -- Declare variable for get syncdate
	DECLARE var_syncdate DATETIME;
	
    -- Declare where variable
	DECLARE var_where1 VARCHAR(250);
