/* Procedure structure for procedure `sp_ws_tablet_check_load` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_check_load` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_check_load`(
    IN var_userid INT,	
	IN var_routeid INT
	)
BEGIN
    DECLARE sts INT DEFAULT 0;
    SELECT STATUS INTO sts FROM controlpanel WHERE controlpanel.flagid=72;   
     IF sts = 0 THEN
   
     SELECT 1 AS cnt ; 
     
     ELSE
      
         
      SELECT COUNT(*) AS cnt FROM startingloaddetail AS sd
		WHERE 1=1 and sd.status = 0 AND sd.routecode = var_routeid AND DATE(sd.ddate)=DATE(CURRENT_DATE()) AND sd.salesmancode = var_userid;
      
     End if ;		
     		
		
     
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_check_newload` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_check_newload` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_check_newload`(
    IN var_routecode INT,	
	IN var_ddate DATE,
	IN var_loadperiodno VARCHAR(250)
	)
BEGIN
    -- DECLARE lpno INT DEFAULT 0;
 DECLARE lpno INT DEFAULT 0;
     UPDATE startingloaddetail SET status = 1 WHERE routecode = var_routecode AND ddate=DATE(var_ddate) AND loadperiodnumber  IN (var_loadperiodno);
         
      SELECT loadperiodnumber INTO lpno FROM startingloaddetail AS sd WHERE routecode = var_routecode AND ddate=DATE(var_ddate) AND status = 0;
			
     	  IF 	lpno = null THEN 
		SELECT 0 as loadperiodno; 
	  ELSE 
		SELECT lpno as loadperiodno;
	  END IF;
		
     
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_deletemaster` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_deletemaster` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_deletemaster`(
IN tblname VARCHAR(255),
IN var_userid INT,
IN var_deviceid VARCHAR(255)
)
BEGIN
DECLARE var_syncdate DATETIME;
    
    SELECT syncdate INTO var_syncdate FROM tbl_syncservice WHERE userid = var_userid AND deviceid = var_deviceid limit 1;
    
    SELECT CODE,tablename,recordid, show_pk(tablename)AS fieldname FROM logmaster WHERE operation_type='delete' AND cdat > var_syncdate AND tablename  IN('customermaster','salesman','routemaster','startingloaddetail','itemgroup','salescalender','promoplandetail','promoplanheader','promokeydetail','promokeyheader','promotionassignmentadvanced','promotioncontrol','bankmaster','productgroupheader','productgroupdetail','companydetail','posmaster','customerposinventory','customerposlimit','posinstructions','nonservreasons','expreasons','expiryreturnreasons','retitmreasons','freegoodreasons','voidreasons','customersurveyplan','customersurveykeyplan','customersurveykey','customersurveydefinition','customersurveydefassign','lookupindexdetail','pricingdetail1','customerpricing1');
    
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_get_supervisor_foc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_get_supervisor_foc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_get_supervisor_foc`(
	IN var_routeid INT
	)
BEGIN
SET @dyn_sql10 = CONCAT("
SELECT  sfb.supervisorcode,sfb.itemcode,sfb.originalqty,sfb.balanceqty,sf.startdate,sf.enddate,rm.routecode,sf.contractid FROM subareamaster sb INNER JOIN supervisor s ON sb.supervisorcode=s.supervisorcode
INNER JOIN routemaster rm ON rm.`subareacode`=sb.subareacode
INNER JOIN supervisor_foc_balance sfb ON sfb.supervisorcode = s.supervisorcode
INNER JOIN supervisor_foc sf ON sf.supervisorcode=sfb.supervisorcode
WHERE rm.routecode='",var_routeid,"' and sfb.balanceqty>0 and sf.enddate>=now()");
	PREPARE s10 FROM @dyn_sql10;
	EXECUTE s10;
    
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_get_warehousestock` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_get_warehousestock` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_get_warehousestock`(
    IN var_userid INT,	
	IN var_routeid INT
	)
BEGIN
SELECT ws.warehousecode,ws.trandate,ws.itemcode,IFNULL(ws.cases,0)AS cases,IFNULL(ws.units,0) AS units,IFNULL(ws.totunits,0) AS totunits,
IFNULL(ws.upc,0) AS upc,IFNULL(ws.caseprice,0) AS caseprice,IFNULL(ws.eachprice,0) AS eachprice,IFNULL(ws.balanceqty,0) AS balanceqty 
   FROM warehousestock ws  
    INNER JOIN depotmaster dm ON dm.depotcode= ws.warehousecode
    INNER JOIN areamaster am ON am.depotcode = dm.depotcode
    INNER JOIN subareamaster sam ON sam.areacode = am.areacode
    INNER  JOIN routemaster rm ON  rm.subareacode= sam.subareacode
    INNER JOIN routeitemgrp rtg ON rtg.routeitemgrpcode=rm.routeitemgrpcode
    INNER JOIN routeitemmapping  rim ON rim.routeitemgrpcode =rtg.routeitemgrpcode 
   AND rim.itemcode=ws.itemcode
    WHERE rm.routecode=var_routeid AND ws.totunits>0;  
    
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_tablet_update_supervisor_foc` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_tablet_update_supervisor_foc` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_tablet_update_supervisor_foc`(
	IN var_itemcode INT,
	IN var_foc INT,
	IN var_sv_code INT
	)
BEGIN
SET @dyn_sql = CONCAT("UPDATE supervisor_foc_balance SET balanceqty=balanceqty-'",var_foc,"' WHERE itemcode='",var_itemcode,"' AND supervisorcode='",var_sv_code,"'");
	PREPARE s FROM @dyn_sql;
	EXECUTE s;
    
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_transactiondata` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_transactiondata` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_transactiondata`(
	IN var_routekey VARCHAR(255)
    )
BEGIN
	
	SELECT 'SEDY' TYPE, COUNT(*) CloudCount FROM startendday WHERE routekey= var_routekey UNION
	SELECT 'IVTH' TYPE, COUNT(*) CloudCount FROM inventorytransactionheader WHERE routekey= var_routekey AND DATA=0 AND voidflag = 0 and manualinvoice=0  UNION  
	/*SELECT 'IVTH' TYPE, 7 CloudCount FROM inventorytransactionheader WHERE routekey= var_routekey AND DATA=0 AND voidflag = 0 UNION */
	SELECT 'IVTD' TYPE, COUNT(*) CloudCount FROM inventorytransactiondetail WHERE routekey= var_routekey UNION
	SELECT 'IVSD' TYPE, count(*) CloudCount FROM inventorysummarydetail WHERE routekey= var_routekey UNION
	SELECT 'RSCS' TYPE, COUNT(*) CloudCount FROM routesequencecustomerstatus WHERE routekey= var_routekey UNION
	SELECT 'CUOC' TYPE, COUNT(*) CloudCount FROM customeroperationscontrol WHERE routekey= var_routekey UNION
	SELECT 'INVH' TYPE, count(*) CloudCount FROM invoiceheader WHERE DATA=0 AND routekey = var_routekey and manualinvoicetype = 0 UNION
	-- SELECT 'INVH' TYPE, 2 CloudCount FROM invoiceheader WHERE DATA=0 AND routekey = var_routekey UNION 
	SELECT 'INVD' TYPE, COUNT(*) CloudCount FROM invoicedetail WHERE routekey= var_routekey union
	-- SELECT 'INVD' TYPE, 31 CloudCount FROM invoicedetail WHERE routekey= var_routekey UNION
	SELECT 'INVR' TYPE, COUNT(*) CloudCount FROM invoicerxddetail WHERE routekey= var_routekey UNION
	SELECT 'BAED' TYPE, COUNT(*) CloudCount FROM batchexpirydetail WHERE routekey= var_routekey UNION
	SELECT 'SAOH' TYPE, COUNT(*) CloudCount FROM salesorderheader WHERE routekey= var_routekey UNION
	SELECT 'SAOD' TYPE, COUNT(*) CloudCount FROM salesorderdetail WHERE routekey= var_routekey UNION
	SELECT 'SAOR' TYPE, COUNT(*) CloudCount FROM orderrxddetail WHERE routekey= var_routekey UNION
	SELECT 'PRMD' TYPE, COUNT(*) CloudCount FROM promotiondetail WHERE routekey= var_routekey UNION
	SELECT 'ARHR' TYPE, COUNT(*) CloudCount FROM arheader WHERE routekey= var_routekey UNION
	/*SELECT 'ARHR' TYPE, 3 CloudCount FROM arheader WHERE routekey= var_routekey UNION*/
	SELECT 'ARDL' TYPE, COUNT(*) CloudCount FROM ardetail WHERE routekey= var_routekey UNION
	
	
	/*sujee commented 05/04/2021 AND ih.immediatepaid>0 minus values */
	SELECT 'CCDS' TYPE ,
	IFNULL(SUM(COALESCE((SELECT COUNT(ih.invoicenumber) cc FROM invoiceheader ih WHERE ih.routekey = ccd.routekey AND IH.VISITKEY = ccd.VISITKEY  AND IFNULL(ih.manualinvoicetype,0) = 0 
	  AND ih.voidflag = 0  ),0)) +
	SUM(COALESCE((SELECT COUNT(ah.invoicenumber) cc FROM arheader ah WHERE ah.routekey = ccd.routekey AND ah.VISITKEY = ccd.VISITKEY AND ah.voidflag = 0),0)),0) CloudCount
	FROM cashcheckdetail ccd WHERE ccd.routekey = var_routekey  UNION  
	
	-- SELECT 'CCDS' TYPE ,	4 CloudCount	FROM cashcheckdetail ccd WHERE ccd.routekey = var_routekey UNION 
	
	SELECT 'CPPD' TYPE, COUNT(*) CloudCount FROM customerpromotionplandetail WHERE routekey= var_routekey UNION
	SELECT 'SADS' TYPE, COUNT(*) CloudCount FROM surveyauditdetail WHERE routekey= var_routekey UNION
	SELECT 'PECD' TYPE, COUNT(*) CloudCount FROM posequipmentchangedetail WHERE routekey= var_routekey UNION
	SELECT 'CUID' TYPE, COUNT(*) CloudCount FROM customerinventorydetail WHERE routekey= var_routekey UNION
	SELECT 'NOSC' TYPE, COUNT(*) CloudCount FROM nonservicedcustomer WHERE routekey= var_routekey UNION
	SELECT 'NOSH' TYPE, COUNT(*) CloudCount FROM nosalesheader WHERE routekey= var_routekey UNION
	SELECT 'AORL' TYPE, COUNT(*) CloudCount FROM t_access_override_log WHERE routekey= var_routekey;
	
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_updatesyncdate` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_updatesyncdate` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_updatesyncdate`(
	in var_userid int,
	in var_deviceid varchar(250),
	IN var_routeid INT
    )
BEGIN
SELECT routecode INTO @route FROM routemaster WHERE salesmancode = var_userid;
INSERT INTO tbl_syncservice(userid,deviceid,syncdate,synctime,routecode)
	VALUES(var_userid, var_deviceid, CURDATE(), CURTIME(), @route);
	
SELECT LAST_INSERT_ID() AS insertrow;
	
END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_update_invoicetransactionkey` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_update_invoicetransactionkey` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_update_invoicetransactionkey`(
		IN var_transactionkey BIGINT(20),
		IN var_routekey BIGINT(20),
		IN var_visitkey BIGINT(20),
		IN var_oldtransactionkey BIGINT(20)
		)
BEGIN
	#invoicedetail
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	#cashcheckdetail
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	#invoicerxddetail
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	#promotiondetail
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	#sigcapturedata
	UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
	#customerinvoice
        UPDATE invoicerxddetail SET transactionkey = var_transactionkey	WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey AND `transactionkey` =var_oldtransactionkey;
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_upload_ar_detl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_upload_ar_detl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_upload_ar_detl`(
					IN var_routekey DECIMAL(28,0),
					IN var_visitkey DECIMAL(28,0),
					IN var_transactionkey DECIMAL(28,0),
					IN var_invoicenumber DECIMAL(18,0),
					IN var_invoicedate DATETIME,
					IN var_totalinvoiceamount DECIMAL(19,4),
					IN var_onacctreasoncode INT(11),
					IN var_amountpaid DECIMAL(19,4),
					IN var_invoicebalance DECIMAL(19,4),
					IN var_arcollectiontype INT(11),
					IN var_chequestatusindicator DECIMAL(18,0),
					IN var_sapchequestatusindicator Varchar(50),
					IN var_currencycode DECIMAL(18,0),
					IN var_pdcbalance DECIMAL(19,4),
					IN var_alternateinvoicenumber VARCHAR(30),
					IN var_salesmancode BIGINT(18)
				)
BEGIN
	DECLARE txnkey BIGINT DEFAULT 0;
	
	SELECT transactionkey INTO txnkey FROM arheader WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey ;
	IF txnkey <> 0 THEN
		
		INSERT INTO ardetail SET 	
			routekey = var_routekey,
			visitkey = var_visitkey,
			transactionkey = txnkey,
			invoicenumber = var_invoicenumber,
			salesmancode=var_salesmancode,
			invoicedate = var_invoicedate,
			totalinvoiceamount = var_totalinvoiceamount,
			onacctreasoncode = var_onacctreasoncode,
			amountpaid = var_amountpaid,
			invoicebalance = var_invoicebalance,
			arcollectiontype = var_arcollectiontype,
			chequestatusindicator = var_chequestatusindicator,
			referenceno = var_sapchequestatusindicator,
			currencycode = get_default_currencycode_routekey(var_routekey),
			pdcbalance = var_pdcbalance,
			alternateinvoicenumber = var_alternateinvoicenumber,
			receivedtime = CURTIME()
			ON DUPLICATE KEY UPDATE transactionkey = txnkey ;						
			
		UPDATE customerinvoice c 
		SET 
		amountpaid = (SELECT SUM(amountpaid) FROM ardetail i WHERE i.invoicenumber = c.invoicenumber ), 
		invoicebalance = (SELECT totalinvoiceamount FROM ardetail i WHERE i.invoicenumber = c.invoicenumber LIMIT 1) - ( SELECT SUM(amountpaid) FROM ardetail i WHERE i.invoicenumber = c.invoicenumber )
		WHERE invoicenumber = var_invoicenumber;
		
	END IF;								
	
 				
	SELECT var_transactionkey AS lastid;	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_upload_inv_detl` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_upload_inv_detl` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_upload_inv_detl`(
	IN var_routekey DECIMAL(28,0),
	IN var_visitkey DECIMAL(28,0),
	IN var_transactionkey BIGINT(20),
	IN var_itemcode DECIMAL(18,0),
	IN var_salesqty DECIMAL(18,0),
	IN var_returnqty DECIMAL(18,0),
	IN var_damagedqty DECIMAL(18,0),
	IN var_freesampleqty DECIMAL(18,0),
	IN var_salesprice DECIMAL(18,6),
	IN var_returnprice DECIMAL(18,6),
	IN var_stdsalesprice DECIMAL(18,6),
	IN var_stdreturnprice DECIMAL(18,6),
	IN var_promoqty DECIMAL(18,0),
	IN var_salesitemexcisetax DECIMAL(19,4),
	IN var_salesitemgsttax DECIMAL(19,4),
	IN var_returnitemexcisetax DECIMAL(19,4),
	IN var_returnitemgsttax DECIMAL(19,4),
	IN var_damageditemexcisetax DECIMAL(19,4),
	IN var_damageditemgsttax DECIMAL(19,4),
	IN var_fgitemexcisetax DECIMAL(19,4),
	IN var_fgitemgsttax DECIMAL(19,4),
	IN var_promoitemexcisetax DECIMAL(19,4),
	IN var_promoitemgsttax DECIMAL(19,4),
	IN var_coopid CHAR(10),
	IN var_batchdetailkey DECIMAL(18,0),
	IN var_salescaseprice DECIMAL(18,6),
	IN var_returncaseprice DECIMAL(18,6),
	IN var_stdsalescaseprice DECIMAL(18,6),
	IN var_stdreturncaseprice DECIMAL(18,6),
	IN var_goodreturnprice DECIMAL(18,6),
	IN var_goodreturncaseprice DECIMAL(18,6),
	IN var_stdgoodreturncaseprice DECIMAL(18,6),
	IN var_stdgoodreturnprice DECIMAL(18,6),
	IN var_expiryqty DECIMAL(18,0),
	IN var_currencycode DECIMAL(18,0),
	IN var_returnfreeqty DECIMAL(18,0),
	IN var_manualfreeqty DECIMAL(18,0),
	IN var_limitedfreeqty DECIMAL(18,0),
	IN var_rebaterentqty DECIMAL(18,0),
	IN var_fixedrentqty DECIMAL(18,0),
	IN var_pricechgindicator DECIMAL(18,0),
	IN var_discountamount DECIMAL(19,4),
	IN var_discountpercentage DECIMAL(18,6),
	IN var_promoamount DECIMAL(19,4),
	IN var_replacementqty DECIMAL(18,0),
	IN var_replacementprice DECIMAL(18,6),
	IN var_replacementcaseprice DECIMAL(18,6),
	IN var_promovalue DECIMAL(19,4),
	IN var_mdat DATETIME,	
	IN var_returnpromovalue DECIMAL(19,4),
	IN var_returnpromoamount DECIMAL(19,4),	
	IN var_roundtotalsalesamount DECIMAL(18,4),
	IN var_diffround DECIMAL(18,4),
	IN var_linetotal DECIMAL(18,4) ,
	IN var_buybackexcisetax DECIMAL(19,4),
	IN var_buybackgsttax DECIMAL(19,4),
	IN var_expiryitemgsttax DECIMAL(19,4),
	IN var_damagepromoamount DECIMAL(19,4)
)
BEGIN   
	DECLARE txnkey bigINT DEFAULT 0;
	
	SELECT transactionkey INTO txnkey FROM invoiceheader WHERE `routekey` = var_routekey AND `visitkey` =var_visitkey ;
	if txnkey <> 0 then
 	
	INSERT INTO invoicedetail SET 
		routekey = var_routekey,
		visitkey = var_visitkey,
		transactionkey = txnkey,
		itemcode = var_itemcode,
		salesqty = var_salesqty,
		returnqty = var_returnqty,
		damagedqty = var_damagedqty,
		freesampleqty = var_freesampleqty,
		salesprice = var_salesprice,
		returnprice = var_returnprice,
		stdsalesprice = var_stdsalesprice,
		stdreturnprice = var_stdreturnprice,
		promoqty = var_promoqty,
		salesitemexcisetax = var_salesitemexcisetax,
		salesitemgsttax = var_salesitemgsttax,
		returnitemexcisetax = var_returnitemexcisetax,
		returnitemgsttax = var_returnitemgsttax,
		damageditemexcisetax = var_damageditemexcisetax,
		damageditemgsttax = var_damageditemgsttax,
		fgitemexcisetax = var_fgitemexcisetax,
		fgitemgsttax = var_fgitemgsttax,
		promoitemexcisetax = var_promoitemexcisetax,
		promoitemgsttax = var_promoitemgsttax,
		coopid = var_coopid,
		batchdetailkey = var_batchdetailkey,
		salescaseprice = var_salescaseprice,
		returncaseprice = var_returncaseprice,
		stdsalescaseprice = var_stdsalescaseprice,
		stdreturncaseprice = var_stdreturncaseprice,
		goodreturnprice = var_goodreturnprice,
		goodreturncaseprice = var_goodreturncaseprice,
		stdgoodreturncaseprice = var_stdgoodreturncaseprice,
		stdgoodreturnprice = var_stdgoodreturnprice,
		expiryqty = var_expiryqty,
		currencycode = get_default_currencycode_routekey(var_routekey),
		returnfreeqty = var_returnfreeqty,
		manualfreeqty = var_manualfreeqty,
		limitedfreeqty = var_limitedfreeqty,
		rebaterentqty = var_rebaterentqty,
		fixedrentqty = var_fixedrentqty,
		pricechgindicator = var_pricechgindicator,
		discountamount = var_discountamount,
		discountpercentage = var_discountpercentage,
		promoamount = var_promoamount,
		replacementqty = var_replacementqty,
		replacementprice = var_replacementprice,
		replacementcaseprice = var_replacementcaseprice,
		promovalue = var_promovalue,
		mdat = var_mdat,		
		returnpromovalue = var_returnpromovalue,
		returnpromoamount = var_returnpromoamount,		
		roundsalesamount=var_roundtotalsalesamount,
		diffround=var_diffround,
		linetotal = var_linetotal,
		receivedtime = CURTIME(),
		buybackexcisetax = var_buybackexcisetax,
		buybackgsttax = var_buybackgsttax,
		expiryitemgsttax= var_expiryitemgsttax,
		damagepromoamount= var_damagepromoamount
		on duplicate key update transactionkey = txnkey ;
		
	end if;
	SELECT var_routekey AS lastid; 
	
	
    END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_upload_order_detail` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_upload_order_detail` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_upload_order_detail`(
	IN var_deliveryno DECIMAL(18,6),
	IN var_itemcode int,
	IN var_qtypcs VARCHAR(20),
	IN var_price VARCHAR(50)
    )
BEGIN
		insert into deliverydetail(deliveryno, itemcode,unitspercase, salesqty, salesprice) 
		values 
			(var_deliveryno, 
			(select actualitemcode from itemmaster where alternatecode = var_itemcode), 
			(select unitspercase from itemmaster i where actualitemcode = var_itemcode ),
			var_qtypcs, var_price )
		;
		
		SELECT deliveryno, itemcode, COUNT(*) sts FROM deliverydetail WHERE deliveryno = var_deliveryno and itemcode = var_itemcode GROUP BY deliveryno;
		
	END */$$
DELIMITER ;

/* Procedure structure for procedure `sp_ws_upload_order_header` */

/*!50003 DROP PROCEDURE IF EXISTS  `sp_ws_upload_order_header` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ws_upload_order_header`(
	IN var_docno DECIMAL(18,6),
	IN var_txndate date,
	IN var_custcode varchar(20),
	IN var_custname varchar(50),
	IN var_custaddr text,
	IN var_contact varchar(20),
	IN var_totalamount DECIMAL(18,6)
    )
BEGIN
		DECLARE cnt int default 0;
		declare custcode bigint default 0;
		select count(*) into cnt from customermaster where alternatecode = var_custcode;
		
		if cnt = 0 then 
			insert into customermaster(alternatecode, customername, 
			customeraddress1,contactpersonmobilenumber , 
			activecustomer , type, enableadvancepayment, routecode, invoicepriceprint
			)
			values(
				var_custcode,var_custname, var_custaddr,var_contact,1,1,1, 111,1
			);
		end if;
		
		select customercode into custcode from customermaster WHERE alternatecode = var_custcode;
		
		if custcode > 0 then 
			insert into deliveryheader(orderno,customercode,deliveryroute,drivercode, deliverydate, totalamount,invoiced,ponumber, upddate ) 
			values (
				var_docno, 
				custcode,
				(select routecode from customermaster where customercode = custcode ),
				(SELECT routecode FROM customermaster WHERE customercode = custcode ),
				var_txndate, 
				var_totalamount, 
				0,
				0, 
				now()
			) on duplicate key update orderno = var_docno;		
		
		end if;
		
		select orderno, deliveryno,cnt, count(*) sts from deliveryheader where orderno = var_docno group by orderno;
		
	END */$$
DELIMITER ;

/* Procedure structure for procedure `tts_taac_login` */

/*!50003 DROP PROCEDURE IF EXISTS  `tts_taac_login` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `tts_taac_login`(
	var_username VARCHAR(255),
	var_userpassword  VARCHAR(255),
	var_deviceid  VARCHAR(255))
begin
		DECLARE cnt INT DEFAULT 0;	
	SELECT COUNT(*) INTO cnt FROM taac_login AS sm WHERE sm.username = var_username AND sm.password = var_userpassword;
		
	if cnt = 1 then
		select 0 as STATUS, empname from taac_login AS sm WHERE sm.username = var_username AND sm.password = var_userpassword;	
		
	else 
		SELECT 1 AS STATUS;
	END IF;	
END */$$
DELIMITER ;

/* Procedure structure for procedure `update_data_posting` */

/*!50003 DROP PROCEDURE IF EXISTS  `update_data_posting` */;

DELIMITER $$

/*!50003 CREATE DEFINER=`root`@`localhost` PROCEDURE `update_data_posting`(
        IN var_routecode BIGINT(20)
    )
BEGIN
	SELECT COALESCE(MAX(routekey),0), salesmancode INTO @routekey, @salesman FROM startendday WHERE routecode = var_routecode;
	
	IF @routekey > 0 THEN
		
		DELETE ird
		FROM invoicerxddetail ird 
		LEFT JOIN invoicedetail id ON id.transactionkey = ird.transactionkey AND id.itemcode = ird.itemcode AND ird.itemtransactiontype = 3
		WHERE  id.manualfreeqty = 0 AND id.routekey = @routekey;				
		
		UPDATE customeroperationscontrol coc, invoiceheader ih
		SET coc.customercode = ih.customercode
		WHERE coc.routekey = ih.routekey AND coc.visitkey = ih.visitkey AND coc.customercode <> ih.customercode AND
			coc.routekey = @routekey;		
		
		UPDATE customeroperationscontrol coc, arheader ih
		SET coc.customercode = ih.customercode
		WHERE coc.routekey = ih.routekey AND coc.visitkey = ih.visitkey AND coc.customercode <> ih.customercode AND
			coc.routekey = @routekey;
	END IF;
	
	-- CALL sp_check_returns (@routekey);
	
	-- CALL post_salestrend_routebook (var_routecode);
		
	-- CALL post_salesachievement(@salesman);
				
    END */$$
DELIMITER ;

