/*!50001 CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `rvupload` AS select '' AS `SEQNO`,'' AS `line_item`,'2000' AS `COMP_CODE`,date_format(`ah`.`transactiondate`,'%d.%m.%Y') AS `DOC_DATE`,date_format(`ah`.`transactiondate`,'%d.%m.%Y') AS `Posting Date`,'DZ' AS `DOC_TYPE`,concat('RECTV',cast(`ah`.`invoicenumber` as char charset utf8mb3)) AS `RECEIPT_NUMBER`,'' AS `HEADER_TXT`,cast(`ad`.`alternateinvoicenumber` as char charset utf8mb3) AS `ALLOC_NMBR`,' ' AS `GL_ACCOUNT`,date_format(`ah`.`transactiondate`,'%d.%m.%Y') AS `Value Date`,'' AS `TAX_CODE`,'' AS `COST_CENTER`,`cm`.`alternatecode` AS `ITEM_TEXT`,`pc`.`PROFITCENTRE` AS `PROFIT_CTR`,`cm`.`hhccustomernameshort` AS `CUSTOMER`,'' AS `SP_GL_IND`,'OMR' AS `CURR`,'' AS `AMOUNT_DEBIT`,`ad`.`amountpaid` AS `AMOUNT_CR`,'' AS `INV_DOC_NO`,'' AS `GJAHR`,'' AS `line_item_no`,'' AS `line_item_no1` from ((((((`arheader` `ah` join `ardetail` `ad` on((`ah`.`transactionkey` = `ad`.`transactionkey`))) join `customermaster` `cm` on((`cm`.`customercode` = `ah`.`customercode`))) join `routemaster` `rm` on((`rm`.`routecode` = `ah`.`routecode`))) join `routedetail` `brd` on(((`rm`.`routecode` = `brd`.`RouteCode`) and (`brd`.`RouteCode` = `ah`.`routecode`)))) join `cashcheckdetail` `ccd` on((`ccd`.`routekey` = `ah`.`routekey`))) join `owcpcgl` `pc` on(((`pc`.`LOCATION` = convert(`brd`.`WAREHOUSE` using utf8mb4)) and (`ccd`.`visitkey` = `ah`.`visitkey`) and (`ccd`.`hhctransactionkey` = `ah`.`hhctransactionkey`) and (`ccd`.`routekey` = `ah`.`routekey`)))) where (`ah`.`transactiondate` >= '2023-06-01') union select '' AS `SEQNO`,'' AS `line_item`,'2000' AS `COMP_CODE`,date_format(`bah`.`transactiondate`,'%d.%m.%Y') AS `DOC_DATE`,date_format(`bah`.`transactiondate`,'%d.%m.%Y') AS `Posting Date`,'DZ' AS `DOC_TYPE`,concat('RECTV',cast(`bah`.`invoicenumber` as char charset utf8mb3)) AS `RECEIPT_NUMBER`,'' AS `HEADER_TXT`,'' AS `ALLOC_NMBR`,`bpc`.`GL_NO` AS `GL_ACCOUNT`,date_format(`bah`.`transactiondate`,'%d.%m.%Y') AS `Value Date`,'' AS `TAX_CODE`,'' AS `COST_CENTER`,'' AS `ITEM_TEXT`,`bpc`.`PROFITCENTRE` AS `PROFIT_CTR`,'' AS `CUSTOMER`,'' AS `SP_GL_IND`,'OMR' AS `CURR`,sum(`bad`.`amountpaid`) AS `AMOUNT_DEBIT`,'' AS `AMOUNT_CR`,'' AS `INV_DOC_NO`,'' AS `GJAHR`,'' AS `line_item_no`,'' AS `line_item_no1` from ((((((`arheader` `bah` join `ardetail` `bad` on((`bah`.`transactionkey` = `bad`.`transactionkey`))) join `customermaster` `bcm` on((`bcm`.`customercode` = `bah`.`customercode`))) join `routemaster` `brm` on((`brm`.`routecode` = `bah`.`routecode`))) join `routedetail` `brd` on(((`brm`.`routecode` = `brd`.`RouteCode`) and (`brd`.`RouteCode` = `bah`.`routecode`)))) join `cashcheckdetail` `bccd` on((`bccd`.`routekey` = `bah`.`routekey`))) join `owcpcgl` `bpc` on(((`bpc`.`LOCATION` = convert(`brd`.`WAREHOUSE` using utf8mb4)) and (`bccd`.`visitkey` = `bah`.`visitkey`) and (`bccd`.`hhctransactionkey` = `bah`.`hhctransactionkey`) and (`bccd`.`routekey` = `bah`.`routekey`)))) where (`bah`.`transactiondate` >= '2023-06-01') group by `bah`.`invoicenumber`,`bah`.`transactiondate`,`brm`.`routename`,`brd`.`WAREHOUSE`,`bpc`.`GL_NO`,`bpc`.`PROFITCENTRE` */;

/*View structure for view sb_sales_dump */

/*!50001 DROP TABLE IF EXISTS `sb_sales_dump` */;
